-- ============================================================
-- 圣经全文（新改訳2017）· 数据文件 3/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '历代志上', 13, 4, 15, 'エフンネの子カレブの子は、イル、エラ、ナアム。エラの子はケナズ。'),
('JPN', '历代志上', 13, 4, 16, 'エハレルエルの子は、ジフ、ジファ、ティルヤ、アサルエル。'),
('JPN', '历代志上', 13, 4, 17, 'エズラの子は、エテル、メレデ、エフェル、ヤロン。メレデの妻は身ごもって、ミリアムとシャンマイとエシュテモアの父イシュバフを産んだ。'),
('JPN', '历代志上', 13, 4, 18, '──メレデのユダ人の妻は、ゲドルの父ヤレデ、ソコの父ヘベル、ザノアハの父エクティエルを産んだ──これらはメレデが妻としたファラオの娘ビテヤの子であった。'),
('JPN', '历代志上', 13, 4, 19, 'ナハムの姉妹、ホディヤの妻の子は、ガルミ人ケイラの父とマアカ人エシュテモア。'),
('JPN', '历代志上', 13, 4, 20, 'シモンの子は、アムノン、リンナ、ベン・ハナン、ティロン。イシュイの子は、ゾヘテ、ベン・ゾヘテ。'),
('JPN', '历代志上', 13, 4, 21, 'ユダの子シェラの子孫は、レカの父エル、マレシャの父ラアダ、ベテ・アシュベアで亜麻布業を営む家の氏族、'),
('JPN', '历代志上', 13, 4, 22, 'モアブとヤシュビ・ラヘムを治めたヨキム、コゼバの人々、ヨアシュ、サラフ。この記録は古い。'),
('JPN', '历代志上', 13, 4, 23, '彼らは陶器師で、ネタイムとゲデラの住民であり、王の仕事をするため、王とともにそこに住んだ。'),
('JPN', '历代志上', 13, 4, 24, 'シメオンの子は、ネムエル、ヤミン、ヤリブ、ゼラフ、シャウル。'),
('JPN', '历代志上', 13, 4, 25, 'シャウルの子はシャルム、その子はミブサム、その子はミシュマ。'),
('JPN', '历代志上', 13, 4, 26, 'ミシュマの子孫は、その子ハムエル、その子はザクル、その子はシムイ。'),
('JPN', '历代志上', 13, 4, 27, 'シムイには十六人の息子と、六人の娘がいたが、彼の兄弟たちの子は多くなかった。彼らの全氏族は、ユダの子らほどには多くならなかった。'),
('JPN', '历代志上', 13, 4, 28, '彼らが住んだのは、ベエル・シェバ、モラダ、ハツァル・シュアル、'),
('JPN', '历代志上', 13, 4, 29, 'ビルハ、エツェム、トラデ、'),
('JPN', '历代志上', 13, 4, 30, 'ベトエル、ホルマ、ツィクラグ、'),
('JPN', '历代志上', 13, 4, 31, 'ベテ・マルカボテ、ハツァル・スシム、ベテ・ビルイ、シャアライムである。これらはダビデの治世に至るまで、彼らの町々であった。'),
('JPN', '历代志上', 13, 4, 32, 'また、彼らの村々は、エタム、アイン、リンモン、トケン、アシャンの五つの町であり、'),
('JPN', '历代志上', 13, 4, 33, 'これらの町々の周りにあって、バアルにまで及ぶすべての村。これが彼らの居住地であり、彼らは系図に記載されていた。'),
('JPN', '历代志上', 13, 4, 34, 'メショバブ、ヤムレク、アマツヤの子ヨシャ、'),
('JPN', '历代志上', 13, 4, 35, 'ヨエル、アシエルの子セラヤの子ヨシブヤの子エフー、'),
('JPN', '历代志上', 13, 4, 36, 'エルヨエナイ、ヤアコバ、エショハヤ、アサヤ、アディエル、エシミエル、ベナヤ、'),
('JPN', '历代志上', 13, 4, 37, 'シフイの子ジザ。シフイはアロンの子、アロンはエダヤの子、エダヤはシムリの子、シムリはシェマヤの子。'),
('JPN', '历代志上', 13, 4, 38, 'ここに名前の出てくるこれらの人たちは、彼らの諸氏族の長であった。彼らの一族は大いに増えた。'),
('JPN', '历代志上', 13, 4, 39, '彼らは、その群れのために牧場を探し求めて、ゲドルの入り口、谷の東方まで行って、'),
('JPN', '历代志上', 13, 4, 40, '豊かな良い牧場を見つけた。その土地は広々としていて、静かで安らかだった。以前そこには、ハム系の人々が住んでいた。'),
('JPN', '历代志上', 13, 4, 41, 'ユダの王ヒゼキヤの時代に、ここに名を記された人々が来て、彼らの天幕と、そこにいたメウニム人を討ち、彼らを聖絶した。今日もそのままである。彼らはこの人々に代わってそこに住んだ。そこには、彼らの群れのために牧場があったからである。'),
('JPN', '历代志上', 13, 4, 42, 'また、彼らシメオン族のうち、五百人の人々が、イシュイの子ペラテヤ、ネアルヤ、レファヤ、ウジエルをかしらとしてセイル山に行った。'),
('JPN', '历代志上', 13, 4, 43, '彼らは、アマレクの逃れて残っていた者を討ち、そこに住んだ。今日もそのままである。'),
('JPN', '历代志上', 13, 5, 1, 'イスラエルの長子ルベンの子孫。ルベンは長子であったが、父の寝床を汚したことにより、その長子の権利はイスラエルの子ヨセフの子に与えられた。それで、彼は系図には長子の権利を持つ者として記載されていない。'),
('JPN', '历代志上', 13, 5, 2, 'ユダは彼の兄弟たちの間で勢いを増し、君たる者もそこから出たが、長子の権利はヨセフのものとなった。'),
('JPN', '历代志上', 13, 5, 3, 'イスラエルの長子ルベンの子は、ハノク、パル、ヘツロン、カルミ。'),
('JPN', '历代志上', 13, 5, 4, 'ヨエルの子は、その子シェマヤ、その子ゴグ、その子シムイ、'),
('JPN', '历代志上', 13, 5, 5, 'その子ミカ、その子レアヤ、その子バアル、'),
('JPN', '历代志上', 13, 5, 6, 'その子はアッシリアの王ティグラト・ピレセルが引いて行ったベエラ。彼はルベン人の族長であった。'),
('JPN', '历代志上', 13, 5, 7, 'また、彼の兄弟たちで、氏族ごとに、生まれた順に系図に載せられた者のかしらはエイエル、次はゼカリヤ、'),
('JPN', '历代志上', 13, 5, 8, 'そしてベラ。彼はヨエルの子シェマの子アザズの子で、アロエルに住み、ネボやバアル・メオンにまで及び、'),
('JPN', '历代志上', 13, 5, 9, '東はあの大河ユーフラテスから荒野の入り口に及ぶ地に住んだ。ギルアデの地で彼らの家畜が増えたからである。'),
('JPN', '历代志上', 13, 5, 10, '彼らはサウルの時代にハガル人と戦いを交え、ハガル人は彼らの手によって倒れた。そこで彼らは、ギルアデの東方一帯に天幕を張って住んだ。'),
('JPN', '历代志上', 13, 5, 11, 'ガドの子孫は、彼らの真向かいに当たるバシャンの地に住み、サルカにまで及んだ。'),
('JPN', '历代志上', 13, 5, 12, 'かしらのヨエル、二番目のシャファム、そしてヤナイ、シャファテがバシャンに住んだ。'),
('JPN', '历代志上', 13, 5, 13, 'その一族に属する兄弟たちは、ミカエル、メシュラム、シェバ、ヨライ、ヤアカン、ジア、エベルの七人。'),
('JPN', '历代志上', 13, 5, 14, 'これらはアビハイルの子であった。アビハイルはフリの子、フリはヤロアハの子、ヤロアハはギルアデの子、ギルアデはミカエルの子、ミカエルはエシシャイの子、エシシャイはヤフドの子、ヤフドはブズの子である。'),
('JPN', '历代志上', 13, 5, 15, 'グニの子アブディエルの子アヒ。彼はその一族のかしらであった。'),
('JPN', '历代志上', 13, 5, 16, '彼らは、ギルアデとバシャンとそれに属する村々、およびシャロンの放牧地全域の境に至るまで住んだ。'),
('JPN', '历代志上', 13, 5, 17, '彼らはみな、ユダの王ヨタムの時代、イスラエルの王ヤロブアムの時代に系図に記載された。'),
('JPN', '历代志上', 13, 5, 18, 'ルベンの子孫、ガド人、マナセの半部族で、盾と剣を取り、弓を引き、戦いの訓練を受けた勇者たちのうち、従軍する者は四万四千七百六十人であった。'),
('JPN', '历代志上', 13, 5, 19, '彼らはハガル人、およびエトル、ナフィシュ、ノダブと戦いを交えたが、'),
('JPN', '历代志上', 13, 5, 20, '助けを得てこれらに当たったので、ハガル人およびこれとともにいた者はみな彼らの手に渡された。それは、彼らがその戦いのときに神に叫び求めたからである。彼らが神に拠り頼んだので、神は彼らの願いを聞き入れられた。'),
('JPN', '历代志上', 13, 5, 21, '彼らはこの人々の家畜、らくだ五万頭、羊二十五万匹、ろば二千頭、また十万人の人を奪い去った。'),
('JPN', '历代志上', 13, 5, 22, 'この戦いは神から出ていたため、多くの者が刺されて倒れたからである。彼らはこの人々に代わって捕囚の時までそこに住んだ。'),
('JPN', '历代志上', 13, 5, 23, 'マナセの半部族の人々は、バシャンからバアル・ヘルモン、セニル、ヘルモン山に至る地に住み、その数は多かった。'),
('JPN', '历代志上', 13, 5, 24, '彼らの一族のかしらたちは次のとおり。エフェル、イシュイ、エリエル、アズリエル、エレミヤ、ホダウヤ、ヤフディエル。この人たちは勇士で、名のある人たちであり、その一族のかしらであった。'),
('JPN', '历代志上', 13, 5, 25, 'ところが、彼らはその父祖の神の信頼を裏切り、神が彼らの前から根絶やしにされたその地の民の神々を慕って淫行をした。'),
('JPN', '历代志上', 13, 5, 26, 'そこで、イスラエルの神は、アッシリアの王プルの霊、すなわちアッシリアの王ティグラト・ピレセルの霊を奮い立たせられた。それで彼は、ルベン人とガド人、およびマナセの半部族を捕らえ移し、彼らをハラフ、ハボル、ハラ、ゴザンの川に連れて行った。今日もそのままである。'),
('JPN', '历代志上', 13, 6, 1, 'レビの子は、ゲルション、ケハテ、メラリ。'),
('JPN', '历代志上', 13, 6, 2, 'ケハテの子は、アムラム、イツハル、ヘブロン、ウジエル。'),
('JPN', '历代志上', 13, 6, 3, 'アムラムの子は、アロン、モーセ、ミリアム。アロンの子は、ナダブ、アビフ、エルアザル、イタマル。'),
('JPN', '历代志上', 13, 6, 4, 'エルアザルはピネハスを生み、ピネハスはアビシュアを生み、'),
('JPN', '历代志上', 13, 6, 5, 'アビシュアはブキを生み、ブキはウジを生み、'),
('JPN', '历代志上', 13, 6, 6, 'ウジはゼラフヤを生み、ゼラフヤはメラヨテを生み、'),
('JPN', '历代志上', 13, 6, 7, 'メラヨテはアマルヤを生み、アマルヤはアヒトブを生み、'),
('JPN', '历代志上', 13, 6, 8, 'アヒトブはツァドクを生み、ツァドクはアヒマアツを生み、'),
('JPN', '历代志上', 13, 6, 9, 'アヒマアツはアザルヤを生み、アザルヤはヨハナンを生み、'),
('JPN', '历代志上', 13, 6, 10, 'ヨハナンはアザルヤを生んだ。これは、ソロモンがエルサレムに建てた宮で、祭司の務めを果たしたアザルヤである。'),
('JPN', '历代志上', 13, 6, 11, 'アザルヤはアマルヤを生み、アマルヤはアヒトブを生み、'),
('JPN', '历代志上', 13, 6, 12, 'アヒトブはツァドクを生み、ツァドクはシャルムを生み、'),
('JPN', '历代志上', 13, 6, 13, 'シャルムはヒルキヤを生み、ヒルキヤはアザルヤを生み、'),
('JPN', '历代志上', 13, 6, 14, 'アザルヤはセラヤを生み、セラヤはエホツァダクを生んだ。'),
('JPN', '历代志上', 13, 6, 15, 'エホツァダクは、主がネブカドネツァルの手によってユダとエルサレムを捕囚にしたとき、そこを去った。'),
('JPN', '历代志上', 13, 6, 16, 'レビ族は、ゲルショム、ケハテ、メラリ。'),
('JPN', '历代志上', 13, 6, 17, 'ゲルショム族の名は次のとおり。リブニ、シムイ。'),
('JPN', '历代志上', 13, 6, 18, 'ケハテ族は、アムラム、イツハル、ヘブロン、ウジエル。'),
('JPN', '历代志上', 13, 6, 19, 'メラリ族は、マフリ、ムシ。これが一族ごとのレビ人の諸氏族である。'),
('JPN', '历代志上', 13, 6, 20, 'ゲルショムに属する者は、その子リブニ、その子ヤハテ、その子ジンマ、'),
('JPN', '历代志上', 13, 6, 21, 'その子ヨアフ、その子イド、その子ゼラフ、その子エオテライ。'),
('JPN', '历代志上', 13, 6, 22, 'ケハテ族は、その子アミナダブ、その子コラ、その子アシル、'),
('JPN', '历代志上', 13, 6, 23, 'その子エルカナ、その子エブヤサフ、その子アシル、'),
('JPN', '历代志上', 13, 6, 24, 'その子タハテ、その子ウリエル、その子ウジヤ、その子シャウル。'),
('JPN', '历代志上', 13, 6, 25, 'エルカナの子は、アマサイ、アヒモテ。'),
('JPN', '历代志上', 13, 6, 26, 'エルカナについては、エルカナの子は、その子ツォファイ、その子ナハテ、'),
('JPN', '历代志上', 13, 6, 27, 'その子エリアブ、その子エロハム、その子エルカナ。'),
('JPN', '历代志上', 13, 6, 28, 'サムエルの子は、長子ヨエル、次男アビヤ。'),
('JPN', '历代志上', 13, 6, 29, 'メラリの子は、マフリ、その子リブニ、その子シムイ、その子ウザ、'),
('JPN', '历代志上', 13, 6, 30, 'その子シムア、その子ハギヤ、その子アサヤ。'),
('JPN', '历代志上', 13, 6, 31, '契約の箱が安置所に納められた後、ダビデが主の宮の歌を受け持たせるために立てた人たちは、次のとおりである。'),
('JPN', '历代志上', 13, 6, 32, 'ソロモンがエルサレムに主の宮を建てるまでは、この者たちが会見の天幕である幕屋の前で、歌をもって仕え、それぞれ定めにしたがって奉仕を受け持った。'),
('JPN', '历代志上', 13, 6, 33, '奉仕をした者たちとその一族は次のとおりである。ケハテ族からはヨエルの子、歌い手ヘマン。ヨエルはサムエルの子、'),
('JPN', '历代志上', 13, 6, 34, 'サムエルはエルカナの子、エルカナはエロハムの子、エロハムはエリエルの子、エリエルはトアハの子、'),
('JPN', '历代志上', 13, 6, 35, 'トアハはツフの子、ツフはエルカナの子、エルカナはマハテの子、マハテはアマサイの子、'),
('JPN', '历代志上', 13, 6, 36, 'アマサイはエルカナの子、エルカナはヨエルの子、ヨエルはアザルヤの子、アザルヤはゼパニヤの子、'),
('JPN', '历代志上', 13, 6, 37, 'ゼパニヤはタハテの子、タハテはアシルの子、アシルはエブヤサフの子、エブヤサフはコラの子、'),
('JPN', '历代志上', 13, 6, 38, 'コラはイツハルの子、イツハルはケハテの子、ケハテはレビの子、レビはイスラエルの子である。'),
('JPN', '历代志上', 13, 6, 39, 'ヘマンの兄弟アサフは、彼の右側に立って仕えた。アサフはベレクヤの子、ベレクヤはシムアの子、'),
('JPN', '历代志上', 13, 6, 40, 'シムアはミカエルの子、ミカエルはバアセヤの子、バアセヤはマルキヤの子、'),
('JPN', '历代志上', 13, 6, 41, 'マルキヤはエテニの子、エテニはゼラフの子、ゼラフはアダヤの子、'),
('JPN', '历代志上', 13, 6, 42, 'アダヤはエタンの子、エタンはジンマの子、ジンマはシムイの子、'),
('JPN', '历代志上', 13, 6, 43, 'シムイはヤハテの子、ヤハテはゲルショムの子、ゲルショムはレビの子である。'),
('JPN', '历代志上', 13, 6, 44, '左側には、彼らの同胞メラリ族の、キシの子エタンがいた。キシはアブディの子、アブディはマルクの子、'),
('JPN', '历代志上', 13, 6, 45, 'マルクはハシャブヤの子、ハシャブヤはアマツヤの子、アマツヤはヒルキヤの子、'),
('JPN', '历代志上', 13, 6, 46, 'ヒルキヤはアムツィの子、アムツィはバニの子、バニはシェメルの子、'),
('JPN', '历代志上', 13, 6, 47, 'シェメルはマフリの子、マフリはムシの子、ムシはメラリの子、メラリはレビの子である。'),
('JPN', '历代志上', 13, 6, 48, '彼らの同胞のレビ人には、神の宮である幕屋のあらゆる奉仕が与えられた。'),
('JPN', '历代志上', 13, 6, 49, 'アロンとその子らは、全焼のささげ物の祭壇と香の祭壇の上に煙を立ち上らせて、至聖所のすべての務めに当たり、イスラエルのために宥めを行った。すべて、神のしもべモーセが命じたとおりである。'),
('JPN', '历代志上', 13, 6, 50, 'アロンの子孫は次のとおりである。その子エルアザル、その子ピネハス、その子アビシュア、'),
('JPN', '历代志上', 13, 6, 51, 'その子ブキ、その子ウジ、その子ゼラフヤ、'),
('JPN', '历代志上', 13, 6, 52, 'その子メラヨテ、その子アマルヤ、その子アヒトブ、'),
('JPN', '历代志上', 13, 6, 53, 'その子ツァドク、その子アヒマアツ。'),
('JPN', '历代志上', 13, 6, 54, '彼らの居住地は、地域内の宿営ごとに言えば次のとおりである。ケハテ人の氏族に属するアロンの子らについては、彼らがくじに当たったので、'),
('JPN', '历代志上', 13, 6, 55, '彼らには、ユダの地にあるヘブロンと、その周りの放牧地が与えられた。'),
('JPN', '历代志上', 13, 6, 56, 'ただし、この町の畑とその村々は、エフンネの子カレブに与えられた。'),
('JPN', '历代志上', 13, 6, 57, 'アロンの子らには、逃れの町であるヘブロン、リブナとその放牧地、ヤティル、エシュテモアとその放牧地、'),
('JPN', '历代志上', 13, 6, 58, 'ヒレズとその放牧地、デビルとその放牧地、'),
('JPN', '历代志上', 13, 6, 59, 'アシャンとその放牧地、ベテ・シェメシュとその放牧地、'),
('JPN', '历代志上', 13, 6, 60, 'またベニヤミン部族から、ゲバとその放牧地、アレメテとその放牧地、アナトテとその放牧地が与えられた。彼らの町は全部で十三あり、各氏族の町になった。'),
('JPN', '历代志上', 13, 6, 61, '残りのケハテ族には、あの半部族、すなわちマナセの半部族に属する氏族から、くじによって十の町が与えられた。'),
('JPN', '历代志上', 13, 6, 62, 'ゲルショム族の諸氏族には、イッサカル部族、アシェル部族、ナフタリ部族、バシャンのマナセ部族から十三の町が与えられた。'),
('JPN', '历代志上', 13, 6, 63, 'メラリ人の諸氏族には、ルベン部族、ガド部族、ゼブルン部族から、くじによって十二の町が与えられた。'),
('JPN', '历代志上', 13, 6, 64, 'イスラエルの子らは、レビ人にこれらの町とその放牧地を与えるとき、'),
('JPN', '历代志上', 13, 6, 65, 'ユダ部族、シメオン部族、ベニヤミン部族から、これらの町々をくじによって与えた。彼らはその町々の名を読み上げた。'),
('JPN', '历代志上', 13, 6, 66, 'ケハテ人諸氏族のうちの一部には、エフライム部族からその地域の町々が与えられた。'),
('JPN', '历代志上', 13, 6, 67, '彼らには、エフライムの山地にある逃れの町シェケムとその放牧地、ゲゼルとその放牧地、'),
('JPN', '历代志上', 13, 6, 68, 'ヨクメアムとその放牧地、ベテ・ホロンとその放牧地、'),
('JPN', '历代志上', 13, 6, 69, 'アヤロンとその放牧地、ガテ・リンモンとその放牧地が与えられた。'),
('JPN', '历代志上', 13, 6, 70, '残りのケハテ族の氏族には、マナセの半部族から、アネルとその放牧地、バラムとその放牧地が与えられた。'),
('JPN', '历代志上', 13, 6, 71, 'ゲルショム族には、マナセの半部族に属する氏族から、バシャンのゴランとその放牧地、アシュタロテとその放牧地、'),
('JPN', '历代志上', 13, 6, 72, 'イッサカル部族から、ケデシュとその放牧地、ダベラテとその放牧地、'),
('JPN', '历代志上', 13, 6, 73, 'ラモテとその放牧地、アネムとその放牧地、'),
('JPN', '历代志上', 13, 6, 74, 'アシェル部族から、マシャルとその放牧地、アブドンとその放牧地、'),
('JPN', '历代志上', 13, 6, 75, 'フコクとその放牧地、レホブとその放牧地、'),
('JPN', '历代志上', 13, 6, 76, 'ナフタリ部族から、ガリラヤのケデシュとその放牧地、ハモンとその放牧地、キルヤタイムとその放牧地が与えられた。'),
('JPN', '历代志上', 13, 6, 77, '残りのメラリ族には、ゼブルン部族から、リンモノとその放牧地、タボルとその放牧地、'),
('JPN', '历代志上', 13, 6, 78, 'エリコからヨルダン川を渡った地方、すなわち、ヨルダン川の東では、ルベン部族から、荒野にあるベツェルとその放牧地、ヤハツとその放牧地、'),
('JPN', '历代志上', 13, 6, 79, 'ケデモテとその放牧地、メファアテとその放牧地、'),
('JPN', '历代志上', 13, 6, 80, 'ガド部族から、ギルアデのラモテとその放牧地、マハナイムとその放牧地、'),
('JPN', '历代志上', 13, 6, 81, 'ヘシュボンとその放牧地、ヤゼルとその放牧地が与えられた。'),
('JPN', '历代志上', 13, 7, 1, 'イッサカル族の者は、トラ、プア、ヤシュブ、シムロンの四人。'),
('JPN', '历代志上', 13, 7, 2, 'トラの子は、ウジ、レファヤ、エリエル、ヤフマイ、イブサム、シェムエル。これらは彼らの父トラ一族のかしらたちで、その家系の勇士たちであった。その数はダビデの時代には二万二千六百人であった。'),
('JPN', '历代志上', 13, 7, 3, 'ウジの子は、イズラフヤ。イズラフヤの子は、ミカエル、オバデヤ、ヨエル、イシヤ。彼ら五人はすべてかしらであった。'),
('JPN', '历代志上', 13, 7, 4, 'この人々に加えて、彼ら一族の家系によると、戦いに備えた部隊は三万六千人であった。彼らが多くの妻子を得たからである。'),
('JPN', '历代志上', 13, 7, 5, 'イッサカル全氏族の同胞で、系図に記載された勇士は全部で八万七千人であった。'),
('JPN', '历代志上', 13, 7, 6, 'ベニヤミンの子はベラ、ベケル、エディアエルの三人。'),
('JPN', '历代志上', 13, 7, 7, 'ベラの子はエツボン、ウジ、ウジエル、エリモテ、イリの五人。彼らは一族のかしらであり、勇士であった。系図に記載された者は二万二千三十四人であった。'),
('JPN', '历代志上', 13, 7, 8, 'ベケルの子はゼミラ、ヨアシュ、エリエゼル、エルヨエナイ、オムリ、エレモテ、アビヤ、アナトテ、アレメテ。これらはみな、ベケルの子であった。'),
('JPN', '历代志上', 13, 7, 9, 'その子孫のうち、彼らの系図に記載された一族のかしらで勇士である者の数は、二万二百人であった。'),
('JPN', '历代志上', 13, 7, 10, 'エディアエルの子はビルハン。ビルハンの子はエウシュ、ベニヤミン、エフデ、ケナアナ、ゼタン、タルシシュ、アヒシャハル。'),
('JPN', '历代志上', 13, 7, 11, 'これらはみな、エディアエルの子であった。彼らは一族のかしらで勇士であり、一万七千二百人が従軍して戦いに出る者であった。'),
('JPN', '历代志上', 13, 7, 12, 'シュピムとフピムはイルの子であり、フシムはアヘルの子であった。'),
('JPN', '历代志上', 13, 7, 13, 'ナフタリの子はヤハツィエル、グニ、エツェル、シャルム。これらはビルハの子であった。'),
('JPN', '历代志上', 13, 7, 14, 'マナセの子は、彼のアラム人の側女が産んだアスリエル。彼女はギルアデの父マキルを産んだ。'),
('JPN', '历代志上', 13, 7, 15, 'マキルはフピムとシュピムのために妻を迎えた。彼の妹の名はマアカといった。次男の名はツェロフハデ。ツェロフハデには娘たちがあった。'),
('JPN', '历代志上', 13, 7, 16, 'マキルの妻マアカは男の子を産み、その名をペレシュと呼んだ。その弟の名はシェレシュであり、その子はウラムとレケムであった。'),
('JPN', '历代志上', 13, 7, 17, 'ウラムの子はベダン。これらがマナセの子マキルの子であるギルアデの子であった。'),
('JPN', '历代志上', 13, 7, 18, 'また彼の妹モレケテが産んだのは、イシュホデ、アビエゼル、マフラ。'),
('JPN', '历代志上', 13, 7, 19, 'シェミダの子は、アフヤン、シェケム、リクヒ、アニアム。'),
('JPN', '历代志上', 13, 7, 20, 'エフライムの子はシュテラフ。その子はベレデ、その子はタハテ、その子はエルアダ、その子はタハテ、'),
('JPN', '历代志上', 13, 7, 21, 'その子はザバデ、その子はシュテラフ。そして、エゼルとエルアデ。二人はこの地の生まれであるガテの人々に殺された。下って行って家畜を奪おうとしたからである。'),
('JPN', '历代志上', 13, 7, 22, '彼らの父エフライムは、何日もの間喪に服したので、彼の兄弟たちが来て彼を慰めた。'),
('JPN', '历代志上', 13, 7, 23, 'それからエフライムは妻のところに入った。彼女は身ごもって男の子を産んだ。彼はその子をベリアと名づけた。その家がわざわいの渦中にあったからである。'),
('JPN', '历代志上', 13, 7, 24, 'エフライムの娘はシェエラであった。彼女は上および下ベテ・ホロン、そしてウゼン・シェエラを建てた。'),
('JPN', '历代志上', 13, 7, 25, '彼の子はレファフ。その子はレシェフ、その子はテラフ、その子はタハン、'),
('JPN', '历代志上', 13, 7, 26, 'その子はラダン、その子はアミフデ、その子はエリシャマ、'),
('JPN', '历代志上', 13, 7, 27, 'その子はヌン、その子はヨシュア。'),
('JPN', '历代志上', 13, 7, 28, '彼らの所有地と居住地は、ベテルとそれに属する村々、東方ではナアラン、西方ではゲゼルとそれに属する村々、それからシェケムとそれに属する村々、そしてアヤとそれに属する村々に至る。'),
('JPN', '历代志上', 13, 7, 29, 'マナセ族の領土内には、ベテ・シェアンとそれに属する村々、タアナクとそれに属する村々、メギドとそれに属する村々、ドルとそれに属する村々があった。これらの地に、イスラエルの子ヨセフの子孫が住んだ。'),
('JPN', '历代志上', 13, 7, 30, 'アシェルの子はイムナ、イシュワ、イシュウィ、ベリアと彼らの姉妹セラフ。'),
('JPN', '历代志上', 13, 7, 31, 'ベリアの子はヘベル、マルキエル。マルキエルはビルザイテの父。'),
('JPN', '历代志上', 13, 7, 32, 'ヘベルが生んだのは、ヤフレテ、ショメル、ホタムと彼らの姉妹シュア。'),
('JPN', '历代志上', 13, 7, 33, 'ヤフレテの子はパサク、ビムハル、アシュワテ。これらがヤフレテの子であった。'),
('JPN', '历代志上', 13, 7, 34, 'ショメルの子はアヒ、ロフガ、フバ、アラム。'),
('JPN', '历代志上', 13, 7, 35, '彼の兄弟ヘレムの子はツォファフ、イムナ、シェレシュ、アマル。'),
('JPN', '历代志上', 13, 7, 36, 'ツォファフの子はスアハ、ハルネフェル、シュアル、ベリ、イムラ、'),
('JPN', '历代志上', 13, 7, 37, 'ベツェル、ホデ、シャンマ、シルシャ、イテラン、ベエラ。'),
('JPN', '历代志上', 13, 7, 38, 'エテルの子はエフンネ、ピスパ、アラ。'),
('JPN', '历代志上', 13, 7, 39, 'ウラの子はアラフ、ハニエル、リツヤ。'),
('JPN', '历代志上', 13, 7, 40, 'これらはみなアシェルの子で、一族のかしら、選り抜きの勇士、首長たちのかしらであった。戦いのとき戦に出る者として彼らの系図に記載された者の数は、二万六千人であった。'),
('JPN', '历代志上', 13, 8, 1, 'ベニヤミンが生んだのは、その長子ベラ、次男アシュベル、三男アハラフ、'),
('JPN', '历代志上', 13, 8, 2, '四男ノハ、五男ラファ。'),
('JPN', '历代志上', 13, 8, 3, 'ベラの子はアダル、ゲラ、アビフデ、'),
('JPN', '历代志上', 13, 8, 4, 'アビシュア、ナアマン、アホアハ、'),
('JPN', '历代志上', 13, 8, 5, 'ゲラ、シェフファン、フラム。'),
('JPN', '历代志上', 13, 8, 6, 'エフデの子は次のとおりである。彼らはゲバの住民の一族のかしらで、マナハテに捕らえ移された者たちである。'),
('JPN', '历代志上', 13, 8, 7, 'この人々を捕らえ移したのはナアマンとアヒヤとゲラである。エフデはウザとアヒフデを生んだ。'),
('JPN', '历代志上', 13, 8, 8, 'シャハライムは、その妻フシムとバアラを去らせてから、モアブの野で子をもうけた。'),
('JPN', '历代志上', 13, 8, 9, '彼がその妻ホデシュによって生んだのは、ヨバブ、ツィブヤ、メシャ、マルカム、'),
('JPN', '历代志上', 13, 8, 10, 'エウツ、サケヤ、ミルマ。これらは彼の子で、一族のかしらであった。'),
('JPN', '历代志上', 13, 8, 11, '彼がフシムによって生んだのは、アビトブとエルパアル。'),
('JPN', '历代志上', 13, 8, 12, 'エルパアルの子はエベル、ミシュアム、シェメデ。シェメデはオノとロデおよびそれに属する村々を建てた。'),
('JPN', '历代志上', 13, 8, 13, 'またベリアとシェマ。二人はアヤロンの住民の一族のかしらで、ガテの住民を追い払った。'),
('JPN', '历代志上', 13, 8, 14, 'アフヨ、シャシャク、エレモテ、'),
('JPN', '历代志上', 13, 8, 15, 'ゼバデヤ、アラド、エデル、'),
('JPN', '历代志上', 13, 8, 16, 'ミカエル、イシュパ、ヨハはベリアの子であった。'),
('JPN', '历代志上', 13, 8, 17, 'ゼバデヤ、メシュラム、ヒズキ、ヘベル、'),
('JPN', '历代志上', 13, 8, 18, 'イシュメライ、イズリア、ヨバブ。これらはエルパアルの子であった。'),
('JPN', '历代志上', 13, 8, 19, 'ヤキム、ジクリ、ザブディ、'),
('JPN', '历代志上', 13, 8, 20, 'エリエナイ、ツィレタイ、エリエル、'),
('JPN', '历代志上', 13, 8, 21, 'アダヤ、ベラヤ、シムラテ。これらはシムイの子であった。'),
('JPN', '历代志上', 13, 8, 22, 'イシュパン、エベル、エリエル、'),
('JPN', '历代志上', 13, 8, 23, 'アブドン、ジクリ、ハナン、'),
('JPN', '历代志上', 13, 8, 24, 'ハナンヤ、エラム、アントティヤ、'),
('JPN', '历代志上', 13, 8, 25, 'イフデヤ、ペヌエル。これらはシャシャクの子であった。'),
('JPN', '历代志上', 13, 8, 26, 'シャムシェライ、シェハルヤ、アタルヤ、'),
('JPN', '历代志上', 13, 8, 27, 'ヤアレシュヤ、エリヤ、ジクリ。これらはエロハムの子であった。'),
('JPN', '历代志上', 13, 8, 28, 'この人たちは、彼らの家系の一族のかしらであり、おもだった者たちであった。彼らはエルサレムに住んだ。'),
('JPN', '历代志上', 13, 8, 29, 'ギブオンにはギブオンの父が住んだ。その妻の名はマアカ。'),
('JPN', '历代志上', 13, 8, 30, 'その子は長子アブドン、それにツル、キシュ、バアル、ナダブ、'),
('JPN', '历代志上', 13, 8, 31, 'ゲドル、アフヨ、ゼケル。'),
('JPN', '历代志上', 13, 8, 32, 'ミクロテはシムアを生んだ。彼らも、その兄弟たちとともに、向かい合ってエルサレムに住んだ。'),
('JPN', '历代志上', 13, 8, 33, 'ネルはキシュを生み、キシュはサウルを生み、サウルはヨナタン、マルキ・シュア、アビナダブ、エシュバアルを生んだ。'),
('JPN', '历代志上', 13, 8, 34, 'ヨナタンの子はメリブ・バアル。メリブ・バアルはミカを生んだ。'),
('JPN', '历代志上', 13, 8, 35, 'ミカの子はピトン、メレク、タアレア、アハズ。'),
('JPN', '历代志上', 13, 8, 36, 'アハズはエホアダを生み、エホアダは、アレメテ、アズマウェテ、ジムリを生み、ジムリはモツァを生んだ。'),
('JPN', '历代志上', 13, 8, 37, 'モツァはビンアを生んだ。その子はラファ、その子はエルアサ、その子はアツェル。'),
('JPN', '历代志上', 13, 8, 38, 'アツェルには六人の子がいた。その名は次のとおりである。アズリカム、ボクル、イシュマエル、シェアルヤ、オバデヤ、ハナン。これらはみな、アツェルの子であった。'),
('JPN', '历代志上', 13, 8, 39, '彼の兄弟エシェクの子は、長子ウラム、次男エウシュ、三男エリフェレテ。'),
('JPN', '历代志上', 13, 8, 40, 'ウラムの子たちは勇士であり、弓を引く人々であった。子や孫が多く、百五十人いた。以上はみな、ベニヤミンの子孫であった。'),
('JPN', '历代志上', 13, 9, 1, '全イスラエルは系図に記載された。それは『イスラエルの王の書』にまさしく記されている。ユダは、その不信の罪のゆえに、バビロンに捕らえ移されていた。'),
('JPN', '历代志上', 13, 9, 2, '彼らの所有地である彼らの町々に戻って来て最初に住みついたのは、イスラエルの人々、祭司たち、レビ人および宮のしもべたちであった。'),
('JPN', '历代志上', 13, 9, 3, 'エルサレムには、ユダ族、ベニヤミン族、エフライムおよびマナセ族の者が住んだ。'),
('JPN', '历代志上', 13, 9, 4, 'アミフデの子ウタイ。アミフデはオムリの子、オムリはイムリの子、イムリはバニの子。バニはユダの子ペレツの子孫である。'),
('JPN', '历代志上', 13, 9, 5, 'シロ人からは、長子アサヤとその子孫。'),
('JPN', '历代志上', 13, 9, 6, 'ゼラフ族からは、エウエルとその同族六百九十人。'),
('JPN', '历代志上', 13, 9, 7, 'ベニヤミン族からは、サル。彼はセヌアの子ホダウヤの子であるメシュラムの子。'),
('JPN', '历代志上', 13, 9, 8, 'エロハムの子イブネヤ、ミクリの子ウジの子エラ、イブニヤの子レウエルの子であるシェファテヤの子メシュラム。'),
('JPN', '历代志上', 13, 9, 9, 'ならびに彼らの家系の同族九百五十六人。これらはみな、父祖の家ごとの一族のかしらに当たる人たちであった。'),
('JPN', '历代志上', 13, 9, 10, '祭司たちからは、エダヤ、エホヤリブ、ヤキン、'),
('JPN', '历代志上', 13, 9, 11, 'ヒルキヤの子アザルヤ。ヒルキヤはメシュラムの子、メシュラムはツァドクの子、ツァドクはメラヨテの子、メラヨテは神の宮のつかさアヒトブの子である。'),
('JPN', '历代志上', 13, 9, 12, 'エロハムの子アダヤ。エロハムはパシュフルの子、パシュフルはマルキヤの子である。またアディエルの子マサイ。アディエルはヤフゼラの子、ヤフゼラはメシュラムの子、メシュラムはメシレミテの子、メシレミテはイメルの子である。'),
('JPN', '历代志上', 13, 9, 13, '彼らの同族で一族のかしらたちは千七百六十人。彼らは、神の宮の奉仕の仕事に熟練した勇士たちであった。'),
('JPN', '历代志上', 13, 9, 14, 'レビ人からは、メラリ族のハシャブヤの子アズリカムの子ハシュブの子であるシェマヤ。'),
('JPN', '历代志上', 13, 9, 15, 'また、バクバカル、ヘレシュ、ガラル、マタンヤ。マタンヤはアサフの子ジクリの子であるミカの子。'),
('JPN', '历代志上', 13, 9, 16, 'オバデヤ。彼はエドトンの子ガラルの子であるシェマヤの子。そしてベレクヤ。彼はネトファ人の村々に住んだエルカナの子アサの子であった。'),
('JPN', '历代志上', 13, 9, 17, '門衛はシャルム、アクブ、タルモン、アヒマンで、彼らの兄弟シャルムがかしらであった。'),
('JPN', '历代志上', 13, 9, 18, '彼は今日に至るまで、東方にある王の門にいる。この人々はレビ人の宿営の門衛であった。'),
('JPN', '历代志上', 13, 9, 19, 'コラの子エブヤサフの子であるコレの子シャルムと、その父の家に属する彼の兄弟たち、すなわちコラ人は、その奉仕の務めに就き、天幕の入り口を守る者となった。彼らの一族は主の宿営の門口を守る者であった。'),
('JPN', '历代志上', 13, 9, 20, 'かつてはエルアザルの子ピネハスが彼らの長であり、主が彼とともにおられた。'),
('JPN', '历代志上', 13, 9, 21, 'メシェレムヤの子ゼカリヤは会見の天幕の戸口を守る門衛であった。'),
('JPN', '历代志上', 13, 9, 22, '入り口にいる門衛として選ばれたこれらの人たちは、合わせて二百十二人であった。彼らはそれぞれの村で系図に記載された。ダビデと予見者サムエルが、彼らの忠実さに基づいて、この職務を定めたのである。'),
('JPN', '历代志上', 13, 9, 23, '彼らとその子らは、守衛として主の宮すなわち天幕の家の門を受け持った。'),
('JPN', '历代志上', 13, 9, 24, '四方、すなわち東、西、北、南に門衛がいた。'),
('JPN', '历代志上', 13, 9, 25, '彼らの村々の同胞は、七日目ごとに来て、決まった時から決まった時まで、彼らとともにいなければならなかった。'),
('JPN', '历代志上', 13, 9, 26, '門衛の長である四人のレビ人は信任を得て、神の宮の脇部屋および宝物倉を受け持った。'),
('JPN', '历代志上', 13, 9, 27, '彼らは神の宮の周りで夜を過ごした。彼らには任務が課せられていて、朝ごとに鍵を開けたからである。'),
('JPN', '历代志上', 13, 9, 28, '彼らの中のある者は、奉仕のための器具を受け持った。数を合わせてこれらを運び入れ、数を合わせてこれらを運び出した。'),
('JPN', '历代志上', 13, 9, 29, 'また彼らの中のある者は、用具、すべての聖なる用具と、小麦粉、ぶどう酒、油、乳香、バルサム油の管理を割り当てられた。'),
('JPN', '历代志上', 13, 9, 30, '祭司の子の中には、バルサム油の香料を調合する者たちもいた。'),
('JPN', '历代志上', 13, 9, 31, 'レビ人の一人、コラ人シャルムの長男とマティテヤは、平たい菓子を作る務めを任された。'),
('JPN', '历代志上', 13, 9, 32, 'また、ケハテ族の彼らの同胞のうちには、並べ供えるパンを担当し、安息日ごとに用意する者たちもいた。'),
('JPN', '历代志上', 13, 9, 33, 'これらは歌い手で、レビ人の一族のかしらであり、各部屋にいて、ほかの務めを免れていた。昼となく夜となく彼らはその務めに携わったからである。'),
('JPN', '历代志上', 13, 9, 34, 'この人たちは、レビ人の一族のかしらであり、その家系のうちのおもだった者であった。彼らはエルサレムに住んだ。'),
('JPN', '历代志上', 13, 9, 35, 'ギブオンにはギブオンの父エイエルが住んだ。その妻の名はマアカ。'),
('JPN', '历代志上', 13, 9, 36, 'その子は、長子アブドン、それにツル、キシュ、バアル、ネル、ナダブ、'),
('JPN', '历代志上', 13, 9, 37, 'ゲドル、アフヨ、ゼカリヤ、ミクロテ。'),
('JPN', '历代志上', 13, 9, 38, 'ミクロテはシムアムを生んだ。彼らも、その兄弟たちとともに、向かい合ってエルサレムに住んだ。'),
('JPN', '历代志上', 13, 9, 39, 'ネルはキシュを生み、キシュはサウルを生み、サウルはヨナタン、マルキ・シュア、アビナダブ、エシュバアルを生んだ。'),
('JPN', '历代志上', 13, 9, 40, 'ヨナタンの子はメリブ・バアル。メリブ・バアルはミカを生んだ。'),
('JPN', '历代志上', 13, 9, 41, 'ミカの子はピトン、メレク、タフレア。'),
('JPN', '历代志上', 13, 9, 42, 'アハズはヤアラを生み、ヤアラはアレメテ、アズマウェテ、ジムリを生み、ジムリはモツァを生んだ。'),
('JPN', '历代志上', 13, 9, 43, 'モツァはビンアを生んだ。その子はレファヤ、その子はエルアサ、その子はアツェル。'),
('JPN', '历代志上', 13, 9, 44, 'アツェルには六人の子がいた。その名は次のとおりである。アズリカム、ボクル、イシュマエル、シェアルヤ、オバデヤ、ハナン。これらはアツェルの子であった。'),
('JPN', '历代志上', 13, 10, 1, 'さて、ペリシテ人はイスラエルと戦った。イスラエル人はペリシテ人の前から逃げ、ギルボア山で刺されて倒れた。'),
('JPN', '历代志上', 13, 10, 2, 'ペリシテ人はサウルとその息子たちに追い迫って、サウルの息子ヨナタン、アビナダブ、マルキ・シュアを打ち殺した。'),
('JPN', '历代志上', 13, 10, 3, '攻撃はサウルに集中し、射手たちが彼を狙い撃ちにしたので、彼は射手たちのゆえに傷を負った。'),
('JPN', '历代志上', 13, 10, 4, 'サウルは道具持ちに言った。「おまえの剣を抜いて、私を刺し殺してくれ。さもないと、あの無割礼の者たちがやって来て、私をなぶりものにするだろう。」しかし、道具持ちは非常に恐れて、とうていその気になれなかった。それでサウルは剣を取り、その上に倒れ込んだ。'),
('JPN', '历代志上', 13, 10, 5, '道具持ちは、サウルが死んだのを見ると、自分も剣の上に身を伏せて死んだ。'),
('JPN', '历代志上', 13, 10, 6, 'こうしてサウルは死に、彼の三人の息子も彼の全家も、ともに死んだ。'),
('JPN', '历代志上', 13, 10, 7, '谷にいたイスラエル人はみな、兵たちが逃げ、サウルとその息子たちが死んだのを見て、自分たちの町々を捨てて逃げた。それで、ペリシテ人がやって来て、そこに住んだ。'),
('JPN', '历代志上', 13, 10, 8, '翌日、ペリシテ人が、刺し殺された者たちからはぎ取ろうとしてやって来たとき、サウルとその息子たちがギルボア山で倒れているのを見つけた。'),
('JPN', '历代志上', 13, 10, 9, '彼らはサウルからはぎ取り、彼の首と武具を取った。そして、ペリシテ人の地の隅々にまで人を送り、彼らの偶像と民とに告げ知らせた。'),
('JPN', '历代志上', 13, 10, 10, '彼らはサウルの武具を彼らの神々の神殿に奉納し、彼の首はダゴンの神殿にさらした。'),
('JPN', '历代志上', 13, 10, 11, 'ヤベシュ・ギルアデの人々はみな、ペリシテ人がサウルに行った仕打ちをすべて聞いた。'),
('JPN', '历代志上', 13, 10, 12, 'そこで勇士たちがみな立ち上がり、サウルの亡骸と彼の息子たちの亡骸を取り上げ、これをヤベシュに運んで、彼らの骨をヤベシュにある樫の木の下に葬り、七日間、断食した。'),
('JPN', '历代志上', 13, 10, 13, 'このように、サウルは主の信頼を裏切った不信の罪のゆえに死んだ。彼は主のことばを守らず、霊媒に伺いを立てることまでして、'),
('JPN', '历代志上', 13, 10, 14, '主に尋ねることをしなかった。そのため、主は彼を殺し、王位をエッサイの子ダビデに回された。'),
('JPN', '历代志上', 13, 11, 1, '全イスラエルは、ヘブロンのダビデのもとに集まってこう言った。「ご覧ください。私たちはあなたの骨肉です。'),
('JPN', '历代志上', 13, 11, 2, 'これまで、サウルが王であったときでさえ、イスラエルを動かしていたのはあなたでした。あなたの神、主はあなたに言われました。『あなたがわたしの民イスラエルを牧し、あなたがわたしの民イスラエルの君主となる』と。」'),
('JPN', '历代志上', 13, 11, 3, 'イスラエルの全長老はヘブロンの王のもとに来た。ダビデはヘブロンで、主の御前に彼らと契約を結び、彼らはサムエルによる主のことばのとおりに、ダビデに油を注いでイスラエルの王とした。'),
('JPN', '历代志上', 13, 11, 4, 'ダビデと全イスラエルはエルサレム、すなわちエブスに行った。そこには、その地の住民であるエブス人がいた。'),
('JPN', '历代志上', 13, 11, 5, 'エブスの住民はダビデに言った。「おまえは、ここに攻めて来ることなどできない。」しかし、ダビデはシオンの要害を攻め取った。これがダビデの町である。'),
('JPN', '历代志上', 13, 11, 6, 'そのとき、ダビデは言った。「だれでも最初にエブス人を討つ者がかしらとなり、長となる。」ツェルヤの子ヨアブが最初に攻め上ったので、彼がかしらとなった。'),
('JPN', '历代志上', 13, 11, 7, 'ダビデはこの要害に住んだ。それゆえ、これはダビデの町と呼ばれた。'),
('JPN', '历代志上', 13, 11, 8, '彼は、町の周りに城壁を、ミロから一周するまで築いた。町のほかの部分はヨアブが築き直した。'),
('JPN', '历代志上', 13, 11, 9, 'ダビデはますます大いなる者となり、万軍の主が彼とともにおられた。'),
('JPN', '历代志上', 13, 11, 10, 'ダビデの勇士のかしらたちは次のとおりである。彼らは、ダビデとともにその王権を強固にし、全イスラエルとともに、イスラエルについての主のことばのとおり、彼を王とした人々である。'),
('JPN', '历代志上', 13, 11, 11, 'ダビデの勇士たちの名簿は次のとおりである。補佐官のかしら、ハクモニの子ヤショブアム。彼は槍を振るって一度に三百人を刺し殺した。'),
('JPN', '历代志上', 13, 11, 12, '彼の次は、アホアハ人ドドの子エルアザル。彼は三勇士の一人であった。'),
('JPN', '历代志上', 13, 11, 13, '彼がダビデとともにパス・ダミムにいたとき、ペリシテ人が戦うためにそこに集まった。そこには、大麦が豊かに実った畑があった。兵はペリシテ人の前から逃げたが、'),
('JPN', '历代志上', 13, 11, 14, '彼らはその畑の真ん中に踏みとどまってこれを守り、ペリシテ人を討った。主は大勝利をもって救われた。'),
('JPN', '历代志上', 13, 11, 15, '三十人のかしらのうちのこの三人は、岩場にあるアドラムの洞穴にいるダビデのところに下って来た。ペリシテ人の陣営はレファイムの谷間に敷かれていた。'),
('JPN', '历代志上', 13, 11, 16, 'そのときダビデは要害にいて、ペリシテ人の守備隊はそのときベツレヘムにいた。'),
('JPN', '历代志上', 13, 11, 17, 'ダビデは切に望んで、「だれか私に、ベツレヘムの門にある井戸の水を飲ませてくれたらよいのだが」と言った。'),
('JPN', '历代志上', 13, 11, 18, '三人はペリシテ人の陣営を突き破って、ベツレヘムの門にある井戸から水を汲み、それを携えてダビデのところに持って来た。しかしダビデはそれを飲もうとはせず、それを主の前に注いで、'),
('JPN', '历代志上', 13, 11, 19, 'こう言った。「そんなことをするなど、私の神の御前に、絶対にできない。いのちをかけて行った人たちの血を、どうして飲めるだろうか。彼らは、いのちをかけてこれを運んで来てくれたのだ。」彼はそれを飲もうとはしなかった。三勇士は、そのようなことまでしたのである。'),
('JPN', '历代志上', 13, 11, 20, 'さて、ヨアブの兄弟アビシャイは三十人のかしらであった。彼は槍を振るって三百人を刺し殺し、あの三人とともに名をあげた。'),
('JPN', '历代志上', 13, 11, 21, '彼は三十人の中で二倍の誉れを受けていたので、彼らの長になったが、あの三人には及ばなかった。'),
('JPN', '历代志上', 13, 11, 22, 'エホヤダの子ベナヤは、カブツェエル出身で、多くの手柄を立てた力ある人であった。彼はモアブの英雄二人を打ち殺した。また、ある雪の日に、洞穴の中に下りて行って雄獅子を打ち殺した。'),
('JPN', '历代志上', 13, 11, 23, '彼はまた、身長が五キュビトもあるエジプト人を打ち殺した。このエジプト人は、手に機織りの巻き棒のような槍を持っていた。ベナヤは杖を持ってその男のところに下って行き、エジプト人の手から槍をもぎ取って、その槍で彼を殺した。'),
('JPN', '历代志上', 13, 11, 24, 'エホヤダの子ベナヤはこれらのことをして、三勇士とともに名をあげた。'),
('JPN', '历代志上', 13, 11, 25, '彼はあの三十人の中でも最も誉れが高かったが、あの三人には及ばなかった。ダビデは彼を自分の護衛長にした。'),
('JPN', '历代志上', 13, 11, 26, '勇士たちは次のとおりである。ヨアブの兄弟アサエル。ベツレヘム出身のドドの子エルハナン。'),
('JPN', '历代志上', 13, 11, 27, 'ハロリ人シャモテ。ペロニ人ヘレツ。'),
('JPN', '历代志上', 13, 11, 28, 'テコア人イケシュの子イラ。アナトテ人アビエゼル。'),
('JPN', '历代志上', 13, 11, 29, 'フシャ人シベカイ。アホアハ人イライ。'),
('JPN', '历代志上', 13, 11, 30, 'ネトファ人マフライ。ネトファ人バアナの子ヘレデ。'),
('JPN', '历代志上', 13, 11, 31, 'ギブア出身のベニヤミン族リバイの子イタイ。ピルアトン人ベナヤ。'),
('JPN', '历代志上', 13, 11, 32, 'ガアシュの谷の出であるフライ。アルバト人アビエル。'),
('JPN', '历代志上', 13, 11, 33, 'バハルム人アズマウェテ。シャアルビム人エルヤフバ。'),
('JPN', '历代志上', 13, 11, 34, 'ギゾ人ハシェムの息子たち。ハラル人シャゲの子ヨナタン。'),
('JPN', '历代志上', 13, 11, 35, 'ハラル人サカルの子アヒアム。ウルの子エリファル。'),
('JPN', '历代志上', 13, 11, 36, 'メケラテ人ヘフェル。ペロン人アヒヤ。'),
('JPN', '历代志上', 13, 11, 37, 'カルメル人ヘツロ。エズバイの子ナアライ。'),
('JPN', '历代志上', 13, 11, 38, 'ナタンの兄弟ヨエル。ハグリの子ミブハル。'),
('JPN', '历代志上', 13, 11, 39, 'アンモン人ツェレク。ツェルヤの子ヨアブの道具持ち、ベエロテ人ナフライ。'),
('JPN', '历代志上', 13, 11, 40, 'エテル人イラ。エテル人ガレブ。'),
('JPN', '历代志上', 13, 11, 41, 'ヒッタイト人ウリヤ。アフライの子ザバデ。'),
('JPN', '历代志上', 13, 11, 42, 'ルベン人シザの子アディナ。彼はルベン人のかしらで、三十人を率いていた。'),
('JPN', '历代志上', 13, 11, 43, 'マアカの子ハナン。ミテニ人ヨシャファテ。'),
('JPN', '历代志上', 13, 11, 44, 'アシュタロテ人ウジヤ。アロエル人ホタムの子シャマとエイエル。'),
('JPN', '历代志上', 13, 11, 45, 'ティツ人シムリの子エディアエルとその兄弟ヨハ。'),
('JPN', '历代志上', 13, 11, 46, 'マハウィム人エリエル。エルナアムの子エリバイとヨシャウヤ。モアブ人イテマ。'),
('JPN', '历代志上', 13, 11, 47, 'エリエル、オベデ、メツォバヤ人ヤアシエル。'),
('JPN', '历代志上', 13, 12, 1, 'ダビデがまだキシュの子サウルから身を避けていたとき、ツィクラグの彼のもとに来た人たちは次のとおりである。彼らは、勇士たちの中で戦いの加勢をした人たちであり、'),
('JPN', '历代志上', 13, 12, 2, '弓を取る者で、右手でも左手でも石を投げたり弓を射たりでき、サウルの同族ベニヤミンの出であった。'),
('JPN', '历代志上', 13, 12, 3, 'かしらはアヒエゼル、次はヨアシュ。彼らはギブア人シェマアの子。エジエルとペレテ。彼らはアズマウェテの子。ベラカとアナトテ人エフー。'),
('JPN', '历代志上', 13, 12, 4, 'ギブオン人イシュマヤ、彼は三十人の中の勇士で、三十人の長であった。次に、エレミヤ、ヤハジエル、ヨハナン、ゲデラ人エホザバデ、'),
('JPN', '历代志上', 13, 12, 5, 'エルウザイ、エリモテ、ベアルヤ、シェマルヤ、ハリフ人シェファテヤ、'),
('JPN', '历代志上', 13, 12, 6, 'エルカナ、イシヤ、アザルエル、ヨエゼル、ヤショブアム。これらはコラ人である。'),
('JPN', '历代志上', 13, 12, 7, 'ヨエラとゼバデヤ。これらはゲドル出身のエロハムの子である。'),
('JPN', '历代志上', 13, 12, 8, 'また、ガド人から離れて、荒野の要害にいたダビデのもとに来た人たちは、勇士で戦いにたけた人たちであり、大盾と槍の備えがあった。彼らの顔は獅子の顔で、速く走ることは山のかもしかのようであった。'),
('JPN', '历代志上', 13, 12, 9, 'そのかしらはエゼル。第二はオバデヤ。第三はエリアブ。'),
('JPN', '历代志上', 13, 12, 10, '第四はミシュマナ。第五はエレミヤ。'),
('JPN', '历代志上', 13, 12, 11, '第六はアタイ。第七はエリエル。'),
('JPN', '历代志上', 13, 12, 12, '第八はヨハナン。第九はエルザバデ。'),
('JPN', '历代志上', 13, 12, 13, '第十はエレミヤ。第十一はマクバナイ。'),
('JPN', '历代志上', 13, 12, 14, 'これらはガド族から出た軍のかしらたちで、その最も小さい者も、一人が百人に匹敵し、最も大いなる者は千人に匹敵した。'),
('JPN', '历代志上', 13, 12, 15, 'この人たちは、第一の月、すなわちヨルダン川がどこの岸もいっぱいにあふれるとき、これを渡った者たちである。彼らは、谷にいた人々をすべて東に西に追い散らした。'),
('JPN', '历代志上', 13, 12, 16, 'ベニヤミンとユダの子孫からも、要害のダビデのもとに来た人たちがいた。'),
('JPN', '历代志上', 13, 12, 17, 'ダビデは彼らの前に出て行き、彼らに答えて言った。「もし、あなたがたがやって来たのが平和のためであり、私を助けようとするのなら、私の心はあなたがたと一つだ。しかし、もし、私の手に暴虐がないのに、私をだまして、私の敵に渡すためなら、私たちの父祖の神がそれを見て、責められますように。」'),
('JPN', '历代志上', 13, 12, 18, 'そのとき、御霊が補佐官の長アマサイをおおった。「ダビデよ、私たちはあなたの味方。エッサイの子よ、私たちはあなたとともにいる。平安があるように。あなたに平安があるように。あなたを助ける者に平安があるように。まことにあなたの神はあなたを助ける。」ダビデは彼らを受け入れ、部隊のかしらとした。'),
('JPN', '历代志上', 13, 12, 19, 'ダビデがペリシテ人とともに、サウルとの戦いに出たとき、マナセからも何人かの者がダビデのもとに下って来た。しかし彼らはペリシテ人を助けなかった。ペリシテ人の領主たちが協議をし、「彼はわれわれの首を持って、主君サウルのもとに投降するだろう」と言って、彼を送り返したからである。'),
('JPN', '历代志上', 13, 12, 20, 'ダビデがツィクラグに行ったとき、マナセからアデナフ、エホザバデ、エディアエル、ミカエル、エホザバデ、エリフ、ツィレタイが彼のもとに下って来た。彼らはマナセに属する千人隊のかしらであった。'),
('JPN', '历代志上', 13, 12, 21, '彼らはダビデを助けて、あの略奪隊に対抗した。みな勇士であり、軍における長であった。'),
('JPN', '历代志上', 13, 12, 22, '人々はダビデを助けるため、日に日に彼のもとに来て、ついに神の陣営のような大陣営となった。'),
('JPN', '历代志上', 13, 12, 23, '主のことばのとおりにサウルの支配をダビデに移すために、ヘブロンにいるダビデのもとに来た武装した者のかしらの数は次のとおりである。'),
('JPN', '历代志上', 13, 12, 24, 'ユダ族で、大盾と槍を手にして武装した者六千八百人。'),
('JPN', '历代志上', 13, 12, 25, 'シメオン族からは、戦に出る勇士七千百人。'),
('JPN', '历代志上', 13, 12, 26, 'レビ族からは四千六百人。'),
('JPN', '历代志上', 13, 12, 27, 'エホヤダはアロンの家のつかさで、彼とともにいた者は三千七百人。'),
('JPN', '历代志上', 13, 12, 28, 'ツァドクは若い勇士で、その一族には二十二人の隊長がいた。'),
('JPN', '历代志上', 13, 12, 29, 'サウルの同胞ベニヤミン族からは三千人。その大多数は、それまでサウルの家を守り続けてきた。'),
('JPN', '历代志上', 13, 12, 30, 'エフライム族からは二万八百人。彼らは勇士で、その一族で名のある人々であった。'),
('JPN', '历代志上', 13, 12, 31, 'マナセの半部族からは、ダビデを王にするために指名されて来た者一万八千人。'),
('JPN', '历代志上', 13, 12, 32, 'イッサカル族からは、時を悟り、イスラエルが何をなすべきかを知っていた、かしら二百人。その同胞はみな彼らの命令に従った。'),
('JPN', '历代志上', 13, 12, 33, 'ゼブルンからは、完全に武装して戦いの備えをして従軍していた者五万人。彼らは心を一つにして集まった。'),
('JPN', '历代志上', 13, 12, 34, 'ナフタリからは隊長一千人。彼らのもとに大盾と槍を取る者三万七千人。'),
('JPN', '历代志上', 13, 12, 35, 'ダン人からは、戦いの備えをした者二万八千六百人。'),
('JPN', '历代志上', 13, 12, 36, 'アシェルからは、戦いの備えをして従軍する者四万人。'),
('JPN', '历代志上', 13, 12, 37, 'ヨルダンの川向こう、ルベン人、ガド人、マナセの半部族からは、戦いのために完全武装をした者十二万人。'),
('JPN', '历代志上', 13, 12, 38, 'これらすべての、戦いに備えて集まった戦士たちは、ダビデを全イスラエルの王にしようと、全き心でヘブロンに来た。イスラエルの残りの者たちも、ダビデを王にすることで心が一つになっていた。'),
('JPN', '历代志上', 13, 12, 39, '彼らはダビデとともに三日間そこにとどまり、食べたり飲んだりした。彼らの兄弟たちが彼らのために用意したのである。'),
('JPN', '历代志上', 13, 12, 40, '彼らに近い者たちも、イッサカル、ゼブルン、ナフタリに至るまで、ろば、らくだ、らば、牛に載せて食べ物を運んで来た。小麦粉の菓子、干しいちじく、干しぶどう、ぶどう酒、油、牛、羊などが数多くあった。イスラエルに喜びがあったからである。'),
('JPN', '历代志上', 13, 13, 1, 'ダビデは千人隊と百人隊の長たち、およびすべての隊長と協議し、'),
('JPN', '历代志上', 13, 13, 2, 'イスラエルの全会衆に言った。「もしあなたがたが良しとし、私たちの神、主から出たことなら、イスラエル全土に残っている私たちの同胞に一斉に使者を送ろう。彼らのうちには、放牧地のある町々の祭司やレビ人もいる。彼らを私たちのもとに集めよう。'),
('JPN', '历代志上', 13, 13, 3, '私たちの神の箱を私たちのもとに持ち帰ろう。私たちは、サウルの時代には、これを顧みなかったから。」'),
('JPN', '历代志上', 13, 13, 4, 'すると全会衆は、そうしようと言った。このことが、すべての民の目には良いことに思えたからである。'),
('JPN', '历代志上', 13, 13, 5, 'そこで、ダビデは、神の箱をキルヤテ・エアリムから運ぶため、エジプトのシホルからレボ・ハマテに至るまでの全イスラエルを召集した。'),
('JPN', '历代志上', 13, 13, 6, 'ダビデと全イスラエルは、バアラ、すなわちユダに属するキルヤテ・エアリムに上り、そこから、「ケルビムに座しておられる主」という名で呼ばれていた神の箱を運び上げようとした。'),
('JPN', '历代志上', 13, 13, 7, '彼らはアビナダブの家から、神の箱を新しい荷車に載せ、ウザとアフヨがその荷車を御した。'),
('JPN', '历代志上', 13, 13, 8, 'ダビデと全イスラエルは、歌、竪琴、琴、タンバリン、シンバル、ラッパをもって、神の前で力の限り喜び踊った。'),
('JPN', '历代志上', 13, 13, 9, '彼らがキドンの打ち場まで来たとき、ウザは手を伸ばして、箱を押さえた。牛がよろめいたからである。'),
('JPN', '历代志上', 13, 13, 10, 'すると、主の怒りがウザに向かって燃え上がり、彼を打った。彼が手を箱の上に伸ばしたからである。彼はその場で、神の前で死んだ。'),
('JPN', '历代志上', 13, 13, 11, 'ダビデの心は激した。主がウザに対して怒りを発せられたからである。その場所は今日までペレツ・ウザと呼ばれている。'),
('JPN', '历代志上', 13, 13, 12, 'その日、ダビデは神を恐れて言った。「どうして、神の箱を私のところに運び込むことができようか。」'),
('JPN', '历代志上', 13, 13, 13, 'そこでダビデは、箱を自分のところ、ダビデの町には移さず、ガテ人オベデ・エドムの家に回した。'),
('JPN', '历代志上', 13, 13, 14, '神の箱は、オベデ・エドムの一家とともに、彼の家に三か月とどまった。主は、オベデ・エドムの家と、彼に属するすべてのものを祝福された。'),
('JPN', '历代志上', 13, 14, 1, 'ツロの王ヒラムは、ダビデの王宮を建てるため、ダビデのもとに使者と、杉材、石工、木工を送った。'),
('JPN', '历代志上', 13, 14, 2, 'ダビデは、主が自分をイスラエルの王として堅く立ててくださり、主の民イスラエルのために、自分の王権が高く上げられていることを知った。'),
('JPN', '历代志上', 13, 14, 3, 'ダビデはエルサレムで、さらに妻たちを迎えた。ダビデはさらに息子たち、娘たちを生んだ。'),
('JPN', '历代志上', 13, 14, 4, 'エルサレムで彼に生まれた子の名は次のとおり。シャムア、ショバブ、ナタン、ソロモン、'),
('JPN', '历代志上', 13, 14, 5, 'イブハル、エリシュア、エリフェレテ、'),
('JPN', '历代志上', 13, 14, 6, 'ノガハ、ネフェグ、ヤフィア、'),
('JPN', '历代志上', 13, 14, 7, 'エリシャマ、ベエルヤダ、エリフェレテ。'),
('JPN', '历代志上', 13, 14, 8, 'ペリシテ人は、ダビデが油注がれて全イスラエルの王となったことを聞いた。ペリシテ人はみな、ダビデを狙って攻め上って来た。ダビデはそれを聞き、彼らを迎え撃ちに出た。'),
('JPN', '历代志上', 13, 14, 9, '一方、ペリシテ人はやって来て、レファイムの谷間を襲った。'),
('JPN', '历代志上', 13, 14, 10, 'ダビデは神に伺った。「ペリシテ人に向かって攻め上るべきでしょうか。彼らを私の手に渡してくださるでしょうか。」主は彼に言われた。「攻め上れ。わたしは彼らをあなたの手に渡す。」'),
('JPN', '历代志上', 13, 14, 11, '彼らはバアル・ペラツィムに攻め上り、ダビデはそこで彼らを討った。ダビデは言った。「神は、水が破れ出るように、私の手を用いて私の敵を破られた。」それゆえ、その場所の名はバアル・ペラツィムと呼ばれた。'),
('JPN', '历代志上', 13, 14, 12, '彼らはそこに自分たちの神々を置き去りにした。ダビデが命じたので、それらは火で焼かれた。'),
('JPN', '历代志上', 13, 14, 13, 'ペリシテ人は、再びその谷間を襲った。'),
('JPN', '历代志上', 13, 14, 14, 'ダビデが再び神に伺うと、神は彼に仰せられた。「彼らを追って上って行くな。彼らに面と向かわず回り込み、バルサム樹の茂みの前から彼らに向かえ。'),
('JPN', '历代志上', 13, 14, 15, 'バルサム樹の茂みの上で行進の音が聞こえたら、そのとき、あなたは攻めかかれ。神が、ペリシテ人の陣営を討つために、あなたより先に出ているからだ。」'),
('JPN', '历代志上', 13, 14, 16, 'ダビデは神が彼に命じられたとおりにした。彼らはギブオンからゲゼルまでのペリシテ人の陣営を討った。'),
('JPN', '历代志上', 13, 14, 17, 'こうして、ダビデの名声は全地に及んだ。主はすべての国々に、彼に対する恐れをもたらされた。'),
('JPN', '历代志上', 13, 15, 1, 'ダビデは、ダビデの町に自分のために家を造り、また神の箱のために場所を定め、そのために天幕を張った。'),
('JPN', '历代志上', 13, 15, 2, 'そのとき、ダビデは言った。「レビ人でなければ、神の箱を担いではならない。主は、主の箱を担がせ、とこしえまでもご自分に仕えさせようと、彼らを選ばれたからである。」'),
('JPN', '历代志上', 13, 15, 3, 'ダビデは全イスラエルをエルサレムに呼び集め、主の箱を、定めておいた場所へ運び上げようとした。'),
('JPN', '历代志上', 13, 15, 4, 'ダビデはアロンの子らとレビ人を集めた。'),
('JPN', '历代志上', 13, 15, 5, 'ケハテ族から、その長ウリエルと、彼の同族の者百二十人。'),
('JPN', '历代志上', 13, 15, 6, 'メラリ族から、その長アサヤと、彼の同族の者二百二十人。'),
('JPN', '历代志上', 13, 15, 7, 'ゲルショム族から、その長ヨエルと、彼の同族の者百三十人。'),
('JPN', '历代志上', 13, 15, 8, 'エリツァファン族から、その長シェマヤと、彼の同族の者二百人。'),
('JPN', '历代志上', 13, 15, 9, 'ヘブロン族から、その長エリエルと、彼の同族の者八十人。'),
('JPN', '历代志上', 13, 15, 10, 'ウジエル族から、その長アミナダブと、彼の同族の者百二十人。'),
('JPN', '历代志上', 13, 15, 11, 'ダビデは祭司ツァドクとエブヤタル、それにレビ人のウリエルとアサヤ、ヨエルとシェマヤ、エリエル、アミナダブを呼び寄せて、'),
('JPN', '历代志上', 13, 15, 12, 'こう言った。「あなたがたはレビ人の各家系のかしらである。あなたがたと同族の者たちは身を聖別し、イスラエルの神、主の箱を、私が定めておいた場所へ運び上げなさい。'),
('JPN', '历代志上', 13, 15, 13, '最初の時には、あなたがたがいなかったため、私たちの神、主は私たちに怒りを発せられた。定めにしたがって、私たちが主を求めなかったからだ。」'),
('JPN', '历代志上', 13, 15, 14, 'そこで、祭司たちとレビ人たちは、イスラエルの神、主の箱を運び上げるために身を聖別した。'),
('JPN', '历代志上', 13, 15, 15, 'レビ人たちは、モーセが主のことばにしたがって命じたとおり、担い棒を肩に載せて神の箱を担いだ。'),
('JPN', '历代志上', 13, 15, 16, 'ダビデはレビ人の長たちに命じて、彼らの同族の者たちを歌い手として任命し、琴、竪琴、シンバルなどの楽器を手に、喜びの声をあげるようにさせた。'),
('JPN', '历代志上', 13, 15, 17, 'そこで、レビ人は、ヨエルの子ヘマン、彼の同族からベレクヤの子アサフ、彼らの同族メラリ族からクシャヤの子エタンを任命した。'),
('JPN', '历代志上', 13, 15, 18, 'また彼らとともに同族の第二の組として、ゼカリヤ、ベン、ヤアジエル、シェミラモテ、エヒエル、ウンニ、エリアブ、ベナヤ、マアセヤ、マティテヤ、エリフェレフ、ミクネヤ、門衛のオベデ・エドムとエイエルを任命した。'),
('JPN', '历代志上', 13, 15, 19, '歌い手ヘマン、アサフ、エタンは、青銅のシンバルを鳴らした。'),
('JPN', '历代志上', 13, 15, 20, 'ゼカリヤ、アジエル、シェミラモテ、エヒエル、ウンニ、エリアブ、マアセヤ、ベナヤは、『アラモテの調べ』にのせて、琴を奏でた。'),
('JPN', '历代志上', 13, 15, 21, 'マティテヤ、エリフェレフ、ミクネヤ、オベデ・エドム、エイエル、アザズヤは、『第八の調べ』にのせ、竪琴に合わせて指揮した。'),
('JPN', '历代志上', 13, 15, 22, 'レビ人の長の一人であるケナンヤは歌唱を担当し、歌唱を導いた。彼はそれに通じていたからである。'),
('JPN', '历代志上', 13, 15, 23, 'ベレクヤとエルカナは箱を守る門衛であった。'),
('JPN', '历代志上', 13, 15, 24, '祭司たち、すなわちシェバンヤ、ヨシャファテ、ネタンエル、アマサイ、ゼカリヤ、ベナヤ、エリエゼルは、神の箱の前でラッパを吹き鳴らす者、オベデ・エドムとエヒヤは箱を守る門衛であった。'),
('JPN', '历代志上', 13, 15, 25, 'こうしてダビデは、イスラエルの長老たち、千人隊の長たちとともに行って、喜びをもって主の契約の箱をオベデ・エドムの家から運び上げようとした。'),
('JPN', '历代志上', 13, 15, 26, '神が主の契約の箱を担ぐレビ人を助けてくださったとき、彼らは雄牛七頭と雄羊七匹をいけにえとして献げた。'),
('JPN', '历代志上', 13, 15, 27, 'ダビデは上質の亜麻布の上着をまとっていた。箱を担ぐすべてのレビ人、歌い手たち、歌い手たちの歌唱の導き手ケナンヤも同様であった。ダビデは亜麻布のエポデを身に着けていた。'),
('JPN', '历代志上', 13, 15, 28, '全イスラエルは歓声をあげ、角笛、ラッパ、シンバルを鳴らし、琴と竪琴を響かせて、主の契約の箱を運び上げた。'),
('JPN', '历代志上', 13, 15, 29, 'こうして、主の契約の箱はダビデの町に入った。サウルの娘ミカルは窓から見下ろしていたが、ダビデ王が飛び跳ねて喜び踊っているのを見て、心の中で彼を蔑んだ。'),
('JPN', '历代志上', 13, 16, 1, '人々は神の箱を運び込んで、ダビデがそのために張った天幕の真ん中にそれを置き、神の前に全焼のささげ物と交わりのいけにえを献げた。'),
('JPN', '历代志上', 13, 16, 2, 'ダビデは全焼のささげ物と交わりのいけにえを献げ終えて、主の御名によって民を祝福した。'),
('JPN', '历代志上', 13, 16, 3, 'そしてイスラエルのすべての人に、男にも女にも、それぞれ、円形パン、なつめ椰子の菓子、干しぶどうの菓子を分け与えた。'),
('JPN', '历代志上', 13, 16, 4, 'それから、レビ人の中のある者たちを任命して主の箱の前で仕えさせ、イスラエルの神、主に向かってその御名を呼び、告白し、賛美するようにした。'),
('JPN', '历代志上', 13, 16, 5, 'かしらはアサフ、彼に次ぐ者は、ゼカリヤ、エイエル、シェミラモテ、エヒエル、マティテヤ、エリアブ、ベナヤ、オベデ・エドム、エイエル。彼らは琴や竪琴などの楽器を携え、アサフはシンバルを響かせた。'),
('JPN', '历代志上', 13, 16, 6, '祭司ベナヤとヤハジエルは、ラッパを携え、常に神の契約の箱の前にいた。'),
('JPN', '历代志上', 13, 16, 7, 'その日、その時、初めてダビデはアサフとその兄弟たちを任命して、このように主に感謝をささげさせた。'),
('JPN', '历代志上', 13, 16, 8, '主に感謝し、御名を呼び求めよ。そのみわざを諸国の民の間に知らせよ。'),
('JPN', '历代志上', 13, 16, 9, '主に歌え。主にほめ歌を歌え。そのすべての奇しいみわざを語れ。'),
('JPN', '历代志上', 13, 16, 10, '主の聖なる御名を誇りとせよ。主を慕い求める者たちの心よ、喜べ。'),
('JPN', '历代志上', 13, 16, 11, '主とその御力を尋ね求めよ。絶えず御顔を慕い求めよ。'),
('JPN', '历代志上', 13, 16, 12, '主が行われた奇しいみわざを思い起こせ。その奇跡と御口のさばきを。'),
('JPN', '历代志上', 13, 16, 13, '主のしもべイスラエルの裔よ。主に選ばれた者、ヤコブの子らよ。'),
('JPN', '历代志上', 13, 16, 14, 'この方こそ、私たちの神、主。そのさばきは全地にわたる。'),
('JPN', '历代志上', 13, 16, 15, '心に留めよ。主の契約をとこしえに。命じられたみことばを、千代までも。'),
('JPN', '历代志上', 13, 16, 16, 'それは、アブラハムと結んだ契約。イサクへの誓い。'),
('JPN', '历代志上', 13, 16, 17, '主はそれをヤコブへの定めとして立てられた。イスラエルへの、永遠の契約として。'),
('JPN', '历代志上', 13, 16, 18, 'そのとき主は言われた。「わたしは、あなたにカナンの地を与える。あなたがたへのゆずりの地として。」'),
('JPN', '历代志上', 13, 16, 19, 'そのころ、あなたがたの数は少なく、実にわずかで、そこでは寄留者であった。'),
('JPN', '历代志上', 13, 16, 20, '彼らは、国から国へ、一つの王国からほかの民へと渡り歩いた。'),
('JPN', '历代志上', 13, 16, 21, 'しかし主は、だれにも彼らを虐げさせず、彼らのために王たちを戒められた。'),
('JPN', '历代志上', 13, 16, 22, '「わたしの油注がれた者たちに触れるな。わたしの預言者たちに危害を加えるな。」'),
('JPN', '历代志上', 13, 16, 23, '全地よ、主に歌え。日から日へと、御救いの良い知らせを告げよ。'),
('JPN', '历代志上', 13, 16, 24, '主の栄光を国々の間で語り告げよ。その奇しいみわざを、あらゆる民の間で。'),
('JPN', '历代志上', 13, 16, 25, '主は大いなる方、大いに賛美される方。すべての神々にまさって恐れられる方だ。'),
('JPN', '历代志上', 13, 16, 26, 'まことに、どの民の神々もみな偽りだ。しかし主は天をお造りになった。'),
('JPN', '历代志上', 13, 16, 27, '威厳と威光は御前にあり、力と喜びは御住まいにある。'),
('JPN', '历代志上', 13, 16, 28, 'もろもろの民の諸族よ、主に帰せよ。栄光と力を主に帰せよ。'),
('JPN', '历代志上', 13, 16, 29, '御名の栄光を主に帰せよ。ささげ物を携えて、御前に来たれ。聖なる装いをして、主にひれ伏せ。'),
('JPN', '历代志上', 13, 16, 30, '全地よ、主の御前におののけ。まことに、世界は堅く据えられ揺るがない。'),
('JPN', '历代志上', 13, 16, 31, '天は喜び、地は小躍りせよ。国々の間で言え。「主は王である」と。'),
('JPN', '历代志上', 13, 16, 32, '海とそこに満ちているものは、鳴りとどろけ。野とその中にあるものは、みな喜び躍れ。'),
('JPN', '历代志上', 13, 16, 33, 'そのとき、森の木々も喜び歌う。主の御前で。主は必ず、地をさばくために来られる。'),
('JPN', '历代志上', 13, 16, 34, '主に感謝せよ。主はまことにいつくしみ深い。その恵みはとこしえまで。'),
('JPN', '历代志上', 13, 16, 35, '言え。「私たちの救いの神よ、私たちをお救いください。国々から私たちを集め、救い出してください。あなたの聖なる御名に感謝し、あなたの誉れを勝ち誇るために。」'),
('JPN', '历代志上', 13, 16, 36, 'ほむべきかな、イスラエルの神、主。とこしえから、とこしえまで。それから、民はみな「アーメン」と言い、主をほめたたえた。'),
('JPN', '历代志上', 13, 16, 37, 'ダビデはそこに、主の契約の箱の前にアサフとその兄弟たちをとどめおき、毎日の日課として、常に箱の前で仕えさせた。'),
('JPN', '历代志上', 13, 16, 38, 'オベデ・エドムとその六十八人の兄弟たちにもそのようにさせた。エドトンの子オベデ・エドムとホサは門衛とした。'),
('JPN', '历代志上', 13, 16, 39, '祭司ツァドクとその兄弟の祭司たちは、ギブオンの高き所にある主の幕屋の前にとどめおき、'),
('JPN', '历代志上', 13, 16, 40, 'すべて主がイスラエルに命じられた律法に書かれているとおりに、朝夕絶えず、全焼のささげ物の祭壇の上で主に全焼のささげ物を献げさせた。'),
('JPN', '历代志上', 13, 16, 41, 'また、彼らとともにヘマン、エドトン、さらにほかの選ばれた者たちが、「まことに主の恵みは、とこしえまで」と、主をほめたたえるために指名された。'),
('JPN', '历代志上', 13, 16, 42, 'ヘマンとエドトンの手には、ラッパとシンバル、また神の歌に用いる楽器があって、音楽を奏でた。エドトンの子らは門にいた。'),
('JPN', '历代志上', 13, 16, 43, '民はみな、それぞれ自分の家に帰った。ダビデも自分の家族を祝福するために戻って行った。'),
('JPN', '历代志上', 13, 17, 1, 'ダビデが自分の家に住んでいたときのことである。ダビデは預言者ナタンに言った。「見なさい。この私が杉材の家に住んでいるのに、主の契約の箱は天幕の下にある。」'),
('JPN', '历代志上', 13, 17, 2, 'ナタンはダビデに言った。「あなたの心にあることをみな行いなさい。神があなたとともにおられるのですから。」'),
('JPN', '历代志上', 13, 17, 3, 'その夜のことである。次のような神のことばがナタンにあった。'),
('JPN', '历代志上', 13, 17, 4, '「行って、わたしのしもべダビデに言え。『主はこう言われる。あなたがわたしのために、住む家を建てるのではない。'),
('JPN', '历代志上', 13, 17, 5, 'わたしは、イスラエルを連れ上った日から今日まで、家に住んだことはなく、天幕から天幕に、幕屋から幕屋に移ってきたのだ。'),
('JPN', '历代志上', 13, 17, 6, 'わたしが全イスラエルと歩んだところどこででも、わたしが、わたしの民を牧せよと命じたイスラエルのさばきつかさの一人にでも、「なぜ、あなたがたはわたしのために杉材の家を建てなかったのか」と、一度でも言ったことがあっただろうか。』'),
('JPN', '历代志上', 13, 17, 7, '今、わたしのしもべダビデにこう言え。『万軍の主はこう言われる。わたしはあなたを、羊の群れを追う牧場から取り、わが民イスラエルの君主とした。'),
('JPN', '历代志上', 13, 17, 8, 'そして、あなたがどこに行っても、あなたとともにいて、あなたの前であなたのすべての敵を絶ち滅ぼした。わたしは地の大いなる者たちの名に等しい名を、あなたに与えてきた。'),
('JPN', '历代志上', 13, 17, 9, 'わが民イスラエルのために、わたしは一つの場所を定め、民を住まわせてきた。それは、民がそこに住み、もはや恐れおののくことのないように、不正な者たちも、初めのころのように、重ねて民を抑圧することのないようにするためであった。'),
('JPN', '历代志上', 13, 17, 10, 'それは、わたしが、わが民イスラエルの上にさばきつかさを任命して以来のことである。こうして、わたしはあなたのすべての敵を屈服させたのである。今、わたしはあなたに告げる。主があなたのために一つの家を建てる、と。'),
('JPN', '历代志上', 13, 17, 11, 'あなたの日数が満ち、あなたが先祖のもとに行くとき、わたしはあなたの息子の中から、あなたの後に世継ぎの子を起こし、彼の王国を確立させる。'),
('JPN', '历代志上', 13, 17, 12, '彼はわたしのために一つの家を建て、わたしは彼の王座をとこしえまでも堅く立てる。'),
('JPN', '历代志上', 13, 17, 13, 'わたしは彼の父となり、彼はわたしの子となる。わたしの恵みを、わたしはあなたより前にいた者から取り去ったが、彼からはそのように取り去ることはしない。'),
('JPN', '历代志上', 13, 17, 14, 'わたしは、わたしの家とわたしの王国の中に、彼をとこしえまでも立たせる。彼の王座はとこしえまでも堅く立つ。』」'),
('JPN', '历代志上', 13, 17, 15, 'ナタンはこれらすべてのことばを、この幻のすべてを、そのままダビデに告げた。'),
('JPN', '历代志上', 13, 17, 16, 'ダビデ王は主の前に出て、座して言った。「神、主よ、私は何者でしょうか。私の家はいったい何なのでしょうか。あなたが私をここまで導いてくださったとは。'),
('JPN', '历代志上', 13, 17, 17, '神よ。このことがあなたの御目には小さなことでしたのに、あなたはこのしもべの家について、はるか先のことまで告げてくださいました。神、主よ、あなたは私をすぐれた者として見てくださいます。'),
('JPN', '历代志上', 13, 17, 18, 'あなたのしもべに与えられた誉れについて、ダビデはこの上、何を加えて、あなたに申し上げることができるでしょうか。あなたはこのしもべをよくご存じです。'),
('JPN', '历代志上', 13, 17, 19, '主よ。あなたはこのしもべのために、そしてみこころのままに、この大いなることのすべてを行い、この大いなることをすべて知らせてくださいました。'),
('JPN', '历代志上', 13, 17, 20, '主よ。私たちが耳にするすべてにおいて、あなたのような方はほかになく、あなたのほかに神はいません。'),
('JPN', '历代志上', 13, 17, 21, 'また、地上のどの国民があなたの民イスラエルのようでしょうか。神ご自身が行かれて、ご自分の民として贖い、大いなる恐るべきみわざによってご自分の名を置き、エジプトから贖い出したあなたの民の前から異邦の民を追い払われたのです。'),
('JPN', '历代志上', 13, 17, 22, 'そして、あなたの民イスラエルを、とこしえまでもあなたの民とされました。主よ、あなたは彼らの神となられました。'),
('JPN', '历代志上', 13, 17, 23, '今、主よ。あなたが、このしもべとその家についてお語りになったことばを、とこしえまでも真実なものとし、お語りになったとおりに行ってください。'),
('JPN', '历代志上', 13, 17, 24, 'こうして、あなたの御名がとこしえまでも真実で、大いなるものとなり、『イスラエルの神、万軍の主は、イスラエルの神である』と言われますように。あなたのしもべダビデの家が、御前に堅く立ちますように。'),
('JPN', '历代志上', 13, 17, 25, 'わが神よ。あなたはこのしもべの耳を開き、しもべのために一つの家を建てると告げられました。それゆえ、このしもべは御前で祈る勇気を得たのです。'),
('JPN', '历代志上', 13, 17, 26, '今、主よ、あなたこそ神です。あなたはこのしもべに、この良いことを約束してくださいました。'),
('JPN', '历代志上', 13, 17, 27, '今、あなたは、あなたのしもべの家を祝福することを良しとされ、御前にとこしえに続くようにしてくださいました。主よ。あなたが祝福してくださいました。あなたのしもべの家はとこしえに祝福されています。」'),
('JPN', '历代志上', 13, 18, 1, 'その後のことである。ダビデはペリシテ人を討って、これを屈服させ、ガテとそれに属する町々をペリシテ人の手から奪い取った。'),
('JPN', '历代志上', 13, 18, 2, '彼はまたモアブを討った。モアブはダビデのしもべとなり、貢ぎ物を納める者となった。'),
('JPN', '历代志上', 13, 18, 3, 'ツォバの王ハダドエゼルが、ユーフラテス川流域にその勢力を確立しようとして出て行ったとき、ダビデはハマテに出て、彼を討った。'),
('JPN', '历代志上', 13, 18, 4, 'ダビデは、彼から戦車一千、騎兵七千、歩兵二万を取った。ダビデは、そのすべての戦車の馬の足の筋を切った。ただし、そのうち戦車百台分の馬は残した。'),
('JPN', '历代志上', 13, 18, 5, 'ダマスコのアラムがツォバの王ハダドエゼルを助けに来たが、ダビデはアラムの二万二千人を討った。'),
('JPN', '历代志上', 13, 18, 6, 'ダビデはダマスコのアラムに守備隊を置いた。アラムはダビデのしもべとなり、貢ぎ物を納める者となった。主は、ダビデの行く先々で、彼に勝利を与えられた。'),
('JPN', '历代志上', 13, 18, 7, 'ダビデは、ハダドエゼルの家来たちが持っていた金の丸い小盾を奪い取り、エルサレムに持ち帰った。'),
('JPN', '历代志上', 13, 18, 8, 'またダビデは、ハダドエゼルの町ティブハテとクンから、非常に多くの青銅を奪い取った。これを用いて、ソロモンは、青銅の「海」や柱、および青銅の器を作った。'),
('JPN', '历代志上', 13, 18, 9, 'ハマテの王トウは、ダビデがツォバの王ハダドエゼルの全軍勢を打ち破ったことを聞いた。'),
('JPN', '历代志上', 13, 18, 10, '彼は、息子ハドラムをダビデ王のもとに遣わし、安否を尋ね、ダビデがハダドエゼルと戦ってこれを打ち破ったことについて、祝福のことばを述べた。ハダドエゼルがトウにしばしば戦いを挑んでいたからである。トウは、金、銀、青銅の、あらゆる器を贈り物とした。'),
('JPN', '历代志上', 13, 18, 11, 'ダビデ王は、それらもまた、彼がすべての異邦の民、すなわちエドム、モアブ、アンモン人、ペリシテ人、アマレクのもとから運んで来た銀や金とともに、主のために聖別した。'),
('JPN', '历代志上', 13, 18, 12, 'また、ツェルヤの子アビシャイは、塩の谷でエドム人一万八千人を討って、'),
('JPN', '历代志上', 13, 18, 13, 'エドムに守備隊を置いた。こうして、全エドムはダビデのしもべとなった。主は、ダビデの行く先々で、彼に勝利を与えられた。'),
('JPN', '历代志上', 13, 18, 14, 'ダビデは全イスラエルを治め、その民のすべてにさばきと正義を行った。'),
('JPN', '历代志上', 13, 18, 15, 'ツェルヤの子ヨアブは軍団長、アヒルデの子ヨシャファテは史官、'),
('JPN', '历代志上', 13, 18, 16, 'アヒトブの子ツァドクとエブヤタルの子アビメレクは祭司、シャウシャは書記、'),
('JPN', '历代志上', 13, 18, 17, 'エホヤダの子ベナヤはクレタ人とペレテ人の上に立つ者、ダビデの息子たちは王の側近であった。'),
('JPN', '历代志上', 13, 19, 1, 'この後、アンモン人の王ナハシュが死に、その子が代わって王となった。'),
('JPN', '历代志上', 13, 19, 2, 'ダビデは、「ナハシュの子ハヌンに真実を尽くそう。彼の父は私に真実を尽くしてくれたのだから」と言った。そして彼の父の悔やみを言うために、ダビデは使者を送った。ダビデの家来たちがハヌンに悔やみを言うため、アンモン人の地に着いたとき、'),
('JPN', '历代志上', 13, 19, 3, 'アンモン人の首長たちは、ハヌンに言った。「ダビデがあなたのもとにお悔やみの使者を遣わしたからといって、彼が父君を敬っているとお考えですか。彼の家来たちは、この地を調べ、くつがえし、探るために来たのではないでしょうか。」'),
('JPN', '历代志上', 13, 19, 4, 'そこでハヌンはダビデの家来たちを捕らえ、ひげを剃り落とし、衣を半分に切って腰のあたりまでにして送り返した。'),
('JPN', '历代志上', 13, 19, 5, '人々が来て、ダビデにこの人たちのことを告げたので、ダビデは彼らを迎えに人を遣わした。この人たちが非常に恥じていたからである。王は言った。「ひげが伸びるまでエリコにとどまり、それから帰って来なさい。」'),
('JPN', '历代志上', 13, 19, 6, 'アンモン人は、自分たちがダビデの憎しみを買ったのを見てとった。そこでハヌンとアンモン人は、銀千タラントを送って、アラム・ナハライム、アラム・マアカ、ツォバから戦車と騎兵を雇った。'),
('JPN', '历代志上', 13, 19, 7, '彼らは、戦車三万二千台、マアカの王とその兵たちを雇った。彼らは来て、メデバの前に陣を敷いた。アンモン人は彼らの町々から集まり、戦いに臨んだ。'),
('JPN', '历代志上', 13, 19, 8, 'ダビデはこれを聞き、ヨアブと勇士たちの全軍を送った。'),
('JPN', '历代志上', 13, 19, 9, 'アンモン人は出て来て、町の入り口で戦いの備えをした。ともに来た王たちは、彼らだけで野にいた。'),
('JPN', '历代志上', 13, 19, 10, 'ヨアブは、自分の前とうしろに戦いの前線があるのを見て、イスラエルの精鋭全員からさらに兵を選び、アラム人に立ち向かう陣備えをし、'),
('JPN', '历代志上', 13, 19, 11, '残りの兵を兄弟アビシャイの手に託して、アンモン人に立ち向かう陣備えをした。'),
('JPN', '历代志上', 13, 19, 12, 'ヨアブは言った。「もしアラム人が私より強かったら、あなたが私を救ってくれ。もしアンモン人があなたより強かったら、私があなたを救おう。'),
('JPN', '历代志上', 13, 19, 13, '強くあれ。われわれの民のため、われわれの神の町々のために、奮い立とう。主が、御目にかなうことをされるのだ。」'),
('JPN', '历代志上', 13, 19, 14, 'ヨアブと彼とともにいた兵たちが、戦おうとしてアラム人の前方に近づいたとき、アラム人は彼の前から逃げた。'),
('JPN', '历代志上', 13, 19, 15, 'アンモン人はアラム人が逃げるのを見ると、彼らもヨアブの兄弟アビシャイの前から逃げて町に入った。そこでヨアブはエルサレムに帰った。'),
('JPN', '历代志上', 13, 19, 16, 'アラム人は、自分たちがイスラエルに打ち負かされたのを見て、使者を遣わして、ユーフラテス川の向こうのアラム人に出て来させた。ハダドエゼルの軍の長ショファクが彼らを率いていた。'),
('JPN', '历代志上', 13, 19, 17, 'このことが報告されると、ダビデはイスラエル全軍を集結させ、ヨルダン川を渡って彼らの方に進み、戦いの備えをした。ダビデはアラム人と対決する陣備えをした。アラム人は彼と戦った。'),
('JPN', '历代志上', 13, 19, 18, 'アラム人はイスラエルの前から逃げた。ダビデはアラムの戦車兵七千と歩兵四万を殺し、軍の長ショファクも殺した。'),
('JPN', '历代志上', 13, 19, 19, 'ハダドエゼルに仕えていた者たちは、彼らがイスラエルに打ち負かされたのを見て、ダビデと和を講じ、彼に仕えるようになった。アラム人は再びアンモン人を助けようとはしなかった。'),
('JPN', '历代志上', 13, 20, 1, '年が改まり、王たちが出陣する時期になった。ヨアブは軍勢を率いてアンモン人の地を打ち滅ぼし、ラバに来てこれを包囲した。しかしダビデはエルサレムにとどまっていた。ヨアブはラバを討って、これを破壊した。'),
('JPN', '历代志上', 13, 20, 2, 'ダビデは、彼らの王の冠をその頭から奪い取った。それは金一タラントの重さがあり、宝石がはめ込まれていた。その冠はダビデの頭に置かれた。彼は、その町から非常に多くの分捕り物を持ち去った。'),
('JPN', '历代志上', 13, 20, 3, '彼はそこの人々を連れ出して、石のこぎりや、鉄のつるはし、斧を使う労働に就かせた。ダビデはアンモン人のすべての町に対して、いつもこのようにしていた。ダビデとすべての兵はエルサレムに帰った。'),
('JPN', '历代志上', 13, 20, 4, 'その後のこと、ゲゼルでペリシテ人との戦いが起こった。そのとき、フシャ人シベカイはレファイムの子孫の一人シパイを打ち殺した。こうして、ペリシテ人は征服された。'),
('JPN', '历代志上', 13, 20, 5, '再びペリシテ人との戦いがあったとき、ヤイルの子エルハナンは、ガテ人ゴリヤテの兄弟ラフミを打ち殺した。ラフミの槍の柄は、機織りの巻き棒のようであった。'),
('JPN', '历代志上', 13, 20, 6, '再びガテで戦いがあったとき、そこに、指が六本ずつ、二十四本ある背の高い男がいた。彼もラファの子孫であった。'),
('JPN', '历代志上', 13, 20, 7, '彼はイスラエルをそしったが、ダビデの兄弟シムアの子ヨナタンが彼を打ち殺した。'),
('JPN', '历代志上', 13, 20, 8, 'これらはガテのラファの子孫で、ダビデとその家来たちの手にかかって倒れた。'),
('JPN', '历代志上', 13, 21, 1, 'さて、サタンがイスラエルに向かって立ち上がり、イスラエルの人口を数えるように、ダビデをそそのかした。'),
('JPN', '历代志上', 13, 21, 2, 'ダビデはヨアブと民の長たちに言った。「さあ、ベエル・シェバからダンに至るまでのイスラエルを数え、私に報告しなさい。その人数を私が知るためだ。」'),
('JPN', '历代志上', 13, 21, 3, 'ヨアブは言った。「主が、御民を百倍にも増やしてくださいますように。わが主、王よ。彼らはみな、わが主のもの、そのしもべではないでしょうか。なぜわが主は、このようなことをお求めになるのですか。なぜイスラエルに罪過をもたらされるのですか。」'),
('JPN', '历代志上', 13, 21, 4, 'しかし、ヨアブへの王のことばは激しかった。ヨアブは出て行き、イスラエル中を行き巡り、エルサレムに帰って来た。'),
('JPN', '历代志上', 13, 21, 5, 'ヨアブは民の登録人数をダビデに報告した。全イスラエルには剣を使う者が百十万人、ユダには剣を使う者が四十七万人いた。'),
('JPN', '历代志上', 13, 21, 6, 'しかし、ヨアブはレビとベニヤミンをその中に登録しなかった。王の命令を忌み嫌ったからである。'),
('JPN', '历代志上', 13, 21, 7, 'この命令は神の目に悪しきことであった。神はイスラエルを打たれた。'),
('JPN', '历代志上', 13, 21, 8, 'ダビデは神に言った。「私は、このようなことをして、大きな罪を犯しました。どうか、このしもべの咎を取り去ってください。私は本当に愚かなことをしました。」'),
('JPN', '历代志上', 13, 21, 9, '主はダビデの先見者ガドに告げられた。'),
('JPN', '历代志上', 13, 21, 10, '「行ってダビデに告げよ。『主はこう言われる。わたしがあなたに示す三つのことがある。そのうちの一つを選べ。わたしはあなたに対してそれを行う。』」'),
('JPN', '历代志上', 13, 21, 11, 'ガドはダビデのもとに行き、彼に言った。「主はこう言われる。『どれかを受け入れよ。'),
('JPN', '历代志上', 13, 21, 12, '三年間の飢饉か。三か月間、あなたが敵の前で攻めたてられ、敵の剣があなたに追い迫ることか。三日間、主の剣、疫病がこの地に及び、主の使いがイスラエルの国中を荒らすことか。』今、私を遣わされた方に何と答えたらよいかを決めなさい。」'),
('JPN', '历代志上', 13, 21, 13, 'ダビデはガドに言った。「それは私には非常に辛いことです。私を主の手に陥らせてください。主のあわれみは深いからです。私が人の手には陥らないようにしてください。」'),
('JPN', '历代志上', 13, 21, 14, '主はイスラエルに疫病を下されたので、イスラエルのうち七万人が倒れた。'),
('JPN', '历代志上', 13, 21, 15, '神はエルサレムを滅ぼそうと、御使いを遣わされた。主は御使いが滅ぼしているのを見て、わざわいを下すことを思い直し、滅ぼす御使いに言われた。「もう十分だ。手を引け。」主の使いは、エブス人オルナンの打ち場の傍らに立っていた。'),
('JPN', '历代志上', 13, 21, 16, 'ダビデが目を上げると、主の使いが地と天の間に立ち、抜き身の剣を手に持って、エルサレムの上に伸ばしているのを見た。ダビデと長老たちは粗布で身をおおい、ひれ伏した。'),
('JPN', '历代志上', 13, 21, 17, 'ダビデは神に言った。「民を数えよと命じたのは私ではありませんか。罪があるのはこの私です。私が悪を行ったのです。この羊の群れがいったい何をしたというのでしょう。わが神、主よ。どうか、あなたの御手が、私と私の父の家に下りますように。あなたの民を疫病に渡さないでください。」'),
('JPN', '历代志上', 13, 21, 18, 'そこで、主の使いは、ダビデにこう伝えるようガドに言った。「ダビデは上って行って、エブス人オルナンの打ち場に、主の祭壇を築かなければならない。」'),
('JPN', '历代志上', 13, 21, 19, 'ダビデは、ガドが主の御名によって語ったことばにしたがって上って行った。'),
('JPN', '历代志上', 13, 21, 20, 'オルナンが振り返ると御使いが見えた。彼とともにいた四人の息子たちは身を隠したが、オルナンは小麦の打穀をしていた。'),
('JPN', '历代志上', 13, 21, 21, 'ダビデがオルナンのもとに行くと、オルナンはそれを見てダビデに気づき、打ち場から出て来て、地にひれ伏して礼をした。'),
('JPN', '历代志上', 13, 21, 22, 'ダビデはオルナンに言った。「この打ち場の地所を私に譲っていただきたい。そこに主のために祭壇を建てたい。十分な金額で、それを私に譲っていただきたい。そうすれば民への主の罰は終わるだろう。」'),
('JPN', '历代志上', 13, 21, 23, 'オルナンはダビデに言った。「わが主、王よ。どうぞ受け取って、お気に召すようになさってください。ご覧ください。全焼のささげ物のための牛、薪にできる打穀機、穀物のささげ物のための小麦も差し上げます。すべて差し上げます。」'),
('JPN', '历代志上', 13, 21, 24, 'ダビデ王はオルナンに言った。「いや、私はどうしても十分な金額で買いたい。あなたのものを主に献げるわけにはいかない。費用もかけずに全焼のささげ物を献げたくないのだ。」'),
('JPN', '历代志上', 13, 21, 25, 'そしてダビデは、その地所の代金として、金の重さで六百シェケルをオルナンに支払った。'),
('JPN', '历代志上', 13, 21, 26, 'ダビデは、そこに主のために祭壇を築き、全焼のささげ物と交わりのいけにえを献げ、主を呼んだ。主は、全焼のささげ物の祭壇の上に天から火を下し、彼に答えられた。'),
('JPN', '历代志上', 13, 21, 27, '主が御使いに命じられたので、御使いは剣をさやに収めた。'),
('JPN', '历代志上', 13, 21, 28, 'そのとき、ダビデは主がエブス人オルナンの打ち場で彼に答えられたのを見て、そこでいけにえを献げた。'),
('JPN', '历代志上', 13, 21, 29, 'モーセが荒野で造った主の幕屋と全焼のささげ物の祭壇は、そのときギブオンの高き所にあった。'),
('JPN', '历代志上', 13, 21, 30, 'しかしダビデは、神を求めてその前に出て行くことができなかった。主の使いの剣におびえたからである。'),
('JPN', '历代志上', 13, 22, 1, 'そこで、ダビデは言った。「これこそ神である主の宮だ。これこそイスラエルの全焼のささげ物の祭壇だ。」'),
('JPN', '历代志上', 13, 22, 2, 'ダビデは命じて、イスラエルの地にいる寄留者を召集し、神の宮を建てるため、石材を切り出す石切り工を任命した。'),
('JPN', '历代志上', 13, 22, 3, 'ダビデは、門の扉の釘や留め金用の鉄を大量に用意し、青銅も量りきれないほど多く用意した。'),
('JPN', '历代志上', 13, 22, 4, '杉材も数えきれないほど用意した。シドン人とツロ人が、大量の杉材をダビデのもとに運んで来たからである。'),
('JPN', '历代志上', 13, 22, 5, 'ダビデは言った。「わが子ソロモンは、まだ若く力もない。主のために建てる宮は、壮大なもので、全地で名声と栄誉を高めるものでなければならない。それゆえ、私が用意をしておく。」こうして、ダビデは彼が死ぬ前に多くの用意をしておいた。'),
('JPN', '历代志上', 13, 22, 6, 'ダビデはその子ソロモンを呼び、イスラエルの神、主のために宮を建てるように命じた。'),
('JPN', '历代志上', 13, 22, 7, 'ダビデはソロモンに言った。「わが子よ。私は、わが神、主の御名のために宮を建てる志を持ち続けてきた。'),
('JPN', '历代志上', 13, 22, 8, 'しかし、私に次のような主のことばがあった。『あなたは多くの血を流し、大きな戦いをしてきた。あなたがわたしの名のために家を建ててはならない。わたしの前に多くの血を地に流してきたからである。'),
('JPN', '历代志上', 13, 22, 9, '見よ、あなたに一人の男の子が生まれる。彼は穏やかな人となり、わたしは周りのすべての敵から守って彼に安息を与える。彼の名がソロモンと呼ばれるのはそのためである。彼の世に、わたしはイスラエルに平和と平穏を与える。'),
('JPN', '历代志上', 13, 22, 10, '彼がわたしの名のために家を建てる。彼はわたしの子となり、わたしは彼の父となる。わたしは彼の王座をイスラエルの上にとこしえに堅く立てる。』'),
('JPN', '历代志上', 13, 22, 11, 'そこで、わが子よ、主があなたとともにおられ、主があなたについて語られたとおり、あなたが、あなたの神、主の宮を立派に建て上げることができるように。'),
('JPN', '历代志上', 13, 22, 12, 'ただ、どうか主があなたに思慮と悟りを与えて、あなたをイスラエルの上に任命し、あなたの神、主の律法を守らせてくださるように。'),
('JPN', '历代志上', 13, 22, 13, '主がイスラエルのためにモーセに命じられた掟と定めをあなたが守り行うなら、あなたは栄える。強くあれ。雄々しくあれ。恐れてはならない。おののいてはならない。'),
('JPN', '历代志上', 13, 22, 14, '見なさい。私は困難な中で主の宮のために、金十万タラント、銀百万タラントを用意した。また、青銅と鉄はあまりに多くて量りきれない。それに、木材と石材も用意した。あなたは、これらにもっと加えなさい。'),
('JPN', '历代志上', 13, 22, 15, 'あなたのもとには、石を切り出す者、石や木に細工する者、各種の仕事に熟練した者など、多くの仕事をする者がいて、'),
('JPN', '历代志上', 13, 22, 16, '金、銀、青銅、鉄を扱うが、その人数は数えきれない。立ち上がって、実行しなさい。主があなたとともにいてくださるように。」'),
('JPN', '历代志上', 13, 22, 17, 'また、ダビデはイスラエルのすべての長たちに、その子ソロモンを助けるように命じた。'),
('JPN', '历代志上', 13, 22, 18, '「あなたがたの神、主は、あなたがたとともにおられ、周囲の者からあなたがたを守って安息を与えられたではないか。実に、主はこの地の住民を私の手に渡され、この地は主の前とその民の前に服した。'),
('JPN', '历代志上', 13, 22, 19, '今、あなたがたは心とたましいを傾けて、あなたがたの神、主を求めよ。立ち上がって、神である主の聖所を建て上げ、主の御名のために建てられる宮に、主の契約の箱と神の聖なる用具を運び入れよ。」'),
('JPN', '历代志上', 13, 23, 1, 'ダビデは日を重ねて年老い、その子ソロモンをイスラエルの王とした。'),
('JPN', '历代志上', 13, 23, 2, '彼はまた、イスラエルのすべての長たち、祭司、レビ人を集めた。'),
('JPN', '历代志上', 13, 23, 3, 'レビ人のうち、三十歳以上の者を数えたところ、その男子の頭数は三万八千人であった。'),
('JPN', '历代志上', 13, 23, 4, '「そのうち、主の宮の務めを指揮する者は二万四千人、つかさとさばき人は六千人、'),
('JPN', '历代志上', 13, 23, 5, '四千人は門衛となり、四千人は私が賛美するために作った楽器を手にして、主を賛美する者となりなさい。」'),
('JPN', '历代志上', 13, 23, 6, 'ダビデは彼らを組に分けた。レビ族を、ゲルション、ケハテ、メラリに分け、'),
('JPN', '历代志上', 13, 23, 7, 'ゲルション人をラダンとシムイに分けた。'),
('JPN', '历代志上', 13, 23, 8, 'ラダンの子は、そのかしらエヒエル、ゼタム、ヨエルの三人。'),
('JPN', '历代志上', 13, 23, 9, 'シムイの子は、シェロミテ、ハジエル、ハランの三人。これらはラダンの一族のかしらであった。'),
('JPN', '历代志上', 13, 23, 10, 'シムイの子はまた、ヤハテ、ジザ、エウシュ、ベリア。これらの四人はシムイの子であった。'),
('JPN', '历代志上', 13, 23, 11, 'ヤハテはそのかしら、ジザはその次であった。エウシュとベリアは子を多く持たなかった。そこで父の家にいて、一つの役に就いた。'),
('JPN', '历代志上', 13, 23, 12, 'ケハテの子は、アムラム、イツハル、ヘブロン、ウジエルの四人。'),
('JPN', '历代志上', 13, 23, 13, 'アムラムの子は、アロンとモーセ。アロンは、最も聖なるものを聖別するのに選り分けられた。それは、彼とその子たちが、とこしえに主の前に香をたき、主に仕え、とこしえに主の御名によって祝福するためである。'),
('JPN', '历代志上', 13, 23, 14, '神の人モーセの子孫は、レビ部族の者として名を呼ばれた。'),
('JPN', '历代志上', 13, 23, 15, 'モーセの子は、ゲルショムとエリエゼル。'),
('JPN', '历代志上', 13, 23, 16, 'ゲルショムの子は、かしらがシェブエル。'),
('JPN', '历代志上', 13, 23, 17, 'エリエゼルの子は、かしらがレハブヤ。エリエゼルにはほかに息子がいなかったが、レハブヤの子は非常に多かった。'),
('JPN', '历代志上', 13, 23, 18, 'イツハルの子は、かしらがシェロミテ。'),
('JPN', '历代志上', 13, 23, 19, 'ヘブロンの子は、かしらがエリヤ、次にアマルヤ、第三はヤハジエル、第四はエカムアム。'),
('JPN', '历代志上', 13, 23, 20, 'ウジエルの子は、かしらがミカ、次はイシヤ。'),
('JPN', '历代志上', 13, 23, 21, 'メラリの子は、マフリとムシ。マフリの子は、エルアザルとキシュ。'),
('JPN', '历代志上', 13, 23, 22, 'エルアザルは死に、彼には息子がなく娘だけであったので、親族であるキシュの子らが彼女たちを妻に迎えた。'),
('JPN', '历代志上', 13, 23, 23, 'ムシの子は、マフリ、エデル、エレモテの三人。'),
('JPN', '历代志上', 13, 23, 24, 'これは、それぞれ父祖の家に属するレビ族で二十歳以上になり、主の宮の奉仕の仕事をした者であり、一人ひとり名を数えられ、登録された一族のかしらたちであった。'),
('JPN', '历代志上', 13, 23, 25, 'ダビデがこう言ったからである。「イスラエルの神、主は、御民に安息を与え、とこしえまでもエルサレムに住まわれる。'),
('JPN', '历代志上', 13, 23, 26, 'レビ人も、幕屋を運んだり、奉仕に用いるすべての器具を運んだりする必要はない。」'),
('JPN', '历代志上', 13, 23, 27, 'これらが、ダビデの最後のことばにしたがって数えられた二十歳以上のレビ人の数である。'),
('JPN', '历代志上', 13, 23, 28, '彼らの役目は、主の宮に仕えるアロンの子らを、庭、脇部屋、すべての聖なるものに関わるきよめ、また、神の宮での奉仕のわざをもって助けることである。'),
('JPN', '历代志上', 13, 23, 29, 'また、彼らは、並べ供えるパン、穀物のささげ物の小麦粉、種なしの薄焼きパン、平鍋、混ぜ合わせたもの、また各種の量や大きさを計ること、'),
('JPN', '历代志上', 13, 23, 30, '朝ごとに、立って主をほめたたえ、賛美し、夕べにも同様にすること、'),
('JPN', '历代志上', 13, 23, 31, '安息日、新月の祭り、および例祭ごとに、主に献げられるすべての全焼のささげ物が、主の前に絶えず、定められた数で献げられることについても責任を負う。'),
('JPN', '历代志上', 13, 23, 32, '彼らは、主の宮の奉仕に関して、会見の天幕の任務、聖所の任務、同族アロンの子らの任務に当たった。'),
('JPN', '历代志上', 13, 24, 1, 'アロンの子らの組分け。アロンの息子は、ナダブ、アビフ、エルアザル、イタマル。'),
('JPN', '历代志上', 13, 24, 2, 'ナダブとアビフは父に先立って死に、彼らには子がいなかったので、エルアザルとイタマルが祭司の務めに就いた。'),
('JPN', '历代志上', 13, 24, 3, 'ダビデは、エルアザルの子孫の一人ツァドク、およびイタマルの子孫の一人アヒメレクと協力して、アロンの子らをそれぞれの奉仕に任命し、それぞれの組に分けた。'),
('JPN', '历代志上', 13, 24, 4, 'エルアザルの子孫のほうが、イタマルの子孫よりも一族のかしらが多かったので、エルアザルの子孫は、父祖の家のかしらごとに十六組に、イタマルの子孫は、父祖の家ごとに八組に分けられた。'),
('JPN', '历代志上', 13, 24, 5, '彼らはみな同じようにくじを引いて、それぞれの組に分かれた。聖所の組の長たち、神の組の長たちは、エルアザルの子孫の中にも、イタマルの子孫の中にもいたからである。'),
('JPN', '历代志上', 13, 24, 6, 'レビ人の出である書記、ネタンエルの子シェマヤが、王と首長たち、祭司ツァドク、エブヤタルの子アヒメレク、祭司とレビ人の一族のかしらたちの前で、それらを書き記した。エルアザルから一つの父祖の家が選ばれると、イタマルからも一つ選ばれた。'),
('JPN', '历代志上', 13, 24, 7, '第一のくじは、エホヤリブに当たった。第二はエダヤに、'),
('JPN', '历代志上', 13, 24, 8, '第三はハリムに、第四はセオリムに、'),
('JPN', '历代志上', 13, 24, 9, '第五はマルキヤに、第六はミヤミンに、'),
('JPN', '历代志上', 13, 24, 10, '第七はハ・コツに、第八はアビヤに、'),
('JPN', '历代志上', 13, 24, 11, '第九はヨシュアに、第十はシェカンヤに、'),
('JPN', '历代志上', 13, 24, 12, '第十一はエルヤシブに、第十二はヤキムに、'),
('JPN', '历代志上', 13, 24, 13, '第十三はフパに、第十四はエシェブアブに、'),
('JPN', '历代志上', 13, 24, 14, '第十五はビルガに、第十六はイメルに、'),
('JPN', '历代志上', 13, 24, 15, '第十七はヘジルに、第十八はハ・ピツェツに、'),
('JPN', '历代志上', 13, 24, 16, '第十九はペタフヤに、第二十はエヘズケルに、'),
('JPN', '历代志上', 13, 24, 17, '第二十一はヤキンに、第二十二はガムルに、'),
('JPN', '历代志上', 13, 24, 18, '第二十三はデラヤに、第二十四はマアズヤに当たった。'),
('JPN', '历代志上', 13, 24, 19, 'これらが主の宮に入って奉仕するために登録された者たちで、彼らの先祖アロンが、イスラエルの神、主の命令にしたがって定めたとおりである。'),
('JPN', '历代志上', 13, 24, 20, '残りのレビ族については、次のとおりである。アムラムの子孫ではシュバエル。シュバエルの子ではエフデヤ。'),
('JPN', '历代志上', 13, 24, 21, 'レハブヤについて。レハブヤの子では、そのかしらイシヤ。'),
('JPN', '历代志上', 13, 24, 22, 'イツハル人では、シェロミテ。シェロミテの子ではヤハテ。'),
('JPN', '历代志上', 13, 24, 23, 'ヘブロンの子は、そのかしらがエリヤ、第二はアマルヤ、第三はヤハジエル、第四はエカムアム。'),
('JPN', '历代志上', 13, 24, 24, 'ウジエルの子孫はミカ。ミカの子ではシャミル。'),
('JPN', '历代志上', 13, 24, 25, 'ミカの兄弟はイシヤ。イシヤの子ではゼカリヤ。'),
('JPN', '历代志上', 13, 24, 26, 'メラリの子はマフリとムシ。彼の子ヤアジヤの子孫、'),
('JPN', '历代志上', 13, 24, 27, 'すなわち、メラリの子孫で、彼の子ヤアジヤから出た者は、ショハム、ザクル、イブリ。'),
('JPN', '历代志上', 13, 24, 28, 'マフリからは、エルアザル。彼には子がいなかった。'),
('JPN', '历代志上', 13, 24, 29, 'キシュからは、キシュの子孫のエラフメエル。'),
('JPN', '历代志上', 13, 24, 30, 'ムシの子は、マフリ、エデル、エリモテ。これが、それぞれその父祖の家に属するレビの子孫である。'),
('JPN', '历代志上', 13, 24, 31, '彼らもまた、彼らの同族であるアロンの子らと全く同じように、ダビデ王、ツァドク、アヒメレク、祭司とレビ人の一族のかしらたちの前で、くじを引いた。一族では、かしらもその弟と全く同じであった。'),
('JPN', '历代志上', 13, 25, 1, 'また、ダビデと軍の長たちは、アサフとヘマンとエドトンの子らを奉仕のために取り分け、竪琴と琴とシンバルに合わせて預言する者とした。仕事に就いた者の数は、その奉仕にしたがって次のとおりである。'),
('JPN', '历代志上', 13, 25, 2, 'アサフの子では、ザクル、ヨセフ、ネタンヤ、アサルエラ。これらはアサフの子で、王の指揮にしたがって預言するアサフの指揮下にあった。'),
('JPN', '历代志上', 13, 25, 3, 'エドトンについて。エドトンの子は、ゲダルヤ、ツェリ、エシャヤ、シムイ、ハシャブヤ、マティテヤの六人。竪琴に合わせて主をほめたたえ、賛美しながら預言する彼らの父エドトンの指揮下にあった。'),
('JPN', '历代志上', 13, 25, 4, 'ヘマンについて。ヘマンの子は、ブキヤ、マタンヤ、ウジエル、シェブエル、エリモテ、ハナンヤ、ハナニ、エリアタ、ギダルティ、ロマムティ・エゼル、ヨシュベカシャ、マロティ、ホティル、マハジオテ。'),
('JPN', '历代志上', 13, 25, 5, 'これらはみな、王の先見者ヘマンの子で、神のことばを通して王の角を高く上げる者たちであった。神はヘマンに息子十四人と娘三人を与えられた。'),
('JPN', '历代志上', 13, 25, 6, 'これらはみな、その父の指揮下にあって、シンバル、琴、竪琴を手に、主の宮で歌を歌い、王の指揮下に神の宮の奉仕に当たる者たちである。アサフ、エドトン、ヘマン、'),
('JPN', '历代志上', 13, 25, 7, '彼ら、および、主にささげる歌の訓練を受け、みな達人であった彼らの同族の数は二百八十八人であった。'),
('JPN', '历代志上', 13, 25, 8, '彼らは、下の者も上の者も、達人も弟子も、みな同じように任務のためのくじを引いた。'),
('JPN', '历代志上', 13, 25, 9, '第一のくじは、アサフに属するヨセフに当たり、第二はゲダルヤに当たった。彼と兄弟たち、子たち、十二人。'),
('JPN', '历代志上', 13, 25, 10, '第三はザクル、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 11, '第四はイツェリ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 12, '第五はネタンヤ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 13, '第六はブキヤ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 14, '第七はエサルエラ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 15, '第八はエシャヤ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 16, '第九はマタンヤ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 17, '第十はシムイ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 18, '第十一はアザルエル、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 19, '第十二はハシャブヤ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 20, '第十三はシュバエル、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 21, '第十四はマティテヤ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 22, '第十五はエレモテ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 23, '第十六はハナンヤ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 24, '第十七はヨシュベカシャ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 25, '第十八はハナニ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 26, '第十九はマロティ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 27, '第二十はエリアタ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 28, '第二十一はホティル、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 29, '第二十二はギダルティ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 30, '第二十三はマハジオテ、その子たち、兄弟たち、十二人。'),
('JPN', '历代志上', 13, 25, 31, '第二十四はロマムティ・エゼル、その子たち、兄弟たち、十二人に当たった。'),
('JPN', '历代志上', 13, 26, 1, '門衛の組分けについて。コラ人ではアサフ族のコレの子メシェレムヤ。'),
('JPN', '历代志上', 13, 26, 2, 'メシェレムヤには子があった。長男ゼカリヤ、次男エディアエル、三男ゼバデヤ、四男ヤテニエル、'),
('JPN', '历代志上', 13, 26, 3, '五男エラム、六男ヨハナン、七男エルエホエナイ。'),
('JPN', '历代志上', 13, 26, 4, 'オベデ・エドムには子があった。長男シェマヤ、次男エホザバデ、三男ヨアフ、四男サカル、五男ネタンエル、'),
('JPN', '历代志上', 13, 26, 5, '六男アンミエル、七男イッサカル、八男ペウレタイ。神が彼を祝福されたからである。'),
('JPN', '历代志上', 13, 26, 6, '彼の子シェマヤに子どもたちが生まれた。彼らは勇士だったので、その父の家を治める者となった。'),
('JPN', '历代志上', 13, 26, 7, 'シェマヤの子は、オテニ、レファエル、オベデ、エルザバデ、エルザバデの兄弟で勇者の、エリフとセマクヤ。'),
('JPN', '历代志上', 13, 26, 8, 'これらはみな、オベデ・エドムの子で、彼らとその子、兄弟たちは、その奉仕にふさわしい力のある勇敢な人であった。オベデ・エドムに属する者は六十二人であった。'),
('JPN', '历代志上', 13, 26, 9, 'メシェレムヤには子どもと兄弟たちがあった。彼らは勇者で、十八人であった。'),
('JPN', '历代志上', 13, 26, 10, 'メラリ族のホサには子があった。そのかしらはシムリであった。彼は長男ではなかったが、父が彼をかしらにしたのである。'),
('JPN', '历代志上', 13, 26, 11, '第二はヒルキヤ、第三はテバルヤ、第四はゼカリヤであった。ホサの子ども、兄弟たちは合計十三人であった。'),
('JPN', '历代志上', 13, 26, 12, '門衛のこれらの各組に対し、主の宮で仕える任務が、彼らのかしらごとに、彼らの兄弟たちと全く同じように割り当てられた。'),
('JPN', '历代志上', 13, 26, 13, 'こうして彼らは、下の者も上の者も等しく、その父祖の家ごとに、一つ一つの門についてくじを引いた。'),
('JPN', '历代志上', 13, 26, 14, '東方のくじはシェレムヤに当たった。彼の子で思慮深い助言者ゼカリヤのためにくじが引かれ、彼のくじは北方と出た。'),
('JPN', '历代志上', 13, 26, 15, 'オベデ・エドムには南方、彼の子らには倉、'),
('JPN', '历代志上', 13, 26, 16, 'シュピムとホサには西方、それに上り坂の大路のシャレケテ門が当たった。見張りの組と組とは並び合っていた。'),
('JPN', '历代志上', 13, 26, 17, '東方には六人のレビ人、北方には毎日四人、南方には毎日四人、倉には二人ずつ、'),
('JPN', '历代志上', 13, 26, 18, '西方の前庭には、大路に四人、前庭に二人であった。'),
('JPN', '历代志上', 13, 26, 19, '以上が、コラ族とメラリ族の門衛の組分けである。'),
('JPN', '历代志上', 13, 26, 20, 'レビ人のアヒヤは、神の宮の宝物倉および聖なるささげ物の宝物倉を管理した。'),
('JPN', '历代志上', 13, 26, 21, 'ゲルション族でラダンに属するラダンの子ら、ゲルション人ラダンに属する一族のかしらたち、すなわちエヒエル人、'),
('JPN', '历代志上', 13, 26, 22, 'エヒエル人の子孫、その兄弟ゼタムとヨエルは、主の宮の宝物倉を管理した。'),
('JPN', '历代志上', 13, 26, 23, 'アムラム人、イツハル人、ヘブロン人、ウジエル人については、'),
('JPN', '历代志上', 13, 26, 24, 'モーセの子ゲルショムの子シェブエルが宝物倉のつかさであった。'),
('JPN', '历代志上', 13, 26, 25, '彼の同族で、エリエゼルに属する者は、その子レハブヤ、その子エシャヤ、その子ヨラム、その子ジクリ、その子シェロミテであるが、'),
('JPN', '历代志上', 13, 26, 26, 'このシェロミテと彼の兄弟たちは、ダビデ王と一族のかしらたち、および、千人隊の長、百人隊の長たち、軍の長たちが聖別して献げた聖なるささげ物の、すべての宝物倉を管理した。'),
('JPN', '历代志上', 13, 26, 27, '彼らは、戦いで得た分捕り物の一部を、主の宮を修理するために聖別した。'),
('JPN', '历代志上', 13, 26, 28, 'すべて予見者サムエル、キシュの子サウル、ネルの子アブネル、ツェルヤの子ヨアブが聖別した物、すなわち、すべての聖なるささげ物は、シェロミテとその兄弟たちに委ねられた。'),
('JPN', '历代志上', 13, 26, 29, 'イツハル人のうち、ケナンヤとその子たちは、イスラエルに関する外の仕事に就き、つかさやさばき人となった。'),
('JPN', '历代志上', 13, 26, 30, 'ヘブロン人のうち、ハシャブヤとその同族の者、すなわち勇者千七百人は、ヨルダン川より西のイスラエルの管理に当たり、主に対する務めと王に対する奉仕のすべてを担った。'),
('JPN', '历代志上', 13, 26, 31, 'ヘブロン人のうち、エリヤは、その一族とその家系によればヘブロン人のかしらであった。ダビデの治世の第四十年に、彼らは調べられ、ギルアデのヤゼルで彼らの中に勇士たちが見つかった。'),
('JPN', '历代志上', 13, 26, 32, '彼の同族の者たちは勇者であって、二千七百人いたが、一族のかしらたちであった。ダビデ王は彼らを、ルベン人、ガド人、マナセ人の半部族の上に任命し、すべて神に関わる事柄、王に関わる事柄に当たらせた。'),
('JPN', '历代志上', 13, 27, 1, 'イスラエルの子ら、すなわち、一族のかしらたち、千人隊の長、百人隊の長たち、および彼らのつかさたちは王に仕え、一年のすべての月を通して、月ごとの交代制により各分団のすべてのことに当たった。その人数は一つの分団が二万四千人であった。'),
('JPN', '历代志上', 13, 27, 2, '第一の月、第一分団を率いるのは、ザブディエルの子ヤショブアム。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 3, '彼はペレツの子孫の一人で、第一の月を受け持つ軍の長たちすべてのかしらであった。'),
('JPN', '历代志上', 13, 27, 4, '第二の月、分団を率いるのは、アホアハ人ドダイ。彼の分団には、長であるミクロテがいた。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 5, '第三の月、第三軍団の長は祭司エホヤダの子ベナヤ。彼がかしらであった。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 6, '彼は、あの三十人の勇士の一人、三十人の長のベナヤである。彼の分団には、その子アミザバデがいた。'),
('JPN', '历代志上', 13, 27, 7, '第四の月、第四団は、ヨアブの兄弟アサエル。その子ゼバデヤが彼の跡を継いだ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 8, '第五の月、第五団は、長はイズラフ人シャムフテ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 9, '第六の月、第六団は、テコア人イケシュの子イラ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 10, '第七の月、第七団は、エフライム族の出であるペロニ人ヘレツ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 11, '第八の月、第八団は、ゼラフ人に属するフシャ人シベカイ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 12, '第九の月、第九団は、ベニヤミン人に属するアナトテ人アビエゼル。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 13, '第十の月、第十団は、ゼラフ人に属するネトファ人マフライ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 14, '第十一の月、第十一団は、エフライム族の出であるピルアトン人ベナヤ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 15, '第十二の月、第十二団は、オテニエルに属するネトファ人ヘルダイ。彼の分団は二万四千人。'),
('JPN', '历代志上', 13, 27, 16, 'なお、イスラエルの各部族の長は、ルベン人では、ジクリの子エリエゼルが長。シメオン人ではマアカの子シェファテヤ。'),
('JPN', '历代志上', 13, 27, 17, 'レビではケムエルの子ハシャブヤ。アロンではツァドク。'),
('JPN', '历代志上', 13, 27, 18, 'ユダではダビデの兄弟の一人エリフ。イッサカルではミカエルの子オムリ。'),
('JPN', '历代志上', 13, 27, 19, 'ゼブルンではオバデヤの子イシュマヤ。ナフタリではアズリエルの子エリモテ。'),
('JPN', '历代志上', 13, 27, 20, 'エフライム族ではアザズヤの子ホセア。マナセの半部族ではペダヤの子ヨエル。'),
('JPN', '历代志上', 13, 27, 21, 'ギルアデのマナセの半部族ではゼカリヤの子イド。ベニヤミンではアブネルの子ヤアシエル。'),
('JPN', '历代志上', 13, 27, 22, 'ダンではエロハムの子アザルエル。これらがイスラエル各部族の長たちであった。'),
('JPN', '历代志上', 13, 27, 23, 'ダビデは二十歳以下の者は数に入れなかった。主がイスラエルを天の星のように多くすると言われたからである。'),
('JPN', '历代志上', 13, 27, 24, 'ツェルヤの子ヨアブが数え始めたが、終わらなかった。しかし、このことで御怒りがイスラエルの上に下った。それでその数はダビデ王の年代記の統計には載らなかった。'),
('JPN', '历代志上', 13, 27, 25, '王の宝物倉をつかさどったのは、アディエルの子アズマウェテ。畑地、町々、村々、それぞれの塔にある宝物倉を管理したのは、ウジヤの子ヨナタン。'),
('JPN', '历代志上', 13, 27, 26, '土地を耕して畑仕事をする者たちを管理したのは、ケルブの子エズリ。'),
('JPN', '历代志上', 13, 27, 27, 'ぶどう畑を管理したのは、ラマ人シムイ。酒蔵用のぶどう畑の産物を管理したのは、シェファム人ザブディ。'),
('JPN', '历代志上', 13, 27, 28, 'シェフェラにあるオリーブの木といちじく桑の木を管理したのは、ゲデル人バアル・ハナン。油の倉を管理したのはヨアシュ。'),
('JPN', '历代志上', 13, 27, 29, 'シャロンで飼われる牛の群れを管理したのは、シャロン人シルタイ。谷にいる牛の群れを管理したのは、アデライの子シャファテ。'),
('JPN', '历代志上', 13, 27, 30, 'らくだを管理したのは、イシュマエル人オビル。雌ろばを管理したのは、メロノテ人エフデヤ。'),
('JPN', '历代志上', 13, 27, 31, '羊の群れを管理したのは、ハガル人ヤジズ。これらはみな、ダビデ王の所有する財産の長官であった。'),
('JPN', '历代志上', 13, 27, 32, 'ダビデのおじヨナタンは助言者であり、洞察力のある人で、彼は書記でもあった。ハクモニの子エヒエルは王の子らとともにいた。'),
('JPN', '历代志上', 13, 27, 33, 'アヒトフェルは王の助言者で、アルキ人フシャイは王の友であった。'),
('JPN', '历代志上', 13, 27, 34, 'アヒトフェルの跡を継いだのは、ベナヤの子エホヤダとエブヤタル。王の軍の長はヨアブであった。'),
('JPN', '历代志上', 13, 28, 1, 'ダビデは、イスラエルのすべての長、すなわち、各部族の長、王に仕える各組の長、千人隊の長、百人隊の長、王とその子たちの全財産と家畜の担当者の長、宦官、有力者、およびすべての勇士たちをエルサレムに召集した。'),
('JPN', '历代志上', 13, 28, 2, 'ダビデ王は立ち上がって、こう言った。「私の兄弟たち、私の民よ。私の言うことを聞きなさい。私は主の契約の箱のため、私たちの神の足台のために安息の家を建てる志を持ち、建築の用意をしてきた。'),
('JPN', '历代志上', 13, 28, 3, 'しかし、神は私に仰せられた。『あなたはわたしの名のために家を建ててはならない。あなたは戦いの人であり、人の血を流してきたからである。』'),
('JPN', '历代志上', 13, 28, 4, 'イスラエルの神、主は、私の父の全家から私を選び、とこしえにイスラエルを治める王としてくださった。主はユダの中から君たる者を選び、ユダの家の中で私の父の家を、父の子たちの中で私を喜びとし、全イスラエルを治める王としてくださった。'),
('JPN', '历代志上', 13, 28, 5, '主は私に多くの子を授けてくださったが、私のすべての子どもの中から、私の子ソロモンを選び、イスラエルを治める主の王座に就けてくださった。'),
('JPN', '历代志上', 13, 28, 6, 'そして、私にこう言われた。『あなたの子ソロモンが、わたしの家とわたしの庭を造る。わたしが彼をわたしの子として選び、わたしが彼の父となるからだ。'),
('JPN', '历代志上', 13, 28, 7, 'もし彼が、今日のように、わたしの命令と定めを行おうと固く決心しているなら、わたしは彼の王国をとこしえまでも確立しよう。』'),
('JPN', '历代志上', 13, 28, 8, '今、主の会衆である全イスラエルの前で、私たちの神が聞いておられるこの場所で言う。あなたがたは、自分たちの神、主の命令をすべて守り、求めなさい。それは、あなたがたがこの良い地を所有し、あなたがたの後、とこしえまでもあなたがたの子孫に受け継がせるためである。'),
('JPN', '历代志上', 13, 28, 9, 'わが子ソロモンよ。あなたの父の神を知り、全き心と喜びの気持ちをもって神に仕えなさい。主はすべての心を探り、すべての思いの動機を読み取られるからである。もし、あなたが神を求めるなら、神はあなたにご自分を現される。もし、あなたが神を離れるなら、神はあなたをとこしえまでも退けられる。'),
('JPN', '历代志上', 13, 28, 10, '今、心に留めなさい。主は聖所となる宮を建てるために、あなたを選ばれた。勇気を出して実行しなさい。」'),
('JPN', '历代志上', 13, 28, 11, 'ダビデはその子ソロモンに、玄関広間、神殿、宝物室、屋上の間、内部屋、贖いの間などの設計図を授けた。'),
('JPN', '历代志上', 13, 28, 12, '設計図は、すべて御霊によって彼に示された。すなわち、主の宮の庭のこと、周囲のすべての脇部屋のこと、神の宮の宝物倉のこと、聖なるささげ物の宝物倉のこと、'),
('JPN', '历代志上', 13, 28, 13, '祭司とレビ人の組分けのこと、主の宮の奉仕のすべての仕事のこと、主の宮の奉仕に用いるすべての用具のことである。'),
('JPN', '历代志上', 13, 28, 14, '金については、各種の奉仕に用いるすべての器具に使う金の重さが、すべての銀の器具については、各種の奉仕に用いるすべての器具の重さが示され、'),
('JPN', '历代志上', 13, 28, 15, '金の燭台とその上にある金のともしび皿の重さは、一つ一つの燭台とその上にあるともしび皿の重さが、銀の燭台については、一つ一つの燭台の用途別に燭台とその上にあるともしび皿の重さが示されていた。'),
('JPN', '历代志上', 13, 28, 16, '並べ供えるパンの机の金の重さは、一つ一つの机ごとに、銀の机に用いる銀の重さとともに示されていた。'),
('JPN', '历代志上', 13, 28, 17, '肉刺し、鉢、壺は純金であるが、金の杯については、それぞれの杯の重さ、銀の杯についても、それぞれの杯の重さ、'),
('JPN', '历代志上', 13, 28, 18, '香をたく祭壇については、精錬された金の重さが示されていた。また、翼を広げて主の契約の箱をおおう金のケルビムの車の設計図も示されていた。'),
('JPN', '历代志上', 13, 28, 19, '「これらすべては、私の上に臨んだ主の手によって書き物になっていて、仕事の全貌が理解できるはずだ。」'),
('JPN', '历代志上', 13, 28, 20, 'それから、ダビデはその子ソロモンに言った。「強く、雄々しく、事を成し遂げなさい。恐れてはならない。おののいてはならない。神である主、私の神が、あなたとともにいてくださるのだから。主は、あなたを見放さず、あなたを見捨てず、主の宮の奉仕に関わるすべての仕事を完成させてくださる。'),
('JPN', '历代志上', 13, 28, 21, '見よ。神の宮のあらゆる奉仕のために祭司とレビ人の各組がいる。どんな仕事でも、あらゆる奉仕のために知恵をもって進んで事に当たる者がみな、あなたとともにいる。首長たちとすべての民は、あなたの命令すべてに従う。」'),
('JPN', '历代志上', 13, 29, 1, 'ダビデ王は全会衆に言った。「わが子ソロモンは、神が選ばれた、ただ一人の者であるが、まだ若く力もない。しかしこの工事は大きい。なぜなら、この宮は人のためではなく、神である主のためのものだからである。'),
('JPN', '历代志上', 13, 29, 2, '私は全力を尽くして、私の神の宮のために準備をしてきた。すなわち、金製品のための金、銀製品のための銀、青銅製品のための青銅、鉄製品のための鉄、木製品のための木、縞めのう、色とりどりの象眼細工用の石、あらゆる宝石、大理石などを大量に準備した。'),
('JPN', '历代志上', 13, 29, 3, 'そのうえ、私は、私の神の宮に対する喜びとして、聖なる宮のために準備したすべてのものに加えて、自分の宝としていた金銀を、私の神の宮のために献げる。'),
('JPN', '历代志上', 13, 29, 4, '建物の壁をおおうため、オフィルの金の中から金三千タラントと、精錬された銀七千タラント、'),
('JPN', '历代志上', 13, 29, 5, '金製品のための金、銀製品のための銀、あらゆる職人の手仕事のためのものを献げる。今日、自ら進んで、その手にあふれるほど主に献げる者はいないか。」'),
('JPN', '历代志上', 13, 29, 6, 'すると、一族の長たち、イスラエル各部族の長たち、千人隊と百人隊の長たち、さらに王家の執務の長たちは、自ら進んで、'),
('JPN', '历代志上', 13, 29, 7, '神の宮の奉仕のために、金五千タラント一万ダリク、銀一万タラント、青銅一万八千タラント、鉄十万タラントを献げた。'),
('JPN', '历代志上', 13, 29, 8, '宝石を持っている者は、これをゲルション人エヒエルの手に託して主の宮の宝物倉に献げた。'),
('JPN', '历代志上', 13, 29, 9, '民は、長たちが自ら進んで献げたことを喜んだ。彼らが全き心をもって、自ら進んで主に献げたからである。ダビデ王も大いに喜んだ。'),
('JPN', '历代志上', 13, 29, 10, 'ダビデは全会衆の前で主をほめたたえた。ダビデは言った。「私たちの父イスラエルの神、主よ。あなたがとこしえからとこしえまで、ほめたたえられますように。'),
('JPN', '历代志上', 13, 29, 11, '主よ、偉大さ、力、輝き、栄光、威厳は、あなたのものです。天にあるものも地にあるものもすべて。主よ、王国もあなたのものです。あなたは、すべてのものの上に、かしらとしてあがめられるべき方です。'),
('JPN', '历代志上', 13, 29, 12, '富と誉れは御前から出ます。あなたはすべてのものを支配しておられます。あなたの御手には勢いと力があり、あなたの御手によって、すべてのものが偉大にされ、力づけられるのです。'),
('JPN', '历代志上', 13, 29, 13, '私たちの神よ。今、私たちはあなたに感謝し、あなたの栄えに満ちた御名をほめたたえます。'),
('JPN', '历代志上', 13, 29, 14, 'このように自ら進んで献げる力を持っているとしても、私は何者なのでしょう、私の民は何者なのでしょう。すべてはあなたから出たのであり、私たちは御手から出たものをあなたに献げたにすぎません。'),
('JPN', '历代志上', 13, 29, 15, '私たちは、父祖たちがみなそうであったように、あなたの前では寄留者であり、居留している者です。地上での私たちの日々は影のようなもので、望みもありません。'),
('JPN', '历代志上', 13, 29, 16, '私たちの神、主よ。あなたの聖なる御名のために宮を建てようと私たちが準備したこの多くのものすべては、あなたの御手から出たものであり、すべてはあなたのものです。'),
('JPN', '历代志上', 13, 29, 17, 'わが神よ。あなたは心を試される方で、真っ直ぐなことを愛されるのを私はよく知っています。私は直ぐな心で、これらすべてを自ら進んで献げました。また今、ここにいるあなたの民が、自ら進んであなたに献げるのを、私は喜びのうちに見ました。'),
('JPN', '历代志上', 13, 29, 18, '私たちの父祖アブラハム、イサク、イスラエルの神、主よ。御民が心にめぐらす思いをとこしえに守り、彼らの心をしっかりとあなたに向けさせてください。'),
('JPN', '历代志上', 13, 29, 19, 'わが子ソロモンに全き心を与え、あなたの命令とさとしと掟を守らせて、すべてを行わせ、私が準備してきた宮を建てさせてください。」'),
('JPN', '历代志上', 13, 29, 20, 'そして、ダビデは全会衆に「あなたがたの神、主をほめたたえよ」と言った。すると全会衆は、父祖の神、主をほめたたえ、主と王の前に身をかがめてひれ伏した。'),
('JPN', '历代志上', 13, 29, 21, 'その翌日、彼らは主にいけにえを献げ、主に全焼のささげ物を献げた。雄牛千頭、雄羊千匹、子羊千匹、これらに添える注ぎのぶどう酒、また全イスラエルのための多くのいけにえを献げた。'),
('JPN', '历代志上', 13, 29, 22, 'その日、彼らは大いに喜んで、主の前で食べたり飲んだりし、改めてダビデの子ソロモンを王とし、主の前で油を注いで君主とした。また、ツァドクを祭司とした。'),
('JPN', '历代志上', 13, 29, 23, 'こうしてソロモンは主の王座に就き、父ダビデに代わって王となった。彼は栄え、全イスラエルは彼に聞き従った。'),
('JPN', '历代志上', 13, 29, 24, 'すべての首長たち、勇士たち、そしてダビデ王のすべての息子たちも、ソロモン王に忠誠を誓った。'),
('JPN', '历代志上', 13, 29, 25, '主はソロモンを全イスラエルの目の前に非常に大いなる者とし、彼より前にイスラエルを治めたどの王にも見られなかった王の威厳を、彼に与えられた。'),
('JPN', '历代志上', 13, 29, 26, 'このようにして、エッサイの子ダビデは全イスラエルを治めたのである。'),
('JPN', '历代志上', 13, 29, 27, '彼がイスラエルの王であった期間は四十年であった。ヘブロンで七年治め、エルサレムで三十三年治めた。'),
('JPN', '历代志上', 13, 29, 28, '彼は幸せな晩年を過ごし、齢も富も誉れも満ち足りて死んだ。彼の子ソロモンが代わって王となった。'),
('JPN', '历代志上', 13, 29, 29, 'ダビデ王についての事柄は、最初から最後まで、『予見者サムエルの働き』、『預言者ナタンの働き』、『先見者ガドの働き』にまさしく記されている。'),
('JPN', '历代志上', 13, 29, 30, 'そこには、彼の統治のすべてとその功績、また、彼とイスラエル、および諸国のすべての王国の上に過ぎていった時代についても記されている。'),
('JPN', '历代志下', 14, 1, 1, 'ダビデの子ソロモンは王権を確立した。彼の神、主がともにおられ、彼を並外れて偉大な者とされた。'),
('JPN', '历代志下', 14, 1, 2, 'ソロモンは全イスラエル、千人隊、百人隊の長、さばき人、および一族のかしらである全イスラエルの族長すべてに向かって語り、'),
('JPN', '历代志下', 14, 1, 3, 'ソロモンおよび彼とともにいた全会衆は、ギブオンにある高き所に行った。そこに、主のしもべモーセが荒野で造った神の会見の天幕があったからである。'),
('JPN', '历代志下', 14, 1, 4, 'しかし、神の箱については、ダビデがこれをキルヤテ・エアリムから、ダビデがそのために定めた場所に運び上げていた。箱のための天幕をエルサレムに張っていたのである。'),
('JPN', '历代志下', 14, 1, 5, 'ギブオンの主の幕屋の前には、フルの子であるウリの子ベツァルエルが造った青銅の祭壇があった。ソロモンと会衆はそこで主を求めた。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '历代志下', 14, 1, 6, 'ソロモンは、そこに、すなわち会見の天幕におられる主の前にある青銅の祭壇に上り、その上で千匹の全焼のささげ物を献げた。'),
('JPN', '历代志下', 14, 1, 7, 'その夜、神はソロモンに現れて仰せられた。「あなたに何を与えようか。願え。」'),
('JPN', '历代志下', 14, 1, 8, 'ソロモンは神に言った。「あなたは、私の父ダビデに大いなる恵みを施されました。そして、父に代わって私を王とされました。'),
('JPN', '历代志下', 14, 1, 9, '神、主よ、今、私の父ダビデになさったあなたの約束を堅く守ってください。あなたは、地のちりのように数の多い民の上に、私を王とされたからです。'),
('JPN', '历代志下', 14, 1, 10, '今、知恵と知識を私に授けてください。そうすれば、私はこの民の前に出入りいたします。さもなければ、だれに、この大いなるあなたの民をさばくことができるでしょうか。」'),
('JPN', '历代志下', 14, 1, 11, '神はソロモンに仰せられた。「そのようなことがあなたの心にあり、富も、財も、名誉も、あなたを憎む者たちのいのちさえ願わず、また長寿も願わず、むしろ、わたしがあなたをその王として立てたわたしの民をさばくための知恵と知識を願ったので、'),
('JPN', '历代志下', 14, 1, 12, 'その知恵と知識があなたに授けられる。またわたしは、あなたの前の王にも後の王にもないほどの富と財宝と誉れをあなたに与える。」'),
('JPN', '历代志下', 14, 1, 13, 'こうして、ソロモンはギブオンにある高き所から出て行き、会見の天幕の前を去ってエルサレムに行き、イスラエルの王となった。'),
('JPN', '历代志下', 14, 1, 14, 'ソロモンは戦車と騎兵を集め、戦車千四百台と騎兵一万二千人を所有した。彼はこれらを戦車の町々、およびエルサレムの王のもとに配置した。'),
('JPN', '历代志下', 14, 1, 15, '王はエルサレムで銀と金を石のように用い、杉の木をシェフェラのいちじく桑の木のように大量に用いた。'),
('JPN', '历代志下', 14, 1, 16, 'ソロモンが所有していた馬は、エジプトとクエから輸入されたもので、王の商人たちが、クエから代価を払って手に入れたものであった。'),
('JPN', '历代志下', 14, 1, 17, '彼らはエジプトから戦車を銀六百、馬を銀百五十で買い上げて、輸入した。同様に、ヒッタイト人のすべての王やアラムの王たちにも、王の商人たちの仲買で輸出された。'),
('JPN', '历代志下', 14, 2, 1, 'ソロモンは、主の御名のための宮と自分の王国のための宮殿を建てることを命じた。'),
('JPN', '历代志下', 14, 2, 2, 'ソロモンは、荷を担ぐ者七万人、山で石を切り出す者八万人、彼らを指揮する者三千六百人をそろえた。'),
('JPN', '历代志下', 14, 2, 3, '彼はツロの王ヒラムのもとに人を遣わして言った。「あなたが私の父ダビデに対し、父の住む家を建てるための杉材を送ってくださったように、私にもしていただけないでしょうか。'),
('JPN', '历代志下', 14, 2, 4, 'ご覧ください。私は、私の神、主の御名のために宮を建ててこれを主に聖別し、その御前に香りの高い香をたき、常にパンを供え、朝ごと夕ごと、安息日と新月の祭りに、また私たちの神、主の例祭に、全焼のささげ物を献げようとしています。このことは、とこしえにイスラエルに命じられているのです。'),
('JPN', '历代志下', 14, 2, 5, '私が建てようとしている宮は壮大なものです。私たちの神は、すべての神々にまさって大いなる神だからです。'),
('JPN', '历代志下', 14, 2, 6, 'しかし、だれが主のために宮を建てる力を持っているというのでしょう。天も、天の天も主をお入れできないのです。主のために宮を建てようとする私は何者でしょう。ただ主の前に香をたく者にすぎません。'),
('JPN', '历代志下', 14, 2, 7, 'そこで今、私のもとに、金、銀、青銅、鉄の細工、および紫織物、紅織物、青織物の製造に熟練した人で、各種の彫り物の技術を心得ている人を送ってください。父ダビデが備え、私のもとにいるユダとエルサレムの熟練した者たちも一緒に働きます。'),
('JPN', '历代志下', 14, 2, 8, 'また、レバノンから杉、もみ、白檀の木材を私のもとに送ってください。あなたの家来たちがレバノンの木を切ることに熟練していることを知っております。もちろん、私の家来たちも、あなたの家来たちと一緒に働きます。'),
('JPN', '历代志下', 14, 2, 9, '私のために、木材を多量に用意させるためです。私の建てる宮は壮大であり、すばらしいものだからです。'),
('JPN', '历代志下', 14, 2, 10, 'それで私は、材木を切り出す者、木を切る者たちのため、あなたのしもべたちのために、砕いた小麦二万コル、大麦二万コル、ぶどう酒二万バテ、油二万バテを提供します。」'),
('JPN', '历代志下', 14, 2, 11, 'ツロの王ヒラムは文書を送ってソロモンに答えた。「主はご自分の民を愛しておられるので、あなたを彼らの上に立てて王とされました。」'),
('JPN', '历代志下', 14, 2, 12, 'またヒラムは言った。「天と地を造られたイスラエルの神、主がほめたたえられますように。主はダビデ王に知恵のある子を与え、思慮と悟りを授けて、主のための宮と、自分の王国のための宮殿を建てさせられます。'),
('JPN', '历代志下', 14, 2, 13, '今、私は判断力に恵まれた熟練工、職人の長フラムを遣わします。'),
('JPN', '历代志下', 14, 2, 14, '彼は、ダンの子孫の女を母とし、ツロの人を父としていて、金、銀、青銅、鉄、石材、木材の細工、および紫織物、青織物、亜麻布、紅織物の製造を心得、委ねられればどのような彫り物も、どのような設計も行うことができる人物です。彼は、あなたの熟練工たち、私の主でありあなたの父であるダビデの熟練工たちとともに働きます。'),
('JPN', '历代志下', 14, 2, 15, '今、私の主が語られた小麦と大麦、油とぶどう酒を、しもべどもにお送りください。'),
('JPN', '历代志下', 14, 2, 16, '私たちのほうでは、お入り用なだけレバノンから木材を切り、これをいかだに組んで、海路ヤッファまであなたのもとにお届けします。あなたがこれをエルサレムに運び上げてください。」'),
('JPN', '历代志下', 14, 2, 17, 'ソロモンは、父ダビデが行った人口調査に続いて、イスラエルの地にいる寄留者全員の人数を調べたが、十五万三千六百人であった。'),
('JPN', '历代志下', 14, 2, 18, '彼は、その中から七万人を荷を担ぐ者に、八万人を山で石を切り出す者に、三千六百人を民の労働を指揮する者にした。'),
('JPN', '历代志下', 14, 3, 1, 'ソロモンは、エルサレムのモリヤの山で主の宮の建築を始めた。そこは、主が父ダビデにご自分を現され、ダビデが準備していた場所で、エブス人オルナンの打ち場があったところである。'),
('JPN', '历代志下', 14, 3, 2, 'ソロモンが建築を始めたのは、その治世の第四年、第二の月の二日であった。'),
('JPN', '历代志下', 14, 3, 3, '神の宮を建てるために、ソロモンが据えた礎は次のとおりである。長さは、古い尺度のキュビトによると六十キュビト、幅は二十キュビト。'),
('JPN', '历代志下', 14, 3, 4, '前に付く玄関は、長さが神殿の幅と同じ二十キュビト、高さは百二十キュビトとし、その内側を純金でおおった。'),
('JPN', '历代志下', 14, 3, 5, 'この広間はもみの木の板を張り、良質の金でおおい、さらにその上になつめ椰子の木の彫刻と鎖を置き、'),
('JPN', '历代志下', 14, 3, 6, 'また、この神殿は宝石で美しく飾った。金はパルワイムの金であった。'),
('JPN', '历代志下', 14, 3, 7, 'この神殿の梁も、敷居も、壁も、扉も金でおおい、壁にはケルビムを刻んだ。'),
('JPN', '历代志下', 14, 3, 8, 'またソロモンは至聖所を造った。その長さは神殿の幅と同じ二十キュビト、幅も二十キュビトであり、これを六百タラントの良質の金でおおった。'),
('JPN', '历代志下', 14, 3, 9, '杭の金の重さは五十シェケルであった。その部屋の上部も金でおおった。'),
('JPN', '历代志下', 14, 3, 10, 'ソロモンは至聖所の中に、彫像のケルビムを二つ作り、これに金をかぶせた。'),
('JPN', '历代志下', 14, 3, 11, 'ケルビムの翼は、長さが二十キュビトであった。片方のケルビムの一方の翼は五キュビトで、神殿の壁に届いていて、もう一方の翼も五キュビトで、もう片方のケルビムの翼に届いていた。'),
('JPN', '历代志下', 14, 3, 12, 'もう片方のケルビムの一方の翼も五キュビトで、神殿の壁に届いていて、もう一方の翼も五キュビトで、もう片方のケルビムの翼につながっていた。'),
('JPN', '历代志下', 14, 3, 13, 'これらのケルビムの翼は広げられていて、二十キュビトあった。これらはその足で立ち、その顔は神殿の方に向いていた。'),
('JPN', '历代志下', 14, 3, 14, '彼はまた、青糸、紫糸、緋糸、および亜麻糸で垂れ幕を作り、その上にケルビムの模様を縫い付けた。'),
('JPN', '历代志下', 14, 3, 15, '彼は、神殿の前に柱を二本作った。高さは三十五キュビトで、その頂にある柱頭は五キュビトであった。'),
('JPN', '历代志下', 14, 3, 16, '彼は内殿の鎖を作り、柱の頂に取り付けた。また、ざくろを百個作って、鎖に取り付けた。'),
('JPN', '历代志下', 14, 3, 17, '彼は柱を本殿の前に、一つを右側に、一つを左側に立てた。右側の柱の名をヤキンと呼び、左側の柱の名をボアズと呼んだ。'),
('JPN', '历代志下', 14, 4, 1, '彼はまた、青銅の祭壇を造った。その長さは二十キュビト、幅は二十キュビト、高さは十キュビトであった。'),
('JPN', '历代志下', 14, 4, 2, 'それから、彼は鋳物の「海」を造った。縁から縁まで十キュビトの円形で、高さは五キュビト。周囲は測り縄で巻いて三十キュビトであった。'),
('JPN', '历代志下', 14, 4, 3, 'その下に沿って、牛の像が周囲を取り巻いていた。一キュビトにつき十ずつの割合で「海」の周りを取り巻いていた。この牛は二段になっていて、「海」を鋳たときに鋳込んだものである。'),
('JPN', '历代志下', 14, 4, 4, '「海」は十二頭の牛の上に据えられていた。三頭は北を向き、三頭は西を向き、三頭は南を向き、三頭は東を向いていた。「海」はこれらの牛の上に載せられていて、牛の後部はすべて内側を向いていた。'),
('JPN', '历代志下', 14, 4, 5, '「海」の厚さは一手幅あり、その縁は杯の縁のように、ゆりの花の形をしていた。その容量は三千バテであった。'),
('JPN', '历代志下', 14, 4, 6, '彼はまた、洗うための洗盤を十個造り、五個を右側に、五個を左側に置いた。その中で全焼のささげ物に用いるものがすすぎ清められた。「海」は祭司たちが身を洗うためのものであった。'),
('JPN', '历代志下', 14, 4, 7, 'また、金の燭台十個を規定にしたがって作り、本殿の中に、五個を右側、五個を左側に置いた。'),
('JPN', '历代志下', 14, 4, 8, '机を十個作り、それを本殿の中に、五個を右側、五個を左側に置いた。それから金の鉢を百個作った。'),
('JPN', '历代志下', 14, 4, 9, 'さらに祭司たちの庭と大庭、およびその庭の戸を造り、その戸を青銅でおおった。'),
('JPN', '历代志下', 14, 4, 10, '「海」は右側、すなわち、東南の方角に置いた。'),
('JPN', '历代志下', 14, 4, 11, 'さらに、フラムは灰壺と十能と鉢を作った。こうして、フラムは、ソロモン王のために神の宮でなすべきすべての仕事を完了した。'),
('JPN', '历代志下', 14, 4, 12, 'すなわち、二本の柱と、二本の柱の頂にある丸い柱頭、および柱の頂にある丸い二つの柱頭をおおう二つの格子細工、'),
('JPN', '历代志下', 14, 4, 13, 'また、二つの格子細工に取り付ける四百個のざくろ、すなわち、柱の先端にある丸い二つの柱頭をおおうそれぞれの格子細工のための二段のざくろ、'),
('JPN', '历代志下', 14, 4, 14, 'また、台を作り、その台の上の洗盤を作り、'),
('JPN', '历代志下', 14, 4, 15, '「海」一つと、その下の十二頭の牛、'),
('JPN', '历代志下', 14, 4, 16, '灰壺と十能と肉刺し、およびそれらに属するすべての物を、職人の長フラムがソロモン王のため、主の宮のために、磨き上げた青銅で作った。'),
('JPN', '历代志下', 14, 4, 17, '王は、ヨルダンの低地、スコテとツェレダの間の粘土の地でこれらを鋳造した。'),
('JPN', '历代志下', 14, 4, 18, 'ソロモンはこれらすべての用具を大量に作った。青銅の重さは量られなかった。'),
('JPN', '历代志下', 14, 4, 19, 'また、ソロモンは神の宮にあるあらゆる物を作った。金の祭壇と、臨在のパンを載せる金の机、'),
('JPN', '历代志下', 14, 4, 20, '内殿の前で火をともすための燭台と、その上のともしび皿を、規定にしたがって純金で作った。'),
('JPN', '历代志下', 14, 4, 21, 'また、金の飾り花、ともしび皿、芯切りばさみを作った。それは混じりけのない金であった。'),
('JPN', '历代志下', 14, 4, 22, '芯取りばさみ、鉢、平皿、火皿を純金で作った。神殿の入り口は、至聖所に通じる扉と、神殿の本殿に通じる扉を金で作った。'),
('JPN', '历代志下', 14, 5, 1, 'こうして、ソロモンが主の宮のためにしたすべての工事が完了した。ソロモンは父ダビデが聖別した物、すなわち、銀、金、各種の用具類を運び入れ、神の宮の宝物倉に納めた。'),
('JPN', '历代志下', 14, 5, 2, 'それからソロモンは、イスラエルの長老たち、および、イスラエルの部族のかしらたちと一族の長たちをすべて、エルサレムに召集した。ダビデの町シオンから主の契約の箱を運び上げるためであった。'),
('JPN', '历代志下', 14, 5, 3, 'イスラエルのすべての人々は、第七の新月の祭りに王のもとに集まった。'),
('JPN', '历代志下', 14, 5, 4, 'イスラエルの長老全員が到着すると、レビ人たちは箱を担ぎ、'),
('JPN', '历代志下', 14, 5, 5, '箱と、会見の天幕と、天幕にあったすべての聖なる用具を運び上げた。これらの物を祭司たちとレビ人たちが運び上げた。'),
('JPN', '历代志下', 14, 5, 6, 'ソロモン王と、王のところに集まったイスラエルの全会衆は、箱の前で羊や牛をいけにえとして献げた。その数はあまりにも多く、数えることも調べることもできなかった。'),
('JPN', '历代志下', 14, 5, 7, '祭司たちは、主の契約の箱を、定められた場所、すなわち神殿の内殿である至聖所のケルビムの翼の下に運び入れた。'),
('JPN', '历代志下', 14, 5, 8, 'ケルビムは、箱の一定の場所の上に翼を広げていた。こうしてケルビムは箱とその担ぎ棒を上からおおった。'),
('JPN', '历代志下', 14, 5, 9, 'その担ぎ棒は長かったので、棒の先が内殿の前の聖所からは見えていたが、外からは見えなかった。それは今日までそこにある。'),
('JPN', '历代志下', 14, 5, 10, '箱の中には、二枚の板のほかには何も入っていなかった。これは、イスラエルの子らがエジプトから出て来たとき、主が彼らと契約を結ばれた際に、モーセがホレブで入れたものである。'),
('JPN', '历代志下', 14, 5, 11, '祭司たちが聖所から出て来たときのことである。列席したすべての祭司たちは、務めの組分けにかかわらず自らを聖別していた。'),
('JPN', '历代志下', 14, 5, 12, 'また、歌い手であるレビ人全員、すなわち、アサフ、ヘマン、エドトン、および彼らの子たちや兄弟たちも、亜麻布を身にまとい、シンバル、琴および竪琴を手にして祭壇の東側に立ち、百二十人の祭司たちも彼らとともにラッパを吹き鳴らしていた。'),
('JPN', '历代志下', 14, 5, 13, 'ラッパを吹き鳴らす者たち、歌い手たちが、まるで一人のように一致して歌声を響かせ、主を賛美し、ほめたたえた。そして、ラッパとシンバルと様々な楽器を奏でて声をあげ、「主はまことにいつくしみ深い。その恵みはとこしえまで」と主に向かって賛美した。そのとき、雲がその宮、すなわち主の宮に満ちた。'),
('JPN', '历代志下', 14, 5, 14, '祭司たちは、その雲のために、立って仕えることができなかった。主の栄光が神の宮に満ちたからである。'),
('JPN', '历代志下', 14, 6, 1, 'そのとき、ソロモンは言った。「主は、黒雲の中に住む、と言われました。'),
('JPN', '历代志下', 14, 6, 2, 'そこでこの私は、あなたの御住まいである家を建てました。御座がとこしえに据えられる場所を。」'),
('JPN', '历代志下', 14, 6, 3, 'それから王は振り向いて、イスラエルの全会衆を祝福した。イスラエルの全会衆は起立していた。'),
('JPN', '历代志下', 14, 6, 4, '彼は言った。「イスラエルの神、主がほめたたえられますように。主は御口をもって私の父ダビデに語り、御手をもってこれを成し遂げて、こう言われた。'),
('JPN', '历代志下', 14, 6, 5, '『わたしの民をエジプトの地から導き出した日からこのかた、わたしは、わたしの名を置く家を建てるために、イスラエルの全部族のうちのどの町も選ばず、また、わたしの民イスラエルの上に立つ君主とするために、だれも選ばなかった。'),
('JPN', '历代志下', 14, 6, 6, 'ただ、エルサレムを選んでそこにわたしの名を置き、ダビデを選んでわたしの民イスラエルの上に立てた。』'),
('JPN', '历代志下', 14, 6, 7, 'それで私の父ダビデの心にはいつも、イスラエルの神、主の御名のために家を建てたいという思いがあった。'),
('JPN', '历代志下', 14, 6, 8, 'ところが主は、私の父ダビデにこう言われた。『あなたの心にはいつも、わたしの名のために家を建てたいという思いがあった。その思いがあなたの心にあったことは、良いことである。'),
('JPN', '历代志下', 14, 6, 9, 'しかし、あなたはその家を建ててはならない。あなたの腰から生まれ出るあなたの子が、わたしの名のために家を建てるのだ。』'),
('JPN', '历代志下', 14, 6, 10, '主はお告げになった約束を果たされたので、私は主の約束どおりに父ダビデに代わって立ち、イスラエルの王座に就いた。そしてイスラエルの神、主の御名のためにこの家を建て、'),
('JPN', '历代志下', 14, 6, 11, '主の契約が納められている箱をそこに置いた。その契約は、主が、イスラエルの子らと結ばれたものである。」'),
('JPN', '历代志下', 14, 6, 12, '彼はイスラエルの全会衆の前で、主の祭壇の前に立ち、両手を伸べ広げた。'),
('JPN', '历代志下', 14, 6, 13, 'ソロモンは、長さ五キュビト、幅五キュビト、高さ三キュビトの青銅の足台を作って庭の中央に据えていたので、その上に立った。そしてイスラエルの全会衆の前でひざまずき、天に向かって両手を伸べ広げて、'),
('JPN', '历代志下', 14, 6, 14, 'こう言った。「イスラエルの神、主よ。天にも地にも、あなたのような神はほかにありません。あなたは、心を尽くして御前に歩むあなたのしもべたちに対し、契約と恵みを守られる方です。'),
('JPN', '历代志下', 14, 6, 15, 'あなたは、あなたのしもべ、私の父ダビデに約束されたことを、ダビデのために守ってくださいました。あなたは御口をもって語り、また、今日のように御手をもってこれを成し遂げられました。'),
('JPN', '历代志下', 14, 6, 16, 'そこで今、イスラエルの神、主よ。あなたのしもべ、私の父ダビデに約束されたことを、ダビデのために守ってください。『あなたがわたしの前に歩んだように、あなたの子孫がその道を守り、わたしの律法に歩みさえするなら、あなたには、イスラエルの王座に就く者がわたしの前から断たれることはない』と言われたことを。'),
('JPN', '历代志下', 14, 6, 17, '今、イスラエルの神、主よ。あなたのしもべダビデに約束されたおことばが堅く立てられますように。'),
('JPN', '历代志下', 14, 6, 18, 'それにしても、神は、はたして人間とともに地の上に住まわれるでしょうか。実に、天も、天の天も、あなたをお入れすることはできません。まして私が建てたこの宮など、なおさらのことです。'),
('JPN', '历代志下', 14, 6, 19, 'あなたのしもべの祈りと願いに御顔を向けてください。私の神、主よ。あなたのしもべが御前にささげる叫びと祈りを聞いてください。'),
('JPN', '历代志下', 14, 6, 20, 'そして、この宮、すなわち、あなたの御名をそこに置くと言われたこの場所に、昼も夜も御目を開き、あなたのしもべがこの場所に向かってささげる祈りを聞いてください。'),
('JPN', '历代志下', 14, 6, 21, 'あなたのしもべとあなたの民イスラエルが、この場所に向かってささげる願いを聞いてください。あなたご自身が、あなたの御住まいの場所、天からこれを聞いてください。聞いて、お赦しください。'),
('JPN', '历代志下', 14, 6, 22, 'ある人が隣人に罪を犯して、のろいの誓いを立てるよう求められ、この宮の中にある、あなたの祭壇の前に来て誓うなら、'),
('JPN', '历代志下', 14, 6, 23, 'あなたご自身が天からこれを聞き、あなたのしもべたちにさばきを行って、悪い者にはその生き方への報いをその頭上に返し、正しい者にはその正しさにしたがって義をもって報いてください。'),
('JPN', '历代志下', 14, 6, 24, 'あなたの民イスラエルが、あなたの前に罪ある者となって、敵に打ち負かされたとき、彼らが立ち返り、御名をほめたたえ、この宮で御前に祈り願うなら、'),
('JPN', '历代志下', 14, 6, 25, 'あなたご自身が天からこれを聞き、あなたの民イスラエルの罪を赦し、あなたが彼らとその先祖たちにお与えになった地に、彼らを帰らせてください。'),
('JPN', '历代志下', 14, 6, 26, '彼らがあなたの前に罪ある者となって、天が閉ざされ雨が降らなくなったとき、彼らがこの場所に向かって祈り、御名をほめたたえ、あなたが苦しませたことによって彼らがその罪から立ち返るなら、'),
('JPN', '历代志下', 14, 6, 27, 'あなたご自身が天でこれを聞き、あなたのしもべたち、あなたの民イスラエルの罪を赦してください。彼らの歩むべき良い道を彼らに教え、あなたの民に相続地としてお与えになったあなたの地に雨を降らせてください。'),
('JPN', '历代志下', 14, 6, 28, 'この地に飢饉が起こり、疫病や立ち枯れや黒穂病、いなごやその若虫が発生したときでも、敵がこの地の町々を攻め囲んだときでも、どのようなわざわい、どのような病気であっても、'),
('JPN', '历代志下', 14, 6, 29, 'だれでもあなたの民イスラエルが、それぞれ自分の疫病や痛みを思い知らされて、この宮に向かって両手を伸べ広げて祈るなら、どのような祈り、どのような願いであっても、'),
('JPN', '历代志下', 14, 6, 30, 'あなたご自身が、御座が据えられた場所である天から聞いて、赦し、一人ひとりに、そのすべての生き方にしたがって報いてください。あなたはその心をご存じです。あなただけが、すべての人の子の心をご存じだからです。'),
('JPN', '历代志下', 14, 6, 31, 'そうして、あなたが私たちの先祖にお与えになった大地の上で彼らが生き続ける間、いつもあなたを恐れて、あなたの道に歩むようにしてください。'),
('JPN', '历代志下', 14, 6, 32, '同様に、あなたの民イスラエルの者でない異国人についても、その人があなたの大いなる御名と力強い御手と伸ばされた御腕のゆえに、遠方の地から来てこの宮に向かって祈るなら、'),
('JPN', '历代志下', 14, 6, 33, 'あなたご自身が、あなたの御座が据えられた場所である天からこれを聞き、その異国人があなたに向かって願うことをすべて、かなえてください。そうすれば、地上のあらゆる民が御名を知り、あなたの民イスラエルと同じようにあなたを恐れるようになり、私が建てたこの宮で御名が呼び求められなければならないことを知るでしょう。'),
('JPN', '历代志下', 14, 6, 34, 'あなたの民が敵との戦いのために出て行くとき、遣わされる道で、あなたがお選びになったこの都、私が御名のために建てた宮に向かって、あなたに祈るなら、'),
('JPN', '历代志下', 14, 6, 35, '天から彼らの祈りと願いを聞いて、彼らの言い分を聞き入れてやってください。'),
('JPN', '历代志下', 14, 6, 36, '罪に陥らない人は一人もいません。ですから、彼らがあなたの前に罪ある者となったために、あなたが怒って彼らを敵に渡し、彼らが、遠く、あるいは近くの国に捕虜として捕らわれて行き、'),
('JPN', '历代志下', 14, 6, 37, '捕らわれて行った地で我に返り、その捕囚の地であなたに立ち返ってあわれみを乞い、『私たちは罪ある者です。不義をなし、悪を行いました』と言い、'),
('JPN', '历代志下', 14, 6, 38, '捕らわれて行った捕囚の地で、心のすべて、たましいのすべてをもってあなたに立ち返り、あなたが彼らの先祖にお与えになった彼らの地、あなたがお選びになったこの都、私が御名のために建てたこの宮の方に向かって祈るなら、'),
('JPN', '历代志下', 14, 6, 39, 'あなたの御座が据えられた場所である天から、彼らの祈りと願いを聞き、彼らの訴えをかなえて、あなたの前に罪ある者となったあなたの民を赦してください。'),
('JPN', '历代志下', 14, 6, 40, '今、わが神よ。どうか、この場所でささげる祈りに御目を開き、御耳を傾けてください。'),
('JPN', '历代志下', 14, 6, 41, '今、神、主よ、立ち上がってください。あなたの休み所にお入りください。あなたとあなたの御力の箱も。神、主よ、あなたの祭司たちが救いを身にまとい、あなたにある敬虔な人たちが、いつくしみを喜びますように。'),
('JPN', '历代志下', 14, 6, 42, '神、主よ、あなたに油注がれた者たちの顔を退けないでください。あなたのしもべダビデの誠実な行いの数々を思い起こしてください。」'),
('JPN', '历代志下', 14, 7, 1, 'ソロモンが祈り終えると、天から火が下って来て、全焼のささげ物と数々のいけにえを焼き尽くし、主の栄光がこの宮に満ちた。'),
('JPN', '历代志下', 14, 7, 2, '祭司たちは主の宮に入ることができなかった。主の栄光が主の宮に満ちたからである。'),
('JPN', '历代志下', 14, 7, 3, 'イスラエルのすべての人々は、火が下り、主の栄光がこの宮の上に現れたのを見て、膝をかがめて顔を地面の敷石に付け、伏し拝んで、「主はまことにいつくしみ深い。その恵みはとこしえまで」と主をほめたたえた。'),
('JPN', '历代志下', 14, 7, 4, 'それから、王とすべての民は、主の前にいけにえを献げた。'),
('JPN', '历代志下', 14, 7, 5, 'ソロモン王は牛二万二千頭と羊十二万匹を献げた。こうして、王とすべての民は神の宮を奉献した。'),
('JPN', '历代志下', 14, 7, 6, '祭司たちはその務めにしたがって立ち、レビ人も主の楽器を手にしていた。これはダビデ王が作ったもので、ダビデが彼らの奏楽によって賛美するとき、「主の恵みはとこしえまで」と主をほめたたえるためのものであった。祭司たちは彼らに対面してラッパを吹き鳴らした。全イスラエルは起立していた。'),
('JPN', '历代志下', 14, 7, 7, 'ソロモンは、主の宮の前庭の中央部を聖別し、そこで、全焼のささげ物と、交わりのいけにえの脂肪を献げた。ソロモンが造っておいた青銅の祭壇では、全焼のささげ物と穀物のささげ物と脂肪を受け入れることができなかったからである。'),
('JPN', '历代志下', 14, 7, 8, 'ソロモンはこのとき、ともにいた全イスラエル、すなわち、レボ・ハマテからエジプト川に至るまでの非常に多くの会衆と一緒に、七日間の祭りを行った。'),
('JPN', '历代志下', 14, 7, 9, '彼らは八日目にきよめの集会を開いた。七日間、祭壇の奉献を行い、七日間、祭りを行ったからである。'),
('JPN', '历代志下', 14, 7, 10, '第七の月の二十三日に、彼は民をそれぞれの天幕に帰らせた。彼らは、主がダビデとソロモンとその民イスラエルに下さった恵みを喜び、心満たされていた。'),
('JPN', '历代志下', 14, 7, 11, 'こうしてソロモンは、主の宮と王宮を建て終え、主の宮と自分の宮殿について行おうとしていた、彼の心にあったすべてのことを見事に実現した。'),
('JPN', '历代志下', 14, 7, 12, 'その夜、主はソロモンに現れ、彼に言われた。「わたしはあなたの祈りを聞き、この場所をわたしにいけにえを献げる宮として選んだ。'),
('JPN', '历代志下', 14, 7, 13, 'わたしが天を閉ざして雨が降らなくなったり、あるいはわたしがバッタに命じてこの地を食い尽くさせたりして、わたしがわたしの民に対して疫病を送ったときには、'),
('JPN', '历代志下', 14, 7, 14, 'わたしの名で呼ばれているわたしの民が、自らへりくだり、祈りをささげ、わたしの顔を慕い求めてその悪の道から立ち返るなら、わたしは親しく天から聞いて、彼らの罪を赦し、彼らの地を癒やす。'),
('JPN', '历代志下', 14, 7, 15, '今、わたしはこの場所でささげられる祈りに目を開き、耳を傾ける。'),
('JPN', '历代志下', 14, 7, 16, '今、わたしはこの宮を選んで聖別した。それはとこしえにわたしの名をそこに置くためである。わたしの目とわたしの心は、いつもそこにある。'),
('JPN', '历代志下', 14, 7, 17, 'もしあなたが、あなたの父ダビデが歩んだように、わたしの前に歩み、わたしがあなたに命じたことすべてをそのまま実行し、わたしの掟と定めを守るなら、'),
('JPN', '历代志下', 14, 7, 18, 'わたしが、あなたの父ダビデに『あなたには、イスラエルを支配する人が断たれることはない』と言って契約を結んだとおり、わたしはあなたの王座を確立しよう。'),
('JPN', '历代志下', 14, 7, 19, 'しかし、もしあなたがたが背いて、あなたがたの前に置いたわたしの掟とわたしの命令を捨て去り、行ってほかの神々に仕え、それを拝むなら、'),
('JPN', '历代志下', 14, 7, 20, 'わたしは彼らに与えた地から彼らを根こそぎにし、わたしがわたしの名のために聖別したこの宮をわたしの前から投げ捨て、これをすべての民の間で物笑いの種とし、嘲りの的とする。'),
('JPN', '历代志下', 14, 7, 21, 'かつてはそびえていたこの宮も、そのそばを通り過ぎる者はみな驚き恐れて、『何のために、主はこの地とこの宮に、このような仕打ちをされたのだろう』と言う。'),
('JPN', '历代志下', 14, 7, 22, '人々は、『彼らは、エジプトの地から彼らを導き出した彼らの父祖の神、主を捨ててほかの神々に頼り、それを拝み、それに仕えた。そのため主はこのすべてのわざわいを彼らに下されたのだ』と言う。」'),
('JPN', '历代志下', 14, 8, 1, 'ソロモンが主の宮と自分の宮殿を二十年かけて建て終えたとき、'),
('JPN', '历代志下', 14, 8, 2, 'ソロモンは、ヒラムが彼に返した町々を建て直し、そこにイスラエル人を住まわせた。'),
('JPN', '历代志下', 14, 8, 3, 'ソロモンはハマテ・ツォバに出て行き、これに打ち勝った。'),
('JPN', '历代志下', 14, 8, 4, '彼は荒野にタデモルを建て、倉庫の町々をすべてハマテに建てた。'),
('JPN', '历代志下', 14, 8, 5, '彼はまた、上ベテ・ホロンと下ベテ・ホロンを建てた。これは、城壁と門とかんぬきのある防備の町々であった。'),
('JPN', '历代志下', 14, 8, 6, 'さらにバアラテ、およびソロモンが所有するすべての倉庫の町、戦車のためのすべての町、騎兵のための町々、またソロモンがエルサレム、レバノン、および彼の全領地に建てたいと切に願っていたすべてのものを、彼は建てた。'),
('JPN', '历代志下', 14, 8, 7, 'イスラエルの出ではない、ヒッタイト人、アモリ人、ペリジ人、ヒビ人、エブス人の生き残りの民すべて、'),
('JPN', '历代志下', 14, 8, 8, 'すなわち、この地に残されていた人々、イスラエル人が滅ぼし尽くさなかった人々の子孫に当たる者たちを、ソロモンは苦役に徴用した。今日に至るまで、そうである。'),
('JPN', '历代志下', 14, 8, 9, 'しかし、ソロモンはイスラエル人を自分の労働のための奴隷とはしなかった。彼らは戦士であり、彼の補佐官の長であり、戦車隊や騎兵隊の長だったからである。'),
('JPN', '历代志下', 14, 8, 10, 'ソロモン王には監督をする長が二百五十人いて、彼らは民を指揮していた。'),
('JPN', '历代志下', 14, 8, 11, 'ソロモンはファラオの娘を、ダビデの町から彼女のために建てた家に連れ上った。「私の妻はイスラエルの王ダビデの家に住んではならない。主の箱が入れられたところは聖だからである」と彼が考えたからである。'),
('JPN', '历代志下', 14, 8, 12, 'それからソロモンは、玄関の前に築いた主の祭壇の上に、主のために全焼のささげ物を献げた。'),
('JPN', '历代志下', 14, 8, 13, 'また、モーセの命令どおりに、安息日ごと、新月の祭りごと、年三回の例祭、すなわち、種なしパンの祭り、七週の祭り、仮庵の祭りごとに、日ごとの定めにしたがって献げた。'),
('JPN', '历代志下', 14, 8, 14, '彼は父ダビデの定めにしたがい、祭司たちの組分けを定めてその務めに就かせ、レビ人もその任務に就かせ、日ごとの定めとして、祭司たちの前で賛美と奉仕をさせた。門衛たちも、その組分けにしたがって、それぞれ門に立たせた。神の人ダビデの命令がこうだったからである。'),
('JPN', '历代志下', 14, 8, 15, '彼らは、王がすべてのことにつき、また宝物倉のことについて、祭司たちとレビ人たちに命じたことからそれることはなかった。'),
('JPN', '历代志下', 14, 8, 16, 'ソロモンの工事全体は、主の宮の礎を据える日から完成まで確かに遂行され、主の宮は完成した。'),
('JPN', '历代志下', 14, 8, 17, 'それから、ソロモンはエドムの地の海岸にあるエツヨン・ゲベルとエイラトへ行った。'),
('JPN', '历代志下', 14, 8, 18, 'ヒラムは、自分のしもべたちに託して、船団と海に詳しい水夫たちを彼のもとに送り込んだ。彼らは、ソロモンのしもべたちとともにオフィルへ行き、そこから金四百五十タラントを取って、ソロモン王のもとに運んだ。'),
('JPN', '历代志下', 14, 9, 1, 'ときに、シェバの女王は、ソロモンの名声を聞いたので、難問をもってソロモンを試そうと、非常に大勢の従者を率い、バルサム油と多くの金および宝石をらくだに載せて、エルサレムにやって来た。彼女はソロモンのところに来ると、心にあることをすべて彼に問いかけた。'),
('JPN', '历代志下', 14, 9, 2, 'ソロモンは、彼女のすべての問いに答えた。ソロモンが分からなくて、彼女に答えられなかったことは何一つなかった。'),
('JPN', '历代志下', 14, 9, 3, 'シェバの女王は、ソロモンの知恵と、彼が建てた宮殿と、'),
('JPN', '历代志下', 14, 9, 4, 'その食卓の料理、列席の家来たち、給仕たちの態度とその服装、献酌官たちとその服装、そして主の宮に上る階段を見て、息も止まるばかりであった。'),
('JPN', '历代志下', 14, 9, 5, '彼女は王に言った。「私が国であなたの事績とあなたの知恵について聞き及んでいたことは、本当でした。'),
('JPN', '历代志下', 14, 9, 6, '私は自分で来て、自分の目で見るまでは、彼らの言うことを信じなかったのですが、なんと、私にはあなたの知恵のすばらしさを半分も知らされていなかったのです。あなたは、私が聞いていたうわさを上回る方でした。'),
('JPN', '历代志下', 14, 9, 7, 'なんと幸せなことでしょう。あなたにつく人たちは。なんと幸せなことでしょう。いつもあなたの前に立って、あなたの知恵を聞くことができる、このあなたの家来たちは。'),
('JPN', '历代志下', 14, 9, 8, 'あなたの神、主がほめたたえられますように。主はあなたを喜び、その王座にあなたを就かせ、あなたの神、主のために王とされました。あなたの神はイスラエルを愛して、これをとこしえに確立されたので、あなたを彼らの上に王として与え、公正と正義を行わせるのです。」'),
('JPN', '历代志下', 14, 9, 9, '彼女は百二十タラントの金と、非常に多くのバルサム油と宝石を王に贈った。シェバの女王がソロモン王に贈ったほどのバルサム油はかつてなかった。'),
('JPN', '历代志下', 14, 9, 10, 'また、オフィルから金を運んで来たヒラムのしもべたちとソロモンのしもべたちは、白檀の木材と宝石を運んで来た。'),
('JPN', '历代志下', 14, 9, 11, '王はこの白檀の木材で、主の宮と王宮のための通路を造り、歌い手たちのための竪琴と琴を作った。かつてユダの地で、このようなものが見られたことはなかった。'),
('JPN', '历代志下', 14, 9, 12, 'ソロモン王は、シェバの女王が王のもとに携えて来た物以外のもので、彼女が求めたものは何でもその望みのままに与えた。彼女は家来たちを連れて、自分の国へ帰って行った。'),
('JPN', '历代志下', 14, 9, 13, '一年間にソロモンのところに入って来た金の重さは、金の目方で六百六十六タラントであった。'),
('JPN', '历代志下', 14, 9, 14, 'このほかに、隊商や商人たちが携えて来たものがあった。アラビアのすべての王たち、およびその地の総督たちも、ソロモンのところに金や銀を携えて来た。'),
('JPN', '历代志下', 14, 9, 15, 'ソロモン王は、延べ金で大盾二百を作り、その大盾一つに六百シェケルの延べ金を使った。'),
('JPN', '历代志下', 14, 9, 16, 'また延べ金で盾三百を作り、その盾一つに三百シェケルの金を使った。王はそれらを「レバノンの森の宮殿」に置いた。'),
('JPN', '历代志下', 14, 9, 17, '王は大きな象牙の王座を作り、これに純金をかぶせた。'),
('JPN', '历代志下', 14, 9, 18, '王座には六つの段があり、その王座には金の足台が取り付けられていた。座席の両側には肘掛けがあり、その肘掛けのわきには二頭の雄獅子が立っていた。'),
('JPN', '历代志下', 14, 9, 19, 'また、十二頭の雄獅子が六つの段の両側に立っていた。このような物は、どこの王国でも作られたことがなかった。'),
('JPN', '历代志下', 14, 9, 20, 'ソロモン王が飲み物に用いる器はすべて金であった。「レバノンの森の宮殿」にあった器もすべて純金であった。銀は、ソロモンの時代には価値あるものとは見なされていなかった。'),
('JPN', '历代志下', 14, 9, 21, '王にはヒラムのしもべたちを乗せてタルシシュへ行く船があり、三年に一度、タルシシュの船が金、銀、象牙、猿、孔雀を運んで来たからである。'),
('JPN', '历代志下', 14, 9, 22, 'ソロモン王は、富と知恵とにおいて、地上のどの王よりもまさっていた。'),
('JPN', '历代志下', 14, 9, 23, '地上のすべての王は、神がソロモンの心に授けられた知恵を聞こうとして、彼に謁見を求めた。'),
('JPN', '历代志下', 14, 9, 24, '彼らはそれぞれ贈り物として、銀の器、金の器、衣服、武器、バルサム油、馬、ろばなどを、毎年携えて来た。'),
('JPN', '历代志下', 14, 9, 25, 'ソロモンは馬と戦車のための厩舎を四千、および騎兵を一万二千持っていた。彼はこれらを戦車の町々、およびエルサレムの王のもとに配置した。'),
('JPN', '历代志下', 14, 9, 26, '彼は、あの大河からペリシテ人の地、さらにエジプトの国境に至るすべての王を支配下に置いた。'),
('JPN', '历代志下', 14, 9, 27, '王はエルサレムで銀を石のように用い、杉の木をシェフェラのいちじく桑の木のように大量に用いた。'),
('JPN', '历代志下', 14, 9, 28, '馬は、エジプトおよびあらゆる国々からソロモンのもとに運ばれて来た。'),
('JPN', '历代志下', 14, 9, 29, 'ソロモンについてのその他の事柄、それは最初から最後まで、『預言者ナタンの働き』、『シロ人アヒヤの預言』、および『先見者イドが見たネバテの子ヤロブアムについての幻』に確かに記されている。'),
('JPN', '历代志下', 14, 9, 30, 'ソロモンはエルサレムで四十年間、全イスラエルの王であった。'),
('JPN', '历代志下', 14, 9, 31, 'ソロモンは先祖とともに眠りにつき、人々は彼の父ダビデの町に彼を葬った。彼の子レハブアムが代わって王となった。'),
('JPN', '历代志下', 14, 10, 1, 'レハブアムはシェケムへ行った。全イスラエルが彼を王とするために、シェケムに来ていたからである。'),
('JPN', '历代志下', 14, 10, 2, 'ネバテの子ヤロブアムはソロモン王の顔を避けてエジプトに逃れていたが、レハブアムのことを聞いたとき、ヤロブアムはエジプトから戻って来た。'),
('JPN', '历代志下', 14, 10, 3, '人々が使者を遣わして、ヤロブアムを呼び寄せたので、彼は全イスラエルとともにやって来て、レハブアムに言った。'),
('JPN', '历代志下', 14, 10, 4, '「あなたの父上は、私たちのくびきを重くしました。今、あなたは、父上が私たちに負わせた過酷な労働と重いくびきを軽くしてください。そうすれば、私たちはあなたに仕えます。」'),
('JPN', '历代志下', 14, 10, 5, 'するとレハブアムは彼らに、「三日たったら、私のところに戻って来るがよい」と言った。そこで民は出て行った。'),
('JPN', '历代志下', 14, 10, 6, 'レハブアム王は、父ソロモンが生きている間ソロモンに仕えていた長老たちに、「この民にどう返答したらよいと思うか」と相談した。'),
('JPN', '历代志下', 14, 10, 7, '彼らは王に答えた。「もし、あなたがこの民に優しくし、彼らに好意を示し、彼らに親切なことばをかけてやるなら、彼らはいつまでもあなたのしもべとなるでしょう。」'),
('JPN', '历代志下', 14, 10, 8, 'しかし、王はこの長老たちが与えた助言を退け、自分とともに育ち、自分に仕えている若者たちにこう相談した。'),
('JPN', '历代志下', 14, 10, 9, '「この民に何と返答したらよいと思うか。彼らは私に『あなたの父上が私たちに負わせたくびきを軽くしてください』と言ってきたのだが。」'),
('JPN', '历代志下', 14, 10, 10, '彼とともに育った若者たちは答えた。「『あなたの父上は私たちのくびきを重くしました。けれども、あなたはそれを軽くしてください』と言ってきたこの民には、こう答えたらよいでしょう。『私の小指は父の腰よりも太い。'),
('JPN', '历代志下', 14, 10, 11, '私の父がおまえたちに重いくびきを負わせたのであれば、私はおまえたちのくびきをもっと重くする。私の父がおまえたちをむちで懲らしめたのであれば、私はサソリを使う』と。」'),
('JPN', '历代志下', 14, 10, 12, 'ヤロブアムとすべての民は、三日目にレハブアムのところに来た。王が「三日目に私のところに戻って来るがよい」と命じたからである。'),
('JPN', '历代志下', 14, 10, 13, '王は彼らに厳しく答えた。レハブアム王は長老たちの助言を退け、'),
('JPN', '历代志下', 14, 10, 14, '若者たちの助言どおりに民に答えた。「私はおまえたちのくびきを重くする。私はそれをもっと重くする。私の父がおまえたちをむちで懲らしめたのなら、私はサソリを使う。」'),
('JPN', '历代志下', 14, 10, 15, '王は民の願いを聞き入れなかった。神がそう仕向けられたからである。それは、かつてシロ人アヒヤを通してネバテの子ヤロブアムに告げられたことばを主が実現されるためであった。'),
('JPN', '历代志下', 14, 10, 16, '全イスラエルは、王が自分たちに耳を貸さないのを見てとった。そこで、民は王にことばを返した。「ダビデのうちには、われわれのためのどんな割り当て地があろうか。エッサイの子のうちには、われわれのためのゆずりの地はない。イスラエルよ、それぞれ自分の天幕に帰れ。ダビデよ、今、あなたの家を見よ。」全イスラエルは自分たちの天幕に帰って行った。'),
('JPN', '历代志下', 14, 10, 17, 'ただし、ユダの町々に住むイスラエルの子らにとっては、レハブアムがその王であった。'),
('JPN', '历代志下', 14, 10, 18, 'レハブアム王は役務長官ハドラムを遣わしたが、イスラエルの人々は彼を石で打ち殺した。レハブアム王はやっとの思いで戦車に乗り込み、エルサレムに逃げた。'),
('JPN', '历代志下', 14, 10, 19, 'このようにして、イスラエルはダビデの家に背いた。今日もそうである。'),
('JPN', '历代志下', 14, 11, 1, 'レハブアムはエルサレムに帰り、ユダとベニヤミンの家から選り抜きの戦士十八万を召集し、王国をレハブアム自身のもとに取り戻すため、イスラエルと戦おうとした。'),
('JPN', '历代志下', 14, 11, 2, 'すると、神の人シェマヤに次のような主のことばがあった。'),
('JPN', '历代志下', 14, 11, 3, '「ユダの王、ソロモンの子レハブアム、および、ユダとベニヤミンに属する全イスラエルに告げよ。'),
('JPN', '历代志下', 14, 11, 4, '『主はこう言われる。上って行ってはならない。あなたがたの兄弟たちと戦ってはならない。それぞれ自分の家に帰れ。わたしが、こうなるように仕向けたのだから。』」そこで、彼らは主のことばに聞き従い、ヤロブアムを目指して進む行軍を中止して、引き返した。'),
('JPN', '历代志下', 14, 11, 5, 'レハブアムはエルサレムに住み、ユダに防備の町々を建てた。'),
('JPN', '历代志下', 14, 11, 6, 'すなわち、ベツレヘムとエタムとテコア、'),
('JPN', '历代志下', 14, 11, 7, 'ベテ・ツルとソコとアドラム、'),
('JPN', '历代志下', 14, 11, 8, 'ガテとマレシャとジフ、'),
('JPN', '历代志下', 14, 11, 9, 'アドライムとラキシュとアゼカ、'),
('JPN', '历代志下', 14, 11, 10, 'ツォルアとアヤロンとヘブロン。これらはユダとベニヤミンの中にあり、防備の町々であった。'),
('JPN', '历代志下', 14, 11, 11, '彼は防備を固めて、その中に隊長を置き、食糧、油、ぶどう酒を蓄えた。'),
('JPN', '历代志下', 14, 11, 12, 'またどの町にも大盾と槍を置き、これらの町をますます堅固にした。こうして、ユダとベニヤミンは彼の側についた。'),
('JPN', '历代志下', 14, 11, 13, 'イスラエル全土の祭司たちとレビ人たちは、すべての地域から出て来て、彼の側についた。'),
('JPN', '历代志下', 14, 11, 14, 'レビ人たちは、自分たちの放牧地と所有地を捨てて、ユダとエルサレムに来たのである。ヤロブアムとその子らが、主の祭司としての彼らの職を解き、'),
('JPN', '历代志下', 14, 11, 15, '自分のために祭司たちを任命して、彼が造った高き所と雄やぎと子牛に仕えさせたからである。'),
('JPN', '历代志下', 14, 11, 16, '彼らの後に続いて、イスラエルの全部族の中から、イスラエルの神、主を尋ね求めようと心に決めた者たちが、その父祖の神、主にいけにえを献げるためエルサレムに来た。'),
('JPN', '历代志下', 14, 11, 17, '彼らは三年の間、ユダの王権を強固にし、ソロモンの子レハブアムに力添えをした。三年の間、彼らがダビデとソロモンの道に歩んだからである。'),
('JPN', '历代志下', 14, 11, 18, 'レハブアムは、ダビデの子エリモテとエッサイの子エリアブの娘アビハイルの間にできた娘マハラテを妻とした。'),
('JPN', '历代志下', 14, 11, 19, '彼女は彼に男の子を産んだ。エウシュ、シェマルヤ、ザハムである。'),
('JPN', '历代志下', 14, 11, 20, '彼女を妻とした後で、彼はアブサロムの娘マアカを妻とした。彼女はアビヤ、アタイ、ジザ、シェロミテを産んだ。'),
('JPN', '历代志下', 14, 11, 21, 'レハブアムは彼のすべての妻や側女にまさってアブサロムの娘マアカを愛した。彼は妻を十八人、側女を六十人抱えていて、二十八人の息子、六十人の娘をもうけた。'),
('JPN', '历代志下', 14, 11, 22, 'レハブアムはマアカの子アビヤを立ててかしらとし、兄弟たちの長とした。彼を王にしようと考えたからである。'),
('JPN', '历代志下', 14, 11, 23, 'レハブアムは賢く事を行い、その子どもたちをみな、ユダとベニヤミンの全土に、すなわちすべての防備の町々に分散させ、多くの食糧を彼らに与え、また大勢の妻を彼らのために探し求めた。'),
('JPN', '历代志下', 14, 12, 1, 'レハブアムの王位が確立し、彼が強くなると、彼は主の律法を捨て、彼とともにいた全イスラエルもそうした。'),
('JPN', '历代志下', 14, 12, 2, 'さて、レハブアム王の第五年に、エジプトの王シシャクがエルサレムに攻め上って来た。イスラエルが主の信頼を裏切っていたからである。'),
('JPN', '历代志下', 14, 12, 3, '一緒に来たのは、戦車千二百台、騎兵六万人。彼とともにエジプトから来た兵たち、すなわち、ルブ人、スキ人、クシュ人は数えきれないほどであった。'),
('JPN', '历代志下', 14, 12, 4, '彼はユダに属する防備の町々を攻め取り、エルサレムまで攻め寄せて来た。'),
('JPN', '历代志下', 14, 12, 5, 'そのとき、預言者シェマヤが、シシャクのことでエルサレムに集まっていたレハブアムとユダの首長たちのもとに来て言った。「主はこう言われる。『あなたがたがわたしを捨てたので、わたしもあなたがたを捨てて、シシャクの手に渡した。』」'),
('JPN', '历代志下', 14, 12, 6, 'すると、イスラエルの首長たちと王はへりくだり、「主は正しい」と言った。'),
('JPN', '历代志下', 14, 12, 7, '主が、彼らのへりくだった様子をご覧になると、シェマヤに次のような主のことばがあった。「彼らがへりくだったので、わたしは彼らを滅ぼさない。間もなく彼らに救いを与える。わたしの憤りがシシャクの手を通してエルサレムに注がれることはない。'),
('JPN', '历代志下', 14, 12, 8, 'ただし、彼らはシシャクのしもべとなる。わたしに仕えることと地の諸王に仕えることの違いを知るためである。」'),
('JPN', '历代志下', 14, 12, 9, 'エジプトの王シシャクはエルサレムに攻め上り、主の宮の財宝、王宮の財宝を奪い取った。彼は何もかも奪い取った。ソロモンが作った金の盾も奪い取った。'),
('JPN', '历代志下', 14, 12, 10, 'レハブアム王は、その代わりに青銅の盾を作り、これを王宮の門を守る近衛兵の隊長の手に託した。'),
('JPN', '历代志下', 14, 12, 11, '王が主の宮に入るたびに、近衛兵が来てこれを運んで行き、また近衛兵の控え室に戻した。'),
('JPN', '历代志下', 14, 12, 12, '王がへりくだったとき、主の怒りは彼を離れ、主は徹底的に滅ぼすことはされなかった。ユダにも良いことがあったのである。'),
('JPN', '历代志下', 14, 12, 13, 'レハブアム王はエルサレムで勢力を増し、国を治めた。レハブアムは四十一歳で王となり、主がご自分の名を置くためにイスラエルの全部族の中から選ばれた都、エルサレムで十七年間、王であった。彼の母の名はナアマといい、アンモン人であった。'),
('JPN', '历代志下', 14, 12, 14, '彼は悪事を行った。心を定めて主を求めることをしなかったのである。'),
('JPN', '历代志下', 14, 12, 15, 'レハブアムについての事柄、それは最初から最後まで、『預言者シェマヤと先見者イドの働き』に、系図にしたがって確かに記載されている。レハブアムとヤロブアムの間には、いつも戦いがあった。'),
('JPN', '历代志下', 14, 12, 16, 'レハブアムは先祖とともに眠りにつき、ダビデの町に葬られた。彼の子アビヤが代わって王となった。'),
('JPN', '历代志下', 14, 13, 1, 'ヤロブアム王の第十八年に、アビヤがユダの王となり、'),
('JPN', '历代志下', 14, 13, 2, 'エルサレムで三年間、王であった。彼の母の名はミカヤといい、ギブア出身のウリエルの娘であった。アビヤとヤロブアムの間には戦いがあった。'),
('JPN', '历代志下', 14, 13, 3, 'アビヤは精鋭四十万の勇敢な戦士の部隊を率いて戦いに臨んだ。一方、ヤロブアムも八十万の精鋭の戦士を率いて彼に対抗し、戦いに備えた。'),
('JPN', '历代志下', 14, 13, 4, 'アビヤは、エフライムの山地にあるツェマライム山の上に立って言った。「ヤロブアムおよび全イスラエルよ、私の言うことを聞け。'),
('JPN', '历代志下', 14, 13, 5, 'イスラエルの神、主が、塩の契約をもって、イスラエルの王国をとこしえにダビデとその子孫に与えられたことを、あなたがたが知らないはずはない。'),
('JPN', '历代志下', 14, 13, 6, 'ところが、ダビデの子ソロモンのしもべであったネバテの子ヤロブアムが立ち上がって、自分の主君に反逆し、'),
('JPN', '历代志下', 14, 13, 7, '彼のもとに、ごろつき、よこしまな者たちが集まり、ソロモンの子レハブアムより優勢となった。それに、レハブアムは若くて気が弱く、彼らに対抗して自分の力を増し加えることがなかった。'),
('JPN', '历代志下', 14, 13, 8, 'そして今、あなたがたは、ダビデの子孫の手にある主の王国に敵対しようとしている。あなたがたは大軍であり、ヤロブアムがあなたがたのために造って神とした金の子牛もあなたがたとともにある。'),
('JPN', '历代志下', 14, 13, 9, 'あなたがたは、アロンの子らである主の祭司たちとレビ人を追放し、諸国の民に倣って自分たちのために祭司を立てたではないか。だれでも若い雄牛一頭と雄羊七匹をもって祭司職につこうとするなら、神ではないものの祭司となれたのである。'),
('JPN', '历代志下', 14, 13, 10, 'しかし、私たちにとっては、主が私たちの神であり、この方を捨てなかった。また、主に仕える祭司たちはアロンの子らであり、レビ人も務めを果たしている。'),
('JPN', '历代志下', 14, 13, 11, '彼らは朝ごと夕ごとに主に向けて全焼のささげ物を焼いて煙にし、芳ばしい香をたき、並べ供えるパンをきよい机の上に整え、夕ごとに金の燭台とその上のともしび皿に火をともしている。私たちは、私たちの神、主への務めを果たしているが、あなたがたはこの方を捨て去った。'),
('JPN', '历代志下', 14, 13, 12, '見よ、神は私たちとともにいて、かしらとなっておられる。また、神の祭司たちも吹き鳴らすラッパを手にして、あなたがたに対し進撃の合図を吹き鳴らそうとしている。イスラエルの人々よ、あなたがたの父祖の神、主と戦ってはならない。とうてい勝ち目がないからである。」'),
('JPN', '历代志下', 14, 13, 13, 'ところが、ヤロブアムは伏兵を回して、彼らの背後から攻めるようにさせた。そのため、本隊はユダの正面に、伏兵はその背後にいることとなった。'),
('JPN', '历代志下', 14, 13, 14, 'ユダが向き直ると、なんと、戦いは前後から迫っていた。そこで、彼らは主に叫び求め、祭司たちはラッパを吹き鳴らした。'),
('JPN', '历代志下', 14, 13, 15, 'そして、ユダの人々はときの声をあげた。ユダの人々がときの声をあげると、神はヤロブアムと全イスラエルを、アビヤとユダの前に打ち破られたので、'),
('JPN', '历代志下', 14, 13, 16, 'イスラエルの人々はユダの前から逃げ去った。こうして、神は彼らをユダの手に渡された。'),
('JPN', '历代志下', 14, 13, 17, 'アビヤとその兵たちは彼らを討ち、大打撃を与えた。イスラエルのうち、精鋭五十万が剣に倒れた。'),
('JPN', '历代志下', 14, 13, 18, 'イスラエル人はこのとき屈服させられ、ユダ人は勝利を得た。彼らがその父祖の神、主に拠り頼んだからである。'),
('JPN', '历代志下', 14, 13, 19, 'アビヤはヤロブアムを追撃し、ベテルとそれに属する村々、エシャナとそれに属する村々、エフラインとそれに属する村々を彼から取った。'),
('JPN', '历代志下', 14, 13, 20, 'こうして、ヤロブアムはアビヤの時代に、再び勢力を回復することはできなかった。主が彼を打たれたので、彼は死んだ。'),
('JPN', '历代志下', 14, 13, 21, '一方アビヤは勢力を増し、十四人を妻として、二十二人の息子と十六人の娘をもうけた。'),
('JPN', '历代志下', 14, 13, 22, 'アビヤについてのその他の事柄、彼の行いとことばは、『預言者イドの注解』に記されている。'),
('JPN', '历代志下', 14, 14, 1, 'アビヤは先祖とともに眠りにつき、人々は彼をダビデの町に葬った。彼の子アサが代わって王となった。彼の治世になって十年の間、国は平穏であった。'),
('JPN', '历代志下', 14, 14, 2, 'アサは、自分の神、主の目にかなう良いことを行った。'),
('JPN', '历代志下', 14, 14, 3, '彼は異教の祭壇と高き所を取り除き、石の柱を砕き、アシェラ像を切り倒し、'),
('JPN', '历代志下', 14, 14, 4, 'ユダの人々に命じて、彼らの父祖の神、主を求めさせ、その律法と命令を行わせた。'),
('JPN', '历代志下', 14, 14, 5, '彼はユダのすべての町から高き所と香の台を取り除いた。こうして、王国は彼のもとに平穏であった。'),
('JPN', '历代志下', 14, 14, 6, '彼はユダに防備の町々を築いた。主が彼に安息を与えられたので、当時数年の間、国は平穏を保ち、彼と戦う者はいなかった。'),
('JPN', '历代志下', 14, 14, 7, '彼はユダの人々に言った。「さあ、これらの町々を建て、その周りに城壁とやぐらを巡らし、門とかんぬきを設けよう。この地はまだ私たちの前にある。私たちが私たちの神、主を求めたからだ。私たちが求めたので、神は周囲の者たちから私たちを守り、安息を下さったのだ。」こうして、彼らは町々を建設し、繁栄した。'),
('JPN', '历代志下', 14, 14, 8, 'アサには、大盾と槍を携えたユダの兵が三十万、盾を持ち弓を引くベニヤミンの兵が二十八万あり、これらはみな勇士であった。'),
('JPN', '历代志下', 14, 14, 9, 'さて、クシュ人ゼラフが、彼らに向かって百万の軍勢と三百台の戦車を率いて出陣し、マレシャにまで攻めて来た。'),
('JPN', '历代志下', 14, 14, 10, 'アサは彼に対して出陣し、マレシャにあるツェファテの谷で戦いの備えをした。'),
('JPN', '历代志下', 14, 14, 11, 'アサは自分の神、主を呼び求めて言った。「主よ、力の強い者を助けるのも、力のない者を助けるのも、あなたには変わりはありません。私たちの神、主よ、私たちを助けてください。私たちはあなたに拠り頼み、御名によってこの大軍に向かって来ました。主よ、あなたは私たちの神です。人間が、あなたに力を行使することのないようにしてください。」'),
('JPN', '历代志下', 14, 14, 12, '主はアサとユダの前でクシュ人を打たれたので、クシュ人は逃げ去った。'),
('JPN', '历代志下', 14, 14, 13, 'アサおよび彼とともにいた兵は、彼らをゲラルまで追撃した。クシュ人は倒れ、生きている者はいなかった。主とその陣営の前に打ち砕かれたからである。兵たちは非常に多くの分捕り物を持ち帰った。'),
('JPN', '历代志下', 14, 14, 14, '彼らはまた、ゲラル周辺のすべての町も打ち倒した。主の恐れがその町々にあったからである。彼らはすべての町で略奪した。そこには多くの略奪できる物があったからである。'),
('JPN', '历代志下', 14, 14, 15, 'また家畜の群れの天幕も襲い、多くの羊とらくだを奪って、エルサレムに帰った。'),
('JPN', '历代志下', 14, 15, 1, 'すると、オデデの子アザルヤに神の霊が臨んだ。'),
('JPN', '历代志下', 14, 15, 2, '彼はアサの前に進み出て、言った。「アサおよび、すべてユダとベニヤミンの人々よ、私の言うことを聞きなさい。あなたがたが主とともにいる間は、主はあなたがたとともにおられます。もし、あなたがたがこの方を求めるなら、あなたがたにご自分を示してくださいます。もし、あなたがたがこの方を捨てるなら、この方はあなたがたを捨ててしまわれます。'),
('JPN', '历代志下', 14, 15, 3, '長年の間、イスラエルにはまことの神もなく、教師となる祭司もなく、律法もありませんでした。'),
('JPN', '历代志下', 14, 15, 4, 'しかし、苦しみの中で、彼らがイスラエルの神、主に立ち返り、この方を慕い求めたところ、主は彼らにご自分を示してくださいました。'),
('JPN', '历代志下', 14, 15, 5, 'この時期には、出て行く者にも、入って来る者にも平安がありませんでした。国々に住むすべての人々に数々の大きな騒乱があったからです。'),
('JPN', '历代志下', 14, 15, 6, 'そして、国は国に、町は町に逆らい、彼らはともに打ち砕かれてしまいました。神があらゆる苦しみをもって、彼らをかき乱されたからです。'),
('JPN', '历代志下', 14, 15, 7, 'しかし、あなたがたは勇気を出しなさい。力を落としてはなりません。あなたがたの働きには報いがあるからです。」'),
('JPN', '历代志下', 14, 15, 8, 'アサは、これらのことばと預言者オデデの預言を聞いて奮い立ち、ユダとベニヤミンの全地、また彼がエフライムの山地で攻め取った町々から、忌むべき物を除いた。そして、主の宮の玄関の前にあった主の祭壇を新しくした。'),
('JPN', '历代志下', 14, 15, 9, '彼は、ユダとベニヤミンのすべての人々、およびエフライム、マナセ、シメオンから来て彼らのもとに寄留している人々を集めた。その神、主がアサとともにおられるのを見て、イスラエルから多くの人々が彼のもとに下って来ていたのである。'),
('JPN', '历代志下', 14, 15, 10, '彼らはアサの治世の第十五年の第三の月にエルサレムに集まった。'),
('JPN', '历代志下', 14, 15, 11, 'その日、彼らは自分たちが携えて来た分捕り物の中から、牛七百頭と羊七千匹を主にいけにえとして献げた。'),
('JPN', '历代志下', 14, 15, 12, '彼らは契約を結び、心を尽くし、いのちを尽くして、父祖の神、主を求めることと、'),
('JPN', '历代志下', 14, 15, 13, 'だれでもイスラエルの神、主を求めない者は、小さな者も大きな者も、男も女も、死刑にされることとした。'),
('JPN', '历代志下', 14, 15, 14, '彼らは大声で喜びの叫びをあげ、ラッパと角笛を吹いて、主に誓いを立てた。'),
('JPN', '历代志下', 14, 15, 15, 'ユダの人々はみなその誓いを喜んだ。それは、彼らが心のすべてをもって誓いを立て、ただ一筋に主を慕い求め、そして主がご自分を彼らに示されたからである。主は周囲の者から守って彼らに安息を与えられた。'),
('JPN', '历代志下', 14, 15, 16, 'また、アサ王は、母マアカがアシェラのために憎むべき像を造ったので、彼女を皇太后の位から退けた。アサはその憎むべき像を切り倒して粉々に砕き、これをキデロンの谷で焼いた。'),
('JPN', '历代志下', 14, 15, 17, '高き所はイスラエルから取り除かれなかったが、アサの心は生涯、全きものであった。'),
('JPN', '历代志下', 14, 15, 18, '彼は、父が聖別した物と自分が聖別した物、銀、金、器を、神の宮に運び入れた。'),
('JPN', '历代志下', 14, 15, 19, 'アサの治世の第三十五年まで、戦いは起こらなかった。'),
('JPN', '历代志下', 14, 16, 1, 'アサの治世の第三十六年に、イスラエルの王バアシャがユダに上って来て、ラマを築き直し、ユダの王アサのもとにだれも出入りできないようにした。'),
('JPN', '历代志下', 14, 16, 2, 'アサは、主の宮と王宮の宝物倉から銀と金を取り出し、ダマスコに住んでいたアラムの王ベン・ハダドのもとに送り届けて言った。'),
('JPN', '历代志下', 14, 16, 3, '「私の父とあなたの父上の間にあったように、私とあなたの間にも同盟を結びましょう。ご覧ください。私はあなたに銀と金を送りました。どうか、イスラエルの王バアシャとの同盟を破棄して、彼が私のもとから離れ去るようにしてください。」'),
('JPN', '历代志下', 14, 16, 4, 'ベン・ハダドはアサ王の願いを聞き入れ、自分の配下の軍の高官たちをイスラエルの町々に差し向けた。彼らは、イヨンと、ダンと、アベル・マイム、およびナフタリに属するすべての倉庫の町々を攻撃した。'),
('JPN', '历代志下', 14, 16, 5, 'バアシャはこれを聞くと、ラマを築き直すのを中止し、その工事をやめた。'),
('JPN', '历代志下', 14, 16, 6, 'そこで、アサ王はユダの人々をみな連れて行き、バアシャが建築に用いたラマの石材と木材を運び出させたうえ、これを用いてゲバとミツパを建てた。'),
('JPN', '历代志下', 14, 16, 7, 'そのとき、予見者ハナニがユダの王アサのもとに来て、彼に言った。「あなたはアラムの王に拠り頼み、あなたの神、主に拠り頼みませんでした。それゆえ、アラム王の軍勢はあなたの手から逃れたのです。'),
('JPN', '历代志下', 14, 16, 8, 'あのクシュ人とルブ人は大軍勢ではなかったでしょうか。戦車や騎兵は非常に多くはなかったでしょうか。しかし、あなたが主に拠り頼んだとき、主は彼らをあなたの手に渡されたのです。'),
('JPN', '历代志下', 14, 16, 9, '主はその御目をもって全地を隅々まで見渡し、その心がご自分と全く一つになっている人々に御力を現してくださるのです。あなたは、このことについて愚かなことをしました。これから、あなたには数々の戦いが起こるでしょう。」'),
('JPN', '历代志下', 14, 16, 10, 'アサはこの予見者に対して怒りを発し、彼を牢獄につないだ。彼に対して、このことで激しい怒りを抱いたのである。アサはこのとき、民のうちのある者を踏みにじった。'),
('JPN', '历代志下', 14, 16, 11, '見よ。アサについての事柄は、最初から最後まで、『ユダとイスラエルの王の書』にまさしく記されている。'),
('JPN', '历代志下', 14, 16, 12, 'アサはその治世の第三十九年に、両足とも病気になった。それは非常に重かったが、その病気の中でさえ、彼は主を求めず、医者を求めた。'),
('JPN', '历代志下', 14, 16, 13, 'アサは先祖とともに眠りについた。彼はその治世の第四十一年に死んだ。'),
('JPN', '历代志下', 14, 16, 14, 'そこで、人々は、彼が自分のためにダビデの町に掘っておいた墓に彼を葬り、調合法にしたがって作った種々の香り高い香油で満ちた寝床に、彼を横たえた。そして、彼のために非常にたくさんの香をたいた。'),
('JPN', '历代志下', 14, 17, 1, '彼に代わって、彼の子ヨシャファテが王となり、イスラエルに対して勢力を増し加えた。'),
('JPN', '历代志下', 14, 17, 2, '彼はユダにあるすべての城壁のある町々に軍隊を置き、ユダの地と、彼の父アサが攻め取ったエフライムの町々に守備隊を置いた。'),
('JPN', '历代志下', 14, 17, 3, '主はヨシャファテとともにおられた。彼がその先祖ダビデの最初の道に歩んで、バアルの神々に求めず、'),
('JPN', '历代志下', 14, 17, 4, '父祖の神に求め、その命令にしたがって歩み、イスラエルの行いに倣わなかったからである。'),
('JPN', '历代志下', 14, 17, 5, '主は、王国を彼の手によって確立された。ユダの人々はみなヨシャファテに貢ぎ物を持って来たので、彼には富と誉れが豊かに与えられた。'),
('JPN', '历代志下', 14, 17, 6, '彼の心は主の道を大いに誇りとし、彼はさらに、高き所とアシェラ像をユダから取り除いた。'),
('JPN', '历代志下', 14, 17, 7, '彼はその治世の第三年に、彼の高官たち、ベン・ハイル、オバデヤ、ゼカリヤ、ネタンエル、ミカヤを遣わして、ユダの町々で教えさせた。'),
('JPN', '历代志下', 14, 17, 8, '彼らとともにレビ人も同行した。すなわち、シェマヤ、ネタンヤ、ゼバデヤ、アサエル、シェミラモテ、ヨナタン、アドニヤ、トビヤ、トブ・アドニヤなどのレビ人である。また、彼らとともに、祭司のエリシャマとヨラムも同行した。'),
('JPN', '历代志下', 14, 17, 9, '彼らはユダで教えた。主の律法の書を携え、ユダのすべての町を巡回して、民の間で教えた。'),
('JPN', '历代志下', 14, 17, 10, '主の恐れが、ユダの周りの地のすべての王国にあったので、ヨシャファテに戦いを仕掛ける者はいなかった。'),
('JPN', '历代志下', 14, 17, 11, 'ペリシテ人の中には、ヨシャファテに貢ぎ物と税としての銀を持って来る者があり、アラビア人も雄羊七千七百匹、雄やぎ七千七百匹を彼に持って来た。'),
('JPN', '历代志下', 14, 17, 12, 'こうして、ヨシャファテはしだいに並外れて強大になり、ユダに城塞や倉庫の町々を築いた。'),
('JPN', '历代志下', 14, 17, 13, '彼には、ユダの町々で多くのなすべき工事があった。また、エルサレムには勇敢な戦士たちがいた。'),
('JPN', '历代志下', 14, 17, 14, '彼らの父祖の家ごとの登録は次のとおりである。ユダでは、千人隊の長たち、隊長アデナ。その配下には勇士三十万人。'),
('JPN', '历代志下', 14, 17, 15, '次に隊長ヨハナン。その配下には二十八万人。'),
('JPN', '历代志下', 14, 17, 16, 'その次は、自ら進んで主に身を献げたジクリの子アマスヤ。その配下には二十万人の勇士。'),
('JPN', '历代志下', 14, 17, 17, 'ベニヤミンからは、勇士エルヤダ。その配下には、弓と盾を取る者が二十万人。'),
('JPN', '历代志下', 14, 17, 18, '次に、エホザバデ。その配下には十八万人の武装した者。'),
('JPN', '历代志下', 14, 17, 19, 'これらが王に仕えた人々である。このほかに、王がユダ全土の城壁のある町々に配属した人々がいた。'),
('JPN', '历代志下', 14, 18, 1, 'ヨシャファテには富と誉れが豊かに与えられたが、彼はアハブと姻戚関係に入った。'),
('JPN', '历代志下', 14, 18, 2, '数年後、彼がサマリアのアハブのところに下って行くと、アハブは彼および彼とともにいた民のために、おびただしい数の羊や牛を屠り、ラモテ・ギルアデに攻め上るよう誘った。'),
('JPN', '历代志下', 14, 18, 3, 'イスラエルの王アハブはユダの王ヨシャファテに言った。「私とともにラモテ・ギルアデに行ってくれませんか。」彼は答えた。「私とあなたは一つ、私の民とあなたの民は一つ、私の馬とあなたの馬は一つです。ともに戦いに臨みましょう。」'),
('JPN', '历代志下', 14, 18, 4, 'ヨシャファテはイスラエルの王に言った。「まず、主のことばを伺ってください。」'),
('JPN', '历代志下', 14, 18, 5, 'イスラエルの王は、四百人の預言者を集めて、彼らに尋ねた。「われわれはラモテ・ギルアデに戦いに行くべきか。それとも、私はやめるべきか。」彼らは答えた。「あなたは攻め上ってください。神は王様の手にこれを渡されます。」'),
('JPN', '历代志下', 14, 18, 6, 'ヨシャファテは、「ここには、われわれがみこころを求めることのできる主の預言者が、ほかにいないのですか」と言った。'),
('JPN', '历代志下', 14, 18, 7, 'イスラエルの王はヨシャファテに答えた。「ほかにもう一人、主に伺うことのできる者がいます。しかし、私は彼を憎んでいます。彼は私について良いことは預言せず、いつも悪いことばかりを預言するからです。それはイムラの子ミカヤです。」ヨシャファテは言った。「王よ、そういうふうには言わないでください。」'),
('JPN', '历代志下', 14, 18, 8, 'イスラエルの王は一人の宦官を呼び、「急いでイムラの子ミカヤを連れて来い」と命じた。'),
('JPN', '历代志下', 14, 18, 9, 'イスラエルの王とユダの王ヨシャファテは、それぞれ王服をまとって王の座に着いて、サマリアの門の入り口にある打ち場で座っていた。預言者はみな、彼らの前で預言していた。'),
('JPN', '历代志下', 14, 18, 10, 'ケナアナの子ゼデキヤは、王のために鉄の角を作って言った。「主はこう言われます。『これらの角で、あなたはアラムを突いて、絶ち滅ぼさなければならない。』」'),
('JPN', '历代志下', 14, 18, 11, '預言者たちはみな、同じように預言した。「あなたはラモテ・ギルアデに攻め上って勝利を得てください。主は王の手にこれを渡されます。」'),
('JPN', '历代志下', 14, 18, 12, 'ミカヤを呼びに行った使者はミカヤに告げた。「いいですか。預言者たちは口をそろえて、王に対して良いことを述べています。どうか、あなたも彼らと同じように語り、良いことを述べてください。」'),
('JPN', '历代志下', 14, 18, 13, 'ミカヤは答えた。「主は生きておられる。私の神が私に告げられることを、そのまま述べよう。」'),
('JPN', '历代志下', 14, 18, 14, '彼が王のもとに着くと、王は彼に言った。「ミカヤ、われわれはラモテ・ギルアデに戦いに行くべきか。それとも、私はやめるべきか。」彼は答えた。「あなたがたは攻め上って勝利を得なさい。彼らはあなたがたの手に渡されます。」'),
('JPN', '历代志下', 14, 18, 15, '王は彼に言った。「私が何度おまえに誓わせたら、おまえは主の名によって真実だけを私に告げるようになるのか。」'),
('JPN', '历代志下', 14, 18, 16, '彼は答えた。「私は全イスラエルが、山々に散らされているのを見た。まるで、羊飼いのいない羊の群れのように。そのとき主はこう言われた。『彼らには主人がいない。彼らをそれぞれ自分の家に無事に帰らせよ。』」'),
('JPN', '历代志下', 14, 18, 17, 'イスラエルの王はヨシャファテに言った。「あなたに言ったではありませんか。彼は私について良いことは預言せず、悪いことばかりを預言すると。」'),
('JPN', '历代志下', 14, 18, 18, 'ミカヤは言った。「それゆえ、主のことばを聞きなさい。私は主が御座に着き、天の万軍がその右左に立っているのを見ました。'),
('JPN', '历代志下', 14, 18, 19, 'そして、主は言われました。『イスラエルの王アハブを惑わして攻め上らせ、ラモテ・ギルアデで倒れさせるのはだれか。』すると、ある者はああしよう、別の者はこうしようと言いました。'),
('JPN', '历代志下', 14, 18, 20, 'ひとりの霊が進み出て、主の前に立ち、『この私が彼を惑わします』と言うと、主は彼に『どのようにやるのか』とお尋ねになりました。'),
('JPN', '历代志下', 14, 18, 21, '彼は答えました。『私が出て行って、彼のすべての預言者の口で偽りを言う霊となります。』主は『きっとあなたは惑わすことができる。出て行って、そのとおりにせよ』と言われました。'),
('JPN', '历代志下', 14, 18, 22, '今ご覧のとおり、主はここにいるあなたの預言者たちの口に、偽りを言う霊を授けられました。主はあなたに下るわざわいを告げられたのです。」'),
('JPN', '历代志下', 14, 18, 23, 'ケナアナの子ゼデキヤが近寄って来て、ミカヤの頬を殴りつけて言った。「どの道を通って主の霊が私を離れ、おまえに語ったというのか。」'),
('JPN', '历代志下', 14, 18, 24, 'ミカヤは答えた。「あなたが奥の間に入って身を隠すその日に、あなたは思い知ることになる。」'),
('JPN', '历代志下', 14, 18, 25, 'イスラエルの王は言った。「ミカヤを捕らえよ。町の長アモンと王の子ヨアシュのもとに連れて行き、'),
('JPN', '历代志下', 14, 18, 26, '王がこう命じたと言え。『この男を獄屋に入れ、私が無事に帰るまで、わずかなパンと、わずかな水だけ与えておけ。』」'),
('JPN', '历代志下', 14, 18, 27, 'ミカヤは言った。「もしも、あなたが無事に戻って来ることがあるなら、主は私によって語られなかったということです。」そして、「すべての民よ、聞きなさい」と言った。'),
('JPN', '历代志下', 14, 18, 28, 'イスラエルの王とユダの王ヨシャファテは、ラモテ・ギルアデに攻め上った。'),
('JPN', '历代志下', 14, 18, 29, 'イスラエルの王はヨシャファテに言った。「私は変装して戦いに行きます。しかし、あなたは自分の王服を着ていてください。」イスラエルの王は変装し、彼らは戦いに行った。'),
('JPN', '历代志下', 14, 18, 30, 'アラムの王は、自分の配下の戦車隊長たちに次のように命じた。「兵とも将軍とも戦うな。ただイスラエルの王だけを狙って戦え。」'),
('JPN', '历代志下', 14, 18, 31, '戦車隊長たちはヨシャファテを見ると、「あれがイスラエルの王に違いない」と思い、彼と戦おうとして取り囲んだ。ヨシャファテが助けを叫び求めたので、主は彼を助けられた。神は彼らを、彼から引き離された。'),
('JPN', '历代志下', 14, 18, 32, '戦車隊長たちは、彼がイスラエルの王ではないことを知ると、彼を追うことをやめて引き返した。'),
('JPN', '历代志下', 14, 18, 33, 'そのとき、ある一人の兵士が何気なく弓を引くと、イスラエルの王の胸当てと草摺の間を射抜いた。王は戦車の御者に言った。「手綱を返して、私を陣営から出させてくれ。傷を負ってしまったから。」'),
('JPN', '历代志下', 14, 18, 34, 'その日、戦いは激しくなった。イスラエルの王は、アラムに向かって夕方まで戦車の中で立っていたが、日没のころになって死んだ。'),
('JPN', '历代志下', 14, 19, 1, 'ユダの王ヨシャファテは、無事にエルサレムの自分の家に帰った。'),
('JPN', '历代志下', 14, 19, 2, 'ハナニの子、先見者エフーが、ヨシャファテ王の前に進み出て言った。「悪者を助け、主を憎む者を愛するというのですか。このことのゆえに、あなたの上に、主の前から怒りが下ります。'),
('JPN', '历代志下', 14, 19, 3, 'しかし、あなたには良いことも認められます。あなたはこの地からアシェラ像を取り除き、心を定めて神を求めてこられました。」'),
('JPN', '历代志下', 14, 19, 4, 'ヨシャファテはエルサレムに住んでいたが、彼はもう一度ベエル・シェバからエフライムの山地に至る民の中に出て行き、彼らを父祖の神、主に立ち返らせた。'),
('JPN', '历代志下', 14, 19, 5, '彼はこの地、すなわち、ユダにあるすべての城壁のある町に、それぞれの町のさばき人を任命した。'),
('JPN', '历代志下', 14, 19, 6, '彼はさばき人たちにこう言った。「あなたがたは自分のすることに注意しなさい。あなたがたがさばくのは、人のためではなく、主のためだからだ。この方は、さばきが行われるとき、あなたがたとともにおられる。'),
('JPN', '历代志下', 14, 19, 7, '今、主への恐れがあなたがたにあるように。忠実に行いなさい。私たちの神、主には、不正をすることも、えこひいきをすることも、賄賂を取ることもないからだ。」'),
('JPN', '历代志下', 14, 19, 8, 'ヨシャファテは、エルサレムにおいても、レビ人と祭司たちの中から、またイスラエルに属する氏族のかしらたちの中から、主のさばきと訴訟に携わる者たちを任命した。彼らはエルサレムに住んだ。'),
('JPN', '历代志下', 14, 19, 9, 'ヨシャファテは彼らに次のように命じた。「あなたがたは主を恐れ、真実と全き心をもって、このように行わなければならない。'),
('JPN', '历代志下', 14, 19, 10, 'それぞれの町に住んでいるあなたがたの兄弟たちから、流血の事件について、あるいは律法、命令、掟、定めについて、あなたがたのところに訴訟が持ち込まれた場合にはいつでも、あなたがたは、彼らが主に対して責めを負わないように、またあなたがたとあなたがたの兄弟たちの上に御怒りが下ることのないように、彼らに警告しなさい。そのように行えば、あなたがたが責めを負うことはない。'),
('JPN', '历代志下', 14, 19, 11, '見よ。祭司アマルヤはあなたがたの上に立つかしらで、主の事柄全体に関して責任を持つ。また、ユダの家の長イシュマエルの子ゼバデヤは王の事柄全体に関して責任を負う。さらに、レビ人たちは、あなたがたの前でつかさとなる。勇気を出して実行しなさい。主が善を行う者とともにいてくださるように。」'),
('JPN', '历代志下', 14, 20, 1, 'その後のことであった。モアブ人とアンモン人、および彼らに合流した一部のアンモン人が、ヨシャファテと戦おうとして攻めて来た。'),
('JPN', '历代志下', 14, 20, 2, 'すると、人々は来て、ヨシャファテに次のように告げた。「海の向こうのアラムから、大軍があなたに向かって攻めて来ました。早くも、彼らはハツェツォン・タマル、すなわちエン・ゲディに来ています。」'),
('JPN', '历代志下', 14, 20, 3, 'ヨシャファテは恐れた。そして心に決めて主を求め、ユダの全土に断食を呼びかけた。'),
('JPN', '历代志下', 14, 20, 4, 'ユダの人々は集まって来て、主の助けを求めた。実にユダのすべての町から人々が来て、主を求めたのである。'),
('JPN', '历代志下', 14, 20, 5, 'ヨシャファテは、主の宮にある新しい庭の前で、ユダとエルサレムの集団の中に立って、'),
('JPN', '历代志下', 14, 20, 6, 'こう言った。「私たちの父祖の神、主よ。あなたは天におられる神ではありませんか。あなたはすべての異邦の王国を支配なさる方ではありませんか。あなたの御手には勢いと力があり、あなたに立ち向かえる者はだれもいません。'),
('JPN', '历代志下', 14, 20, 7, '私たちの神よ。あなたは、この地の住民をあなたの民イスラエルの前から追い払い、とこしえにあなたの友アブラハムの裔にお与えになったのではありませんか。'),
('JPN', '历代志下', 14, 20, 8, '彼らはそこに住み、あなたのため、御名のために、そこに聖所を建てて言いました。'),
('JPN', '历代志下', 14, 20, 9, '『もし、さばきの剣、疫病、飢饉などのわざわいが私たちを襲うなら、私たちはこの宮の前、あなたの御前に立ちます。あなたの御名がこの宮にあるからです。そして、私たちは苦難の中からあなたに叫びます。あなたは聞いて、お救いくださいます。』'),
('JPN', '历代志下', 14, 20, 10, 'ところが今、アンモン人、モアブ人、およびセイル山の人々をご覧ください。かつてイスラエルがエジプトの地から出て来たとき、あなたは彼らの地に入って行くことをお許しになりませんでした。それで、イスラエルは彼らを避け、彼らを滅ぼさなかったのです。'),
('JPN', '历代志下', 14, 20, 11, 'ご覧ください。彼らが私たちにしようとしていることを。彼らは、あなたが私たちに相続させてくださったあなたの所有地から、私たちを追い払おうとしてやって来たのです。'),
('JPN', '历代志下', 14, 20, 12, '私たちの神よ。彼らをさばいてくださらないのですか。攻めて来るこの大軍に当たる力は、私たちにはありません。私たちとしては、どうすればよいのか分かりません。ただ、あなたに目を注ぐのみです。」'),
('JPN', '历代志下', 14, 20, 13, 'ユダの人々はみな主の前に立っていた。彼らの幼子たち、妻たち、子どもたちもともにいた。'),
('JPN', '历代志下', 14, 20, 14, 'ときに、主の霊が会衆の中で、アサフ族の出であるレビ人ヤハジエルの上に臨んだ。彼はマタンヤの子エイエルの子ベナヤの子ゼカリヤの子である。'),
('JPN', '历代志下', 14, 20, 15, '彼は言った。「ユダのすべての人々、エルサレムの住民、およびヨシャファテ王よ、よく聞いてください。主はあなたがたにこう言われます。『この大軍のゆえに恐れてはならない。おののいてはならない。これはあなたがたの戦いではなく、神の戦いである。'),
('JPN', '历代志下', 14, 20, 16, '明日、彼らのところに攻め下れ。見よ、彼らはツィツの坂を上って来る。あなたがたはエルエルの荒野の前、谷の外れで彼らに出会う。'),
('JPN', '历代志下', 14, 20, 17, 'この戦いは、あなたがたが戦うのではない。堅く立って、あなたがたとともにおられる主の救いを見よ。ユダとエルサレムよ、恐れてはならない。おののいてはならない。明日、彼らに向かって出陣せよ。主はあなたがたとともにおられる。』」'),
('JPN', '历代志下', 14, 20, 18, 'ヨシャファテは地にひれ伏し、ユダのすべての人々とエルサレムの住民も主の前にひれ伏して、主を礼拝した。'),
('JPN', '历代志下', 14, 20, 19, 'ケハテの子孫、コラの子孫であるレビ人たちは立ち上がり、大声をあげてイスラエルの神、主を賛美した。'),
('JPN', '历代志下', 14, 20, 20, 'こうして、彼らは翌朝早く、テコアの荒野へ出陣した。出陣のとき、ヨシャファテは立ち上がって言った。「ユダおよびエルサレムの住民よ、私の言うことを聞け。あなたがたの神、主を信じなさい。そうすれば、あなたがたは堅く立つことができる。主の預言者たちを信じ、勝利を得よ。」'),
('JPN', '历代志下', 14, 20, 21, '彼は民と相談し、主に向かって歌う者たちと、聖なる装いをして賛美する者たちとを任命した。彼らが武装した者の前に出て行って、こう言うためであった。「主に感謝せよ。その恵みはとこしえまで。」'),
('JPN', '历代志下', 14, 20, 22, '彼らが喜びと賛美の声をあげ始めると、主は伏兵を設けて、ユダに攻めて来たアンモン人、モアブ人、セイル山の人々を襲わせたので、彼らは打ち負かされた。'),
('JPN', '历代志下', 14, 20, 23, 'アンモン人とモアブ人は、セイル山の住民たちに立ち向かい、これを絶滅させ、根絶やしにした。セイルの住民を滅ぼし尽くすと、彼らは互いに戦って滅ぼし合った。'),
('JPN', '历代志下', 14, 20, 24, 'ユダの人々が、荒野に面した見張り場に上って、その大軍の方を見渡すと、なんと、死体が野に転がっていた。逃れた者は一人もいなかった。'),
('JPN', '历代志下', 14, 20, 25, 'ヨシャファテとその民が分捕り物を奪いに行くと、そこで数多くの武具、衣服、高価な器具を見つけたので、運びきれないほどはぎ取った。分捕り物があまりにも多かったので、奪うのに三日もかかった。'),
('JPN', '历代志下', 14, 20, 26, '四日目に、彼らはベラカの谷に集まり、そこで主をほめたたえた。それゆえ、人々はその場所の名をベラカの谷と呼んで、今日に至っている。'),
('JPN', '历代志下', 14, 20, 27, 'ユダとエルサレムの人々はみな、ヨシャファテを先頭にして、喜びのうちにエルサレムに凱旋した。主がその敵のことで彼らに喜びを与えられたからである。'),
('JPN', '历代志下', 14, 20, 28, '彼らは琴、竪琴、ラッパを携えてエルサレムに入り、主の宮に行った。'),
('JPN', '历代志下', 14, 20, 29, '主がイスラエルの敵と戦われたと聞くと、地のすべての王国に神の恐れが下った。'),
('JPN', '历代志下', 14, 20, 30, 'ヨシャファテの治世は平穏であった。神は周囲の者から彼を守り、安息を与えられた。'),
('JPN', '历代志下', 14, 20, 31, 'このようにして、ヨシャファテはユダを治めた。彼は三十五歳で王となり、エルサレムで二十五年間、王であった。その母の名はアズバといい、シルヒの娘であった。'),
('JPN', '历代志下', 14, 20, 32, 'ヨシャファテはその父アサの道に歩み、そこから外れることなく、主の目にかなうことを行った。'),
('JPN', '历代志下', 14, 20, 33, 'しかし、高き所は取り除かれなかった。民はなおも、彼らの父祖の神にその心を定めようとしなかった。'),
('JPN', '历代志下', 14, 20, 34, 'ヨシャファテについてのその他の事柄は、最初から最後まで、『イスラエルの王の書』に載せられた『ハナニの子エフーの働き』にまさしく記されている。'),
('JPN', '历代志下', 14, 20, 35, 'その後、ユダの王ヨシャファテは、イスラエルの王アハズヤと同盟を結んだ。アハズヤは悪事を行った。'),
('JPN', '历代志下', 14, 20, 36, 'ヨシャファテはタルシシュへ行く船団をつくるために、アハズヤと同盟を結んだ。そして、彼らはエツヨン・ゲベルで船団をつくった。'),
('JPN', '历代志下', 14, 20, 37, 'マレシャ出身のドダワフの子エリエゼルがヨシャファテに向かって次のように預言した。「あなたがアハズヤと同盟を結んだので、主はあなたが造ったものを打ち壊されます。」すると、船は難破し、タルシシュへ行くことができなくなった。'),
('JPN', '历代志下', 14, 21, 1, 'ヨシャファテは先祖とともに眠りにつき、先祖とともにダビデの町に葬られた。その子ヨラムが代わって王となった。'),
('JPN', '历代志下', 14, 21, 2, '彼には兄弟たちがいた。ヨシャファテの子で、アザルヤ、エヒエル、ゼカリヤ、アザルヤ、ミカエル、シェファテヤであった。これらはみな、イスラエルの王ヨシャファテの子であった。'),
('JPN', '历代志下', 14, 21, 3, '父は彼らに、ユダの防備の町々とともに、銀、金、貴重な贈り物を数多く与えたが、王国はヨラムに与えた。彼が長男だったからである。'),
('JPN', '历代志下', 14, 21, 4, 'ヨラムは父の王国の上に立つと、勢力を増し加え、その兄弟たちをすべて剣にかけて殺し、イスラエルの首長たち数人も殺した。'),
('JPN', '历代志下', 14, 21, 5, 'ヨラムは三十二歳で王となり、エルサレムで八年間、王であった。'),
('JPN', '历代志下', 14, 21, 6, '彼はアハブの家の者がしたように、イスラエルの王たちの道に歩んだ。アハブの娘が彼の妻だったからである。彼は主の目に悪であることを行った。'),
('JPN', '历代志下', 14, 21, 7, 'しかし、主はダビデと結ばれた契約のゆえに、ダビデの家を滅ぼすことを望まれなかった。主はダビデとその子孫に常にともしびを与えると約束されたからである。'),
('JPN', '历代志下', 14, 21, 8, 'ヨラムの時代に、エドムが背いてユダの支配から脱し、自分たちの上に王を立てた。'),
('JPN', '历代志下', 14, 21, 9, 'ヨラムは、彼の高官たちとともに、すべての戦車を率いて渡って行き、夜襲を試みて、彼を包囲していたエドムと戦車隊長たちを討った。'),
('JPN', '历代志下', 14, 21, 10, 'それでも、エドムは背いてユダの支配から脱した。今日もそうである。リブナもそのときに背いてユダの支配から脱しようとした。ヨラムが父祖の神、主を捨てたからである。'),
('JPN', '历代志下', 14, 21, 11, 'また、彼はユダの山々に高き所を造り、エルサレムの住民に淫行を行わせて、ユダを迷わせた。'),
('JPN', '历代志下', 14, 21, 12, '預言者エリヤから、次のような書状が彼のもとに届いた。「あなたの父祖ダビデの神、主は、こう言われる。『あなたが、あなたの父ヨシャファテの道にも、ユダの王アサの道にも歩まず、'),
('JPN', '历代志下', 14, 21, 13, 'イスラエルの王たちの道に歩み、アハブの家が淫行を行わせたように、ユダとエルサレムの住民に淫行を行わせ、また、あなたよりも善良な、あなたの父の家の兄弟たちを殺したので、'),
('JPN', '历代志下', 14, 21, 14, '見よ。主は大きな災害をもって、あなたの民、あなたの子たち、あなたの妻たち、そしてあなたの全財産を打つ。'),
('JPN', '历代志下', 14, 21, 15, 'あなた自身は、悪性の内臓の病気をわずらい、ついにはその病のために、日に日に内臓が外に出て来るようになる。』」'),
('JPN', '历代志下', 14, 21, 16, '主は、クシュ人の近くにいたペリシテ人とアラビア人の霊を奮い立たせて、ヨラムに敵対させたので、'),
('JPN', '历代志下', 14, 21, 17, '彼らはユダに攻め上って侵略し、王宮で見つかったすべての財産をはじめとして彼の子や妻たちまでも奪い去った。そのため、彼には末子のエホアハズのほか、息子は一人も残らなかった。'),
('JPN', '历代志下', 14, 21, 18, 'これらすべてのことの後、主は不治の内臓の病で彼を打たれた。'),
('JPN', '历代志下', 14, 21, 19, '年は巡り、二年の終わりが来ると、彼の内臓は病のために外に出てしまい、ついに彼は重い病で死んだ。民は、彼の父祖たちのために香をたいたようには、彼のために香をたくことはしなかった。'),
('JPN', '历代志下', 14, 21, 20, '彼は三十二歳で王となり、エルサレムで八年間、王であった。彼は惜しまれることなく世を去った。人々は彼をダビデの町に葬ったが、王たちの墓には納めなかった。'),
('JPN', '历代志下', 14, 22, 1, 'エルサレムの住民は、彼の末子アハズヤを彼の代わりに王とした。アラビア人とともに陣営に攻めて来た略奪隊が、年長の子らをすべて殺してしまったからである。こうしてユダの王ヨラムの子アハズヤが王となった。'),
('JPN', '历代志下', 14, 22, 2, 'アハズヤは四十二歳で王となり、エルサレムで一年間、王であった。彼の母の名はアタルヤといい、オムリの孫娘であった。'),
('JPN', '历代志下', 14, 22, 3, '彼もまた、アハブの家の道に歩んだ。彼の母が助言者となり、悪を行わせたのである。'),
('JPN', '历代志下', 14, 22, 4, '彼はアハブの家に倣って主の目に悪であることを行った。父の死後、アハブの家の者が助言者となり、彼を滅びに至らせたのである。'),
('JPN', '历代志下', 14, 22, 5, '彼はまた、彼らの助言にしたがって、イスラエルの王アハブの子ヨラムとともに、アラムの王ハザエルと戦うため、ラモテ・ギルアデに行った。アラム人はヨラムを討った。'),
('JPN', '历代志下', 14, 22, 6, 'ヨラムは、アラムの王ハザエルと戦ったときにラマで負った傷を癒やすため、イズレエルに帰った。ユダの王ヨラムの子アハズヤは、アハブの子ヨラムが弱っていたので、彼を見舞いにイズレエルに下って行った。'),
('JPN', '历代志下', 14, 22, 7, 'アハズヤがヨラムのもとに行って滅びたのは、神から出たことであった。彼はそこに着くと、ヨラムとともにニムシの子エフーのところに出て行った。このエフーは、主がアハブの家を絶ち滅ぼすために油を注がれた人であった。'),
('JPN', '历代志下', 14, 22, 8, 'エフーはアハブの家にさばきを行い、アハズヤに仕えていたユダの首長たちとアハズヤの兄弟の子たちを見つけて、彼らを殺した。'),
('JPN', '历代志下', 14, 22, 9, '彼はアハズヤを捜した。アハズヤは、サマリアに身を隠していたところを捕らえられた。人々は彼をエフーのもとに引いて来て殺したが、「これは心を尽くして主を求めたヨシャファテの子である」と言って、彼を葬った。こうして、アハズヤの家は王国を治める者を失った。'),
('JPN', '历代志下', 14, 22, 10, 'アハズヤの母アタルヤは、自分の子が死んだと知ると、ただちにユダの家に属する王の一族全員を滅ぼした。'),
('JPN', '历代志下', 14, 22, 11, 'しかし、王の娘エホシェバは、殺される王の子たちの中からアハズヤの子ヨアシュをこっそり連れ出し、寝具をしまう小部屋にその子とその乳母を入れた。祭司エホヤダの妻でアハズヤの妹である、ヨラム王の娘エホシェバが、ヨアシュをアタルヤから隠したので、アタルヤは彼を殺せなかった。'),
('JPN', '历代志下', 14, 22, 12, 'ヨアシュはこの人々とともに、神の宮に六年間、身を隠していた。その間、アタルヤが国を治めていた。'),
('JPN', '历代志下', 14, 23, 1, '七年目に、エホヤダは奮い立って、百人隊の長たち、すなわち、エロハムの子アザルヤ、ヨハナンの子イシュマエル、オベデの子アザルヤ、アダヤの子マアセヤ、ジクリの子エリシャファテを連れて来て、自分と契約を結ばせた。'),
('JPN', '历代志下', 14, 23, 2, '彼らはユダを行き巡り、ユダのすべての町からレビ人とイスラエルの氏族のかしらたちを集めたので、その人たちはエルサレムに来た。'),
('JPN', '历代志下', 14, 23, 3, '全会衆は神の宮で王と契約を結んだ。エホヤダは彼らに言った。「見よ。主がダビデの子孫について約束されたとおり、王の子が王となる。'),
('JPN', '历代志下', 14, 23, 4, 'あなたがたのなすべきことはこうだ。あなたがた祭司とレビ人のうち、安息日に務めに当たる者の三分の一は、入り口の門衛となる。'),
('JPN', '历代志下', 14, 23, 5, '三分の一は王宮に、もう三分の一は礎の門に、そして、すべての民は主の宮の庭にいるように。'),
('JPN', '历代志下', 14, 23, 6, '祭司と奉仕に当たるレビ人たちしか、主の宮に入ってはならない。彼らは聖別されているので、入ってよい。すべての民は主への務めを果たさなければならない。'),
('JPN', '历代志下', 14, 23, 7, 'レビ人は、それぞれ武器を手にして王の周りを囲め。宮に入って来る者は殺されなければならない。あなたがたは、王が入るときにも出るときにも、王とともにいなさい。」'),
('JPN', '历代志下', 14, 23, 8, 'レビ人およびそのユダの人たちはみな、すべて祭司エホヤダが命じたとおりに行った。彼らは、それぞれ自分の部下たちを、安息日に務めに当たる者も、安息日に務めに当たらない者も連れて来た。祭司エホヤダが組分けの任を解かなかったのである。'),
('JPN', '历代志下', 14, 23, 9, '祭司エホヤダは百人隊の長たちに、神の宮にあったダビデ王の槍、大盾、丸い小盾を与えた。'),
('JPN', '历代志下', 14, 23, 10, 'また、すべての民一人ひとりの手に投げ槍を持たせて、神殿の右側から神殿の左側まで、祭壇と神殿に向かって王の周りに立たせた。'),
('JPN', '历代志下', 14, 23, 11, '彼らは王の子を連れ出し、王冠をかぶらせ、さとしの書を渡して、彼を王と宣言した。そしてエホヤダとその子たちが彼に油を注いで、「王様万歳」と叫んだ。'),
('JPN', '历代志下', 14, 23, 12, 'アタルヤは、王をほめたたえている民と近衛兵の声を聞いて、主の宮の民のところに行った。'),
('JPN', '历代志下', 14, 23, 13, '彼女が見ると、なんと、王が入り口の柱のそばに立ち、王の傍らに隊長たちやラッパ奏者たちがいて、民衆がみな喜んでラッパを吹き鳴らしていた。歌い手たちは楽器を手にして賛美の指揮をしていた。アタルヤは自分の衣を引き裂き、「謀反だ、謀反だ」と叫んだ。'),
('JPN', '历代志下', 14, 23, 14, '祭司エホヤダは、部隊を委ねられた百人隊の長たちを呼び出して、彼らに言った。「この女を列の間から連れ出せ。この女に従って来る者は剣で殺せ。」祭司が「この女を主の宮で殺してはならない」と言ったからである。'),
('JPN', '历代志下', 14, 23, 15, '彼らは彼女を取り押さえた。彼女が馬の門の出入り口を通って王宮に着くと、彼らは彼女をそこで殺した。'),
('JPN', '历代志下', 14, 23, 16, 'エホヤダは、彼と、すべての民および王との間で、彼らが主の民となるという契約を結ばせた。'),
('JPN', '历代志下', 14, 23, 17, '民はみなバアルの神殿に行って、それを打ち壊した。彼らはその祭壇と像を打ち砕き、バアルの祭司マタンを祭壇の前で殺した。'),
('JPN', '历代志下', 14, 23, 18, 'エホヤダは主の宮に管理人を置き、それをレビ人の祭司たちに委ねた。彼らは、ダビデが組分けをして主の宮に配属した人々であり、ダビデの指示に基づいて、喜びと歌をもって、モーセの律法に記されているとおりに主の全焼のささげ物を献げる人々であった。'),
('JPN', '历代志下', 14, 23, 19, 'また彼は、主の宮の門に門衛たちを立て、汚れた者が、どんな理由があっても入れないようにした。'),
('JPN', '历代志下', 14, 23, 20, '彼は、百人隊の長たち、貴族たち、民の君主たち、および民衆すべてを率いて、王を主の宮から連れて下った。彼らは上の門を通って王宮に入り、王を王国の座に着かせた。'),
('JPN', '历代志下', 14, 23, 21, '民衆はみな喜んだ。アタルヤは剣で殺され、この町は平穏となった。'),
('JPN', '历代志下', 14, 24, 1, 'ヨアシュは七歳で王となり、エルサレムで四十年間、王であった。彼の母の名はツィブヤといい、ベエル・シェバ出身であった。'),
('JPN', '历代志下', 14, 24, 2, 'ヨアシュは、祭司エホヤダが生きている間は、主の目にかなうことを行った。'),
('JPN', '历代志下', 14, 24, 3, 'エホヤダは彼に二人の妻を迎えさせた。息子たちと娘たちが彼に生まれた。'),
('JPN', '历代志下', 14, 24, 4, 'その後のことであった。ヨアシュは主の宮を新しくすることを志し、'),
('JPN', '历代志下', 14, 24, 5, '祭司とレビ人を集めて、彼らに言った。「ユダの町々へ出て行き、あなたがたの神の宮を毎年修繕するために、全イスラエルから金を集めて来なさい。あなたがたは急いでそのことをしなければならない。」ところが、レビ人は急がなかった。'),
('JPN', '历代志下', 14, 24, 6, 'そこで王は、かしらであるエホヤダを呼んで、彼に言った。「なぜあなたはレビ人に要求して、主のしもべモーセとイスラエルの会衆があかしの天幕のために定めた税金を、ユダとエルサレムから持って来させないのですか。」'),
('JPN', '历代志下', 14, 24, 7, 'それは、悪女アタルヤとその子らが、神の宮に押し入り、主の宮の聖なるものをすべてバアルの神々のために用いていたからである。'),
('JPN', '历代志下', 14, 24, 8, '王が命令すると、人々は一つの箱を作り、それを主の宮の門の外側に置いた。'),
('JPN', '历代志下', 14, 24, 9, '彼らは、神のしもべモーセが荒野でイスラエルに定めた税金を主のもとに持って来るように、ユダとエルサレムに布告した。'),
('JPN', '历代志下', 14, 24, 10, 'すべての首長たちとすべての民は喜んでそれを持って来て、あふれるまで箱に投げ入れた。'),
('JPN', '历代志下', 14, 24, 11, 'その箱がレビ人によって王の役所に運ばれるたびに、多くの金額があることが確認されると、王の書記と祭司のかしらに仕える管理人が来て箱を空にした。そして、それを持って行って元の場所に戻した。彼らは毎日このように行い、多くの献金を集めた。'),
('JPN', '历代志下', 14, 24, 12, '王とエホヤダは、これを主の宮の奉仕の働きをする者に渡した。彼らは、主の宮を新しくするために石切り工と大工を雇い、さらに、主の宮を修繕するために鉄と青銅の職人を雇った。'),
('JPN', '历代志下', 14, 24, 13, '仕事をする者は仕事をし、彼らの手によって修復作業が進んだ。彼らは、神の宮を元のとおりに建て、これを補強した。'),
('JPN', '历代志下', 14, 24, 14, '工事が終わると、彼らは残った金を王とエホヤダの前に持って来た。その金で、主の宮の用具、すなわち、儀式や全焼のささげ物の用具、深皿、金銀の器が作られた。エホヤダが生きている間、主の宮では絶えず全焼のささげ物が献げられた。'),
('JPN', '历代志下', 14, 24, 15, 'エホヤダは老年を迎え、長寿を全うして死んだ。死んだとき、彼は百三十歳であった。'),
('JPN', '历代志下', 14, 24, 16, '彼はダビデの町に王たちとともに葬られた。彼がイスラエルにおいて、神とその宮に対して良いことを行ったからである。'),
('JPN', '历代志下', 14, 24, 17, 'エホヤダの死後、ユダの首長たちが来て、王を伏し拝んだ。それで、王は彼らの言うことを聞き入れた。'),
('JPN', '历代志下', 14, 24, 18, '彼らは父祖の神、主の宮を捨て、アシェラと偶像に仕えた。彼らのこの罪過のゆえに、御怒りがユダとエルサレムの上に下った。'),
('JPN', '历代志下', 14, 24, 19, '彼らを主に立ち返らせるため、預言者たちが彼らの中に遣わされた。預言者たちは彼らを戒めたが、彼らは耳を貸さなかった。'),
('JPN', '历代志下', 14, 24, 20, '神の霊が祭司エホヤダの子ゼカリヤをおおった。彼は民よりも高いところに立って、彼らに言った。「神はこう仰せられる。『あなたがたは、なぜ主の命令を破り、繁栄を逃がすのか。』あなたがたが主を捨てたので、主もあなたがたを捨てられた。」'),
('JPN', '历代志下', 14, 24, 21, 'ところが、彼らは彼に対して陰謀を企て、王の命令によって、主の宮の庭で彼を石で打ち殺した。'),
('JPN', '历代志下', 14, 24, 22, 'ヨアシュ王は、ゼカリヤの父エホヤダが自分に尽くしてくれた誠意を心に留めず、かえってその子を殺した。ゼカリヤは死ぬとき、「主がご覧になって、責任を問われますように」と言った。'),
('JPN', '历代志下', 14, 24, 23, '年が改まるころ、アラムの軍勢がヨアシュに向かって攻め上り、ユダとエルサレムに来て、民の中から民の指導者たちをすべて滅ぼした。そして、分捕り物をすべてダマスコの王のもとに送った。'),
('JPN', '历代志下', 14, 24, 24, 'アラムの軍勢は少数で来たが、主が非常に大きな軍勢を彼らの手に渡されたのであった。それは、人々が、その父祖の神、主を捨てたからである。こうして、ヨアシュにさばきが下された。'),
('JPN', '历代志下', 14, 24, 25, '軍勢が、重傷を負ったヨアシュを捨てて離れて行ったとき、彼の家来たちは、祭司エホヤダの息子たちの血のゆえに謀反を企て、寝台の上で彼を殺した。彼は死んで、人々は彼をダビデの町に葬ったが、王たちの墓には葬らなかった。'),
('JPN', '历代志下', 14, 24, 26, '彼に謀反を企てたのは次の者たちである。アンモン人の女シムアテの子ザバデ、モアブ人の女シムリテの子エホザバデ。'),
('JPN', '历代志下', 14, 24, 27, 'ヨアシュの子たちのこと、彼について語られた多くの預言のこと、神の宮の修復のことは、『王の書の注解』にまさしく記されている。彼の子アマツヤが代わって王となった。'),
('JPN', '历代志下', 14, 25, 1, 'アマツヤは二十五歳で王となり、エルサレムで二十九年間、王であった。彼の母の名はエホアダンといい、エルサレム出身であった。'),
('JPN', '历代志下', 14, 25, 2, '彼は主の目にかなうことを行ったが、全き心をもってではなかった。'),
('JPN', '历代志下', 14, 25, 3, '彼の王国が強くなると、彼は、自分の父である王を討った家来たちを殺した。'),
('JPN', '历代志下', 14, 25, 4, 'しかし、彼らの子どもたちは殺さなかった。モーセの書の律法に記されているところに従ったのである。主はその中でこう命じておられた。「父が子のゆえに殺されてはならない。子が父のゆえに殺されてはならない。人が死ぬのは、自分の罪過のゆえでなければならない。」'),
('JPN', '历代志下', 14, 25, 5, 'アマツヤはユダの人々を召集し、ユダ族およびベニヤミン族の全員を、父祖の家ごとに、千人隊の長、百人隊の長の下に配属した。二十歳以上の者を登録すると、槍と大盾を手にして従軍する兵が三十万人いることが分かった。'),
('JPN', '历代志下', 14, 25, 6, 'さらに、彼はイスラエルから、銀百タラントで十万人の勇士を雇った。'),
('JPN', '历代志下', 14, 25, 7, 'すると、神の人が彼のもとに来て言った。「王よ、イスラエルの軍勢をあなたとともに行かせてはなりません。主は、イスラエル、すなわちエフライムのいかなる人々とも、ともにおられないからです。'),
('JPN', '历代志下', 14, 25, 8, 'しかし、もしあなたが行くのなら、そうしなさい。雄々しく戦いなさい。神はあなたを敵の前につまずかせられます。神には、助ける力も、つまずかせる力もあるからです。」'),
('JPN', '历代志下', 14, 25, 9, 'アマツヤは神の人に言った。「では、イスラエルの部隊に与えた百タラントはどうしたらよいのか。」神の人は答えた。「主は、それよりも多くのものを、あなたにお与えになることができます。」'),
('JPN', '历代志下', 14, 25, 10, 'そこでアマツヤは、エフライムから彼のもとに来た部隊を、もとのところに帰すために切り離した。彼らはユダに対して激しく怒り、怒りに燃えながら自分たちのところへ帰って行った。'),
('JPN', '历代志下', 14, 25, 11, 'アマツヤは奮い立ち、自分の兵を率いて塩の谷へ行き、セイルの者たち一万人を討った。'),
('JPN', '历代志下', 14, 25, 12, 'ユダの人々は一万人を生け捕りにして、崖の上に連れて行き、その崖の上から彼らを投げ落とした。彼らは一人残らず砕かれてしまった。'),
('JPN', '历代志下', 14, 25, 13, 'アマツヤが自分とともに戦いに行かせずに帰した部隊の者たちは、サマリアからベテ・ホロンに及ぶユダの町々を襲い、三千人を打ち殺し、多くの物を略奪した。'),
('JPN', '历代志下', 14, 25, 14, 'アマツヤがエドム人を討って帰って来た後のこと、彼はセイル人の神々を持って来て、それらを自分の神々として立てた。彼はその前で伏し拝み、犠牲を供えていた。'),
('JPN', '历代志下', 14, 25, 15, 'すると、主はアマツヤに向かって怒りを燃やし、彼のもとに預言者を遣わして言われた。「なぜあなたは、あなたの手から自分の民を救い出すこともできないような神々を求めたのか。」'),
('JPN', '历代志下', 14, 25, 16, '彼が王にまだ話している最中に、王は彼に言った。「われわれはおまえを王の助言者にしたか。やめよ。なぜ、打ち殺されるようなことをするのか。」そこで、預言者は話すのをやめたが、こう言った。「私は、神があなたを滅ぼそうと計画しておられるのを知りました。あなたがこのことを行い、私の勧めを聞かなかったからです。」'),
('JPN', '历代志下', 14, 25, 17, 'ユダの王アマツヤは、協議の上で、エフーの子エホアハズの子、イスラエルの王ヨアシュに使者を送って言った。「さあ、直接、対決しようではないか。」'),
('JPN', '历代志下', 14, 25, 18, 'イスラエルの王ヨアシュは、ユダの王アマツヤに使者を送って言った。「レバノンのあざみが、レバノンの杉に使者を送って、『あなたの娘を私の息子の妻にくれないか』と言ったが、レバノンの野の獣が通り過ぎて、そのあざみを踏みにじった。'),
('JPN', '历代志下', 14, 25, 19, 'あなたは、『どうだ、自分はエドムを討った』と言って、心高ぶり、誇っている。今は自分の家にとどまっていなさい。なぜ、あえてわざわいを引き起こし、あなたもユダもともに倒れようとするのか。」'),
('JPN', '历代志下', 14, 25, 20, 'しかし、アマツヤは聞き入れなかった。それは神から出たことであって、彼らを敵の手に渡すためであった。彼らがエドムの神々を求めたからである。'),
('JPN', '历代志下', 14, 25, 21, 'イスラエルの王ヨアシュは攻め上った。彼とユダの王アマツヤは、ユダのベテ・シェメシュで直接、対決した。'),
('JPN', '历代志下', 14, 25, 22, 'ユダはイスラエルに打ち負かされ、それぞれ自分の天幕に逃げ帰った。'),
('JPN', '历代志下', 14, 25, 23, 'イスラエルの王ヨアシュは、エホアハズの子ヨアシュの子、ユダの王アマツヤをベテ・シェメシュで捕らえ、エルサレムに引いて来た。そして、エルサレムの城壁をエフライムの門から隅の門まで、四百キュビトにわたって打ち壊した。'),
('JPN', '历代志下', 14, 25, 24, 'また、オベデ・エドムが管理している神の宮にあったすべての金と銀、すべての器、王宮の財宝、および人質を取ってサマリアに帰った。'),
('JPN', '历代志下', 14, 25, 25, 'ユダの王ヨアシュの子アマツヤは、イスラエルの王エホアハズの子ヨアシュの死後、なお十五年生きた。'),
('JPN', '历代志下', 14, 25, 26, 'アマツヤについてのその他の事柄、それは最初から最後まで、『ユダとイスラエルの王の書』に確かに記されている。'),
('JPN', '历代志下', 14, 25, 27, 'アマツヤが主に従うことから離れたとき、エルサレムで人々が彼に対して謀反を企てた。彼はラキシュに逃げたが、人々はラキシュに追っ手を送り、そこで彼を殺した。'),
('JPN', '历代志下', 14, 25, 28, '彼らは彼を馬に乗せて運び、ユダの町に先祖とともに葬った。'),
('JPN', '历代志下', 14, 26, 1, 'ユダの民はみな、当時十六歳であったウジヤを立てて、その父アマツヤの代わりに王とした。'),
('JPN', '历代志下', 14, 26, 2, '彼は、アマツヤが先祖とともに眠りについた後、エイラトを築き直し、それをユダに復帰させた。'),
('JPN', '历代志下', 14, 26, 3, 'ウジヤは十六歳で王となり、エルサレムで五十二年間、王であった。彼の母の名はエコルヤといい、エルサレム出身であった。'),
('JPN', '历代志下', 14, 26, 4, '彼は、すべて父アマツヤが行ったとおりに、主の目にかなうことを行った。'),
('JPN', '历代志下', 14, 26, 5, '神を認めることを教えたゼカリヤが生きていた間、彼は神を求めた。また彼が主を求めていた間、神は彼を栄えるようにされた。'),
('JPN', '历代志下', 14, 26, 6, '彼は出陣してペリシテ人と戦い、ガテの城壁、ヤブネの城壁、アシュドデの城壁を打ち壊し、アシュドデをはじめとするペリシテ人の領土に町々を建てた。'),
('JPN', '历代志下', 14, 26, 7, '神は彼を助けて、ペリシテ人、グル・バアルに住むアラビア人、メウニム人に立ち向かわせられた。'),
('JPN', '历代志下', 14, 26, 8, 'アンモン人はウジヤのもとに貢ぎ物を納めた。こうして、彼の名はエジプトの境にまで届いた。その勢力がこの上なく強くなったからである。'),
('JPN', '历代志下', 14, 26, 9, 'ウジヤはエルサレムの隅の門、谷の門、および城壁の角の上にやぐらを建て、これを強固にした。'),
('JPN', '历代志下', 14, 26, 10, '彼はまた、荒野にやぐらを建て、多くの水溜めを掘った。シェフェラにも平野にも多くの家畜を持っていたからである。山地や果樹園には農夫やぶどう作りがいた。彼は農業を好んだのである。'),
('JPN', '历代志下', 14, 26, 11, 'さらに、ウジヤには常時戦いに備える部隊があった。それは書記エイエルとつかさマアセヤによって登録された人数にしたがって各隊に配属され、王の隊長の一人ハナンヤの指揮下にあった。'),
('JPN', '历代志下', 14, 26, 12, '勇士である一族のかしらたちの総数は、二千六百人であった。'),
('JPN', '历代志下', 14, 26, 13, 'その指揮下には三十万七千五百人の軍勢があり、王を助けて敵に当たる強力な部隊であった。'),
('JPN', '历代志下', 14, 26, 14, 'ウジヤは、その全軍のために、盾、槍、かぶと、よろい、弓、および投石器用の石を用意した。'),
('JPN', '历代志下', 14, 26, 15, 'さらに彼はエルサレムで、巧みに考案された兵器を作り、矢や大石を放つために、やぐらの上や城壁の角の上に据えた。こうして、彼の名声は遠くにまで広まった。彼が驚くべき助けを得て、強くなったからである。'),
('JPN', '历代志下', 14, 26, 16, 'しかし、彼が強くなると、その心は高ぶり、ついに身に滅びを招いた。彼は自分の神、主の信頼を裏切った。香の壇の上で香をたこうとして主の神殿に入ったのである。'),
('JPN', '历代志下', 14, 26, 17, 'すると、彼の後から祭司アザルヤが、主に仕える八十人の勇敢な祭司たちとともに入って来た。'),
('JPN', '历代志下', 14, 26, 18, '彼らはウジヤ王の前に立ちふさがって言った。「ウジヤよ。主に香をたくのはあなたのすることではありません。香をたくのは、聖別された祭司たち、アロンの子らのすることです。聖所から出てください。あなたは主の信頼を裏切りました。あなたには、神である主の誉れは与えられません。」'),
('JPN', '历代志下', 14, 26, 19, 'ウジヤは激しく怒った。香をたくための香炉を手にしていたが、彼が祭司たちに対して激しく怒ったとき、主の神殿の中にいた祭司たちの前、香の壇の傍らで、彼の額にツァラアトが現れた。'),
('JPN', '历代志下', 14, 26, 20, '祭司の長アザルヤと祭司たち全員が彼の方を見ると、なんと、彼の額がツァラアトに冒されていた。そこで彼らは、急いで彼をそこから連れ出した。彼自身も急いで出て行った。主が彼を打たれたからである。'),
('JPN', '历代志下', 14, 26, 21, 'ウジヤ王は死ぬ日までツァラアトに冒され、ツァラアトに冒された者として隔離された家に住んだ。彼が主の宮から断たれたからである。その子ヨタムが王宮を管理し、民衆をさばいた。'),
('JPN', '历代志下', 14, 26, 22, 'ウジヤについてのその他の事柄は、最初から最後まで、アモツの子、預言者イザヤが書き記した。'),
('JPN', '历代志下', 14, 26, 23, 'ウジヤは彼の先祖とともに眠りについた。人々は彼を王たちの墓地の野に先祖とともに葬った。彼がツァラアトに冒された者だと言われていたからである。彼の子ヨタムが代わって王となった。'),
('JPN', '历代志下', 14, 27, 1, 'ヨタムは二十五歳で王となり、エルサレムで十六年間、王であった。彼の母の名はエルシャといい、ツァドクの娘であった。'),
('JPN', '历代志下', 14, 27, 2, '彼は、すべて父ウジヤが行ったとおりに、主の目にかなうことを行った。ただし、主の神殿に入ることはしなかった。民は依然として滅びに向かっていた。'),
('JPN', '历代志下', 14, 27, 3, '彼は主の宮の上の門を建てた。また、オフェルの城壁の上に多くのものを建てた。'),
('JPN', '历代志下', 14, 27, 4, '彼はユダの山地に町々を建て、森林地帯には城塞とやぐらを築いた。'),
('JPN', '历代志下', 14, 27, 5, '彼はアンモン人の王と戦い、彼らに打ち勝った。その年、アンモン人は銀百タラント、小麦一万コル、大麦一万コルを彼に贈った。アンモン人はこれだけのものを彼に納め、二年目も三年目も同じようにした。'),
('JPN', '历代志下', 14, 27, 6, 'ヨタムは勢力を増し加えた。彼が、自分の神、主の前に、自分の道を確かなものとしたからである。'),
('JPN', '历代志下', 14, 27, 7, 'ヨタムについてのその他の事柄、彼の戦いと彼の行いは、『イスラエルとユダの王の書』にまさしく記されている。'),
('JPN', '历代志下', 14, 27, 8, '彼は二十五歳で王となり、エルサレムで十六年間、王であった。'),
('JPN', '历代志下', 14, 27, 9, 'ヨタムは先祖とともに眠りにつき、人々は彼をダビデの町に葬った。彼の子アハズが代わって王となった。'),
('JPN', '历代志下', 14, 28, 1, 'アハズは二十歳で王となり、エルサレムで十六年間、王であった。彼はその父祖ダビデとは違って、主の目にかなうことを行わず、'),
('JPN', '历代志下', 14, 28, 2, 'イスラエルの王たちの道に歩み、そのうえ、バアルの神々のために鋳物の像を造った。'),
('JPN', '历代志下', 14, 28, 3, '彼は、ベン・ヒノムの谷で犠牲を供え、主がイスラエルの子らの前から追い払われた異邦の民の、忌み嫌うべき慣わしをまねて、自分の子どもたちに火の中を通らせた。'),
('JPN', '历代志下', 14, 28, 4, '彼は高き所、丘の上、青々と茂るあらゆる木の下で、いけにえを献げ、犠牲を供えた。'),
('JPN', '历代志下', 14, 28, 5, '彼の神、主が彼をアラムの王の手に渡されたので、彼らは彼を討ち、彼のところから多くの者を捕虜にしてダマスコへ連れ去った。また、彼はイスラエルの王の手にも渡されたので、イスラエルの王は彼を討って大損害を与えた。'),
('JPN', '历代志下', 14, 28, 6, 'レマルヤの子ペカは、ユダで一日のうちに十二万人を殺した。みな勇士たちであった。彼らがその父祖の神、主を捨てたからである。'),
('JPN', '历代志下', 14, 28, 7, 'エフライムの勇士ジクリは、王の子マアセヤ、王の家の長アズリカム、王の補佐官エルカナを殺した。'),
('JPN', '历代志下', 14, 28, 8, 'イスラエルの人々は、自分の同胞の中から、女たち、男女の子どもたち二十万人を捕虜にし、また、彼らから多くの物を略奪して、分捕り物をサマリアに持って行った。'),
('JPN', '历代志下', 14, 28, 9, 'そこには主の預言者で、その名をオデデという者がいた。この人はサマリアに入って来た軍隊の前に進み出て言った。「見よ。あなたがたの父祖の神、主がユダに対して憤られたため、主はあなたがたの手に彼らを渡された。ところが、あなたがたは天に届くほどの激しい怒りをもって彼らを殺した。'),
('JPN', '历代志下', 14, 28, 10, '今、あなたがたはユダとエルサレムの人々を従わせて、自分たちの男女の奴隷にしようとしている。ただ、あなたがた自身も、あなたがたの神、主に対して罪過があるのではないか。'),
('JPN', '历代志下', 14, 28, 11, '今、私に聞きなさい。あなたがたの同胞の中から捕らえた捕虜を帰しなさい。主の燃える怒りがあなたがたに臨んでいるからだ。」'),
('JPN', '历代志下', 14, 28, 12, 'そのとき、エフライムの人々のかしらたちの中から、ヨハナンの子アザルヤ、メシレモテの子ベレクヤ、シャルムの子ヒゼキヤ、ハデライの子アマサが、戦いから帰って来た者たちに対して立ち上がり、'),
('JPN', '历代志下', 14, 28, 13, '彼らに言った。「捕虜をここに連れて来てはならない。私たちを、主に対して罪過ある者とするようなことをあなたがたは考えて、私たちの罪と罪過を増し加えようとしている。私たちの罪過はすでに大きく、燃える怒りがイスラエルの上に臨んでいるからだ。」'),
('JPN', '历代志下', 14, 28, 14, 'そこで、武装した者たちは、首長たちと全会衆の前で、捕虜と略奪した物を手放した。'),
('JPN', '历代志下', 14, 28, 15, '指名された人々は立ち上がり、捕虜を引き受け、彼らの中で裸の者にはみな、分捕り物の中から衣服を取って着せた。彼らは捕虜に衣服を着せ、履き物を与え、食べさせ、飲ませ、油を塗り、また、足の弱い者はみなろばに乗せ、なつめ椰子の町エリコにいる兄弟たちのところへ連れて行った。こうして、彼らはサマリアに帰った。'),
('JPN', '历代志下', 14, 28, 16, 'そのとき、アハズ王はアッシリアの王たちに人を遣わして、助けを求めた。'),
('JPN', '历代志下', 14, 28, 17, 'エドム人も再び攻めて来て、ユダを打ち、捕虜を捕らえて行った。'),
('JPN', '历代志下', 14, 28, 18, 'ペリシテ人は、ユダのシェフェラおよびネゲブにある町々を襲い、ベテ・シェメシュ、アヤロン、ゲデロテ、およびソコとそれに属する村々、ティムナとそれに属する村々、ギムゾとそれに属する村々を取って、そこに住んだ。'),
('JPN', '历代志下', 14, 28, 19, 'これは、主がイスラエルの王アハズのゆえにユダを低くされたためである。彼がユダにおいて好き勝手にふるまい、甚だしく主の信頼を裏切ったからである。'),
('JPN', '历代志下', 14, 28, 20, 'アッシリアの王ティグラト・ピレセルは彼のところに来たが、彼の力になるどころか、むしろ彼を苦しめた。'),
('JPN', '历代志下', 14, 28, 21, 'アハズは、主の宮、および王と高官たちの家から物を取って、アッシリアの王に贈ったが、何の助けにもならなかった。'),
('JPN', '历代志下', 14, 28, 22, 'アッシリアの王が彼を苦しめたとき、このアハズ王は、さらに主の信頼を裏切った。'),
('JPN', '历代志下', 14, 28, 23, '彼は、自分を打ったダマスコの神々にいけにえを献げて言った。「アラムの王たちの神々は彼らを助けている。この神々に、私もいけにえを献げよう。そうすれば私を助けてくれるだろう。」これらの神々は、彼と全イスラエルをつまずかせるものとなった。'),
('JPN', '历代志下', 14, 28, 24, 'アハズは、神の宮の用具を集めた。彼は神の宮の用具を取り外し、主の宮の戸を閉じ、エルサレムの街角のいたるところに祭壇を造った。'),
('JPN', '历代志下', 14, 28, 25, 'またユダの町という町にはすべて、ほかの神々に犠牲を供えるための高き所を造り、彼の父祖の神、主の怒りを引き起こした。'),
('JPN', '历代志下', 14, 28, 26, 'アハズについてのその他の事柄、彼のすべての行いは、最初から最後まで、『ユダとイスラエルの王の書』にまさしく記されている。'),
('JPN', '历代志下', 14, 28, 27, 'アハズは先祖とともに眠りにつき、人々は彼をエルサレムの都に葬った。彼をイスラエルの王たちの墓に運び入れなかったのである。彼の子ヒゼキヤが代わって王となった。'),
('JPN', '历代志下', 14, 29, 1, 'ヒゼキヤは二十五歳で王となり、エルサレムで二十九年間、王であった。彼の母の名はアビヤといい、ゼカリヤの娘であった。'),
('JPN', '历代志下', 14, 29, 2, '彼は、すべて父祖ダビデが行ったとおりに、主の目にかなうことを行った。'),
('JPN', '历代志下', 14, 29, 3, '彼はその治世の第一年の第一の月に、主の宮の戸を開いてこれらを修理した。'),
('JPN', '历代志下', 14, 29, 4, '彼は祭司とレビ人を連れて来て、東側の広場に集め、'),
('JPN', '历代志下', 14, 29, 5, '彼らに言った。「レビ人よ、聞きなさい。今、あなたがたは自分自身を聖別しなさい。あなたがたの父祖の神、主の宮を聖別し、聖所から忌まわしいものを取り除きなさい。'),
('JPN', '历代志下', 14, 29, 6, 'というのも、私たちの先祖は信頼を裏切り、私たちの神、主の目に悪であることを行い、この方を捨て去り、主の御住まいから顔を背けて背を向けたからです。'),
('JPN', '历代志下', 14, 29, 7, 'また、彼らは玄関の戸を閉じ、ともしびを消し、聖所でイスラエルの神に香をたかず、全焼のささげ物を献げることをしなかったのです。'),
('JPN', '历代志下', 14, 29, 8, 'そこで、主の御怒りがユダとエルサレムの上に下り、あなたがたが自分の目で見るとおり、主は彼らをおののきのもと、恐怖のもと、また嘲りの的とされました。'),
('JPN', '历代志下', 14, 29, 9, '見なさい。このため私たちの先祖は剣に倒れ、私たちの息子たち、娘たち、妻たちは、捕虜になっています。'),
('JPN', '历代志下', 14, 29, 10, '今、私の願いは、イスラエルの神、主と契約を結ぶことです。そうすれば、主の燃える怒りが私たちから離れるでしょう。'),
('JPN', '历代志下', 14, 29, 11, '子たちよ、今、手をこまねいていてはなりません。主はあなたがたを選んでご自分の前に立って仕えさせ、ご自分に奉仕する者、香をたく者とされたからです。」'),
('JPN', '历代志下', 14, 29, 12, 'そこで、レビ人は立ち上がった。ケハテの子孫からはアマサイの子マハテとアザルヤの子ヨエル、メラリの子孫からはアブディの子キシュとエハレルエルの子アザルヤ、ゲルションの子孫からはジンマの子ヨアフとヨアフの子エデン、'),
('JPN', '历代志下', 14, 29, 13, 'エリツァファンの子孫からはシムリとエイエル、アサフの子孫からはゼカリヤとマタンヤ、'),
('JPN', '历代志下', 14, 29, 14, 'ヘマンの子孫からはエヒエルとシムイ、エドトンの子孫からはシェマヤとウジエルであった。'),
('JPN', '历代志下', 14, 29, 15, 'こうして、彼らは自分の兄弟たちを集め、身を聖別して、主のことばによる王の命令のとおりに、主の宮をきよめに来た。'),
('JPN', '历代志下', 14, 29, 16, '祭司たちは主の宮の内側に入って、これをきよめた。彼らが、主の神殿にあった汚れたものをみな主の宮の庭に出すと、レビ人が受け取って、外のキデロンの谷へ持って行った。'),
('JPN', '历代志下', 14, 29, 17, '彼らは第一の月の一日に聖別し始めた。その月の八日に主の玄関に入り、八日間にわたって主の宮を聖別し、第一の月の十六日に終えた。'),
('JPN', '历代志下', 14, 29, 18, 'そこで、彼らは中に入り、ヒゼキヤ王のところに行って言った。「私たちは主の宮をすべてきよめました。全焼のささげ物の祭壇とそのすべての用具、並べ供えるパンの机とそのすべての備品をきよめました。'),
('JPN', '历代志下', 14, 29, 19, 'また、アハズ王がその治世に信頼を裏切って取り除いたすべての用具を整えて、聖別しました。ご覧ください。それらは主の祭壇の前にあります。」'),
('JPN', '历代志下', 14, 29, 20, 'ヒゼキヤ王は朝早く、この町の長たちを集めて、主の宮に上って行った。'),
('JPN', '历代志下', 14, 29, 21, '彼らは、王国と聖所とユダのために、罪のきよめのささげ物として、雄牛七頭、雄羊七匹、子羊七匹、雄やぎ七匹を引いて来た。王は、祭司であるアロンの子らに命じて、主の祭壇の上でささげ物を献げさせた。'),
('JPN', '历代志下', 14, 29, 22, '彼らは牛を屠り、祭司たちがその血を受け取って祭壇に振りかけた。次に雄羊を屠り、その血を祭壇に振りかけた。次に子羊を屠り、その血を祭壇に振りかけた。'),
('JPN', '历代志下', 14, 29, 23, 'それから、彼らは王および会衆の前に、罪のきよめのささげ物とする雄やぎを引いて来て、それらの上に自分たちの手を置いた。'),
('JPN', '历代志下', 14, 29, 24, '祭司たちはこれらを屠り、その血を祭壇に献げて、罪のきよめのささげ物とし、全イスラエルのために宥めを行った。全焼のささげ物と罪のきよめのささげ物を、王が全イスラエルのために命じたからである。'),
('JPN', '历代志下', 14, 29, 25, 'また、王はレビ人を主の宮に配置し、ダビデおよび王の先見者ガド、預言者ナタンの命令のとおりに、シンバルと琴と竪琴を持たせた。この命令は主から出たものであり、その預言者たちを通して与えられたものだからである。'),
('JPN', '历代志下', 14, 29, 26, 'こうして、レビ人はダビデの楽器を手にし、祭司はラッパを手にして立った。'),
('JPN', '历代志下', 14, 29, 27, 'そこでヒゼキヤは、全焼のささげ物を祭壇で献げるように命じた。全焼のささげ物が献げ始められると、イスラエルの王ダビデの楽器に合わせて、主の歌とラッパが始まった。'),
('JPN', '历代志下', 14, 29, 28, '全会衆は伏し拝み、歌い手は歌い、ラッパ奏者はラッパを吹き鳴らした。このすべては、全焼のささげ物が終わるまで続いた。'),
('JPN', '历代志下', 14, 29, 29, '献げ終えると、王および彼とともにいたすべての者は、膝をかがめて伏し拝んだ。'),
('JPN', '历代志下', 14, 29, 30, 'ヒゼキヤ王と高官たちが、ダビデおよび先見者アサフのことばをもって主を賛美するようにレビ人に命じると、彼らは喜びつつ賛美した。そして、一同はひざまずいて伏し拝んだ。'),
('JPN', '历代志下', 14, 29, 31, 'そのとき、ヒゼキヤは言った。「今、あなたがたは主に身を献げました。近づいて、感謝のささげ物を主の宮に携えて来なさい。」会衆は感謝のささげ物を携えて来た。また、心から進んで献げる者はみな、全焼のささげ物を携えて来た。'),
('JPN', '历代志下', 14, 29, 32, '会衆が携えて来た全焼のささげ物の数は、牛七十頭、雄羊百匹、子羊二百匹であり、これらはみな、主への全焼のささげ物であった。'),
('JPN', '历代志下', 14, 29, 33, 'また、聖なるささげ物は、牛六百頭、羊三千匹であった。'),
('JPN', '历代志下', 14, 29, 34, 'ただ、祭司たちが少なかったので、すべての全焼のささげ物の皮を剝ぎ尽くすことができなかった。そこで、彼らの兄弟に当たるレビ人が、その役目を終えるまで、またほかの祭司たちが身を聖別するまで助けた。レビ人は、祭司たちよりも直ぐな心をもって、身を聖別したのである。'),
('JPN', '历代志下', 14, 29, 35, 'また、多くの全焼のささげ物、その全焼のささげ物に添える交わりのいけにえの脂肪、注ぎのぶどう酒もあった。こうして主の宮の奉仕の用意ができた。'),
('JPN', '历代志下', 14, 29, 36, 'ヒゼキヤとすべての民は、神が民のために備えてくださったことを喜んだ。このことが突然のことだったからである。'),
('JPN', '历代志下', 14, 30, 1, 'ヒゼキヤはイスラエルとユダの全土に人を遣わして、またエフライムとマナセに手紙を書いて、エルサレムにある主の宮に来て、イスラエルの神、主に過越のいけにえを献げるように呼びかけた。'),
('JPN', '历代志下', 14, 30, 2, '王とその高官たちとエルサレムの全会衆は協議して、第二の月に過越のいけにえを献げようと決めた。'),
('JPN', '历代志下', 14, 30, 3, 'というのは、身を聖別した祭司たちが十分な数に達しておらず、民もエルサレムに集まっていなかったので、そのときには献げることができなかったからである。'),
('JPN', '历代志下', 14, 30, 4, 'このことは、王と全会衆の目に良いことに思えたので、'),
('JPN', '历代志下', 14, 30, 5, '彼らはベエル・シェバからダンに至るまで、イスラエル全土に通達を出し、エルサレムに来てイスラエルの神、主に過越のいけにえを献げるよう、呼びかけることを決定した。規定どおりに献げている者が多くなかったからである。'),
('JPN', '历代志下', 14, 30, 6, '急使たちは、王とその高官たちから託された手紙を携えて、イスラエルとユダの全土を行き巡り、王の命令のとおりに告げた。「イスラエルの子らよ、アブラハム、イサク、イスラエルの神、主に立ち返りなさい。そうすれば、主は、アッシリアの王たちの手を逃れて残ったあなたがたのところに、帰って来てくださいます。'),
('JPN', '历代志下', 14, 30, 7, 'あなたがたは、父祖の神、主の信頼を裏切ったあなたがたの父たちや兄弟たちのようになってはなりません。あなたがたが見るとおり、主は彼らを恐怖に渡されました。'),
('JPN', '历代志下', 14, 30, 8, '今、あなたがたは、自分たちの父たちのようにうなじを固くしてはなりません。主に服従しなさい。とこしえに聖別された主の聖所に来て、あなたがたの神、主に仕えなさい。そうすれば、主の燃える怒りがあなたがたから離れるでしょう。'),
('JPN', '历代志下', 14, 30, 9, 'もしあなたがたが主に立ち返るなら、あなたがたの兄弟や子たちは、彼らを捕虜にした人々のあわれみを受け、この地に帰って来るでしょう。あなたがたの神、主は恵み深く、あわれみ深い方であり、あなたがたが主に立ち返るなら、あなたがたから御顔を背けられることはありません。」'),
('JPN', '历代志下', 14, 30, 10, 'こうして急使たちは、エフライムとマナセからゼブルンの地に至るまで、町から町へと行き巡ったが、人々は彼らを笑いものにして嘲った。'),
('JPN', '历代志下', 14, 30, 11, 'ただ、アシェル、マナセ、およびゼブルンの一部の人々は、へりくだってエルサレムに上って来た。'),
('JPN', '历代志下', 14, 30, 12, 'また、ユダには神の御手が臨んで、人々の心を一つにし、主のことばどおり、王とその高官たちの命令が実行された。'),
('JPN', '历代志下', 14, 30, 13, 'こうして、第二の月に多くの民が、種なしパンの祭りを行うためにエルサレムに集まった。それは、おびただしい数の大集団であった。'),
('JPN', '历代志下', 14, 30, 14, '彼らは立ち上がり、エルサレムにあった祭壇を取り除き、すべての香の壇を取り除いて、キデロンの谷に投げ捨てた。'),
('JPN', '历代志下', 14, 30, 15, 'そして、第二の月の十四日に、彼らは過越のいけにえを屠った。祭司とレビ人は恥じて、身を聖別し、全焼のささげ物を主の宮に携えて来た。'),
('JPN', '历代志下', 14, 30, 16, '彼らは神の人モーセの律法のとおり、定めにしたがって、それぞれの持ち場に立った。祭司はレビ人の手から受け取った血を振りかけた。'),
('JPN', '历代志下', 14, 30, 17, '会衆の中には、身を聖別していない者が多かった。そこで、きよくないすべての人々に代わって、レビ人が、過越のいけにえを屠る役目に就かなければならなかった。それらを主に対して聖なるものとするためである。'),
('JPN', '历代志下', 14, 30, 18, '民のうち大勢の者、エフライムとマナセ、イッサカルとゼブルンの多くの者は、身をきよめずに、しかも、記されているのとは異なったやり方で過越のいけにえを食べてしまった。それでヒゼキヤは彼らのために祈った。「いつくしみ深い主よ、彼らをお赦しください。'),
('JPN', '历代志下', 14, 30, 19, '彼らは聖なるもののきよめの規定どおりにいたしませんでしたが、心を定めて神を、彼らの父祖の神、主を求めています。」'),
('JPN', '历代志下', 14, 30, 20, '主はヒゼキヤの願いを聞き、民を癒やされた。'),
('JPN', '历代志下', 14, 30, 21, 'エルサレムにいたイスラエルの子らは、七日の間、大きな喜びをもって種なしパンの祭りを行った。レビ人と祭司たちは、毎日主に向かって力強い調べの楽器を奏でて、主をほめたたえた。'),
('JPN', '历代志下', 14, 30, 22, 'ヒゼキヤは、主への務めによく通じているすべてのレビ人に励ましのことばをかけた。彼らは、交わりのいけにえを献げ、父祖の神、主に告白をしつつ、七日間、祝いの食事にあずかった。'),
('JPN', '历代志下', 14, 30, 23, '全会衆は、さらに七日間祭りを行うことを決め、喜びをもって七日間、祭りを行った。'),
('JPN', '历代志下', 14, 30, 24, 'ユダの王ヒゼキヤは、千頭の雄牛と七千匹の羊を会衆に提供し、高官たちは雄牛千頭と羊一万匹を会衆に提供した。また、多くの祭司が身を聖別した。'),
('JPN', '历代志下', 14, 30, 25, 'こうして、ユダの全会衆、祭司とレビ人、イスラエルから来た全会衆、イスラエルの地から来た寄留者でユダに在住している者たちは、みな喜んだ。'),
('JPN', '历代志下', 14, 30, 26, 'エルサレムには大きな喜びがあった。イスラエルの王、ダビデの子ソロモンの時代以来、エルサレムでこのようなことはなかったからである。'),
('JPN', '历代志下', 14, 30, 27, 'レビ人の祭司たちが立ち上がって民を祝福した。彼らの声は聞き届けられ、彼らの祈りは、主の聖なる御住まいである天に届いた。'),
('JPN', '历代志下', 14, 31, 1, 'これらすべてのことが終わると、そこにいた全イスラエルはユダの町々に出て行き、石の柱を打ち砕き、アシェラ像を切り倒し、ユダ全土とベニヤミン、またエフライムとマナセの中にある高き所と祭壇を徹底的に壊した。そして、すべてのイスラエルの子らは、それぞれ自分の町、自分の所有地へ帰って行った。'),
('JPN', '历代志下', 14, 31, 2, 'ヒゼキヤは祭司とレビ人の組を定め、祭司とレビ人それぞれの組ごとに、その奉仕にしたがって全焼のささげ物と交わりのいけにえを献げさせ、さらに、主の宿営の門で仕え、告白し、賛美させた。'),
('JPN', '历代志下', 14, 31, 3, 'また王は、全焼のささげ物のために、自分の財産から自分の分を出した。すなわち、主の律法に記されているとおりに、朝夕の全焼のささげ物、また安息日、新月の祭り、例祭ごとに献げる全焼のささげ物をした。'),
('JPN', '历代志下', 14, 31, 4, 'さらに彼は、エルサレムに住む民に対して、祭司とレビ人の受ける分を与えるように命じた。祭司とレビ人が主の律法に専念するためであった。'),
('JPN', '历代志下', 14, 31, 5, 'この命令が広まるとともに、イスラエルの子らは、穀物、新しいぶどう酒、油、蜜など、畑のすべての収穫の初物をたくさん持って来た。彼らはすべての物の十分の一を豊富に携えて来た。'),
('JPN', '历代志下', 14, 31, 6, 'ユダの町々に住むイスラエルとユダの人々も、牛や羊の十分の一と、彼らの神、主に聖別した聖なるささげ物の十分の一を携えて来て、いくつもの山に積み上げた。'),
('JPN', '历代志下', 14, 31, 7, '第三の月に彼らは積み始め、第七の月に終えた。'),
('JPN', '历代志下', 14, 31, 8, 'ヒゼキヤと高官たちは、やって来て積まれた山を見ると、主とその民イスラエルをほめたたえた。'),
('JPN', '历代志下', 14, 31, 9, 'ヒゼキヤが、その積まれた山について祭司とレビ人に説明を求めると、'),
('JPN', '历代志下', 14, 31, 10, 'ツァドク家の祭司の長アザルヤが、彼に答えて言った。「人々が奉納物を主の宮に携えて来ることを始めてから、食べて満ち足り、たくさん残るようになりました。主が御民を祝福されたので、その残りがこんなにたくさんあるのです。」'),
('JPN', '历代志下', 14, 31, 11, 'そこで、ヒゼキヤが主の宮の脇部屋を整えるように命じたので、彼らは整えて、'),
('JPN', '历代志下', 14, 31, 12, 'その奉納物と十分の一の聖なるささげ物を忠実に運び入れた。彼らを指図した長はレビ人カナンヤであり、その兄弟シムイが補佐であった。'),
('JPN', '历代志下', 14, 31, 13, 'エヒエル、アザズヤ、ナハテ、アサエル、エリモテ、エホザバデ、エリエル、イスマクヤ、マハテ、ベナヤは、ヒゼキヤ王と神の宮のつかさアザルヤの命によって、カナンヤとその兄弟シムイを助けて管理者となった。'),
('JPN', '历代志下', 14, 31, 14, '東の門の門衛、レビ人イムナの子コレは、神に進んで献げるものを受け持ち、主への奉納物と最も聖なるささげ物を分配した。'),
('JPN', '历代志下', 14, 31, 15, '彼の下には、エデン、ミンヤミン、ヨシュア、シェマヤ、アマルヤ、シェカンヤがいて、祭司の町々で組ごとに、老若の別なく、忠実に彼らの兄弟たちに分配した。'),
('JPN', '历代志下', 14, 31, 16, 'これとは別に、系図に記載された三歳以上の男子で、毎日の日課として組ごとの任務に就き、奉仕に当たるために主の宮に入るすべての者にも分配した。'),
('JPN', '历代志下', 14, 31, 17, 'また父祖の家ごとに祭司として系図に記載された者、および、二十歳以上のレビ人で系図に記載された者で、組ごとにその任務に就く人々にも分配した。'),
('JPN', '历代志下', 14, 31, 18, 'さらに、全会衆のうち、すべて系図に記載された幼児、妻たち、息子たち、娘たちにも分配した。彼らは聖なるささげ物を、聖なるものとして忠実に扱ったからである。'),
('JPN', '历代志下', 14, 31, 19, 'また、それぞれの町の放牧地にいるアロンの子らである祭司たちのためには、どの町にも指名された者たちがいて、祭司たちのすべての男子、および、レビ人で系図に記載されている者すべてに受ける分を与えることとした。'),
('JPN', '历代志下', 14, 31, 20, 'ヒゼキヤはユダの全地でこのように行い、その神、主の前に、良いこと、正しいこと、真実なことを行った。'),
('JPN', '历代志下', 14, 31, 21, '彼が始めたすべてのわざにおいて、すなわち、神の宮の奉仕において、律法において、命令において、彼は神を求め、心を尽くして行い、これを成し遂げた。'),
('JPN', '历代志下', 14, 32, 1, 'これらの真実なことが行われた後、アッシリアの王センナケリブが来てユダに入り、城壁のある町々に対して陣を敷いた。それらを攻め取ろうと考えたのである。'),
('JPN', '历代志下', 14, 32, 2, 'ヒゼキヤは、センナケリブが来て、エルサレムに対して戦を仕掛けようとしているのを見たので、'),
('JPN', '历代志下', 14, 32, 3, '町の外にある泉の水をふさごうと、高官たちや勇士たちと相談した。彼らは王を支持した。'),
('JPN', '历代志下', 14, 32, 4, 'そこで、多くの民が集まり、すべての泉と、この地を流れている川をせき止めて言った。「アッシリアの王たちに攻め入らせ、豊富な水を見つけさせてなるものか。」'),
('JPN', '历代志下', 14, 32, 5, '王は奮い立ち、崩れていた城壁をすべて改修し、その上にやぐらを立て上げ、その外側にもう一つの城壁を築き、ダビデの町のミロを強固にした。さらに、大量の投げ槍と盾を作った。'),
('JPN', '历代志下', 14, 32, 6, '彼は民の上に戦時の隊長たちを立て、彼らを町の門の広場に召集し、激励して言った。'),
('JPN', '历代志下', 14, 32, 7, '「強くあれ。雄々しくあれ。アッシリアの王や、彼とともにいるすべての大軍を恐れてはならない。おののいてはならない。彼とともにいる者よりも大いなる方が、私たちとともにいてくださるからである。'),
('JPN', '历代志下', 14, 32, 8, '彼とともにいる者は肉の腕だが、私たちとともにおられる方は、私たちの神、主であり、私たちを助け、私たちの戦いを戦ってくださる。」民はユダの王ヒゼキヤのことばによって力づけられた。'),
('JPN', '历代志下', 14, 32, 9, 'この後、アッシリアの王センナケリブは、その家来たちをエルサレムに遣わした。彼自身は全軍を率いてラキシュを攻めていた。家来たちは、ユダの王ヒゼキヤとエルサレムにいたすべてのユダの人々に告げた。'),
('JPN', '历代志下', 14, 32, 10, '「アッシリアの王センナケリブがこう言っておられる。おまえたちは何に拠り頼んで、エルサレムの包囲の中にとどまるのか。'),
('JPN', '历代志下', 14, 32, 11, 'ヒゼキヤは、『私たちの神、主は、アッシリアの王の手から私たちを救い出してくださる』と言って、おまえたちをそそのかし、飢えと渇きで、おまえたちを死なせようとしているではないか。'),
('JPN', '历代志下', 14, 32, 12, 'ヒゼキヤとは、その高き所と祭壇を取り除いて、ユダとエルサレムに『あなたがたは、ただ一つの祭壇の前で拝み、その上で香をたかなくてはならない』と言った者ではないか。'),
('JPN', '历代志下', 14, 32, 13, 'おまえたちは、私と私の先祖たちがすべての国々の民にしてきたことを知らないのか。諸国の神々が彼らの国を私の手から救い出すことができたか。'),
('JPN', '历代志下', 14, 32, 14, '私の先祖たちが滅ぼしたこれらの国々の神々のうち、だれがその民を私の手から救い出すことができたか。おまえたちの神がおまえたちを私の手から救い出すことができるとでもいうのか。'),
('JPN', '历代志下', 14, 32, 15, '今、おまえたちは、ヒゼキヤにごまかされるな。このようにそそのかされてはならない。彼を信じるな。どのような国、どのような王国のどのような神も、その民を私の手や私の先祖たちの手から救い出すことはできないからだ。まして、おまえたちの神は、おまえたちを私の手から救い出すことはできない。」'),
('JPN', '历代志下', 14, 32, 16, '彼の家来たちは、なおも、神である主とそのしもべヒゼキヤに悪口を浴びせた。'),
('JPN', '历代志下', 14, 32, 17, 'センナケリブは手紙を書いて、イスラエルの神、主を侮辱し、主に逆らって言った。「自分の民を私の手から救い出せなかった国々の神々と同じように、ヒゼキヤの神も、その民を私の手から救い出すことはできない。」'),
('JPN', '历代志下', 14, 32, 18, '彼らは、城壁の上にいたエルサレムの民にユダのことばで大声で呼びかけ、民を恐れさせ、おじけさせて、この町を取ろうとした。'),
('JPN', '历代志下', 14, 32, 19, '彼らは、人の手のわざである、地上の民の神々について語るのと同じように、エルサレムの神について語ったのである。'),
('JPN', '历代志下', 14, 32, 20, 'ヒゼキヤ王と、アモツの子、預言者イザヤは、このことについて祈り、天に叫び求めた。'),
('JPN', '历代志下', 14, 32, 21, '主は御使いを遣わして、アッシリアの王の陣営にいたすべての勇士、指揮官、隊長を全滅させた。アッシリアの王は恥じて国へ帰り、自分の神の宮に入った。そのとき、自分の身から生まれ出た者たちが、そこで彼を剣にかけて倒した。'),
('JPN', '历代志下', 14, 32, 22, 'こうして主は、ヒゼキヤとエルサレムの住民を、アッシリアの王センナケリブの手、および、すべての者の手から救って、四方から彼らを守られた。'),
('JPN', '历代志下', 14, 32, 23, '多くの人々が、主へのささげ物やユダの王ヒゼキヤに贈る選りすぐりの品々を携えて、エルサレムに来るようになった。この時以来、ヒゼキヤはすべての国々から尊敬の目で見られるようになった。'),
('JPN', '历代志下', 14, 32, 24, 'そのころ、ヒゼキヤは病気になって死にかかっていた。彼が主に祈ったとき、主は彼に答え、しるしを与えられた。'),
('JPN', '历代志下', 14, 32, 25, 'ところがヒゼキヤは、自分に与えられた恵みに応えようとせず、かえってその心を高ぶらせたので、彼の上に、また、ユダとエルサレムの上に御怒りが下った。'),
('JPN', '历代志下', 14, 32, 26, 'しかし、ヒゼキヤがその心の高ぶりを捨ててへりくだり、彼もエルサレムの住民もそうしたので、主の御怒りは、ヒゼキヤの時代には彼らの上に臨まなかった。'),
('JPN', '历代志下', 14, 32, 27, 'ヒゼキヤは非常に多くの富と誉れを手にした。彼は、銀、金、宝石、バルサム油、盾、すべての尊い器を納める宝物倉、'),
('JPN', '历代志下', 14, 32, 28, '穀物、新しいぶどう酒、油などの産物のための倉庫、さらに、あらゆる家畜のための小屋や、羊の群れの囲いを造った。'),
('JPN', '历代志下', 14, 32, 29, '彼は町々を建て、羊や牛の群れもおびただしい数であった。神が、実に豊かな財産を彼に与えられたからである。'),
('JPN', '历代志下', 14, 32, 30, 'このヒゼキヤこそ、上方にあるギホンの水源をふさぎ、ダビデの町の西側に向かってまっすぐに流した人である。ヒゼキヤは、そのすべての仕事を成し遂げた。'),
('JPN', '历代志下', 14, 32, 31, 'ただし、バビロンの首長たちが、この地に示されたしるしについて調べるために彼のもとに使節を遣わしたとき、神は彼を試みて、その心にあることすべてを知ろうとして彼を捨て置かれた。'),
('JPN', '历代志下', 14, 32, 32, 'ヒゼキヤについてのその他の事柄、その誠実な行いは、『ユダとイスラエルの王の書』の『アモツの子、預言者イザヤの幻』にまさしく記されている。'),
('JPN', '历代志下', 14, 32, 33, 'ヒゼキヤは先祖とともに眠りにつき、人々は彼をダビデの子たちの墓地の上り坂に葬った。ユダのすべての人々とエルサレムの住民は、彼の死に際し、彼に栄誉を与えた。彼の子マナセが代わって王となった。'),
('JPN', '历代志下', 14, 33, 1, 'マナセは十二歳で王となり、エルサレムで五十五年間、王であった。'),
('JPN', '历代志下', 14, 33, 2, '彼は、主がイスラエルの子らの前から追い払われた異邦の民の忌み嫌うべき慣わしをまねて、主の目に悪であることを行った。'),
('JPN', '历代志下', 14, 33, 3, 'そして、父ヒゼキヤが取り壊した高き所を築き直し、バアルのためにいくつもの祭壇を築き、アシェラ像を造った。また、彼は天の万象を拝んでこれに仕えた。'),
('JPN', '历代志下', 14, 33, 4, 'こうして彼は、主がかつて「エルサレムにわたしの名がとこしえにあるように」と言われた主の宮に、いくつもの祭壇を築いた。'),
('JPN', '历代志下', 14, 33, 5, '主の宮の二つの庭には、天の万象のために祭壇を築いた。'),
('JPN', '历代志下', 14, 33, 6, 'この彼は、ベン・ヒノムの谷で自分の子どもたちに火の中を通らせ、卜占をし、まじないをし、呪術を行い、霊媒や口寄せをし、主の目に悪であることを行って、いつも主の怒りを引き起こしていた。'),
('JPN', '历代志下', 14, 33, 7, '彼はまた、自分が造った偶像の彫像を神の宮に安置した。神はかつてこの宮について、ダビデとその子ソロモンに仰せられた。「わたしは、この宮に、そしてわたしがイスラエルの全部族の中から選んだエルサレムに、わたしの名をとこしえに置く。'),
('JPN', '历代志下', 14, 33, 8, 'もし彼らが、わたしの命じたすべてのこと、わたしがモーセを通して与えたすべての律法と掟と定めを守り行いさえするなら、わたしはもう二度と、あなたがたの先祖たちのものと定めた地からイスラエルの足を去らせることはしない。」'),
('JPN', '历代志下', 14, 33, 9, 'しかし、マナセはユダとエルサレムの住民を迷わせて、主がイスラエルの子らの前で根絶やしにされた異邦の民よりも、さらに悪いことを行わせた。'),
('JPN', '历代志下', 14, 33, 10, '主はマナセとその民に語られたが、彼らは耳を傾けなかった。'),
('JPN', '历代志下', 14, 33, 11, 'そこで主は、アッシリアの王の配下にある軍の長たちを彼らのところに連れて来られた。彼らはマナセを鉤で捕らえ、青銅の足かせにつないで、バビロンへ引いて行った。'),
('JPN', '历代志下', 14, 33, 12, 'しかし、彼は苦しみの中で彼の神、主に嘆願し、父祖の神の前に大いにへりくだり、'),
('JPN', '历代志下', 14, 33, 13, '神に祈ったので、神は彼の願いを聞き入れ、その切なる求めを聞いて、彼をエルサレムの彼の王国に戻された。こうしてマナセは、主こそ神であることを知った。'),
('JPN', '历代志下', 14, 33, 14, 'その後、彼はダビデの町の外側、ギホンの西側の谷に城壁を築いた。それは魚の門に至り、オフェルを囲むもので、非常に高く築かれた。また、彼はすべてのユダの城壁のある町々に軍の高官を置いた。'),
('JPN', '历代志下', 14, 33, 15, 'また彼は、主の宮から異国の神々と偶像、および、主の宮のある山とエルサレムに自分が築いたすべての祭壇を取り除き、町の外に投げ捨てた。'),
('JPN', '历代志下', 14, 33, 16, 'そして、主の祭壇を築き直し、その上で交わりのいけにえと感謝のいけにえを献げ、ユダに命じて、イスラエルの神、主に仕えさせた。'),
('JPN', '历代志下', 14, 33, 17, 'しかし民は、自分たちの神、主に対してではあったが、なお高き所でいけにえを献げていた。'),
('JPN', '历代志下', 14, 33, 18, 'マナセについてのその他の事柄、彼が神にささげた祈り、イスラエルの神、主の御名によって彼に語った先見者たちのことばは、まさしく『イスラエルの王の書』にある。'),
('JPN', '历代志下', 14, 33, 19, '彼の祈り、その願いが聞き入れられたこと、および、彼がへりくだる前に犯したその罪、その不信の罪、高き所を築き、アシェラ像と刻んだ像を立てた場所については、『ホザイの働き』にまさしく記されている。'),
('JPN', '历代志下', 14, 33, 20, 'マナセは先祖とともに眠りにつき、その家に葬られた。彼の子アモンが代わって王となった。'),
('JPN', '历代志下', 14, 33, 21, 'アモンは二十二歳で王となり、エルサレムで二年間、王であった。'),
('JPN', '历代志下', 14, 33, 22, '彼はその父マナセが行ったように、主の目に悪であることを行った。アモンはその父マナセが造ったすべての刻んだ像にいけにえを献げ、これに仕えた。'),
('JPN', '历代志下', 14, 33, 23, 'しかし、その父マナセがへりくだったようには、主の前にへりくだらず、かえって、このアモンは罪過を増し加えた。'),
('JPN', '历代志下', 14, 33, 24, '彼の家来たちは彼に謀反を起こし、その宮殿の中で彼を殺した。'),
('JPN', '历代志下', 14, 33, 25, 'しかし、民衆はアモン王に謀反を起こした者をみな打ち殺した。民衆はアモンの子ヨシヤを代わりに王とした。'),
('JPN', '历代志下', 14, 34, 1, 'ヨシヤは八歳で王となり、エルサレムで三十一年間、王であった。'),
('JPN', '历代志下', 14, 34, 2, '彼は主の目にかなうことを行い、父祖ダビデの道に歩み、右にも左にもそれなかった。'),
('JPN', '历代志下', 14, 34, 3, '彼の治世の第八年、まだ若いころに、彼は父祖ダビデの神を求めることを始め、第十二年にユダとエルサレムをきよめて、高き所、アシェラ像、刻んだ像、および鋳像を除き始めた。'),
('JPN', '历代志下', 14, 34, 4, '人々は彼の前でバアルの神々の祭壇を打ち壊した。彼は、その上にあった香の台を切り倒し、アシェラ像と刻んだ像と鋳像を打ち砕いて粉々にし、これらのいけにえを献げた者たちの墓の上にまき散らした。'),
('JPN', '历代志下', 14, 34, 5, '彼はまた、祭司たちの骨を彼らの祭壇の上で焼き、ユダとエルサレムをきよめた。'),
('JPN', '历代志下', 14, 34, 6, 'また、マナセ、エフライム、シメオン、さらにはナフタリに至る町々や、その周辺の荒れた地方でも同様にした。'),
('JPN', '历代志下', 14, 34, 7, '彼はイスラエルの全地で祭壇を打ち壊し、アシェラ像と刻んだ像を粉々に砕き、すべての香の台を切り倒して、エルサレムに帰った。'),
('JPN', '历代志下', 14, 34, 8, 'その治世の第十八年に、ヨシヤはこの地と宮をきよめるために、アツァルヤの子シャファン、この町の長マアセヤ、エホアハズの子である史官ヨアフを遣わして、自分の神、主の宮を修理した。'),
('JPN', '历代志下', 14, 34, 9, '彼らは大祭司ヒルキヤのもとに行き、神の宮に納められていた金を渡した。これは入り口を守るレビ人が、マナセとエフライム、すべてのイスラエルの残りの者、および全ユダとベニヤミンから集めたものであった。それから彼らはエルサレムに戻り、'),
('JPN', '历代志下', 14, 34, 10, '主の宮で工事をしている監督者たちにそれを手渡した。監督者たちは、神殿を繕い、修理するために、主の宮で行われている工事をしている者たちにそれを渡した。'),
('JPN', '历代志下', 14, 34, 11, '彼らは、大工や建築する者たちにそれを渡した。切り石やつなぎ材を買い、ユダの王たちが荒れさせた家々に梁を置くためであった。'),
('JPN', '历代志下', 14, 34, 12, 'この人々は忠実に仕事を行った。彼らの上には、メラリ族のレビ人ヤハテとオバデヤ、ケハテ族のゼカリヤとメシュラムが監督として任命された。レビ人たちはみな、楽器を奏でるのが得意な者たちであったが、'),
('JPN', '历代志下', 14, 34, 13, '荷を運ぶ者たちも管理し、各分野の仕事に当たるすべての職人たちの指揮も執った。レビ人の中には、書記、つかさ、門衛などもいた。'),
('JPN', '历代志下', 14, 34, 14, '彼らが、主の宮に携え入れられていた金を取り出していたとき、祭司ヒルキヤは、モーセを通して示された主の律法の書を見つけた。'),
('JPN', '历代志下', 14, 34, 15, 'ヒルキヤは書記シャファンに知らせて、「主の宮で律法の書を見つけました」と言った。ヒルキヤがその書物をシャファンに渡すと、'),
('JPN', '历代志下', 14, 34, 16, 'シャファンは、その書物を王のもとに携えて行き、さらに王に次のように報告した。「しもべたちに委ねられたことは、すべてやらせております。'),
('JPN', '历代志下', 14, 34, 17, '彼らは主の宮にあった金を取り出して、これを監督者たちの手と、工事をしている者たちの手に渡しました。」'),
('JPN', '历代志下', 14, 34, 18, 'さらに書記シャファンは王に告げた。「祭司ヒルキヤが私に一つの書物を渡してくれました。」シャファンは王の前でそれを朗読した。'),
('JPN', '历代志下', 14, 34, 19, '王は律法のことばを聞いたとき、自分の衣を引き裂いた。'),
('JPN', '历代志下', 14, 34, 20, '王はヒルキヤ、シャファンの子アヒカム、ミカの子アブドン、書記シャファン、王の家来アサヤに次のように命じた。'),
('JPN', '历代志下', 14, 34, 21, '「行って、見つかった書物のことばについて、私のため、イスラエルとユダの残りの者のために、主を求めよ。私たちの先祖が主のことばを守らず、すべてこの書に記されているとおりに行わなかったために、私たちの上に注がれた主の憤りが激しいからだ。」'),
('JPN', '历代志下', 14, 34, 22, 'そこで、ヒルキヤと王が指名した人々は、女預言者フルダのもとに行った。彼女は、ハスラの子トクハテの子である装束係シャルムの妻で、エルサレムの第二区に住んでいた。彼らが事の次第を彼女に伝えると、'),
('JPN', '历代志下', 14, 34, 23, '彼女は彼らに答えた。「イスラエルの神である主はこう言われます。『あなたがたをわたしのもとに遣わした人に言え。'),
('JPN', '历代志下', 14, 34, 24, '主はこう言われる。見よ。わたしはこの場所とその住民の上にわざわいをもたらす。ユダの王の前で読みあげられた、その書物に記されているすべてののろいをもたらす。'),
('JPN', '历代志下', 14, 34, 25, '彼らはわたしを捨て、ほかの神々に犠牲を供え、自分たちのすべての手のわざで、わたしの怒りを引き起こした。わたしの憤りはこの場所に注がれ、消えることはない。』'),
('JPN', '历代志下', 14, 34, 26, '主に尋ねるために、あなたがたを遣わしたユダの王には、こう言いなさい。『あなたが聞いたことばについて、イスラエルの神である主は、こう言われる。'),
('JPN', '历代志下', 14, 34, 27, 'あなたがこの場所とその住民について神のことばを聞いたとき、あなたは心を痛めて神の前にへりくだり、わたしの前にへりくだって自分の衣を引き裂き、わたしの前で泣いたので、わたしもまた、あなたの願いを聞き入れる──主のことば──。'),
('JPN', '历代志下', 14, 34, 28, '見よ、わたしはあなたを先祖たちのもとに集める。あなたは平安のうちに自分の墓に集められる。あなたは自分の目で、わたしがこの場所とその住民にもたらす、すべてのわざわいを見ることはない。』」彼らはそれを王に報告した。'),
('JPN', '历代志下', 14, 34, 29, '王は使者を遣わして、ユダとエルサレムのすべての長老たちを集めた。'),
('JPN', '历代志下', 14, 34, 30, '王は、ユダのすべての人々、エルサレムの住民、祭司とレビ人、および上の者から下の者まで、すべての民とともに主の宮に上り、主の宮で見つかった契約の書のことばをすべて彼らに読み聞かせた。'),
('JPN', '历代志下', 14, 34, 31, 'それから王は定めの場所に立ち、主の前に契約を結び、主に従って歩み、心を尽くし、いのちを尽くして主の命令と証しと掟を守り、この書物に記されている契約のことばを行うことを誓った。'),
('JPN', '历代志下', 14, 34, 32, '王はエルサレムとベニヤミンにいるすべての者をこの契約に加わらせた。エルサレムの住民は、その父祖の神である神の契約にしたがって行動した。'),
('JPN', '历代志下', 14, 34, 33, 'ヨシヤはイスラエルの子らのものである全地から、忌み嫌うべきものを取り除き、イスラエルにいるすべての者を自分の神、主に仕えさせた。彼の生きている間、彼らはその父祖の神、主に従う道から外れなかった。'),
('JPN', '历代志下', 14, 35, 1, 'さて、ヨシヤはエルサレムで主に過越のいけにえを献げた。人々は第一の月の十四日に過越のいけにえを屠った。'),
('JPN', '历代志下', 14, 35, 2, '彼は祭司たちをその任務に就かせ、彼らを力づけて、主の宮の奉仕に当たらせた。'),
('JPN', '历代志下', 14, 35, 3, '王は、全イスラエルを教え導く、主に聖別されたレビ人たちに言った。「聖なる箱を、イスラエルの王ダビデの子ソロモンが建てた宮に据えなさい。もはやあなたがたはそれを肩に担ぐことはない。今、あなたがたの神、主と、その民イスラエルに仕えなさい。'),
('JPN', '历代志下', 14, 35, 4, 'あなたがたは、イスラエルの王ダビデの文書とその子ソロモンの書きつけのとおり、父祖の家ごとに、組分けにしたがって準備をしなさい。'),
('JPN', '历代志下', 14, 35, 5, 'あなたがたの兄弟である、この民の者たちが属している父祖の家の区分にしたがって、聖所に立ちなさい。レビ人にとって、一族の分があるようにしなさい。'),
('JPN', '历代志下', 14, 35, 6, 'それから、過越のいけにえを屠り、身を聖別し、あなたがたの同胞のために準備をして、モーセを通して示された主のことばのとおりに行いなさい。」'),
('JPN', '历代志下', 14, 35, 7, 'ヨシヤは民の者たちに、群れの中から子羊とやぎの子を提供した。これらはみな、そこにいたすべての人の過越のいけにえのためであった。その数は三万匹、牛は三千頭。これらは王の財産の中から出された。'),
('JPN', '历代志下', 14, 35, 8, '王の高官たちも、民、祭司、レビ人のために、進んで献げるものを提供した。神の宮のつかさたち、ヒルキヤ、ゼカリヤ、エヒエルも、祭司たちに過越のいけにえとして羊二千六百匹、牛三百頭を与えた。'),
('JPN', '历代志下', 14, 35, 9, 'さらに、レビ人の長たち、すなわち、カナンヤとその兄弟シェマヤ、ネタンエル、およびハシャブヤ、エイエル、エホザバデも、レビ人に過越のいけにえとして羊五千匹、牛五百頭を提供した。'),
('JPN', '历代志下', 14, 35, 10, '奉仕の用意ができたので、王の命令のとおりに、祭司たちはそれぞれの定めの場所に、レビ人はそれぞれの組分けにしたがって立った。'),
('JPN', '历代志下', 14, 35, 11, '彼らが過越のいけにえを屠ると、祭司たちは彼らの手から受け取った血を振りかけ、レビ人は皮を剝いだ。'),
('JPN', '历代志下', 14, 35, 12, '彼らは全焼のささげ物を取り分け、それを父祖の家の区分ごとに民の者たちに渡し、モーセの書に記されているとおりに主に献げさせた。牛についても同様にした。'),
('JPN', '历代志下', 14, 35, 13, '彼らは定めにしたがって、過越のいけにえを火で焼き、聖なるささげ物を、鍋、釜、平鍋で煮て、民の者たちすべてに急いで配った。'),
('JPN', '历代志下', 14, 35, 14, 'その後で、彼らは自分たちや祭司たちのための用意をした。アロンの子らである祭司たちは、夜になるまで、全焼のささげ物と脂肪を献げていたからである。そこでレビ人は、自分たちや、アロンの子らである祭司たちのための用意をした。'),
('JPN', '历代志下', 14, 35, 15, 'アサフの子孫である歌い手たちは、ダビデ、アサフ、ヘマン、および王の先見者エドトンの命令のとおりにその役目に就いていた。また、門衛たちはそれぞれの門を守っていた。彼らのうちだれも、その奉仕を離れる必要がなかった。彼らの兄弟であるレビ人が彼らのための用意をしたからである。'),
('JPN', '历代志下', 14, 35, 16, 'こうしてその日、ヨシヤ王の命令のとおりに、主の祭壇で過越のいけにえを献げ、全焼のささげ物を献げるための、主への奉仕の用意はすべて整った。'),
('JPN', '历代志下', 14, 35, 17, 'そこにいたイスラエルの子らは、そのとき、過越のいけにえを献げ、七日間にわたって種なしパンの祭りを行った。'),
('JPN', '历代志下', 14, 35, 18, '預言者サムエルの時代以来、イスラエルでこのような過越のいけにえが献げられたことはなかった。イスラエルのどの王も、ここでヨシヤが、祭司とレビ人、そこにいた全ユダとイスラエル、そしてエルサレムの住民とともに献げたような過越のいけにえを献げたことはなかった。'),
('JPN', '历代志下', 14, 35, 19, 'ヨシヤの治世の第十八年に、この過越のいけにえが献げられた。'),
('JPN', '历代志下', 14, 35, 20, 'このようにヨシヤが宮を整えた後、エジプトの王ネコが、ユーフラテス河畔のカルケミシュで戦うために上って来た。そこで、ヨシヤは彼を迎え撃つために出陣した。'),
('JPN', '历代志下', 14, 35, 21, 'ところが、ネコは彼に使者を遣わして言った。「ユダの王よ、私とあなたと何の関係があるのか。今日は、あなたを攻めに来たのではない。私が戦っている王家に向かって行くところなのだ。神は、早く行くように命じておられる。私とともにおられる神に逆らうことはやめよ。さもなければ、神があなたを滅ぼされる。」'),
('JPN', '历代志下', 14, 35, 22, 'しかし、ヨシヤは身を引かず、かえって彼と戦おうとして変装し、神の御口から出たネコのことばを聞かなかった。そして、メギドの平地で戦うために出かけた。'),
('JPN', '历代志下', 14, 35, 23, '射手たちがヨシヤ王を射抜いたので、王は家来たちに言った。「私を運び出してくれ。ひどい傷を負ってしまった。」'),
('JPN', '历代志下', 14, 35, 24, '家来たちは王を戦車から降ろし、彼が持っていた第二の車に乗せてエルサレムに連れ帰った。彼は死に、その先祖たちの墓に葬られた。全ユダとエルサレムは、ヨシヤのために喪に服した。'),
('JPN', '历代志下', 14, 35, 25, 'エレミヤはヨシヤのために哀歌を作った。男女の歌い手は、ヨシヤのことをその哀歌で語り伝えるようになり、今日に至っている。これはイスラエルの慣例となり、まさしく哀歌に記されている。'),
('JPN', '历代志下', 14, 35, 26, 'ヨシヤについてのその他の事柄、主の律法に記されているところに基づいた彼の誠実な行い、'),
('JPN', '历代志下', 14, 35, 27, 'またその事績は、最初から最後まで、『イスラエルとユダの王の書』にまさしく記されている。'),
('JPN', '历代志下', 14, 36, 1, '民衆は、ヨシヤの子エホアハズを選んで、彼の父に代えてエルサレムで王とした。'),
('JPN', '历代志下', 14, 36, 2, 'エホアハズは二十三歳で王となり、エルサレムで三か月間、王であった。'),
('JPN', '历代志下', 14, 36, 3, 'エジプトの王はエルサレムで彼を退位させ、この国に銀百タラントと金一タラントの科料を課した。'),
('JPN', '历代志下', 14, 36, 4, 'それからエジプトの王は、彼の兄弟エルヤキムをユダとエルサレムの王とし、その名をエホヤキムと改めさせた。ネコは、その兄弟エホアハズを捕らえて、エジプトへ連れて行った。'),
('JPN', '历代志下', 14, 36, 5, 'エホヤキムは二十五歳で王となり、エルサレムで十一年間、王であった。彼は自分の神、主の目に悪であることを行った。'),
('JPN', '历代志下', 14, 36, 6, '彼のもとに、バビロンの王ネブカドネツァルが攻め上って来て、彼を青銅の足かせにつなぎ、バビロンへ引いて行った。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '历代志下', 14, 36, 7, 'ネブカドネツァルは、主の宮の器をバビロンに持ち去り、バビロンにある彼の宮殿に置いた。'),
('JPN', '历代志下', 14, 36, 8, 'エホヤキムについてのその他の事柄、彼が行った忌み嫌うべきこと、彼について露見したことは、『イスラエルとユダの王の書』にまさしく記されている。彼の子エホヤキンが代わって王となった。'),
('JPN', '历代志下', 14, 36, 9, 'エホヤキンは十八歳で王となり、エルサレムで三か月と十日の間、王であった。彼は主の目に悪であることを行った。'),
('JPN', '历代志下', 14, 36, 10, '年が改まると、ネブカドネツァル王は使者を遣わして、主の宮にあった尊い器とともに彼をバビロンに連れて行った。そして、エホヤキンの親戚ゼデキヤをユダとエルサレムの王とした。'),
('JPN', '历代志下', 14, 36, 11, 'ゼデキヤは二十一歳で王となり、エルサレムで十一年間、王であった。'),
('JPN', '历代志下', 14, 36, 12, '彼はその神、主の目に悪であることを行い、主のことばを告げた預言者エレミヤの前にへりくだらなかった。'),
('JPN', '历代志下', 14, 36, 13, '彼はまた、彼に神にかけて誓わせたネブカドネツァル王に反逆した。彼はうなじを固くし、心を閉ざして、イスラエルの神、主に立ち返らなかった。'),
('JPN', '历代志下', 14, 36, 14, 'そのうえ、祭司長全員と民も、異邦の民の忌み嫌うべきすべての慣わしをまねて、不信に不信を重ね、主がエルサレムで聖別された主の宮を汚した。'),
('JPN', '历代志下', 14, 36, 15, '彼らの父祖の神、主は、彼らのもとに早くからたびたび使者を遣わされた。それは、ご自分の民と、ご自分の住まいをあわれまれたからである。'),
('JPN', '历代志下', 14, 36, 16, 'ところが、彼らは神の使者たちを侮り、そのみことばを蔑み、その預言者たちを笑いものにしたので、ついに主の激しい憤りが民に対して燃え上がり、もはや癒やされることがないまでになった。'),
('JPN', '历代志下', 14, 36, 17, '主は、彼らのもとにカルデア人の王を攻め上らせた。彼は、聖所の中で若い男たちを剣で殺し、若い男も若い女も、年寄りも弱い者も容赦しなかった。主は、すべてのものを彼の手に渡された。'),
('JPN', '历代志下', 14, 36, 18, '彼は、神の宮の大小すべての器、主の宮の財宝と、王とその高官たちの財宝、これらすべてをバビロンへ持ち去った。'),
('JPN', '历代志下', 14, 36, 19, '神の宮は焼かれ、エルサレムの城壁は打ち壊され、その高殿はすべて火で焼かれ、その中の宝としていた器も一つ残らず破壊された。'),
('JPN', '历代志下', 14, 36, 20, '彼は、剣を逃れた残りの者たちをバビロンへ捕らえ移した。こうして彼らは、ペルシア王国が支配権を握るまで、彼とその子たちの奴隷となった。'),
('JPN', '历代志下', 14, 36, 21, 'これは、エレミヤによって告げられた主のことばが成就して、この地が安息を取り戻すためであった。その荒廃の全期間が七十年を満たすまで、この地は安息を得た。'),
('JPN', '历代志下', 14, 36, 22, 'ペルシアの王キュロスの第一年に、エレミヤによって告げられた主のことばが成就するために、主はペルシアの王キュロスの霊を奮い立たせた。王は王国中に通達を出し、また文書にもした。'),
('JPN', '历代志下', 14, 36, 23, '「ペルシアの王キュロスは言う。『天の神、主は、地のすべての王国を私にお与えくださった。この方が、ユダにあるエルサレムに、ご自分のために宮を建てるよう私を任命された。あなたがた、だれでも主の民に属する者には、その神、主がともにいてくださるように。その者は上って行くようにせよ。』」'),
('JPN', '以斯拉记', 15, 1, 1, 'ペルシアの王キュロスの第一年に、エレミヤによって告げられた主のことばが成就するために、主はペルシアの王キュロスの霊を奮い立たせた。王は王国中に通達を出し、また文書にもした。'),
('JPN', '以斯拉记', 15, 1, 2, '「ペルシアの王キュロスは言う。『天の神、主は、地のすべての王国を私にお与えくださった。この方が、ユダにあるエルサレムに、ご自分のために宮を建てるよう私を任命された。'),
('JPN', '以斯拉记', 15, 1, 3, 'あなたがた、だれでも主の民に属する者には、その神がともにいてくださるように。その者はユダにあるエルサレムに上り、イスラエルの神、主の宮を建てるようにせよ。この方はエルサレムにおられる神である。'),
('JPN', '以斯拉记', 15, 1, 4, 'あとに残る者たちはみな、その者を支援するようにせよ。その者がどこに寄留しているにしても、その場所から、その土地の人々が、エルサレムにある神の宮のために進んで献げるものに加え、銀、金、財貨、家畜をもってその者を支援せよ。』」'),
('JPN', '以斯拉记', 15, 1, 5, 'そこで、ユダとベニヤミンの一族のかしらたち、祭司たち、レビ人たちは立ち上がった。エルサレムにある主の宮を建てるために上って行くように、神が彼ら全員の霊を奮い立たせたのである。'),
('JPN', '以斯拉记', 15, 1, 6, '彼らの周りの人々はみな、銀の器、金、財貨、家畜、選りすぐりの品々、そのほか進んで献げるあらゆる物をもって彼らを力づけた。'),
('JPN', '以斯拉记', 15, 1, 7, 'キュロス王は、ネブカドネツァルがエルサレムから持ち出して、自分の神々の宮に置いていた主の宮の器を運び出させた。'),
('JPN', '以斯拉记', 15, 1, 8, 'ペルシアの王キュロスは財務官ミテレダテに命じてこれを取り出し、その数を確かめさせ、ユダの首長シェシュバツァルに渡した。'),
('JPN', '以斯拉记', 15, 1, 9, 'その数は次のとおりであった。金の皿三十、銀の皿一千、香炉二十九、'),
('JPN', '以斯拉记', 15, 1, 10, '金の鉢三十、予備の銀の鉢四百十、その他の器一千。'),
('JPN', '以斯拉记', 15, 1, 11, '金や銀の用具は全部で五千四百あった。捕囚の民がバビロンからエルサレムに上ることを許されたとき、シェシュバツァルはこれらの物をみな一緒に携えて上った。'),
('JPN', '以斯拉记', 15, 2, 1, 'バビロンの王ネブカドネツァルがバビロンに引いて行った捕囚の民で、その捕囚の身から解かれてエルサレムとユダに上り、それぞれ自分の町に帰ったこの州の人々は次のとおりである。'),
('JPN', '以斯拉记', 15, 2, 2, '彼らは、ゼルバベル、ヨシュア、ネヘミヤ、セラヤ、レエラヤ、モルデカイ、ビルシャン、ミスパル、ビグワイ、レフム、バアナと一緒に帰って来た。イスラエルの民の人数は次のとおりである。'),
('JPN', '以斯拉记', 15, 2, 3, 'パルオシュ族、二千百七十二人。'),
('JPN', '以斯拉记', 15, 2, 4, 'シェファテヤ族、三百七十二人。'),
('JPN', '以斯拉记', 15, 2, 5, 'アラフ族、七百七十五人。'),
('JPN', '以斯拉记', 15, 2, 6, 'ヨシュアとヨアブの二族からなるパハテ・モアブ族、二千八百十二人。'),
('JPN', '以斯拉记', 15, 2, 7, 'エラム族、一千二百五十四人。'),
('JPN', '以斯拉记', 15, 2, 8, 'ザト族、九百四十五人。'),
('JPN', '以斯拉记', 15, 2, 9, 'ザカイ族、七百六十人。'),
('JPN', '以斯拉记', 15, 2, 10, 'バニ族、六百四十二人。'),
('JPN', '以斯拉记', 15, 2, 11, 'ベバイ族、六百二十三人。'),
('JPN', '以斯拉记', 15, 2, 12, 'アズガデ族、一千二百二十二人。'),
('JPN', '以斯拉记', 15, 2, 13, 'アドニカム族、六百六十六人。'),
('JPN', '以斯拉记', 15, 2, 14, 'ビグワイ族、二千五十六人。'),
('JPN', '以斯拉记', 15, 2, 15, 'アディン族、四百五十四人。'),
('JPN', '以斯拉记', 15, 2, 16, 'ヒゼキヤ族、すなわちアテル族、九十八人。'),
('JPN', '以斯拉记', 15, 2, 17, 'ベツァイ族、三百二十三人。'),
('JPN', '以斯拉记', 15, 2, 18, 'ヨラ族、百十二人。'),
('JPN', '以斯拉记', 15, 2, 19, 'ハシュム族、二百二十三人。'),
('JPN', '以斯拉记', 15, 2, 20, 'ギバル族、九十五人。'),
('JPN', '以斯拉记', 15, 2, 21, 'ベツレヘム人、百二十三人。'),
('JPN', '以斯拉记', 15, 2, 22, 'ネトファの人々、五十六人。'),
('JPN', '以斯拉记', 15, 2, 23, 'アナトテの人々、百二十八人。'),
('JPN', '以斯拉记', 15, 2, 24, 'アズマウェテ人、四十二人。'),
('JPN', '以斯拉记', 15, 2, 25, 'キルヤテ・アリム人とケフィラ人とベエロテ人、七百四十三人。'),
('JPN', '以斯拉记', 15, 2, 26, 'ラマ人とゲバ人、六百二十一人。'),
('JPN', '以斯拉记', 15, 2, 27, 'ミクマスの人々、百二十二人。'),
('JPN', '以斯拉记', 15, 2, 28, 'ベテルとアイの人々、二百二十三人。'),
('JPN', '以斯拉记', 15, 2, 29, 'ネボ人、五十二人。'),
('JPN', '以斯拉记', 15, 2, 30, 'マグビシュ族、百五十六人。'),
('JPN', '以斯拉记', 15, 2, 31, '別のエラム族、一千二百五十四人。'),
('JPN', '以斯拉记', 15, 2, 32, 'ハリム族、三百二十人。'),
('JPN', '以斯拉记', 15, 2, 33, 'ロデ人とハディデ人とオノ人、七百二十五人。'),
('JPN', '以斯拉记', 15, 2, 34, 'エリコ人、三百四十五人。'),
('JPN', '以斯拉记', 15, 2, 35, 'セナア人、三千六百三十人。'),
('JPN', '以斯拉记', 15, 2, 36, '祭司は、ヨシュアの家系のエダヤ族、九百七十三人。'),
('JPN', '以斯拉记', 15, 2, 37, 'イメル族、一千五十二人。'),
('JPN', '以斯拉记', 15, 2, 38, 'パシュフル族、一千二百四十七人。'),
('JPN', '以斯拉记', 15, 2, 39, 'ハリム族、一千十七人。'),
('JPN', '以斯拉记', 15, 2, 40, 'レビ人は、ホダウヤ族のヨシュアとカデミエルの二族、七十四人。'),
('JPN', '以斯拉记', 15, 2, 41, '歌い手は、アサフ族、百二十八人。'),
('JPN', '以斯拉记', 15, 2, 42, '門衛の人々は、シャルム族、アテル族、タルモン族、アクブ族、ハティタ族、ショバイ族、合計百三十九人。'),
('JPN', '以斯拉记', 15, 2, 43, '宮のしもべたちは、ツィハ族、ハスファ族、タバオテ族、'),
('JPN', '以斯拉记', 15, 2, 44, 'ケロス族、シアハ族、パドン族、'),
('JPN', '以斯拉记', 15, 2, 45, 'レバナ族、ハガバ族、アクブ族、'),
('JPN', '以斯拉记', 15, 2, 46, 'ハガブ族、シャルマイ族、ハナン族、'),
('JPN', '以斯拉记', 15, 2, 47, 'ギデル族、ガハル族、レアヤ族、'),
('JPN', '以斯拉记', 15, 2, 48, 'レツィン族、ネコダ族、ガザム族、'),
('JPN', '以斯拉记', 15, 2, 49, 'ウザ族、パセアハ族、ベサイ族、'),
('JPN', '以斯拉记', 15, 2, 50, 'アスナ族、メウニム族、ネフシム族、'),
('JPN', '以斯拉记', 15, 2, 51, 'バクブク族、ハクファ族、ハルフル族、'),
('JPN', '以斯拉记', 15, 2, 52, 'バツルテ族、メヒダ族、ハルシャ族、'),
('JPN', '以斯拉记', 15, 2, 53, 'バルコス族、シセラ族、テマフ族、'),
('JPN', '以斯拉记', 15, 2, 54, 'ネツィアハ族、ハティファ族。'),
('JPN', '以斯拉记', 15, 2, 55, 'ソロモンのしもべたちの子孫は、ソタイ族、ソフェレテ族、ペルダ族、'),
('JPN', '以斯拉记', 15, 2, 56, 'ヤアラ族、ダルコン族、ギデル族、'),
('JPN', '以斯拉记', 15, 2, 57, 'シェファテヤ族、ハティル族、ポケレテ・ハ・ツェバイム族、アミ族。'),
('JPN', '以斯拉记', 15, 2, 58, '宮のしもべたちと、ソロモンのしもべたちの子孫は、合計三百九十二人。'),
('JPN', '以斯拉记', 15, 2, 59, '次の人々はテル・メラフ、テル・ハルシャ、ケルブ、アダン、イメルから引き揚げて来たが、自分たちの先祖の家系と血統がイスラエル人であったかどうかを証明できなかった。'),
('JPN', '以斯拉记', 15, 2, 60, 'デラヤ族、トビヤ族、ネコダ族、六百五十二人。'),
('JPN', '以斯拉记', 15, 2, 61, '祭司の子孫の中では、ホバヤ族、ハ・コツ族、バルジライ族。このバルジライは、ギルアデ人バルジライの娘の一人を妻にしたので、その名で呼ばれていた。'),
('JPN', '以斯拉记', 15, 2, 62, 'これらの人々は自分たちの系図書きを捜してみたが、見つからなかったので、彼らは祭司職を果たす資格がない者とされた。'),
('JPN', '以斯拉记', 15, 2, 63, 'そのため総督は彼らに、ウリムとトンミムを使える祭司が起こるまでは、最も聖なるものを食べてはならないと命じた。'),
('JPN', '以斯拉记', 15, 2, 64, '全会衆の合計は四万二千三百六十人であった。'),
('JPN', '以斯拉记', 15, 2, 65, 'このほかに、彼らの男女の奴隷が七千三百三十七人いた。また、彼らには男女の歌い手が二百人いた。'),
('JPN', '以斯拉记', 15, 2, 66, '彼らの馬は七百三十六頭。らばは二百四十五頭。'),
('JPN', '以斯拉记', 15, 2, 67, 'らくだは四百三十五頭。ろばは六千七百二十頭であった。'),
('JPN', '以斯拉记', 15, 2, 68, '一族のかしらの中のある者たちは、エルサレムにある主の宮に着いたとき、神の宮を元の場所に建てるために、自分から進んでささげ物をした。'),
('JPN', '以斯拉记', 15, 2, 69, '彼らは自分たちの財力に応じて、工事資金として金六万一千ダリク、銀五千ミナ、祭司の長服百着を献げた。'),
('JPN', '以斯拉记', 15, 2, 70, 'こうして、祭司、レビ人、民のある者たち、歌い手、門衛、宮のしもべたち、すなわち、全イスラエルは自分の元の町々に住んだ。'),
('JPN', '以斯拉记', 15, 3, 1, 'イスラエルの子らは自分たちの町々にいたが、第七の月が来たとき、民は一斉にエルサレムに集まって来た。'),
('JPN', '以斯拉记', 15, 3, 2, 'そこで、エホツァダクの子ヨシュアとその兄弟の祭司たち、またシェアルティエルの子ゼルバベルとその兄弟たちは、神の人モーセの律法に書かれているとおりに全焼のささげ物を献げるため、イスラエルの神の祭壇を築いた。'),
('JPN', '以斯拉记', 15, 3, 3, '彼らは、周りの国々の民を恐れていたので、祭壇を所定の場所に設けた。彼らはその上で主に全焼のささげ物、すなわち、朝ごと夕ごとの全焼のささげ物を献げた。'),
('JPN', '以斯拉记', 15, 3, 4, '彼らは、書かれているとおりに仮庵の祭りを祝い、毎日の分として定められた数にしたがって、日々の全焼のささげ物を献げた。'),
('JPN', '以斯拉记', 15, 3, 5, 'それから、常供の全焼のささげ物、新月の祭りやすべての聖別された主の例祭のためのささげ物、そして一人ひとりが進んで献げるものを、喜んで主に献げた。'),
('JPN', '以斯拉记', 15, 3, 6, '彼らは第七の月の一日から全焼のささげ物を主に献げ始めたが、主の神殿の礎はまだ据えられていなかった。'),
('JPN', '以斯拉记', 15, 3, 7, '彼らは石切り工や大工には金を与え、シドンとツロの人々には食べ物や飲み物や油を与えた。それはペルシアの王キュロスが与えた許可によって、レバノンから海路、ヤッファに杉材を運んでもらうためであった。'),
('JPN', '以斯拉记', 15, 3, 8, '彼らがエルサレムにある神の宮のところに着いて二年目の第二の月に、シェアルティエルの子ゼルバベルと、エホツァダクの子ヨシュアと、そのほかの同僚の祭司とレビ人たち、および捕囚からエルサレムに帰って来たすべての人々は、主の宮の工事を指揮するために二十歳以上のレビ人を立てて、工事を始めた。'),
('JPN', '以斯拉记', 15, 3, 9, 'こうして、ヨシュアと、その息子たち、その兄弟たち、カデミエルとその息子たち、ユダの息子たちは一致して立ち、神の宮の工事に当たる者たちを指揮した。ヘナダデの息子たちと孫たち、そのレビ人の兄弟たちもそうした。'),
('JPN', '以斯拉记', 15, 3, 10, '建築する者たちが主の神殿の礎を据えたとき、イスラエルの王ダビデの規定によって主を賛美するために、祭服を着た祭司たちはラッパを持ち、アサフの子らのレビ人たちはシンバルを持って出て来た。'),
('JPN', '以斯拉记', 15, 3, 11, 'そして彼らは主を賛美し、感謝しながら「主はまことにいつくしみ深い。その恵みはとこしえまでもイスラエルに」と歌い交わした。こうして、主の宮の礎が据えられたので、民はみな主を賛美して大声で叫んだ。'),
('JPN', '以斯拉记', 15, 3, 12, 'しかし、祭司、レビ人、一族のかしらたちのうち、以前の宮を見たことのある多くの老人たちは、目の前でこの宮の基が据えられたとき、大声をあげて泣いた。一方、ほかの多くの人々は喜びにあふれて声を張り上げた。'),
('JPN', '以斯拉记', 15, 3, 13, 'そのため、喜びの叫び声と民の泣き声をだれも区別できなかった。民が大声をあげて叫んだので、その声は遠いところまで聞こえた。'),
('JPN', '以斯拉记', 15, 4, 1, 'ユダとベニヤミンの敵たちは、捕囚から帰って来た人々がイスラエルの神、主のために宮を建てていると聞いて、'),
('JPN', '以斯拉记', 15, 4, 2, 'ゼルバベルと一族のかしらたちのところに近づいて来て言った。「私たちも、あなたがたと一緒に建てたい。私たちは、あなたがたと同様、あなたがたの神を求めたいのです。私たちをここに連れて来たアッシリアの王エサル・ハドンの時以来、私たちはあなたがたの神に、いけにえを献げてきました。」'),
('JPN', '以斯拉记', 15, 4, 3, 'しかし、ゼルバベルとヨシュアと、そのほかのイスラエルの一族のかしらたちは彼らに言った。「私たちの神のために宮を建てることは、あなたがたにではなく、私たちに属する事柄です。ペルシアの王キュロス王が私たちに命じたとおり、私たちだけで、イスラエルの神、主のために宮を建てるつもりです。」'),
('JPN', '以斯拉记', 15, 4, 4, 'すると、その地の民はユダの民の気力を失わせようとし、脅して建てさせないようにした。'),
('JPN', '以斯拉记', 15, 4, 5, 'さらに、顧問を買収して彼らに反対させ、この計画をつぶそうとした。このことはペルシアの王キュロスの時代から、ペルシアの王ダレイオスの治世の時まで続いた。'),
('JPN', '以斯拉记', 15, 4, 6, 'またクセルクセスの治世には、その治世の初めに、彼らはユダとエルサレムの住民を非難する告訴状を書いた。'),
('JPN', '以斯拉记', 15, 4, 7, 'また、アルタクセルクセスの時代に、ビシュラム、ミテレダテ、タベエルとほかの同僚たちは、ペルシアの王アルタクセルクセスに書き送った。その手紙の文字はアラム語で書かれ、アラム語で述べられていた。'),
('JPN', '以斯拉记', 15, 4, 8, '参事官レフム、書記官シムシャイはエルサレムに関して、次のような書状をアルタクセルクセス王に書き送った。'),
('JPN', '以斯拉记', 15, 4, 9, 'これは、参事官レフム、書記官シムシャイ、ほかの同僚たち、裁判官、使節、役人、ペルシア人、ウルク人、バビロン人、スサの人々すなわちエラム人、'),
('JPN', '以斯拉记', 15, 4, 10, 'その他、偉大にして高貴なアッシュルバニパルが、サマリアの町々とユーフラテス川西方のほかの地に引いて行って住まわせた諸民族からであった。'),
('JPN', '以斯拉记', 15, 4, 11, '彼らが送ったその書状の写しは次のとおりである。「ユーフラテス川西方の者、あなた様のしもべどもから、アルタクセルクセス王へ。さて、'),
('JPN', '以斯拉记', 15, 4, 12, '王にお知らせいたします。あなた様のところから、私どものところに上って来たユダヤ人たちはエルサレムに着き、あの反抗的で悪しき町を再建しております。その城壁を修復し、その礎もすでに据えられています。'),
('JPN', '以斯拉记', 15, 4, 13, '今、王にお知らせいたします。もしこの町が再建され、城壁が修復されたら、彼らは貢ぎ物、関税、税金を納めなくなり、王家に間違いなく損害を与えることになるでしょう。'),
('JPN', '以斯拉记', 15, 4, 14, 'さて、私どもは王宮の塩を賜る者ですから、王に対する侮辱を見るわけにはいきません。それゆえ、私どもは人を遣わして、王にお知らせするのです。'),
('JPN', '以斯拉记', 15, 4, 15, 'あなた様の先祖の記録文書を調べていただきたいのです。そうすれば、この町が反抗的な町で、王たちと諸州に損害を与えてきたこと、また昔からこの町で反乱が繰り返されたことを、その記録文書の中に見て、理解していただけるでしょう。この町が滅ぼされたのも、そのためです。'),
('JPN', '以斯拉记', 15, 4, 16, '私たちは王にお知らせします。もしこの町が再建され、城壁が修復されたら、あなたはこのためにユーフラテス川西方の権益を失ってしまわれるでしょう。」'),
('JPN', '以斯拉记', 15, 4, 17, '王は参事官レフム、書記官シムシャイ、およびサマリアとユーフラテス川西方のほかの地に住んでいる彼らの同僚たちに返事を送った。「平安があるように。さて、'),
('JPN', '以斯拉记', 15, 4, 18, 'あなたがたが私たちのところに送ってよこしたあの手紙は、私の前で説明されて読まれた。'),
('JPN', '以斯拉记', 15, 4, 19, '私は命令を下し、調べさせたところ、その町は昔から王たちに対して謀反を企て、その町で反逆と反乱が行われたことが分かった。'),
('JPN', '以斯拉记', 15, 4, 20, 'またエルサレムにはかつて勢力のある王たちがいて、ユーフラテス川西方の地を全部支配し、貢ぎ物、関税、税金が彼らに納められていたことも分かった。'),
('JPN', '以斯拉记', 15, 4, 21, '今あなたがたは命令を下して、その者たちの工事をやめさせ、私から再び命令が下るまで、この町が再建されないようにせよ。'),
('JPN', '以斯拉记', 15, 4, 22, 'あなたがたはよく気をつけ、このことを怠ってはならない。損害が増して王の不利益となるといけないから。」'),
('JPN', '以斯拉记', 15, 4, 23, 'さて、アルタクセルクセス王の手紙の写しがレフムと、書記官シムシャイと、その同僚たちの前で読まれると、彼らは急いでエルサレムのユダヤ人のところに行き、実力をもって彼らの工事をやめさせた。'),
('JPN', '以斯拉记', 15, 4, 24, 'こうして、エルサレムにある神の宮の工事は中止され、ペルシアの王ダレイオスの治世の第二年まで中止されたままになった。'),
('JPN', '以斯拉记', 15, 5, 1, 'さて、預言者ハガイとイドの子ゼカリヤという二人の預言者は、ユダとエルサレムにいるユダヤ人に対して、自分たちの上におられるイスラエルの神の御名によって預言した。'),
('JPN', '以斯拉记', 15, 5, 2, 'そこでシェアルティエルの子ゼルバベルと、エホツァダクの子ヨシュアは立ち上がり、エルサレムにある神の宮を建て始めた。神の預言者たちが一緒にいて、彼らを助けた。'),
('JPN', '以斯拉记', 15, 5, 3, 'そのような時期に、ユーフラテス川西方の総督タテナイと、シェタル・ボゼナイと、その同僚たちが彼らのところにやって来て、こう言った。「この宮を建て、この城壁を修復せよとの命令をだれがあなたがたに下したのか。」'),
('JPN', '以斯拉记', 15, 5, 4, 'そしてまた、「この建物を建てている者たちの名は何というのか」と尋ねた。'),
('JPN', '以斯拉记', 15, 5, 5, 'しかし、ユダヤ人の長老たちの上には彼らの神の目が注がれていたので、このことがダレイオスに報告されて、さらにこのことについての返事の手紙が来るまで、彼らの工事を中止させることができなかった。'),
('JPN', '以斯拉记', 15, 5, 6, 'ユーフラテス川西方の総督タテナイと、シェタル・ボゼナイと、その同僚のユーフラテス川西方にいる知事たちが、ダレイオス王に送った書状の写しは次のとおりである。'),
('JPN', '以斯拉记', 15, 5, 7, '彼らが王に送った報告には次のように書かれていた。「ダレイオス王に全き平安がありますように。'),
('JPN', '以斯拉记', 15, 5, 8, '王にお知らせいたします。私たちはユダ州に行き、あの大いなる神の宮に行ってみましたが、それは大きな石で建てられていて、壁には木材が組まれていました。その工事は彼らの手で着々と進められ、順調に行われています。'),
('JPN', '以斯拉记', 15, 5, 9, 'そこで、私たちはその長老たちに尋ねて、彼らに次のように言いました。『この宮を建て、この城壁を修復せよとの命令をだれがあなたがたに下したのか。』'),
('JPN', '以斯拉记', 15, 5, 10, '私たちはまた、あなたにお知らせするために彼らにその名を尋ねました。それは、彼らの先頭に立っている者の名を書き記すためでした。'),
('JPN', '以斯拉记', 15, 5, 11, 'すると、彼らは次のように私たちに返事をしました。『私たちこそは天と地の神のしもべであり、ずっと昔から建っていた宮を建て直しているのです。それはイスラエルの大王が建てて、完成させたものです。'),
('JPN', '以斯拉记', 15, 5, 12, 'しかし、私たちの先祖が天の神を怒らせたので、神は彼らを、カルデア人であるバビロンの王ネブカドネツァルの手に渡されました。彼はこの宮を破壊し、民を捕らえてバビロンに移したのです。'),
('JPN', '以斯拉记', 15, 5, 13, 'しかし、バビロンの王キュロスの第一年に、キュロス王はこの神の宮を建て直すよう命令を下しました。'),
('JPN', '以斯拉记', 15, 5, 14, 'キュロス王はまた、ネブカドネツァルがエルサレムの神殿から持ち出して、バビロンの神殿に運んで行った神の宮の金や銀の器を、バビロンの神殿から取り出し、自分が総督に任命したシェシュバツァルという名の者にそれを渡しました。'),
('JPN', '以斯拉记', 15, 5, 15, 'そして、シェシュバツァルに、これらの器を携えて行ってエルサレムの神殿に納め、神の宮を元の場所に建て直せと言いました。'),
('JPN', '以斯拉记', 15, 5, 16, 'そこで、このシェシュバツァルは来て、エルサレムの神の宮の礎を据えました。その時から今に至るまで建築が続いていますが、まだ完成していません。』'),
('JPN', '以斯拉记', 15, 5, 17, 'ですから、王様、もしもよろしければ、エルサレムにあるこの神の宮を建てるために、キュロス王からの命令が下ったのが事実かどうか、あのバビロンにある王室書庫をお調べください。そして、このことについての王のご判断を私たちにお伝えください。」'),
('JPN', '以斯拉记', 15, 6, 1, 'それでダレイオス王は命令を下し、重要文書を納めてあるバビロンの文書保管所を調べさせたところ、'),
('JPN', '以斯拉记', 15, 6, 2, 'メディア州の城の中のエクバタナで一つの巻物が見つかった。その中に次のように書かれていた。「記録。'),
('JPN', '以斯拉记', 15, 6, 3, 'キュロス王の第一年にキュロス王は命令を下した。エルサレムにある神の宮、いけにえが献げられる宮を建て、その礎を定めよ。宮の高さは六十キュビト、その幅も六十キュビト。'),
('JPN', '以斯拉记', 15, 6, 4, '大きな石の層は三段。木材の層は一段とする。その費用は王家から支払われる。'),
('JPN', '以斯拉记', 15, 6, 5, 'また、ネブカドネツァルがエルサレムの神殿から持ち出して、バビロンに運んで来た神の宮の金や銀の器は返し、エルサレムの神殿に運んで元の場所に戻す。こうして、それらを神の宮に納める。」'),
('JPN', '以斯拉记', 15, 6, 6, '王は次のように命じた。「それゆえ、今、ユーフラテス川西方の総督タテナイと、シェタル・ボゼナイと、その同僚たちでユーフラテス川西方の地にいる知事たちよ。そこから遠ざかれ。'),
('JPN', '以斯拉记', 15, 6, 7, 'この神の宮の工事をそのままやらせておけ。ユダヤ人の総督とユダヤ人の長老たちに、この神の宮を元の場所に建てさせよ。'),
('JPN', '以斯拉记', 15, 6, 8, '私は、さらに、この神の宮を建てるために、あなたがたがこれらユダヤ人の長老たちにどうすべきか、命令を下す。王の収益としてのユーフラテス川西方の地の貢ぎ物の中から、その費用を間違いなくそれらの者たちに支払って、滞らぬようにせよ。'),
('JPN', '以斯拉记', 15, 6, 9, 'また、その必要とする物、すなわち、天の神に献げる全焼のささげ物のための雄牛、雄羊、子羊、また小麦、塩、ぶどう酒、油を、エルサレムにいる祭司たちの求めに応じて、毎日怠りなく彼らに与えよ。'),
('JPN', '以斯拉记', 15, 6, 10, 'こうして彼らが天の神に芳ばしい香りを献げ、王と王子たちの長寿を祈るようにせよ。'),
('JPN', '以斯拉记', 15, 6, 11, '私は命令を下す。だれであれ、この法令を犯す者があれば、その家から梁を引き抜き、その者をその上にはりつけにしなければならない。このことのゆえに、その家はごみの山としなければならない。'),
('JPN', '以斯拉记', 15, 6, 12, 'エルサレムに御名を住まわせられた神が、この命令を変更してエルサレムにあるこの神の宮を破壊しようと手を下す王や民をみな、投げ倒されますように。私ダレイオスはここに命令を下す。間違いなくこれを守れ。」'),
('JPN', '以斯拉记', 15, 6, 13, 'ダレイオス王がこう書き送ったので、ユーフラテス川西方の総督タテナイと、シェタル・ボゼナイと、その同僚たちは、間違いなくこれを行った。'),
('JPN', '以斯拉记', 15, 6, 14, 'ユダヤ人の長老たちは、預言者ハガイとイドの子ゼカリヤの預言を通し、建築を行って成功した。彼らはイスラエルの神の命令により、またキュロスとダレイオスと、ペルシアの王アルタクセルクセスの命令によって、建築を終えた。'),
('JPN', '以斯拉记', 15, 6, 15, 'こうして、この宮はダレイオス王の治世の第六年、アダルの月の三日に完成した。'),
('JPN', '以斯拉记', 15, 6, 16, 'イスラエルの子ら、すなわち、祭司、レビ人、そのほかの捕囚から帰って来た人たちは、喜びをもってこの神の宮の奉献式を祝った。'),
('JPN', '以斯拉记', 15, 6, 17, '彼らはこの神の宮の奉献式のために、雄牛百頭、雄羊二百匹、子羊四百匹を献げた。また、イスラエルの部族の数にしたがって、全イスラエルのために罪のきよめのささげ物として、雄やぎ十二匹を献げた。'),
('JPN', '以斯拉记', 15, 6, 18, 'また彼らは、エルサレムでの神への奉仕のため、祭司をその区分にしたがって、レビ人をその組にしたがってそれぞれ任命した。モーセの書に記されているとおりである。'),
('JPN', '以斯拉记', 15, 6, 19, '捕囚から帰って来た人々は、第一の月の十四日に過越を祝った。'),
('JPN', '以斯拉记', 15, 6, 20, '祭司とレビ人たちは一人残らず身をきよめて、みなきよくなっていたので、捕囚から帰って来たすべての人々のため、彼らの同胞の祭司たちのため、また彼ら自身のために、過越のいけにえを屠った。'),
('JPN', '以斯拉记', 15, 6, 21, '捕囚から戻って来たイスラエル人はこれを食べた。イスラエルの神、主を求めて、その地の異邦の民の汚れから離れて彼らに加わった者たちもみなそうした。'),
('JPN', '以斯拉记', 15, 6, 22, 'そして彼らは七日間、喜びをもって種なしパンの祭りを守った。これは、主が彼らを喜ばせ、またアッシリアの王の心を彼らに向けて、イスラエルの神である神の宮の工事にあたって、彼らを力づけるようにされたからである。'),
('JPN', '以斯拉记', 15, 7, 1, 'これらの出来事の後、ペルシアの王アルタクセルクセスの治世に、セラヤの子エズラという人がいた。セラヤはアザルヤの子、順次、ヒルキヤの子、'),
('JPN', '以斯拉记', 15, 7, 2, 'シャルムの子、ツァドクの子、アヒトブの子、'),
('JPN', '以斯拉记', 15, 7, 3, 'アマルヤの子、アザルヤの子、メラヨテの子、'),
('JPN', '以斯拉记', 15, 7, 4, 'ゼラフヤの子、ウジの子、ブキの子、'),
('JPN', '以斯拉记', 15, 7, 5, 'アビシュアの子、ピネハスの子、エルアザルの子、このエルアザルは祭司のかしらアロンの子である。'),
('JPN', '以斯拉记', 15, 7, 6, 'このエズラがバビロンから上って来たのである。彼はイスラエルの神、主がお与えになったモーセの律法に通じている学者であった。彼の神、主の御手が彼の上にあったので、王は彼の願いをすべてかなえた。'),
('JPN', '以斯拉记', 15, 7, 7, 'アルタクセルクセス王の第七年に、イスラエル人の一部、および祭司、レビ人、歌い手、門衛、宮のしもべの一部が、エルサレムに上って来た。'),
('JPN', '以斯拉记', 15, 7, 8, 'エズラは王の第七年の第五の月にエルサレムに着いた。'),
('JPN', '以斯拉记', 15, 7, 9, 'すなわち、彼は第一の月の一日にバビロンを出発した。彼の神の恵みの御手は確かに彼の上にあり、第五の月の一日に、彼はエルサレムに着いた。'),
('JPN', '以斯拉记', 15, 7, 10, 'エズラは、主の律法を調べ、これを実行し、イスラエルで掟と定めを教えようと心を定めていた。'),
('JPN', '以斯拉记', 15, 7, 11, 'アルタクセルクセス王が、祭司であり学者であったエズラに与えた手紙の写しは次のとおりである。このエズラは、主の命令のことばと、イスラエルに関する主の掟に精通していた。'),
('JPN', '以斯拉记', 15, 7, 12, '「王の王アルタクセルクセス。天の神の律法の学者である祭司エズラへ。中略。さて、'),
('JPN', '以斯拉记', 15, 7, 13, '私は命令を下す。私の国にいるイスラエルの民、その祭司、レビ人のうち、だれでも自分から進んでエルサレムに上って行きたい者は、あなたと一緒に行ってよい。'),
('JPN', '以斯拉记', 15, 7, 14, 'なぜなら、あなたは王とその七人の顧問によって遣わされているからである。それは、あなたの手にあるあなたの神の律法にしたがって、ユダとエルサレムを調査するためである。'),
('JPN', '以斯拉记', 15, 7, 15, 'また、王とその顧問たちが、エルサレムを住まいとされるイスラエルの神に進んで献げた銀と金を、'),
('JPN', '以斯拉记', 15, 7, 16, 'またバビロン全州であなたが得るすべての銀と金を、それに、エルサレムにある自分たちの神の宮のために、民と祭司たちが進んで献げたささげ物を合わせて、携えて行くためである。'),
('JPN', '以斯拉记', 15, 7, 17, 'それゆえ、あなたはその献金で、雄牛、雄羊、子羊、また、そのための穀物のささげ物と注ぎのぶどう酒を怠りなく買い求め、エルサレムにあるあなたがたの神の宮の祭壇の上で、それを献げなければならない。'),
('JPN', '以斯拉记', 15, 7, 18, 'また、残りの銀と金の使い方については、あなたとあなたの兄弟たちが良いと思うことは何でも、あなたがたの神のみむねにしたがって行うがよい。'),
('JPN', '以斯拉记', 15, 7, 19, 'また、あなたの神の宮での礼拝のために渡された用具は、エルサレムの神の前に供えよ。'),
('JPN', '以斯拉记', 15, 7, 20, 'そのほか、あなたの神の宮のために必要なもので、どうしても支出しなければならないものは、王室の金庫からそれを支出してよい。'),
('JPN', '以斯拉记', 15, 7, 21, '私アルタクセルクセス王は、ユーフラテス川西方の財務官全員に命令を下す。天の神の律法の学者である祭司エズラが、あなたがたに求めることは何でも、怠りなくそれを行え。'),
('JPN', '以斯拉记', 15, 7, 22, 'すなわち、銀は百タラントまで、小麦は百コルまで、ぶどう酒は百バテまで、油も百バテまで、塩は制限なし。'),
('JPN', '以斯拉记', 15, 7, 23, '天の神の宮のために、天の神によって命じられていることは何でも、熱心に行え。御怒りが王とその子たちの国に下るといけないから。'),
('JPN', '以斯拉记', 15, 7, 24, 'また次のことを知らせる。祭司、レビ人、歌い手、門衛、宮のしもべ、すなわち、この神の宮に仕える者たちにはだれに対しても、貢ぎ物、関税、税金を課してはならない。'),
('JPN', '以斯拉记', 15, 7, 25, 'エズラよ。あなたは自分の手にあるあなたの神の知恵にしたがって、さばき人や裁判官を任命し、ユーフラテス川西方にいるすべての民、すなわち、あなたの神の律法を知っているすべての者をさばかせよ。またあなたがたは、これを知らない者に教えよ。'),
('JPN', '以斯拉记', 15, 7, 26, 'あなたの神の律法と王の律法を守らない者には、だれに対しても、死刑でも、追放でも、財産の没収でも、投獄でも、その判決を厳格に執行せよ。」'),
('JPN', '以斯拉记', 15, 7, 27, '私たちの父祖の神、主がほめたたえられますように。主はエルサレムにある主の宮に栄光を与えるために、このようなことを王の心に起こさせ、'),
('JPN', '以斯拉记', 15, 7, 28, '王とその顧問と、王の有力な高官すべての前で私に恵みを得させてくださった。私の神、主の御手が私の上にあったので、私は奮い立って、一緒に上るイスラエル人のかしらたちを集めることができた。'),
('JPN', '以斯拉记', 15, 8, 1, 'アルタクセルクセス王の治世に、バビロンから私と一緒に上って来た一族のかしらと、その系図の記載は次のとおりである。'),
('JPN', '以斯拉记', 15, 8, 2, 'ピネハス族からはゲルショム。イタマル族からはダニエル。ダビデ族からはハトシュ。'),
('JPN', '以斯拉记', 15, 8, 3, 'ハトシュはシェカンヤの孫。パルオシュ族からは、ゼカリヤと、系図に記載された同行の者、男子百五十人。'),
('JPN', '以斯拉记', 15, 8, 4, 'パハテ・モアブ族からは、ゼラフヤの子エルエホエナイと、同行の男子二百人。'),
('JPN', '以斯拉记', 15, 8, 5, 'ザト族からは、ヤハジエルの子シェカンヤと、同行の男子三百人。'),
('JPN', '以斯拉记', 15, 8, 6, 'アディン族からは、ヨナタンの子エベデと、同行の男子五十人。'),
('JPN', '以斯拉记', 15, 8, 7, 'エラム族からは、アタルヤの子エシャヤと、同行の男子七十人。'),
('JPN', '以斯拉记', 15, 8, 8, 'シェファテヤ族からは、ミカエルの子ゼバデヤと、同行の男子八十人。'),
('JPN', '以斯拉记', 15, 8, 9, 'ヨアブ族からは、エヒエルの子オバデヤと、同行の男子二百十八人。'),
('JPN', '以斯拉记', 15, 8, 10, 'バニ族からは、ヨシフヤの子シェロミテと、同行の男子百六十人。'),
('JPN', '以斯拉记', 15, 8, 11, 'ベバイ族からは、ベバイの子ゼカリヤと、同行の男子二十八人。'),
('JPN', '以斯拉记', 15, 8, 12, 'アズガデ族からは、ハ・カタンの子ヨハナンと、同行の男子百十人。'),
('JPN', '以斯拉记', 15, 8, 13, 'アドニカム族からの者は最後の者たちで、その名はエリフェレテ、エイエル、シェマヤ、および彼らと同行の男子六十人。'),
('JPN', '以斯拉记', 15, 8, 14, 'ビグワイ族からは、ウタイとザクルと、同行の男子七十人。'),
('JPN', '以斯拉记', 15, 8, 15, '私はアハワに流れる川のほとりに彼らを集め、私たちはそこに三日間宿営した。私はそこに民と祭司たちを確認したが、レビ人は見つけることができなかった。'),
('JPN', '以斯拉记', 15, 8, 16, 'それで私は、かしらのエリエゼル、アリエル、シェマヤ、エルナタン、ヤリブ、エルナタン、ナタン、ゼカリヤ、メシュラムと、教師エホヤリブ、エルナタンを呼び集め、'),
('JPN', '以斯拉记', 15, 8, 17, 'カシフヤ地方のかしらイドについて、彼らに指示した。すなわち、イドとその同僚、またカシフヤ地方にいる宮のしもべたちに対して、私たちの神の宮に仕える者たちを送ってもらうためには何と言えばよいか、彼らにことばを授けた。'),
('JPN', '以斯拉记', 15, 8, 18, '私たちの神の恵みの御手が私たちの上にあったので、彼らはイスラエルの子、レビの子、マフリの子のうちから賢明な者、シェレベヤと、その子たち、およびその兄弟たち十八人を私たちのところに連れて来てくれた。'),
('JPN', '以斯拉记', 15, 8, 19, 'また、ハシャブヤとともに、メラリの子のうちからエシャヤと、その兄弟と、その子たち二十人、'),
('JPN', '以斯拉记', 15, 8, 20, 'および、ダビデとその高官たちにより、レビ人に奉仕するよう任命されていた宮のしもべたちのうちから、二百二十人の宮のしもべたちを連れて来た。これらの者はみな、指名された者であった。'),
('JPN', '以斯拉记', 15, 8, 21, '私はそこ、アハワ川のほとりで断食を布告した。それは、私たちの神の前でへりくだり、私たちのために、私たちの子どもたちと、私たちのすべての持ち物のために、道中の無事を神に願い求めるためであった。'),
('JPN', '以斯拉记', 15, 8, 22, 'それは私が、道中の敵から私たちを助ける部隊と騎兵たちを、王に求めるのを恥じたからであった。実際、私たちは王に、「私たちの神の御手は、神を尋ね求めるすべての者の上に幸いを下し、その力と怒りは、神を捨てるすべての者の上に下る」と言っていたのである。'),
('JPN', '以斯拉记', 15, 8, 23, 'そのため私たちはこのことのために断食して、自分たちの神に願い求めた。すると、神は私たちの願いを聞き入れてくださった。'),
('JPN', '以斯拉记', 15, 8, 24, '私は祭司長たちのうちから十二人、すなわち、シェレベヤとハシャブヤ、および彼らの同僚十人を選り分けた。'),
('JPN', '以斯拉记', 15, 8, 25, 'そして、王、顧問たち、高官たち、および、そこにいたすべてのイスラエル人が献げた、私たちの神の宮への奉納物である銀、金、器を量って、彼らに渡した。'),
('JPN', '以斯拉记', 15, 8, 26, '私は銀六百五十タラント、百タラント相当の銀の器、および金百タラントを量って、彼らに渡した。'),
('JPN', '以斯拉记', 15, 8, 27, 'また、一千ダリク相当の金の鉢二十、さらに、金のように高価な、光り輝く見事な青銅の器二個を彼らに渡した。'),
('JPN', '以斯拉记', 15, 8, 28, 'それから私は彼らに言った。「あなたがたは主の聖なるものである。この器も聖なるものである。この銀と金は、あなたがたの父祖の神、主に対する、進んで献げるものである。'),
('JPN', '以斯拉记', 15, 8, 29, 'あなたがたは、エルサレムの主の宮の部屋で、祭司長たち、レビ人たち、イスラエルの一族の長たちの前で重さを量るまで、寝ずの番をしてそれらを守りなさい。」'),
('JPN', '以斯拉记', 15, 8, 30, '祭司とレビ人たちは、重さを量った銀、金、器を、エルサレムの私たちの神の宮に持って行くために受け取った。'),
('JPN', '以斯拉记', 15, 8, 31, '私たちはエルサレムに行こうと、第一の月の十二日にアハワ川を出発した。私たちの神の御手が私たちの上にあり、その道中、敵の手、待ち伏せする者の手から私たちを救い出してくださった。'),
('JPN', '以斯拉记', 15, 8, 32, 'こうして私たちはエルサレムに着いて、そこに三日間とどまった。'),
('JPN', '以斯拉记', 15, 8, 33, '四日目に銀と金と器が私たちの神の宮の中で量られ、ウリヤの子の祭司メレモテの手に渡された。彼とともにピネハスの子エルアザルがいて、彼らとともに、レビ人である、ヨシュアの子エホザバデとビヌイの子ノアデヤがいた。'),
('JPN', '以斯拉记', 15, 8, 34, 'すべてが数えられ、量られた。そのとき全重量が書き留められた。'),
('JPN', '以斯拉记', 15, 8, 35, '捕囚の人々で、捕囚から帰って来た者は、イスラエルの神に全焼のささげ物を献げた。すなわち、全イスラエルのために雄牛十二頭、雄羊九十六匹、子羊七十七匹、罪のきよめのささげ物として雄やぎ十二匹を献げた。これはすべて主への全焼のささげ物であった。'),
('JPN', '以斯拉记', 15, 8, 36, 'それから、彼らは王の命令書を、王の太守たちとユーフラテス川西方の総督たちに渡した。この人たちはこの民と神の宮に援助を与えた。'),
('JPN', '以斯拉记', 15, 9, 1, 'これらのことが終わった後、指導者たちが私のところに近づいて来て次のように言った。「イスラエルの民、祭司、レビ人は、カナン人、ヒッタイト人、ペリジ人、エブス人、アンモン人、モアブ人、エジプト人、アモリ人など異国の忌み嫌うべき習慣と縁を絶つことなく、'),
('JPN', '以斯拉记', 15, 9, 2, 'かえって、彼らも息子たちも、これらの国々の娘を妻にし、聖なる種族がもろもろの地の民と混じり合ってしまいました。しかも、指導者たち、代表者たちがこの不信の罪の張本人なのです。」'),
('JPN', '以斯拉记', 15, 9, 3, '私はこのことを聞いて、衣と上着を引き裂き、髪の毛とひげを引き抜き、茫然として座り込んでしまった。'),
('JPN', '以斯拉记', 15, 9, 4, '捕囚から帰って来た人々の不信の罪のことで、イスラエルの神のことばを恐れかしこむ者はみな、私のところに集まって来た。私は夕方のささげ物の時刻まで、茫然としてそこに座っていた。'),
('JPN', '以斯拉记', 15, 9, 5, '夕方のささげ物の時刻になって、打ちのめされていた私は立ち上がり、衣と上着を引き裂いたまま、ひざまずき、自分の神、主に向かって手を伸べ広げて、'),
('JPN', '以斯拉记', 15, 9, 6, 'こう言った。「私の神よ。私は恥じています。私の神よ。私はあなたに向かって顔を上げることを恥ずかしく思います。私たちの咎は増し、私たちの頭より高くなり、私たちの罪過は大きく、天にまで達したからです。'),
('JPN', '以斯拉记', 15, 9, 7, '私たちの先祖の時代から今日まで、私たちは大きな罪過の中にありました。私たちのその咎のため、私たちや、私たちの王、祭司たちは、諸国の王たちの手に渡され、剣にかけられ、捕虜にされ、かすめ奪われ、面目を失って、今日あるとおりです。'),
('JPN', '以斯拉记', 15, 9, 8, 'しかし今、しばらくの間、私たちの神、主はそのあわれみによって、私たちに逃れの者を残し、私たちのためにご自分の聖なる所に一本の杭を与えてくださいました。これは、私たちの神が私たちの目を明るくし、奴隷の身の私たちを少しでも生き延びさせてくださるためでした。'),
('JPN', '以斯拉记', 15, 9, 9, '事実、私たちは奴隷です。しかし私たちの神は、この奴隷の身の私たちを見捨てることなく、かえって、ペルシアの王たちによって恵みを施し、私たちを生かして、私たちの神の宮を建て直させ、その廃墟を元に戻し、ユダとエルサレムに石垣を下さいました。'),
('JPN', '以斯拉记', 15, 9, 10, 'こうなった今、何と言えばよいのでしょうか。私たちの神よ、私たちはあなたの命令を捨てたのです。'),
('JPN', '以斯拉记', 15, 9, 11, 'あなたは、あなたのしもべである預言者たちによって、こう命じておられました。『あなたがたが入って行って所有しようとしている地は、異国の汚れで汚れた地、忌み嫌うべき行いによって隅々まで汚れで満ちてしまった地である。'),
('JPN', '以斯拉记', 15, 9, 12, 'だから今、あなたがたの娘を彼らの息子に嫁がせてはならない。また、彼らの娘をあなたがたの息子の妻にしてはならない。永久に彼らの平安も幸せも求めてはならない。それは、あなたがたが強くなり、その地の良い物を食べ、これを永久にあなたがたの子孫の所有とするためである』と。'),
('JPN', '以斯拉记', 15, 9, 13, '私たちの悪い行いと大きな罪過のゆえに、様々なことが私たちの上に起こりましたが、私たちの神、あなたは、私たちの咎に値するよりも軽い罰を与え、逃れの者をこのように私たちに備えてくださいました。そのようなことの後で、'),
('JPN', '以斯拉记', 15, 9, 14, '私たちは再びあなたの命令を破って、忌み嫌うべき行いをするこれらの民と、姻戚関係に入ってよいのでしょうか。あなたは怒って、ついには私たちを絶ち滅ぼし、残りの者も、逃れの者もいないようにされるのではないでしょうか。'),
('JPN', '以斯拉记', 15, 9, 15, 'イスラエルの神、主よ、あなたは正しい方です。まことに、今日あるとおり、私たちは逃れの者として残されています。ご覧ください。私たちは罪過を負ってあなたの御前におります。このような状態で、だれもあなたの御前に立つことはできないにもかかわらず。」'),
('JPN', '以斯拉记', 15, 10, 1, 'エズラが神の宮の前でひれ伏して、涙ながらに祈り告白しているとき、男や女や子どもの大会衆がイスラエルのうちから彼のところに集まって来た。民は涙を流して激しく泣いた。'),
('JPN', '以斯拉记', 15, 10, 2, 'そのとき、エラムの子孫の一人エヒエルの子シェカンヤが、エズラに言った。「私たちは、自分たちの神の信頼を裏切り、この地の民である異国人の女を妻にしました。しかし、このことについてイスラエルには今なお望みがあります。'),
('JPN', '以斯拉记', 15, 10, 3, '今、私たちは自分たちの神と契約を結び、主の勧告と、私たちの神の命令を恐れかしこむ人々の勧告にしたがって、これらの妻たちと、その子どもたちをみな追い出しましょう。律法にしたがってこれを行いましょう。'),
('JPN', '以斯拉记', 15, 10, 4, '立ち上がってください。このことはあなたの肩にかかっています。私たちはあなたに協力します。勇気を出して、実行してください。」'),
('JPN', '以斯拉记', 15, 10, 5, 'エズラは立ち上がり、祭司、レビ人、全イスラエルの長たちに、この提案を実行するよう誓わせた。すると彼らは誓った。'),
('JPN', '以斯拉记', 15, 10, 6, 'エズラは神の宮の前を去って、エルヤシブの子ヨハナンの部屋に行った。そこに行って、パンも食べず、水も飲まずにいた。捕囚から帰って来た人々の不信の罪を嘆き悲しんだのである。'),
('JPN', '以斯拉记', 15, 10, 7, 'そして、通達がユダとエルサレムに出された。それは、捕囚から帰って来た者はみなエルサレムに集合するように、というものであり、'),
('JPN', '以斯拉记', 15, 10, 8, 'また、三日のうちに来ない者はみな、指導者たちや長老たちの決定にしたがってその全財産を聖絶され、さらにその人は、捕囚から帰って来た人々の会衆から除名される、としていた。'),
('JPN', '以斯拉记', 15, 10, 9, 'ユダとベニヤミンの男はみな、三日のうちにエルサレムに集まって来た。それは第九の月の二十日であった。こうして、すべての民は神の宮の前の広場に座り、この件で、また大雨のために震えていた。'),
('JPN', '以斯拉记', 15, 10, 10, '祭司エズラは立ち上がって、彼らに言った。「あなたがたは神の信頼を裏切った。異国人の女を妻にし、イスラエルの罪過を増し加えた。'),
('JPN', '以斯拉记', 15, 10, 11, 'だから今、あなたがたの父祖の神、主に告白して、そのみむねにかなったことをしなさい。この地の民、異国人の女たちから離れなさい。」'),
('JPN', '以斯拉记', 15, 10, 12, '全会衆は大声をあげて答えた。「必ずあなたの言われたとおりにします。'),
('JPN', '以斯拉记', 15, 10, 13, 'しかし、民は大勢いて、大雨の時期ですから、私たちは外に立っていることができません。しかも、これは一日や二日の仕事でもありません。私たちはこのことで大いに背いてきたのですから。'),
('JPN', '以斯拉记', 15, 10, 14, '全会衆を代表して私たちの指導者たちに、ここにとどまっていただきたい。そして、私たちの町で異国人の女を妻にした者はみな、定められた時に、それぞれの町の長老たち、さばき人たちと一緒に出頭するようにしていただきたい。そうすれば、このことについての私たちの神の燃える怒りは、私たちから去るでしょう。」'),
('JPN', '以斯拉记', 15, 10, 15, 'アサエルの子ヨナタンとティクワの子ヤフゼヤだけはこれに反対し、メシュラムとレビ人シャベタイの支持を得たが、'),
('JPN', '以斯拉记', 15, 10, 16, '捕囚から帰って来た人々は、その提案どおりにした。祭司エズラは、彼らの一族のそれぞれのために、かしらの者たちを、みな名指しで選り分けた。こうして、彼らはこの件を調べるために第十の月の一日に検討を始め、'),
('JPN', '以斯拉记', 15, 10, 17, '第一の月の一日までに、異国人の女を妻にした男たちについて、みな調べ終えた。'),
('JPN', '以斯拉记', 15, 10, 18, '祭司の子らのうちで異国人の女を妻にした者が分かった。エホツァダクの子ヨシュアの息子たちと、その兄弟たちのうちのマアセヤ、エリエゼル、ヤリブ、ゲダルヤであった。'),
('JPN', '以斯拉记', 15, 10, 19, '彼らはその妻を離縁すると誓い、自分たちの罪過のために、雄羊一匹を代償のささげ物として献げた。'),
('JPN', '以斯拉记', 15, 10, 20, 'イメル族のうちでは、ハナニとゼバデヤ。'),
('JPN', '以斯拉记', 15, 10, 21, 'ハリム族のうちでは、マアセヤ、エリヤ、シェマヤ、エヒエル、ウジヤ。'),
('JPN', '以斯拉记', 15, 10, 22, 'パシュフル族のうちでは、エルヨエナイ、マアセヤ、イシュマエル、ネタンエル、エホザバデ、エルアサ。'),
('JPN', '以斯拉记', 15, 10, 23, 'レビ人のうちでは、エホザバデ、シムイ、ケラヤすなわちケリタ、ペタフヤ、ユダ、エリエゼル。'),
('JPN', '以斯拉记', 15, 10, 24, '歌い手のうちでは、エルヤシブ。門衛のうちでは、シャルム、テレム、ウリ。'),
('JPN', '以斯拉记', 15, 10, 25, '一般のイスラエル人のうち、パルオシュ族のうちでは、ラムヤ、イジヤ、マルキヤ、ミヤミン、エルアザル、マルキヤ、ベナヤ。'),
('JPN', '以斯拉记', 15, 10, 26, 'エラム族のうちでは、マタンヤ、ゼカリヤ、エヒエル、アブディ、エレモテ、エリヤ。'),
('JPN', '以斯拉记', 15, 10, 27, 'ザト族のうちでは、エルヨエナイ、エルヤシブ、マタンヤ、エレモテ、ザバデ、アジザ。'),
('JPN', '以斯拉记', 15, 10, 28, 'ベバイ族のうちでは、ヨハナン、ハナンヤ、ザバイ、アテライ。'),
('JPN', '以斯拉记', 15, 10, 29, 'バニ族のうちでは、メシュラム、マルク、アダヤ、ヤシュブ、シェアル、ラモテ。'),
('JPN', '以斯拉记', 15, 10, 30, 'パハテ・モアブ族のうちでは、アデナ、ケラル、ベナヤ、マアセヤ、マタンヤ、ベツァルエル、ビヌイ、マナセ。'),
('JPN', '以斯拉记', 15, 10, 31, 'ハリム族のうちでは、エリエゼル、イシヤ、マルキヤ、シェマヤ、シメオン、'),
('JPN', '以斯拉记', 15, 10, 32, 'ベニヤミン、マルク、シェマルヤ。'),
('JPN', '以斯拉记', 15, 10, 33, 'ハシュム族のうちでは、マテナイ、マタタ、ザバデ、エリフェレテ、エレマイ、マナセ、シムイ。'),
('JPN', '以斯拉记', 15, 10, 34, 'バニ族のうちでは、マアダイ、アムラム、ウエル、'),
('JPN', '以斯拉记', 15, 10, 35, 'ベナヤ、ベデヤ、ケルフ、'),
('JPN', '以斯拉记', 15, 10, 36, 'ワンヤ、メレモテ、エルヤシブ、'),
('JPN', '以斯拉记', 15, 10, 37, 'マタンヤ、マテナイ、ヤアサイ。'),
('JPN', '以斯拉记', 15, 10, 38, 'バニ、ビヌイ、シムイ、'),
('JPN', '以斯拉记', 15, 10, 39, 'シェレムヤ、ナタン、アダヤ、'),
('JPN', '以斯拉记', 15, 10, 40, 'マクナデバイ、シャシャイ、シャライ、'),
('JPN', '以斯拉记', 15, 10, 41, 'アザルエル、シェレムヤ、シェマルヤ、'),
('JPN', '以斯拉记', 15, 10, 42, 'シャルム、アマルヤ、ヨセフ。'),
('JPN', '以斯拉记', 15, 10, 43, 'ネボ族のうちでは、エイエル、マティテヤ、ザバデ、ゼビナ、ヤダイ、ヨエル、ベナヤ。'),
('JPN', '以斯拉记', 15, 10, 44, 'これらの者はみな、異国人の女を妻にした者であった。彼らの妻たちの中には、すでに子を産んだ者もいた。'),
('JPN', '尼希米记', 16, 1, 1, 'ハカルヤの子ネヘミヤのことば。第二十年のキスレウの月に、私がスサの城にいたときのことであった。'),
('JPN', '尼希米记', 16, 1, 2, '私の兄弟の一人ハナニが、ユダから来た数人の者と一緒にやって来た。私は、捕囚されずに残された逃れの者であるユダヤ人たちについて、またエルサレムのことについて、彼らに尋ねた。'),
('JPN', '尼希米记', 16, 1, 3, '彼らは私に答えた。「あの州で捕囚を生き残った者たちは、大きな困難と恥辱の中にあります。そのうえ、エルサレムの城壁は崩され、その門は火で焼き払われたままです。」'),
('JPN', '尼希米记', 16, 1, 4, 'このことばを聞いたとき、私は座り込んで泣き、数日の間嘆き悲しみ、断食して天の神の前に祈った。'),
('JPN', '尼希米记', 16, 1, 5, '「ああ、天の神、主よ。大いなる恐るべき神よ。主を愛し、主の命令を守る者に対して、契約を守り、恵みを下さる方よ。'),
('JPN', '尼希米记', 16, 1, 6, 'どうか、あなたの耳を傾け、あなたの目を開いて、このしもべの祈りを聞いてください。私は今、あなたのしもべイスラエルの子らのために、昼も夜も御前に祈り、私たちがあなたに対して犯した、イスラエルの子らの罪を告白しています。まことに、私も私の父の家も罪を犯しました。'),
('JPN', '尼希米记', 16, 1, 7, '私たちはあなたに対して非常に悪いことをして、あなたのしもべモーセにお命じになった、命令も掟も定めも守りませんでした。'),
('JPN', '尼希米记', 16, 1, 8, 'どうか、あなたのしもべモーセにお命じになったことばを思い起こしてください。『あなたがたが信頼を裏切るなら、わたしはあなたがたを諸国の民の間に散らす。'),
('JPN', '尼希米记', 16, 1, 9, 'あなたがたがわたしに立ち返り、わたしの命令を守り行うなら、たとえ、あなたがたのうちの散らされた者が天の果てにいても、わたしは彼らをそこから集め、わたしの名を住まわせるためにわたしが選んだ場所に連れて来る。』'),
('JPN', '尼希米记', 16, 1, 10, 'これらの者たちこそ、あなたがその偉大な力と力強い御手をもって贖い出された、あなたのしもべ、あなたの民です。'),
('JPN', '尼希米记', 16, 1, 11, 'ああ、主よ。どうかこのしもべの祈りと、喜んであなたの名を恐れるあなたのしもべたちの祈りに耳を傾けてください。どうか今日、このしもべに幸いを見させ、この人の前で、あわれみを受けさせてくださいますように。」そのとき、私は王の献酌官であった。'),
('JPN', '尼希米记', 16, 2, 1, 'アルタクセルクセス王の第二十年のニサンの月に、王の前にぶどう酒が出されたとき、私はぶどう酒を取り、王に差し上げた。それまで、私は王の前で気持ちが沈んでいたことはなかった。'),
('JPN', '尼希米记', 16, 2, 2, 'すると、王は私に言った。「病気でもなさそうなのに、なぜ、そのように沈んだ顔をしているのか。きっと心に悲しみがあるに違いない。」私は非常に恐れて、'),
('JPN', '尼希米记', 16, 2, 3, '王に言った。「王よ、永遠に生きられますように。私の先祖の墓がある都が廃墟となり、その門が火で焼き尽くされているというのに、どうして沈んだ顔をしないでいられるでしょうか。」'),
('JPN', '尼希米记', 16, 2, 4, '王は私に言った。「では、何を望んでいるのか。」私は天の神に祈ってから、'),
('JPN', '尼希米记', 16, 2, 5, '王に答えた。「もしも王が良しとされ、このしもべにご好意をいただけますなら、私をユダの地、私の先祖の墓のある都へ遣わして、それを再建させてください。」'),
('JPN', '尼希米记', 16, 2, 6, '王は私に言った。王妃もそばに座っていた。「旅はどのくらいかかるのか。いつ戻って来るのか。」王はこれを良しとして、私を遣わしてくださることになり、私は予定を伝えた。'),
('JPN', '尼希米记', 16, 2, 7, 'また私は王にこう言った。「もしも王様がよろしければ、ユダに着くまで私が通行できるように、ユーフラテス川西方の総督たちへの手紙をいただけるでしょうか。'),
('JPN', '尼希米记', 16, 2, 8, 'そして、宮の城門の梁を置くため、また、あの都の城壁と私が入る家のために木材をもらえるように、王家の園の管理人アサフへの手紙もお願いします。」わが神の恵みの御手が私の上にあったので、王はそれをかなえてくださった。'),
('JPN', '尼希米记', 16, 2, 9, 'それで私はユーフラテス川西方の総督たちのところに行き、王の手紙を彼らに手渡した。王は、軍の高官たちと騎兵たちを私とともに送り出してくださった。'),
('JPN', '尼希米记', 16, 2, 10, 'ホロン人サンバラテと、アンモン人でその部下のトビヤは、これを聞いて非常に不機嫌になった。イスラエル人の益を求める者がやって来たからである。'),
('JPN', '尼希米记', 16, 2, 11, 'こうして私はエルサレムに着いて、そこに三日間とどまった。'),
('JPN', '尼希米记', 16, 2, 12, 'ある夜、私は起きて出て行った。ほかに数人の者も一緒であった。しかし私は、私の神がエルサレムのためにさせようと私の心に示しておられることを、だれにも告げなかった。また私自身が乗った動物のほかに、動物はいなかった。'),
('JPN', '尼希米记', 16, 2, 13, '私は夜、谷の門を通って竜の泉の方、糞の門のところに出て行き、エルサレムの城壁を調べた。それは崩され、その門は火で焼き尽くされていた。'),
('JPN', '尼希米记', 16, 2, 14, 'さらに、泉の門と王の池の方へ進んで行ったが、私が乗っていた動物の通れる場所がなかった。'),
('JPN', '尼希米记', 16, 2, 15, '夜のうちに流れを上って行って、城壁を調べた。そしてまた引き返し、谷の門を通って戻った。'),
('JPN', '尼希米记', 16, 2, 16, '代表者たちは、私がどこへ行っていたか、また私が何をしていたかを知らなかった。ユダヤ人にも、祭司たちにも、有力者たちにも、代表者たちにも、そのほか工事をする者たちにも、その時まで私は何も告げていなかった。'),
('JPN', '尼希米记', 16, 2, 17, '私は彼らに言った。「私たちが直面している困難は見てのとおりだ。エルサレムは廃墟となり、その門は火で焼き払われたままだ。さあ、エルサレムの城壁を築き直し、もうこれ以上、屈辱を受けないようにしよう。」'),
('JPN', '尼希米记', 16, 2, 18, 'そして、私に恵みを下さった私の神の御手のことと、また王が言ったことばを彼らに告げた。すると彼らは「さあ、再建に取りかかろう」と言って、この良い仕事に着手した。'),
('JPN', '尼希米记', 16, 2, 19, 'ところが、ホロン人サンバラテと、アンモン人でその部下のトビヤ、およびアラブ人ゲシェムは、これを聞いて私たちを嘲り、蔑んで言った。「おまえたちのしているこのことは何だ。おまえたちは王に反逆しようとしているのか。」'),
('JPN', '尼希米记', 16, 2, 20, '私は彼らにことばを返して言った。「天の神ご自身が私たちを成功させてくださる。それで、そのしもべである私たちは、再建に取りかかっているのだ。あなたがたには、エルサレムのうちに何の取り分も、権利も、ゆかりもない。」'),
('JPN', '尼希米记', 16, 3, 1, 'こうして大祭司エルヤシブは、その仲間の祭司たちと、羊の門の再建に取りかかった。彼らはそれを聖別して、扉を取り付けた。そしてメアのやぐらのところまで聖別し、ハナンエルのやぐらにまで及んだ。'),
('JPN', '尼希米记', 16, 3, 2, 'その傍らではエリコの人々が建て、その傍らではイムリの子ザクルが建てた。'),
('JPN', '尼希米记', 16, 3, 3, '魚の門はセナアの子らが建てた。彼らは梁を置き、扉、錠、かんぬきを取り付けた。'),
('JPN', '尼希米记', 16, 3, 4, '彼らの傍らではハ・コツの子ウリヤの子であるメレモテが修復を行い、その傍らではメシェザブエルの子ベレクヤの子であるメシュラムが修復を行い、その傍らではバアナの子ツァドクが修復を行った。'),
('JPN', '尼希米记', 16, 3, 5, 'その傍らではテコア人たちが修復を行ったが、彼らの貴族たちはその上役に頭を下げることはなく、工事に協力しなかった。'),
('JPN', '尼希米记', 16, 3, 6, 'エシャナの門はパセアハの子エホヤダと、ベソデヤの子メシュラムが修復を行った。彼らは梁を置き、扉、錠、かんぬきを取り付けた。'),
('JPN', '尼希米记', 16, 3, 7, '彼らの傍らでは、ギブオン人メラテヤ、メロノテ人ヤドン、それにユーフラテス川西方の総督の管轄に属する、ギブオンとミツパの人々が修復を行った。'),
('JPN', '尼希米记', 16, 3, 8, 'その傍らでは金細工人のハルハヤの子ウジエルが修復を行い、その傍らでは香料作りの一人ハナンヤが修復を行った。こうして、彼らはエルサレムを、幅広の城壁のところまで修復した。'),
('JPN', '尼希米记', 16, 3, 9, 'その傍らでは、エルサレム地区の半区の長、フルの子レファヤが修復を行った。'),
('JPN', '尼希米记', 16, 3, 10, 'その傍らではハルマフの子エダヤが自分の家のそばの部分を修復し、その傍らではハシャブネヤの子ハトシュが修復を行った。'),
('JPN', '尼希米记', 16, 3, 11, 'その続きの部分は、ハリムの子マルキヤと、パハテ・モアブの子ハシュブが、炉のやぐらと一緒に修復した。'),
('JPN', '尼希米记', 16, 3, 12, 'その傍らでは、エルサレム地区の残りの半区の長、ハ・ロヘシュの子シャルムが、自分の娘たちと一緒に修復を行った。'),
('JPN', '尼希米记', 16, 3, 13, '谷の門はハヌンと、ザノアハの住民が修復を行った。彼らはそれを建て直し、扉、錠、かんぬきを取り付け、糞の門までの城壁千キュビトを修復した。'),
('JPN', '尼希米记', 16, 3, 14, '糞の門はベテ・ハ・ケレム地区の長、レカブの子マルキヤが修復した。彼はそれを建て直し、扉、錠、かんぬきを取り付けた。'),
('JPN', '尼希米记', 16, 3, 15, '泉の門はミツパ地区の長、コル・ホゼの子シャルンが修復した。彼はそれを建て直し、屋根を付け、扉、錠、かんぬきを取り付けた。また、王の園のシェラフの池の城壁を、ダビデの町から下って来る階段のところまで修復した。'),
('JPN', '尼希米记', 16, 3, 16, 'その向こうでは、ベテ・ツル地区の半区の長、アズブクの子ネヘミヤが、ダビデの墓地のそばまでと、人工貯水池までと、勇士たちの家のところまでを修復した。'),
('JPN', '尼希米记', 16, 3, 17, 'その向こうでは、バニの子レフムなどレビ人たちが修復を行った。その傍らでは、ケイラ地区の半区の長、ハシャブヤが自分の地区のために修復を行った。'),
('JPN', '尼希米记', 16, 3, 18, 'その向こうでは、ケイラの残りの半区の長、ヘナダデの子バワイなど、彼らの同僚たちが修復を行った。'),
('JPN', '尼希米记', 16, 3, 19, 'その傍らでは、ミツパの長、ヨシュアの子エゼルが、城壁の曲がり角の隅にある武器倉に向かう上り坂のそばで、続きの部分を修復した。'),
('JPN', '尼希米记', 16, 3, 20, 'その向こうでは、ザカイの子バルクが続きの部分を、城壁の曲がり角から大祭司エルヤシブの家の門のところまで熱心に修復した。'),
('JPN', '尼希米记', 16, 3, 21, 'その向こうでは、ハ・コツの子ウリヤの子メレモテが続きの部分を、エルヤシブの家の門からエルヤシブの家の端まで、修復を行った。'),
('JPN', '尼希米记', 16, 3, 22, 'その向こうでは、低地の人々である祭司たちが修復を行った。'),
('JPN', '尼希米记', 16, 3, 23, 'その向こうでは、ベニヤミンとハシュブが自分たちの家のそばの部分を修復した。その向こうでは、アナネヤの子マアセヤの子アザルヤが自分の家の近くを修復した。'),
('JPN', '尼希米记', 16, 3, 24, 'その向こうでは、ヘナダデの子ビヌイが続きの部分を、アザルヤの家から城壁の曲がり角の隅まで修復した。'),
('JPN', '尼希米记', 16, 3, 25, 'ウザイの子パラルは、城壁の曲がり角の部分と、監視の庭のそばにあって上の王宮から突き出ているやぐらを修復した。その向こうでは、パルオシュの子ペダヤと、'),
('JPN', '尼希米记', 16, 3, 26, 'オフェルに住む宮のしもべたちが、東の方の水の門と突き出ているやぐらのそばの部分までを修復した。'),
('JPN', '尼希米记', 16, 3, 27, 'その向こうでは、テコア人が、突き出ている大きなやぐらのそばからオフェルの城壁までの続きの部分を修復した。'),
('JPN', '尼希米记', 16, 3, 28, '馬の門から上の方は、祭司たちがそれぞれ自分の家のそばの部分を修復した。'),
('JPN', '尼希米记', 16, 3, 29, 'その向こうでは、イメルの子ツァドクが自分の家のそばの部分を修復した。その向こうでは、シェカンヤの子、東の門を守る者シェマヤが修復を行った。'),
('JPN', '尼希米记', 16, 3, 30, 'その向こうでは、シェレムヤの子ハナンヤと、ツァラフの六男ハヌンが、その続きの部分を修復した。その向こうでは、ベレクヤの子メシュラムが自分の部屋のそばの部分を修復した。'),
('JPN', '尼希米记', 16, 3, 31, 'その向こうでは、金細工人の一人マルキヤが、召集の門の向かい側にある、宮のしもべたちや商人たちの家のところまでと、角の二階の部屋のところまでを修復した。'),
('JPN', '尼希米记', 16, 3, 32, '角の二階の部屋と羊の門の間は、金細工人と商人たちが修復した。'),
('JPN', '尼希米记', 16, 4, 1, 'サンバラテは私たちが城壁を築き直していることを聞くと、怒り、非常に憤慨して、ユダヤ人たちを嘲った。'),
('JPN', '尼希米记', 16, 4, 2, '彼はその同胞とサマリアの有力者たちの前で言った。「この哀れなユダヤ人たちは、いったい何をしているのか。あれを修復して、いけにえを献げようというのか。一日で仕上げようというのか。焼けてしまった石を瓦礫の山の中から拾って、生き返らせようというのか。」'),
('JPN', '尼希米记', 16, 4, 3, '彼のそばには、アンモン人トビヤがいて、彼も「彼らが築き直している城壁など、狐が一匹上っただけで、その石垣を崩してしまうだろう」と言った。'),
('JPN', '尼希米记', 16, 4, 4, '「お聞きください、私たちの神よ。私たちは軽蔑されています。彼らの侮辱を彼ら自身の頭上に返し、彼らが捕囚の地でかすめ奪われるようにしてください。'),
('JPN', '尼希米记', 16, 4, 5, '彼らの咎をおおい隠すことなく、彼らの罪を御前から消し去らないでください。彼らが、建て直している者たちを憤慨させたからです。」'),
('JPN', '尼希米记', 16, 4, 6, 'こうして私たちは城壁を築き直し、城壁はすべて、その半分の高さまでつなぎ合わされた。民に働く気があったからである。'),
('JPN', '尼希米记', 16, 4, 7, 'サンバラテ、トビヤ、アラブ人、アンモン人、アシュドデ人たちは、エルサレムの城壁の修復がはかどり、割れ目もふさがり始めたことを聞いたとき、激しく怒り、'),
('JPN', '尼希米记', 16, 4, 8, '皆でエルサレムに攻め入って混乱を起こそうと、陰謀を企てた。'),
('JPN', '尼希米记', 16, 4, 9, 'そこで私たちは、私たちの神に祈り、彼らに備えて昼も夜も見張りを置いた。'),
('JPN', '尼希米记', 16, 4, 10, 'ユダの人々は言った。「荷を担ぐ者の力は弱り、瓦礫は山をなしている。城壁を築き直すことなど、私たちにできはしない。」'),
('JPN', '尼希米记', 16, 4, 11, '私たちの敵は言った。「彼らが気づかないうちに、見つけないうちに、彼らの真ん中に入り込み、彼らを殺して、その工事をやめさせよう。」'),
('JPN', '尼希米记', 16, 4, 12, 'そのため、彼らの近くに住んでいたユダヤ人たちはやって来て、四方八方から十回も私たちに言った。「私たちのところに戻って来てください。」'),
('JPN', '尼希米记', 16, 4, 13, 'そこで私は、民をその家族ごとに、城壁のうしろの低い場所の空地に、剣や槍や弓を持たせて配置した。'),
('JPN', '尼希米记', 16, 4, 14, '私は彼らの様子を見て立ち上がり、有力者たちや代表者たち、およびその他の人たちに言った。「彼らを恐れてはならない。大いなる恐るべき主を覚え、自分たちの兄弟、息子、娘、妻、また家のために戦いなさい。」'),
('JPN', '尼希米记', 16, 4, 15, '私たちの敵が、自分たちの企みが私たちに悟られたこと、神がそれを打ち壊されたことを聞いたとき、私たちはみな城壁に戻り、それぞれ自分の工事に当たった。'),
('JPN', '尼希米记', 16, 4, 16, 'その日以来、私の配下の若い者の半分は工事を続け、もう半分は、槍、盾、弓、よろいで身を固めていた。隊長たちがユダの全家を守った。'),
('JPN', '尼希米记', 16, 4, 17, '城壁を築く者たち、荷を担いで運ぶ者たちは、片手で仕事をし、片手に投げ槍を握っていた。'),
('JPN', '尼希米记', 16, 4, 18, '築く者はそれぞれ剣を腰にして築き、角笛を吹き鳴らす者は私のそばにいた。'),
('JPN', '尼希米记', 16, 4, 19, '私は有力者たち、代表者たち、およびそのほかの人々に言った。「この工事は大きく、また範囲は広い。私たちは城壁の上で互いに遠く離れ離れになっている。'),
('JPN', '尼希米记', 16, 4, 20, 'どこででも、角笛が鳴るのを聞いたら、私たちのところに集まって来なさい。私たちの神が私たちのために戦ってくださるのだ。」'),
('JPN', '尼希米记', 16, 4, 21, 'こうして私たちはこの工事を進めたが、その半分の者は、夜明けから星が現れるまで槍を手にしていた。'),
('JPN', '尼希米记', 16, 4, 22, 'そのときまた、私は民に言った。「それぞれ自分の配下の若い者と一緒に、エルサレムの内側で夜を明かすようにしなさい。そうすれば、夜には見張りがいて、昼には働くことができる。」'),
('JPN', '尼希米记', 16, 4, 23, '私も、私の親類の者も、私の配下の若い者たちも、私を守る見張りの人々も、私たちの中のだれも服を脱がず、水場でもそれぞれ投げ槍を持っていた。'),
('JPN', '尼希米记', 16, 5, 1, 'さて、民とその妻たちから、同胞のユダヤ人たちに対して強い抗議の声があがった。'),
('JPN', '尼希米记', 16, 5, 2, 'ある者は、「私たちには息子や娘がいて、大人数だ。食べて生きるために穀物を手に入れなければならない」と言い、'),
('JPN', '尼希米记', 16, 5, 3, 'またある者は、「私たちの畑も、ぶどう畑も、家も抵当に入れなければならない。この飢饉に際して穀物を手に入れるために」と言った。'),
('JPN', '尼希米记', 16, 5, 4, 'またある者は言った。「私たちは、畑やぶどう畑に課された王の税金を支払うために、金を借りなければならなかった。'),
('JPN', '尼希米记', 16, 5, 5, '現に、私たちの血肉は私たちの同胞の血肉と同じだし、私たちの子どもも彼らの子どもと同じだ。それなのに、今、私たちは息子や娘を奴隷に売らなければならない。実際、もう娘が奴隷にされている者もいる。ところが、私たちの畑もぶどう畑も他人の所有となっているので、私たちにはどうする力もない。」'),
('JPN', '尼希米记', 16, 5, 6, '私は彼らの抗議と、これらのことばを聞いて、激しく腹を立てた。'),
('JPN', '尼希米记', 16, 5, 7, '私は十分考えたうえで、有力者たちや代表者たちを非難して言った。「あなたがたはみな、自分の同胞たちに、利子をつけて金を貸している。」そして大集会を開いて彼らを責め、'),
('JPN', '尼希米记', 16, 5, 8, '彼らに言った。「私たちは、異邦の民に売られた同胞のユダヤ人を、できる限り買い取った。それなのに、あなたがたはまた自分の同胞を売ろうとしている。彼らはまた私たちに売られなければならなくなる。」すると彼らは黙ってしまい、一言も言えなかった。'),
('JPN', '尼希米记', 16, 5, 9, '私は続けた。「あなたがたのしていることは良くない。あなたがたは、私たちの敵である異邦の民から侮辱を受けることなく、私たちの神を恐れつつ歩むべきではないか。'),
('JPN', '尼希米记', 16, 5, 10, '私も、私の親類の者も、私の配下の若い者たちも、彼らに金や穀物を貸してやったが、私たちはその負債を帳消しにしよう。'),
('JPN', '尼希米记', 16, 5, 11, 'だから、あなたがたも今日、彼らの畑、ぶどう畑、オリーブ畑、家、それに、あなたがたが彼らに貸していた金や穀物、新しいぶどう酒、油などの利息分を彼らに返してやりなさい。」'),
('JPN', '尼希米记', 16, 5, 12, 'すると彼らは、「私たちは返します。彼らから何も要求しません。私たちはあなたの言われるとおりにします」と言った。そこで私は祭司たちを呼んで、この約束を実行する誓いを立てさせた。'),
('JPN', '尼希米记', 16, 5, 13, '私はまた、衣の裾を振って言った。「この約束を果たさない者はだれでも、神がこのように、その人の家から、また、その人の勤労の実から振り落としてくださいますように。このように振り落とされて、無一文になりますように。」すると全会衆は、「アーメン」と言って主をほめたたえた。こうして民はこの約束を実行した。'),
('JPN', '尼希米记', 16, 5, 14, 'また、私がユダの地の総督として任命された日から、すなわち、アルタクセルクセス王の第二十年から第三十二年までの十二年間、私も私の親類も総督としての手当てを受けなかった。'),
('JPN', '尼希米记', 16, 5, 15, '私の前任の総督たちは民の負担を重くし、銀四十シェケルのほかにパンとぶどう酒を民から取り立てた。しかも、彼らに仕える若い者たちは民にいばりちらした。しかし、私は神を恐れて、そのようなことはしなかった。'),
('JPN', '尼希米记', 16, 5, 16, 'また、私はこの城壁の工事に力を注ぎ、私たちは農地を買わなかった。私の配下の若い者たちはみな工事に集まっていた。'),
('JPN', '尼希米记', 16, 5, 17, 'ユダヤ人と代表者たち百五十人、また私たちの周囲の国々から来る者が、私の食卓に着いていた。'),
('JPN', '尼希米记', 16, 5, 18, 'そのため、一日に牛一頭、選り抜きの羊六頭が料理され、私のためには何羽かの鳥が料理された。それに、十日ごとに、あらゆる種類のぶどう酒がたくさん用意された。それでも私は、この民に重い負担がかかっていたので、総督としての手当を要求しなかった。'),
('JPN', '尼希米记', 16, 5, 19, '私の神よ。どうか私がこの民のためにしたすべてのことを覚えて、私をいつくしんでください。'),
('JPN', '尼希米记', 16, 6, 1, 'さて、サンバラテ、トビヤ、アラブ人ゲシェム、その他の私たちの敵に、私が城壁を築き直し、破れ口が残っていないことが伝えられたときのこと、ただし、まだ門には扉を取り付けていなかったときのことである。'),
('JPN', '尼希米记', 16, 6, 2, 'サンバラテとゲシェムは私のところに使いをよこして言った。「さあ、オノの平地のケフィリムで会見しよう。」彼らは私に危害を加えようと企んでいたのである。'),
('JPN', '尼希米记', 16, 6, 3, 'そこで、私は彼らのところに使者たちを遣わして言った。「私は大工事をしているから、下って行けない。私が工事をそのままにして、あなたがたのところへ下って行ったために、工事が止まるようなことがあってよいものだろうか。」'),
('JPN', '尼希米记', 16, 6, 4, '彼らは同じようなことを、四度も私のところに言ってよこした。それで私も同じことを彼らに答えた。'),
('JPN', '尼希米记', 16, 6, 5, 'サンバラテは五度目にも同じようにして、若い者を私のところによこした。その手に一通の開封された手紙を持っていた。'),
('JPN', '尼希米记', 16, 6, 6, 'それには次のように書いてあった。「諸国民の間で言いふらされ、また、ゲシェムも言っていることには、あなたとユダヤ人たちは反逆を企んでいて、そのために、あなたは城壁を築き直している。このうわさによれば、あなたは彼らの王になろうとしている。'),
('JPN', '尼希米记', 16, 6, 7, 'また、あなたは預言者さえ立てて、ここユダには王がいると、自分についてエルサレムで宣言させようとしている。今にこのことは王に聞こえるであろう。さあ、来なさい。一緒に相談しよう。」'),
('JPN', '尼希米记', 16, 6, 8, 'そこで、私は彼のところに人を遣わして言った。「あなたが言っているようなことは、なされていない。それはあなたが心の中で勝手に考え出したことだ」と。'),
('JPN', '尼希米记', 16, 6, 9, 'これらのことはみな、「彼らの工事に対する気力が落ち、工事は中止されるだろう」と考えて、私たちを脅すためであった。ああ、今、どうか私を力づけてください。'),
('JPN', '尼希米记', 16, 6, 10, '私がメヘタブエルの子デラヤの子シェマヤの家に行ったところ、彼は引きこもっていた。そしてこう言った。「神の宮、神殿の中で会い、神殿の戸を閉じておこう。彼らがあなたを殺しにやって来るから。きっと夜分に殺しにやって来る。」'),
('JPN', '尼希米记', 16, 6, 11, 'そこで私は言った。「私のような者が逃げてよいものか。私のような者で、だれが神殿に入って生き続けるだろうか。私は入らない。」'),
('JPN', '尼希米记', 16, 6, 12, '私には分かった。今、彼を遣わしたのは、神ではないと。彼がこの預言を私に伝えたのは、トビヤとサンバラテが彼を買収したからだと。'),
('JPN', '尼希米记', 16, 6, 13, '私が恐れて、言われるがままにして罪を犯し、私の悪評が立って、私がそしられるようにするために、彼は買収されたのだった。'),
('JPN', '尼希米记', 16, 6, 14, 'わが神よ。トビヤやサンバラテのこれらのしわざと、また、私を恐れさせようとした女預言者ノアデヤや、その他の預言者たちのしわざを覚えていてください。'),
('JPN', '尼希米记', 16, 6, 15, 'こうして、城壁は五十二日かかって、エルルの月の二十五日に完成した。'),
('JPN', '尼希米记', 16, 6, 16, '私たちの敵がみなこれを聞いたとき、周囲の国々の民はみな恐れ、大いに面目を失った。この工事が私たちの神によってなされたことを知ったからである。'),
('JPN', '尼希米记', 16, 6, 17, 'またそのころ、ユダの有力者たちはトビヤのところにひんぱんに手紙を送っていて、トビヤも彼らに返事をしていた。'),
('JPN', '尼希米记', 16, 6, 18, 'それは、トビヤがアラフの子シェカンヤの婿であり、また、トビヤの子ヨハナンもベレクヤの子メシュラムの娘を妻に迎えていたので、彼に誓いを立てていた者がユダの中に大勢いたからである。'),
('JPN', '尼希米记', 16, 6, 19, 'さらに、彼らは私の前でトビヤの善行を語り、彼に私の言うことを筒抜けにしていた。トビヤは私を脅すために、たびたび手紙を送って来た。'),
('JPN', '尼希米记', 16, 7, 1, '城壁が築き直され、私が扉を取り付けたとき、門衛、歌い手、レビ人が任命された。'),
('JPN', '尼希米记', 16, 7, 2, '私は兄弟ハナニとこの城の長ハナンヤに、エルサレムを治めるように命じた。これは、ハナンヤが誠実な人であり、多くの人にまさって神を恐れていたからであった。'),
('JPN', '尼希米记', 16, 7, 3, '私は彼らに言った。「太陽が高く昇って暑くなるまでは、エルサレムの門を開けてはならない。そして彼らが警備に立っている間に、門をしっかりと閉じておきなさい。エルサレムの住民を、それぞれ物見のやぐらか自分の家の前に、見張りとして立てなさい。」'),
('JPN', '尼希米记', 16, 7, 4, 'この町は広々としていて大きかったが、その中の住民は少なく、家もまだ十分に建てられていなかった。'),
('JPN', '尼希米记', 16, 7, 5, '私の神は私の心に示して、私に有力者たちや、代表者たちや、民衆を集めて、彼らの系図を記載させた。私は最初に上って来た人々の系図を発見し、その中に次のように書かれているのを見つけた。'),
('JPN', '尼希米记', 16, 7, 6, 'バビロンの王ネブカドネツァルが引いて行った捕囚の民で、その捕囚の身から解かれてエルサレムとユダに上り、それぞれ自分の町に帰ったこの州の人々は次のとおりである。'),
('JPN', '尼希米记', 16, 7, 7, '彼らは、ゼルバベル、ヨシュア、ネヘミヤ、アザルヤ、ラアムヤ、ナハマニ、モルデカイ、ビルシャン、ミスペレテ、ビグワイ、ネフム、バアナと一緒に帰って来た。イスラエルの民の人数は次のとおりである。'),
('JPN', '尼希米记', 16, 7, 8, 'パルオシュ族、二千百七十二人。'),
('JPN', '尼希米记', 16, 7, 9, 'シェファテヤ族、三百七十二人。'),
('JPN', '尼希米记', 16, 7, 10, 'アラフ族、六百五十二人。'),
('JPN', '尼希米记', 16, 7, 11, 'ヨシュアとヨアブの二族からなるパハテ・モアブ族、二千八百十八人。'),
('JPN', '尼希米记', 16, 7, 12, 'エラム族、一千二百五十四人。'),
('JPN', '尼希米记', 16, 7, 13, 'ザト族、八百四十五人。'),
('JPN', '尼希米记', 16, 7, 14, 'ザカイ族、七百六十人。'),
('JPN', '尼希米记', 16, 7, 15, 'ビヌイ族、六百四十八人。'),
('JPN', '尼希米记', 16, 7, 16, 'ベバイ族、六百二十八人。'),
('JPN', '尼希米记', 16, 7, 17, 'アズガデ族、二千三百二十二人。'),
('JPN', '尼希米记', 16, 7, 18, 'アドニカム族、六百六十七人。'),
('JPN', '尼希米记', 16, 7, 19, 'ビグワイ族、二千六十七人。'),
('JPN', '尼希米记', 16, 7, 20, 'アディン族、六百五十五人。'),
('JPN', '尼希米记', 16, 7, 21, 'ヒゼキヤ族、すなわちアテル族、九十八人。'),
('JPN', '尼希米记', 16, 7, 22, 'ハシュム族、三百二十八人。'),
('JPN', '尼希米记', 16, 7, 23, 'ベツァイ族、三百二十四人。'),
('JPN', '尼希米记', 16, 7, 24, 'ハリフ族、百十二人。'),
('JPN', '尼希米记', 16, 7, 25, 'ギブオン族、九十五人。'),
('JPN', '尼希米记', 16, 7, 26, 'ベツレヘムとネトファの人々、百八十八人。'),
('JPN', '尼希米记', 16, 7, 27, 'アナトテの人々、百二十八人。'),
('JPN', '尼希米记', 16, 7, 28, 'ベテ・アズマウェテの人々、四十二人。'),
('JPN', '尼希米记', 16, 7, 29, 'キルヤテ・エアリムとケフィラとベエロテの人々、七百四十三人。'),
('JPN', '尼希米记', 16, 7, 30, 'ラマとゲバの人々、六百二十一人。'),
('JPN', '尼希米记', 16, 7, 31, 'ミクマスの人々、百二十二人。'),
('JPN', '尼希米记', 16, 7, 32, 'ベテルとアイの人々、百二十三人。'),
('JPN', '尼希米记', 16, 7, 33, '別のネボの人々、五十二人。'),
('JPN', '尼希米记', 16, 7, 34, '別のエラム族、一千二百五十四人。'),
('JPN', '尼希米记', 16, 7, 35, 'ハリム族、三百二十人。'),
('JPN', '尼希米记', 16, 7, 36, 'エリコ人、三百四十五人。'),
('JPN', '尼希米记', 16, 7, 37, 'ロデ人とハディデ人とオノ人、七百二十一人。'),
('JPN', '尼希米记', 16, 7, 38, 'セナア人、三千九百三十人。'),
('JPN', '尼希米记', 16, 7, 39, '祭司は、ヨシュアの家系のエダヤ族、九百七十三人。'),
('JPN', '尼希米记', 16, 7, 40, 'イメル族、一千五十二人。'),
('JPN', '尼希米记', 16, 7, 41, 'パシュフル族、一千二百四十七人。'),
('JPN', '尼希米记', 16, 7, 42, 'ハリム族、一千十七人。'),
('JPN', '尼希米记', 16, 7, 43, 'レビ人は、ホダウヤ族のヨシュアとカデミエルの二族、七十四人。'),
('JPN', '尼希米记', 16, 7, 44, '歌い手は、アサフ族、百四十八人。'),
('JPN', '尼希米记', 16, 7, 45, '門衛は、シャルム族、アテル族、タルモン族、アクブ族、ハティタ族、ショバイ族、百三十八人。'),
('JPN', '尼希米记', 16, 7, 46, '宮のしもべは、ツィハ族、ハスファ族、タバオテ族、'),
('JPN', '尼希米记', 16, 7, 47, 'ケロス族、シア族、パドン族、'),
('JPN', '尼希米记', 16, 7, 48, 'レバナ族、ハガバ族、シャルマイ族、'),
('JPN', '尼希米记', 16, 7, 49, 'ハナン族、ギデル族、ガハル族、'),
('JPN', '尼希米记', 16, 7, 50, 'レアヤ族、レツィン族、ネコダ族、'),
('JPN', '尼希米记', 16, 7, 51, 'ガザム族、ウザ族、パセアハ族、'),
('JPN', '尼希米记', 16, 7, 52, 'ベサイ族、メウニム族、ネフィシェシム族、'),
('JPN', '尼希米记', 16, 7, 53, 'バクブク族、ハクファ族、ハルフル族、'),
('JPN', '尼希米记', 16, 7, 54, 'バツリテ族、メヒダ族、ハルシャ族、'),
('JPN', '尼希米记', 16, 7, 55, 'バルコス族、シセラ族、テマフ族、'),
('JPN', '尼希米记', 16, 7, 56, 'ネツィアハ族、ハティファ族。'),
('JPN', '尼希米记', 16, 7, 57, 'ソロモンのしもべたちの子孫は、ソタイ族、ソフェレテ族、ペリダ族、'),
('JPN', '尼希米记', 16, 7, 58, 'ヤアラ族、ダルコン族、ギデル族、'),
('JPN', '尼希米记', 16, 7, 59, 'シェファテヤ族、ハティル族、ポケレテ・ハツェバイム族、アモン族。'),
('JPN', '尼希米记', 16, 7, 60, '宮のしもべたちと、ソロモンのしもべたちの子孫は、合計三百九十二人。'),
('JPN', '尼希米记', 16, 7, 61, '次の人々はテル・メラフ、テル・ハルシャ、ケルブ、アドン、イメルから引き揚げて来たが、自分たちの先祖の家系と血統がイスラエル人であったかどうかを証明できなかった。'),
('JPN', '尼希米记', 16, 7, 62, 'デラヤ族、トビヤ族、ネコダ族、六百四十二人。'),
('JPN', '尼希米记', 16, 7, 63, '祭司の中では、ホバヤ族、ハ・コツ族、バルジライ族。このバルジライは、ギルアデ人バルジライの娘の一人を妻にしたので、その名で呼ばれていた。'),
('JPN', '尼希米记', 16, 7, 64, 'これらの人々は自分たちの系図書きを捜してみたが、見つからなかったので、彼らは祭司職を果たす資格がない者とされた。'),
('JPN', '尼希米记', 16, 7, 65, 'そのため総督は彼らに、ウリムとトンミムを使える祭司が起こるまでは、最も聖なるものを食べてはならないと命じた。'),
('JPN', '尼希米记', 16, 7, 66, '全会衆の合計は四万二千三百六十人であった。'),
('JPN', '尼希米记', 16, 7, 67, 'このほかに、彼らの男女の奴隷が七千三百三十七人いた。また、彼らには男女の歌い手が二百四十五人いた。'),
('JPN', '尼希米记', 16, 7, 68, 'らくだは四百三十五頭。ろばは六千七百二十頭であった。'),
('JPN', '尼希米记', 16, 7, 69, '一族のかしらの何人かは、工事のためにささげ物をした。総督は資金として金一千ダリク、鉢五十、祭司の長服五百三十着を献げ、'),
('JPN', '尼希米记', 16, 7, 70, 'また、一族のかしらのある者は、工事資金として金二万ダリク、銀二千二百ミナを献げた。'),
('JPN', '尼希米记', 16, 7, 71, 'そのほかの民の献げたものは、金二万ダリク、銀二千ミナ、祭司の長服六十七着であった。'),
('JPN', '尼希米记', 16, 7, 72, 'こうして、祭司、レビ人、門衛、歌い手、民のある者たち、宮のしもべたちが、すなわち、全イスラエルが自分たちの元の町々に住んだ。イスラエルの子らは自分たちの町々にいたが、第七の月が来たとき、'),
('JPN', '尼希米记', 16, 8, 1, '民全体が、一斉に水の門の前の広場に集まって来た。そして彼らは、主がイスラエルに命じたモーセの律法の書を持って来るように、学者エズラに言った。'),
('JPN', '尼希米记', 16, 8, 2, 'そこで、第七の月の一日に祭司エズラは、男、女、および、聞いて理解できる人たちすべてからなる会衆の前に律法を持って来て、'),
('JPN', '尼希米记', 16, 8, 3, '水の門の前の広場で夜明けから真昼まで、男、女、および理解できる人たちの前で、これを朗読した。民はみな律法の書に耳を傾けた。'),
('JPN', '尼希米记', 16, 8, 4, '学者エズラは、このために作られた木の壇の上に立った。彼のそばには、右手にマティテヤ、シェマ、アナヤ、ウリヤ、ヒルキヤ、マアセヤが立ち、左手にペダヤ、ミシャエル、マルキヤ、ハシュム、ハシュバダナ、ゼカリヤ、メシュラムが立った。'),
('JPN', '尼希米记', 16, 8, 5, 'エズラは民全体の目の前で、その書を開いた。彼は民全体よりも高いところにいたのである。彼がそれを開くと、民はみな立ち上がった。'),
('JPN', '尼希米记', 16, 8, 6, 'エズラが大いなる神、主をほめたたえると、民はみな両手を上げながら「アーメン、アーメン」と答え、ひざまずき、顔を地に伏せて主を礼拝した。'),
('JPN', '尼希米记', 16, 8, 7, 'ヨシュア、バニ、シェレベヤ、ヤミン、アクブ、シャベタイ、ホディヤ、マアセヤ、ケリタ、アザルヤ、エホザバデ、ハナン、ペラヤなどレビ人たちは、民に律法を解き明かした。その間、民はその場に立っていた。'),
('JPN', '尼希米记', 16, 8, 8, '彼らが神のみおしえの書を読み、その意味を明快に示したので、民は読まれたことを理解した。'),
('JPN', '尼希米记', 16, 8, 9, '総督であるネヘミヤと、祭司であり学者であるエズラと、民に解き明かすレビ人たちは、民全体に向かって言った。「今日は、あなたがたの神、主にとって聖なる日である。悲しんではならない。泣いてはならない。」民が律法のことばを聞いたときに、みな泣いていたからである。'),
('JPN', '尼希米记', 16, 8, 10, 'さらに、彼は彼らに言った。「行って、ごちそうを食べ、甘いぶどう酒を飲みなさい。何も用意できなかった人には食べ物を贈りなさい。今日は、私たちの主にとって聖なる日である。悲しんではならない。主を喜ぶことは、あなたがたの力だからだ。」'),
('JPN', '尼希米记', 16, 8, 11, 'レビ人たちも、民全体を静めながら言った。「静まりなさい。今日は聖なる日だから。悲しんではならない。」'),
('JPN', '尼希米记', 16, 8, 12, 'こうして、民はみな帰って行き、食べたり飲んだり、ごちそうを贈ったりして、大いに喜んだ。教えられたことを理解したからである。'),
('JPN', '尼希米记', 16, 8, 13, '二日目に、民全体の一族のかしらたちと、祭司たち、レビ人たちは、律法のことばをよく調べるために、学者エズラのところに集まって来た。'),
('JPN', '尼希米记', 16, 8, 14, 'そして彼らは、主がモーセを通して命じた律法に次のように書かれているのを見出した。すなわち、「イスラエルの子らは第七の月の祭りの間、仮庵の中に住まなければならない。'),
('JPN', '尼希米记', 16, 8, 15, 'また、『山へ出て行き、オリーブの葉、野生のオリーブの木の葉、ミルトスの葉、なつめ椰子の葉、また茂った枝木などの枝を取って来て、書かれているとおりに仮庵を作るように』と、自分たちのすべての町とエルサレムに通達を出して、知らせなければならない」とあった。'),
('JPN', '尼希米记', 16, 8, 16, 'そこで民は出て行き、枝を取って来て、それぞれ自分の家の屋根の上や庭の中、また神の宮の庭、水の門の広場、エフライムの門の広場に、自分たちのために仮庵を作った。'),
('JPN', '尼希米记', 16, 8, 17, '捕囚から帰って来た全会衆は仮庵を作り、その仮庵に住んだ。ヌンの子ヨシュアの時代から今日まで、イスラエルの子らはこのようにしていなかったので、それは非常に大きな喜びであった。'),
('JPN', '尼希米记', 16, 8, 18, '神のみおしえの書は、最初の日から最後の日まで毎日朗読された。祭りは七日間祝われ、八日目には定めにしたがって、きよめの集会が行われた。'),
('JPN', '尼希米记', 16, 9, 1, 'その月の二十四日に、イスラエルの子らは集まって断食をし、粗布をまとって土をかぶった。'),
('JPN', '尼希米记', 16, 9, 2, 'イスラエルの子孫はすべての異国の人々と関係を絶ち、立ち上がって、自分たちの罪と先祖の咎を告白した。'),
('JPN', '尼希米记', 16, 9, 3, '彼らはそれぞれ所定のところに立って、昼の四分の一は、彼らの神、主のみおしえの書を朗読し、次の四分の一は、彼らの神、主に告白をして礼拝した。'),
('JPN', '尼希米记', 16, 9, 4, 'ヨシュア、バニ、カデミエル、シェバンヤ、ブンニ、シェレベヤ、バニ、ケナニはレビ人の台の上に立ち、彼らの神、主に向かって大声で叫んだ。'),
('JPN', '尼希米记', 16, 9, 5, 'レビ人のヨシュア、カデミエル、バニ、ハシャブネヤ、シェレベヤ、ホディヤ、シェバンヤ、ペタフヤは言った。「立ち上がって、あなたがたの神、主をほめたたえよ。とこしえからとこしえまで。あなたの栄光の御名はほむべきかな。すべての祝福と賛美の上に高く上げられて。'),
('JPN', '尼希米记', 16, 9, 6, 'ただ、あなただけが主です。あなたは天と、天の天と、その万象を、地とその上のすべてのものを、海とその中にあるすべてのものを造られました。あなたはそのすべてを生かしておられます。天の万象はあなたを伏し拝んでいます。'),
('JPN', '尼希米记', 16, 9, 7, 'あなたこそ神である主です。あなたはアブラムを選んでカルデア人のウルから連れ出し、その名をアブラハムとされました。'),
('JPN', '尼希米记', 16, 9, 8, '彼の心が御前に忠実であるのを見て、あなたは彼と契約を結び、カナン人、ヒッタイト人、アモリ人、ペリジ人、エブス人、ギルガシ人の地を彼の子孫に与えるとされました。そしてその約束を果たされました。あなたは正しい方だからです。'),
('JPN', '尼希米记', 16, 9, 9, 'あなたはエジプトで私たちの先祖の苦難を見て、葦の海のほとりで、その叫びを聞かれました。'),
('JPN', '尼希米记', 16, 9, 10, 'ファラオとそのすべての家臣、その国のすべての民に対して、数々のしるしと不思議を行われました。彼らが私たちの先祖に対して傲慢にふるまったのを、あなたがみこころに留められたからです。こうして、今日あるとおり、あなたは名をあげられました。'),
('JPN', '尼希米记', 16, 9, 11, 'あなたは私たちの先祖の前で海を裂き、彼らは海の真ん中の乾いた地面を渡りました。追っ手は、奔流に吞み込まれる石のように、あなたが海の深みに投げ込まれました。'),
('JPN', '尼希米记', 16, 9, 12, '昼は雲の柱の中にあって彼らを導き、夜は火の柱の中にあってその行くべき道を照らされました。'),
('JPN', '尼希米记', 16, 9, 13, 'あなたはシナイ山の上に下り、天から彼らと語り、正しい定めと、まことのみおしえ、良き掟と命令を彼らにお与えになりました。'),
('JPN', '尼希米记', 16, 9, 14, 'あなたの聖なる安息を彼らに教え、あなたのしもべモーセを通して、命令と掟とみおしえを彼らに命じられました。'),
('JPN', '尼希米记', 16, 9, 15, '彼らが飢えたときには、天からパンを与え、渇いたときには、岩から水を出し、彼らに与えると誓われたその地に入ってそこを所有するよう、彼らに命じられました。'),
('JPN', '尼希米记', 16, 9, 16, 'しかし彼ら、私たちの先祖は傲慢にふるまい、うなじを固くし、あなたの命令に聞き従いませんでした。'),
('JPN', '尼希米记', 16, 9, 17, '彼らは聞き従うことを拒み、彼らの間で行われた奇しいみわざを思い出さず、かえってうなじを固くし、かしらを立てて、逆らって奴隷の身に戻ろうとしました。それにもかかわらず、あなたは赦しの神であり、情け深く、あわれみ深く、怒るのに遅く、恵み豊かであられ、彼らをお捨てになりませんでした。'),
('JPN', '尼希米记', 16, 9, 18, '彼らが自分たちのために鋳物の子牛を造り、『これが、あなたをエジプトから導き上ったあなたの神だ』と言って、ひどい侮辱を加えたときでさえ、'),
('JPN', '尼希米记', 16, 9, 19, 'あなたは大きなあわれみをかけ、彼らを荒野に見捨てられませんでした。昼は雲の柱が彼らから離れず、道中を導き、夜は火の柱が、行くべき道を照らしました。'),
('JPN', '尼希米记', 16, 9, 20, 'あなたは、彼らを賢くしようと、ご自分の良き霊を与え、彼らの口からあなたのマナを絶やさず、彼らが渇いたときには水を与えられました。'),
('JPN', '尼希米记', 16, 9, 21, '四十年の間、あなたは彼らを養われました。彼らは荒野で何も不足することなく、上着はすり切れず、足も腫れませんでした。'),
('JPN', '尼希米记', 16, 9, 22, 'あなたは諸王国と諸民族を彼らに渡し、それらを領地として割り当てられました。彼らはシホンの地、ヘシュボンの王の地と、バシャンの王オグの地を所有しました。'),
('JPN', '尼希米记', 16, 9, 23, 'あなたは彼らの子孫を空の星のように増やし、彼らの先祖たちに、『入って行って所有せよ』と言った地に、彼らを導き入れられました。'),
('JPN', '尼希米记', 16, 9, 24, 'その子孫は入って行って、その地を所有しました。あなたは、この地の住民、カナン人を彼らの前に屈服させて、その手に渡し、王たちとその地の人々を、彼らの思いのままに扱わせました。'),
('JPN', '尼希米记', 16, 9, 25, 'こうして、彼らは城壁のある町々と肥えた土地を攻め取り、あらゆる良い物に満ちた家、掘り井戸とぶどう畑、そしてオリーブと果樹を、豊かに手に入れました。彼らは食べて満腹し、肥え太って、あなたの大いなる恵みを楽しみました。'),
('JPN', '尼希米记', 16, 9, 26, 'しかし、彼らはあなたに逆らい、反逆して、あなたの律法をうしろに投げ捨て、あなたに立ち返らせようとして彼らを戒めたあなたの預言者たちを殺し、数々のひどい侮辱を加えました。'),
('JPN', '尼希米记', 16, 9, 27, 'そこであなたは彼らを敵の手に渡され、敵が彼らを苦しめました。彼らがその苦難の時にあなたに叫び求めると、あなたは天からこれを聞き入れ、あなたの大いなるあわれみによって救う者たちを彼らに与え、敵の手から救われるようにしてくださいました。'),
('JPN', '尼希米记', 16, 9, 28, 'しかし、一息つくと、彼らはまたあなたの前に悪事を行いました。あなたは彼らを敵の手に捨て置き、敵が彼らを支配しました。彼らが再びあなたに叫び求めると、あなたは天からこれを聞き入れ、あわれみによって、たびたび彼らを救い出されました。'),
('JPN', '尼希米记', 16, 9, 29, 'あなたは彼らを戒めて、あなたの律法に立ち返らせようとされました。しかし、彼らは傲慢にふるまい、あなたの命令に聞き従わず、その命令を行う人は、それによって生きるというあなたの定めに背いて罪を犯し、肩を怒らして、うなじを固くし、聞き入れようとはしませんでした。'),
('JPN', '尼希米记', 16, 9, 30, 'それでも、あなたは何年も彼らを忍び、あなたの霊により、あなたの預言者たちを通して彼らを戒められましたが、彼らは耳を傾けませんでした。そのため、あなたは彼らを地のもろもろの民の手に渡されました。'),
('JPN', '尼希米记', 16, 9, 31, 'しかし、あなたはその大いなるあわれみにより、彼らを滅ぼし尽くすことはせず、お見捨てにもなりませんでした。あなたは、情け深くあわれみ深い神です。'),
('JPN', '尼希米记', 16, 9, 32, '私たちの神、大いなる神よ。力強く恐るべき方、契約と恵みを守られる方よ。今、アッシリアの王たちの時代から今日まで、私たちと私たちの王たち、高官たち、祭司、預言者、私たちの先祖、また、あなたの民全体に降りかかった困難をみな、どうか小さなことと見なさないでください。'),
('JPN', '尼希米记', 16, 9, 33, '私たちに降りかかったすべてのことにおいて、あなたは正しくあられます。あなたは真実を行われましたが、私たちは悪を行ったのです。'),
('JPN', '尼希米记', 16, 9, 34, '私たちの王、高官、祭司、先祖たちはあなたの律法を守らず、あなたがお与えになった命令と警告にも、耳を傾けませんでした。'),
('JPN', '尼希米记', 16, 9, 35, '彼らは自分たちの王国の中で、あなたが下さったその大きな恵みの中で、また、あなたが彼らの前に置かれた、広くて肥えた土地にいても、あなたに仕えず、また自分たちの悪い行いから立ち返ることもありませんでした。'),
('JPN', '尼希米记', 16, 9, 36, 'ご覧ください。私たちは今、奴隷です。私たちが実りと良い物を食べられるようにと、あなたが先祖に与えてくださった、この地で。ご覧ください。私たちは奴隷です。'),
('JPN', '尼希米记', 16, 9, 37, '私たちの罪のゆえに、この地の豊かな産物は、あなたが私たちの上に立てられた王たちのものとなっています。彼らは私たちのからだを支配し、家畜も彼らの思いのままです。私たちは大きな苦しみの中にいます。」'),
('JPN', '尼希米记', 16, 9, 38, 'これらすべてのことのゆえに、私たちは文書をもって盟約を結んだ。そして、私たちの高官たち、レビ人たち、祭司たちはそれに印を押した。'),
('JPN', '尼希米记', 16, 10, 1, '印を押した者は次のとおりである。ハカルヤの子の総督ネヘミヤ、およびゼデキヤ、'),
('JPN', '尼希米记', 16, 10, 2, 'セラヤ、アザルヤ、エレミヤ、'),
('JPN', '尼希米记', 16, 10, 3, 'パシュフル、アマルヤ、マルキヤ、'),
('JPN', '尼希米记', 16, 10, 4, 'ハトシュ、シェバンヤ、マルク、'),
('JPN', '尼希米记', 16, 10, 5, 'ハリム、メレモテ、オバデヤ、'),
('JPN', '尼希米记', 16, 10, 6, 'ダニエル、ギネトン、バルク、'),
('JPN', '尼希米记', 16, 10, 7, 'メシュラム、アビヤ、ミヤミン、'),
('JPN', '尼希米记', 16, 10, 8, 'マアズヤ、ビルガイ、シェマヤ。以上は祭司たちであった。'),
('JPN', '尼希米记', 16, 10, 9, 'レビ人では、アザンヤの子ヨシュア、ヘナダデの子らのうちのビヌイ、カデミエル、'),
('JPN', '尼希米记', 16, 10, 10, 'および彼らの親類で、シェバンヤ、ホディヤ、ケリタ、ペラヤ、ハナン、'),
('JPN', '尼希米记', 16, 10, 11, 'ミカ、レホブ、ハシャブヤ、'),
('JPN', '尼希米记', 16, 10, 12, 'ザクル、シェレベヤ、シェバンヤ、'),
('JPN', '尼希米记', 16, 10, 13, 'ホディヤ、バニ、ベニヌ。'),
('JPN', '尼希米记', 16, 10, 14, '民のかしらでは、パルオシュ、パハテ・モアブ、エラム、ザト、バニ、'),
('JPN', '尼希米记', 16, 10, 15, 'ブンニ、アズガデ、ベバイ、'),
('JPN', '尼希米记', 16, 10, 16, 'アドニヤ、ビグワイ、アディン、'),
('JPN', '尼希米记', 16, 10, 17, 'アテル、ヒゼキヤ、アズル、'),
('JPN', '尼希米记', 16, 10, 18, 'ホディヤ、ハシュム、ベツァイ、'),
('JPN', '尼希米记', 16, 10, 19, 'ハリフ、アナトテ、ネバイ、'),
('JPN', '尼希米记', 16, 10, 20, 'マグピアシュ、メシュラム、ヘジル、'),
('JPN', '尼希米记', 16, 10, 21, 'メシェザブエル、ツァドク、ヤドア、'),
('JPN', '尼希米记', 16, 10, 22, 'ペラテヤ、ハナン、アナヤ、'),
('JPN', '尼希米记', 16, 10, 23, 'ホセア、ハナンヤ、ハシュブ、'),
('JPN', '尼希米记', 16, 10, 24, 'ハ・ロヘシュ、ピルハ、ショベク、'),
('JPN', '尼希米记', 16, 10, 25, 'レフム、ハシャブナ、マアセヤ、'),
('JPN', '尼希米记', 16, 10, 26, 'アヒヤ、ハナン、アナン、'),
('JPN', '尼希米记', 16, 10, 27, 'マルク、ハリム、バアナ。'),
('JPN', '尼希米记', 16, 10, 28, 'このほかの民、祭司、レビ人、門衛、歌い手、宮のしもべたち、また、諸国の民と関係を絶って神の律法についた者全員、その妻、息子、娘たち、すべて理解できるまでになった者は、'),
('JPN', '尼希米记', 16, 10, 29, '彼らの親類のすぐれた人々と歩調を合わせつつ、神のしもべモーセを通して与えられた神の律法に歩み、私たちの主、主のすべての命令、その定めと掟を守り行うという、次のような、のろいの誓いに加わった。'),
('JPN', '尼希米记', 16, 10, 30, '「私たちの娘をこの地の民に与えず、また、彼らの娘を私たちの息子の妻としない。'),
('JPN', '尼希米记', 16, 10, 31, '諸国の民が安息日に商品、あるいはどんな穀物を売りに持って来ても、私たちは安息日や聖なる日には彼らから買わない。また、私たちは七年目には土地を休ませ、あらゆる負債を免除する。'),
('JPN', '尼希米记', 16, 10, 32, '私たちは、自分たちの神の宮での礼拝のために、毎年シェケルの三分の一を献げる義務を自らに課す。'),
('JPN', '尼希米记', 16, 10, 33, 'これは、並べ供えるパンと常供の穀物のささげ物のため、常供の全焼のささげ物のため、安息日、新月の祭り、例祭、聖なるささげ物のため、そしてイスラエルの宥めを行う罪のきよめのささげ物のため、および私たちの神の宮のすべての用途のためである。'),
('JPN', '尼希米记', 16, 10, 34, 'また私たち、祭司とレビ人と民は、薪のささげ物について、毎年定められた時に、父祖の家ごとに神の家に携えて来ることを、くじによって決める。律法に記されているとおり、私たちの神、主の祭壇の上で燃やすためである。'),
('JPN', '尼希米记', 16, 10, 35, 'また、私たちの土地の初なりと、あらゆる木の初なりの果実をすべて、毎年、主の宮に携えて来ることに決める。'),
('JPN', '尼希米记', 16, 10, 36, 'また、律法に記されているとおり、私たちの子どもと家畜の初子、私たちの牛や羊の初子を、私たちの神の宮に、私たちの神の宮で仕えている祭司たちのところに携えて来ることに決める。'),
('JPN', '尼希米记', 16, 10, 37, 'また、私たちの初物の麦粉と奉納物、およびあらゆる木の果実、新しいぶどう酒と油を祭司たちのところに、私たちの神の宮の部屋に携えて来る。また、私たちの土地の十分の一はレビ人たちのものとする。レビ人は、私たちの耕作するすべての町から十分の一を受け取る者たちである。'),
('JPN', '尼希米记', 16, 10, 38, 'レビ人が十分の一を集めるとき、アロンの子孫である祭司が、そのレビ人とともにいなければならない。レビ人は、その十分の一の十分の一を私たちの神の宮へ携え上り、宝物倉の部屋に納めなければならない。'),
('JPN', '尼希米记', 16, 10, 39, 'この部屋に、イスラエルの子らとレビ人たちは、穀物、新しいぶどう酒、油の奉納物を携えて来るようになっているからである。そこには聖所の用具があり、また、当番の祭司や門衛や歌い手たちもいる。このようにして私たちは、自分たちの神の宮をなおざりにはしない。」'),
('JPN', '尼希米记', 16, 11, 1, '民の指導者たちはエルサレムに住んでいたが、それ以外の民はくじを引いて、十人のうちから一人ずつ、聖なる都エルサレムに来て住むようにし、あとの九人をほかの町々に住まわせた。'),
('JPN', '尼希米记', 16, 11, 2, '民は、自分から進んでエルサレムに住もうとする人々をみな祝福した。'),
('JPN', '尼希米记', 16, 11, 3, 'エルサレムに住んだこの州のかしらたちは次のとおりである。ユダの町々には、イスラエルの人々、祭司、レビ人、宮のしもべたち、ソロモンのしもべたちの子孫が、それぞれ自分たちの町の自分の所有地に住んだ。'),
('JPN', '尼希米记', 16, 11, 4, 'エルサレムには、ユダ族とベニヤミン族のうちのある者が住んだ。ユダ族では、まずウジヤの子アタヤ。ウジヤはゼカリヤの子、ゼカリヤはアマルヤの子、アマルヤはシェファテヤの子、シェファテヤはマハラルエルの子、マハラルエルはペレツの子孫の一人である。'),
('JPN', '尼希米记', 16, 11, 5, '次にバルクの子マアセヤ。バルクはコル・ホゼの子、コル・ホゼはハザヤの子、ハザヤはアダヤの子、アダヤはエホヤリブの子、エホヤリブはゼカリヤの子、ゼカリヤはシロ人の子孫である。'),
('JPN', '尼希米记', 16, 11, 6, 'エルサレムに住んだペレツの子孫は合計四百六十八人の勇士であった。'),
('JPN', '尼希米记', 16, 11, 7, 'ベニヤミン族では次のとおりである。まずメシュラムの子サル。メシュラムはヨエデの子、ヨエデはペダヤの子、ペダヤはコラヤの子、コラヤはマアセヤの子、マアセヤはイティエルの子、イティエルはエシャヤの子である。'),
('JPN', '尼希米记', 16, 11, 8, '彼の次にガバイとサライで、九百二十八人。'),
('JPN', '尼希米记', 16, 11, 9, 'ジクリの子ヨエルが彼らの監督者であり、セヌアの子ユダがこの町の副監督者であった。'),
('JPN', '尼希米记', 16, 11, 10, '祭司のうちでは、エホヤリブの子エダヤと、ヤキン、'),
('JPN', '尼希米记', 16, 11, 11, 'ヒルキヤの子セラヤであった。ヒルキヤはメシュラムの子、メシュラムはツァドクの子、ツァドクはメラヨテの子、メラヨテはアヒトブの子である。セラヤは神の宮のつかさであった。'),
('JPN', '尼希米记', 16, 11, 12, '彼らの同族で宮の務めをする者は八百二十二人。また、エロハムの子アダヤ。エロハムはペラルヤの子、ペラルヤはアムツィの子、アムツィはゼカリヤの子、ゼカリヤはパシュフルの子、パシュフルはマルキヤの子である。'),
('JPN', '尼希米记', 16, 11, 13, 'アダヤの同族で一族のかしらたちは二百四十二人。また、アザルエルの子アマシュサイ。アザルエルはアフザイの子、アフザイはメシレモテの子、メシレモテはイメルの子である。'),
('JPN', '尼希米记', 16, 11, 14, '彼らの同族の勇士たちは百二十八人。彼らの監督者はハゲドリムの子ザブディエルであった。'),
('JPN', '尼希米记', 16, 11, 15, 'レビ人のうちでは、ハシュブの子シェマヤ。ハシュブはアズリカムの子、アズリカムはハシャブヤの子、ハシャブヤはブンニの子である。'),
('JPN', '尼希米记', 16, 11, 16, 'また、レビ人のかしらのうちシャベタイとエホザバデは、神の宮の外まわりの仕事をつかさどっていた。'),
('JPN', '尼希米记', 16, 11, 17, 'また、ミカの子マタンヤ。ミカはアサフの子のザブディの子である。マタンヤは祈りの時に感謝の歌を歌い始める指導者、バクブクヤはその同族の副指導者であった。また、シャムアの子アブダ。シャムアはエドトンの子のガラルの子である。'),
('JPN', '尼希米记', 16, 11, 18, '聖なる都にいるレビ人は合計二百八十四人であった。'),
('JPN', '尼希米记', 16, 11, 19, '門衛では、アクブとタルモン、および門の見張りをする彼らの同族で、百七十二人であった。'),
('JPN', '尼希米记', 16, 11, 20, 'そのほかのイスラエルの人々、祭司、レビ人たちは、ユダのすべての町で、それぞれ自分の相続地にいた。'),
('JPN', '尼希米记', 16, 11, 21, '宮のしもべたちはオフェルに住み、ツィハとギシュパは宮のしもべたちをつかさどっていた。'),
('JPN', '尼希米记', 16, 11, 22, 'エルサレムにいるレビ人の監督者は、バニの子ウジであった。バニはハシャブヤの子、ハシャブヤはマタンヤの子、マタンヤはミカの子である。ウジはアサフの子孫の歌い手の一人で、神の宮の礼拝を指導していた。'),
('JPN', '尼希米记', 16, 11, 23, '歌い手たちには王の命令が下っていて、日課が定められていた。'),
('JPN', '尼希米记', 16, 11, 24, 'また、ユダの子ゼラフの子孫の一人で、メシェザブエルの子ペタフヤは、民に関するすべての事柄について王を助ける役を務めた。'),
('JPN', '尼希米记', 16, 11, 25, '農地がある村々で、ユダの子孫の一部が住んだのは、キルヤテ・アルバとそれに属する村々、ディボンとそれに属する村々、エカブツェエルとその村々、'),
('JPN', '尼希米记', 16, 11, 26, 'ヨシュア、モラダ、ベテ・ペレテ、'),
('JPN', '尼希米记', 16, 11, 27, 'ハツァル・シュアル、ベエル・シェバとそれに属する村々、'),
('JPN', '尼希米记', 16, 11, 28, 'ツィクラグ、メコナとそれに属する村々、'),
('JPN', '尼希米记', 16, 11, 29, 'エン・リンモン、ツォルア、ヤルムテ、'),
('JPN', '尼希米记', 16, 11, 30, 'ザノアハ、アドラムとそれらに属する村々、ラキシュとその農地、アゼカとそれに属する村々であった。こうして彼らは、ベエル・シェバからヒノムの谷までの一帯に住みついた。'),
('JPN', '尼希米记', 16, 11, 31, 'ベニヤミンの子孫は、ゲバから、ミクマス、アヤ、ベテルとそれに属する村々、'),
('JPN', '尼希米记', 16, 11, 32, 'アナトテ、ノブ、アナネヤ、'),
('JPN', '尼希米记', 16, 11, 33, 'ハツォル、ラマ、ギタイム、'),
('JPN', '尼希米记', 16, 11, 34, 'ハディデ、ツェボイム、ネバラテ、'),
('JPN', '尼希米记', 16, 11, 35, 'ロデとオノ、および職人の谷に住んだ。'),
('JPN', '尼希米记', 16, 11, 36, 'レビ人のうち、ユダにいたある組はベニヤミンに加わった。'),
('JPN', '尼希米记', 16, 12, 1, 'シェアルティエルの子ゼルバベルおよびヨシュアと一緒に上って来た、祭司とレビ人は次のとおりである。セラヤ、エレミヤ、エズラ、'),
('JPN', '尼希米记', 16, 12, 2, 'アマルヤ、マルク、ハトシュ、'),
('JPN', '尼希米记', 16, 12, 3, 'シェカンヤ、レフム、メレモテ、'),
('JPN', '尼希米记', 16, 12, 4, 'イド、ギネトイ、アビヤ、'),
('JPN', '尼希米记', 16, 12, 5, 'ミヤミン、マアデヤ、ビルガ、'),
('JPN', '尼希米记', 16, 12, 6, 'シェマヤ、エホヤリブ、エダヤ、'),
('JPN', '尼希米记', 16, 12, 7, 'サル、アモク、ヒルキヤ、エダヤ。以上はヨシュアの時代に、祭司とその同族のかしらであった者たちである。'),
('JPN', '尼希米记', 16, 12, 8, 'また、レビ人では、ヨシュア、ビヌイ、カデミエル、シェレベヤ、ユダ、マタンヤで、感謝の歌を受け持っていたのはマタンヤとその兄弟たちであった。'),
('JPN', '尼希米记', 16, 12, 9, 'また、彼らの兄弟のバクブクヤとウンニは、務めのときには彼らの向かい側に立った。'),
('JPN', '尼希米记', 16, 12, 10, 'ヨシュアはエホヤキムを生み、エホヤキムはエルヤシブを生み、エルヤシブはエホヤダを生み、'),
('JPN', '尼希米记', 16, 12, 11, 'エホヤダはヨナタンを生み、ヨナタンはヤドアを生んだ。'),
('JPN', '尼希米记', 16, 12, 12, '次に、エホヤキムの時代に、祭司で一族のかしらであった者は次のとおりである。セラヤ族ではメラヤ、エレミヤ族ではハナンヤ、'),
('JPN', '尼希米记', 16, 12, 13, 'エズラ族ではメシュラム、アマルヤ族ではヨハナン、'),
('JPN', '尼希米记', 16, 12, 14, 'メリク族ではヨナタン、シェバンヤ族ではヨセフ、'),
('JPN', '尼希米记', 16, 12, 15, 'ハリム族ではアデナ、メラヨテ族ではヘルカイ、'),
('JPN', '尼希米记', 16, 12, 16, 'イド族ではゼカリヤ、ギネトン族ではメシュラム、'),
('JPN', '尼希米记', 16, 12, 17, 'アビヤ族ではジクリ、ミンヤミン族、モアデヤ族ではピルタイ、'),
('JPN', '尼希米记', 16, 12, 18, 'ビルガ族ではシャムア、シェマヤ族ではヨナタン、'),
('JPN', '尼希米记', 16, 12, 19, 'エホヤリブ族ではマテナイ、エダヤ族ではウジ、'),
('JPN', '尼希米记', 16, 12, 20, 'サライ族ではカライ、アモク族ではエベル、'),
('JPN', '尼希米记', 16, 12, 21, 'ヒルキヤ族ではハシャブ、エダヤ族ではネタンエル。'),
('JPN', '尼希米记', 16, 12, 22, 'エルヤシブ、エホヤダ、ヨハナン、ヤドアの時代にレビ人は一族のかしらとして登録され、また、祭司はペルシア人ダレイオスの治世に登録された。'),
('JPN', '尼希米记', 16, 12, 23, 'レビの子孫で一族のかしらたちは、エルヤシブの子ヨハナンの時代まで、年代記に記されていた。'),
('JPN', '尼希米记', 16, 12, 24, 'レビ人のかしらたちは、ハシャブヤ、シェレベヤ、およびカデミエルの子ヨシュアであり、その兄弟たちが彼らの向かい側に立って、組と組が相応じて、神の人ダビデの命令に基づき、賛美をして感謝をささげた。'),
('JPN', '尼希米记', 16, 12, 25, 'マタンヤ、バクブクヤ、オバデヤ、メシュラム、タルモン、アクブは門衛で、門の倉を見張っていた。'),
('JPN', '尼希米记', 16, 12, 26, '以上はエホツァダクの子ヨシュアの子エホヤキムの時代と、総督ネヘミヤ、および学者である祭司エズラの時代の人々である。'),
('JPN', '尼希米记', 16, 12, 27, 'エルサレムの城壁の奉献式に際して、彼らはあらゆる場所からレビ人を捜し出してエルサレムに連れて来た。シンバルと琴と竪琴に合わせて感謝の歌を歌い、喜びをもって奉献式を行うためであった。'),
('JPN', '尼希米记', 16, 12, 28, '歌い手たちは、エルサレムの周辺の低地やネトファ人の村々から、'),
('JPN', '尼希米记', 16, 12, 29, 'またベテ・ギルガルやゲバとアズマウェテの農地から集まって来た。この歌い手たちは、エルサレムの周辺に自分たちの村々を建てていたのである。'),
('JPN', '尼希米记', 16, 12, 30, '祭司とレビ人は自分たちの身をきよめ、また民と門と城壁をきよめた。'),
('JPN', '尼希米记', 16, 12, 31, '私はユダの長たちを城壁に上らせ、感謝の歌をささげる二つの大きな賛美隊として配置した。一組は城壁の上を右の方に、糞の門に向かって進んだ。'),
('JPN', '尼希米记', 16, 12, 32, '彼らのうしろに続いて進んだ者は、ホシャヤとユダの長たちの半分、'),
('JPN', '尼希米记', 16, 12, 33, 'アザルヤ、エズラ、メシュラム、'),
('JPN', '尼希米记', 16, 12, 34, 'ユダ、ベニヤミン、シェマヤ、エレミヤであった。'),
('JPN', '尼希米记', 16, 12, 35, '祭司のうちのある者もラッパを持って進んだ。まず、ヨナタンの子ゼカリヤ。ヨナタンはシェマヤの子、シェマヤはマタンヤの子、マタンヤはミカヤの子、ミカヤはザクルの子、ザクルはアサフの子である。'),
('JPN', '尼希米记', 16, 12, 36, '次に、ゼカリヤの兄弟たちシェマヤ、アザルエル、ミラライ、ギラライ、マアイ、ネタンエル、ユダ、ハナニで、神の人ダビデの楽器を持って続いた。学者エズラが彼らの先頭に立った。'),
('JPN', '尼希米记', 16, 12, 37, '彼らは泉の門のところで、城壁の上り口にあるダビデの町の階段をまっすぐに上り、ダビデの家の上を通って東の方の水の門に来た。'),
('JPN', '尼希米记', 16, 12, 38, '感謝の歌をささげるもう一組の賛美隊は、左の方に進んだ。私はそのうしろに従った。民の半分は城壁の上を進み、炉のやぐらの上を通って、幅広の城壁のところに進み、'),
('JPN', '尼希米记', 16, 12, 39, 'エフライムの門の上を通り、エシャナの門を過ぎ、魚の門と、ハナンエルのやぐらと、ハ・メアのやぐらを過ぎて、羊の門まで進んだ。そして監視の門で立ち止まった。'),
('JPN', '尼希米记', 16, 12, 40, 'こうして、感謝の歌をささげる二つの賛美隊は神の宮で位置についた。私も、私とともにいた代表者たちの半分もそうした。'),
('JPN', '尼希米记', 16, 12, 41, 'また祭司たち、エルヤキム、マアセヤ、ミンヤミン、ミカヤ、エルヨエナイ、ゼカリヤ、ハナンヤもラッパを持って、そこにいた。'),
('JPN', '尼希米记', 16, 12, 42, 'また、マアセヤ、シェマヤ、エルアザル、ウジ、ヨハナン、マルキヤ、エラム、エゼルもいた。こうして、歌い手たちは歌い、イズラフヤが指揮をした。'),
('JPN', '尼希米记', 16, 12, 43, '彼らはその日、数多くのいけにえを献げて喜んだ。神が彼らを大いに喜ばせてくださったからである。女も子どもも喜んだので、エルサレムの喜びの声ははるか遠くまで聞こえた。'),
('JPN', '尼希米记', 16, 12, 44, 'その日、財宝や、奉納物、初物や十分の一を納める部屋を管理する人たちが任命され、祭司とレビ人のために律法で定められた分を、町々の農地からそこに集めた。これは、職務に就いている祭司とレビ人をユダの人々が喜んだからである。'),
('JPN', '尼希米记', 16, 12, 45, '彼らは、自分たちの神への任務ときよめの任務を果たした。歌い手や門衛たちも同様であった。ダビデとその子ソロモンの命令のとおりである。'),
('JPN', '尼希米记', 16, 12, 46, '昔から、ダビデとアサフの時代から、歌い手たちのかしらたちがいて、神への賛美と感謝の歌がささげられた。'),
('JPN', '尼希米记', 16, 12, 47, 'ゼルバベルの時代とネヘミヤの時代、全イスラエルは、歌い手と門衛のために定められた分を日ごとに渡していた。彼らはまたレビ人の分を聖別し、レビ人はアロンの子らの分を聖別していた。'),
('JPN', '尼希米记', 16, 13, 1, 'その日、民が聞いているところでモーセの書が朗読され、その中に、アンモン人とモアブ人は決して神の集会に加わってはならない、と書かれているのが見つかった。'),
('JPN', '尼希米记', 16, 13, 2, 'それは、かつて彼らが、パンと水をもってイスラエル人を迎えることをせず、かえってバラムを雇ってイスラエル人を呪わせようとしたからであった。私たちの神はその呪いを祝福に変えられた。'),
('JPN', '尼希米记', 16, 13, 3, '民はこの律法を聞くとすぐに、混血の者をみなイスラエルから切り離した。'),
('JPN', '尼希米记', 16, 13, 4, 'これより以前、祭司エルヤシブは、私たちの神の宮の部屋を任されていて、トビヤと親しい関係にあったので、'),
('JPN', '尼希米记', 16, 13, 5, 'トビヤのために一つの大きな部屋をあてがっていた。以前その部屋は、穀物のささげ物、乳香、器、またレビ人や歌い手や門衛たちのために定められていた、穀物と新しいぶどう酒と油の十分の一、さらに祭司のための奉納物を保管するところであった。'),
('JPN', '尼希米记', 16, 13, 6, 'この間ずっと、私はエルサレムにいなかった。私が、バビロンの王アルタクセルクセスの三十二年に王のところに行き、その後しばらくして王にいとまを乞い、'),
('JPN', '尼希米记', 16, 13, 7, 'エルサレムに帰って来たからである。そのとき私は、エルヤシブがトビヤのために行った悪、すなわち、神の宮の庭にある一つの部屋を彼にあてがったことに気づいた。'),
('JPN', '尼希米记', 16, 13, 8, '私は大いに気分を害し、トビヤ家の家財をすべてその部屋から外へ放り出し、'),
('JPN', '尼希米记', 16, 13, 9, '命じて、その部屋をきよめさせた。そして私は、神の宮の器を、穀物のささげ物や乳香と一緒に再びそこに納めた。'),
('JPN', '尼希米记', 16, 13, 10, 'また私は、レビ人の分が支給されていなかったために、務めに当たるレビ人と歌い手たちが、それぞれ自分の農地に逃げ去っていたことを知った。'),
('JPN', '尼希米记', 16, 13, 11, '私は代表者たちを詰問し、「どうして神の宮が見捨てられているのか」と言った。そして私はレビ人たちを集め、元の職務に就かせた。'),
('JPN', '尼希米记', 16, 13, 12, 'ユダの人々はみな、穀物と新しいぶどう酒と油の十分の一を貯蔵庫に持って来た。'),
('JPN', '尼希米记', 16, 13, 13, 'そこで私は、祭司シェレムヤ、学者ツァドク、レビ人の一人ペダヤに貯蔵庫を管理させ、マタンヤの子ザクルの子ハナンを彼らの助手とした。彼らが忠実な者と認められていたからである。彼らの任務は仲間に分配をすることであった。'),
('JPN', '尼希米记', 16, 13, 14, '私の神よ、どうか、このことのゆえに私を覚えていてください。私が神の宮とその務めのためにした数々の誠実な行いを、ぬぐい去らないでください。'),
('JPN', '尼希米记', 16, 13, 15, 'そのころ私は、ユダのうちで安息日にぶどう踏みをしている者、麦束を運んでいる者、また、ろばに荷物を負わせている者、さらに、ぶどう酒、ぶどうの実、いちじくなど、あらゆる品物を積んで、安息日にエルサレムに運び込んでいる者を見つけた。それで私は、彼らが食糧を売ったその日に、彼らを戒めた。'),
('JPN', '尼希米记', 16, 13, 16, 'また、そこに住んでいたツロの人々も、魚などあらゆる商品を運んで来て、安息日に、しかもエルサレムでユダの人々に売っていた。'),
('JPN', '尼希米记', 16, 13, 17, 'そこで、私はユダの有力者たちを詰問して言った。「あなたがたが行っているこの悪事は何か。安息日を汚しているではないか。'),
('JPN', '尼希米记', 16, 13, 18, 'あなたがたの先祖も、このようなことをしたので、私たちの神はこのすべてのわざわいを、私たちとこの都の上にもたらされたのではないか。それなのに、あなたがたは安息日を汚して、イスラエルの上にまたもや御怒りを招こうとしている。」'),
('JPN', '尼希米记', 16, 13, 19, '安息日の前、エルサレムの門に夕闇が迫ると、私は命じて扉を閉めさせ、安息日が終わるまでは開いてはならないと命じた。そして、私の配下の若い者の何人かを門の見張りに立て、安息日に荷物が持ち込まれないようにした。'),
('JPN', '尼希米记', 16, 13, 20, 'それで商人やあらゆる品物を売る者たちは、一、二度エルサレムの外で夜を過ごした。'),
('JPN', '尼希米记', 16, 13, 21, 'そこで、私は彼らを戒めて言った。「なぜ、あなたがたは城壁の前で夜を過ごすのか。もう一度このようなことをすれば、私はあなたがたを処罰する。」その時から、彼らはもう安息日には来なくなった。'),
('JPN', '尼希米记', 16, 13, 22, 'また私はレビ人に、安息日を聖なるものとするために、彼らが身をきよめ、門の見張りとして来るように命じた。私の神よ、このことにおいても、どうか私を覚えていてください。そして、あなたの豊かな恵みにしたがって私をあわれんでください。'),
('JPN', '尼希米记', 16, 13, 23, 'そのころまた私は、アシュドデ人、アンモン人、モアブ人の女を妻にしているユダヤ人たちに気がついた。'),
('JPN', '尼希米记', 16, 13, 24, '彼らの子どもの半分は、アシュドデのことばか、あるいはそれぞれほかのことばを話して、ユダヤのことばが分からなかった。'),
('JPN', '尼希米记', 16, 13, 25, 'そこで私は彼らを詰問してののしり、そのうちの数人を打って毛を引き抜き、神にかけて誓わせて言った。「あなたがたの娘を彼らの息子に嫁がせてはならない。また、彼らの娘をあなたがたの息子、あるいはあなたがた自身の妻としてはならない。'),
('JPN', '尼希米记', 16, 13, 26, 'イスラエルの王ソロモンも、このことで罪を犯したではないか。多くの国の中で彼のような王はいなかった。彼は神に愛され、神は彼をイスラエル全土を治める王としたのに、その彼にさえ異国人の女たちが罪を犯させてしまった。'),
('JPN', '尼希米记', 16, 13, 27, 'あなたがたについても、異国人の女を妻とし、私たちの神の信頼を裏切るという、この大きな悪が行われていることを聞かなければならないのか。」'),
('JPN', '尼希米记', 16, 13, 28, '大祭司エルヤシブの子エホヤダの子の一人は、ホロン人サンバラテの婿であった。それで、私は彼を私のところから追い出した。'),
('JPN', '尼希米记', 16, 13, 29, '私の神よ、どうか彼らのことを覚えていてください。彼らは祭司職を汚し、祭司職とレビ人たちの契約を汚したのです。'),
('JPN', '尼希米记', 16, 13, 30, '私は異教的なもの一切から彼らをきよめ、祭司とレビ人のそれぞれの務めにしたがって職務に就かせ、'),
('JPN', '尼希米记', 16, 13, 31, '定められた時に行う薪のささげ物と、初物についても規定を定めた。私の神よ、どうか私を覚えて、いつくしんでください。'),
('JPN', '以斯帖记', 17, 1, 1, 'クセルクセスの時代、クセルクセスが、インドからクシュまで百二十七州を治めていた時のことである。'),
('JPN', '以斯帖记', 17, 1, 2, 'クセルクセス王がスサの城で、王座に着いていたころ、'),
('JPN', '以斯帖记', 17, 1, 3, 'その治世の第三年に、彼はすべての首長と家臣たちのために宴会を催した。それにはペルシアとメディアの有力者、貴族たち、および諸州の首長たちが出席した。'),
('JPN', '以斯帖记', 17, 1, 4, '王は彼の王国の栄光の富と大いなる栄誉を幾日も示して、百八十日に及んだ。'),
('JPN', '以斯帖记', 17, 1, 5, 'この期間が終わると、王は、スサの城にいた身分の高い者から低い者に至るまでのすべての民のために、七日間、王宮の園の庭で宴会を催した。'),
('JPN', '以斯帖记', 17, 1, 6, '白綿布や青色の布が、白や紫色の細ひもで大理石の柱の銀の輪に結び付けられ、金と銀でできた長椅子が、緑色石、白大理石、真珠貝や黒大理石のモザイクの床の上に置かれていた。'),
('JPN', '以斯帖记', 17, 1, 7, '金の杯で酒がふるまわれたが、その杯は一つ一つ種類が違っていた。王室のぶどう酒は、王にふさわしく豊かにあった。'),
('JPN', '以斯帖记', 17, 1, 8, 'しかし飲酒は、「強要しないこと」という法に従っていた。だれでもそれぞれ自分の思いのままにさせるようにと、王が宮廷のすべての長に命じていたからである。'),
('JPN', '以斯帖记', 17, 1, 9, '王妃ワシュティも、クセルクセス王の王宮で婦人たちのために宴会を催した。'),
('JPN', '以斯帖记', 17, 1, 10, '七日目に、クセルクセス王はぶどう酒で心が陽気になり、王に仕える七人の宦官メフマン、ビゼタ、ハルボナ、ビグタ、アバグタ、ゼタル、カルカスに命じ、'),
('JPN', '以斯帖记', 17, 1, 11, '王妃ワシュティに王冠をかぶらせて、王の前に連れて来るようにと言った。彼女の容姿がすばらしかったので、その美しさを民と首長たちに見せるためであった。'),
('JPN', '以斯帖记', 17, 1, 12, 'しかし、王妃ワシュティは宦官から伝えられた王の命令を拒み、来ようとはしなかった。そのため王は激しく怒り、その憤りは彼のうちで燃え立った。'),
('JPN', '以斯帖记', 17, 1, 13, 'そこで王は時を熟知している、知恵のある者たちに言った──このように、法令と裁判に詳しいすべての者に諮るのが、王の慣わしであった。'),
('JPN', '以斯帖记', 17, 1, 14, '王の側近はペルシアとメディアの七人の首長たち、カルシェナ、シェタル、アデマタ、タルシシュ、メレス、マルセナ、メムカンで、彼らは王の面前に控えながら、王国の最高の地位に就いていた──'),
('JPN', '以斯帖记', 17, 1, 15, '「王妃ワシュティは、宦官によって伝えられたクセルクセス王の命令に従わなかった。法令にしたがって、彼女をどう処分すべきか。」'),
('JPN', '以斯帖记', 17, 1, 16, 'メムカンは王と首長たちの前で答えた。「王妃ワシュティは王一人だけではなく、クセルクセス王のすべての州の全首長と全住民にも悪いことをしました。'),
('JPN', '以斯帖记', 17, 1, 17, '王妃のことが女たちみなに知れ渡り、『クセルクセス王が王妃ワシュティに、王の前に来るように命じたのに、来なかった』と言って、女たちは自分の夫を軽く見るようになるでしょう。'),
('JPN', '以斯帖记', 17, 1, 18, '今日にでも、王妃のことを聞いたペルシアとメディアの首長の夫人たちは、王のすべての首長たちにこのことを言って、並々ならぬ軽蔑と怒りが起こることでしょう。'),
('JPN', '以斯帖记', 17, 1, 19, 'もし王がおよろしければ、ワシュティはクセルクセス王の前に出てはならない、という勅令をご自分でお出しになり、ペルシアとメディアの法令の中に書き入れて、変更することのないようにされてはいかがでしょうか。王妃の位は、彼女よりももっとすぐれた者にお授けください。'),
('JPN', '以斯帖记', 17, 1, 20, '王が出される詔勅がこの大きな王国の隅々まで告げ知らされれば、女たちは、身分の高い者から低い者に至るまでみな、自分の夫を敬うようになるでしょう。」'),
('JPN', '以斯帖记', 17, 1, 21, 'この進言は王と首長たちの心にかなったので、王はメムカンの言ったとおりにした。'),
('JPN', '以斯帖记', 17, 1, 22, '王は、王のすべての州に書簡を送った。各州にはその文字で、各民族にはその言語で書簡を送り、男子はみな一家の主人となること、また自分の民族の言語で話すことを命じた。'),
('JPN', '以斯帖记', 17, 2, 1, 'これらの出来事の後、クセルクセス王の憤りが収まると、王はワシュティのこと、彼女のしたこと、彼女について決められたことを思い出した。'),
('JPN', '以斯帖记', 17, 2, 2, '王に仕える侍従たちは言った。「王のために容姿の美しい未婚の娘たちを探しましょう。'),
('JPN', '以斯帖记', 17, 2, 3, '王は王国のすべての州に役人を任命し、容姿の美しい未婚の娘たちをみな、スサの城の後宮に集めて、女たちの監督官である王の宦官ヘガイの管理のもとに置き、化粧品を彼女たちに与えるようにしてください。'),
('JPN', '以斯帖记', 17, 2, 4, 'そして、王のお心にかなう娘を、ワシュティの代わりに王妃としてください。」このことは王の心にかなったので、彼はそのようにした。'),
('JPN', '以斯帖记', 17, 2, 5, 'スサの城に一人のユダヤ人がいて、その名をモルデカイといった。この人はヤイルの子で、ヤイルはシムイの子、シムイはベニヤミン人キシュの子であった。'),
('JPN', '以斯帖记', 17, 2, 6, 'このキシュは、ユダの王エコンヤと一緒に捕らえ移された捕囚の民とともに、エルサレムから捕らえ移された者であった。エコンヤはバビロンの王ネブカドネツァルが捕らえ移したのであった。'),
('JPN', '以斯帖记', 17, 2, 7, 'モルデカイはおじの娘ハダサ、すなわちエステルを養育していた。彼女には父も母もいなかったからである。この娘は姿も美しく、顔だちも良かった。モルデカイは、彼女の父と母が死んだとき、彼女を引き取って自分の娘としていた。'),
('JPN', '以斯帖记', 17, 2, 8, '王の命令、すなわちその法令が伝えられて、多くの娘たちがスサの城に集められ、ヘガイの管理のもとに置かれたとき、エステルも王宮に連れて行かれて、女たちの監督官ヘガイの管理のもとに置かれた。'),
('JPN', '以斯帖记', 17, 2, 9, 'この娘はヘガイの目にかない、彼の好意を得た。彼は急いで化粧品とごちそうを彼女に与え、また王宮から選ばれた七人の侍女を彼女に付けた。また、ヘガイは彼女とその侍女たちを、後宮の最も良いところに移した。'),
('JPN', '以斯帖记', 17, 2, 10, 'エステルは自分の民族も、自分の生まれも明かさなかった。モルデカイが、明かしてはいけないと彼女に命じておいたからである。'),
('JPN', '以斯帖记', 17, 2, 11, 'モルデカイは毎日、後宮の庭の前を行き来し、エステルの安否と、彼女がどうされるかを知ろうとしていた。'),
('JPN', '以斯帖记', 17, 2, 12, '娘たちは、女たちの規則にしたがって、十二か月の期間が終わった後、一人ずつ順番にクセルクセス王のところに入って行くことになっていた。準備の期間は、六か月は没薬の香油を、次の六か月は香料と女たちのための化粧品を用いて化粧することで、完了するのであった。'),
('JPN', '以斯帖记', 17, 2, 13, 'このようにして、娘が王のところに入って行くとき、その娘の願うものはみな与えられ、それを携えて後宮から王宮に行くことができた。'),
('JPN', '以斯帖记', 17, 2, 14, '娘は夕方入って行き、朝になると第二の後宮に帰ることになっていた。そこは、側女たちの監督官である、王の宦官シャアシュガズの管理のもとにあった。そこの女は、王が気に入って指名されるのでなければ、二度と王のところには行けなかった。'),
('JPN', '以斯帖记', 17, 2, 15, 'さて、モルデカイが引き取って自分の娘とした、彼のおじアビハイルの娘エステルが、王のところに入って行く順番が来たとき、彼女は女たちの監督官である、王の宦官ヘガイの勧めたもののほかは、何一つ求めなかった。こうしてエステルは、彼女を見るすべての者から好意を受けていた。'),
('JPN', '以斯帖记', 17, 2, 16, 'エステルが王宮のクセルクセス王のもとに召し入れられたのは、王の治世の第七年の第十の月、すなわちテベテの月であった。'),
('JPN', '以斯帖记', 17, 2, 17, '王はほかのどの女よりもエステルを愛した。このため、彼女はどの娘たちよりも王の好意と寵愛を受けた。王は王冠を彼女の頭に置き、ワシュティの代わりに彼女を王妃とした。'),
('JPN', '以斯帖记', 17, 2, 18, 'それから、王はすべての首長と家臣たちのために大宴会、すなわちエステルの宴会を催した。諸州には免税を布告し、王にふさわしい贈り物を配った。'),
('JPN', '以斯帖记', 17, 2, 19, '娘たちが二度目に集められたとき、モルデカイは王の門のところに座っていた。'),
('JPN', '以斯帖记', 17, 2, 20, 'エステルは、モルデカイが彼女に命じていたように、自分の生まれも自分の民族も明かしていなかった。エステルはモルデカイに養育されていたときと同じように、彼の命令に従っていた。'),
('JPN', '以斯帖记', 17, 2, 21, 'そのころ、モルデカイが王の門のところに座っていると、入り口を守っていた王の二人の宦官ビグタンとテレシュが怒って、クセルクセス王を手にかけようとしていた。'),
('JPN', '以斯帖记', 17, 2, 22, 'このことがモルデカイの知るところとなり、彼はこれを王妃エステルに知らせた。エステルはこれをモルデカイの名で王に告げた。'),
('JPN', '以斯帖记', 17, 2, 23, 'このことが追及され、その事実が明らかになったので、彼ら二人は木にかけられた。このことは王の前で年代記に記録された。'),
('JPN', '以斯帖记', 17, 3, 1, 'これらの出来事の後、クセルクセス王はアガグ人ハメダタの子ハマンを重んじ、彼を昇進させて、その席を彼とともにいる首長たちのだれよりも上に置いた。'),
('JPN', '以斯帖记', 17, 3, 2, 'それで、王の門のところにいる王の家来たちはみな、ハマンに対して膝をかがめてひれ伏した。王が彼についてこのように命じたからである。しかし、モルデカイは膝もかがめず、ひれ伏そうともしなかった。'),
('JPN', '以斯帖记', 17, 3, 3, '王の門のところにいる王の家来たちは、モルデカイに「あなたはなぜ、王の命令に背くのか」と言った。'),
('JPN', '以斯帖记', 17, 3, 4, '彼らは毎日そう言ったが、モルデカイは耳を貸そうとしなかった。それで、モルデカイのしていることが続けられてよいものかどうかを確かめようと、これをハマンに告げた。モルデカイが、自分がユダヤ人であることを彼らに打ち明けていたからである。'),
('JPN', '以斯帖记', 17, 3, 5, 'ハマンはモルデカイが自分に対して膝もかがめず、ひれ伏そうともしないのを見て、憤りに満たされた。'),
('JPN', '以斯帖记', 17, 3, 6, 'しかし、ハマンはモルデカイ一人を手にかけるだけでは満足しなかった。モルデカイの民族のことが、ハマンに知らされていたのである。それでハマンは、クセルクセスの王国中のすべてのユダヤ人、すなわちモルデカイの民族を根絶やしにしようとした。'),
('JPN', '以斯帖记', 17, 3, 7, 'クセルクセス王の第十二年の第一の月、すなわちニサンの月に、日と月を決めるためにハマンの前で、プル、すなわちくじが投げられた。くじは第十二の月、すなわちアダルの月に当たった。'),
('JPN', '以斯帖记', 17, 3, 8, 'ハマンはクセルクセス王に言った。「王国のすべての州にいる諸民族の間に、散らされて離れ離れになっている一つの民族があります。彼らの法令はどの民族のものとも違っていて、王の法令を守っていません。彼らをそのままにさせておくことは、王のためになりません。'),
('JPN', '以斯帖记', 17, 3, 9, '王様。もしよろしければ、彼らを滅ぼすようにと書いてください。私はその仕事をする者たちに銀一万タラントを量って渡します。そうして、それを王の宝物庫に納めさせましょう。」'),
('JPN', '以斯帖记', 17, 3, 10, '王は自分の手から指輪を外して、アガグ人ハメダタの子で、ユダヤ人の敵であるハマンにそれを渡した。'),
('JPN', '以斯帖记', 17, 3, 11, '王はハマンに言った。「その銀はおまえに与えられるようにしよう。また、その民族もその銀でおまえの好きなようにするがよい。」'),
('JPN', '以斯帖记', 17, 3, 12, 'そこで、第一の月の十三日に、王の書記官たちが召集され、ハマンが、王の太守、各州を治めている総督、各民族の首長たちに命じたことがすべて、各州にその文字で、各民族にはその言語で記された。それは、クセルクセスの名で書かれ、王の指輪で印が押された。'),
('JPN', '以斯帖记', 17, 3, 13, '書簡は急使によって王のすべての州へ送られた。それには、第十二の月、すなわちアダルの月の十三日の一日のうちに、若い者も年寄りも、子どもも女も、すべてのユダヤ人を根絶やしにし、殺害し、滅ぼし、彼らの家財をかすめ奪えとあった。'),
('JPN', '以斯帖记', 17, 3, 14, '各州に法令として発布される文書の写しが、この日の準備のために、すべての民族に公示された。'),
('JPN', '以斯帖记', 17, 3, 15, '急使は王の命令によって急いで出て行った。この法令はスサの城でも発布された。このとき、王とハマンは酒を酌み交わしていたが、スサの都は混乱に陥った。'),
('JPN', '以斯帖记', 17, 4, 1, 'モルデカイは、なされたすべてのことを知った。モルデカイは衣を引き裂き、粗布をまとい、灰をかぶり、大声で激しくわめき叫びながら都の真ん中に出て行った。'),
('JPN', '以斯帖记', 17, 4, 2, 'そして王の門の前のところまで来た。王の門の中には、粗布をまとったままでは入ることができなかったのである。'),
('JPN', '以斯帖记', 17, 4, 3, '王の命令とその法令が届いたどの州においても、ユダヤ人の間には大きな悲しみがあり、断食と泣き声と嘆きが起こり、多くの人たちは粗布をまとって灰の上に座った。'),
('JPN', '以斯帖记', 17, 4, 4, 'エステルの侍女たちとその宦官たちが入って来て、彼女にこのことを告げたので、王妃は非常に痛み苦しんだ。彼女はモルデカイに衣服を送り、それを着せて、粗布を脱がせようとしたが、彼はそれを受け取らなかった。'),
('JPN', '以斯帖记', 17, 4, 5, 'エステルは、王の宦官の一人で、王が彼女に仕えさせるために任命していたハタクを呼び寄せ、モルデカイのところへ行って、これはどういうわけか、また何のためかと聞いて来るように命じた。'),
('JPN', '以斯帖记', 17, 4, 6, 'ハタクは王の門の前の、町の広場にいるモルデカイのところに出て行った。'),
('JPN', '以斯帖记', 17, 4, 7, 'モルデカイは自分の身に起こったことをすべて彼に告げ、ハマンがユダヤ人を滅ぼすために王の宝物庫に納めると約束した、正確な金額も告げた。'),
('JPN', '以斯帖记', 17, 4, 8, 'また、ユダヤ人を根絶やしにするためにスサで発布された法令の文書の写しを彼に渡した。それは、エステルに見せて事情を知らせ、そして彼女が王のところに行って、自分の民族のために王からのあわれみを乞い求めるように、彼女に命じるためであった。'),
('JPN', '以斯帖记', 17, 4, 9, 'ハタクは帰って来て、モルデカイの伝言をエステルに告げた。'),
('JPN', '以斯帖记', 17, 4, 10, 'エステルはハタクに命じて、モルデカイにこう伝えた。'),
('JPN', '以斯帖记', 17, 4, 11, '「王の家臣たちも王の諸州の民も、だれでも知っているように、召されないのに奥の中庭に入って王のところに行く者は、男でも女でも死刑に処せられるという法令があります。ただし、王がその人に金の笏を差し伸ばせば、その人は生きながらえます。私はこの三十日間、まだ王のところへ行くようにと召されていません。」'),
('JPN', '以斯帖记', 17, 4, 12, '彼がエステルのことばをモルデカイに告げると、'),
('JPN', '以斯帖记', 17, 4, 13, 'モルデカイはエステルに返事を送って言った。「あなたは、すべてのユダヤ人から離れて王宮にいるので助かるだろう、と考えてはいけない。'),
('JPN', '以斯帖记', 17, 4, 14, 'もし、あなたがこのようなときに沈黙を守るなら、別のところから助けと救いがユダヤ人のために起こるだろう。しかし、あなたも、あなたの父の家も滅びるだろう。あなたがこの王国に来たのは、もしかすると、このような時のためかもしれない。」'),
('JPN', '以斯帖记', 17, 4, 15, 'エステルはモルデカイに返事を送って言った。'),
('JPN', '以斯帖记', 17, 4, 16, '「行って、スサにいるユダヤ人をみな集め、私のために断食してください。三日三晩、食べたり飲んだりしないようにしてください。私も私の侍女たちも、同じように断食します。そのようにしたうえで、法令に背くことですが、私は王のところへ参ります。私は、死ななければならないのでしたら死にます。」'),
('JPN', '以斯帖记', 17, 4, 17, 'モルデカイは出て行って、エステルが彼に頼んだとおりにした。'),
('JPN', '以斯帖记', 17, 5, 1, '三日目になり、エステルは王妃の衣装を着て、王室の正面にある王宮の奥の中庭に立った。王は王室の入り口の正面にある王宮の玉座に座っていた。'),
('JPN', '以斯帖记', 17, 5, 2, '王が、中庭に立っている王妃エステルを見たとき、彼女は王の好意を得た。王は手にしている金の笏をエステルに差し伸ばした。エステルは近寄って、その笏の先に触れた。'),
('JPN', '以斯帖记', 17, 5, 3, '王は彼女に言った。「どうしたのだ。王妃エステル。何を望んでいるのか。王国の半分でも、あなたにやれるのだが。」'),
('JPN', '以斯帖记', 17, 5, 4, 'エステルは答えた。「もしも王様がよろしければ、今日、私が王様のために設ける宴会にハマンとご一緒にお越しください。」'),
('JPN', '以斯帖记', 17, 5, 5, 'すると王は「ハマンを急いで来させて、エステルの言ったようにしよう」と言った。王とハマンはエステルが設けた宴会にやって来た。'),
('JPN', '以斯帖记', 17, 5, 6, 'その酒宴の席上、王はエステルに尋ねた。「あなたは何を願っているのか。それを授けてやろう。何を望んでいるのか。王国の半分でも、それをかなえてやろう。」'),
('JPN', '以斯帖记', 17, 5, 7, 'エステルは答えて言った。「私が願い、望んでいることは、'),
('JPN', '以斯帖记', 17, 5, 8, 'もしも私が王様のご好意を受けることができ、また王様がよろしくて、私の願いをゆるし、私の望みをかなえていただけますなら、私が設ける宴会に、もう一度ハマンとご一緒にお越しください。そうすれば、明日、私は王様のおっしゃったとおりにいたします。」'),
('JPN', '以斯帖记', 17, 5, 9, 'ハマンはその日、喜び上機嫌で去って行った。ところが、ハマンは、王の門のところにいるモルデカイが立ち上がろうともせず、身動きもしないのを見て、モルデカイに対する憤りに満たされた。'),
('JPN', '以斯帖记', 17, 5, 10, 'しかし、ハマンは我慢して家に帰り、人を送って、友人たちと妻ゼレシュを連れて来させた。'),
('JPN', '以斯帖记', 17, 5, 11, 'ハマンは自分の輝かしい富について、また子どもが大勢いることや、王が自分を重んじ、王の首長や家臣たちの上に自分を昇進させてくれたことなどを、すべて彼らに話した。'),
('JPN', '以斯帖记', 17, 5, 12, 'ハマンは言った。「しかも王妃エステルは、王妃が設けた宴会に、私のほかはだれも王と一緒に来させなかった。明日も私は、王と一緒に王妃に招かれている。'),
('JPN', '以斯帖记', 17, 5, 13, 'しかし、私が、王の門のところに座っているあのユダヤ人モルデカイを見なければならない間は、これら一切のことも私には何の役にも立たない。」'),
('JPN', '以斯帖记', 17, 5, 14, 'すると、彼の妻ゼレシュと彼の友人たちはみな彼に言った。「高さ五十キュビトの柱を立てさせて、明日の朝、王に話して、モルデカイをそれにかけるようにしなさい。それから、王と一緒に、喜んでその宴会にお出かけなさい。」ハマンはこの進言が気に入ったので、その柱を立てさせた。'),
('JPN', '以斯帖记', 17, 6, 1, 'その夜、王は眠れなかったので、記録の書、年代記を持って来るように命じた。そしてそれは王の前で読まれた。'),
('JPN', '以斯帖记', 17, 6, 2, 'その中に、入り口を守っていた王の二人の宦官ビグタナとテレシュが、クセルクセス王を殺そうとしていることをモルデカイが報告した、と書かれているのを見つけた。'),
('JPN', '以斯帖记', 17, 6, 3, 'そこで王は尋ねた。「このことで、栄誉とか昇進とか、何かモルデカイに与えたか。」王に仕える侍従たちは答えた。「彼には何もしていません。」'),
('JPN', '以斯帖记', 17, 6, 4, '王は言った。「庭にだれがいるのか。」ちょうどハマンが、モルデカイのために準備した柱に彼をかけることを王に上奏しようと、王宮の外庭に入って来たところであった。'),
('JPN', '以斯帖记', 17, 6, 5, '王に仕える侍従たちは王に言った。「庭のあそこにハマンがいます。」王は言った。「ここに通せ。」'),
('JPN', '以斯帖记', 17, 6, 6, 'ハマンが入って来ると、王は彼に言った。「王が栄誉を与えたいと思う者には、どうしたらよかろう。」ハマンは心のうちで思った。「王が栄誉を与えたいと思う者とは、私以外にだれがいるだろう。」'),
('JPN', '以斯帖记', 17, 6, 7, 'そこでハマンは王に言った。「王が栄誉を与えたいと思われる人のためには、')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '以斯帖记', 17, 6, 8, '王が着ておられた王服を持って来て、また、王の乗られた馬を、その頭に王冠をつけて引いて来るようにしてください。'),
('JPN', '以斯帖记', 17, 6, 9, 'その王服と馬を、貴族である王の首長の一人の手に渡し、王が栄誉を与えたいと思われる人に王服を着せ、その人を馬に乗せて都の広場に導き、その前で『王が栄誉を与えたいと思われる人はこのとおりである』と、ふれまわらせてください。」'),
('JPN', '以斯帖记', 17, 6, 10, 'すると、王はハマンに言った。「あなたが言ったとおりに、すぐ王服と馬を取って来て、王の門のところに座っているユダヤ人モルデカイにそのようにしなさい。あなたの言ったことを一つも怠ってはならない。」'),
('JPN', '以斯帖记', 17, 6, 11, 'ハマンは王服と馬を取って来て、モルデカイに着せ、彼を馬に乗せて都の広場に導き、その前で「王が栄誉を与えたいと思われる人はこのとおりである」と叫んだ。'),
('JPN', '以斯帖记', 17, 6, 12, 'それからモルデカイは王の門に戻ったが、ハマンは嘆き悲しんで頭をおおい、急いで家に帰った。'),
('JPN', '以斯帖记', 17, 6, 13, 'ハマンは自分の身に起こったことの一部始終を、妻ゼレシュと彼のすべての友人たちに話した。すると、知恵のある者たちと妻ゼレシュは彼に言った。「あなたはモルデカイに敗れかけていますが、このモルデカイがユダヤ民族の一人であるなら、あなたはもう彼に勝つことはできません。必ずやあなたは敗れるでしょう。」'),
('JPN', '以斯帖记', 17, 6, 14, '彼らがまだハマンと話しているうちに、王の宦官たちがやって来て、ハマンを急がせて、エステルの設けた宴会に連れて行った。'),
('JPN', '以斯帖记', 17, 7, 1, '王とハマンは王妃エステルの宴会にやって来た。'),
('JPN', '以斯帖记', 17, 7, 2, 'この酒宴の二日目にも、王はエステルに尋ねた。「あなたは何を願っているのか。王妃エステル。それを授けてやろう。何を望んでいるのか。王国の半分でも、それをかなえてやろう。」'),
('JPN', '以斯帖记', 17, 7, 3, '王妃エステルは答えた。「王様。もしも私があなた様のご好意を受けることができ、また王様がよろしければ、私の願いを聞き入れて、私にいのちを与え、私の望みを聞き入れて、私の民族にもいのちを与えてください。'),
('JPN', '以斯帖记', 17, 7, 4, '私も私の民族も、売られて、根絶やしにされ、虐殺され、滅ぼされようとしています。私たちが男女の奴隷として売られるだけなら、私は黙っていたことでしょうが、そうはいきません。その迫害する者は、王のお受けになる損失を償うことはできないのですから。」'),
('JPN', '以斯帖记', 17, 7, 5, 'クセルクセス王は王妃エステルに言った。「そんなことをしようと心に企んでいる者は、いったいだれか。どこにいるのか。」'),
('JPN', '以斯帖记', 17, 7, 6, 'エステルは言った。「迫害する者、敵とは、この悪人ハマンです。」ハマンは王と王妃の前で震え上がった。'),
('JPN', '以斯帖记', 17, 7, 7, '王は憤って酒宴の席を立ち、宮殿の園に出て行った。ハマンは王妃エステルにいのち乞いをしようとしてとどまった。王が彼にわざわいを下す決心をしたことが分かったからである。'),
('JPN', '以斯帖记', 17, 7, 8, '王が宮殿の園から酒宴の広間に戻って来ると、エステルのいた長椅子の上にハマンがひれ伏していたので、王は言った。「私の前で、この家の中で王妃までも辱めようとするのか。」このことばが王の口から出るやいなや、ハマンの顔は青ざめた。'),
('JPN', '以斯帖记', 17, 7, 9, 'そのとき、王の前にいた宦官の一人ハルボナが言った。「ちょうど、王に良い知らせを告げたモルデカイのためにハマンが用意した、高さ五十キュビトの柱がハマンの家に立っています。」すると王は命じた。「彼をそれにかけよ。」'),
('JPN', '以斯帖记', 17, 7, 10, 'こうしてハマンは、モルデカイのために準備しておいた柱にかけられた。それで王の憤りは収まった。'),
('JPN', '以斯帖记', 17, 8, 1, 'その日、クセルクセス王は王妃エステルに、ユダヤ人を迫害する者ハマンの家を与えた。モルデカイは王の前に来た。エステルが自分と彼との関係を明かしたからである。'),
('JPN', '以斯帖记', 17, 8, 2, '王はハマンから取り返した自分の指輪を外して、それをモルデカイに与え、エステルはモルデカイにハマンの家の管理を任せた。'),
('JPN', '以斯帖记', 17, 8, 3, 'エステルは再び王に告げて、その足もとにひれ伏し、アガグ人ハマンがユダヤ人に対して企んだ、わざわいとその計略を取り除いていただきたいと、泣きながら嘆願した。'),
('JPN', '以斯帖记', 17, 8, 4, '王がエステルに金の笏を差し伸ばしたので、エステルは身を起こし、王の前に立って、'),
('JPN', '以斯帖记', 17, 8, 5, '言った。「もしも王様がよろしければ、また私が王様のご好意を受けることができ、このことを王様がもっともだとお思いになり、私のことがお気に召すなら、アガグ人ハメダタの子ハマンが、王のすべての州にいるユダヤ人を滅ぼしてしまえと書いた、あのたくらみの書簡を取り消すように、詔書を出してください。'),
('JPN', '以斯帖记', 17, 8, 6, 'どうして私は、自分の民族に降りかかるわざわいを見て我慢していられるでしょう。また、どうして、私の同族が滅びるのを見て我慢していられるでしょう。」'),
('JPN', '以斯帖记', 17, 8, 7, 'クセルクセス王は、王妃エステルとユダヤ人モルデカイに言った。「見よ。ハマンの家を私はエステルに与え、彼は柱にかけられた。ハマンがユダヤ人たちに手を下そうとしたからである。'),
('JPN', '以斯帖记', 17, 8, 8, 'あなたがたは、ユダヤ人についてあなたがたのよいと思うように王の名で書き、王の指輪でそれに印を押しなさい。王の名で書かれ、王の指輪で印が押された文書は、だれも取り消すことができない。」'),
('JPN', '以斯帖记', 17, 8, 9, 'そのとき、王の書記官たちが召集された。それは第三の月、すなわちシワンの月の二十三日であった。そして、すべてモルデカイが命じたとおりに、ユダヤ人と、太守、総督たち、およびインドからクシュまで百二十七州の首長たちに、詔書が書き送られた。各州にその文字で、各民族にはその言語で、ユダヤ人にはその文字と言語で書き送られた。'),
('JPN', '以斯帖记', 17, 8, 10, 'モルデカイはクセルクセス王の名で書き、王の指輪でそれに印を押し、その書簡を、御用馬の早馬に乗る急使に託して送った。'),
('JPN', '以斯帖记', 17, 8, 11, 'その中で王は、どの町にいるユダヤ人たちにも、自分のいのちを守るために集まって、自分たちを襲う民や州の軍隊を、子どもも女たちも含めて残らず根絶やしにし、虐殺し、滅ぼし、彼らの家財をかすめ奪うことを許した。'),
('JPN', '以斯帖记', 17, 8, 12, 'このことは、クセルクセス王のすべての州において、第十二の月、すなわちアダルの月の十三日に、一日のうちに行うようにということであった。'),
('JPN', '以斯帖记', 17, 8, 13, '各州に法令として発布される、この文書の写しが、すべての民族に公示された。それは、ユダヤ人が自分たちの敵に復讐するこの日に備えるためであった。'),
('JPN', '以斯帖记', 17, 8, 14, '御用馬の早馬に乗った急使は、王の命令によってせき立てられて、急いで出て行った。この法令はスサの城で発布された。'),
('JPN', '以斯帖记', 17, 8, 15, 'モルデカイは青色と白色の王服を着て、大きな金の冠をかぶり、白亜麻布と紫色のマントをまとって、王の前から出て来た。すると、スサの都は喜びの声にあふれた。'),
('JPN', '以斯帖记', 17, 8, 16, 'ユダヤ人にとって、それは光と喜び、歓喜と栄誉であった。'),
('JPN', '以斯帖记', 17, 8, 17, '王の命令と法令が届いたところは、どの州、どの町でも、ユダヤ人は喜び楽しみ、祝宴を張って、祝日とした。この地の諸民族の中で大勢の者が、自分はユダヤ人であると宣言した。それはユダヤ人への恐れが彼らに下ったからである。'),
('JPN', '以斯帖记', 17, 9, 1, '第十二の月、すなわちアダルの月の十三日、この日に王の命令と法令が実施された。ユダヤ人の敵がユダヤ人を征服しようと望んでいたまさにその日に、逆に、ユダヤ人のほうが自分たちを憎む者たちを征服することとなった。'),
('JPN', '以斯帖记', 17, 9, 2, 'ユダヤ人たちは、自分たちに害を加えようとする者たちを手にかけようと、クセルクセス王のすべての州にある自分たちの町々で集まったが、だれもユダヤ人に抵抗する者はいなかった。彼らへの恐れが、すべての民族に下ったからである。'),
('JPN', '以斯帖记', 17, 9, 3, '諸州の首長、太守、総督、王の役人もみなユダヤ人たちを支援した。モルデカイへの恐れが彼らに下ったからである。'),
('JPN', '以斯帖记', 17, 9, 4, '実際、モルデカイは王宮で勢力があり、その名声はすべての州に広がっていた。実に、この人物モルデカイは、ますます勢力を伸ばしたのであった。'),
('JPN', '以斯帖记', 17, 9, 5, 'ユダヤ人たちは彼らの敵をみな剣で打ち殺し、虐殺して滅ぼし、自分たちを憎む者を思いのままに処分した。'),
('JPN', '以斯帖记', 17, 9, 6, 'ユダヤ人はスサの城でも五百人を殺して滅ぼし、'),
('JPN', '以斯帖记', 17, 9, 7, 'また、パルシャンダタ、ダルフォン、アスパタ、'),
('JPN', '以斯帖记', 17, 9, 8, 'ポラタ、アダルヤ、アリダタ、'),
('JPN', '以斯帖记', 17, 9, 9, 'パルマシュタ、アリサイ、アリダイ、ワイザタを、'),
('JPN', '以斯帖记', 17, 9, 10, 'すなわち、ハメダタの子でユダヤ人を迫害する者ハマンの子、十人を虐殺した。しかし、略奪品には手を出さなかった。'),
('JPN', '以斯帖记', 17, 9, 11, 'その日、スサの城で殺された者の数が王に報告されると、'),
('JPN', '以斯帖记', 17, 9, 12, '王は王妃エステルに言った。「ユダヤ人はスサの城で、五百人とハマンの息子十人を殺して滅ぼした。王のほかの諸州では、彼らはどうしたであろう。ところで、あなたは何を願っているのか。それを授けてやろう。あなたのさらなる望みは何か。それをかなえてやろう。」'),
('JPN', '以斯帖记', 17, 9, 13, 'エステルは答えた。「もしも王様がよろしければ、明日も、スサにいるユダヤ人に、今日の法令どおりにすることをお許しください。そして、ハマンの息子十人を柱にかけてください。」'),
('JPN', '以斯帖记', 17, 9, 14, 'そこで王は、そのように実施するように命じた。法令がスサで布告され、ハマンの息子十人は柱にかけられた。'),
('JPN', '以斯帖记', 17, 9, 15, 'スサにいるユダヤ人はアダルの月の十四日にも集まって、スサで三百人を殺した。しかし、略奪品には手を出さなかった。'),
('JPN', '以斯帖记', 17, 9, 16, '王の諸州にいる残りのユダヤ人たちも団結して、自分たちのいのちを守り、敵からの安息を得た。すなわち、自分たちを憎む者七万五千人を殺した。しかし、略奪品には手を出さなかった。'),
('JPN', '以斯帖记', 17, 9, 17, 'これはアダルの月の十三日のことであり、その十四日に彼らは休んで、その日を祝宴と喜びの日とした。'),
('JPN', '以斯帖记', 17, 9, 18, 'しかし、スサにいるユダヤ人たちは、その月の十三日にも十四日にも集まり、十五日には休んで、その日を祝宴と喜びの日とした。'),
('JPN', '以斯帖记', 17, 9, 19, 'それで、城壁のない村に住む田舎のユダヤ人は、アダルの月の十四日を喜びと祝宴の祝日とし、互いにごちそうを贈り交わす日としている。'),
('JPN', '以斯帖记', 17, 9, 20, 'モルデカイはこれらのことを書いて、クセルクセス王のすべての州の、近い所や遠い所にいる、すべてのユダヤ人に書簡を送った。'),
('JPN', '以斯帖记', 17, 9, 21, 'それは、ユダヤ人が毎年アダルの月の十四日と十五日を、'),
('JPN', '以斯帖记', 17, 9, 22, '自分たちの敵からの安息を得た日、悲しみが喜びに、喪が祝いの日に変わった月として、祝宴と喜びの日、互いにごちそうを贈り交わし、貧しい人々に贈り物をする日と定めるためであった。'),
('JPN', '以斯帖记', 17, 9, 23, 'ユダヤ人は、すでに守り始めていたことであるが、モルデカイが彼らに書き送ったことを受け入れた。'),
('JPN', '以斯帖记', 17, 9, 24, '実に、アガグ人ハメダタの子で、ユダヤ人すべてを迫害する者ハマンは、ユダヤ人を滅ぼそうと企んで、プル、すなわちくじによって決め、彼らをかき乱して滅ぼそうとしたが、'),
('JPN', '以斯帖记', 17, 9, 25, 'そのことが王の耳に入ったときに、王は書簡で命じ、ハマンがユダヤ人に対して企んだ悪い計略をハマンの頭上に返し、彼とその子らを柱にかけたのであった。'),
('JPN', '以斯帖记', 17, 9, 26, 'こういうわけで、ユダヤ人はプルの名にちなんで、これらの日をプリムと呼んだ。こうして、この書簡のすべてのことばにより、また、このことについて彼らが見たこと、また彼らに起こったことにより、'),
('JPN', '以斯帖记', 17, 9, 27, 'ユダヤ人は、自分たちとその子孫、および自分たちにつく者たちが、その文書のとおりに毎年定まった時期にこの両日を守り行い、これを廃止してはならないと定めた。'),
('JPN', '以斯帖记', 17, 9, 28, 'また、この両日は代々にわたり、すべての家族、諸州、町々において記念され、祝われなければならないとし、これらのプリムの日がユダヤ人の間で廃止されることがなく、この記憶が自分たちの子孫の中で途絶えてしまわないようにした。'),
('JPN', '以斯帖记', 17, 9, 29, 'アビハイルの娘である王妃エステルと、ユダヤ人モルデカイは、プリムについてのこの第二の書簡を全権をもって書き記し、確かなものとした。'),
('JPN', '以斯帖记', 17, 9, 30, 'この書簡は、平和と誠実のことばをもって、クセルクセスの王国の百二十七州にいるすべてのユダヤ人に送られ、'),
('JPN', '以斯帖记', 17, 9, 31, 'ユダヤ人モルデカイと王妃エステルがユダヤ人に命じたとおり、また、ユダヤ人が自分たちとその子孫のために、断食と哀悼に関して定めたとおり、このプリムの両日を定まった時期に守るようにした。'),
('JPN', '以斯帖记', 17, 9, 32, 'エステルの命令はこのプリムに関する事柄を義務づけ、書物に記された。'),
('JPN', '以斯帖记', 17, 10, 1, 'クセルクセス王は本土と海の島々に苦役を課した。'),
('JPN', '以斯帖记', 17, 10, 2, '彼の権威と勇気によるすべての功績、王に重んじられたモルデカイの偉大さについての詳細、それは『メディアとペルシアの王の歴代誌』に確かに記されている。'),
('JPN', '以斯帖记', 17, 10, 3, '実に、ユダヤ人モルデカイはクセルクセス王の次の位にあって、ユダヤ人にとっては大いなる者であり、多くの同胞たちに敬愛された。彼は自分の民の幸福を求め、自分の全民族に平和を語る者であった。'),
('JPN', '约伯记', 18, 1, 1, 'ウツの地に、その名をヨブという人がいた。この人は誠実で直ぐな心を持ち、神を恐れて悪から遠ざかっていた。'),
('JPN', '约伯记', 18, 1, 2, '彼に七人の息子と三人の娘が生まれた。'),
('JPN', '约伯记', 18, 1, 3, '彼は羊七千匹、らくだ三千頭、牛五百くびき、雌ろば五百頭、それに非常に多くのしもべを所有していた。この人は東の人々の中で一番の有力者であった。'),
('JPN', '约伯记', 18, 1, 4, '彼の息子たちは互いに行き来し、それぞれ自分の順番の日に、家で宴会を開き、人を遣わして彼らの三人の姉妹も招き、よく一緒に食べたり飲んだりしていた。'),
('JPN', '约伯记', 18, 1, 5, '宴会の日が一巡すると、ヨブは彼らを呼び寄せて聖別した。朝早く起きて、彼ら一人ひとりのために、それぞれの全焼のささげ物を献げたのである。ヨブは、「もしかすると、息子たちが罪に陥って、心の中で神を呪ったかもしれない」と思ったからである。ヨブはいつもこのようにしていた。'),
('JPN', '约伯记', 18, 1, 6, 'ある日、神の子らがやって来て、主の前に立った。サタンもやって来て、彼らの中にいた。'),
('JPN', '约伯记', 18, 1, 7, '主はサタンに言われた。「おまえはどこから来たのか。」サタンは主に答えた。「地を行き巡り、そこを歩き回って来ました。」'),
('JPN', '约伯记', 18, 1, 8, '主はサタンに言われた。「おまえは、わたしのしもべヨブに心を留めたか。彼のように、誠実で直ぐな心を持ち、神を恐れて悪から遠ざかっている者は、地上には一人もいない。」'),
('JPN', '约伯记', 18, 1, 9, 'サタンは主に答えた。「ヨブは理由もなく神を恐れているのでしょうか。'),
('JPN', '约伯记', 18, 1, 10, 'あなたが、彼の周り、彼の家の周り、そしてすべての財産の周りに、垣を巡らされたのではありませんか。あなたが彼の手のわざを祝福されたので、彼の家畜は地に増え広がっているのです。'),
('JPN', '约伯记', 18, 1, 11, 'しかし、手を伸ばして、彼のすべての財産を打ってみてください。彼はきっと、面と向かってあなたを呪うに違いありません。」'),
('JPN', '约伯记', 18, 1, 12, '主はサタンに言われた。「では、彼の財産をすべておまえの手に任せる。ただし、彼自身には手を伸ばしてはならない。」そこで、サタンは主の前から出て行った。'),
('JPN', '约伯记', 18, 1, 13, 'ある日、彼の息子、娘たちが、一番上の兄の家で食べたりぶどう酒を飲んだりしていたとき、'),
('JPN', '约伯记', 18, 1, 14, '一人の使者がヨブのところにやって来て言った。「牛が耕し、そのそばでろばが草を食べていると、'),
('JPN', '约伯记', 18, 1, 15, 'シェバ人が襲いかかってこれを奪い取り、若い者たちを剣の刃で打ち殺しました。私一人だけが逃れて、あなたに知らせに参りました。」'),
('JPN', '约伯记', 18, 1, 16, 'この者がまだ話している間に、もう一人が来て言った。「神の火が天から下って、羊と若い者たちを焼き滅ぼしました。私一人だけが逃れて、あなたに知らせに参りました。」'),
('JPN', '约伯记', 18, 1, 17, 'この者がまだ話している間に、もう一人が来て言った。「カルデア人が三組になって、らくだを襲い、これを奪い取り、若い者たちを剣の刃で打ち殺しました。私一人だけが逃れて、あなたに知らせに参りました。」'),
('JPN', '约伯记', 18, 1, 18, 'この者がまだ話している間に、もう一人が来て言った。「あなたのご子息やお嬢さんたちは、一番上のお兄さんの家で食べたりぶどう酒を飲んだりしておられました。'),
('JPN', '约伯记', 18, 1, 19, 'そこへ荒野の方から大風が吹いて来て、家の四隅を打ち、それがお若い方々の上に倒れたので、皆様亡くなられました。私一人だけが逃れて、あなたに知らせに参りました。」'),
('JPN', '约伯记', 18, 1, 20, 'このとき、ヨブは立ち上がって上着を引き裂き、頭を剃り、地にひれ伏して礼拝し、'),
('JPN', '约伯记', 18, 1, 21, 'そして言った。「私は裸で母の胎から出て来た。また裸でかしこに帰ろう。主は与え、主は取られる。主の御名はほむべきかな。」'),
('JPN', '约伯记', 18, 1, 22, 'ヨブはこれらすべてのことにおいても、罪に陥ることなく、神に対して愚痴をこぼすようなことはしなかった。'),
('JPN', '约伯记', 18, 2, 1, 'ある日、神の子らがやって来て、主の前に立った。サタンも彼らの中にやって来て、主の前に立った。'),
('JPN', '约伯记', 18, 2, 2, '主はサタンに言われた。「おまえはどこから来たのか。」サタンは主に答えた。「地を行き巡り、そこを歩き回って来ました。」'),
('JPN', '约伯记', 18, 2, 3, '主はサタンに言われた。「おまえはわたしのしもべヨブに心を留めたか。彼のように、誠実で直ぐな心を持ち、神を恐れて悪から遠ざかっている者は、地上には一人もいない。彼はなお、自分の誠実さを堅く保っている。おまえは、わたしをそそのかして彼に敵対させ、理由もなく彼を吞み尽くそうとしたが。」'),
('JPN', '约伯记', 18, 2, 4, 'サタンは主に答えた。「皮の代わりは、皮をもってします。自分のいのちの代わりには、人は財産すべてを与えるものです。'),
('JPN', '约伯记', 18, 2, 5, 'しかし、手を伸ばして、彼の骨と肉を打ってみてください。彼はきっと、面と向かってあなたを呪うに違いありません。」'),
('JPN', '约伯记', 18, 2, 6, '主はサタンに言われた。「では、彼をおまえの手に任せる。ただ、彼のいのちには触れるな。」'),
('JPN', '约伯记', 18, 2, 7, 'サタンは主の前から出て行き、ヨブを足の裏から頭の頂まで、悪性の腫物で打った。'),
('JPN', '约伯记', 18, 2, 8, 'ヨブは土器のかけらを取り、それでからだを引っかいた。彼は灰の中に座っていた。'),
('JPN', '约伯记', 18, 2, 9, 'すると、妻が彼に言った。「あなたは、これでもなお、自分の誠実さを堅く保とうとしているのですか。神を呪って死になさい。」'),
('JPN', '约伯记', 18, 2, 10, 'しかし、彼は妻に言った。「あなたは、どこかの愚かな女が言うようなことを言っている。私たちは幸いを神から受けるのだから、わざわいも受けるべきではないか。」ヨブはこのすべてのことにおいても、唇によって罪に陥ることはなかった。'),
('JPN', '约伯记', 18, 2, 11, 'さて、ヨブの三人の友が、ヨブに降りかかったこれらすべてのわざわいのことを聞き、それぞれ自分のところから訪ねて来た。すなわち、テマン人エリファズ、シュアハ人ビルダデ、ナアマ人ツォファルである。彼らはヨブに同情し、慰めようと、互いに打ち合わせて来た。'),
('JPN', '约伯记', 18, 2, 12, '彼らは遠くから目を上げて彼を見たが、それがヨブであることが見分けられなかった。彼らは声をあげて泣き、それぞれ自分の上着を引き裂き、ちりを天に向かって投げ、自分の頭の上にまき散らした。'),
('JPN', '约伯记', 18, 2, 13, '彼らは彼とともに七日七夜、地に座っていたが、だれも一言も彼に話しかけなかった。彼の痛みが非常に大きいのを見たからである。'),
('JPN', '约伯记', 18, 3, 1, 'そのようなことがあった後、ヨブは口を開いて自分の生まれた日を呪った。'),
('JPN', '约伯记', 18, 3, 2, 'ヨブは言った。'),
('JPN', '约伯记', 18, 3, 3, '私が生まれた日は滅び失せよ。「男の子が胎に宿った」と告げられたその夜も。'),
('JPN', '约伯记', 18, 3, 4, 'その日は闇になれ。神も上からその日を顧みるな。光もその上を照らすな。'),
('JPN', '约伯记', 18, 3, 5, '闇と暗黒がその日を取り戻し、雲がその上にとどまれ。昼を薄暗くするものも、その日を脅かせ。'),
('JPN', '约伯记', 18, 3, 6, 'その夜は、暗闇が奪い取るように。その日は、年の日々のうちで喜ばないように。月の日数のうちにも入れないように。'),
('JPN', '约伯记', 18, 3, 7, '見よ、その夜は不妊となるように。その夜には喜びの声も起こらないように。'),
('JPN', '约伯记', 18, 3, 8, '日を呪う者たちが、レビヤタンを巧みに呼び起こす者たちが、その日に呪いをかけるように。'),
('JPN', '约伯记', 18, 3, 9, 'その夜明けの星は暗くなれ。光を待っても、それはなく、暁のまばたきを見ることがないように。'),
('JPN', '约伯记', 18, 3, 10, 'その日が、私をはらんだ胎の戸を閉ざさず、私の目から労苦を隠してくれなかったからだ。'),
('JPN', '约伯记', 18, 3, 11, 'なぜ私は、胎内で死ななかったのか。胎を出たとき、息絶えなかったのか。'),
('JPN', '约伯记', 18, 3, 12, 'なにゆえ、両膝が私を受けとめたのか。乳房があって、私がそれを吸ったのか。'),
('JPN', '约伯记', 18, 3, 13, '今ごろ私は安らかに横になり、眠って安らいでいただろうに。'),
('JPN', '约伯记', 18, 3, 14, '自分たちのためにあの廃墟を築いた王たち、地の指導者たちと一緒に。'),
('JPN', '约伯记', 18, 3, 15, '黄金を持ち、自分の家を銀で満たした首長たちと一緒に。'),
('JPN', '约伯记', 18, 3, 16, 'なぜ私は、ひそかに堕ろされた死産の子、光を見なかった嬰児のようにならなかったのか。'),
('JPN', '约伯记', 18, 3, 17, 'かしこでは、悪しき者は荒れ狂うのをやめ、かしこでは、力の萎えた者は憩い、'),
('JPN', '约伯记', 18, 3, 18, '捕らわれ人たちもみな、ともに安らかで、激しく追い立てる者の声も聞こえない。'),
('JPN', '约伯记', 18, 3, 19, 'かしこでは、下の者も上の者も同じで、奴隷も主人から解き放たれている。'),
('JPN', '约伯记', 18, 3, 20, 'なぜ、苦悩する者に光が、心の痛んだ者にいのちが与えられるのか。'),
('JPN', '约伯记', 18, 3, 21, '彼らは死を待つが、死はやって来ない。隠された宝にまさって死を探し求めても。'),
('JPN', '约伯记', 18, 3, 22, '彼らは墓を見出したときに、歓声をあげて喜び楽しむ。'),
('JPN', '约伯记', 18, 3, 23, '自分の道が隠されている人、神が囲いに閉じ込めた人になぜ光が与えられるのか。'),
('JPN', '约伯记', 18, 3, 24, 'まことに、食物の代わりに嘆きが私に来て、私のうめきは水のようにあふれ出る。'),
('JPN', '约伯记', 18, 3, 25, '私がおびえていたもの、それが私を襲い、私が恐れていたもの、それが降りかかったからだ。'),
('JPN', '约伯记', 18, 3, 26, '安らぎもなく、休みもなく、憩いもなく、心は乱れている。'),
('JPN', '约伯记', 18, 4, 1, 'すると、テマン人エリファズが話し始めた。'),
('JPN', '约伯记', 18, 4, 2, 'もし、人があなたにことばを投げかけたら、あなたはそれに耐えられるか。しかし、だれが語らないでいられるだろう。'),
('JPN', '约伯记', 18, 4, 3, '見よ。あなたは多くの人を訓戒し、弱った手を力づけてきた。'),
('JPN', '约伯记', 18, 4, 4, 'あなたのことばは、つまずいた者を起こし、くずおれる膝をしっかりさせてきた。'),
('JPN', '约伯记', 18, 4, 5, 'しかし今、これがあなたに及ぶと、あなたはそれに耐えられない。これがあなたに至ると、あなたはおじ惑う。'),
('JPN', '约伯记', 18, 4, 6, 'あなたの敬虔さは、あなたの確信ではないか。あなたの誠実さは、あなたの望みではないか。'),
('JPN', '约伯记', 18, 4, 7, 'さあ、思い出せ。だれか、潔白なのに滅びた者があるか。どこに、真っ直ぐなのに絶たれた者があるか。'),
('JPN', '约伯记', 18, 4, 8, '私の見てきたところでは、不法を耕して害悪を蒔く者が、自らそれらを刈り取るのだ。'),
('JPN', '约伯记', 18, 4, 9, '彼らは神の息吹によって滅び、御怒りの息によって消え失せる。'),
('JPN', '约伯记', 18, 4, 10, '獅子のうなり声、たける獅子の声がする。しかし、若獅子の牙は砕かれる。'),
('JPN', '约伯记', 18, 4, 11, '雄獅子は獲物がなくて滅び、雌獅子の子らは散っていく。'),
('JPN', '约伯记', 18, 4, 12, 'あることばが私に忍び寄り、そのささやきを私の耳がとらえた。'),
('JPN', '约伯记', 18, 4, 13, '夜の幻で思いが乱れ、深い眠りが人々を襲うとき、'),
('JPN', '约伯记', 18, 4, 14, 'おののきと震えが私に降りかかり、私の骨々の多くがわなないた。'),
('JPN', '约伯记', 18, 4, 15, 'ある霊が顔の上を通り過ぎ、私は身の毛がよだった。'),
('JPN', '约伯记', 18, 4, 16, 'それは立ち止まったが、私はその顔だちを見分けられなかった。しかし、その姿は私の目の前にあった。静寂。そして私は次のような声を聞いた。'),
('JPN', '约伯记', 18, 4, 17, '「人は神の前に正しくあり得ようか。その造り主の前にきよくあり得ようか。'),
('JPN', '约伯记', 18, 4, 18, '見よ。神はご自分のしもべさえ信頼せず、御使いたちのうちにさえ、誤りを認められる。'),
('JPN', '约伯记', 18, 4, 19, 'まして、ちりに土台を据えた泥の家に住む者はなおさらのこと。彼らはシミよりもたやすく押しつぶされ、'),
('JPN', '约伯记', 18, 4, 20, '朝から夕方まで打ち砕かれ、永久に滅ぼされて、だれも顧みない。'),
('JPN', '约伯记', 18, 4, 21, '彼らの天幕の綱は確かに取り去られる。彼らは知恵がないために死ぬ。」'),
('JPN', '约伯记', 18, 5, 1, 'さあ、呼んでみよ。だれかあなたに答える者はいるか。聖なる者のうちのだれのところにあなたは向かうのか。'),
('JPN', '约伯记', 18, 5, 2, '苛立ちは愚か者を殺し、ねたみは浅はかな者を死なせる。'),
('JPN', '约伯记', 18, 5, 3, '私は愚か者が根を張るのを見て、ただちにその住まいを呪った。'),
('JPN', '约伯记', 18, 5, 4, 'その子たちは安全からはほど遠く、門で押しつぶされても、救い出す者もいない。'),
('JPN', '约伯记', 18, 5, 5, '愚か者が刈り入れた物は、飢えた人が食べ、茨の中からさえそれを奪う。渇いた人たちが彼らの富をあえぎ求める。'),
('JPN', '约伯记', 18, 5, 6, 'まことに、不幸はちりから出て来ることはなく、労苦は土から生え出ることはない。'),
('JPN', '约伯记', 18, 5, 7, 'まことに、人は労苦のために生まれる。火花が上に向かって飛ぶように。'),
('JPN', '约伯记', 18, 5, 8, '私なら、神に尋ね、神に向かって自分のことを訴えるだろう。'),
('JPN', '约伯记', 18, 5, 9, '神は、測り知れない大いなることをなし、数えきれない奇しいみわざを行われる。'),
('JPN', '约伯记', 18, 5, 10, '地の上に雨を降らせ、野の面に水を送られる。'),
('JPN', '约伯记', 18, 5, 11, '神は低い者を高く上げ、嘆き悲しむ者は安全なところに引き上げられる。'),
('JPN', '约伯记', 18, 5, 12, '神は悪賢い者たちの企みを打ち砕かれ、彼らの手は良い成果を得られない。'),
('JPN', '约伯记', 18, 5, 13, '神は知恵のある者を、彼ら自身の悪巧みによって捕らえ、彼らのねじれたはかりごとは突然終わる。'),
('JPN', '约伯记', 18, 5, 14, '彼らは昼間に闇と出会い、真昼でも、夜のように手探りする。'),
('JPN', '约伯记', 18, 5, 15, '神は貧しい者を剣から、剣の刃から、強い者の手から救われる。'),
('JPN', '约伯记', 18, 5, 16, 'こうして弱い者は望みを抱き、不正は口をつぐむ。'),
('JPN', '约伯记', 18, 5, 17, 'ああ、幸いなことよ、神が叱責するその人は。だから、全能者の訓戒を拒んではならない。'),
('JPN', '约伯记', 18, 5, 18, '神は傷つけるが、その傷を包み、打ち砕くが、御手で癒やしてくださるからだ。'),
('JPN', '约伯记', 18, 5, 19, '六つの苦しみから、神はあなたを救い出し、七つの中でも、わざわいはあなたに触れない。'),
('JPN', '约伯记', 18, 5, 20, '飢饉のときには、あなたを死から、戦いのときには、剣の力から贖い出す。'),
('JPN', '约伯记', 18, 5, 21, '舌のむちで打たれるときも、あなたは隠され、破壊がやって来ても、恐れることはない。'),
('JPN', '约伯记', 18, 5, 22, 'あなたは破壊と飢饉をあざ笑い、地の獣をさえ恐れることはない。'),
('JPN', '约伯记', 18, 5, 23, '野の石とあなたは契りを結び、野の獣があなたと和らぐからだ。'),
('JPN', '约伯记', 18, 5, 24, 'あなたは自分の天幕が安全であるのを知り、自分の牧場を見回っても、何も失っていない。'),
('JPN', '约伯记', 18, 5, 25, 'あなたは自分の子孫、自分の末裔が、地の青草のように増えるのを知る。'),
('JPN', '约伯记', 18, 5, 26, 'あなたは長寿を全うして墓に入る。あたかも麦束が、時が来ると収められるように。'),
('JPN', '约伯记', 18, 5, 27, 'さあ、私たちが調べ上げたことはこのとおりだ。これを聞き、自分自身でこれを知れ。'),
('JPN', '约伯记', 18, 6, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 6, 2, 'ああ、私の苦悶の重さが量られ、私の破滅が、ともに秤にかけられたらよいのに。'),
('JPN', '约伯记', 18, 6, 3, 'きっと海の砂よりも重いだろう。だから、私のことばは激しかったのだ。'),
('JPN', '约伯记', 18, 6, 4, 'まことに、全能者の矢が私に刺さり、その毒を私の霊が飲み、神の脅威が私に対して準備されている。'),
('JPN', '约伯记', 18, 6, 5, '野ろばが若草の上で鳴くだろうか。雄牛が飼葉の上でうなるだろうか。'),
('JPN', '约伯记', 18, 6, 6, '味のない物は塩なしに食べられるだろうか。卵の白身に味があるだろうか。'),
('JPN', '约伯记', 18, 6, 7, '私の喉はそれを受けつけない。それらは私には腐った食物のようだ。'),
('JPN', '约伯记', 18, 6, 8, 'ああ、私の願いがかなえられ、私が望むものを神が下さるとよいのに。'),
('JPN', '约伯记', 18, 6, 9, '神が望むままに私を砕き、御手を伸ばして私を絶たれるのであれば、'),
('JPN', '约伯记', 18, 6, 10, 'それはなおも私にとって慰めであり、容赦ない激痛の中でも、私は小躍りして喜ぶ。私は聖なる方のことばを、拒んだことはない。'),
('JPN', '约伯记', 18, 6, 11, '私にどんな力があるのだろうか。私が待たなければならないとは。どんな終わりがあるのだろうか。耐え忍ばなければならないとは。'),
('JPN', '约伯记', 18, 6, 12, '私の力は石の力なのか。私の肉は青銅なのか。'),
('JPN', '约伯记', 18, 6, 13, '私のうちには何の助けもないではないか。すぐれた知性は、私から取り払われている。'),
('JPN', '约伯记', 18, 6, 14, '落胆している者には、友からの友情を。さもないと、全能者への恐れを捨てるだろう。'),
('JPN', '约伯记', 18, 6, 15, '兄弟たちは水無し川のように私を裏切った。流れが去る川床のように。'),
('JPN', '约伯记', 18, 6, 16, 'それは氷で黒ずみ、雪で隠される。'),
('JPN', '约伯记', 18, 6, 17, '炎天のころには、流れがなくなり、暑くなるとその場所から消える。'),
('JPN', '约伯记', 18, 6, 18, '隊商はその道筋からそれ、荒れ地に上って滅びる。'),
('JPN', '约伯记', 18, 6, 19, 'テマの隊商はこれを目印とし、シェバの旅人はこれに望みをかける。'),
('JPN', '约伯记', 18, 6, 20, '彼らはこれに頼ったために恥を見、そこまでやって来て、辱めを受ける。'),
('JPN', '约伯记', 18, 6, 21, '今や、あなたがたはそのようになった。あなたがたは恐ろしいことを見ておびえている。'),
('JPN', '约伯记', 18, 6, 22, '私が言ったことがあるか。「私に贈り物をせよ」と。「あなたがたの財産の中から私のために賄賂を贈れ」と。'),
('JPN', '约伯记', 18, 6, 23, 'あるいは「敵の手から私を救い出せ。横暴な者たちの手から私を贖い出せ」と。'),
('JPN', '约伯记', 18, 6, 24, '私に教えよ。そうすれば、私は黙ろう。私がどのように迷い出たのか、私に悟らせよ。'),
('JPN', '约伯记', 18, 6, 25, '真っ直ぐなことばは、なんと痛いことか。あなたがたは自分で何を責め立てているのか。'),
('JPN', '约伯记', 18, 6, 26, 'ことばで私を責めるつもりか。絶望している者のことばを、風と見なすつもりか。'),
('JPN', '约伯记', 18, 6, 27, 'あなたがたは、みなしごをくじで分け合い、自分の友さえ売りに出す。'),
('JPN', '约伯记', 18, 6, 28, '今、ぜひ、私の方に顔を向けてくれ。あなたがたの顔に向かって私は決してまやかしを言わない。'),
('JPN', '约伯记', 18, 6, 29, '思い直してくれ。不正があってはならない。思い直してくれ。私の正しさが問われているのだ。'),
('JPN', '约伯记', 18, 6, 30, '私の舌に不正があるだろうか。私の口は破滅を見極められないだろうか。'),
('JPN', '约伯记', 18, 7, 1, '地上の人間には苦役があるではないか。その日々は日雇い人の日々のようではないか。'),
('JPN', '约伯记', 18, 7, 2, '日陰をあえぎ求める奴隷のように、賃金を待ち焦がれる日雇い人のように、'),
('JPN', '约伯记', 18, 7, 3, 'そのように、私には徒労の月日が割り当てられ、労苦の夜が定められている。'),
('JPN', '约伯记', 18, 7, 4, '私は横になるときに言う。「いつ起き上がれるだろうか」と。夜は長く、私は夜明けまで寝返りを打ち続ける。'),
('JPN', '约伯记', 18, 7, 5, '私の肉は、うじ虫と土くれをまとい、皮膚は固まっては、また崩れる。'),
('JPN', '约伯记', 18, 7, 6, '私の日々は機の杼よりも速く、望みのないままに終わる。'),
('JPN', '约伯记', 18, 7, 7, '心に留めてください。私のいのちが息にすぎないことを。私の目は、再び幸いを見ることはありません。'),
('JPN', '约伯记', 18, 7, 8, '私を見る人の目は、もう私を認めることはありません。あなたが私に目を留められても、私はもういません。'),
('JPN', '约伯记', 18, 7, 9, '雲は消え去ります。そのように、よみに下る者は上っては来ません。'),
('JPN', '约伯记', 18, 7, 10, 'その人はもう自分の家には帰れず、彼の家も、もう彼のことが分かりません。'),
('JPN', '约伯记', 18, 7, 11, 'ですから、私も自分の口を制することをせず、霊の苦しみの中で語り、たましいの苦悩の中で嘆きます。'),
('JPN', '约伯记', 18, 7, 12, '私は海でしょうか、それとも竜でしょうか。あなたが私の上に見張りを置かれるとは。'),
('JPN', '约伯记', 18, 7, 13, '寝台が私を慰め、寝床が嘆きを負ってくれると私が思っても、'),
('JPN', '约伯记', 18, 7, 14, 'あなたは、いくつもの夢で私をおののかせ、幻によって私をおびえさせます。'),
('JPN', '约伯记', 18, 7, 15, '私のたましいは窒息を、私のからだではなく死を選びます。'),
('JPN', '约伯记', 18, 7, 16, 'もういやです。いつまでも生きたくありません。かまわないでください。私の日々は空しいものです。'),
('JPN', '约伯记', 18, 7, 17, '人とは何ものなのでしょう。あなたがこれを尊び、これに心を留められるとは。'),
('JPN', '约伯记', 18, 7, 18, '朝ごとにこれを訪れ、その都度これを試されるとは。'),
('JPN', '约伯记', 18, 7, 19, 'いつまで私から目をそらしてくださらないのですか。唾を飲み込む間も、私を放っておいてくださらないのですか。'),
('JPN', '约伯记', 18, 7, 20, '私が罪ある者だとしても、人を見張るあなたに、私は何ができるでしょう。どうしてあなたは、私を標的とされるのですか。私は、自らを重荷としなければならないのですか。'),
('JPN', '约伯记', 18, 7, 21, 'どうして、あなたは私の背きを赦さず、私の咎を取り去ってくださらないのですか。私が今も、ちりに横たわらなければならないとは。あなたが私を捜しても、私はもういません。'),
('JPN', '约伯记', 18, 8, 1, '次に、シュアハ人ビルダデが答えた。'),
('JPN', '约伯记', 18, 8, 2, 'いつまで、あなたはこのようなことを語るのか。あなたが口にすることばは激しい風だ。'),
('JPN', '约伯记', 18, 8, 3, '神がさばきを曲げられるだろうか。全能者が義を曲げられるだろうか。'),
('JPN', '约伯记', 18, 8, 4, 'もし、あなたの子らが神の前に罪ある者となり、神が彼らをその背きの手に渡されても、'),
('JPN', '约伯记', 18, 8, 5, 'もし、あなたが熱心に神に求め、全能者にあわれみを乞うなら、'),
('JPN', '约伯记', 18, 8, 6, 'もし、あなたが純粋で真っ直ぐなら、今すぐ神はあなたのために奮い立ち、あなたの義の住まいを回復されるだろう。'),
('JPN', '约伯记', 18, 8, 7, 'あなたの始まりは小さくても、あなたの終わりは、きわめて大きなものとなる。'),
('JPN', '约伯记', 18, 8, 8, 'さあ、先人に尋ねよ。先祖たちの探究したことを確かめよ。'),
('JPN', '约伯记', 18, 8, 9, '私たちは昨日からの者で、何も知らない。私たちの地上の日々は影にすぎないのだ。'),
('JPN', '约伯记', 18, 8, 10, '彼らはあなたに教え、あなたに語りかけ、その心からことばを発しないだろうか。'),
('JPN', '约伯记', 18, 8, 11, 'パピルスは沼地がなくても育つだろうか。葦は水がなくても伸びるだろうか。'),
('JPN', '约伯记', 18, 8, 12, 'まだ若芽のときに、引き抜かれもしないのに、ほかの草に先立って枯れる。'),
('JPN', '约伯记', 18, 8, 13, 'すべて神を忘れる者の道はこのようだ。神を敬わない者の望みは消え失せる。'),
('JPN', '约伯记', 18, 8, 14, 'その人の確信は、か細いクモの糸、その信頼はクモの巣だ。'),
('JPN', '约伯记', 18, 8, 15, '自分の家に寄りかかると、家はそれに耐えきれない。これにすがりついても、それは持ちこたえない。'),
('JPN', '约伯记', 18, 8, 16, '神を敬わない者は日に当たって青々と茂り、その若枝は庭に生え出る。'),
('JPN', '约伯记', 18, 8, 17, 'その根は石塚に絡まり、石造りの家に生え広がる。'),
('JPN', '约伯记', 18, 8, 18, 'しかし、彼がその場所から取り除かれるなら、その場所は、彼を見たことがない、とうそぶく。'),
('JPN', '约伯记', 18, 8, 19, '見よ、これこそが彼の道の喜びである。その土からは、ほかのものが生え出る。'),
('JPN', '约伯记', 18, 8, 20, '見よ。神は誠実な人を退けることはなく、悪を行う者の手を取ることはない。'),
('JPN', '约伯记', 18, 8, 21, '神は、ついには笑いをあなたの口に、喜びの叫びをあなたの唇に満たされる。'),
('JPN', '约伯记', 18, 8, 22, 'あなたを憎む者は恥を身にまとい、悪しき者の天幕はなくなる。'),
('JPN', '约伯记', 18, 9, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 9, 2, 'そのとおりであることを、私は確かに知っている。しかし、人はどのようにして、神の前に正しくあり得るのか。'),
('JPN', '约伯记', 18, 9, 3, 'たとえ、神と言い争いたいと思っても、千に一つも答えられないだろう。'),
('JPN', '约伯记', 18, 9, 4, '神は心に知恵のある方、力の強い方。この神に対して頑なになって、だれが、そのままですむだろうか。'),
('JPN', '约伯记', 18, 9, 5, '神は山々を移されるが、山々は気づかない。神は怒って、それらをくつがえされる。'),
('JPN', '约伯记', 18, 9, 6, '神が地をその基で震わせられると、その柱は揺れ動く。'),
('JPN', '约伯记', 18, 9, 7, '太陽にお命じになると、それは昇らず、星もまた封じ込められる。'),
('JPN', '约伯记', 18, 9, 8, '神はただひとりで天を延べ広げ、海の大波を踏みつけられる。'),
('JPN', '约伯记', 18, 9, 9, '神は牡牛座、オリオン座、すばる、それに南の天の間を造られた。'),
('JPN', '约伯记', 18, 9, 10, '大いなることをなさって測り知れず、その奇しいみわざは数えきれない。'),
('JPN', '约伯记', 18, 9, 11, '神がそばを通り過ぎても、私には見えない。進んで行っても、気づかない。'),
('JPN', '约伯记', 18, 9, 12, 'ああ、神が奪い取ろうとされるとき、だれがそれを引き止められるだろうか。だれが神に向かって、「何をするのか」と言えるだろうか。'),
('JPN', '约伯记', 18, 9, 13, '神は御怒りを翻されない。ラハブの仲間も、神のみもとに身をかがめる。'),
('JPN', '约伯记', 18, 9, 14, 'まして、この私が神に答えられるだろうか。神と交わすべきことばを私が選べるだろうか。'),
('JPN', '约伯记', 18, 9, 15, 'たとえ私が正しくても、答えることはできない。私をさばく方に対して、あわれみを乞うだけだ。'),
('JPN', '约伯记', 18, 9, 16, '私が呼び、私に答えてくださったとしても、神が私の声に耳を傾けられるとは、信じられない。'),
('JPN', '约伯记', 18, 9, 17, '神は嵐をもって私を傷つけ、理由もなく傷を増し加え、'),
('JPN', '约伯记', 18, 9, 18, '私に息もつかせず、私を苦しみで満たされる。'),
('JPN', '约伯记', 18, 9, 19, 'もし、力のことなら、見よ、神は強い。もし、さばきのことなら、だれが私を呼び出すのか。'),
('JPN', '约伯记', 18, 9, 20, 'たとえ私が正しくても、私自身の口が私を不義に定める。たとえ私が誠実でも、神は私を曲がった者とされる。'),
('JPN', '约伯记', 18, 9, 21, '私は誠実だ。しかし私には自分が分からない。私は自分のいのちを憎む。'),
('JPN', '约伯记', 18, 9, 22, 'みな同じことだ。だから私は言う。神は誠実な者も悪い者も、ともに絶ち滅ぼされると。'),
('JPN', '约伯记', 18, 9, 23, '突然、にわか水が出て人を死なせると、神は潔白な者の受ける試練を嘲られる。'),
('JPN', '约伯记', 18, 9, 24, '地は悪しき者の手に委ねられ、神は地のさばき人らの顔をおおわれる。神がなさるのでなければ、だれがそうするのか。'),
('JPN', '约伯记', 18, 9, 25, '私の日々は飛脚よりも速い。それは飛び去って、幸せを見ることはない。'),
('JPN', '约伯记', 18, 9, 26, 'それは葦の舟のように通り過ぎる。獲物をめがけて舞い降りる鷲のように。'),
('JPN', '约伯记', 18, 9, 27, 'たとえ「不平を忘れ、悲しい顔を捨てて明るくふるまいたい」と私が言っても、'),
('JPN', '约伯记', 18, 9, 28, '自分のあらゆる苦痛に私はおびえています。私はよく知っています。あなたが私を潔白な者となさらないことを。'),
('JPN', '约伯记', 18, 9, 29, '私はきっと、悪しき者とされるでしょう。なぜ私は、空しく労するのでしょうか。'),
('JPN', '约伯记', 18, 9, 30, 'たとえ私が雪の水で身を洗っても、灰汁で手を清めても、'),
('JPN', '约伯记', 18, 9, 31, 'あなたは私を墓の穴に沈め、私が着る服は私を忌み嫌います。'),
('JPN', '约伯记', 18, 9, 32, '神は、私のように人間ではありません。その方に、私が応じることができるでしょうか。「さあ、さばきの座に一緒に行きましょう」と。'),
('JPN', '约伯记', 18, 9, 33, '私たち二人の上に手を置く仲裁者が、私たちの間にはいません。'),
('JPN', '约伯记', 18, 9, 34, '神がその杖を私から取り去り、その恐ろしさが私をおびえさせませんように。'),
('JPN', '约伯记', 18, 9, 35, 'そうなれば、私は恐れず神に語りかけます。しかし今、私はそうではありません。'),
('JPN', '约伯记', 18, 10, 1, '私のたましいはいのちを忌み嫌う。私は不平をぶちまけ、たましいの苦しみのうちに私は語ろう。'),
('JPN', '约伯记', 18, 10, 2, '私は神にこう言おう。「私を不義に定めないでください。何のために私と争われるのかを教えてください。'),
('JPN', '约伯记', 18, 10, 3, 'あなたが人を虐げ、御手の労苦の実を蔑み、悪しき者たちのはかりごとに光を添えることは、あなたにとって良いことでしょうか。'),
('JPN', '约伯记', 18, 10, 4, 'あなたには肉の目があるのですか。あなたは人間が見るように見られるのですか。'),
('JPN', '约伯记', 18, 10, 5, 'あなたの日々は人間の日々のようなのですか。あなたの年は人の年のようなのですか。'),
('JPN', '约伯记', 18, 10, 6, 'それで、私の咎を探し出し、私の罪を探り出されるのですか。'),
('JPN', '约伯记', 18, 10, 7, '私に悪しきことがないこと、あなたの手から救い出せる者がいないことを、あなたはご存じなのに。'),
('JPN', '约伯记', 18, 10, 8, 'あなたの手が私をかたどり、私を造られました。それなのに、私を滅ぼし尽くそうとされます。'),
('JPN', '约伯记', 18, 10, 9, '思い出してください。あなたは私を粘土のようにして造られました。私を土のちりに戻そうとなさるのですか。'),
('JPN', '约伯记', 18, 10, 10, 'あなたは私を乳のように注ぎ出して、チーズのように固め、'),
('JPN', '约伯记', 18, 10, 11, '皮と肉を私に着せて、骨と筋で編まれたではありませんか。'),
('JPN', '约伯记', 18, 10, 12, '恵みをもって私にいのちを与え、あなたの顧みが私の霊を守りました。'),
('JPN', '约伯记', 18, 10, 13, 'しかし、あなたはこれらのことを心に秘めておられました。このことがあなたのうちにあるのを私は知っています。'),
('JPN', '约伯记', 18, 10, 14, 'もし、私が罪ある者となるなら、あなたは私を見張られます。こうして、私の咎を免じてはくださいません。'),
('JPN', '约伯记', 18, 10, 15, 'もし、私が悪しき者とされるのなら、ああ、なんと悲しいことでしょう。私は正しい者とされても、頭を上げることはできません。自分の恥に飽き飽きし、自分の苦しみを見ていますから。'),
('JPN', '约伯记', 18, 10, 16, '頭を上げると、あなたは獅子のように私を狙い、再び私に驚くべき力をふるわれるでしょう。'),
('JPN', '约伯记', 18, 10, 17, 'あなたは私に対して証人たちを新たに立てて、私に向かって苛立ちを増し加え、いよいよ私を苦しめられるでしょう。'),
('JPN', '约伯记', 18, 10, 18, 'なぜ、あなたは私を母の胎から出されたのですか。私が息絶えていたなら、だれの目にも留まらなかったでしょう。'),
('JPN', '约伯记', 18, 10, 19, '私は、存在しなかったかのように、母の胎から墓に運ばれていたらよかったのに。'),
('JPN', '约伯记', 18, 10, 20, '私の生きる日はわずかなのですか。それならやめてください。私にかまわないでください。私はわずかでも明るくふるまいたいのです。'),
('JPN', '约伯记', 18, 10, 21, '私が闇と死の陰の地に行って、再び帰って来なくなる前に。'),
('JPN', '约伯记', 18, 10, 22, 'そこは、暗闇のように真っ暗な地。死の陰があり、秩序がなく、光も暗闇のようです。」'),
('JPN', '约伯记', 18, 11, 1, 'さらに、ナアマ人ツォファルが答えた。'),
('JPN', '约伯记', 18, 11, 2, 'ことば数が多ければ、言い返されないだろうか。人は唇で義とされるのだろうか。'),
('JPN', '约伯记', 18, 11, 3, 'あなたの無駄話は、人を黙らせるだろうか。あなたが嘲るとき、あなたに恥を見させる者はいないのだろうか。'),
('JPN', '约伯记', 18, 11, 4, 'あなたは言う。「私の主張は純粋だ。私はあなたの目に清い」と。'),
('JPN', '约伯记', 18, 11, 5, 'しかし、神が語りかけ、あなたに対して唇を開いてくださっていたなら、'),
('JPN', '约伯记', 18, 11, 6, '神は知恵の奥義をあなたに告げ、知性を倍にしてくださったであろう。知れ。神があなたのために、あなたの咎を忘れてくださることを。'),
('JPN', '约伯记', 18, 11, 7, 'あなたは神の深さを見極められるだろうか。全能者の極みを見出せるだろうか。'),
('JPN', '约伯记', 18, 11, 8, 'それは天よりも高い。あなたに何ができるだろう。それはよみよりも深い。あなたが何を知り得るだろう。'),
('JPN', '约伯记', 18, 11, 9, 'それを測ると、地よりも長く、海よりも広い。'),
('JPN', '约伯记', 18, 11, 10, 'もし、神が通り過ぎたり、閉じ込めたり、あるいは法廷を召集したりするなら、だれが神を引き止められるだろう。'),
('JPN', '约伯记', 18, 11, 11, '確かに神は、不信実な者を知っておられる。不法を見て、それに気づかれないだろうか。'),
('JPN', '约伯记', 18, 11, 12, '無知な人間も賢くなるだろう。野ろばの子が人として生まれるのなら。'),
('JPN', '约伯记', 18, 11, 13, 'もし、あなたが心を定め、神に向かって手を伸べ広げるなら、'),
('JPN', '约伯记', 18, 11, 14, 'もし、手に不法があればそれを遠ざけ、あなたの天幕に不正を住まわせないなら、'),
('JPN', '约伯记', 18, 11, 15, 'そのとき、あなたは欠けのない者として顔を上げることができ、堅く立って恐れることはない。'),
('JPN', '约伯记', 18, 11, 16, 'こうしてあなた自身は労苦を忘れ、これを流れ去った水のように思い出すだろう。'),
('JPN', '约伯记', 18, 11, 17, 'あなたの一生は真昼よりも輝き、闇も朝のようになる。'),
('JPN', '约伯记', 18, 11, 18, '望みがあるので、あなたは安らぎ、守られて安らかに休む。'),
('JPN', '约伯记', 18, 11, 19, '横になっても、あなたを脅かす者はいない。多くの者があなたの好意を求める。'),
('JPN', '约伯记', 18, 11, 20, 'しかし、悪者どもの目は衰え果て、彼らは逃れ場を失う。彼らの望みは、最後の一息にすぎない。'),
('JPN', '约伯记', 18, 12, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 12, 2, 'まさに、あなたがたは地の民。あなたがたとともに知恵も死ぬ。'),
('JPN', '约伯记', 18, 12, 3, '私にも、同じように良識がある。私はあなたがたに劣っていない。これくらいのことを知らない者がいるだろうか。'),
('JPN', '约伯记', 18, 12, 4, '私は、自分の友の笑いものとなっている。神を呼び求め、神が答えてくださった者なのに。正しく誠実な者が笑いものだ。'),
('JPN', '约伯记', 18, 12, 5, '安らかだと思っている者はわざわいを侮る。わざわいは、足がよろめく者に用意されている。'),
('JPN', '约伯记', 18, 12, 6, '荒らす者の天幕には安らぎがあり、神を怒らせる者は安らかだ。神がご自分の手でそうさせる者は。'),
('JPN', '约伯记', 18, 12, 7, 'しかし獣に尋ねてみよ。あなたに教えてくれるだろう。空の鳥にも。あなたに告げてくれるだろう。'),
('JPN', '约伯记', 18, 12, 8, 'あるいは地に話しかけよ。教えてくれるだろう。海の魚も語るだろう。'),
('JPN', '约伯记', 18, 12, 9, 'これらすべてのうちで、主の御手がこれをなしたことを知らない者があるだろうか。'),
('JPN', '约伯记', 18, 12, 10, 'すべての生き物のいのちと、すべての肉なる人の息は、その御手のうちにある。'),
('JPN', '约伯记', 18, 12, 11, '口が食物の味を知るように、耳はことばを聞き分けないだろうか。'),
('JPN', '约伯记', 18, 12, 12, '年寄りに知恵があり、年のたけた者に英知があるのか。'),
('JPN', '约伯记', 18, 12, 13, '知恵と力は神とともにあり、思慮と英知も神のものだ。'),
('JPN', '约伯记', 18, 12, 14, '見よ。神が打ち壊すと、二度と建て直せない。人を閉じ込めると、開けられない。'),
('JPN', '约伯记', 18, 12, 15, '見よ。神が引き止めると水は涸れ、水を送ると地はくつがえる。'),
('JPN', '约伯记', 18, 12, 16, '力と英知は神とともにあり、迷い出る者も、迷わす者も神のものだ。'),
('JPN', '约伯记', 18, 12, 17, '神は助言者たちを裸足にして連れ去り、さばく者たちを愚弄し、'),
('JPN', '约伯记', 18, 12, 18, '王たちのかせを解き放ち、彼らの腰に帯を巻き付け、'),
('JPN', '约伯记', 18, 12, 19, '祭司たちを裸足にして連れ去り、勢いある者に道を誤らせる。'),
('JPN', '约伯记', 18, 12, 20, '神は、信頼されている者の唇を取り去り、長老たちの良識を取り上げ、'),
('JPN', '约伯记', 18, 12, 21, '君主たちを侮り、力ある者たちの腰帯を解き、'),
('JPN', '约伯记', 18, 12, 22, '闇から深みをあらわにし、暗黒を光に引き出す。'),
('JPN', '约伯记', 18, 12, 23, '神は国々を栄えさせ、また滅ぼす。国々を広げ、また取り去る。'),
('JPN', '约伯记', 18, 12, 24, '地の民のかしらたちから良識を取り去り、彼らを道のない荒れ地の中でさまよわせ、'),
('JPN', '约伯记', 18, 12, 25, '彼らは光のない闇の中を、手探りで進む。神は彼らを酔いどれのようによろけさせる。'),
('JPN', '约伯记', 18, 13, 1, '見よ。私の目はこれらすべてのことを見た。私の耳も聞いて、それを理解している。'),
('JPN', '约伯记', 18, 13, 2, 'あなたがたが知っていることは私もよく知っている。私はあなたがたより劣ってはいない。'),
('JPN', '约伯记', 18, 13, 3, 'けれども、この私は全能なる方に語りかけ、神と論じ合うことを願う。'),
('JPN', '约伯记', 18, 13, 4, 'しかし、あなたがたは偽りを塗る者、みな無用の医者だ。'),
('JPN', '约伯记', 18, 13, 5, 'ああ、あなたがたが沈黙を守っていたら、それがあなたがたの知恵となっていただろうに。'),
('JPN', '约伯记', 18, 13, 6, 'さあ、私の論じるところを聞き、私の唇の訴えに耳を傾けよ。'),
('JPN', '约伯记', 18, 13, 7, 'あなたがたは、神のためにと言って不正を語り、神のためにと言って欺くことを語るのか。'),
('JPN', '约伯记', 18, 13, 8, 'あなたがたは、神の顔を立てるつもりか。神のためにと、言い争うつもりか。'),
('JPN', '约伯记', 18, 13, 9, '神があなたがたを調べても、かまわないのか。人を欺くように神を欺こうとするのか。'),
('JPN', '约伯记', 18, 13, 10, '神は必ずあなたがたを責める。ひそかに自分の顔を立てようとするなら。'),
('JPN', '约伯记', 18, 13, 11, '神の威厳があなたがたをおびえさせ、神の恐れがあなたがたに下るのではないか。'),
('JPN', '约伯记', 18, 13, 12, 'あなたがたの申し立ては灰のことば。あなたがたの弁明は粘土の盾だ。'),
('JPN', '约伯记', 18, 13, 13, '黙れ。私に関わるな。この私が話す。私に何が降りかかってもかまわない。'),
('JPN', '约伯记', 18, 13, 14, '何のために私は、自分の肉を歯にのせ、自分のたましいを手のひらに置くのか。'),
('JPN', '约伯记', 18, 13, 15, '見よ。神が私を殺しても、私は神を待ち望み、なおも私の道を神の御前に主張しよう。'),
('JPN', '约伯记', 18, 13, 16, '神もまた、私の救いとなってくださる。神を敬わない者は、御前に出ることはできない。'),
('JPN', '约伯记', 18, 13, 17, 'あなたがたは、私のことばをよく聞け。私の述べることを、自分の耳で。'),
('JPN', '约伯记', 18, 13, 18, '今、私は自分の言い分を並べる。自分が義とされることを私は知っている。'),
('JPN', '约伯记', 18, 13, 19, 'だれか私と論争する者がいるのか。もしいるなら、今にも私は黙って息絶えよう。'),
('JPN', '约伯记', 18, 13, 20, 'ただ二つのことを、私になさらないでください。そうすれば、私は御顔から身を隠しません。'),
('JPN', '约伯记', 18, 13, 21, 'あなたの手を私の上から遠ざけてください。あなたの恐ろしさで、おびえさせないでください。'),
('JPN', '约伯记', 18, 13, 22, '呼んでください。私が答えます。あるいは私に語らせ、あなたが返答してください。'),
('JPN', '约伯记', 18, 13, 23, '私には、咎と罪がどれほどあるのでしょうか。私の背きと罪を私に知らせてください。'),
('JPN', '约伯记', 18, 13, 24, 'なぜ、あなたは御顔を隠し、私をあなたの敵と見なされるのですか。'),
('JPN', '约伯记', 18, 13, 25, 'あなたは吹き散らされた木の葉を脅し、乾いた藁を追いかけられるのですか。'),
('JPN', '约伯记', 18, 13, 26, '実に、あなたは私に対し厳しい宣告を書きたて、私の若いときの咎を負い続けさせます。'),
('JPN', '约伯记', 18, 13, 27, 'あなたは私の足にかせをはめ、私が歩む道をことごとく見張り、私の足の裏にしるしを刻まれます。'),
('JPN', '约伯记', 18, 13, 28, 'そのような者は、腐った物のように朽ちます。シミが食った衣服のように。'),
('JPN', '约伯记', 18, 14, 1, '女から生まれた人間は、その齢が短く、心乱されることで満ちています。'),
('JPN', '约伯记', 18, 14, 2, '花のように咲き出てはしおれ、影のように逃げ去り、とどまることがありません。'),
('JPN', '约伯记', 18, 14, 3, 'このような者に対してさえあなたは目を見開き、この私をご自分とともに、さばきの座に連れて行かれるのですか。'),
('JPN', '约伯记', 18, 14, 4, 'きよい物を汚れた物から取り出せたらよいのに。しかし、だれ一人できません。'),
('JPN', '约伯记', 18, 14, 5, 'もし、人の日数が定められていて、その月の数もあなたが決めておられ、その人が越えることのできない限界をあなたが設けておられるなら、'),
('JPN', '约伯记', 18, 14, 6, 'その人から目をそらして、かまわないでください。彼が雇い人のように自分の日を楽しむために。'),
('JPN', '约伯记', 18, 14, 7, '木には望みがある。たとえ切られても、また芽を出しその若枝は絶えることがない。'),
('JPN', '约伯记', 18, 14, 8, 'たとえ、その根が地の中で老い、その根株が土の中で死んでも、'),
('JPN', '约伯记', 18, 14, 9, '水の潤いがあると芽を吹き出し、苗木のように枝を出す。'),
('JPN', '约伯记', 18, 14, 10, 'しかし、人は死ぬと倒れたきりだ。人間は息絶えると、どこにいるのか。'),
('JPN', '约伯记', 18, 14, 11, '水は海から消え去り、川は干上がり、涸れる。'),
('JPN', '约伯记', 18, 14, 12, 'そのように、人は伏して起き上がらず、天がなくなるまで目覚めず、その眠りから覚めることはない。'),
('JPN', '约伯记', 18, 14, 13, 'ああ、あなたが私をよみに隠し、あなたの怒りが過ぎ去るまで私を潜ませ、私のために時を定めて、私を覚えてくださればよいのに。'),
('JPN', '约伯记', 18, 14, 14, '人は死ぬと、また生きるでしょうか。私は苦役の日の限り、待ちます。私の代わりがやって来るまで。'),
('JPN', '约伯记', 18, 14, 15, 'あなたがお呼びになれば、お答えします。あなたは御手のわざを慕っておられるでしょう。'),
('JPN', '约伯记', 18, 14, 16, '今、あなたは私の一歩一歩を数えておられます。私の罪に目を留めないでください。'),
('JPN', '约伯记', 18, 14, 17, '私の背きを袋の中に封じ込め、私の咎をおおってください。'),
('JPN', '约伯记', 18, 14, 18, 'しかし、山は倒れて崩れ去り岩もその場所から移されます。'),
('JPN', '约伯记', 18, 14, 19, '水は石を打ち砕き、あなたは小石を押し流して地のちりとされます。そのように、人の望みを絶ち滅ぼされます。'),
('JPN', '约伯记', 18, 14, 20, 'あなたがいつも人に打ち勝つので、人は去って行きます。あなたは彼の顔かたちを変えて、彼を追いやられます。'),
('JPN', '约伯记', 18, 14, 21, '自分の子どもたちが人に尊ばれても、彼がそれを知ることはなく、彼らが人に卑しめられても、彼には見分けがつきません。'),
('JPN', '约伯记', 18, 14, 22, 'ただ彼の肉が彼のために痛みを覚え、そのたましいが彼のために嘆くだけです。'),
('JPN', '约伯记', 18, 15, 1, 'テマン人エリファズが答えた。'),
('JPN', '约伯记', 18, 15, 2, '知恵のある者は、むなしい知識によって答えるだろうか。東風で腹を満たすだろうか。'),
('JPN', '约伯记', 18, 15, 3, '益にならないことばで、役に立たない論法で論じるだろうか。'),
('JPN', '约伯记', 18, 15, 4, 'あなたは敬虔を不要と見なし、神の御前で祈るのをおろそかにしている。'),
('JPN', '约伯记', 18, 15, 5, 'それは、あなたの咎があなたの口に教え、あなたが悪賢い人の舌を選んでいるからだ。'),
('JPN', '约伯记', 18, 15, 6, 'あなたの口があなたを不義に定める。私ではない。あなたの唇が、あなたに不利な証言をする。'),
('JPN', '约伯记', 18, 15, 7, 'あなたは最初の人間として生まれたのか。丘より先に生み出されたのか。'),
('JPN', '约伯记', 18, 15, 8, 'あなたは神との親しい交わりにあずかり、知恵をひとり占めにしているのか。'),
('JPN', '约伯记', 18, 15, 9, 'あなたが知っていることを、私たちが知らないというのか。あなたが悟っていることは、私たちのうちにはないのか。'),
('JPN', '约伯记', 18, 15, 10, '私たちの中には、白髪の者も古老もいて、あなたの父よりもはるかに年を重ねている。'),
('JPN', '约伯记', 18, 15, 11, '神の慰めは、あなたには不十分なのか。あなたに対して優しく語られたことばは。'),
('JPN', '约伯记', 18, 15, 12, 'なぜ、あなたは自分を見失っているのか。なぜ、あなたの目は、ぎらついているのか。'),
('JPN', '约伯记', 18, 15, 13, 'あなたが神に向かって苛立ち、口からあのようなことばを吐くとは。'),
('JPN', '约伯记', 18, 15, 14, 'どういう人が清くあり得るのか。女から生まれた者で、だれが正しくあり得るのか。'),
('JPN', '约伯记', 18, 15, 15, '見よ、神はその聖なる者たちさえ信頼なさらない。天も神の目には清くない。'),
('JPN', '约伯记', 18, 15, 16, 'まして忌み嫌うべき腐り果てた者、不正を水のように飲む人間は、なおさらだ。'),
('JPN', '约伯记', 18, 15, 17, '私はあなたに告げる。私に聞け。私が見たことを述べよう。'),
('JPN', '约伯记', 18, 15, 18, 'それは知恵のある者たちが告げたこと、その先祖には隠されなかったことだ。'),
('JPN', '约伯记', 18, 15, 19, '彼らだけに、この地は与えられ、他国人が彼らの間を通り過ぎることはなかった。'),
('JPN', '约伯记', 18, 15, 20, '悪しき者は一生もだえ苦しむ。横暴な者には、ある年数が知らされずにいる。'),
('JPN', '约伯记', 18, 15, 21, 'その耳には恐ろしい音が聞こえ、平和なときにも、荒らす者が彼を襲う。'),
('JPN', '约伯记', 18, 15, 22, '彼は自分が闇から帰って来られるとは信じない。彼はいつも剣につけ狙われている。'),
('JPN', '约伯记', 18, 15, 23, '食物を求めて、「どこにあるか」とさまよい歩き、闇の日が間近に用意されているのを知っている。'),
('JPN', '约伯记', 18, 15, 24, '苦難と苦悩は彼をおびえさせ、戦いの備えができた王のように彼を圧倒する。'),
('JPN', '约伯记', 18, 15, 25, 'それは、彼が神に対して手向かい、全能者に対して尊大にふるまい、'),
('JPN', '约伯记', 18, 15, 26, '分厚い盾を取って、傲慢にも神に向かって突き進むからだ。'),
('JPN', '约伯记', 18, 15, 27, '彼が顔を脂でおおい、腰の周りを脂肪で膨れさせたとしても、'),
('JPN', '约伯记', 18, 15, 28, '彼は、消し去られた町、人の住んでいない家に、瓦礫の山となるところに住む。'),
('JPN', '约伯记', 18, 15, 29, '彼は富むこともなく、自分の財産も長く持たず、それがもたらす収益は地に広がらない。'),
('JPN', '约伯记', 18, 15, 30, '彼は闇から離れられず、炎がその若枝を枯らし、神の御口の息によって追い払われる。'),
('JPN', '约伯记', 18, 15, 31, '迷わされて、むなしいことに信頼するな。その報いはむなしいからだ。'),
('JPN', '约伯记', 18, 15, 32, '彼の時が来ないうちに報いはなされ、その葉が緑になることはない。'),
('JPN', '约伯记', 18, 15, 33, 'ぶどうの木のように、その未熟な実は落とされ、オリーブのように、その花は振り落とされる。'),
('JPN', '约伯记', 18, 15, 34, '神を敬わない者の仲間には実りがなく、賄賂の天幕は火で焼き尽くされるからだ。'),
('JPN', '约伯记', 18, 15, 35, '彼らは害悪をはらみ、不法を産み、その腹は欺きを準備している。'),
('JPN', '约伯记', 18, 16, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 16, 2, 'そのようなことは、私は何度も聞いた。あなたがたはみな、人をみじめにする慰め手だ。'),
('JPN', '约伯记', 18, 16, 3, 'むなしいことばには終わりがあるのか。あなたは何に挑発されて答え続けるのか。'),
('JPN', '约伯记', 18, 16, 4, '私も、あなたがたのように語ることができる。もし、あなたがたが私の立場にあったなら、あなたがたに向かって私は多くのことばを連ね、あなたがたに向かって頭を振ったことだろう。'),
('JPN', '约伯记', 18, 16, 5, 'この口であなたがたを強くし、唇による慰めを惜しまなかったことだろう。'),
('JPN', '约伯记', 18, 16, 6, 'たとえ私が語っても、私の痛みは抑えられません。たとえ私が忍んでも、どれだけ私からそれが去るでしょう。'),
('JPN', '约伯记', 18, 16, 7, 'まことに神は今、私を疲れ果てさせました。あなたは、私の仲間をみな荒れ果てさせました。'),
('JPN', '约伯记', 18, 16, 8, 'あなたは私をつかみました。自分の痩せ衰えた姿が証人となり、私に向かって立ち上がり、面と向かって不利な証言をします。'),
('JPN', '约伯记', 18, 16, 9, '神は激怒して私を攻めたて、私に向かって歯をむき出される。私の敵は私に向かって目を鋭くする。'),
('JPN', '约伯记', 18, 16, 10, '彼らは私に向かって大きく口を開け、そしりをもって私の頬を打ち、こぞって私を攻める。'),
('JPN', '约伯记', 18, 16, 11, '神は私を不遜な者に引き渡し、悪しき者の手に投げ込まれる。'),
('JPN', '约伯记', 18, 16, 12, '私は平穏でいたのに、神は私を引き回された。首筋をつかんで私を粉々にし、そうして、ご自分の標的とされた。'),
('JPN', '约伯记', 18, 16, 13, 'その射手たちは私を包囲した。神は私の腎臓を容赦なく射抜き、私の胆汁を地に流された。'),
('JPN', '约伯记', 18, 16, 14, '神は私を打ち、打ち破って、勇士のように私に襲いかかられる。'),
('JPN', '约伯记', 18, 16, 15, '私は粗布を肌に縫い付け、自分の角をちりの中に突き刺した。'),
('JPN', '约伯记', 18, 16, 16, '私の顔は泣きはらして赤くなり、まぶたには死の陰がある。'),
('JPN', '约伯记', 18, 16, 17, '私の手には暴虐がなく、私の祈りはきよいのだが。'),
('JPN', '约伯记', 18, 16, 18, '地よ、私の血をおおうな。私の叫びに休み場がないようにせよ。'),
('JPN', '约伯记', 18, 16, 19, '今でも、天には私の証人がおられます。私の保証人が、高い所に。'),
('JPN', '约伯记', 18, 16, 20, '私の友は私を嘲る者たち。しかし、私の目は神に向かって涙を流します。'),
('JPN', '约伯记', 18, 16, 21, 'その方が、人のために神にとりなしてくださいますように。人の子がその友のためにするように。'),
('JPN', '约伯记', 18, 16, 22, '数年もたてば、私は帰らぬ旅路につくのですから。'),
('JPN', '约伯记', 18, 17, 1, '私の霊は乱れ、私の日は尽き、私には墓場があるだけです。'),
('JPN', '约伯记', 18, 17, 2, '実に、嘲る者たちが私とともにいます。私の目は彼らの敵意の中で夜を過ごします。'),
('JPN', '约伯记', 18, 17, 3, 'どうか、私を保証してくれる人をあなたのそばに置いてください。ほかにだれか誓ってくれる人がいるでしょうか。'),
('JPN', '约伯记', 18, 17, 4, 'あなたはあの者たちの心を賢明さから引き離されました。ですから、あなたが彼らを高く上げられることはありません。'),
('JPN', '约伯记', 18, 17, 5, '分け前を得るために友の告げ口をする者。その子らの目は衰え果てる。'),
('JPN', '约伯记', 18, 17, 6, '神は私を人々の笑いものとされ、私は顔に唾される者となった。'),
('JPN', '约伯记', 18, 17, 7, '私の目は苦悶でかすみ、私のからだはどこも影のようだ。'),
('JPN', '约伯记', 18, 17, 8, '心の直ぐな人はこのことに驚き恐れ、潔白な人は神を敬わない者に向かって憤る。'),
('JPN', '约伯记', 18, 17, 9, '正しい人は自分の道を保ち、手のきよい人は強さを増し加える。'),
('JPN', '约伯记', 18, 17, 10, 'だが、あなたがたはみな帰って来るがよい。私はあなたがたの中に、知恵のある者を一人も見出さないだろう。'),
('JPN', '约伯记', 18, 17, 11, '私の日は過ぎ去り、私の企て、私の心の願いも砕かれた。'),
('JPN', '约伯记', 18, 17, 12, '「夜は昼に変わり、闇のあるところに光が近づく」と人は言う。'),
('JPN', '约伯记', 18, 17, 13, 'しかし私が、よみを自分の住まいとして望み、闇に自分の寝床を広げ、'),
('JPN', '约伯记', 18, 17, 14, 'その穴に向かって「あなたは私の父」と言い、うじ虫に向かって「あなたは私の母、私の姉妹」と宣言するなら、'),
('JPN', '约伯记', 18, 17, 15, 'いったい、どこに私の望みがあるのか。だれが私の望みを目にするのか。'),
('JPN', '约伯记', 18, 17, 16, 'それらがよみの戸口に下ったとしても、私たちがともに、ちりの上に降りたとしても。'),
('JPN', '约伯记', 18, 18, 1, 'シュアハ人ビルダデが答えた。'),
('JPN', '约伯记', 18, 18, 2, 'いつになったら、あなたがたはその話にけりをつけるのか。まず理解せよ。それから語り合おうではないか。'),
('JPN', '约伯记', 18, 18, 3, 'なぜ、私たちは獣のように見なされ、あなたがたには愚かに見えるのか。'),
('JPN', '约伯记', 18, 18, 4, '怒って自分自身を引き裂く者よ、あなたのために地が見捨てられるだろうか。岩がその場所から移されるだろうか。'),
('JPN', '约伯记', 18, 18, 5, 'まことに、悪しき者の光は消え、その火の炎も輝くことはない。'),
('JPN', '约伯记', 18, 18, 6, '彼の天幕の内では光が暗くなり、彼を照らすともしびも消える。'),
('JPN', '约伯记', 18, 18, 7, '彼の力強い歩幅は狭められ、自らのはかりごとが彼を打ち倒す。'),
('JPN', '约伯记', 18, 18, 8, '彼は自分の足で網にかかり、その網目の上を歩き回る。'),
('JPN', '约伯记', 18, 18, 9, '罠は彼のかかとを捕らえ、仕掛け網は彼を捕まえる。'),
('JPN', '约伯记', 18, 18, 10, '地には彼を捕まえる縄が隠されている。捕らえるための罠が通り道に。'),
('JPN', '约伯记', 18, 18, 11, '突然の恐怖が彼を周りからおびえさせ、その足を追い立てる。'),
('JPN', '约伯记', 18, 18, 12, '彼の精力は飢えて衰え、わざわいが彼をつまずかせようとする。'),
('JPN', '约伯记', 18, 18, 13, 'わざわいは彼の皮膚を食らおうとし、死の初子がからだを食らおうとする。'),
('JPN', '约伯记', 18, 18, 14, '彼は、拠り頼んでいる天幕から引き抜かれ、恐怖の王のもとへと引き立てられる。'),
('JPN', '约伯记', 18, 18, 15, '彼の天幕には、身内でない者が住み、硫黄がその住まいの上にまき散らされる。'),
('JPN', '约伯记', 18, 18, 16, '下では彼の根が枯れ、上では枝がしおれる。'),
('JPN', '约伯记', 18, 18, 17, '彼の記憶は地から消え失せ、地の面では無名となる。'),
('JPN', '约伯记', 18, 18, 18, '彼は光から闇に追いやられ、世から追い出される。'),
('JPN', '约伯记', 18, 18, 19, '彼の民の中には子孫も末裔もいなくなり、その住みかには一人の生存者もいなくなる。'),
('JPN', '约伯记', 18, 18, 20, '西に住む者は彼の日について驚き恐れ、東に住む者は恐怖に取りつかれる。'),
('JPN', '约伯记', 18, 18, 21, 'まことに、これが不正を働く者の住まい、これが神を知らない者の住む場所である。'),
('JPN', '约伯记', 18, 19, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 19, 2, 'いつまで、あなたがたは私のたましいを悩ませ、ことばで私を砕くのか。'),
('JPN', '约伯记', 18, 19, 3, 'もう十度もあなたがたは私を辱め、私をいじめて恥じることもない。'),
('JPN', '约伯记', 18, 19, 4, '私が本当に過ちに陥っていたとしても、私の過ちは私のうちにとどまるだけだ。'),
('JPN', '约伯记', 18, 19, 5, 'もし、本当にあなたがたが私に向かって高ぶり、私が受けた恥辱のことで、私を責めるつもりなら、'),
('JPN', '约伯记', 18, 19, 6, '今知れ。神が私を不当に扱い、ご自分の網で私を取り囲まれたことを。'),
('JPN', '约伯记', 18, 19, 7, '見よ。私が「暴虐だ」と叫んでも、答えはなく、叫び求めても、さばきは行われない。'),
('JPN', '约伯记', 18, 19, 8, '神は私の道をふさいで通らせず、私の通り道に闇を置かれた。'),
('JPN', '约伯记', 18, 19, 9, '神は私から栄光をはぎ取り、頭から冠を取り去られた。'),
('JPN', '约伯记', 18, 19, 10, '神は四方から私を打ち倒し、私は消え去る。神は私の望みを木のように根こそぎにされる。'),
('JPN', '约伯记', 18, 19, 11, '神は私に向かって怒りを燃やし、私をご自分の敵のように見なされる。'),
('JPN', '约伯记', 18, 19, 12, 'その軍勢は一つとなって進んで来て、私に向かって傾斜路を築き上げ、私の天幕の周りに陣を敷く。'),
('JPN', '约伯记', 18, 19, 13, '神は私の兄弟たちを私から遠ざけ、知人たちはすっかり私から離れて行った。'),
('JPN', '约伯记', 18, 19, 14, '親族は見放し、親しい友も私を忘れた。'),
('JPN', '约伯记', 18, 19, 15, '私の家に身を寄せる者や召使いの女たちも、私をよそ者のように見なし、私は彼らの目に他人となった。'),
('JPN', '约伯记', 18, 19, 16, '私がしもべを呼んでも、彼は返事もしない。私は自分の口で彼に懇願しなければならない。'),
('JPN', '约伯记', 18, 19, 17, '私の息は妻にいやがられ、身内の者たちに嫌われる。'),
('JPN', '约伯记', 18, 19, 18, '若輩までが私を蔑み、私が立ち上がると、私に言い逆らう。'),
('JPN', '约伯记', 18, 19, 19, '親しい仲間はみな私を忌み嫌い、私が愛した人たちも私に背を向けた。'),
('JPN', '约伯记', 18, 19, 20, '私は、骨が皮と肉にくっつき、かろうじて生き延びている。'),
('JPN', '约伯记', 18, 19, 21, 'あなたがた、私の友よ。あわれんでくれ。私をあわれんでくれ。神の御手が私を打ったからだ。'),
('JPN', '约伯记', 18, 19, 22, 'なぜ、神のように私を追いつめるのか。なぜ、私の肉で満足しないのか。'),
('JPN', '约伯记', 18, 19, 23, 'ああ今、できることなら、私のことばが書かれ、書物に記されればよいのに。'),
('JPN', '约伯记', 18, 19, 24, '鉄の筆と鉛によって、いつまでも岩に刻みつけられればよいのに。'),
('JPN', '约伯记', 18, 19, 25, '私は知っている。私を贖う方は生きておられ、ついには、土のちりの上に立たれることを。'),
('JPN', '约伯记', 18, 19, 26, '私の皮がこのように剝ぎ取られた後に、私は私の肉から神を見る。'),
('JPN', '约伯记', 18, 19, 27, 'この方を私は自分自身で見る。私自身の目がこの方を見る。ほかの者ではない。私の思いは胸の内で絶え入るばかりだ。'),
('JPN', '约伯记', 18, 19, 28, 'あなたがたが、「彼をどのように追いつめようか。事の原因は彼にあるのだから」と言うなら、'),
('JPN', '约伯记', 18, 19, 29, 'あなたがたは剣を恐れよ。憤りが剣による刑罰をもたらすからだ。こうして、あなたがたはさばきがあることを知るようになる。'),
('JPN', '约伯记', 18, 20, 1, 'ナアマ人ツォファルは答えた。'),
('JPN', '约伯记', 18, 20, 2, 'こうだから、苛立つ思いが私に応答させるのだ。私の心の焦りのゆえに。'),
('JPN', '约伯记', 18, 20, 3, '私は自分への侮辱となる訓戒を聞く。だから、悟りを与える霊が私に答えを促すのだ。'),
('JPN', '约伯记', 18, 20, 4, 'あなたは確かに知っているはずだ。昔から、人が地の上に置かれてから、'),
('JPN', '约伯记', 18, 20, 5, '悪しき者の喜びは短く、神を敬わない者の楽しみは束の間だ。'),
('JPN', '约伯记', 18, 20, 6, 'たとえ、その者の高ぶりが天にまで上り、その頭が濃い雲にまで達しても、'),
('JPN', '约伯记', 18, 20, 7, '彼は自分の糞のようにすっかり滅び去る。かつて彼を見た者は「彼はどこにいるか」と言う。'),
('JPN', '约伯记', 18, 20, 8, '彼は夢のように飛び去り、だれにも見つからない。彼は夜の幻のように追い払われる。'),
('JPN', '约伯记', 18, 20, 9, '彼を見慣れていた目は、再び彼を見ることがなく、彼の家も、もはや彼を見ない。'),
('JPN', '约伯记', 18, 20, 10, '彼の子らは貧しい人たちにあわれみを乞い、彼は自分の手で、自分の富を元に戻す。'),
('JPN', '约伯记', 18, 20, 11, '彼の骨は若さに満ちていても、彼とともに土のちりの上に横たわることになる。'),
('JPN', '约伯记', 18, 20, 12, 'たとえ悪が口に甘く、彼がそれを舌の裏に隠していても、'),
('JPN', '约伯记', 18, 20, 13, 'あるいはそれを惜しんで捨てようとせず、口の奥にとどめていても、'),
('JPN', '约伯记', 18, 20, 14, '彼が食べた物は腹の中で変わり、彼の内側でコブラの毒となる。'),
('JPN', '约伯记', 18, 20, 15, '富を吞み込んでも、彼はまたそれを吐き出す。神がそれを彼の腹から出される。'),
('JPN', '约伯记', 18, 20, 16, '彼はコブラの毒を吸い、まむしの舌が彼を殺す。'),
('JPN', '约伯记', 18, 20, 17, '彼は豊かな水の流れを見ることがない。蜜と凝乳の流れる川を。'),
('JPN', '约伯记', 18, 20, 18, '労苦して得たものも、吞み込まずに返し、商いで得た富も楽しめない。'),
('JPN', '约伯记', 18, 20, 19, '彼が弱い者を踏みにじって見捨て、自分で建てたのではない家を奪い取ったからだ。'),
('JPN', '约伯记', 18, 20, 20, '彼の腹は満足することを知らないので、欲しがっている物を、何一つ逃さない。'),
('JPN', '约伯记', 18, 20, 21, '彼が食べるためのものは何も残っていない。それゆえ、彼の繁栄は長くは続かない。'),
('JPN', '约伯记', 18, 20, 22, '彼は、豊かさが満ちるときに苦境に立たされ、労苦する者の手がことごとく彼に押し寄せる。'),
('JPN', '约伯记', 18, 20, 23, '彼が腹を満たそうとすると、神は燃える怒りを彼に送り、憤りを彼の上に降らせる。'),
('JPN', '约伯记', 18, 20, 24, '彼が鉄の武器を逃れても、青銅の弓が彼を射抜く。'),
('JPN', '约伯记', 18, 20, 25, '矢が貫いて背中から出、きらめく矢じりが貫いて肝から出る。恐怖が彼の上に臨む。'),
('JPN', '约伯记', 18, 20, 26, 'すべての闇が彼の宝として隠され、吹き起こしたのではない火が彼をなめ尽くし、彼の天幕に生き残っている者も痛手を被る。'),
('JPN', '约伯记', 18, 20, 27, '天は彼の咎をあらわにし、地は彼に逆らって立つ。'),
('JPN', '约伯记', 18, 20, 28, '彼の家の作物はさらわれ、御怒りの日に消え失せる。'),
('JPN', '约伯记', 18, 20, 29, 'これが悪しき人間が神から受ける分、神によって定められた、彼の受け継ぐものである。'),
('JPN', '约伯记', 18, 21, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 21, 2, '私の言い分をよく聞いてくれ。それを、あなたがたから私への慰めにしてくれ。'),
('JPN', '约伯记', 18, 21, 3, 'まず、この私が話すのを許してくれ。私が話し終わってから、あなたは嘲るがよい。'),
('JPN', '约伯记', 18, 21, 4, 'この私の不平は人に向かってであろうか。なぜ、私が苛立ってはならないのか。'),
('JPN', '约伯记', 18, 21, 5, '私の方を向いてくれ。驚き恐れよ。そして手を口に当てよ。'),
('JPN', '约伯记', 18, 21, 6, '私はそのことを思い出すとおびえ、戦慄でからだが震える。'),
('JPN', '约伯记', 18, 21, 7, 'なぜ悪しき者が生きながらえて年をとっても、なお力を増し加えるのか。'),
('JPN', '约伯记', 18, 21, 8, 'その子孫は彼らとともにあって、彼らの前に堅く立ち、その末裔は彼らの目の前に堅く立つ。'),
('JPN', '约伯记', 18, 21, 9, '彼らの家は平和で恐れもなく、神のむちが彼らの上に下されることもない。'),
('JPN', '约伯记', 18, 21, 10, 'その雄牛は、はらませて失敗することがなく、その雌牛は、子を産んで仕損じることがない。'),
('JPN', '约伯记', 18, 21, 11, '彼らは幼子たちを羊の群れのように自由にさせ、彼らの子どもたちは飛び跳ねる。'),
('JPN', '约伯记', 18, 21, 12, '彼らはタンバリンや竪琴に合わせて歌い、笛の音で楽しむ。'),
('JPN', '约伯记', 18, 21, 13, '幸せのうちに寿命を全うし、安らかによみに下る。'),
('JPN', '约伯记', 18, 21, 14, '彼らは神に向かって言う。「私たちから離れよ。私たちは、あなたの道を知りたくない。'),
('JPN', '约伯记', 18, 21, 15, '全能者とは何なのか。私たちが仕えなければならないとは。どんな益があるのか。私たちが彼に祈り願ったところで」と。'),
('JPN', '约伯记', 18, 21, 16, '見よ、彼らの繁栄はその手の中にはない。悪者のはかりごとは、私とは何の関係もない。'),
('JPN', '约伯记', 18, 21, 17, '幾たび、悪者どものともしびが消え、破局が彼らの上に臨み、神が怒って彼らに滅びを分け与えられることか。'),
('JPN', '约伯记', 18, 21, 18, '彼らは風の前の藁のようではないか。つむじ風が吹き散らす籾殻のようではないか。'),
('JPN', '约伯记', 18, 21, 19, '神がそのような者の子らのために、わざわいを秘めておられるというのか。その人自身が報いを受けて、思い知らなければならないのだ。'),
('JPN', '约伯记', 18, 21, 20, 'その人自身の目が自分の滅びを見、自分が全能者の憤りを吞まなければならない。'),
('JPN', '约伯记', 18, 21, 21, '自分の日数が限られているのに、なぜ自分の後の家のことを気にかけるのか。'),
('JPN', '约伯记', 18, 21, 22, '人が神に知識を教えようとするのか。神は、高ぶる者たちにさばきを下されるのだ。'),
('JPN', '约伯记', 18, 21, 23, 'ある者は元気盛りの時に死ぬ。全く安らかに、平穏のうちに。'),
('JPN', '约伯记', 18, 21, 24, 'そのからだは脂ぎって、骨の髄まで潤っている。'),
('JPN', '约伯记', 18, 21, 25, 'しかし、ある者は苦悩のうちに死ぬ。幸せを味わうこともなく。'),
('JPN', '约伯记', 18, 21, 26, '両者はともに土のちりに伏し、うじ虫が彼らをおおう。'),
('JPN', '约伯记', 18, 21, 27, '確かに私は、あなたがたの計画を知っている。私を不当に扱おうとする企みを。'),
('JPN', '约伯记', 18, 21, 28, 'あなたがたは言う。「高貴な人の家はどこにあるか。悪しき者たちが住んだ天幕はどこにあるか」と。'),
('JPN', '约伯记', 18, 21, 29, 'あなたがたは道行く人たちに尋ねなかったのか。彼らの証しをよく調べたことはないのか。'),
('JPN', '约伯记', 18, 21, 30, '悪人がわざわいの日を免れ、激しい怒りの日から連れ出されるというのか。'),
('JPN', '约伯记', 18, 21, 31, 'だれが面と向かって、彼の行くべき道を告げることができるのか。彼がしたことに対して、だれが報いることができるのか。'),
('JPN', '约伯记', 18, 21, 32, '彼は墓場に運ばれ、その塚の上には見張りが立てられる。'),
('JPN', '约伯记', 18, 21, 33, '谷の土くれは彼には快く、すべての人間が彼の後について行き、彼の先には数えきれない人がいる。'),
('JPN', '约伯记', 18, 21, 34, 'それなのに、どうしてあなたがたは空しいことばで私を慰めようとするのか。あなたがたの応答は、不信実以外の何でもない。'),
('JPN', '约伯记', 18, 22, 1, 'テマン人エリファズが答えた。'),
('JPN', '约伯记', 18, 22, 2, '人は神の役に立てるだろうか。賢い人でさえ、ただ自分自身の役に立つだけだ。'),
('JPN', '约伯记', 18, 22, 3, 'あなたが正しいからといって、それが全能者の喜びとなるだろうか。あなたの行いが全きものであるからといって、それが神にとって益になるだろうか。'),
('JPN', '约伯记', 18, 22, 4, 'あなたが神を恐れているためか。神があなたを責められるのは。神があなたとともにさばきの座に入って行かれるのは。'),
('JPN', '约伯记', 18, 22, 5, 'いや、それはあなたの悪が大きく、あなたの不義に際限がないからではないか。'),
('JPN', '约伯记', 18, 22, 6, 'あなたは理由もなく兄弟から質物を取り、着ている物をはぎ取って裸にし、'),
('JPN', '约伯记', 18, 22, 7, '疲れている人に水を飲ませず、飢えている人に食物を拒んだからだ。'),
('JPN', '约伯记', 18, 22, 8, '土地を所有している有力者のように、そこに住む、名のある者のように、'),
('JPN', '约伯记', 18, 22, 9, 'あなたはやもめを手ぶらで去らせ、みなしごたちの腕を折った。'),
('JPN', '约伯记', 18, 22, 10, 'そのため罠があなたを取り巻き、恐れが突然あなたを脅かすのだ。'),
('JPN', '约伯记', 18, 22, 11, 'あるいは、闇のために見ることもできなくなり、みなぎる水があなたをおおうのだ。'),
('JPN', '约伯记', 18, 22, 12, '神は天の高きにおられるではないか。星々の頂を見よ。それらはなんと高いことか。'),
('JPN', '约伯记', 18, 22, 13, 'あなたは言う。「神に何が分かるだろうか。黒雲の中からさばくことができるだろうか。'),
('JPN', '约伯记', 18, 22, 14, '濃い雲が覆いとなって、神は見ることができない。神は天空を歩き回るだけだ」と。'),
('JPN', '约伯记', 18, 22, 15, 'あなたは昔からの道を守って行くのか。悪人どもが歩んだあの道を。'),
('JPN', '约伯记', 18, 22, 16, '彼らは年若くして取り去られ、彼らの土台は流れに押し流された。'),
('JPN', '约伯记', 18, 22, 17, '彼らは神に向かって、「私たちから離れてくれ」と言った。全能者は彼らに何をなさるだろうか。'),
('JPN', '约伯记', 18, 22, 18, 'しかし神は、彼らの家を良き物で満たされた。だが、悪者のはかりごとは私と何の関係もない。'),
('JPN', '约伯记', 18, 22, 19, '正しい者は見て喜び、潔白な者は彼らを嘲って言う。'),
('JPN', '约伯记', 18, 22, 20, '「まことに、私たちに向かい立った者は滅ぼされ、悪人どもが残した物は火が焼き尽くした」と。'),
('JPN', '约伯记', 18, 22, 21, 'さあ、あなたは神と和らぎ、平安を得よ。そうすれば幸いがあなたのところに来るだろう。'),
('JPN', '约伯记', 18, 22, 22, '神の口からみおしえを受け、そのみことばを心にとどめよ。'),
('JPN', '约伯记', 18, 22, 23, 'もし全能者に立ち返るなら、あなたは再び立ち直る。自分の天幕から不正を遠ざけるなら。'),
('JPN', '约伯记', 18, 22, 24, 'あなたは黄金を土のちりの上に置け。オフィルの金を川の小石の間に。'),
('JPN', '约伯记', 18, 22, 25, 'そうすれば全能者はあなたの黄金となり、あなたにとっての尊い銀となる。'),
('JPN', '约伯记', 18, 22, 26, 'そのとき必ず、あなたは全能者を自分の喜びとし、神に向かって顔を上げることができる。'),
('JPN', '约伯记', 18, 22, 27, 'あなたが神に祈ると、神はあなたに聞き、あなたは自分の誓願を果たすことができる。'),
('JPN', '约伯记', 18, 22, 28, 'あなたが事を決めると、それは成り、あなたの道の上には光が輝く。'),
('JPN', '约伯记', 18, 22, 29, '彼らが気落ちすれば、あなたは「勇気を出せ」と言う。こうして、へりくだっている者は救われる。'),
('JPN', '约伯记', 18, 22, 30, '潔白でない者さえ助け出され、あなたの手のきよさによって逃れる。'),
('JPN', '约伯记', 18, 23, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 23, 2, '今日もまた、私の嘆きは激しく、自分のうめきのゆえに私の手は重い。'),
('JPN', '约伯记', 18, 23, 3, 'ああ、できるなら、どこで神に会えるかを知って、その御座にまで行きたいものだ。'),
('JPN', '约伯记', 18, 23, 4, '私は神の御前に自分の言い分を並べて、ことばを尽くして訴えたい。'),
('JPN', '约伯记', 18, 23, 5, '神が私に答えることばを知り、神が私に言われることをわきまえ知りたい。'),
('JPN', '约伯记', 18, 23, 6, '神は強い力で私と争われるだろうか。いや、むしろ私に心を留めてくださるだろう。'),
('JPN', '约伯记', 18, 23, 7, 'そこでは正直な人が神と論じ合うことができ、私は、とこしえにさばきを免れるだろう。'),
('JPN', '约伯记', 18, 23, 8, 'だが見よ。私が前へ進んでも、神はおられず、うしろに行っても、神を認めることができない。'),
('JPN', '约伯记', 18, 23, 9, '左に向かって行っても、神を見ることはなく、右に向きを変えても、会うことができない。'),
('JPN', '约伯记', 18, 23, 10, 'しかし神は、私の行く道を知っておられる。私は試されると、金のようになって出て来る。'),
('JPN', '约伯记', 18, 23, 11, '私の足は神の歩みにつき従い、神の道を守って、それたことがない。'),
('JPN', '约伯记', 18, 23, 12, '私は神の唇の命令から離れず、自分の定めよりも神の口のことばを蓄えた。'),
('JPN', '约伯记', 18, 23, 13, 'しかし、みこころは一つである。だれがその御思いを翻せるだろうか。神はご自分が欲するところを行われる。'),
('JPN', '约伯记', 18, 23, 14, '神は、私について定めたことを成し遂げられる。神にはそのような多くの定めがあるからだ。'),
('JPN', '约伯记', 18, 23, 15, 'それで私は、神の御前でおびえ、思いを巡らして、神を恐れているのだ。'),
('JPN', '约伯记', 18, 23, 16, '神は私の心を弱くされた。全能者が私をおびえさせられたのだ。'),
('JPN', '约伯记', 18, 23, 17, 'しかし、闇によって私が黙らされることはない。私の顔が暗黒におおわれていても。'),
('JPN', '约伯记', 18, 24, 1, 'なぜ、全能者に時が隠されていないのに、神を知る者たちには神の日々が見られないのか。'),
('JPN', '约伯记', 18, 24, 2, '人々は地境を動かし、群れを奪ってこれを飼う。'),
('JPN', '约伯记', 18, 24, 3, 'みなしごのろばを連れ去り、やもめの牛を質に取り、'),
('JPN', '约伯记', 18, 24, 4, '貧しい者たちを道から押しのける。地の苦しむ者たちは、すっかりおおい隠される。'),
('JPN', '约伯记', 18, 24, 5, 'その人たちは荒野の野ろばのように、働きに出ては獲物を探す。荒れた地で、子たちのために食べ物を求めて。'),
('JPN', '约伯记', 18, 24, 6, '野で自分の飼葉を刈り取り、悪しき者のぶどう畑で残り物を集める。'),
('JPN', '约伯记', 18, 24, 7, '着る物もなく、裸で夜を明かし、寒さの中でも身をおおう物がない。'),
('JPN', '约伯记', 18, 24, 8, '山の嵐でずぶぬれになり、避け所もなく、岩を抱く。'),
('JPN', '约伯记', 18, 24, 9, 'みなしごは乳房から引き離され、貧しい者が持つ物は質に取られる。'),
('JPN', '约伯记', 18, 24, 10, '着る物もなく裸で歩き、飢えながら麦束を運ぶ。'),
('JPN', '约伯记', 18, 24, 11, 'オリーブの植え込みの間で油を搾り、踏み場でぶどうを踏みながらも、なお渇く。'),
('JPN', '约伯记', 18, 24, 12, '人の住む町からうめき声が起こり、傷ついた者のたましいが助けを求めて叫ぶ。しかし、神はその叫び声に心を留められない。'),
('JPN', '约伯记', 18, 24, 13, 'これらの者は光に背く者。光の道を認めず、光の通り道にとどまろうとしない。'),
('JPN', '约伯记', 18, 24, 14, '人殺しは、光のある間に起き上がり、苦しむ人や貧しい人を殺して、夜には盗人となる。'),
('JPN', '约伯记', 18, 24, 15, '姦通する者の目も、夕暮れ時を見張り、「だれの目も私に気づかない」と言いながら、自分の顔に覆いをする。'),
('JPN', '约伯记', 18, 24, 16, '彼は暗くなってから家々に侵入する。昼間は閉じこもっていて光を知らない。'),
('JPN', '约伯记', 18, 24, 17, '朝はことごとく、彼のような者には暗黒である。彼は暗黒の恐怖と親しいからだ。'),
('JPN', '约伯记', 18, 24, 18, '彼のような者は水の面をすばやく通り過ぎ、彼らの割り当て地はその地でのろわれる。だれも彼らのぶどう畑の道に向かわない。'),
('JPN', '约伯记', 18, 24, 19, '日照りと暑さは雪解け水を、よみは罪を犯した者を奪い去る。'),
('JPN', '约伯记', 18, 24, 20, '母の胎は彼を忘れ、うじ虫は彼を好んで食べる。彼はもう思い出されることはない。不正な者は木のように折られる。'),
('JPN', '约伯记', 18, 24, 21, '彼は、子を産まない不妊の女を食いものにし、やもめに良くしない。'),
('JPN', '约伯记', 18, 24, 22, '彼は力をもって、権力者たちを引きずり降ろす。彼自身は台頭するが、自分にいのちのあることが信じられない。'),
('JPN', '约伯记', 18, 24, 23, '神が彼に安全を与えるので、彼は支えられる。しかし、神の目は彼らの道の上に注がれる。'),
('JPN', '约伯记', 18, 24, 24, '彼らはしばらくの間高められるが、いなくなる。低くされ、すべての者と同じく刈り集められる。そして麦の穂先のように枯れる。'),
('JPN', '约伯记', 18, 24, 25, '今そうでないからといって、だれが私をまやかし者だと言えるのか。だれが私のことばをたわごとと見なせるのか。'),
('JPN', '约伯记', 18, 25, 1, 'シュアハ人ビルダデが答えた。'),
('JPN', '约伯记', 18, 25, 2, '主権と恐れは神のもの。神はその高い所で平和をつくられる。'),
('JPN', '约伯记', 18, 25, 3, 'その軍勢の数には限りがあるだろうか。その光に照らされない者がいるだろうか。'),
('JPN', '约伯记', 18, 25, 4, '人はどうして神の前に正しくあり得るだろうか。女から生まれた者が、どうして清くあり得るだろうか。'),
('JPN', '约伯记', 18, 25, 5, 'ああ、神の目には月さえ輝きがなく、星も清くない。'),
('JPN', '约伯记', 18, 25, 6, 'まして、うじ虫でしかない人間、虫けらでしかない人の子はなおさらだ。'),
('JPN', '约伯记', 18, 26, 1, 'ヨブは答えた。'),
('JPN', '约伯记', 18, 26, 2, 'あなたは無力な者をどのように助けたのか。力のない腕をどのように救ったのか。'),
('JPN', '约伯记', 18, 26, 3, '知恵のない者にどのように助言し、知性を豊かに示したのか。'),
('JPN', '约伯记', 18, 26, 4, 'だれに対してことばを告げたのか。だれの息があなたから出たのか。'),
('JPN', '约伯记', 18, 26, 5, '死者の霊たち、水に住む者たちはその底で、もだえ苦しむ。'),
('JPN', '约伯记', 18, 26, 6, 'よみも神の前では裸であり、滅びの淵もおおわれることはない。'),
('JPN', '约伯记', 18, 26, 7, '神は北を、茫漠としたところに張り広げ、地を、何もないところに掛けられる。'),
('JPN', '约伯记', 18, 26, 8, '神は水を濃い雲の中に包まれるが、雲はその下で裂けることはない。'),
('JPN', '约伯记', 18, 26, 9, '神は満月の面をおおい、その上に雲を広げ、'),
('JPN', '约伯记', 18, 26, 10, '水の面に円を描いて、光と闇との境とされた。'),
('JPN', '约伯记', 18, 26, 11, '天の柱は揺らぎ、神の叱責に驚愕する。'),
('JPN', '约伯记', 18, 26, 12, '神は御力によって海を鎮め、ご自分の英知をもってラハブを打ち砕かれる。'),
('JPN', '约伯记', 18, 26, 13, 'その息によって天は晴れ渡り、御手は逃げる蛇を刺し殺す。'),
('JPN', '约伯记', 18, 26, 14, '見よ、これらは神のみわざの外側にすぎない。私たちは神についてささやきしか聞いていない。御力を示す雷を、だれが理解できるだろうか。'),
('JPN', '约伯记', 18, 27, 1, 'ヨブはさらに言い分を続けた。'),
('JPN', '约伯记', 18, 27, 2, '私は、私の権利を取り去った神にかけて誓う。私のたましいを苦しめた全能者にかけて。'),
('JPN', '约伯记', 18, 27, 3, '私の息が私のうちにあり、神の霊が私の鼻にあるかぎり、'),
('JPN', '约伯记', 18, 27, 4, '私の唇は決して不正を言わず、私の舌は決して欺くことを語らない。'),
('JPN', '约伯记', 18, 27, 5, 'あなたがたを正しいとすることなど、私には絶対にできない。私は息絶えるまで、自分の誠実さをこの身から離さない。'),
('JPN', '约伯记', 18, 27, 6, '私は自分の義を堅く保って手放さない。私の良心は生涯私を責めはしない。'),
('JPN', '约伯记', 18, 27, 7, '私の敵は悪しき者のようになれ。向かい立つ者たちは不正を働く者のようになれ。'),
('JPN', '约伯记', 18, 27, 8, '神を敬わない者に、どのような望みがあるのか。神が彼を断ち切り、いのちを取り去るときには。'),
('JPN', '约伯记', 18, 27, 9, '苦しみが彼に降りかかるとき、神は彼の叫びを聞かれるであろうか。'),
('JPN', '约伯记', 18, 27, 10, '彼は全能者を自分の喜びとするだろうか。どんなときにも神を呼び求めるだろうか。'),
('JPN', '约伯记', 18, 27, 11, '私は、神の御手にあることをあなたがたに教え、全能者のもとにあるものを隠さない。'),
('JPN', '约伯记', 18, 27, 12, 'あなたがたは、全員がそれを見たのに、なぜ、全く空しいことを言うのか。'),
('JPN', '约伯记', 18, 27, 13, '悪しき人間が神から受ける分、横暴な者が全能者から受け継ぐものは次のとおりだ。'),
('JPN', '约伯记', 18, 27, 14, 'たとえ子どもが増えても、剣にかかり、子孫が食べ物に満ち足りることはない。'),
('JPN', '约伯记', 18, 27, 15, 'その生き残りも死んで葬られ、やもめたちは泣きもしない。'),
('JPN', '约伯记', 18, 27, 16, '彼が金をちりのように積み上げ、衣装を土のように蓄えても、'),
('JPN', '约伯记', 18, 27, 17, '蓄えたものは、正しい者がこれを着て、金は、潔白な者が分ける。'),
('JPN', '约伯记', 18, 27, 18, '彼はシミの巣のような家を建てる。番人が作る仮小屋のような家を。'),
('JPN', '约伯记', 18, 27, 19, '富む者として床につくが、もうそれきりだ。目を開けると、もう何もない。'),
('JPN', '约伯记', 18, 27, 20, '突然の恐怖が洪水のように襲い、夜にはつむじ風が彼を運び去る。'),
('JPN', '约伯记', 18, 27, 21, '東風が彼を運ぶと、彼はいなくなり、その居場所から彼を吹き払う。'),
('JPN', '约伯记', 18, 27, 22, 'それは容赦なく襲いかかり、彼はその手から必死に逃れようとする。'),
('JPN', '约伯记', 18, 27, 23, 'それは彼に向かって手をたたき、彼を嘲って、その居場所から追い出す。'),
('JPN', '约伯记', 18, 28, 1, 'まことに、銀には鉱山があり、金には精錬する場所がある。'),
('JPN', '约伯记', 18, 28, 2, '鉄は土から取られ、銅は鉱石を溶かして取る。'),
('JPN', '约伯记', 18, 28, 3, '人は闇の果てに、その極みにまで行って、暗闇と暗黒にある鉱石を探し出す。'),
('JPN', '约伯记', 18, 28, 4, '彼は、人里離れたところで縦坑を掘り進み、行き交う人に忘れられ、人々から離れたところで、ぶら下がって揺れる。'),
('JPN', '约伯记', 18, 28, 5, '地はそこから食物を産み出すが、その下は火のように沸き返っている。'),
('JPN', '约伯记', 18, 28, 6, 'その鉱石からサファイアが出る。その場所には金のちりがある。'),
('JPN', '约伯记', 18, 28, 7, 'その通り道は猛禽も知らず、隼の目もこれを狙ったことがない。'),
('JPN', '约伯记', 18, 28, 8, '誇り高き獣たちもこれを踏まず、たける獅子も通ったことがない。'),
('JPN', '约伯记', 18, 28, 9, '彼は硬い岩にまで手を加え、山々をその根底からくつがえす。'),
('JPN', '约伯记', 18, 28, 10, '彼は岩に坑道を切り開き、あらゆる宝石を目にする。'),
('JPN', '约伯记', 18, 28, 11, '彼は水が滴ることもないように川をせき止め、隠されていた物を明るみに出す。'),
('JPN', '约伯记', 18, 28, 12, 'しかし知恵はどこで見つかるのか。悟りがある場所はどこか。'),
('JPN', '约伯记', 18, 28, 13, '人にはその価値が分からない。それは生ける者の地では見つからない。'),
('JPN', '约伯记', 18, 28, 14, '深淵は言う。「私の中にはそれはない。」海は言う。「私のところにはない。」'),
('JPN', '约伯记', 18, 28, 15, 'それは純金をもってしても得られない。銀を量ってその代価とすることもできない。'),
('JPN', '约伯记', 18, 28, 16, 'オフィルの金によっても値踏みできない。高価な縞めのうや、サファイアによっても。'),
('JPN', '约伯记', 18, 28, 17, '金も玻璃もこれと並ぶことができず、純金の器とも取り替えられない。'),
('JPN', '约伯记', 18, 28, 18, '珊瑚や水晶は言うに及ばず、知恵の価値は真珠にもまさる。'),
('JPN', '约伯记', 18, 28, 19, 'クシュのトパーズもこれと並ぶことができず、純金でもその値踏みをすることはできない。'),
('JPN', '约伯记', 18, 28, 20, 'では、知恵はどこから来るのか。悟りがある場所はどこか。'),
('JPN', '约伯记', 18, 28, 21, 'それはすべての生き物の目に隠され、空の鳥にも隠れている。'),
('JPN', '约伯记', 18, 28, 22, '滅びの淵も、死も言う。「そのうわさは、この耳で聞いたことがある。」'),
('JPN', '约伯记', 18, 28, 23, '神は知恵の道をご存じであり、神こそ、それがある場所を知っておられる。'),
('JPN', '约伯记', 18, 28, 24, 'それは、神が地の隅々までを見渡し、天の下をことごとく見ておられるからだ。'),
('JPN', '约伯记', 18, 28, 25, '神は風に重さを与え、水を秤で量られた。'),
('JPN', '约伯记', 18, 28, 26, '神は雨のために法則を、稲光のために道を決められた。'),
('JPN', '约伯记', 18, 28, 27, 'そのとき、神は知恵を見て、これを見積もり、これを確かめ、調べ上げられた。'),
('JPN', '约伯记', 18, 28, 28, 'こうして、神は人間に仰せられた。「見よ。主を恐れること、これが知恵であり、悪から遠ざかること、これが悟りである」と。'),
('JPN', '约伯记', 18, 29, 1, 'ヨブはさらに言い分を続けた。'),
('JPN', '约伯记', 18, 29, 2, 'ああ、できることなら、昔の月日のようであったらよいのに。神が私を守ってくださった日々のようであったらよいのに。'),
('JPN', '约伯记', 18, 29, 3, 'あのとき、神はともしびを私の頭上に照らし、神の光によって私は闇の中を歩いた。'),
('JPN', '约伯记', 18, 29, 4, '私がまだ壮年であったころ、私の天幕の中には神との親しい交わりがあった。'),
('JPN', '约伯记', 18, 29, 5, '全能者がまだ私とともにおられたとき、私の子どもたちが周りにいた。'),
('JPN', '约伯记', 18, 29, 6, 'あのとき、私の足は凝乳に浸され、岩は私に、油の流れを豊かに注ぎ出してくれた。'),
('JPN', '约伯记', 18, 29, 7, '私は町の門に出て行き、広場に自分の座る所を設けた。'),
('JPN', '约伯记', 18, 29, 8, 'すると、若者たちは私を見て身を引き、年老いた者も起きてまっすぐに立った。'),
('JPN', '约伯记', 18, 29, 9, '首長たちは話すのを控え、手を口に当てた。'),
('JPN', '约伯记', 18, 29, 10, '君主たちの声もひそまり、その舌は上あごについた。'),
('JPN', '约伯记', 18, 29, 11, '私のことを聞いた耳は、私を称賛し、私を見た目は、私の証人となった。'),
('JPN', '约伯记', 18, 29, 12, 'それは私が、叫び求める苦しむ人を、身寄りのないみなしごを助け出したからだ。'),
('JPN', '约伯记', 18, 29, 13, '死にかかっている者からの祝福が私に届き、やもめの心を私は喜ばせた。'),
('JPN', '约伯记', 18, 29, 14, '私は義をまとい、義は私をおおった。私の公正さは上着であり、かぶり物であった。'),
('JPN', '约伯记', 18, 29, 15, '私は目の見えない人の目となり、足の萎えた人の足となった。'),
('JPN', '约伯记', 18, 29, 16, '私は貧しい人の父となり、見知らぬ人の訴訟を取り上げ、調べてあげた。'),
('JPN', '约伯记', 18, 29, 17, 'また不正を働く者の牙を砕き、その歯の間から獲物を奪い返した。'),
('JPN', '约伯记', 18, 29, 18, 'そこで私はこう思った。「私は自分の巣とともに息絶えるが、自分の日数を砂のように増やす。'),
('JPN', '约伯记', 18, 29, 19, '私の根は水に向かって伸び広がり、夜露が私の枝に宿る。'),
('JPN', '约伯记', 18, 29, 20, '私の栄光は私とともに新しくなり、私の弓は私の手によって次々と矢を放つ」と。'),
('JPN', '约伯记', 18, 29, 21, '人々は期待して私の言うことに聞き入り、私の助言に黙って従った。'),
('JPN', '约伯记', 18, 29, 22, '私が語った後にはだれも言い返さず、私のことばは彼らの上に降り注いだ。'),
('JPN', '约伯记', 18, 29, 23, '彼らは雨を待つように私を待ち、後の雨を待つように、口を大きく開けて待った。'),
('JPN', '约伯记', 18, 29, 24, '私が彼らにほほえみかけると、彼らはそのことを信じることができなかった。彼らが私の顔の光を陰らせることはなかった。'),
('JPN', '约伯记', 18, 29, 25, '私は彼らの行くべき道を選んでやり、首長のように座に着いた。また、軍勢とともにある王のように住み、嘆き悲しむ人を慰める者のようであった。'),
('JPN', '约伯记', 18, 30, 1, 'しかし今は、私より年下の者たちが私をあざ笑う。あの者たちの父は、かつて私が蔑んで羊の群れの番犬と一緒にいさせた人たちだ。'),
('JPN', '约伯记', 18, 30, 2, 'あの者たちの手の力も何の役に立つだろうか。彼らの気力は失せている。'),
('JPN', '约伯记', 18, 30, 3, '彼らは欠乏と飢饉で干上がり、乾いた土にさえかじりつく。荒れ果てた廃墟の暗闇で。'),
('JPN', '约伯记', 18, 30, 4, '彼らは陸ひじきや藪の葉を摘み、えにしだの根を食物とする。'),
('JPN', '约伯记', 18, 30, 5, '世間からは追い出され、人々は盗人に叫ぶように、彼らに大声で叫ぶ。'),
('JPN', '约伯记', 18, 30, 6, '谷の斜面や、土の穴、岩の穴に住み、'),
('JPN', '约伯记', 18, 30, 7, '藪の中でいななき、いらくさの下に群がる。'),
('JPN', '约伯记', 18, 30, 8, '彼らは愚か者の子たち、名もない者の子たち、国からむちでたたき出された者たちだ。'),
('JPN', '约伯记', 18, 30, 9, 'それなのに、今や私は彼らの嘲りの的となり、その笑いぐさとなっている。'),
('JPN', '约伯记', 18, 30, 10, '彼らは私を忌み嫌って遠く離れ、私の顔に向かって情け容赦なく唾を吐きかける。'),
('JPN', '约伯记', 18, 30, 11, '神が私の弓弦を解いて私を苦しめ、彼らが自分の綱を私の前で投げ捨てたのだ。'),
('JPN', '约伯记', 18, 30, 12, 'この生意気な者たちは私の右手に立ち、私の足をもつれさせ、私に対して滅びの道を築いた。'),
('JPN', '约伯记', 18, 30, 13, '彼らは私の通り道を打ち壊し、私の滅びを進めている。彼らに助ける者はいらない。'),
('JPN', '约伯记', 18, 30, 14, '彼らは、広い破れ口から入るように、瓦礫となったところになだれ込む。'),
('JPN', '约伯记', 18, 30, 15, '突然の恐怖が私に降りかかり、私の威厳を、あの風のように吹き払う。私の平穏は、雨雲のように過ぎ去った。'),
('JPN', '约伯记', 18, 30, 16, '今、私のたましいは自分に注がれている。苦しみの日々が私をとらえたからだ。'),
('JPN', '约伯记', 18, 30, 17, '夜は私から骨をえぐり取り、私をむしばむものは休まない。'),
('JPN', '约伯记', 18, 30, 18, '神は大きな力で私の衣服に姿を変え、まるで長服の襟のように私に巻き付かれる。'),
('JPN', '约伯记', 18, 30, 19, '神は泥の中に私を投げ込まれ、私はちりや灰のようになった。'),
('JPN', '约伯记', 18, 30, 20, '私があなたに向かって叫んでも、あなたはお答えになりません。私が立っていても、あなたは私に目を留めてくださいません。'),
('JPN', '约伯记', 18, 30, 21, 'あなたは、私にとって残酷な方に変わり、御手の力で、私を攻めたてられます。'),
('JPN', '约伯记', 18, 30, 22, 'あなたは私を吹き上げて風に乗せ、すぐれた知性で、私を翻弄されます。'),
('JPN', '约伯记', 18, 30, 23, '私は知っています。あなたが私を死に帰らせることを。すべての生き物が集まる家に。'),
('JPN', '约伯记', 18, 30, 24, 'それでも、瓦礫の中で人は手を伸ばさないだろうか。災難にあって助けを求めて叫ぶときに。'),
('JPN', '约伯记', 18, 30, 25, '私は不運な人のために、泣かなかっただろうか。私のたましいは貧しい人のために、心を痛めなかっただろうか。'),
('JPN', '约伯记', 18, 30, 26, '私は善を望んだのに、悪が来た。光を待ったのに、暗闇が来た。'),
('JPN', '约伯记', 18, 30, 27, '私のはらわたは、休みなくかき回され、苦しみの日が私に立ち向かっている。'),
('JPN', '约伯记', 18, 30, 28, '私は日にも当たらず、泣き悲しんで歩き回り、集いの中に立って助けを叫び求める。'),
('JPN', '约伯记', 18, 30, 29, '私はジャッカルの兄弟となり、だちょうの仲間となった。'),
('JPN', '约伯记', 18, 30, 30, '私の皮膚は黒ずんで剝げ落ち、骨は熱で焼けている。'),
('JPN', '约伯记', 18, 30, 31, '私の竪琴は喪のためとなり、私の笛は泣き悲しむ者の声となった。'),
('JPN', '约伯记', 18, 31, 1, '私は自分の目と契約を結んだ。どうしておとめに目を留められるだろうか。'),
('JPN', '约伯记', 18, 31, 2, '神が上から分けてくださる取り分は何か。全能者が高い所から下さる相続のものは。'),
('JPN', '约伯记', 18, 31, 3, '不正を働く者にはわざわいが、不法を行う者には災難が来るではないか。'),
('JPN', '约伯记', 18, 31, 4, '神は私の道をご覧にならないだろうか。私の歩みをすべて数えておられないだろうか。'),
('JPN', '约伯记', 18, 31, 5, 'もし、私が偽りとともに歩み、この足が欺きに急いだのなら、'),
('JPN', '约伯记', 18, 31, 6, '神は私を正しい秤で量られればよい。そうすれば神に私の誠実さが分かるだろう。'),
('JPN', '约伯记', 18, 31, 7, 'もし、私の歩みが道からそれ、私の心が自分の目に従って歩み、私の手に汚れがついていたなら、'),
('JPN', '约伯记', 18, 31, 8, '私が種を蒔いて、ほかの人が食べるがよい。私の作物は根こそぎにされるがよい。'),
('JPN', '约伯记', 18, 31, 9, 'もし、私の心が女に惑わされ、隣人の戸口で待ち伏せしたことがあったなら、'),
('JPN', '约伯记', 18, 31, 10, '私の妻が他人のために粉をひいてもよい。また、他人が彼女と寝てもよい。'),
('JPN', '约伯记', 18, 31, 11, 'これは恥ずべき行い、裁判で罰せられるべき不義であるからだ。'),
('JPN', '约伯记', 18, 31, 12, '実に、それは滅びの淵まで焼き尽くす火だ。私の収穫をことごとく根こそぎにする。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '约伯记', 18, 31, 13, 'もし、しもべや召使いの女が私と争ったとき、私が彼らの訴えを拒んだことがあるなら、'),
('JPN', '约伯记', 18, 31, 14, '神が立たれるとき、私はどうすればよいか。また、神がお調べになるとき、何と答えたらよいか。'),
('JPN', '约伯记', 18, 31, 15, '私を胎内で造られた方は、彼らをも造られたのではないか。同じ方が、私たちを母の胎内に形造られたのではないか。'),
('JPN', '约伯记', 18, 31, 16, 'もし、私が弱い者たちの望みを退け、やもめの目を衰え果てさせ、'),
('JPN', '约伯记', 18, 31, 17, '私一人だけでパンを食べ、みなしごにそれを食べさせなかったのなら、'),
('JPN', '约伯记', 18, 31, 18, '──実は私の幼いときから、弱い者は私を父のようにして育ち、私は生まれたときから、やもめを導いた──'),
('JPN', '约伯记', 18, 31, 19, 'あるいは、もし私が、着る物がなくて死にかかっている人や、身をおおう物を持たない貧しい人を見たとき、'),
('JPN', '约伯记', 18, 31, 20, 'その人の腰が私にあいさつをすることも、私の子羊の毛で彼が暖められることもなかったなら、'),
('JPN', '约伯记', 18, 31, 21, 'あるいは、私が門のところに助け手を見て、みなしごに向かって手を振り上げたことがあったなら、'),
('JPN', '约伯记', 18, 31, 22, '私の肩の骨が肩から落ち、私の腕がつけ根から折れてもよい。'),
('JPN', '约伯记', 18, 31, 23, '神からのわざわいが私をおののかせ、その威力のゆえに、私は何もできないだろう。'),
('JPN', '约伯记', 18, 31, 24, 'もし、私が金を自分の頼みとし、黄金に向かって「私の拠り頼むもの」と言ったことがあるなら、'),
('JPN', '约伯记', 18, 31, 25, 'あるいは、私の富が多いことや、私の手が多くを得たことを喜んだことがあるなら、'),
('JPN', '约伯记', 18, 31, 26, 'あるいは、日の光が輝くのを、月が照りながら動くのを見て、'),
('JPN', '约伯记', 18, 31, 27, 'ひそかに心を惑わされ、手で口づけを投げかけたことがあるなら、'),
('JPN', '约伯记', 18, 31, 28, 'これもまた、裁判で罰せられるべき不義だ。私が、上なる神を否んだのだから。'),
('JPN', '约伯记', 18, 31, 29, 'あるいは、私を憎む者が衰えたのを喜び、彼にわざわいが下ったことに心躍らせたことがあるだろうか。'),
('JPN', '约伯记', 18, 31, 30, '私は自分の口を罪に任せなかった。のろいの誓いで彼のいのちを求めたりして。'),
('JPN', '约伯记', 18, 31, 31, '私の天幕の者たちはみな、こう言っているではないか。「あの方のパンに満腹しなかった者がいったいいるだろうか。」'),
('JPN', '约伯记', 18, 31, 32, '寄留者は外で夜を過ごさず、私は戸口を通りに向けて開けている。'),
('JPN', '约伯记', 18, 31, 33, 'あるいは私がアダムのように、自分の背きをおおい隠し、自分の咎を胸の中に秘めたことがあるだろうか。'),
('JPN', '约伯记', 18, 31, 34, '私が群衆の騒ぎにおびえ、一族の蔑みにひるみ、黙っていて、門を出なかったことがあるだろうか。'),
('JPN', '约伯记', 18, 31, 35, 'だれか、私の言うことを聞いてくれる者はいないものか。──ここに私の署名がある。全能者が私に答えてくださるように──私を訴える者が書いた告訴状があれば、'),
('JPN', '约伯记', 18, 31, 36, '私はそれを肩に担ぎ、冠のように、それをこの身に結び付け、'),
('JPN', '约伯记', 18, 31, 37, '私の歩みの数をこの方に告げ、君主のようにしてこの方に近づきたい。'),
('JPN', '约伯记', 18, 31, 38, 'もし、私の土地が私に向かって叫び、その畝がともに泣くことがあるなら、'),
('JPN', '约伯记', 18, 31, 39, 'あるいは私が金を払わずにその産物を食べ、その持ち主のいのちを失わせたことがあるなら、'),
('JPN', '约伯记', 18, 31, 40, '小麦の代わりに茨が、大麦の代わりに雑草が生えるように。ヨブのことばは終わった。'),
('JPN', '约伯记', 18, 32, 1, 'この三人はヨブに答えるのをやめた。ヨブが自分を正しいと思っていたからである。'),
('JPN', '约伯记', 18, 32, 2, 'すると、ラム族のブズ人、バラクエルの子エリフが怒りを燃やした。彼は、ヨブが神よりも自分自身のほうを義としたので、ヨブに向かって怒りを燃やしたのである。'),
('JPN', '约伯记', 18, 32, 3, '彼はまた、その三人の友に向かっても怒りを燃やした。彼らがヨブを不義に定めながら、言い返せなかったからである。'),
('JPN', '约伯记', 18, 32, 4, 'エリフは、彼らが自分よりも年長だったので、ヨブに語りかける時を待っていた。'),
('JPN', '约伯记', 18, 32, 5, 'エリフは三人の者の口に答えがないのを見て、怒りを燃やした。'),
('JPN', '约伯记', 18, 32, 6, 'ブズ人、バラクエルの子エリフは答えて言った。私は年が若く、あなたがたは年をとっている。だから私はわきに控え、遠慮してあなたがたに私の意見を述べなかった。'),
('JPN', '约伯记', 18, 32, 7, '私は思った。「日を重ねた者が語り、年の多い者が知恵を教えるのだ」と。'),
('JPN', '约伯记', 18, 32, 8, '確かに、人の中には霊があり、全能者の息が人に悟りを与える。'),
('JPN', '约伯记', 18, 32, 9, 'だが、年長者が知恵深いわけではない。老人が道理をわきまえているわけでもない。'),
('JPN', '约伯记', 18, 32, 10, 'だから私は言う。「私の言うことを聞いてくれ。私も自分の意見を述べよう。」'),
('JPN', '约伯记', 18, 32, 11, '今まで私はあなたがたの言うことに期待し、あなたがたの意見に耳を傾けていた。あなたがたがことばを探している間、'),
('JPN', '约伯记', 18, 32, 12, '私はあなたがたに細心の注意を払っていた。しかし、あなたがたのうちには、ヨブを叱責する者も、彼のことばに答える者もいなかった。'),
('JPN', '约伯记', 18, 32, 13, 'だが、おそらくあなたがたは言うだろう。「私たちは知恵を見出した。人ではなく、神が彼を吹き払ったのだ」と。'),
('JPN', '约伯记', 18, 32, 14, '彼はまだ私に向かって、ことばを並べ立ててはいない。私はあなたがたのような言い方では彼に答えることはしない。'),
('JPN', '约伯记', 18, 32, 15, '彼らは意気をそがれて、もう答えない。彼らの言うことばもなくなった。'),
('JPN', '约伯记', 18, 32, 16, '彼らが話さず、じっと立って答えないからといって、私は待っていなければならないのか。'),
('JPN', '约伯记', 18, 32, 17, '私は私で自分の言い分を返し、私も自分の意見を述べよう。'),
('JPN', '约伯记', 18, 32, 18, '私にはことばがあふれていて、内なる霊が私を圧迫しているからだ。'),
('JPN', '约伯记', 18, 32, 19, '今、私の腹は抜け口のないぶどう酒のよう。新しい皮袋のように、張り裂けようとしている。'),
('JPN', '约伯记', 18, 32, 20, '私は話して、気分を晴らしたい。唇を開いて答えたい。'),
('JPN', '约伯记', 18, 32, 21, '私はだれも、えこひいきしない。どんな人にも、へつらったりしない。'),
('JPN', '约伯记', 18, 32, 22, '私はへつらうことを知らないし、そんなことをすれば、私を造った方は、すぐにでも私を取り去ってしまわれるだろう。'),
('JPN', '约伯记', 18, 33, 1, 'そこでヨブよ、どうか私の言い分を聞いてほしい。私のすべてのことばに耳を傾けてほしい。'),
('JPN', '约伯记', 18, 33, 2, 'さあ、私は口を開き、私の口の中の舌が語る。'),
('JPN', '约伯记', 18, 33, 3, '私の言うことは、直ぐな心から出る。私の唇は、率直に知識を語る。'),
('JPN', '约伯记', 18, 33, 4, '神の霊が私を造り、全能者の息が私にいのちを下さる。'),
('JPN', '约伯记', 18, 33, 5, 'あなたにできるのであれば、私に返事をし、ことばを並べ立てて、私の前に立ってみよ。'),
('JPN', '约伯记', 18, 33, 6, '実に、神にとって、私はあなたと同様だ。私もまた粘土で形造られた。'),
('JPN', '约伯记', 18, 33, 7, '見よ、私の脅しも、あなたをおびえさせない。あなたに私の力がのしかかっても、重くはない。'),
('JPN', '约伯记', 18, 33, 8, '確かにあなたは、この耳に言った。私はあなたの話す声を聞いた。'),
('JPN', '约伯记', 18, 33, 9, '「私はきよく、背きがない。私は純潔であり、咎もない。'),
('JPN', '约伯记', 18, 33, 10, 'それなのに、神は私を攻める口実を見つけ、私を神の敵のように見なされる。'),
('JPN', '约伯记', 18, 33, 11, '神は私の足にかせをはめ、私の歩みをことごとく見張られる。」'),
('JPN', '约伯记', 18, 33, 12, '聞け。私はあなたに答える。このことであなたは正しくない。神は人よりも偉大なのだから。'),
('JPN', '约伯记', 18, 33, 13, 'なぜ、あなたは神と言い争うのか。自分のことばに、神がいちいち答えてくださらないからといって。'),
('JPN', '约伯记', 18, 33, 14, '神はある方法で語り、また、ほかの方法で語られるが、人はそれに気づかない。'),
('JPN', '约伯记', 18, 33, 15, '夢の中で、夜の幻の中で、深い眠りが人々を襲うとき、また寝床の上でまどろむとき、'),
('JPN', '约伯记', 18, 33, 16, 'そのとき、神はその人たちの耳を開き、彼らを懲らしめて、それを封印される。'),
('JPN', '约伯记', 18, 33, 17, '神は、人間がその悪いわざを取り除くようにし、人から高ぶりを離れさせ、'),
('JPN', '约伯记', 18, 33, 18, '人のたましいが滅びの穴に入らず、そのいのちが投げ槍で滅びないようにされる。'),
('JPN', '约伯记', 18, 33, 19, '神は、床の上で痛みをもって人を責め、いつまでも続く骨の病によってお叱りになる。'),
('JPN', '约伯记', 18, 33, 20, '彼のいのちは食物を嫌い、そのたましいはうまい物を嫌う。'),
('JPN', '约伯记', 18, 33, 21, 'その肉は衰え果てて見えなくなり、見えなかった骨があらわになる。'),
('JPN', '约伯记', 18, 33, 22, 'そのたましいは滅びの穴に、そのいのちは殺す者たちに近づく。'),
('JPN', '约伯记', 18, 33, 23, 'もし彼のそばに、一人の御使いが、千人に一人の仲介者がいて、その方が彼に代わって彼が誠実であることを告げてくれるなら、'),
('JPN', '约伯记', 18, 33, 24, '神は彼をあわれんで仰せられる。「彼を救って、滅びの穴に下って行かないようにせよ。わたしは身代金を見出した」と。'),
('JPN', '约伯记', 18, 33, 25, 'その肉は幼子のように新しくされて、彼は青年のころに戻る。'),
('JPN', '约伯记', 18, 33, 26, '彼は、神に祈ると受け入れられる。彼は歓喜の声をもって御顔を仰ぎ、神はその人の義に報いてくださる。'),
('JPN', '约伯记', 18, 33, 27, '彼は人々を見つめて言う。「私は罪ある者で、真っ直ぐなことを曲げてきた。しかし私は、当然の報いを受けなかった。'),
('JPN', '约伯记', 18, 33, 28, '神は、私が滅びの穴に下らないように、私のたましいを贖い出してくださった。私のいのちは光を見ることができる」と。'),
('JPN', '约伯记', 18, 33, 29, '見よ、このすべてのことを神は行われる。二度も三度も、人に対して。'),
('JPN', '约伯记', 18, 33, 30, '人のたましいを滅びの穴から引き戻し、いのちの光で照らされる。'),
('JPN', '约伯记', 18, 33, 31, 'ヨブよ、耳を傾けて私に聞け。黙れ。この私が語る。'),
('JPN', '约伯记', 18, 33, 32, 'もし、ことばがあるなら、私に返事をせよ。言え。あなたが正しければ、それを私は喜ぶから。'),
('JPN', '约伯记', 18, 33, 33, 'もし、ことばがないなら、私に聞け。黙れ。私はあなたに知恵を教えよう。'),
('JPN', '约伯记', 18, 34, 1, 'エリフはさらに言った。'),
('JPN', '约伯记', 18, 34, 2, '知恵のある人々よ、私のことばを聞け。知識のある人々よ、私に耳を傾けよ。'),
('JPN', '约伯记', 18, 34, 3, '耳はことばを聞き分け、口は食物を味わうからだ。'),
('JPN', '约伯记', 18, 34, 4, 'さあ、私たちのために正しいことを選び、私たちの間で、何が良いことかをよく知ろう。'),
('JPN', '约伯记', 18, 34, 5, 'ヨブはこう言っているからだ。「私は正しい。神が私の正義を取り去ったのだ。'),
('JPN', '约伯记', 18, 34, 6, '私の正義に反して、私は偽りを言えるだろうか。背きがないのに、私の矢傷は治らない。」'),
('JPN', '约伯记', 18, 34, 7, 'ヨブのような人がほかにいるだろうか。彼は嘲りを水のように飲み、'),
('JPN', '约伯记', 18, 34, 8, '不法を行う者どもとよく交わり、悪人たちとともに歩む。'),
('JPN', '约伯记', 18, 34, 9, '彼は言っている。「神に喜ばれようとしても、それは人の役に立たない。」'),
('JPN', '约伯记', 18, 34, 10, 'だから、あなたがた良識のある人々よ、私に聞け。神が悪を行うなど、全能者が不正をするなど、絶対にあり得ない。'),
('JPN', '约伯记', 18, 34, 11, '神は、人の行いに応じて報いをし、それぞれをその道にしたがって取り扱われる。'),
('JPN', '约伯记', 18, 34, 12, '神は決して悪を行わない。全能者はさばきを曲げない。'),
('JPN', '约伯记', 18, 34, 13, 'だれが、この地を神にゆだねたのか。だれが、全世界を神に任せたのか。'),
('JPN', '约伯记', 18, 34, 14, 'もし、神がご自分だけに心を留め、その霊と息をご自分に集められたら、'),
('JPN', '约伯记', 18, 34, 15, 'すべての肉なるものはともに息絶え、人は土のちりに帰る。'),
('JPN', '约伯记', 18, 34, 16, '悟ることができるなら、これを聞け。私の言うことに耳を傾けよ。'),
('JPN', '约伯记', 18, 34, 17, 'いったい、公正を憎む者が、治めることができるだろうか。正しく力ある方を不義に定めることができるだろうか。'),
('JPN', '约伯记', 18, 34, 18, '人が王に向かって「よこしまな者」と言い、高貴な人に向かって「悪者」と言えるだろうか。'),
('JPN', '约伯记', 18, 34, 19, 'この方は、首長たちをえこひいきせず、上流の人を貧しい民より重んじることはない。彼らはみな、神の御手のわざだからだ。'),
('JPN', '约伯记', 18, 34, 20, '彼らは瞬く間に、それも真夜中に死に、民は動揺のうちにいなくなる。強い者たちも人の手によらずに取り去られる。'),
('JPN', '约伯记', 18, 34, 21, '神の御目が人の道の上にあり、その歩みのすべてを神が見ておられるからだ。'),
('JPN', '约伯记', 18, 34, 22, '不法を行う者どもが身を隠せる闇はなく、暗黒もない。'),
('JPN', '约伯记', 18, 34, 23, '神は人について、それ以上調べる必要はない。さばきのときに、神の前に出させてまでして。'),
('JPN', '约伯记', 18, 34, 24, '神は力ある者を、取り調べなしに打ち滅ぼし、彼らに代えてほかの者たちを立てられる。'),
('JPN', '约伯记', 18, 34, 25, '神は彼らのしわざを知っており、夜に彼らを打ち倒される。彼らは砕かれる。'),
('JPN', '约伯记', 18, 34, 26, '神は、人々の見ているところで、彼らをその邪悪さのゆえに打ちたたかれる。'),
('JPN', '约伯记', 18, 34, 27, 'それは、彼らが神に背いて従わず、神のどの道にも心を留めなかったからだ。'),
('JPN', '约伯记', 18, 34, 28, 'こうして、弱い者の叫びを神に届かせ、神は苦しむ者たちの叫びを聞き入れられる。'),
('JPN', '约伯记', 18, 34, 29, '神が黙っておられるなら、だれがとがめることができるだろうか。神が御顔を隠しておられるなら、だれが神を認めることができるだろうか。一つの国民においても、一人の人間においても同様だ。'),
('JPN', '约伯记', 18, 34, 30, 'それは、神を敬わない人間が治めたり、民を罠にかけたりしないようにするためだ。'),
('JPN', '约伯记', 18, 34, 31, '神に向かってだれかが言ったか。「私は懲らしめを受けました。私はもう悪いことはいたしません。'),
('JPN', '约伯记', 18, 34, 32, '私が見ていないことを、あなたが私に教えてください。私が不正をしたのでしたら、もういたしません」と。'),
('JPN', '约伯记', 18, 34, 33, 'あなたが反対するからといって、神はあなたの願うとおりに報復されるだろうか。私ではなく、あなたが選ぶがよい。あなたの知っていることを言うがよい。'),
('JPN', '约伯记', 18, 34, 34, '良識のある人々や、私に聞く、知恵のある人は私に言うだろう。'),
('JPN', '约伯记', 18, 34, 35, '「ヨブは知識もなしに語る。彼のことばは聡明さに欠けている」と。'),
('JPN', '约伯记', 18, 34, 36, 'どうか、ヨブが最後まで試されるように。彼は不法者のように、ことばを返すからだ。'),
('JPN', '约伯记', 18, 34, 37, '彼は自分の罪にさらに背きを加え、私たちの間で手を打ち鳴らし、神に対してことば数を多くする。'),
('JPN', '约伯记', 18, 35, 1, 'エリフはさらに言った。'),
('JPN', '约伯记', 18, 35, 2, 'あなたは、このことが正義によると見なしているのか。「私の義は神からだ」とでも言うのか。'),
('JPN', '约伯记', 18, 35, 3, 'というのは、あなたがこう言っているからだ。「何があなたの役に立つのでしょうか。私が罪から離れると、どんな利益があるのでしょうか」と。'),
('JPN', '约伯记', 18, 35, 4, '私はあなたにことばを返そう。あなたとともにいる友人たちにも。'),
('JPN', '约伯记', 18, 35, 5, '天を仰ぎ見よ。あなたより、はるかに高い雲をよく見よ。'),
('JPN', '约伯记', 18, 35, 6, 'あなたが罪を犯したとしても、あなたは神に対して何ができるのか。あなたの背きが多くあるとしても、神に対して何をなし得るのか。'),
('JPN', '约伯记', 18, 35, 7, 'あなたが正しかったとしても、神に何を与えられるのか。神は、あなたの手から何を受けられるのか。'),
('JPN', '约伯记', 18, 35, 8, 'あなたの悪は、ただあなたのような人間に、あなたの正しさは、人の子に関わるだけだ。'),
('JPN', '约伯记', 18, 35, 9, '人々は、激しい抑圧のために泣き叫び、偉大な者の腕のために、助けを叫び求める。'),
('JPN', '约伯记', 18, 35, 10, 'しかし、だれも問わない。「私の造り主である神はどこにおられるのか。夜、ほめ歌を下さる方は。'),
('JPN', '约伯记', 18, 35, 11, '地の獣に教えるより、私たちに多くを教え、空の鳥より、私たちを賢くする方は」と。'),
('JPN', '约伯记', 18, 35, 12, 'そこでは、彼らが泣き叫んでも神は答えない。悪人がおごり高ぶっているからだ。'),
('JPN', '约伯记', 18, 35, 13, '神は決して偽りの叫びを聞き入れず、全能者はこれに心を留めない。'),
('JPN', '约伯记', 18, 35, 14, '「神を見られない」とあなたが言うときには、なおさらだ。しかし訴えは神の前にある。あなたは神を待て。'),
('JPN', '约伯记', 18, 35, 15, 'しかし今、神は怒って罰しないだろうか。ひどい罪を知らずにいるだろうか。'),
('JPN', '约伯记', 18, 35, 16, 'ヨブは空しい口を開き、知識もなしに、自分の言い分を並べ立てている。'),
('JPN', '约伯记', 18, 36, 1, 'エリフはさらに続けて言った。'),
('JPN', '约伯记', 18, 36, 2, 'しばらく待て。あなたに示そう。まだ神のために言い分があるからだ。'),
('JPN', '约伯记', 18, 36, 3, '私は遠くから私の意見を持って来て、私の造り主に義を返そう。'),
('JPN', '约伯记', 18, 36, 4, 'まことに、私の言い分は偽りではない。知識の完全な方が、あなたのそばにおられるのだ。'),
('JPN', '约伯记', 18, 36, 5, '見よ。神は強いが、だれをも蔑まれない。その理解の力は強い。'),
('JPN', '约伯记', 18, 36, 6, '神は悪しき者を生かしてはおかず、苦しむ者には権利を与えられる。'),
('JPN', '约伯记', 18, 36, 7, '神は正しい者から目を離さず、彼らを王座にある王たちとともに、永遠に座に着かせる。こうして彼らは高くなる。'),
('JPN', '约伯记', 18, 36, 8, 'もし、彼らが鎖で縛られ、苦しみの縄に捕らえられたら、'),
('JPN', '约伯记', 18, 36, 9, '神は彼らの行いを彼らに告げられる。彼らの背きを。彼らがおごり高ぶったからである。'),
('JPN', '约伯记', 18, 36, 10, '神は彼らの耳を開いて戒め、不法から立ち返るように命じる。'),
('JPN', '约伯记', 18, 36, 11, 'もし彼らが聞き入れて神に仕えるなら、彼らは自分の日々を幸せのうちに、自分の年々を楽しみのうちに全うする。'),
('JPN', '约伯记', 18, 36, 12, 'しかし、もし聞き入れなければ、彼らは槍によって滅び、知識のないまま息絶える。'),
('JPN', '约伯记', 18, 36, 13, '心で神を敬わない者は怒りを蓄え、神が彼らを縛るときでも、助けを叫び求めない。'),
('JPN', '约伯记', 18, 36, 14, '彼らは若くして死に、そのいのちは腐れている。'),
('JPN', '约伯记', 18, 36, 15, '神は苦しむ人をその苦しみの中で助け出し、抑圧の中で彼らの耳を開かれる。'),
('JPN', '约伯记', 18, 36, 16, '神はまた、あなたを苦難の中から誘い出し、束縛のない広いところに導かれる。豊かな食物が備えられた、食卓での安らぎに。'),
('JPN', '约伯记', 18, 36, 17, 'あなたには悪しき者へのさばきが満ちている。さばきと公正があなたを捕らえる。'),
('JPN', '约伯记', 18, 36, 18, 'だからあなたは、憤って、豊かさに誘い込まれないようにせよ。身代金が多いからといって、それに惑わされないようにせよ。'),
('JPN', '约伯记', 18, 36, 19, 'あなたの叫びが並べ立てられても、力の限りが尽くされても、それは役に立たないのではないか。'),
('JPN', '约伯记', 18, 36, 20, '人々が取り去られる夜を、あえぎ求めてはならない。'),
('JPN', '约伯记', 18, 36, 21, '不法に向かわないように注意せよ。あなたは苦しみよりも、これを選んだのだから。'),
('JPN', '约伯记', 18, 36, 22, '見よ、神は力にすぐれておられる。神のような教師が、だれかいるだろうか。'),
('JPN', '约伯记', 18, 36, 23, 'だれが神にその道を指図したのか。だれが「あなたは不正をした」と言ったのか。'),
('JPN', '约伯记', 18, 36, 24, '神のみわざを覚えて賛美せよ。人々がほめ歌った、そのみわざを。'),
('JPN', '约伯记', 18, 36, 25, 'すべての人がこれを見、人が遠くからこれを眺める。'),
('JPN', '约伯记', 18, 36, 26, '見よ。神はいと高く、私たちには知ることができない。その年の数も測り知ることができない。'),
('JPN', '约伯记', 18, 36, 27, '神は水のしずくを引き上げ、それが雨を滴らせて、水の流れとなる。'),
('JPN', '约伯记', 18, 36, 28, '雨雲がこれを降らせ、人の上に豊かに滴らせる。'),
('JPN', '约伯记', 18, 36, 29, 'いったい、だれが濃い雲の広がりと、その幕屋のとどろきを理解できるだろうか。'),
('JPN', '约伯记', 18, 36, 30, '見よ。神はご自分の光をその上に照り渡らせ、また、海の底をおおわれる。'),
('JPN', '约伯记', 18, 36, 31, '神はこれらによって民をさばき、食物を豊かにお与えになる。'),
('JPN', '约伯记', 18, 36, 32, '神は稲妻を両手に包み、これに命じて的を撃たせられる。'),
('JPN', '约伯记', 18, 36, 33, 'その雷鳴は、神について告げ、家畜もまた、起こることについて告げる。'),
('JPN', '约伯记', 18, 37, 1, 'これによって私の心は震え、そこから離れ去るほどだ。'),
('JPN', '约伯记', 18, 37, 2, 'よく聞け。その御声が荒れ狂うのを。その御口から出るとどろきを。'),
('JPN', '约伯记', 18, 37, 3, '神は、天の下のいたるところで放たれる。その稲妻を、地の隅々までも。'),
('JPN', '约伯记', 18, 37, 4, 'その後で雷が鳴りとどろく。神はいかめしい声で雷鳴をとどろかせ、その御声が聞こえるとき、手加減をなさらない。'),
('JPN', '约伯记', 18, 37, 5, '神は御声で、驚くほどに雷鳴をとどろかせ、私たちの知り得ない大きなことをされる。'),
('JPN', '约伯记', 18, 37, 6, '神は雪に対して、地に降れと命じ、夕立に、激しい大雨にも命じられる。'),
('JPN', '约伯记', 18, 37, 7, '神はすべての人の手を封じ込められる。神の造った人間が知るために。'),
('JPN', '约伯记', 18, 37, 8, '獣は巣にもぐり、洞穴の中にうずくまる。'),
('JPN', '约伯记', 18, 37, 9, 'つむじ風は天の間から、寒さは北の方から来る。'),
('JPN', '约伯记', 18, 37, 10, '神の息によって氷が張り、広々とした水が凍りつく。'),
('JPN', '约伯记', 18, 37, 11, '神は濃い雲に水気を含ませ、雲がその稲妻を放つ。'),
('JPN', '约伯记', 18, 37, 12, 'それは神の指図によって巡り回り、事を行う。神が命じるすべてのことを、世界の地の面で。'),
('JPN', '约伯记', 18, 37, 13, '神は、懲らしめのため、ご自分の地のため、または恵みのために、これが起こるようにされる。'),
('JPN', '约伯记', 18, 37, 14, 'ヨブよ、これに耳を傾けよ。神の奇しいみわざを、立ち止まって考えよ。'),
('JPN', '约伯记', 18, 37, 15, 'あなたは知っているか。神がどのようにこれらに命じ、その雲に稲妻をひらめかせられるのかを。'),
('JPN', '约伯记', 18, 37, 16, 'あなたは知っているか。濃い雲のつり合いを、知識の完全な方の不思議なみわざを。'),
('JPN', '约伯记', 18, 37, 17, 'また、南風で地が黙するときに、あなたの衣がいかに熱くなるかを。'),
('JPN', '约伯记', 18, 37, 18, 'あなたは大空を神とともに張り広げられるのか。鋳た鏡のように硬いものを。'),
('JPN', '约伯记', 18, 37, 19, '神に何と言うべきかを私たちに教えよ。闇があるので、ことばを並べることができない。'),
('JPN', '约伯记', 18, 37, 20, '私が語りたいと、神に伝えられるだろうか。人がことばを発すれば、その人は必ず滅ぼされる。'),
('JPN', '约伯记', 18, 37, 21, '今、光は見ることができない。それは雨雲の中に輝いている。しかし、風が吹いて雲を払いのけると、'),
('JPN', '约伯记', 18, 37, 22, '北から黄金の輝きが現れ、神の周りには恐るべき威厳がある。'),
('JPN', '约伯记', 18, 37, 23, '私たちが見出すことのできない全能者は、力にすぐれた方。さばきと正義に富み、苦しめることをなさらない。'),
('JPN', '约伯记', 18, 37, 24, 'だから、人々は神を恐れなければならない。神は心に知恵ある者を顧みられないだろうか。'),
('JPN', '约伯记', 18, 38, 1, '主は嵐の中からヨブに答えられた。'),
('JPN', '约伯记', 18, 38, 2, '知識もなしに言い分を述べて、摂理を暗くするこの者はだれか。'),
('JPN', '约伯记', 18, 38, 3, 'さあ、あなたは勇士のように腰に帯を締めよ。わたしはあなたに尋ねる。わたしに示せ。'),
('JPN', '约伯记', 18, 38, 4, 'わたしが地の基を定めたとき、あなたはどこにいたのか。分かっているなら、告げてみよ。'),
('JPN', '约伯记', 18, 38, 5, 'あなたは知っているはずだ。だれがその大きさを定め、だれがその上に測り縄を張ったかを。'),
('JPN', '约伯记', 18, 38, 6, 'その台座は何の上にはめ込まれたのか。あるいは、その要の石はだれが据えたのか。'),
('JPN', '约伯记', 18, 38, 7, '明けの星々がともに喜び歌い、神の子たちがみな喜び叫んだときに。'),
('JPN', '约伯记', 18, 38, 8, '海が噴き出て、胎内から流れ出たとき、だれが戸でこれを閉じ込めたのか。'),
('JPN', '约伯记', 18, 38, 9, 'そのとき、わたしは雲をその衣とし、暗黒をその産衣とした。'),
('JPN', '约伯记', 18, 38, 10, 'わたしは、これを区切って境を定め、かんぬきと戸を設けて、'),
('JPN', '约伯记', 18, 38, 11, '言った。「ここまでは来てもよい。しかし、これ以上はいけない。おまえの高ぶる波はここでとどまれ」と。'),
('JPN', '约伯记', 18, 38, 12, 'あなたは生まれてこのかた、朝に対して命令を下し、暁に対してあるべき場所を指し示して、'),
('JPN', '约伯记', 18, 38, 13, 'これに地の縁をつかませ、悪しき者をそこから振り落としたことがあるか。'),
('JPN', '约伯记', 18, 38, 14, '地は押印された粘土のように姿を変え、そこにあるものは王服のように彩られる。'),
('JPN', '约伯记', 18, 38, 15, 'その光は悪しき者から退けられ、振り上げられた腕は折られる。'),
('JPN', '约伯记', 18, 38, 16, 'あなたは海の源まで行ったことがあるか。深淵の奥底を歩き回ったことがあるか。'),
('JPN', '约伯记', 18, 38, 17, '死の門があなたに現れたことがあるか。死の陰の門を見たことがあるか。'),
('JPN', '约伯记', 18, 38, 18, '地の広さを見極めたことがあるか。そのすべてを知っているなら、告げてみよ。'),
('JPN', '约伯记', 18, 38, 19, '光の住む所への道はどこか。闇のあるその場所はどこか。'),
('JPN', '约伯记', 18, 38, 20, '光をその国境まで連れて行くというのか。闇の家に至る通りを見分けるというのか。'),
('JPN', '约伯记', 18, 38, 21, 'あなたはよく知っているはずだ。そのとき、あなたは生まれていて、あなたの日数は多いのだから。'),
('JPN', '约伯记', 18, 38, 22, 'あなたは雪の倉に入ったことがあるか。雹の倉を見たことがあるか。'),
('JPN', '约伯记', 18, 38, 23, 'これらは、わたしがとどめているのだ。苦難の時のため、争いと戦の日のために。'),
('JPN', '约伯记', 18, 38, 24, '光が分かれる道はどこか。東風が地の上で分かれ広がる道は。'),
('JPN', '约伯记', 18, 38, 25, 'だれが、大水のために水路を、稲光のために道を切り開き、'),
('JPN', '约伯记', 18, 38, 26, '人のいない地、人間のいない荒野に雨を降らせ、'),
('JPN', '约伯记', 18, 38, 27, '荒れ果てた廃墟の地を満ち足らせ、それに若草を生えさせるのか。'),
('JPN', '约伯记', 18, 38, 28, '雨に父があるのか。露のしずくはだれが生んだのか。'),
('JPN', '约伯记', 18, 38, 29, '氷はだれの胎から出て来たのか。空の白い霜はだれが生んだのか。'),
('JPN', '约伯记', 18, 38, 30, '水は姿を変えて石のようになり、深い淵の面は凍る。'),
('JPN', '约伯记', 18, 38, 31, 'あなたはすばるの鎖を結ぶことができるか。オリオン座の綱を解くことができるか。'),
('JPN', '约伯记', 18, 38, 32, 'あなたは十二宮をその時にかなって、引き出すことができるか。牡牛座をその子の星とともに導くことができるか。'),
('JPN', '约伯记', 18, 38, 33, 'あなたは天の掟を知っているか。地にその法則を立てることができるか。'),
('JPN', '约伯记', 18, 38, 34, 'あなたの声を密雲にまであげ、みなぎる水にあなたをおおわせることができるか。'),
('JPN', '约伯记', 18, 38, 35, 'あなたは稲妻を向こうに行かせ、あなたに向かって「私たちはここです」と言わせることができるか。'),
('JPN', '约伯记', 18, 38, 36, 'だれが、隠されたところに知恵を置いたのか。だれが、秘められたところに悟りを与えたのか。'),
('JPN', '约伯记', 18, 38, 37, 'だれが知恵をもって、雨雲を数えることができるか。だれが天の水袋を傾けることができるか。'),
('JPN', '约伯记', 18, 38, 38, '土が溶け合って塊となり、土くれが硬く固まるときに。'),
('JPN', '约伯记', 18, 38, 39, 'あなたは雌獅子のために獲物を狩り若い獅子の食欲を満たすことができるか。'),
('JPN', '约伯记', 18, 38, 40, 'それらが洞穴に伏し、茂みの中で待ち伏せしているときに。'),
('JPN', '约伯记', 18, 38, 41, '烏に餌を備えるのはだれか。烏の子が神に向かって鳴き叫び、食物がなくてさまようときに。'),
('JPN', '约伯记', 18, 39, 1, 'あなたは岩間の野やぎが子を産む時を知っているか。雌鹿が子を産むのを見守ったことがあるか。'),
('JPN', '约伯记', 18, 39, 2, 'あなたはこれらがはらんでいる月を、数えることができるか。それらが子を産む時を知っているか。'),
('JPN', '约伯记', 18, 39, 3, 'それらは身をかがめて子を産み落とし、その胎児を放り出す。'),
('JPN', '约伯记', 18, 39, 4, 'その子たちは強くなり、野で大きくなる。すると出て行って、元のところには帰らない。'),
('JPN', '约伯记', 18, 39, 5, 'だれが野ろばを解き放ったのか。だれが野生のろばの綱をほどいたのか。'),
('JPN', '约伯记', 18, 39, 6, 'わたしが、荒れた地をその家とし、不毛の地をその住みかとしたのだ。'),
('JPN', '约伯记', 18, 39, 7, 'それは町の騒ぎをあざ笑い、追い立てる者の叫び声を聞かない。'),
('JPN', '约伯记', 18, 39, 8, '山々を自分の牧場として歩き回り、青草なら何でも探し求める。'),
('JPN', '约伯记', 18, 39, 9, '野牛が喜んであなたに仕えるだろうか。あなたの飼葉桶のそばで夜を過ごすだろうか。'),
('JPN', '约伯记', 18, 39, 10, 'あなたはあぜ溝で、野牛に手綱をかけることができるか。それが、あなたに従って谷間を耕すだろうか。'),
('JPN', '约伯记', 18, 39, 11, 'その力が強いからといって、あなたはそれに拠り頼むだろうか。あなた自身の働きをこれに任せるだろうか。'),
('JPN', '约伯记', 18, 39, 12, 'あなたはそう信じているのか。それがあなたの穀物を持ち帰り、あなたの打ち場で、これを集めるとでも。'),
('JPN', '约伯记', 18, 39, 13, 'だちょうは翼を誇らしげに羽ばたかせるが、その羽はこうのとりの羽毛のようだろうか。'),
('JPN', '约伯记', 18, 39, 14, 'だちょうは卵を地面に置き去りにし、これを砂の上で温まるに任せ、'),
('JPN', '约伯记', 18, 39, 15, '自分の足がそれをつぶすかもしれないことを忘れている。野の獣が踏みつけるかもしれないことも。'),
('JPN', '约伯记', 18, 39, 16, 'だちょうは自分の子を、自分のものでないかのように荒く扱い、その産みの苦しみが、無駄になることも全く気にしない。'),
('JPN', '约伯记', 18, 39, 17, '神がこれに知恵を忘れさせ、これに悟りを授けなかったからだ。'),
('JPN', '约伯记', 18, 39, 18, 'それが高く飛び跳ねるとき、馬とその乗り手をあざ笑う。'),
('JPN', '约伯记', 18, 39, 19, 'あなたが馬に力を与えるのか。その首にたてがみを付けるのか。'),
('JPN', '约伯记', 18, 39, 20, 'あなたはこれを、いなごのように飛び跳ねさせることができるのか。その威厳あるいななきは恐ろしい。'),
('JPN', '约伯记', 18, 39, 21, '馬は谷間で、前かきをして力を喜び、武器に立ち向かって進んで行く。'),
('JPN', '约伯记', 18, 39, 22, '恐怖をあざ笑って、ひるむことなく、剣の前から退くことはない。'),
('JPN', '约伯记', 18, 39, 23, '矢筒はその上でうなり、槍と投げ槍はきらめく。'),
('JPN', '约伯记', 18, 39, 24, '荒れ狂って、地を駆け回り、角笛の音に、じっとしてはいられない。'),
('JPN', '约伯记', 18, 39, 25, '角笛が鳴るごとに、ヒヒーンといななき、遠くから戦いを嗅ぎつける。隊長の怒号、ときの声さえも。'),
('JPN', '约伯记', 18, 39, 26, 'あなたの考えによってか。鷹が舞い上がり、南にその翼を広げるのは。'),
('JPN', '约伯记', 18, 39, 27, 'あなたの命令によってか。鷲が高く上がり、その巣を高いところに作るのは。'),
('JPN', '约伯记', 18, 39, 28, 'それは岩場に宿って住み、近寄りがたい切り立つ岩の上にいる。'),
('JPN', '约伯记', 18, 39, 29, 'そこから獲物をうかがい、その目は遠くまで見渡す。'),
('JPN', '约伯记', 18, 39, 30, 'ひなは血を吸い、殺されたもののところに、それはいる。'),
('JPN', '约伯记', 18, 40, 1, '主はヨブに答えられた。'),
('JPN', '约伯记', 18, 40, 2, '非難する者が全能者と争おうとするのか。神を責める者は、それに答えよ。'),
('JPN', '约伯记', 18, 40, 3, 'ヨブは主に答えた。'),
('JPN', '约伯记', 18, 40, 4, 'ああ、私は取るに足りない者です。あなたに何と口答えできるでしょう。私はただ手を口に当てるばかりです。'),
('JPN', '约伯记', 18, 40, 5, '一度、私は語りました。もう答えません。二度、語りました。もう繰り返しません。'),
('JPN', '约伯记', 18, 40, 6, '主は嵐の中からヨブに答えられた。'),
('JPN', '约伯记', 18, 40, 7, 'さあ、あなたは勇士のように腰に帯を締めよ。わたしはあなたに尋ねる。わたしに示せ。'),
('JPN', '约伯记', 18, 40, 8, 'あなたはわたしのさばきを無効にするつもりか。自分を義とするため、わたしを不義に定めるのか。'),
('JPN', '约伯记', 18, 40, 9, 'あなたには神のような腕があるのか。神のような声で雷鳴をとどろき渡らせるのか。'),
('JPN', '约伯记', 18, 40, 10, 'さあ、誉れと気高さで身を飾り、威厳と威光を身にまとえ。'),
('JPN', '约伯记', 18, 40, 11, 'あなたの激しい怒りを吐き散らし、すべて高ぶる者を見て、これを低くせよ。'),
('JPN', '约伯记', 18, 40, 12, 'すべて高ぶる者を見て、これを押さえ、悪者どもを、その場で踏みにじれ。'),
('JPN', '约伯记', 18, 40, 13, '彼らをともに土のちりの中に隠し、その顔を隠れた所につなぎとめよ。'),
('JPN', '约伯记', 18, 40, 14, 'そうすれば、わたしもあなたをたたえて言う。「あなたの右の手は自分を救うことができる」と。'),
('JPN', '约伯记', 18, 40, 15, 'さあ、河馬を見よ。これはあなたと並べてわたしが造ったもの。牛のように草をはむ。'),
('JPN', '约伯记', 18, 40, 16, '見よ。その力は腰にあり、その強さは腹の筋にある。'),
('JPN', '约伯记', 18, 40, 17, '尾は杉の木のように垂れ下がり、ももの筋は絡み合っている。'),
('JPN', '约伯记', 18, 40, 18, '骨は青銅の管、肋骨は鉄の棒のようだ。'),
('JPN', '约伯记', 18, 40, 19, 'これは神の作品の第一のもの、これを造った者が、その剣でこれに近づく。'),
('JPN', '约伯记', 18, 40, 20, '山々はこの獣のために産物をもたらし、野の獣もみなそこで戯れる。'),
('JPN', '约伯记', 18, 40, 21, '蓮の下にそれは横たわる。葦の茂み、沼地の中で。'),
('JPN', '约伯记', 18, 40, 22, '蓮はこれをその陰でおおい、川の柳はこれを囲む。'),
('JPN', '约伯记', 18, 40, 23, 'たとえ川があふれても、慌てない。ヨルダン川が口に注ぎ込んでも、動じない。'),
('JPN', '约伯记', 18, 40, 24, 'その目をつかんで、これを捕らえられるか。罠にかけて、その鼻を突き通せるか。'),
('JPN', '约伯记', 18, 41, 1, 'あなたは釣り針でレビヤタンを釣り上げることができるか。輪縄でその舌を押さえつけることができるか。'),
('JPN', '约伯记', 18, 41, 2, 'あなたは葦をその鼻に通すことができるか。鉤をそのあごに突き通すことができるか。'),
('JPN', '约伯记', 18, 41, 3, 'これが、しきりにあなたに哀願し、優しく語りかけるだろうか。'),
('JPN', '约伯记', 18, 41, 4, 'これがあなたと契約を結び、あなたがこれを捕らえて、永久に奴隷とすることになるだろうか。'),
('JPN', '约伯记', 18, 41, 5, 'あなたは鳥と戯れるように、これと戯れ、娘たちのために、これをつなぐことができるか。'),
('JPN', '约伯记', 18, 41, 6, '漁師仲間がこれを競りにかけ、商人たちの間で分けるだろうか。'),
('JPN', '约伯记', 18, 41, 7, 'あなたは銛でその皮を、やすでその頭を突くことができるだろうか。'),
('JPN', '约伯记', 18, 41, 8, 'その上にあなたの手を置いてみよ。その戦いを思い出して、二度と手を出すな。'),
('JPN', '约伯记', 18, 41, 9, '見よ。それに立ち向かう期待は裏切られる。それを見ただけで圧倒されるではないか。'),
('JPN', '约伯记', 18, 41, 10, 'それを起こすほどの狂暴な者はいない。そうであれば、だれがいったい、わたしの前に立つことができるだろうか。'),
('JPN', '约伯记', 18, 41, 11, 'だれが、まずわたしに与えたというのか。わたしがそれに報いなければならないほどに。天の下にあるものはみな、わたしのものだ。'),
('JPN', '约伯记', 18, 41, 12, 'そのからだの部分についてわたしは黙ってはいられない。それの力強さと、その体格の見事さについて。'),
('JPN', '约伯记', 18, 41, 13, 'だれが、その外套をはぎ取ることができるか。胸当ての折り目の間に入ることができるか。'),
('JPN', '约伯记', 18, 41, 14, 'だれが、その顔の戸を開けることができるか。その歯の周りには恐怖がある。'),
('JPN', '约伯记', 18, 41, 15, 'その背は並んだ盾、封印したように固く閉じている。'),
('JPN', '约伯记', 18, 41, 16, '一つ一つぴったり付いて、風もその間を通れない。'),
('JPN', '约伯记', 18, 41, 17, '互いにくっつき、固くつながって離れない。'),
('JPN', '约伯记', 18, 41, 18, 'そのくしゃみは光を放ち、その目は暁のまぶたのようだ。'),
('JPN', '约伯记', 18, 41, 19, 'その口からは、たいまつが燃え出し、火花が噴き出す。'),
('JPN', '约伯记', 18, 41, 20, 'その鼻からは煙が出て、煮え立つ釜や、燃える葦のようだ。'),
('JPN', '约伯记', 18, 41, 21, 'その息は炭火をおこし、その口からは炎が出る。'),
('JPN', '约伯记', 18, 41, 22, 'その首には力が宿り、その前には恐れが踊る。'),
('JPN', '约伯记', 18, 41, 23, 'その肉のひだはつなぎ合わされ、その身に固く付いて、揺るがない。'),
('JPN', '约伯记', 18, 41, 24, 'その心臓は石のように硬く、臼の下石のように硬い。'),
('JPN', '约伯记', 18, 41, 25, 'それが起き上がると、力ある者もおじけづき、おろおろして逃げ惑う。'),
('JPN', '约伯记', 18, 41, 26, 'それを剣で襲っても無駄だ。槍でも、投げ矢でも、矢じりでも。'),
('JPN', '约伯记', 18, 41, 27, 'それは鉄を藁のように、青銅を腐った木のように見なす。'),
('JPN', '约伯记', 18, 41, 28, '矢によっても、それが逃げるようにはできず、石投げの石も、それには藁となる。'),
('JPN', '约伯记', 18, 41, 29, 'こん棒さえ藁のように見なし、投げ槍のうなる音をあざ笑う。'),
('JPN', '约伯记', 18, 41, 30, 'その下腹は鋭い土器のかけら、それは打穀機のように泥の上に身を伸ばす。'),
('JPN', '约伯记', 18, 41, 31, 'それは深みを釜のように沸き立たせ、海を、香油をかき混ぜる鍋のようにする。'),
('JPN', '约伯记', 18, 41, 32, 'それが通った跡には光が輝き、深淵は白髪のように見なされる。'),
('JPN', '约伯记', 18, 41, 33, '地の上に、これと似たものはなく、恐れを知らないものとして造られた。'),
('JPN', '约伯记', 18, 41, 34, '高いものすべてを見下ろし、誇り高い獣すべての王である。'),
('JPN', '约伯记', 18, 42, 1, 'ヨブは主に答えた。'),
('JPN', '约伯记', 18, 42, 2, 'あなたには、すべてのことができること、どのような計画も不可能ではないことを、私は知りました。'),
('JPN', '约伯记', 18, 42, 3, 'あなたは言われます。「知識もなしに摂理をおおい隠す者はだれか」と。確かに私は、自分の理解できないことを告げてしまいました。自分では知り得ない、あまりにも不思議なことを。'),
('JPN', '约伯记', 18, 42, 4, 'あなたは言われます。「さあ、聞け。わたしが語る。わたしがあなたに尋ねる。わたしに示せ」と。'),
('JPN', '约伯记', 18, 42, 5, '私はあなたのことを耳で聞いていました。しかし今、私の目があなたを見ました。'),
('JPN', '约伯记', 18, 42, 6, 'それで、私は自分を蔑み、悔いています。ちりと灰の中で。'),
('JPN', '约伯记', 18, 42, 7, '主がこれらのことばをヨブに語った後、主はテマン人エリファズに言われた。「わたしの怒りはあなたとあなたの二人の友に向かって燃える。あなたがたが、わたしのしもべヨブのように、わたしについて確かなことを語らなかったからだ。'),
('JPN', '约伯记', 18, 42, 8, '今、あなたがたは雄牛七頭と雄羊七匹を取って、わたしのしもべヨブのところに行き、自分たちのために全焼のささげ物を献げよ。わたしのしもべヨブがあなたがたのために祈る。わたしは彼の願いを受け入れるので、あなたがたの愚行に報いるようなことはしない。あなたがたは、わたしのしもべヨブのように、わたしについて確かなことを語らなかったが。」'),
('JPN', '约伯记', 18, 42, 9, 'テマン人エリファズと、シュアハ人ビルダデと、ナアマ人ツォファルは行って、主が彼らに命じられたようにした。すると主はヨブの願いを受け入れられた。'),
('JPN', '约伯记', 18, 42, 10, 'ヨブがその友人たちのために祈ったとき、主はヨブを元どおりにされた。さらに主はヨブの財産をすべて、二倍にされた。'),
('JPN', '约伯记', 18, 42, 11, 'こうして彼のすべての兄弟、すべての姉妹、それに以前のすべての知人は、彼のところに来て、彼の家で一緒に食事をした。そして彼に同情し、主が彼の上にもたらされたすべてのわざわいについて、彼を慰めた。彼らはそれぞれ一ケシタと金の輪一つずつを彼に与えた。'),
('JPN', '约伯记', 18, 42, 12, '主はヨブの後の半生を前の半生に増して祝福された。それで彼は羊一万四千匹、らくだ六千頭、牛一千くびき、雌ろば一千頭を持つことになった。'),
('JPN', '约伯记', 18, 42, 13, 'また、息子七人、娘三人を持った。'),
('JPN', '约伯记', 18, 42, 14, '彼はその第一の娘をエミマ、第二の娘をケツィア、第三の娘をケレン・ハ・プクと名づけた。'),
('JPN', '约伯记', 18, 42, 15, 'ヨブの娘たちほど美しい女は、この地のどこにも見つからなかった。彼女たちの父は彼女たちに、その兄弟たちの間で相続地を分け与えた。'),
('JPN', '约伯记', 18, 42, 16, 'この後ヨブは百四十年生き、自分の子と、その子の子たちを四代目まで見た。'),
('JPN', '约伯记', 18, 42, 17, 'こうしてヨブは死んだ。年老いて満ち足りた生涯であった。'),
('JPN', '诗篇', 19, 1, 1, '幸いなことよ悪しき者のはかりごとに歩まず罪人の道に立たず嘲る者の座に着かない人。'),
('JPN', '诗篇', 19, 1, 2, '主のおしえを喜びとし昼も夜もそのおしえを口ずさむ人。'),
('JPN', '诗篇', 19, 1, 3, 'その人は流れのほとりに植えられた木。時が来ると実を結びその葉は枯れずそのなすことはすべて栄える。'),
('JPN', '诗篇', 19, 1, 4, '悪しき者はそうではない。まさしく風が吹き飛ばす籾殻だ。'),
('JPN', '诗篇', 19, 1, 5, 'それゆえ悪しき者はさばきに罪人は正しい者の集いに立ち得ない。'),
('JPN', '诗篇', 19, 1, 6, 'まことに正しい者の道は主が知っておられ悪しき者の道は滅び去る。'),
('JPN', '诗篇', 19, 2, 1, 'なぜ国々は騒ぎ立ちもろもろの国民は空しいことを企むのか。'),
('JPN', '诗篇', 19, 2, 2, 'なぜ地の王たちは立ち構え君主たちは相ともに集まるのか。主と主に油注がれた者に対して。'),
('JPN', '诗篇', 19, 2, 3, '「さあ彼らのかせを打ち砕き彼らの綱を解き捨てよう。」'),
('JPN', '诗篇', 19, 2, 4, '天の御座に着いておられる方は笑い主はその者どもを嘲られる。'),
('JPN', '诗篇', 19, 2, 5, 'そのとき主は怒りをもって彼らに告げ激しく怒って彼らを恐れおののかせる。'),
('JPN', '诗篇', 19, 2, 6, '「わたしがわたしの王を立てたのだ。わたしの聖なる山シオンに。」'),
('JPN', '诗篇', 19, 2, 7, '「私は主の定めについて語ろう。主は私に言われた。『あなたはわたしの子。わたしが今日あなたを生んだ。'),
('JPN', '诗篇', 19, 2, 8, 'わたしに求めよ。わたしは国々をあなたへのゆずりとして与える。地の果ての果てまであなたの所有として。'),
('JPN', '诗篇', 19, 2, 9, 'あなたは鉄の杖で彼らを牧し陶器師が器を砕くように粉々にする。』」'),
('JPN', '诗篇', 19, 2, 10, 'それゆえ今王たちよ悟れ。地をさばく者たちよ慎め。'),
('JPN', '诗篇', 19, 2, 11, '恐れつつ主に仕えよ。おののきつつ震え子に口づけせよ。'),
('JPN', '诗篇', 19, 2, 12, '主が怒りおまえたちが道で滅びないために。御怒りがすぐにも燃えようとしているからだ。幸いなことよすべて主に身を避ける人は。'),
('JPN', '诗篇', 19, 3, 1, '主よなんと私の敵が多くなり私に向かい立つ者が多くいることでしょう。'),
('JPN', '诗篇', 19, 3, 2, '多くの者が私のたましいのことを言っています。「彼には神の救いがない」と。セラ'),
('JPN', '诗篇', 19, 3, 3, 'しかし主よあなたこそ私の周りを囲む盾私の栄光私の頭を上げる方。'),
('JPN', '诗篇', 19, 3, 4, '私は声をあげて主を呼び求める。すると主はその聖なる山から私に答えてくださる。セラ'),
('JPN', '诗篇', 19, 3, 5, '私は身を横たえて眠りまた目を覚ます。主が私を支えてくださるから。'),
('JPN', '诗篇', 19, 3, 6, '私は幾万の民をも恐れない。彼らが私を取り囲もうとも。'),
('JPN', '诗篇', 19, 3, 7, '主よ立ち上がってください。私の神よお救いください。あなたは私のすべての敵の頬を打ち悪しき者の歯を砕いてくださいます。'),
('JPN', '诗篇', 19, 3, 8, '救いは主にあります。あなたの民にあなたの祝福がありますように。セラ'),
('JPN', '诗篇', 19, 4, 1, '私が呼ぶとき答えてください。私の義なる神。追いつめられたときあなたは私を解き放ってくださいました。私をあわれみ私の祈りを聞いてください。'),
('JPN', '诗篇', 19, 4, 2, '人の子たちよいつまで私の栄光を辱め空しいものを愛し偽りを慕い求めるのか。セラ'),
('JPN', '诗篇', 19, 4, 3, '知れ。主はご自分の聖徒を特別に扱われるのだ。私が呼ぶとき主は聞いてくださる。'),
('JPN', '诗篇', 19, 4, 4, '震えわななけ。罪を犯すな。心の中で語り床の上で静まれ。セラ'),
('JPN', '诗篇', 19, 4, 5, '義のいけにえを献げ主に拠り頼め。'),
('JPN', '诗篇', 19, 4, 6, '多くの者は言っています。「だれがわれわれに良い目を見させてくれるのか」と。主よどうかあなたの御顔の光を私たちの上に照らしてください。'),
('JPN', '诗篇', 19, 4, 7, 'あなたは喜びを私の心に下さいます。それは彼らに穀物と新しいぶどう酒が豊かにある時にもまさっています。'),
('JPN', '诗篇', 19, 4, 8, '平安のうちに私は身を横たえすぐ眠りにつきます。主よただあなただけが安らかに私を住まわせてくださいます。'),
('JPN', '诗篇', 19, 5, 1, '私のことばに耳を傾けてください。主よ。私のうめきを聞き取ってください。'),
('JPN', '诗篇', 19, 5, 2, '私の叫ぶ声を耳に留めてください。私の王私の神私はあなたに祈っています。'),
('JPN', '诗篇', 19, 5, 3, '主よ朝明けに私の声を聞いてください。朝明けに私はあなたの御前に備えをし仰ぎ望みます。'),
('JPN', '诗篇', 19, 5, 4, 'あなたは悪を喜ぶ神ではなくわざわいはあなたとともに住まないからです。'),
('JPN', '诗篇', 19, 5, 5, '誇り高ぶる者たちは御目の前に立つことはできません。あなたは不法を行う者をすべて憎まれます。'),
('JPN', '诗篇', 19, 5, 6, 'あなたは偽りを言う者どもを滅ぼされます。主は人の血を流す者や欺く者を忌み嫌われます。'),
('JPN', '诗篇', 19, 5, 7, 'しかし私はあなたの豊かな恵みによってあなたの家に行きあなたを恐れつつあなたの聖なる宮に向かってひれ伏します。'),
('JPN', '诗篇', 19, 5, 8, '主よ私を待ち伏せている者がいますからあなたの義によって私を導いてください。私の前にあなたの道をまっすぐにしてください。'),
('JPN', '诗篇', 19, 5, 9, '彼らの口には真実がなく心にあるのは破壊です。彼らの喉は開いた墓。彼らはその舌でへつらうのです。'),
('JPN', '诗篇', 19, 5, 10, '神よ彼らに責めを負わせてください。彼らが自分のはかりごとで倒れますように。その多くの背きのゆえに彼らを追い散らしてください。あなたに逆らっているからです。'),
('JPN', '诗篇', 19, 5, 11, 'どうかあなたに身を避ける者がみな喜びとこしえまでも喜び歌いますように。あなたが彼らをかばってくださり御名を愛する者たちがあなたを誇りますように。'),
('JPN', '诗篇', 19, 5, 12, '主よまことにあなたは正しい者を祝福し大盾のようにいつくしみでおおってくださいます。'),
('JPN', '诗篇', 19, 6, 1, '主よ御怒りで私を責めないでください。あなたの憤りで私を懲らしめないでください。'),
('JPN', '诗篇', 19, 6, 2, '主よ私をあわれんでください。私は衰えています。主よ私を癒やしてください。私の骨は恐れおののいています。'),
('JPN', '诗篇', 19, 6, 3, '私のたましいはひどく恐れおののいています。主よあなたはいつまで──。'),
('JPN', '诗篇', 19, 6, 4, '主よ帰って来て私のたましいを助け出してください。私を救ってください。あなたの恵みのゆえに。'),
('JPN', '诗篇', 19, 6, 5, '死においてはあなたを覚えることはありません。よみにおいてはだれがあなたをほめたたえるでしょう。'),
('JPN', '诗篇', 19, 6, 6, '私は嘆きで疲れ果て夜ごとに涙で寝床を漂わせふしどを大水で押し流します。'),
('JPN', '诗篇', 19, 6, 7, '私の目は苦悶で衰え私のすべての敵のゆえに弱まりました。'),
('JPN', '诗篇', 19, 6, 8, '不法を行う者たちみな私から離れて行け。主が私の泣く声を聞かれたからだ。'),
('JPN', '诗篇', 19, 6, 9, '主は私の切なる願いを聞き主は私の祈りを受け入れられる。'),
('JPN', '诗篇', 19, 6, 10, '私の敵がみな恥を見ひどく恐れおののきますように。彼らが退き恥を見ますように。瞬く間に。'),
('JPN', '诗篇', 19, 7, 1, '私の神主よ私はあなたに身を避けます。どうか追い迫るすべての者から私を救い助け出してください。'),
('JPN', '诗篇', 19, 7, 2, '彼らが獅子のように私のたましいを引き裂き助け出す者もなくさらって行かないように。'),
('JPN', '诗篇', 19, 7, 3, '私の神主よもしも私がこのことをしたのならもしも私の手に不正があるのなら'),
('JPN', '诗篇', 19, 7, 4, 'もしも私が親しい友に悪い仕打ちをしたのならまた私に敵対する者からゆえなく奪ったのなら'),
('JPN', '诗篇', 19, 7, 5, '敵が私のたましいに追い迫り追いつき私のいのちを地に踏みにじるようにし私の栄光をちりの中に埋もれさせてください。セラ'),
('JPN', '诗篇', 19, 7, 6, '主よ御怒りをもって立ち上がり私の敵の激しい怒りに対してご自身を高くし私のために目を覚ましてください。あなたはさばきを定められました。'),
('JPN', '诗篇', 19, 7, 7, '国民の群れをあなたの周りに集めその上の高いみくらにお帰りください。'),
('JPN', '诗篇', 19, 7, 8, '主は諸国の民にさばきを行われます。私の義と私にある誠実にしたがって主よ私をさばいてください。'),
('JPN', '诗篇', 19, 7, 9, 'どうか悪しき者の悪が後を絶ちあなたが正しい者を堅く立てられますように。正しい神は心の深みまで調べられます。'),
('JPN', '诗篇', 19, 7, 10, '私の盾は神にあり神は心の直ぐな人を救われます。'),
('JPN', '诗篇', 19, 7, 11, '神は正しい審判者日々憤る神。'),
('JPN', '诗篇', 19, 7, 12, '立ち返らない者には剣を研ぎ弓を張って狙いを定められます。'),
('JPN', '诗篇', 19, 7, 13, 'その者に向かって死の武器を構えその矢を燃える火矢とされます。'),
('JPN', '诗篇', 19, 7, 14, '見よその者は不法を宿し害悪をはらみ偽りを産んでいます。'),
('JPN', '诗篇', 19, 7, 15, '彼は穴を掘ってそれを深くし自分が作った穴に落ち込みます。'),
('JPN', '诗篇', 19, 7, 16, 'その害悪は自分の頭上に戻りその暴虐は自分の脳天に下ります。'),
('JPN', '诗篇', 19, 7, 17, '私は主をほめたたえます。その義にふさわしく。いと高き方主の御名をほめ歌います。'),
('JPN', '诗篇', 19, 8, 1, '主よ私たちの主よあなたの御名は全地にわたりなんと力に満ちていることでしょう。あなたのご威光は天でたたえられています。'),
('JPN', '诗篇', 19, 8, 2, '幼子たち乳飲み子たちの口を通してあなたは御力を打ち立てられました。あなたに敵対する者に応えるため復讐する敵を鎮めるために。'),
('JPN', '诗篇', 19, 8, 3, 'あなたの指のわざであるあなたの天あなたが整えられた月や星を見るに'),
('JPN', '诗篇', 19, 8, 4, '人とは何ものなのでしょう。あなたが心に留められるとは。人の子とはいったい何ものなのでしょう。あなたが顧みてくださるとは。'),
('JPN', '诗篇', 19, 8, 5, 'あなたは人を御使いよりわずかに欠けがあるものとしこれに栄光と誉れの冠をかぶらせてくださいました。'),
('JPN', '诗篇', 19, 8, 6, 'あなたの御手のわざを人に治めさせ万物を彼の足の下に置かれました。'),
('JPN', '诗篇', 19, 8, 7, '羊も牛もすべてまた野の獣も'),
('JPN', '诗篇', 19, 8, 8, '空の鳥海の魚海路を通うものも。'),
('JPN', '诗篇', 19, 8, 9, '主よ私たちの主よあなたの御名は全地にわたりなんと力に満ちていることでしょう。'),
('JPN', '诗篇', 19, 9, 1, '心を尽くして私は主に感謝をささげます。あなたの奇しいみわざのすべてを語り告げます。'),
('JPN', '诗篇', 19, 9, 2, '私はあなたを喜び誇ります。いと高き方よあなたの御名をほめ歌います。'),
('JPN', '诗篇', 19, 9, 3, '私の敵は退くとき御前でつまずきついえます。'),
('JPN', '诗篇', 19, 9, 4, 'あなたが私の正しい訴えを聞かれるからです。義の審判者として王座に着いておられるからです。'),
('JPN', '诗篇', 19, 9, 5, 'あなたは国々を叱り悪しき者を滅ぼし彼らの名をとこしえに消し去られました。'),
('JPN', '诗篇', 19, 9, 6, '敵は絶え果てました。──永遠の廃墟あなたが根こそぎにされた町々──彼らの記憶さえ消え失せました。'),
('JPN', '诗篇', 19, 9, 7, 'しかし主はとこしえに御座に着きさばきのために王座を堅く立てられた。'),
('JPN', '诗篇', 19, 9, 8, '主は義によって世界をさばき公正をもってもろもろの国民をさばかれる。'),
('JPN', '诗篇', 19, 9, 9, '主は虐げられた者の砦苦しみのときの砦。'),
('JPN', '诗篇', 19, 9, 10, '御名を知る者はあなたに拠り頼みます。主よあなたを求める者をあなたはお見捨てになりませんでした。'),
('JPN', '诗篇', 19, 9, 11, '主にほめ歌を歌えシオンに住まうその方に。主のみわざを告げ知らせよ国々の民に。'),
('JPN', '诗篇', 19, 9, 12, '血に報いる方は彼らを心に留め貧しい者の叫びをお忘れにならない。'),
('JPN', '诗篇', 19, 9, 13, '主よ私をあわれんでください。私を憎む者から来る私の苦しみをご覧ください。死の門から私を引き上げてくださる方よ。'),
('JPN', '诗篇', 19, 9, 14, '私はあなたのすべての誉れを語り告げるため娘シオンの城門であなたの救いに歓声をあげます。'),
('JPN', '诗篇', 19, 9, 15, '国々は自分で作った穴に陥り自分で隠した網に足を取られる。'),
('JPN', '诗篇', 19, 9, 16, '主はご自身を知らしめさばきを行われた。悪しき者は自分の手で作った罠にかかった。ヒガヨンセラ'),
('JPN', '诗篇', 19, 9, 17, '悪しき者はよみに帰って行く。神を忘れるあらゆる国々も。'),
('JPN', '诗篇', 19, 9, 18, '貧しい者は決して忘れられることがなく苦しむ者の望みは永遠に失せることがない。'),
('JPN', '诗篇', 19, 9, 19, '主よ立ち上がり人間が勝ち誇らないようにしてください。国々が御前でさばかれるようにしてください。'),
('JPN', '诗篇', 19, 9, 20, '主よ彼らに恐れを起こさせ国々に思い知らせてください。自らが人間にすぎないことを。セラ'),
('JPN', '诗篇', 19, 10, 1, '主よなぜあなたは遠く離れて立ち苦しみのときに身を隠されるのですか。'),
('JPN', '诗篇', 19, 10, 2, '悪しき者は高ぶって苦しむ人に追い迫ります。彼らが自分の企みに捕らえられますように。'),
('JPN', '诗篇', 19, 10, 3, '悪しき者は自分自身の欲望を誇り貪欲な者は主を呪い侮ります。'),
('JPN', '诗篇', 19, 10, 4, '悪しき者は高慢を顔に表し神を求めません。「神はいない。」これが彼の思いのすべてです。'),
('JPN', '诗篇', 19, 10, 5, '彼の道はいつも栄えあなたのさばきは高すぎて彼の目に入りません。敵という敵を彼は吹き飛ばしてしまいます。'),
('JPN', '诗篇', 19, 10, 6, '彼は心の中で言っています。「私は揺るがされることがなく代々にわたってわざわいにあわない。」'),
('JPN', '诗篇', 19, 10, 7, '彼の口は呪いと欺きと虐げに満ち舌の裏にあるのは害悪と不法です。'),
('JPN', '诗篇', 19, 10, 8, '彼は村外れの待ち伏せ場に座り隠れた所で咎なき者を殺します。彼の目は不幸な人をひそかに狙っています。'),
('JPN', '诗篇', 19, 10, 9, '茂みの中の獅子のように隠れ場で待ち伏せます。苦しむ人を捕らえようと待ち伏せ苦しむ人を網にかけて捕らえてしまいます。'),
('JPN', '诗篇', 19, 10, 10, '彼の強さに不幸な人は砕かれ崩れ倒れます。'),
('JPN', '诗篇', 19, 10, 11, '彼は心の中で言っています。「神は忘れているのだ。顔を隠して永久に見ることはないのだ。」'),
('JPN', '诗篇', 19, 10, 12, '主よ立ち上がってください。神よ御手を上げてください。どうか貧しい者を忘れないでください。'),
('JPN', '诗篇', 19, 10, 13, '何のために悪しき者は神を侮るのでしょうか。彼は心の中であなたが追及することはないと言っています。'),
('JPN', '诗篇', 19, 10, 14, 'あなたは見ておられました。労苦と苦痛をじっと見つめておられました。それを御手の中に収めるために。不幸な人はあなたに身をゆだねます。みなしごはあなたがお助けになります。'),
('JPN', '诗篇', 19, 10, 15, '悪しき者と邪悪な者の腕を折りその悪を探し出して一つも残らないようにしてください。'),
('JPN', '诗篇', 19, 10, 16, '主は世々にわたって永遠の王。国々は主の地から滅び失せました。'),
('JPN', '诗篇', 19, 10, 17, '主よあなたは貧しい者たちの願いを聞いてくださいます。あなたは彼らの心を強くし耳を傾けてくださいます。'),
('JPN', '诗篇', 19, 10, 18, 'みなしごと虐げられた者をかばってくださいます。地から生まれた人間がもはや彼らをおびえさせることがないように。'),
('JPN', '诗篇', 19, 11, 1, '主に私は身を避ける。どうしてあなたがたは私のたましいに言うのか。「鳥のように自分の山に飛んで行け。'),
('JPN', '诗篇', 19, 11, 2, 'それ見よ悪者どもが弓を張り弦に矢をつがえ暗がりで心の直ぐな人を射抜こうとしている。'),
('JPN', '诗篇', 19, 11, 3, '拠り所が壊されたら正しい者に何ができるだろうか。」'),
('JPN', '诗篇', 19, 11, 4, '主はその聖なる宮におられる。主はその王座が天にある。その目は見通しそのまぶたは人の子らを調べる。'),
('JPN', '诗篇', 19, 11, 5, '主は正しい者と悪者を調べる。そのみこころは暴虐を好む者を憎む。'),
('JPN', '诗篇', 19, 11, 6, '主は悪者どもの上に網を下す。火と硫黄燃える風が彼らへの杯。'),
('JPN', '诗篇', 19, 11, 7, '主は正しく正義を愛される。直ぐな人は御顔を仰ぎ見る。'),
('JPN', '诗篇', 19, 12, 1, '主よお救いください。敬虔な人は後を絶ち誠実な人は人の子らの中から消え去りました。'),
('JPN', '诗篇', 19, 12, 2, '人は互いにむなしいことを話しへつらいの唇と二心で話します。'),
('JPN', '诗篇', 19, 12, 3, '主がへつらいの唇と傲慢の舌をことごとく断ち切ってくださいますように。'),
('JPN', '诗篇', 19, 12, 4, '彼らはこう言っています。「われらはこの舌で勝つことができる。この唇はわれらのものだ。だれがわれらの主人なのか。」'),
('JPN', '诗篇', 19, 12, 5, '主は言われます。「苦しむ人が踏みにじられ貧しい人が嘆くから今わたしは立ち上がる。わたしは彼をその求める救いに入れよう。」'),
('JPN', '诗篇', 19, 12, 6, '主のことばは混じり気のないことば。土の炉で七度試され純化された銀。'),
('JPN', '诗篇', 19, 12, 7, '主よあなたは彼らを守られます。今の代からとこしえまでも彼らを保たれます。'),
('JPN', '诗篇', 19, 12, 8, '人の子の間で卑しいことがあがめられているときには悪しき者がいたるところで横行します。'),
('JPN', '诗篇', 19, 13, 1, '主よいつまでですか。あなたは私を永久にお忘れになるのですか。いつまで御顔を私からお隠しになるのですか。'),
('JPN', '诗篇', 19, 13, 2, 'いつまで私は自分のたましいのうちで思い悩まなければならないのでしょう。私の心には一日中悲しみがあります。いつまで敵が私の上におごり高ぶるのですか。'),
('JPN', '诗篇', 19, 13, 3, '私に目を注ぎ私に答えてください。私の神主よ。私の目を明るくしてください。私が死の眠りにつかないように。'),
('JPN', '诗篇', 19, 13, 4, '「彼に勝った」と私の敵が言わないように。私がぐらつくことを逆らう者が喜ばないように。'),
('JPN', '诗篇', 19, 13, 5, '私はあなたの恵みに拠り頼みます。私の心はあなたの救いを喜びます。'),
('JPN', '诗篇', 19, 13, 6, '私は主に歌を歌います。主が私に良くしてくださいましたから。'),
('JPN', '诗篇', 19, 14, 1, '愚か者は心の中で「神はいない」と言う。彼らは腐っていて忌まわしいことを行う。善を行う者はいない。'),
('JPN', '诗篇', 19, 14, 2, '主は天から人の子らを見下ろされた。悟る者神を求める者がいるかどうかと。'),
('JPN', '诗篇', 19, 14, 3, 'すべての者が離れて行きだれもかれも無用の者となった。善を行う者はいない。だれ一人いない。'),
('JPN', '诗篇', 19, 14, 4, '不法を行う者はみな知らないのか。彼らはわたしの民を食らいながらパンを食べ主を呼び求めない。'),
('JPN', '诗篇', 19, 14, 5, '見よ彼らは大いに恐れた。神は正しい一族とともにおられるからだ。'),
('JPN', '诗篇', 19, 14, 6, 'おまえたちは苦しむ者の計画を踏みにじろうとするだろう。しかし主が彼の避け所である。'),
('JPN', '诗篇', 19, 14, 7, 'ああイスラエルの救いがシオンから来るように。主が御民を元どおりにされるときヤコブは楽しめ。イスラエルは喜べ。'),
('JPN', '诗篇', 19, 15, 1, '主よだれがあなたの幕屋に宿るのでしょうか。だれがあなたの聖なる山に住むのでしょうか。'),
('JPN', '诗篇', 19, 15, 2, '全き者として歩み義を行い心の中の真実を語る人。'),
('JPN', '诗篇', 19, 15, 3, '舌をもって中傷せず友人に悪を行わず隣人へのそしりを口にしない人。'),
('JPN', '诗篇', 19, 15, 4, 'その目は主に捨てられた者を蔑み主を恐れる者を彼は尊ぶ。損になっても誓ったことは変えない。'),
('JPN', '诗篇', 19, 15, 5, '利息をつけて金を貸すことはせず潔白な人を不利にする賄賂を受け取らない。このように行う人は決して揺るがされない。'),
('JPN', '诗篇', 19, 16, 1, '神よ私をお守りください。私はあなたに身を避けています。'),
('JPN', '诗篇', 19, 16, 2, '私は主に申し上げます。「あなたこそ私の主。私の幸いはあなたのほかにはありません。」'),
('JPN', '诗篇', 19, 16, 3, '地にある聖徒たちには威厳があり私の喜びはすべて彼らの中にあります。'),
('JPN', '诗篇', 19, 16, 4, 'ほかの神に走った者の痛みは増し加わります。私は彼らが献げる血の酒を注がずその名を口にいたしません。'),
('JPN', '诗篇', 19, 16, 5, '主は私への割り当て分また杯。あなたは私の受ける分を堅く保たれます。'),
('JPN', '诗篇', 19, 16, 6, '割り当ての地は定まりました。私の好む所に。実にすばらしい私へのゆずりの地です。'),
('JPN', '诗篇', 19, 16, 7, '私はほめたたえます。助言を下さる主を。実に夜ごとに内なる思いが私を教えます。'),
('JPN', '诗篇', 19, 16, 8, '私はいつも主を前にしています。主が私の右におられるので私は揺るがされることがありません。'),
('JPN', '诗篇', 19, 16, 9, 'それゆえ私の心は喜び私の胸は喜びにあふれます。私の身も安らかに住まいます。'),
('JPN', '诗篇', 19, 16, 10, 'あなたは私のたましいをよみに捨て置かずあなたにある敬虔な者に滅びをお見せにならないからです。'),
('JPN', '诗篇', 19, 16, 11, 'あなたは私にいのちの道を知らせてくださいます。満ち足りた喜びがあなたの御前にあり楽しみがあなたの右にとこしえにあります。'),
('JPN', '诗篇', 19, 17, 1, '主よ聞いてください正しい訴えを。耳に留めてください私の叫びを。耳に入れてください私の祈りを。これらは欺きの唇から出たものではありません。'),
('JPN', '诗篇', 19, 17, 2, 'あなたの御前で私のためのさばきが行われ御目が正しいことに注がれますように。'),
('JPN', '诗篇', 19, 17, 3, 'あなたは私の心を調べ夜私を問いただされました。私を炉で試されましたが何も見つかりません。私は口の過ちを犯さないように心がけました。'),
('JPN', '诗篇', 19, 17, 4, '人としての行いはあなたの唇のことばに従い無法者が行く道を避けました。'),
('JPN', '诗篇', 19, 17, 5, '私の歩みはあなたの道を堅く守り私の足は揺るぎませんでした。'),
('JPN', '诗篇', 19, 17, 6, '神よ私はあなたを呼び求めました。あなたは私に答えてくださるからです。私に耳を傾けて私のことばを聞いてください。'),
('JPN', '诗篇', 19, 17, 7, 'あなたの右の手で奇しい恵みをお示しください。向かい立つ者どもから身を避ける者を救う方。'),
('JPN', '诗篇', 19, 17, 8, '瞳のように私を守り御翼の陰にかくまってください。'),
('JPN', '诗篇', 19, 17, 9, '私を襲う悪しき者から私を取り巻く貪欲な敵から。'),
('JPN', '诗篇', 19, 17, 10, '彼らは鈍い心を固く閉ざしその口をもって高慢に語ります。'),
('JPN', '诗篇', 19, 17, 11, '彼らは私たちの跡をつけ今取り囲み目を据えて地に投げ倒そうとしています。'),
('JPN', '诗篇', 19, 17, 12, 'それはまるでかみ裂くことに飢えた獅子待ち伏せしている若い獅子のようです。'),
('JPN', '诗篇', 19, 17, 13, '主よ立ち上がり彼の前に進み行き打ちのめしてください。あなたの剣で悪しき者から私のたましいを助け出してください。'),
('JPN', '诗篇', 19, 17, 14, '主よ御手をもって人々から相続分が地上のいのちであるこの世の人々から私のたましいを助け出してください。あなたの蓄えで彼らの腹は満たされ子たちは満ち足りその余りをさらにその幼子らに残します。'),
('JPN', '诗篇', 19, 17, 15, 'しかし私は義のうちに御顔を仰ぎ見目覚めるとき御姿に満ち足りるでしょう。'),
('JPN', '诗篇', 19, 18, 1, '彼は言った。わが力なる主よ。私はあなたを慕います。'),
('JPN', '诗篇', 19, 18, 2, '主はわが巌わが砦わが救い主身を避けるわが岩わが神。わが盾わが救いの角わがやぐら。'),
('JPN', '诗篇', 19, 18, 3, 'ほめたたえられる方。この主を呼び求めると私は敵から救われる。'),
('JPN', '诗篇', 19, 18, 4, '死の綱は私を取り巻き滅びの激流は私をおびえさせた。'),
('JPN', '诗篇', 19, 18, 5, 'よみの綱は私を取り囲み死の罠は私に立ち向かった。'),
('JPN', '诗篇', 19, 18, 6, '私は苦しみの中で主を呼び求めわが神に叫び求めた。主はその宮で私の声を聞かれ御前への叫びは御耳に届いた。'),
('JPN', '诗篇', 19, 18, 7, '地は揺るぎ動いた。山々の基も震え揺れた。主がお怒りになったからだ。'),
('JPN', '诗篇', 19, 18, 8, '煙は鼻から立ち上りその口から出る火は貪り食い炭火は主から燃え上がった。'),
('JPN', '诗篇', 19, 18, 9, '主は天を押し曲げて降りて来られた。黒雲をその足の下にして。'),
('JPN', '诗篇', 19, 18, 10, '主はケルビムに乗って飛び風の翼で天翔られた。'),
('JPN', '诗篇', 19, 18, 11, '主は闇を隠れ家とし水の暗闇濃い雲をご自分の周りで仮庵とされた。'),
('JPN', '诗篇', 19, 18, 12, '御前の輝きから密雲を突き抜けて来たもの。それは雹と燃える炭。'),
('JPN', '诗篇', 19, 18, 13, '主は天に雷鳴を響かせいと高き方は御声を発せられた。雹そして燃える炭。'),
('JPN', '诗篇', 19, 18, 14, '主はご自分の矢を放って彼らを散らしすさまじい稲妻を放ってかき乱された。'),
('JPN', '诗篇', 19, 18, 15, 'こうして水の底が現れ地の基があらわにされた。主よあなたのとがめによりあなたの鼻の荒い息吹によって。'),
('JPN', '诗篇', 19, 18, 16, '主はいと高き所から御手を伸ばして私を捕らえ大水から私を引き上げられました。'),
('JPN', '诗篇', 19, 18, 17, '主は力ある敵から私を救い出されました。私を憎む者どもからも。彼らが私より強かったからです。'),
('JPN', '诗篇', 19, 18, 18, '私のわざわいの日に彼らは立ちはだかりました。けれども主は私の支えとなられました。'),
('JPN', '诗篇', 19, 18, 19, '主は私を広いところに導き出し私を助け出してくださいました。主が私を喜びとされたからです。'),
('JPN', '诗篇', 19, 18, 20, '主は私の義にしたがって私に報い手のきよさにしたがって顧みてくださいました。'),
('JPN', '诗篇', 19, 18, 21, '私は主の道を守り私の神に対して悪を行いませんでした。'),
('JPN', '诗篇', 19, 18, 22, '主のすべてのさばきは私の前にあり主のおきてを私は遠ざけませんでした。'),
('JPN', '诗篇', 19, 18, 23, '私は主の前に全き者。自分の咎から身を守ります。'),
('JPN', '诗篇', 19, 18, 24, '主は私の義にしたがって顧みてくださいました。御目の前のこの手のきよさにしたがって。'),
('JPN', '诗篇', 19, 18, 25, 'あなたは恵み深い者には恵み深く全き者には全き方。'),
('JPN', '诗篇', 19, 18, 26, '清い者には清く曲がった者にはねじ曲げる方。'),
('JPN', '诗篇', 19, 18, 27, 'まことにあなたは苦しむ民を救い高ぶる目を低くされます。'),
('JPN', '诗篇', 19, 18, 28, 'まことにあなたは私のともしびをともされます。私の神主は私の闇を照らされます。'),
('JPN', '诗篇', 19, 18, 29, 'あなたによって私は防塞を突き破り私の神によって城壁を跳び越えます。'),
('JPN', '诗篇', 19, 18, 30, '神その道は完全。主のことばは純粋。主はすべて主に身を避ける者の盾。'),
('JPN', '诗篇', 19, 18, 31, '主のほかにだれが神でしょうか。私たちの神を除いてだれが岩でしょうか。'),
('JPN', '诗篇', 19, 18, 32, '神は私に力を帯びさせ私の道を全きものとされます。'),
('JPN', '诗篇', 19, 18, 33, '主は私の足を雌鹿のようにし高い所に立たせてくださいます。'),
('JPN', '诗篇', 19, 18, 34, '戦いのために私の手を鍛え腕が青銅の弓も引けるようにしてくださいます。'),
('JPN', '诗篇', 19, 18, 35, 'あなたは御救いの盾を私に下さいます。あなたの右の手は私を支えあなたの謙遜は私を大きくします。'),
('JPN', '诗篇', 19, 18, 36, 'あなたは私の歩みを大きくし私のくるぶしはゆるみません。'),
('JPN', '诗篇', 19, 18, 37, '私は敵を追ってこれに追いつき絶ち滅ぼすまでは引き返しませんでした。'),
('JPN', '诗篇', 19, 18, 38, '私が彼らを打ち砕いたので彼らは立てず私の足もとに倒れました。'),
('JPN', '诗篇', 19, 18, 39, 'あなたは戦いのために私に力を帯びさせ向かい立つ者を私のもとにひれ伏させました。'),
('JPN', '诗篇', 19, 18, 40, 'あなたは敵が私を憎む者どもが私に背を見せるようにされました。私は彼らを滅ぼしました。'),
('JPN', '诗篇', 19, 18, 41, '彼らが主に叫び求めても救う者はなく答えもありませんでした。'),
('JPN', '诗篇', 19, 18, 42, '風の前のちりのように私は彼らを粉々に砕き道の泥のように除き去りました。'),
('JPN', '诗篇', 19, 18, 43, 'あなたは民の争いから私を助け出し国々のかしらに任じられました。私の知らなかった民が私に仕えます。'),
('JPN', '诗篇', 19, 18, 44, '彼らは耳で聞くとすぐ私に聞き従います。異国の人々は私にへつらいます。'),
('JPN', '诗篇', 19, 18, 45, '異国の人々は打ちしおれ砦から震えて出て来ます。'),
('JPN', '诗篇', 19, 18, 46, '主は生きておられる。ほむべきかなわが岩。あがむべきかなわが救いの神。'),
('JPN', '诗篇', 19, 18, 47, 'この神は私のために復讐する方。諸国の民を私のもとに従わせてくださる。'),
('JPN', '诗篇', 19, 18, 48, '神は敵から私を助け出される方。実にあなたは向かい立つ者から私を引き上げ不法を行う者から救い出してくださいます。'),
('JPN', '诗篇', 19, 18, 49, 'それゆえ主よ私は国々の間であなたをほめたたえます。あなたの御名をほめ歌います。'),
('JPN', '诗篇', 19, 18, 50, '主はご自分の王に救いを増し加え主に油注がれた者ダビデとその裔にとこしえに恵みを施されます。'),
('JPN', '诗篇', 19, 19, 1, '天は神の栄光を語り告げ大空は御手のわざを告げ知らせる。'),
('JPN', '诗篇', 19, 19, 2, '昼は昼へ話を伝え夜は夜へ知識を示す。'),
('JPN', '诗篇', 19, 19, 3, '話しもせず語りもせずその声も聞こえない。'),
('JPN', '诗篇', 19, 19, 4, 'しかしその光芒は全地にそのことばは世界の果てまで届いた。神は天に太陽のために幕屋を設けられた。'),
('JPN', '诗篇', 19, 19, 5, '花婿のように太陽は部屋から出て勇士のように走路を喜び走る。'),
('JPN', '诗篇', 19, 19, 6, '天の果てからそれは昇り天の果てまでそれは巡る。その熱から隠れ得るものは何もない。'),
('JPN', '诗篇', 19, 19, 7, '主のおしえは完全でたましいを生き返らせ主の証しは確かで浅はかな者を賢くする。'),
('JPN', '诗篇', 19, 19, 8, '主の戒めは真っ直ぐで人の心を喜ばせ主の仰せは清らかで人の目を明るくする。'),
('JPN', '诗篇', 19, 19, 9, '主からの恐れはきよくとこしえまでも変わらない。主のさばきはまことでありことごとく正しい。'),
('JPN', '诗篇', 19, 19, 10, 'それらは金よりも多くの純金よりも慕わしく蜜よりも蜜蜂の巣の滴りよりも甘い。'),
('JPN', '诗篇', 19, 19, 11, 'あなたのしもべもそれらにより戒めを受けそれを守れば大きな報いがあります。'),
('JPN', '诗篇', 19, 19, 12, 'だれが自分の過ちを悟ることができるでしょう。どうか隠れた罪から私を解き放ってください。'),
('JPN', '诗篇', 19, 19, 13, 'あなたのしもべを傲慢から守ってください。それらが私を支配しないようにしてください。そのとき私は大きな背きから解き放たれて全き者となるでしょう。'),
('JPN', '诗篇', 19, 19, 14, '私の口のことばと私の心の思いとが御前に受け入れられますように。主よわが岩わが贖い主よ。'),
('JPN', '诗篇', 19, 20, 1, '苦難の日に主があなたにお答えになりますように。ヤコブの神の御名があなたを高く上げますように。'),
('JPN', '诗篇', 19, 20, 2, '主が聖所からあなたに助けを送りシオンからあなたを支えられますように。'),
('JPN', '诗篇', 19, 20, 3, 'あなたの穀物のささげ物をすべて心に留めあなたの全焼のささげ物を受け入れてくださいますように。セラ'),
('JPN', '诗篇', 19, 20, 4, 'あなたの心の望みを主がかなえてくださいますように。あなたのすべての計画を遂げさせてくださいますように。'),
('JPN', '诗篇', 19, 20, 5, '私たちはあなたの勝利を喜び歌い私たちの神の御名により旗を高く掲げます。あなたの願いのすべてを主が遂げさせてくださいますように。'),
('JPN', '诗篇', 19, 20, 6, '今私は知る。主が主に油注がれた者を救ってくださることを。右の御手の救いの御力をもって聖なる天からその者に答えてくださることを。'),
('JPN', '诗篇', 19, 20, 7, 'ある者は戦車をある者は馬を求める。しかし私たちは私たちの神主の御名を呼び求める。'),
('JPN', '诗篇', 19, 20, 8, '彼らは膝をつき倒れた。しかし私たちはまっすぐに立ち上がった。'),
('JPN', '诗篇', 19, 20, 9, '主よ王をお救いください。私たちが呼ぶときに答えてください。'),
('JPN', '诗篇', 19, 21, 1, '主よあなたの御力を王は喜びます。あなたの御救いをどんなに楽しむことでしょう。'),
('JPN', '诗篇', 19, 21, 2, 'あなたは彼の心の望みをかなえ唇の願いを退けられません。セラ'),
('JPN', '诗篇', 19, 21, 3, 'あなたは幸いに至る祝福をもって彼を迎え頭に純金の冠を置かれます。'),
('JPN', '诗篇', 19, 21, 4, 'いのちを彼はあなたに願いあなたは彼にそれをお与えになります。いつまでもとこしえまでも限りなく。'),
('JPN', '诗篇', 19, 21, 5, '御救いによって彼の栄光は大いなるものとなり威厳と威光をあなたは彼の上に置かれます。'),
('JPN', '诗篇', 19, 21, 6, 'あなたはとこしえに彼に祝福を与え御前で喜び楽しませてくださいます。'),
('JPN', '诗篇', 19, 21, 7, '王は主に信頼しているのでいと高き方の恵みにあって揺るぎません。'),
('JPN', '诗篇', 19, 21, 8, 'あなたの御手はすべての敵を見つけ出しあなたの右の手はあなたを憎む者を見つけ出します。'),
('JPN', '诗篇', 19, 21, 9, 'あなたの現れのときあなたは彼らを燃える炉のようにされます。主は御怒りによって彼らを吞み尽くし火は彼らを食い尽くします。'),
('JPN', '诗篇', 19, 21, 10, '地の上から彼らの裔を人の子らの中から彼らの子孫をあなたは滅ぼしてしまわれます。'),
('JPN', '诗篇', 19, 21, 11, '彼らがあなたに対して悪を企て計略をめぐらしても成し遂げられません。'),
('JPN', '诗篇', 19, 21, 12, 'あなたは彼らが背を見せるようにし弓弦を引き彼らの顔を狙われます。'),
('JPN', '诗篇', 19, 21, 13, '主よあなたの御力のゆえにあなたがあがめられますように。大いなる御力を私たちは歌いほめ歌います。'),
('JPN', '诗篇', 19, 22, 1, 'わが神わが神どうして私をお見捨てになったのですか。私を救わず遠く離れておられるのですか。私のうめきのことばにもかかわらず。'),
('JPN', '诗篇', 19, 22, 2, 'わが神昼に私はあなたを呼びます。しかしあなたは答えてくださいません。夜にも私は黙っていられません。'),
('JPN', '诗篇', 19, 22, 3, 'けれどもあなたは聖なる方御座に着いておられる方イスラエルの賛美です。'),
('JPN', '诗篇', 19, 22, 4, 'あなたに私たちの先祖は信頼しました。彼らは信頼しあなたは彼らを助け出されました。'),
('JPN', '诗篇', 19, 22, 5, 'あなたに叫び彼らは助け出されました。あなたに信頼し彼らは恥を見ませんでした。'),
('JPN', '诗篇', 19, 22, 6, 'しかし私は虫けらです。人間ではありません。人のそしりの的民の蔑みの的です。'),
('JPN', '诗篇', 19, 22, 7, '私を見る者はみな私を嘲ります。口をとがらせ頭を振ります。'),
('JPN', '诗篇', 19, 22, 8, '「主に身を任せよ。助け出してもらえばよい。主に救い出してもらえ。彼のお気に入りなのだから。」'),
('JPN', '诗篇', 19, 22, 9, 'まことにあなたは私を母の胎から取り出した方。母の乳房に拠り頼ませた方。'),
('JPN', '诗篇', 19, 22, 10, '生まれる前から私はあなたにゆだねられました。母の胎内にいたときからあなたは私の神です。'),
('JPN', '诗篇', 19, 22, 11, 'どうか私から遠く離れないでください。苦しみが近くにあり助ける者がいないのです。'),
('JPN', '诗篇', 19, 22, 12, '多くの雄牛が私を取り囲みバシャンの猛者どもが私を囲みました。'),
('JPN', '诗篇', 19, 22, 13, '彼らは私に向かって口を開けています。かみ裂く吼えたける獅子のように。'),
('JPN', '诗篇', 19, 22, 14, '水のように私は注ぎ出され骨はみな外れました。心はろうのように私のうちで溶けました。'),
('JPN', '诗篇', 19, 22, 15, '私の力は土器のかけらのように乾ききり舌は上あごに貼り付いています。死のちりの上にあなたは私を置かれます。'),
('JPN', '诗篇', 19, 22, 16, '犬どもが私を取り囲み悪者どもの群れが私を取り巻いて私の手足にかみついたからです。'),
('JPN', '诗篇', 19, 22, 17, '私は自分の骨をみな数えることができます。彼らは目を凝らし私を見ています。'),
('JPN', '诗篇', 19, 22, 18, '彼らは私の衣服を分け合い私の衣をくじ引きにします。'),
('JPN', '诗篇', 19, 22, 19, '主よあなたは離れないでください。私の力よ早く助けに来てください。'),
('JPN', '诗篇', 19, 22, 20, '救い出してください。私のたましいを剣から。私のただ一つのものを犬の手から。'),
('JPN', '诗篇', 19, 22, 21, '救ってください。獅子の口から野牛の角から。あなたは私に答えてくださいました。'),
('JPN', '诗篇', 19, 22, 22, '私はあなたの御名を兄弟たちに語り告げ会衆の中であなたを賛美します。'),
('JPN', '诗篇', 19, 22, 23, '主を恐れる人々よ主を賛美せよ。ヤコブのすべての裔よ主をあがめよ。イスラエルのすべての裔よ主の前におののけ。'),
('JPN', '诗篇', 19, 22, 24, '主は貧しい人の苦しみを蔑まずいとわず御顔を彼から隠すことなく助けを叫び求めたとき聞いてくださった。'),
('JPN', '诗篇', 19, 22, 25, '大いなる会衆の中での私の賛美はあなたからのものです。私は誓いを果たします。主を恐れる人々の前で。'),
('JPN', '诗篇', 19, 22, 26, 'どうか貧しい人々が食べて満ち足り主を求める人々が主を賛美しますように。──あなたがたの心がいつまでも生きるように──'),
('JPN', '诗篇', 19, 22, 27, '地の果てのすべての者が思い起こし主に帰って来ますように。国々のあらゆる部族もあなたの御前にひれ伏しますように。'),
('JPN', '诗篇', 19, 22, 28, '王権は主のもの。主は国々を統べ治めておられます。'),
('JPN', '诗篇', 19, 22, 29, '地の裕福な者はみな食べてひれ伏しちりに下る者もみな主の御前にひざまずきます。自分のたましいを生かすことができない者も。'),
('JPN', '诗篇', 19, 22, 30, '子孫たちは主に仕え主のことが世代を越えて語り告げられます。'),
('JPN', '诗篇', 19, 22, 31, '彼らは来て生まれてくる民に主の義を告げ知らせます。主が義を行われたからです。'),
('JPN', '诗篇', 19, 23, 1, '主は私の羊飼い。私は乏しいことがありません。'),
('JPN', '诗篇', 19, 23, 2, '主は私を緑の牧場に伏させいこいのみぎわに伴われます。'),
('JPN', '诗篇', 19, 23, 3, '主は私のたましいを生き返らせ御名のゆえに私を義の道に導かれます。'),
('JPN', '诗篇', 19, 23, 4, 'たとえ死の陰の谷を歩むとしても私はわざわいを恐れません。あなたがともにおられますから。あなたのむちとあなたの杖それが私の慰めです。'),
('JPN', '诗篇', 19, 23, 5, '私の敵をよそにあなたは私の前に食卓を整え頭に香油を注いでくださいます。私の杯はあふれています。'),
('JPN', '诗篇', 19, 23, 6, 'まことに私のいのちの日の限りいつくしみと恵みが私を追って来るでしょう。私はいつまでも主の家に住まいます。'),
('JPN', '诗篇', 19, 24, 1, '地とそこに満ちているもの世界とその中に住んでいるものそれは主のもの。'),
('JPN', '诗篇', 19, 24, 2, '主が海に地の基を据え川の上にそれを堅く立てられたからだ。'),
('JPN', '诗篇', 19, 24, 3, 'だれが主の山に登り得るのか。だれが聖なる御前に立てるのか。'),
('JPN', '诗篇', 19, 24, 4, '手がきよく心の澄んだ人そのたましいをむなしいものに向けず偽りの誓いをしない人。'),
('JPN', '诗篇', 19, 24, 5, 'その人は主から祝福を受け自分の救いの神から義を受ける。'),
('JPN', '诗篇', 19, 24, 6, 'これこそヤコブの一族。神を求める者たちあなたの御顔を慕い求める人々である。セラ'),
('JPN', '诗篇', 19, 24, 7, '門よおまえたちの頭を上げよ。永遠の戸よ上がれ。栄光の王が入って来られる。'),
('JPN', '诗篇', 19, 24, 8, '栄光の王とはだれか。強く力ある主。戦いに力ある主。'),
('JPN', '诗篇', 19, 24, 9, '門よおまえたちの頭を上げよ。永遠の戸よ上がれ。栄光の王が入って来られる。'),
('JPN', '诗篇', 19, 24, 10, '栄光の王それはだれか。万軍の主この方こそ栄光の王。セラ'),
('JPN', '诗篇', 19, 25, 1, '主よあなたをわがたましいは仰ぎ求めます。'),
('JPN', '诗篇', 19, 25, 2, 'わが神あなたに私は信頼いたします。どうか私が恥を見ないように敵が私に勝ち誇らないようにしてください。'),
('JPN', '诗篇', 19, 25, 3, 'まことにあなたを待ち望む者がだれも恥を見ずゆえなく裏切る者が恥を見ますように。'),
('JPN', '诗篇', 19, 25, 4, '主よあなたの道を私に知らせあなたの進む道を私に教えてください。'),
('JPN', '诗篇', 19, 25, 5, 'あなたの真理に私を導き教えてください。あなたこそ私の救いの神私はあなたを一日中待ち望みます。'),
('JPN', '诗篇', 19, 25, 6, '主よ思い起こしてください。あなたのあわれみと恵みを。それらはとこしえからのものです。'),
('JPN', '诗篇', 19, 25, 7, '私の若いころの罪や背きを思い起こさないでください。あなたの恵みによって私を覚えていてください。主よあなたのいつくしみのゆえに。'),
('JPN', '诗篇', 19, 25, 8, '主はいつくしみ深く正しくあられます。それゆえ罪人に道をお教えになります。'),
('JPN', '诗篇', 19, 25, 9, '主は貧しい者を正義に歩ませ貧しい者にご自分の道をお教えになります。'),
('JPN', '诗篇', 19, 25, 10, '主の道はみな恵みとまことです。主の契約とさとしを守る者には。'),
('JPN', '诗篇', 19, 25, 11, '主よあなたの御名のゆえに私の咎をお赦しください。それは大きいのです。'),
('JPN', '诗篇', 19, 25, 12, '主を恐れる人はだれか。主はその人に選ぶべき道をお教えになる。'),
('JPN', '诗篇', 19, 25, 13, 'その人のたましいは幸せの中に宿りその子孫は地を受け継ぐ。'),
('JPN', '诗篇', 19, 25, 14, '主はご自分を恐れる者と親しく交わりその契約を彼らにお知らせになる。'),
('JPN', '诗篇', 19, 25, 15, '私の目はいつも主に向かう。主が私の足を罠から引き出してくださるから。'),
('JPN', '诗篇', 19, 25, 16, '私に御顔を向け私をあわれんでください。私はひとり苦しんでいます。'),
('JPN', '诗篇', 19, 25, 17, '私の心の苦しみが大きくなりました。どうかこの苦悩から私を引き出してください。'),
('JPN', '诗篇', 19, 25, 18, '私の悩みと労苦を見て私のすべての罪を赦してください。'),
('JPN', '诗篇', 19, 25, 19, 'ご覧ください。私の敵がどんなに多いかを。彼らは不当な憎しみで私を憎んでいます。'),
('JPN', '诗篇', 19, 25, 20, '私のたましいを守り私を救い出してください。私が恥を見ないようにしてください。私はあなたに身を避けます。'),
('JPN', '诗篇', 19, 25, 21, '誠実で直ぐな心で私が保たれますように。私はあなたを待ち望んでいますから。'),
('JPN', '诗篇', 19, 25, 22, '神よイスラエルをそのすべての苦難から贖い出してください。'),
('JPN', '诗篇', 19, 26, 1, '主よ私を弁護してください。私は誠実に歩みよろめくことなく主に信頼しています。'),
('JPN', '诗篇', 19, 26, 2, '主よ私を調べ試みてください。私の心の深みまで精錬してください。'),
('JPN', '诗篇', 19, 26, 3, 'あなたの恵みは私の目の前にありあなたの真理のうちを私は歩み続けました。'),
('JPN', '诗篇', 19, 26, 4, '私は不信実な人とともに座らず偽善者とともに行きません。'),
('JPN', '诗篇', 19, 26, 5, '悪を行う者の集まりを憎み悪しき者とともに座りません。'),
('JPN', '诗篇', 19, 26, 6, '手を洗い自らの潔白を示します。主よ私はあなたの祭壇の周りを歩きます。'),
('JPN', '诗篇', 19, 26, 7, '感謝の声を響き渡らせて語り告げます。あなたの奇しいみわざのすべてを。'),
('JPN', '诗篇', 19, 26, 8, '主よ私は愛します。あなたの住まいのある所あなたの栄光のとどまる所を。'),
('JPN', '诗篇', 19, 26, 9, 'どうか私のたましいを罪人どもとともに私のいのちを人の血を流す者どもとともに取り去らないでください。'),
('JPN', '诗篇', 19, 26, 10, '彼らの手には悪事がありその右の手は賄賂で満ちているのです。'),
('JPN', '诗篇', 19, 26, 11, 'しかし私は誠実に歩みます。私を贖い出してください。あわれんでください。'),
('JPN', '诗篇', 19, 26, 12, '私の足は平らな所に立っています。数々の集いで私は主をほめたたえます。'),
('JPN', '诗篇', 19, 27, 1, '主は私の光私の救い。だれを私は恐れよう。主は私のいのちの砦。だれを私は怖がろう。'),
('JPN', '诗篇', 19, 27, 2, '私の肉を食らおうと悪を行う者が私に襲いかかったとき崩れ落ちたのは私に逆らう者私の敵であった。'),
('JPN', '诗篇', 19, 27, 3, 'たとえ私に対して陣営が張られても私の心は恐れない。たとえ私に対して戦いが起こってもそれにも私は動じない。'),
('JPN', '诗篇', 19, 27, 4, '一つのことを私は主に願った。それを私は求めている。私のいのちの日の限り主の家に住むことを。主の麗しさに目を注ぎその宮で思いを巡らすために。'),
('JPN', '诗篇', 19, 27, 5, 'それは主が苦しみの日に私を隠れ場に隠しその幕屋のひそかな所に私をかくまい岩の上に私を上げてくださるからだ。'),
('JPN', '诗篇', 19, 27, 6, '今私の頭は私を取り囲む敵の上に高く上げられる。私は主の幕屋で喜びのいけにえをささげ主に歌いほめ歌を歌おう。'),
('JPN', '诗篇', 19, 27, 7, '聞いてください主よ。私が呼ぶこの声を。私をあわれみ私に答えてください。'),
('JPN', '诗篇', 19, 27, 8, 'あなたに代わって私の心は言います。「わたしの顔を慕い求めよ」と。主よあなたの御顔を私は慕い求めます。'),
('JPN', '诗篇', 19, 27, 9, 'どうか御顔を私に隠さないでください。あなたのしもべを怒って押しのけないでください。あなたは私の助けです。見放さないでください。見捨てないでください。私の救いの神よ。'),
('JPN', '诗篇', 19, 27, 10, '私の父私の母が私を見捨てるときは主が私を取り上げてくださいます。'),
('JPN', '诗篇', 19, 27, 11, '主よあなたの道を私に教えてください。私を待ち伏せている者どもがいますから私を平らな道に導いてください。'),
('JPN', '诗篇', 19, 27, 12, '私を敵の意のままにさせないでください。偽りの証人どもが私に向かい立ち暴言を吐いているのです。'),
('JPN', '诗篇', 19, 27, 13, 'もしも私が生ける者の地で主のいつくしみを見ると信じていなかったなら──。'),
('JPN', '诗篇', 19, 27, 14, '待ち望め主を。雄々しくあれ。心を強くせよ。待ち望め主を。'),
('JPN', '诗篇', 19, 28, 1, '主よ私はあなたを呼び求めます。わが岩よどうか私に耳を閉ざさないでください。私に沈黙しないでください。私が穴に下る者どもと同じにされないように。'),
('JPN', '诗篇', 19, 28, 2, '私の願いの声を聞いてください。私があなたに助けを叫び求めるとき。私の手をあなたの聖所の奥に向けて上げるとき。'),
('JPN', '诗篇', 19, 28, 3, 'どうか悪者や不法を行う者どもと一緒に私を引いて行かないでください。彼らは隣人と平和を語りながらその心には悪があるのです。'),
('JPN', '诗篇', 19, 28, 4, '彼らの行いとその悪にしたがって彼らに報いてください。その手のわざにしたがって彼らに報いその仕打ちに報復してください。'),
('JPN', '诗篇', 19, 28, 5, '彼らは主のなさることも御手のわざをも悟らないので主は彼らを打ち壊し建て直すことはされません。'),
('JPN', '诗篇', 19, 28, 6, 'ほむべきかな主。主は私の願いの声を聞かれた。'),
('JPN', '诗篇', 19, 28, 7, '主は私の力私の盾。私の心は主に拠り頼み私は助けられた。私の心は喜び躍り私は歌をもって主に感謝しよう。'),
('JPN', '诗篇', 19, 28, 8, '主は彼らの力。主は主に油注がれた者の救いの砦。'),
('JPN', '诗篇', 19, 28, 9, 'どうか御民を救ってください。あなたのゆずりの民を祝福してください。どうか彼らの羊飼いとなっていつまでも彼らを携え導いてください。'),
('JPN', '诗篇', 19, 29, 1, '力ある者の子らよ。主に帰せよ。栄光と力を主に帰せよ。'),
('JPN', '诗篇', 19, 29, 2, '御名の栄光を主に帰せよ。聖なる装いをして主にひれ伏せ。'),
('JPN', '诗篇', 19, 29, 3, '主の声は水の上にあり栄光の神は雷鳴をとどろかせる。主は大水の上におられる。'),
('JPN', '诗篇', 19, 29, 4, '主の声は力強く主の声は威厳がある。'),
('JPN', '诗篇', 19, 29, 5, '主の声は杉の木を引き裂き主はレバノンの杉を打ち砕く。'),
('JPN', '诗篇', 19, 29, 6, 'それらの木々を子牛のようにレバノンとシルヨンを若い野牛のように跳ねさせる。'),
('JPN', '诗篇', 19, 29, 7, '主の声は炎の穂先をひらめかせる。'),
('JPN', '诗篇', 19, 29, 8, '主の声は荒野を揺さぶり主はカデシュの荒野を揺さぶる。'),
('JPN', '诗篇', 19, 29, 9, '主の声は雌鹿をもだえさせ大森林を裸にする。主の宮ではすべてのものが「栄光」と言う。'),
('JPN', '诗篇', 19, 29, 10, '主は大洪水の前から御座に着いておられる。主はとこしえに王座に着いておられる。'),
('JPN', '诗篇', 19, 29, 11, '主はご自分の民に力をお与えになる。主はご自分の民を平安をもって祝福される。'),
('JPN', '诗篇', 19, 30, 1, '主よ私はあなたをあがめます。あなたは私を引き上げ私の敵が喜ばないようにされたからです。'),
('JPN', '诗篇', 19, 30, 2, 'わが神主よ私が叫び求めるとあなたは私を癒やしてくださいました。'),
('JPN', '诗篇', 19, 30, 3, '主よあなたは私のたましいをよみから引き上げ私を生かしてくださいました。私が穴に下って行かないように。'),
('JPN', '诗篇', 19, 30, 4, '主にある敬虔な者たちよ主をほめ歌え。主の聖なる御名に感謝せよ。'),
('JPN', '诗篇', 19, 30, 5, 'まことに御怒りは束の間いのちは恩寵のうちにある。夕暮れには涙が宿っても朝明けには喜びの叫びがある。'),
('JPN', '诗篇', 19, 30, 6, '私は平安のうちに言った。「私は決して揺るがされない」と。'),
('JPN', '诗篇', 19, 30, 7, '主よあなたはご恩寵のうちに私を私の山に堅く立たせてくださいました。あなたが御顔を隠されると私はおじ惑いました。'),
('JPN', '诗篇', 19, 30, 8, '主よあなたを私は呼び求めます。私の主にあわれみを乞います。'),
('JPN', '诗篇', 19, 30, 9, '私が墓に下っても私の血に何の益があるでしょうか。ちりがあなたをほめたたえるでしょうか。あなたのまことを告げるでしょうか。'),
('JPN', '诗篇', 19, 30, 10, '聞いてください主よ。私をあわれんでください主よ。私の助けとなってください。'),
('JPN', '诗篇', 19, 30, 11, 'あなたは私のために嘆きを踊りに変えてくださいました。私の粗布を解き喜びをまとわせてくださいました。'),
('JPN', '诗篇', 19, 30, 12, '私のたましいがあなたをほめ歌い押し黙ることがないために。私の神主よ私はとこしえまでもあなたに感謝します。'),
('JPN', '诗篇', 19, 31, 1, '主よ私はあなたに身を避けています。私が決して恥を見ないようにしてください。あなたの義によって私を助け出してください。'),
('JPN', '诗篇', 19, 31, 2, '私に耳を傾け急いで私を救い出してください。私の力の岩となり強い砦となって救ってください。'),
('JPN', '诗篇', 19, 31, 3, 'あなたこそ私の巌私の砦。あなたの御名のゆえに私を導き私を伴ってください。'),
('JPN', '诗篇', 19, 31, 4, 'あなたは私を狙って隠された網から私を引き出してくださいます。あなたは私の力です。'),
('JPN', '诗篇', 19, 31, 5, '私の霊をあなたの御手にゆだねます。まことの神主よ。あなたは私を贖い出してくださいます。'),
('JPN', '诗篇', 19, 31, 6, '空しい偶像につく者を私は憎みます。この私は主に信頼しています。'),
('JPN', '诗篇', 19, 31, 7, 'あなたの恵みを私は楽しみ喜びます。あなたは私の悩みをご覧になり私のたましいの苦しみをご存じです。'),
('JPN', '诗篇', 19, 31, 8, 'あなたは私を敵の手に引き渡さず私の足を広いところに立たせてくださいました。'),
('JPN', '诗篇', 19, 31, 9, '私をあわれんでください。主よ。私は苦しんでいるのです。私の目は苦悶で衰え果てました。私のたましいも私のからだも。'),
('JPN', '诗篇', 19, 31, 10, '悲しみのうちに私のいのちは尽き嘆きのうちに私の年は果てました。私の咎によって私の力は弱まり私の骨は衰えてしまいました。'),
('JPN', '诗篇', 19, 31, 11, '敵対するすべての者から私はそしられました。わけても私の隣人から。知り合いには恐れられ外で私を見る者は私を避けて離れ去ります。'),
('JPN', '诗篇', 19, 31, 12, '死人のように私は人の心から忘れられ壊れた器のようになりました。'),
('JPN', '诗篇', 19, 31, 13, '私は多くの者がささやくうわさを聞きました。「恐怖が取り囲んでいる」と。彼らは私に対して謀議をめぐらし私のいのちを取ろうと図りました。'),
('JPN', '诗篇', 19, 31, 14, 'しかし主よ私はあなたに信頼します。私は告白します。「あなたこそ私の神です。」'),
('JPN', '诗篇', 19, 31, 15, '私の時は御手の中にあります。私を救い出してください。敵の手から追い迫る者の手から。'),
('JPN', '诗篇', 19, 31, 16, '御顔をしもべの上に照り輝かせてください。あなたの恵みによって私をお救いください。'),
('JPN', '诗篇', 19, 31, 17, '主よ私が恥を見ないようにしてください。私はあなたを呼び求めていますから。悪しき者どもを辱めてください。彼らが黙ってよみへと下るように。'),
('JPN', '诗篇', 19, 31, 18, '偽りの唇を封じてください。それは正しい者に横柄に語っています。高ぶりと蔑みをもって。'),
('JPN', '诗篇', 19, 31, 19, 'なんと大きいのでしょう。あなたのいつくしみは。あなたを恐れる者のためにあなたはそれを蓄えあなたに身を避ける者のために人の子らの目の前でそれを備えられました。'),
('JPN', '诗篇', 19, 31, 20, 'あなたは彼らを人のそしりから御顔の前にひそかにかくまい舌の争いから隠れ場に隠されます。'),
('JPN', '诗篇', 19, 31, 21, '主はほむべきかな。主は堅固な城壁の町の中で私に奇しい恵みを施してくださいました。'),
('JPN', '诗篇', 19, 31, 22, '私はうろたえて言いました。「私はあなたの目の前から断たれたのだ」と。しかし私の願いの声をあなたは聞かれました。私があなたに叫び求めたときに。'),
('JPN', '诗篇', 19, 31, 23, '主を愛せよ。すべて主にある敬虔な者たち。主は誠実な者を保たれるが高ぶる者には厳しく報いをされる。'),
('JPN', '诗篇', 19, 31, 24, '雄々しくあれ。心を強くせよ。すべて主を待ち望む者よ。'),
('JPN', '诗篇', 19, 32, 1, '幸いなことよその背きを赦され罪をおおわれた人は。'),
('JPN', '诗篇', 19, 32, 2, '幸いなことよ主が咎をお認めにならずその霊に欺きがない人は。'),
('JPN', '诗篇', 19, 32, 3, '私が黙っていたとき私の骨は疲れきり私は一日中うめきました。'),
('JPN', '诗篇', 19, 32, 4, '昼も夜も御手が私の上に重くのしかかり骨の髄さえ夏の日照りで乾ききったからです。セラ'),
('JPN', '诗篇', 19, 32, 5, '私は自分の罪をあなたに知らせ自分の咎を隠しませんでした。私は言いました。「私の背きを主に告白しよう」と。するとあなたは私の罪のとがめを赦してくださいました。セラ'),
('JPN', '诗篇', 19, 32, 6, 'それゆえ敬虔な人はみな祈ります。あなたに向かってあなたがおられるうちに。大水は濁流となっても彼のところに届きません。'),
('JPN', '诗篇', 19, 32, 7, 'あなたは私の隠れ場。あなたは苦しみから私を守り救いの歓声で私を囲んでくださいます。セラ'),
('JPN', '诗篇', 19, 32, 8, '私はあなたが行く道であなたを教えあなたを諭そう。あなたに目を留め助言を与えよう。'),
('JPN', '诗篇', 19, 32, 9, 'あなたがたは分別のない馬やらばのようであってはならない。くつわや手綱そうした馬具で強いるのでなければそれらはあなたの近くには来ない。'),
('JPN', '诗篇', 19, 32, 10, '悪しき者は心の痛みが多い。しかし主に信頼する者は恵みがその人を囲んでいる。'),
('JPN', '诗篇', 19, 32, 11, '正しい者たち主を喜び楽しめ。すべて心の直ぐな人たちよ喜びの声をあげよ。'),
('JPN', '诗篇', 19, 33, 1, '正しい者たち主を喜び歌え。賛美は直ぐな人たちにふさわしい。'),
('JPN', '诗篇', 19, 33, 2, '竪琴に合わせて主に感謝せよ。十弦の琴に合わせてほめ歌を歌え。'),
('JPN', '诗篇', 19, 33, 3, '新しい歌を主に歌え。喜びの叫びとともに巧みに弦をかき鳴らせ。'),
('JPN', '诗篇', 19, 33, 4, 'まことに主のことばは真っ直ぐでそのみわざはことごとく真実である。'),
('JPN', '诗篇', 19, 33, 5, '主は正義と公正を愛される。主の恵みで地は満ちている。'),
('JPN', '诗篇', 19, 33, 6, '主のことばによって天は造られた。天の万象もすべて御口の息吹によって。'),
('JPN', '诗篇', 19, 33, 7, '主は海の水をせき止めて集め湧き出る水を倉に納められる。'),
('JPN', '诗篇', 19, 33, 8, '全地よ主を恐れよ。すべて世界に住む者よ主の御前におののけ。'),
('JPN', '诗篇', 19, 33, 9, '主が仰せられるとそのようになり主が命じられるとそれは立つ。'),
('JPN', '诗篇', 19, 33, 10, '主は国々のはかりごとを破りもろもろの民の計画をくじかれる。'),
('JPN', '诗篇', 19, 33, 11, '主のはかられることはとこしえに立ちみこころの計画は代々に続く。'),
('JPN', '诗篇', 19, 33, 12, '幸いなことよ主を自らの神とする国は。神がご自分のゆずりとして選ばれた民は。'),
('JPN', '诗篇', 19, 33, 13, '主は天から目を注ぎ人の子らをすべてご覧になる。'),
('JPN', '诗篇', 19, 33, 14, '御座が据えられた所から地に住むすべての者に目を留められる。'),
('JPN', '诗篇', 19, 33, 15, '主は一人ひとりの心を形造りわざのすべてを読み取る方。'),
('JPN', '诗篇', 19, 33, 16, '王は軍勢の大きさでは救われない。勇者は力の大きさでは救い出されない。'),
('JPN', '诗篇', 19, 33, 17, '軍馬も勝利の頼みにはならず軍勢の大きさも救いにはならない。'),
('JPN', '诗篇', 19, 33, 18, '見よ主の目は主を恐れる者に注がれる。主の恵みを待ち望む者に。'),
('JPN', '诗篇', 19, 33, 19, '彼らのたましいを死から救い出し飢饉のときにも彼らを生かし続けるために。'),
('JPN', '诗篇', 19, 33, 20, '私たちのたましいは主を待ち望む。主は私たちの助け私たちの盾。'),
('JPN', '诗篇', 19, 33, 21, 'まことに私たちの心は主を喜び私たちは聖なる御名に拠り頼む。'),
('JPN', '诗篇', 19, 33, 22, '主よあなたの恵みが私たちの上にありますように。私たちがあなたを待ち望むときに。'),
('JPN', '诗篇', 19, 34, 1, '私はあらゆるときに主をほめたたえる。私の口にはいつも主への賛美がある。'),
('JPN', '诗篇', 19, 34, 2, '私のたましいは主を誇る。貧しい者はそれを聞いて喜ぶ。'),
('JPN', '诗篇', 19, 34, 3, '私とともに主をほめよ。一つになって御名をあがめよう。'),
('JPN', '诗篇', 19, 34, 4, '私が主を求めると主は答えすべての恐怖から私を救い出してくださった。'),
('JPN', '诗篇', 19, 34, 5, '主を仰ぎ見ると彼らは輝いた。彼らの顔は辱められることがない。'),
('JPN', '诗篇', 19, 34, 6, 'この苦しむ者が呼ぶと主は聞かれすべての苦難から救ってくださった。'),
('JPN', '诗篇', 19, 34, 7, '主の使いは主を恐れる者の周りに陣を張り彼らを助け出される。'),
('JPN', '诗篇', 19, 34, 8, '味わい見つめよ。主がいつくしみ深い方であることを。幸いなことよ主に身を避ける人は。'),
('JPN', '诗篇', 19, 34, 9, '主を恐れよ。主の聖徒たちよ。主を恐れる者には乏しいことがないからだ。'),
('JPN', '诗篇', 19, 34, 10, '若い獅子も乏しくなり飢える。しかし主を求める者は良いものに何一つ欠けることがない。'),
('JPN', '诗篇', 19, 34, 11, '来なさい。子たちよ私に聞きなさい。主を恐れることを教えよう。'),
('JPN', '诗篇', 19, 34, 12, 'いのちを喜びとする人はだれか。幸せを見ようと日数の多いことを愛する人は。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '诗篇', 19, 34, 13, 'あなたの舌に悪口を言わせず唇に欺きを語らせるな。'),
('JPN', '诗篇', 19, 34, 14, '悪を離れて善を行い平和を求めそれを追い続けよ。'),
('JPN', '诗篇', 19, 34, 15, '主の目は正しい人たちの上にあり主の耳は彼らの叫びに傾けられる。'),
('JPN', '诗篇', 19, 34, 16, '主の御顔は悪をなす者どもに敵対し主は彼らの記憶を地から消し去られる。'),
('JPN', '诗篇', 19, 34, 17, '苦しむ者が叫ぶと主は聞かれそのすべての苦難から救い出してくださる。'),
('JPN', '诗篇', 19, 34, 18, '主は心の打ち砕かれた者の近くにおられ霊の砕かれた者を救われる。'),
('JPN', '诗篇', 19, 34, 19, '正しい人には苦しみが多い。しかし主はそのすべてから救い出してくださる。'),
('JPN', '诗篇', 19, 34, 20, '主は彼の骨をことごとく守りその一つさえ折られることはない。'),
('JPN', '诗篇', 19, 34, 21, '悪は悪しき者を殺し正しい人を憎む者は責めを負う。'),
('JPN', '诗篇', 19, 34, 22, '主はそのしもべのたましいを贖い出される。主に身を避ける人はだれも責めを負わない。'),
('JPN', '诗篇', 19, 35, 1, '主よ私と争う者と争い私と戦う者と戦ってください。'),
('JPN', '诗篇', 19, 35, 2, '盾と大盾を手に取って私を助けに来てください。'),
('JPN', '诗篇', 19, 35, 3, '槍を抜き私に追い迫る者たちを封じてください。私のたましいに言ってください。「わたしがあなたの救いだ」と。'),
('JPN', '诗篇', 19, 35, 4, '私のいのちを求める者たちが恥を見卑しめられますように。私に対してわざわいを謀る者たちが退き辱めを受けますように。'),
('JPN', '诗篇', 19, 35, 5, '彼らを風の前の籾殻のようにし主の使いが追い散らすようにしてください。'),
('JPN', '诗篇', 19, 35, 6, '彼らの道を暗闇とし滑りやすくし主の使いが彼らを追うようにしてください。'),
('JPN', '诗篇', 19, 35, 7, 'ゆえもなく彼らは隠しました。網を張った穴を私のために。ゆえもなくそれを掘りました。私のたましいのために。'),
('JPN', '诗篇', 19, 35, 8, '思わぬときに滅びが彼を襲いますように。隠した網が彼を捕らえ滅びの中に彼が落ち込みますように。'),
('JPN', '诗篇', 19, 35, 9, '私のたましいは主にあって喜び御救いの中にあって楽しみます。'),
('JPN', '诗篇', 19, 35, 10, '私のすべての骨は言います。「主よだれがあなたのようでしょう。苦しむ者をより強い者から救い苦しむ者貧しい者を略奪者から救う方。」'),
('JPN', '诗篇', 19, 35, 11, '悪意のある証人どもが立ち私が知らないことを私に問います。'),
('JPN', '诗篇', 19, 35, 12, '彼らは悪をもって善に報い私のたましいは見捨てられています。'),
('JPN', '诗篇', 19, 35, 13, 'しかし私は彼らが病のとき粗布をまといました。私は断食してたましいを苦しめ私の祈りは胸の中を行き来していました。'),
('JPN', '诗篇', 19, 35, 14, '私の友や兄弟であるかのように私は足を運び母の喪に服するようにうなだれて泣き悲しみました。'),
('JPN', '诗篇', 19, 35, 15, 'それなのに私がつまずくと彼らは喜んで集まり私の知らない攻撃者が私に向かって集まり休みなく私を中傷しました。'),
('JPN', '诗篇', 19, 35, 16, '嘲りののしる者たちは私の周りで私に向かって歯をむき出しました。'),
('JPN', '诗篇', 19, 35, 17, 'わが主よいつまで眺めておられるのですか。私のたましいを彼らの略奪から私のただ一つのものを若い獅子から奪い返してください。'),
('JPN', '诗篇', 19, 35, 18, '私は大いなる会衆の中であなたに感謝し力強い民の間であなたを賛美します。'),
('JPN', '诗篇', 19, 35, 19, '偽り者の私の敵を私のことで喜ばせないでください。ゆえもなく私を憎む人々が目くばせし合わないようにしてください。'),
('JPN', '诗篇', 19, 35, 20, '彼らは平和を語らず地の平穏な人々に欺きを企むからです。'),
('JPN', '诗篇', 19, 35, 21, '彼らは私に向かって大きく口を開け「あははこの目で見たぞ」と言います。'),
('JPN', '诗篇', 19, 35, 22, '主よあなたはご覧になりました。黙っていないでください。わが主よ私から遠く離れないでください。'),
('JPN', '诗篇', 19, 35, 23, '奮い立ってください。目を覚ましてください。私のさばきのために。わが神わが主よ私の訴えのために。'),
('JPN', '诗篇', 19, 35, 24, 'あなたの義にしたがって私のためにさばきを行ってください。主よわが神よ彼らを私のことで喜ばせないでください。'),
('JPN', '诗篇', 19, 35, 25, '彼らに心のうちで言わせないでください。「あははわれわれの望みどおりだ」と。どうか言わせないでください。「われわれは彼を吞み込んだ」と。'),
('JPN', '诗篇', 19, 35, 26, '私のわざわいを楽しむ者たちがみな恥を見辱めを受けますように。私に向かって高ぶる者が恥と恥辱を身にまといますように。'),
('JPN', '诗篇', 19, 35, 27, '私の義を喜びとする者たちが喜びの声をあげ楽しむようにしてください。彼らがいつもこう言うようにしてください。「主は大いなるかな。ご自分のしもべの平和を喜ばれる方は」と。'),
('JPN', '诗篇', 19, 35, 28, '私の舌は告げ知らせます。あなたの義を。日夜あなたの誉れを。'),
('JPN', '诗篇', 19, 36, 1, '私の心の奥にまで悪しき者の背きのことばが届く。彼の目の前には神に対する恐れがない。'),
('JPN', '诗篇', 19, 36, 2, '彼は自分の判断で自分を偽り自分の咎を見つけてそれを憎む。'),
('JPN', '诗篇', 19, 36, 3, '彼の口のことばは不法と欺き。思慮深くあろうともせず善を行おうともしない。'),
('JPN', '诗篇', 19, 36, 4, '彼は寝床で不法を謀り良くない道に堅く立ち悪を捨てようとしない。'),
('JPN', '诗篇', 19, 36, 5, '主よあなたの恵みは天にありあなたの真実は雲にまで及びます。'),
('JPN', '诗篇', 19, 36, 6, 'あなたの義は高くそびえる山。あなたのさばきは大いなる淵。主よあなたは人や獣を救ってくださいます。'),
('JPN', '诗篇', 19, 36, 7, '神よあなたの恵みはなんと尊いことでしょう。人の子らは御翼の陰に身を避けます。'),
('JPN', '诗篇', 19, 36, 8, '彼らはあなたの家の豊かさに満たされあなたは楽しみの流れで潤してくださいます。'),
('JPN', '诗篇', 19, 36, 9, 'いのちの泉はあなたとともにありあなたの光のうちに私たちは光を見るからです。'),
('JPN', '诗篇', 19, 36, 10, '注いでください。あなたの恵みをあなたを知る者に。あなたの義を心の直ぐな人たちに。'),
('JPN', '诗篇', 19, 36, 11, '高ぶりの足が私に追いつかず悪しき者の手が私を追いやることのないように。'),
('JPN', '诗篇', 19, 36, 12, 'そこでは不法を行う者は倒れ突き倒されて立ち上がれません。'),
('JPN', '诗篇', 19, 37, 1, '悪を行う者に腹を立てるな。不正を行う者にねたみを起こすな。'),
('JPN', '诗篇', 19, 37, 2, '彼らは草のようにたちまちしおれ青草のように枯れるのだから。'),
('JPN', '诗篇', 19, 37, 3, '主に信頼し善を行え。地に住み誠実を養え。'),
('JPN', '诗篇', 19, 37, 4, '主を自らの喜びとせよ。主はあなたの心の願いをかなえてくださる。'),
('JPN', '诗篇', 19, 37, 5, 'あなたの道を主にゆだねよ。主に信頼せよ。主が成し遂げてくださる。'),
('JPN', '诗篇', 19, 37, 6, '主はあなたの義を光のようにあなたの正しさを真昼のように輝かされる。'),
('JPN', '诗篇', 19, 37, 7, '主の前に静まり耐え忍んで主を待て。その道が栄えている者や悪意を遂げようとする者に腹を立てるな。'),
('JPN', '诗篇', 19, 37, 8, '怒ることをやめ憤りを捨てよ。腹を立てるな。それはただ悪への道だ。'),
('JPN', '诗篇', 19, 37, 9, '悪を行う者は断ち切られ主を待ち望む者彼らが地を受け継ぐからだ。'),
('JPN', '诗篇', 19, 37, 10, 'もうしばらくで悪しき者はいなくなる。その居所を調べてもそこにはいない。'),
('JPN', '诗篇', 19, 37, 11, 'しかし柔和な人は地を受け継ぎ豊かな繁栄を自らの喜びとする。'),
('JPN', '诗篇', 19, 37, 12, '悪しき者は正しい人に敵対して事を謀り彼に向かって歯をむき出す。'),
('JPN', '诗篇', 19, 37, 13, '主は悪しき者を笑われる。彼の日が来るのをご覧になるから。'),
('JPN', '诗篇', 19, 37, 14, '悪しき者は剣を抜き弓を引いた。苦しむ人貧しい人を打ち倒し行いの正しい人を切り殺すために。'),
('JPN', '诗篇', 19, 37, 15, '彼らの剣は自分の胸を貫き彼らの弓はへし折られる。'),
('JPN', '诗篇', 19, 37, 16, '一人の正しい人が持つわずかなものは多くの悪しき者が持つ富にまさる。'),
('JPN', '诗篇', 19, 37, 17, '悪しき者の腕はへし折られるが主は正しい人を支えられるからだ。'),
('JPN', '诗篇', 19, 37, 18, '主は全き人の日々を知っておられ彼らのゆずりは永久に続く。'),
('JPN', '诗篇', 19, 37, 19, '彼らはわざわいのときにも恥を見ず飢饉のときにも満ち足りる。'),
('JPN', '诗篇', 19, 37, 20, 'しかし悪しき者は滅びる。主の敵は牧場の青草のようだ。彼らは消え失せる。煙となって消え失せる。'),
('JPN', '诗篇', 19, 37, 21, '悪しき者は借りるが返さない。正しい人は情け深く人に施す。'),
('JPN', '诗篇', 19, 37, 22, '主に祝福された人は地を受け継ぎ主にのろわれた者は断ち切られる。'),
('JPN', '诗篇', 19, 37, 23, '主によって人の歩みは確かにされる。主はその人の道を喜ばれる。'),
('JPN', '诗篇', 19, 37, 24, 'その人は転んでも倒れ伏すことはない。主がその人の腕を支えておられるからだ。'),
('JPN', '诗篇', 19, 37, 25, '若かったころも年老いた今も私は見たことがない。正しい人が見捨てられることを。その子孫が食べ物を乞うことを。'),
('JPN', '诗篇', 19, 37, 26, 'その人はいつも情け深く人に貸す。その子孫は祝福を得る。'),
('JPN', '诗篇', 19, 37, 27, '悪を離れて善を行え。いつまでも地に住め。'),
('JPN', '诗篇', 19, 37, 28, 'まことに主は義を愛し主にある敬虔な人をお見捨てにならない。彼らは永遠に保たれるが悪しき者どもの子孫は断ち切られる。'),
('JPN', '诗篇', 19, 37, 29, '正しい人は地を受け継ぎいつまでもそこに住む。'),
('JPN', '诗篇', 19, 37, 30, '正しい人の口は知恵を語りその舌は義を告げる。'),
('JPN', '诗篇', 19, 37, 31, 'その心には彼の神のみおしえがあり彼の歩みはよろけることがない。'),
('JPN', '诗篇', 19, 37, 32, '悪しき者は正しい人を待ち伏せ彼を殺そうとする。'),
('JPN', '诗篇', 19, 37, 33, '主は悪しき者の手の中に彼を捨て置かずさばきのときにも彼を不義に定めない。'),
('JPN', '诗篇', 19, 37, 34, '主を待ち望め。主の道を守れ。主はあなたを高く上げ地を受け継がせてくださる。あなたは悪しき者どもが断ち切られるのを見る。'),
('JPN', '诗篇', 19, 37, 35, '私は悪しき者の横暴を見た。彼は野生の木のようにはびこっていた。'),
('JPN', '诗篇', 19, 37, 36, 'だが彼は過ぎ去った。見よ彼はもういない。私は捜したが見つからなかった。'),
('JPN', '诗篇', 19, 37, 37, '全き人に目を留め直ぐな人を見よ。平和の人には未来がある。'),
('JPN', '诗篇', 19, 37, 38, 'しかし背く者はことごとく滅ぼされ悪しき者どもの未来は断ち切られる。'),
('JPN', '诗篇', 19, 37, 39, '正しい人の救いは主から来る。苦難のときの彼らの砦から。'),
('JPN', '诗篇', 19, 37, 40, '主は彼らを助け解き放たれる。悪しき者どもから解き放ち彼らを救われる。彼らが主に身を避けているからだ。'),
('JPN', '诗篇', 19, 38, 1, '主よあなたの激しい怒りで私を責めないでください。あなたの大いなる憤りで私を懲らしめないでください。'),
('JPN', '诗篇', 19, 38, 2, 'あなたの矢が私に突き刺さり御手が私に激しく下りました。'),
('JPN', '诗篇', 19, 38, 3, 'あなたの憤りのため私の肉には完全なところがなく私の罪のゆえ私の骨には健全なところがありません。'),
('JPN', '诗篇', 19, 38, 4, '私の咎が頭を越えるほどになり重荷となって担いきれません。'),
('JPN', '诗篇', 19, 38, 5, '私の傷は悪臭を放って腐り果てました。それは私の愚かさのためです。'),
('JPN', '诗篇', 19, 38, 6, '私は身をかがめ深くうなだれ一日中嘆いて歩き回ります。'),
('JPN', '诗篇', 19, 38, 7, '私の腰は火傷でおおい尽くされ私の肉にはどこにも完全なところがありません。'),
('JPN', '诗篇', 19, 38, 8, '私は衰え果て砕き尽くされ心もだえてほえ叫んでいます。'),
('JPN', '诗篇', 19, 38, 9, '主よ私の願いはすべてあなたの御前にあり私の嘆きはあなたに隠れてはいません。'),
('JPN', '诗篇', 19, 38, 10, '私の胸は激しく鼓動し私の力は私を見捨て目の光さえも私から失せてしまいました。'),
('JPN', '诗篇', 19, 38, 11, '愛する者や私の友も私の病を避けて立ち近親の者でさえ遠く離れて立っています。'),
('JPN', '诗篇', 19, 38, 12, '私のいのちを求める者は罠を仕掛け私のわざわいを願い求める者は私の破滅を告げ絶えず欺くことを語っています。'),
('JPN', '诗篇', 19, 38, 13, 'しかし私は聞きません。聞こえない人のように。口を開きません。話せない人のように。'),
('JPN', '诗篇', 19, 38, 14, 'まるで私は耳が聞こえず口で争わない人のようです。'),
('JPN', '诗篇', 19, 38, 15, 'まことに主よあなたを私は待ち望んでいます。わが神主よあなたが私に答えてくださいます。'),
('JPN', '诗篇', 19, 38, 16, '私は思いました。彼らが私のことで喜ぶのではないか。私の足がよろけるとき私に対して高ぶるのではないかと。'),
('JPN', '诗篇', 19, 38, 17, '私はつまずき倒れそうで痛みが絶えずともにあります。'),
('JPN', '诗篇', 19, 38, 18, '私は自分の咎を言い表します。自分の罪で不安なのです。'),
('JPN', '诗篇', 19, 38, 19, '私の敵は活気に満ちて強く私を憎む偽り者が多くいます。'),
('JPN', '诗篇', 19, 38, 20, '悪をもって善に報いる者どもは私が善を追い求めると私をなじります。'),
('JPN', '诗篇', 19, 38, 21, '主よ私を見捨てないでください。わが神よ私から遠く離れないでください。'),
('JPN', '诗篇', 19, 38, 22, '急いで私を助けてください。主よ私の救いよ。'),
('JPN', '诗篇', 19, 39, 1, '私は言った。私は自分の道に気をつけよう。私が舌で罪を犯さないように。口に口輪をはめておこう。悪しき者が私の前にいる間は。'),
('JPN', '诗篇', 19, 39, 2, '私はひたすら黙っていた。良いことにさえ沈黙した。そのため私の痛みは激しくなった。'),
('JPN', '诗篇', 19, 39, 3, '心は私のうちで熱くなりうめきとともに火が燃え上がった。そこで私は自分の舌で言った。'),
('JPN', '诗篇', 19, 39, 4, '主よお知らせください。私の終わり私の齢がどれだけなのか。私がいかにはかないかを知ることができるように。'),
('JPN', '诗篇', 19, 39, 5, 'ご覧ください。あなたは私の日数を手幅ほどにされました。あなたの御前では私の一生はないも同然です。人はみなしっかり立ってはいても実に空しいかぎりです。セラ'),
('JPN', '诗篇', 19, 39, 6, 'まことに人は幻のように歩き回りまことに空しく立ち騒ぎます。人は蓄えるがだれのものになるのか知りません。'),
('JPN', '诗篇', 19, 39, 7, '主よ今私は何を待ち望みましょう。私の望みそれはあなたです。'),
('JPN', '诗篇', 19, 39, 8, '私のすべての背きから私を助け出してください。私を愚か者のそしりの的としないでください。'),
('JPN', '诗篇', 19, 39, 9, '私は黙し口を開きません。あなたがそうなさったからです。'),
('JPN', '诗篇', 19, 39, 10, 'どうかあなたのむちを取り去ってください。あなたの手に打たれて私は衰え果てました。'),
('JPN', '诗篇', 19, 39, 11, 'あなたは不義を責めて人を懲らしめシミが食うように人の欲するものをなくされます。実に人はみな空しいものです。セラ'),
('JPN', '诗篇', 19, 39, 12, '主よ私の祈りを聞いてください。助けを求める叫びに耳を傾けてください。私の涙に黙っていないでください。私はあなたとともにいる旅人すべての先祖のように寄留の者なのです。'),
('JPN', '诗篇', 19, 39, 13, '私を見つめないでください。私が朗らかになれるようにしてください。私が去っていなくなる前に。'),
('JPN', '诗篇', 19, 40, 1, '私は切に主を待ち望んだ。主は私に耳を傾け助けを求める叫びを聞いてくださった。'),
('JPN', '诗篇', 19, 40, 2, '滅びの穴から泥沼から主は私を引き上げてくださった。私の足を巌に立たせ私の歩みを確かにされた。'),
('JPN', '诗篇', 19, 40, 3, '主はこの口に授けてくださった。新しい歌を私たちの神への賛美を。多くの者は見て恐れ主に信頼するだろう。'),
('JPN', '诗篇', 19, 40, 4, '幸いなことよ主に信頼を置き高ぶる者や偽りに傾く者たちの方を向かない人。'),
('JPN', '诗篇', 19, 40, 5, 'わが神主よなんと多いことでしょう。あなたがなさった奇しいみわざと私たちへの計らいは。あなたに並ぶ者はありません。語ろうとしても告げようとしてもそれはあまりに多くて数えきれません。'),
('JPN', '诗篇', 19, 40, 6, 'あなたはいけにえや穀物のささげ物をお喜びにはなりませんでした。あなたは私の耳を開いてくださいました。全焼のささげ物や罪のきよめのささげ物をあなたはお求めになりませんでした。'),
('JPN', '诗篇', 19, 40, 7, 'そのとき私は申し上げました。「今私はここに来ております。巻物の書に私のことが書いてあります。'),
('JPN', '诗篇', 19, 40, 8, 'わが神よ私はあなたのみこころを行うことを喜びとします。あなたのみおしえは私の心のうちにあります。」'),
('JPN', '诗篇', 19, 40, 9, '私は大いなる会衆の中で義を喜び知らせます。ご覧ください。私は唇を押さえません。主よあなたはご存じです。'),
('JPN', '诗篇', 19, 40, 10, '私はあなたの義を心の中におおい隠さずあなたの真実とあなたの救いを言い表します。私はあなたの恵みとあなたのまことを大いなる会衆に隠しません。'),
('JPN', '诗篇', 19, 40, 11, '主よあなたは私にあわれみを惜しまないでください。あなたの恵みとあなたのまことが絶えず私を見守るようにしてください。'),
('JPN', '诗篇', 19, 40, 12, '数えきれないわざわいが私を取り囲んでいるのです。私の咎が襲いかかり私は何も見ることができません。それは私の髪の毛よりも多く私の心も私を見捨てました。'),
('JPN', '诗篇', 19, 40, 13, '主よみこころによって私を救い出してください。主よ急いで私を助けてください。'),
('JPN', '诗篇', 19, 40, 14, '私のいのちを求め滅ぼそうとする者たちがことごとく恥を見辱められますように。私のわざわいを喜ぶ者たちが退き卑しめられますように。'),
('JPN', '诗篇', 19, 40, 15, '私を「あはは」とあざ笑う者どもが自らの恥に啞然としますように。'),
('JPN', '诗篇', 19, 40, 16, 'あなたを慕い求める人たちがみなあなたにあって楽しみ喜びますように。あなたの救いを愛する人たちが「主は大いなる方」といつも言いますように。'),
('JPN', '诗篇', 19, 40, 17, '私は苦しむ者貧しい者です。主が私を顧みてくださいますように。あなたは私の助け私を救い出す方。わが神よ遅れないでください。'),
('JPN', '诗篇', 19, 41, 1, '幸いなことよ弱っている者に心を配る人は。わざわいの日に主はその人を助け出される。'),
('JPN', '诗篇', 19, 41, 2, '主は彼を見守り彼を生かし地上で幸せな者とされる。どうか彼を敵の意のままにさせないでください。'),
('JPN', '诗篇', 19, 41, 3, '主が病の床で彼を支えられますように。彼が病むとき寝床から起き上がらせてください。'),
('JPN', '诗篇', 19, 41, 4, '私は申し上げます。「主よあわれんでください。私のたましいを癒やしてください。私はあなたの前に罪ある者ですから。」'),
('JPN', '诗篇', 19, 41, 5, '私の敵は私の悪口を言います。「いつ彼は死にその名は消え去るのだろうか。」'),
('JPN', '诗篇', 19, 41, 6, '人が見舞いに来てもその人は噓を言い心のうちでは悪意を蓄え外に出てはそれを言いふらします。'),
('JPN', '诗篇', 19, 41, 7, '私を憎む者はみな私についてともにささやき私に対して悪を企みます。'),
('JPN', '诗篇', 19, 41, 8, '「邪悪なものが彼に取りついている。彼が床についたからにはもう二度と起き上がれまい。」'),
('JPN', '诗篇', 19, 41, 9, '私が信頼した親しい友が私のパンを食べている者までが私に向かってかかとを上げます。'),
('JPN', '诗篇', 19, 41, 10, 'しかし主よ。あなたは私をあわれみ立ち上がらせてください。そうすれば彼らに報いを返せます。'),
('JPN', '诗篇', 19, 41, 11, 'このことによって私は知ります。あなたが私を喜んでおられることを。敵は私に向かって勝ちどきをあげません。'),
('JPN', '诗篇', 19, 41, 12, '私の誠実さゆえに私を強く支えてください。いつまでもあなたの御前に立たせてください。'),
('JPN', '诗篇', 19, 41, 13, 'ほむべきかなイスラエルの神主。とこしえからとこしえまで。アーメン、アーメン。'),
('JPN', '诗篇', 19, 42, 1, '鹿が谷川の流れを慕いあえぐように神よ私のたましいはあなたを慕いあえぎます。'),
('JPN', '诗篇', 19, 42, 2, '私のたましいは神を生ける神を求めて渇いています。いつになれば私は行って神の御前に出られるのでしょうか。'),
('JPN', '诗篇', 19, 42, 3, '昼も夜も私の涙が私の食べ物でした。「おまえの神はどこにいるのか」と人が絶えず私に言う間。'),
('JPN', '诗篇', 19, 42, 4, '私は自分のうちで思い起こし私のたましいを注ぎ出しています。私が祭りを祝う群衆とともに喜びと感謝の声をあげてあの群れと一緒に神の家へとゆっくり歩んで行ったことなどを。'),
('JPN', '诗篇', 19, 42, 5, 'わがたましいよなぜおまえはうなだれているのか。私のうちで思い乱れているのか。神を待ち望め。私はなおも神をほめたたえる。御顔の救いを。'),
('JPN', '诗篇', 19, 42, 6, '私の神よ私のたましいは私のうちでうなだれています。それゆえ私はヨルダンとヘルモンの地からまたミツアルの山からあなたを思い起こします。'),
('JPN', '诗篇', 19, 42, 7, 'あなたの大滝のとどろきに淵が淵を呼び起こしあなたの波あなたの大波はみな私の上を越えて行きました。'),
('JPN', '诗篇', 19, 42, 8, '昼には主が恵みを下さり夜には主の歌が私とともにあります。私のいのちなる神への祈りが。'),
('JPN', '诗篇', 19, 42, 9, '私はわが巌なる神に申し上げます。「なぜあなたは私をお忘れになったのですか。なぜ私は敵の虐げに嘆いて歩き回るのですか。」'),
('JPN', '诗篇', 19, 42, 10, '私に敵対する者たちは私の骨を砕くほどに私をそしり絶えず私に言っています。「おまえの神はどこにいるのか」と。'),
('JPN', '诗篇', 19, 42, 11, 'わがたましいよなぜおまえはうなだれているのか。なぜ私のうちで思い乱れているのか。神を待ち望め。私はなおも神をほめたたえる。私の救い私の神を。'),
('JPN', '诗篇', 19, 43, 1, '神よ私のためにさばいてください。私の訴えを取り上げ不敬虔な民の言い分を退けてください。欺きと不正の人から私を助け出してください。'),
('JPN', '诗篇', 19, 43, 2, 'あなたは私の力の神であられるからです。なぜあなたは私を退けられたのですか。なぜ私は敵の虐げに嘆いて歩き回るのですか。'),
('JPN', '诗篇', 19, 43, 3, 'どうかあなたの光とまことを送りそれらが私を導くようにしてください。あなたの聖なる山あなたの住まいへとそれらが私を連れて行きますように。'),
('JPN', '诗篇', 19, 43, 4, 'こうして私は神の祭壇に私の最も喜びとする神のみもとに行き竪琴に合わせてあなたをほめたたえます。神よ私の神よ。'),
('JPN', '诗篇', 19, 43, 5, 'わがたましいよなぜおまえはうなだれているのか。なぜ私のうちで思い乱れているのか。神を待ち望め。私はなおも神をほめたたえる。私の救い私の神を。'),
('JPN', '诗篇', 19, 44, 1, '神よ私たちはこの耳で聞きました。先祖たちが語ってくれました。あなたが彼らの時代昔になさったみわざを。'),
('JPN', '诗篇', 19, 44, 2, 'あなたは御手をもって異邦の民を追い払いそこに先祖たちを植えられました。もろもろの国民にわざわいを下しそこに先祖たちを送り込まれました。'),
('JPN', '诗篇', 19, 44, 3, '自分の剣によって彼らは地を得たのではなく自分の腕が彼らを救ったのでもありません。ただあなたの右の手あなたの御腕あなたの御顔の光がそうしたのです。あなたが彼らを愛されたからです。'),
('JPN', '诗篇', 19, 44, 4, '神よあなたこそ私の王です。ヤコブの勝利を命じてください。'),
('JPN', '诗篇', 19, 44, 5, 'あなたによって私たちは敵を押し返し御名によって向かい立つ者どもを踏みつけます。'),
('JPN', '诗篇', 19, 44, 6, '私の弓に私は頼りません。私の剣も私を救いません。'),
('JPN', '诗篇', 19, 44, 7, 'しかしあなたは私たちを敵から救い私たちを憎む者どもを辱められます。'),
('JPN', '诗篇', 19, 44, 8, '神にあって私たちはいつも誇ります。あなたの御名をとこしえにほめたたえます。セラ'),
('JPN', '诗篇', 19, 44, 9, 'それなのにあなたは私たちを退け卑しめられました。あなたはもはや私たちの軍勢とともに出陣なさいません。'),
('JPN', '诗篇', 19, 44, 10, 'あなたは私たちを敵から退かせ私たちを憎む者どもは思うままに略奪しました。'),
('JPN', '诗篇', 19, 44, 11, 'あなたは私たちを餌食となる羊のようにし国々の間に散らされました。'),
('JPN', '诗篇', 19, 44, 12, 'ご自分の民を安く売り渡しその代価で何の利益も得ませんでした。'),
('JPN', '诗篇', 19, 44, 13, 'あなたは私たちを隣人のそしりの的とし周りの者の嘲りとし笑いぐさとされます。'),
('JPN', '诗篇', 19, 44, 14, '私たちを国々の間で物笑いの種としもろもろの民の間で笑いものとされるのです。'),
('JPN', '诗篇', 19, 44, 15, '私の前には絶えず辱めがあり恥が私の顔をおおってしまいました。'),
('JPN', '诗篇', 19, 44, 16, 'それはそしる者とののしる者の声のゆえ敵と復讐する者のゆえでした。'),
('JPN', '诗篇', 19, 44, 17, 'これらすべてが私たちを襲いました。しかし私たちはあなたを忘れずあなたの契約を無にしませんでした。'),
('JPN', '诗篇', 19, 44, 18, '私たちの心はたじろがず私たちの歩みはあなたの道からそれませんでした。'),
('JPN', '诗篇', 19, 44, 19, 'あなたはジャッカルの住みかで私たちを砕き死の陰で私たちをおおわれたのです。'),
('JPN', '诗篇', 19, 44, 20, 'もし私たちが自分たちの神の御名を忘れほかの神に向かって手を伸べ広げたなら'),
('JPN', '诗篇', 19, 44, 21, '神はそれを探り出されないでしょうか。神こそ心の秘密を知っておられるからです。'),
('JPN', '诗篇', 19, 44, 22, 'あなたのために私たちは休みなく殺され屠られる羊と見なされています。'),
('JPN', '诗篇', 19, 44, 23, '起きてください。主よなぜ眠っておられるのですか。目を覚ましてください。いつまでも拒まないでください。'),
('JPN', '诗篇', 19, 44, 24, 'なぜ御顔を隠されるのですか。私たちの苦しみと虐げをお忘れになるのですか。'),
('JPN', '诗篇', 19, 44, 25, '私たちのたましいはちりに伏し私たちの腹は地についています。'),
('JPN', '诗篇', 19, 44, 26, '立ち上がって私たちをお助けください。御恵みのゆえに私たちを贖い出してください。'),
('JPN', '诗篇', 19, 45, 1, 'すばらしいことばで私の心は沸き立っている。王のために私が作った詩を私は歌おう。私の舌は巧みな書記の筆。'),
('JPN', '诗篇', 19, 45, 2, 'あなたは人の子らにまさって麗しい。あなたの唇からは優しさが流れ出る。神がとこしえにあなたを祝福しておられるからだ。'),
('JPN', '诗篇', 19, 45, 3, '勇士よあなたの剣を腰に帯びよ。あなたの威厳とあなたの威光を。'),
('JPN', '诗篇', 19, 45, 4, 'あなたの威光は勝利のうちに進み行け。真理と柔和と義のゆえにあなたの右の手はあなたに教えよ。恐るべきわざを。'),
('JPN', '诗篇', 19, 45, 5, 'あなたの矢は鋭い。国々の民はあなたのもとに倒れ王の敵は気を失う。'),
('JPN', '诗篇', 19, 45, 6, '神よあなたの王座は世々限りなくあなたの王国の杖は公平の杖。'),
('JPN', '诗篇', 19, 45, 7, 'あなたは義を愛し悪を憎む。それゆえ神よあなたの神は喜びの油をあなたに注がれた。あなたに並ぶだれにもまして。'),
('JPN', '诗篇', 19, 45, 8, 'あなたの服はみな没薬アロエシナモンの香りを放ち象牙の宮殿に流れる弦の調べはあなたを喜ばせた。'),
('JPN', '诗篇', 19, 45, 9, 'あなたの貴婦人たちの中には諸国の王の娘らもいて王妃はあなたの右に立つ。オフィルの金を身に着けて。'),
('JPN', '诗篇', 19, 45, 10, '娘よ聞け。心して耳を傾けよ。あなたの民とあなたの父の家を忘れよ。'),
('JPN', '诗篇', 19, 45, 11, 'そうすれば王はあなたの美しさを慕うだろう。彼こそあなたの主。彼の前にひれ伏せ。'),
('JPN', '诗篇', 19, 45, 12, '娘ツロは贈り物を携え民のうちの富む者もあなたの好意を求めて来る。'),
('JPN', '诗篇', 19, 45, 13, '王の娘は奥にいて栄華を極めその衣には黄金が織り合わされている。'),
('JPN', '诗篇', 19, 45, 14, '彼女はあや織物をまとい王の前に導かれる。おとめたちが彼女の後に付き従い彼女はあなたのもとに連れて来られる。'),
('JPN', '诗篇', 19, 45, 15, '喜びと楽しみをもって彼女たちは導かれ王の宮殿に入って行く。'),
('JPN', '诗篇', 19, 45, 16, 'あなたの息子らがあなたの父祖に代わりあなたは彼らを全地の君主に任じる。'),
('JPN', '诗篇', 19, 45, 17, '私はあなたの名を代々にわたって呼び求めよう。それゆえ国々の民は世々限りなくあなたをほめたたえよう。'),
('JPN', '诗篇', 19, 46, 1, '神はわれらの避け所また力。苦しむときそこにある強き助け。'),
('JPN', '诗篇', 19, 46, 2, 'それゆえわれらは恐れない。たとえ地が変わり山々が揺れ海のただ中に移るとも。'),
('JPN', '诗篇', 19, 46, 3, 'たとえその水が立ち騒ぎ泡立ってもその水かさが増し山々が揺れ動いても。セラ'),
('JPN', '诗篇', 19, 46, 4, '川がある。その豊かな流れは神の都を喜ばせる。いと高き方のおられるその聖なる所を。'),
('JPN', '诗篇', 19, 46, 5, '神はそのただ中におられその都は揺るがない。神は朝明けまでにこれを助けられる。'),
('JPN', '诗篇', 19, 46, 6, '国々は立ち騒ぎ諸方の王国は揺らぐ。神が御声を発せられると地は溶ける。'),
('JPN', '诗篇', 19, 46, 7, '万軍の主はわれらとともにおられる。ヤコブの神はわれらの砦である。セラ'),
('JPN', '诗篇', 19, 46, 8, '来て見よ。主のみわざを。主は地で恐るべきことをなされた。'),
('JPN', '诗篇', 19, 46, 9, '主は地の果てまでも戦いをやめさせる。弓をへし折り槍を断ち切り戦車を火で焼かれる。'),
('JPN', '诗篇', 19, 46, 10, '「やめよ。知れ。わたしこそ神。わたしは国々の間であがめられ地の上であがめられる。」'),
('JPN', '诗篇', 19, 46, 11, '万軍の主はわれらとともにおられる。ヤコブの神はわれらの砦である。セラ'),
('JPN', '诗篇', 19, 47, 1, 'すべての国々の民よ手をたたけ。喜びの声をもって神に大声で叫べ。'),
('JPN', '诗篇', 19, 47, 2, 'まことにいと高き方主は恐るべき方。全地を治める大いなる王。'),
('JPN', '诗篇', 19, 47, 3, '国々の民を私たちのもとにもろもろの国民を私たちの足もとに従わせられる。'),
('JPN', '诗篇', 19, 47, 4, '主は私たちのために選んでくださる。私たちの受け継ぐ地を。主が愛されるヤコブの誉れを。セラ'),
('JPN', '诗篇', 19, 47, 5, '神は上られる。喜びの叫びの中を。主は行かれる。角笛の音の中を。'),
('JPN', '诗篇', 19, 47, 6, 'ほめ歌を歌え。神にほめ歌を歌え。ほめ歌を歌え。私たちの王にほめ歌を歌え。'),
('JPN', '诗篇', 19, 47, 7, 'まことに神は全地の王。ことばの限りほめ歌を歌え。'),
('JPN', '诗篇', 19, 47, 8, '神は国々を統べ治めておられる。神はその聖なる王座に着いておられる。'),
('JPN', '诗篇', 19, 47, 9, '国々の民の高貴な者たちは集められた。アブラハムの神の民として。まことに地の盾は神のもの。神は大いにあがめられる方。'),
('JPN', '诗篇', 19, 48, 1, '主は大いなる方。大いにほめたたえられるべき方。主の聖なる山私たちの神の都で。'),
('JPN', '诗篇', 19, 48, 2, '高嶺の麗しさは全地の喜び。北の端なるシオンの山は大王の都。'),
('JPN', '诗篇', 19, 48, 3, '神はその都の宮殿でご自分を砦として示された。'),
('JPN', '诗篇', 19, 48, 4, '見よ王たちは集ってともどもにやって来た。'),
('JPN', '诗篇', 19, 48, 5, '彼らは見ると驚きおじ惑い慌てた。'),
('JPN', '诗篇', 19, 48, 6, 'その場で震えが彼らをとらえた。子を産むときのような激しい痛みが。'),
('JPN', '诗篇', 19, 48, 7, '東風によってあなたはタルシシュの船を砕かれる。'),
('JPN', '诗篇', 19, 48, 8, '私たちは聞いたとおりを見た。万軍の主の都私たちの神の都で。神は都をとこしえに堅く立てられる。セラ'),
('JPN', '诗篇', 19, 48, 9, '神よ私たちはあなたの宮の中であなたの恵みを思いました。'),
('JPN', '诗篇', 19, 48, 10, '神よあなたの御名と同じくあなたの誉れは地の果てにまで及んでいます。あなたの右の手は義に満ちています。'),
('JPN', '诗篇', 19, 48, 11, 'あなたのさばきのゆえにシオンの山が喜びユダの娘たちが楽しみますように。'),
('JPN', '诗篇', 19, 48, 12, 'シオンを巡りその周りを歩け。その塔を数えよ。'),
('JPN', '诗篇', 19, 48, 13, 'その城壁に心を留めよ。その宮殿を巡り歩け。後の時代に語り伝えるために。'),
('JPN', '诗篇', 19, 48, 14, 'この方こそまさしく神。世々限りなくわれらの神。神は死を越えて私たちを導かれる。'),
('JPN', '诗篇', 19, 49, 1, 'すべて国々の民よこれを聞け。すべて世に住む者よ耳を傾けよ。'),
('JPN', '诗篇', 19, 49, 2, '低い者も高い者も富む者も貧しい者もともどもに。'),
('JPN', '诗篇', 19, 49, 3, '私の口は知恵を語り私の心は英知を告げる。'),
('JPN', '诗篇', 19, 49, 4, '私はたとえ話に耳を傾け竪琴に合わせて謎を解き明かそう。'),
('JPN', '诗篇', 19, 49, 5, 'なぜ私はわざわいの日々に恐れなければならないのか。私のかかとを狙う者の悪意が私を取り囲むときに。'),
('JPN', '诗篇', 19, 49, 6, '彼らは自分の財産に拠り頼み豊かな富を誇っている。'),
('JPN', '诗篇', 19, 49, 7, '兄弟さえも人は贖い出すことができない。自分の身代金を神に払うことはできない。'),
('JPN', '诗篇', 19, 49, 8, 'たましいの贖いの代価は高く永久にあきらめなくてはならない。'),
('JPN', '诗篇', 19, 49, 9, '人はいつまでも生きられるだろうか。墓を見ないでいられるだろうか。'),
('JPN', '诗篇', 19, 49, 10, '彼は見る。知恵のある者たちが死に愚かな者浅はかな者も等しく滅び自分の財産を他人に残すのを。'),
('JPN', '诗篇', 19, 49, 11, '彼らの心の中ではその家は永遠で住まいは代々に及ぶ。彼らは土地に自分たちの名をつける。'),
('JPN', '诗篇', 19, 49, 12, 'しかし人は栄華のうちにとどまれない。人は滅び失せる獣に等しい。'),
('JPN', '诗篇', 19, 49, 13, 'これが愚か者の道。彼らに従う者もその口のことばを喜ぶ。セラ'),
('JPN', '诗篇', 19, 49, 14, '彼らは羊のようによみに定められ死が彼らの羊飼いとなる。朝には直ぐな者たちが彼らを支配する。彼らの形はなくなりよみがその住む所となる。'),
('JPN', '诗篇', 19, 49, 15, 'しかし神は私のたましいを贖い出しよみの手から私を奪い返してくださる。セラ'),
('JPN', '诗篇', 19, 49, 16, '恐れるな。人が富を得てもその人の家の栄誉が増し加わっても。'),
('JPN', '诗篇', 19, 49, 17, '人は死ぬとき何一つ持って行くことはできずその栄誉もその人を追って下ることはない。'),
('JPN', '诗篇', 19, 49, 18, 'たとえ人が自分自身を生きている間に祝福できてもあなたには物事がうまく行っていると人々があなたをほめたたえても。'),
('JPN', '诗篇', 19, 49, 19, 'そのたましいは代々の先祖のところに行く。そこでは永久に光を見ることはない。'),
('JPN', '诗篇', 19, 49, 20, '人は栄華のうちにあっても悟ることがなければ滅び失せる獣に等しい。'),
('JPN', '诗篇', 19, 50, 1, '神の神主は語り地を呼び集められる。日の昇るところから沈むところまで。'),
('JPN', '诗篇', 19, 50, 2, '麗しさの極みシオンから神は光を放たれる。'),
('JPN', '诗篇', 19, 50, 3, '私たちの神は来られる。黙ってはおられない。御前には食い尽くす火がありその周りには激しい嵐がある。'),
('JPN', '诗篇', 19, 50, 4, '神は上なる天をまた地を呼び集められる。ご自分の民をさばくために。'),
('JPN', '诗篇', 19, 50, 5, '「わたしにある敬虔な者をわたしのところに集めよ。いけにえによってわたしと契約を結んだ者たちを。」'),
('JPN', '诗篇', 19, 50, 6, '天は神の義を告げ知らせる。神こそが審判者であると。セラ'),
('JPN', '诗篇', 19, 50, 7, '「聞けわが民よ。わたしは語ろう。イスラエルよわたしはあなたを戒めよう。わたしは神あなたの神である。'),
('JPN', '诗篇', 19, 50, 8, 'あなたのいけにえのことであなたを責めるのではない。あなたの全焼のささげ物はいつもわたしの前にある。'),
('JPN', '诗篇', 19, 50, 9, 'わたしはあなたの家から雄牛を囲いから雄やぎを取ろうとしているのではない。'),
('JPN', '诗篇', 19, 50, 10, '森のすべての獣はわたしのもの。千の丘の家畜らも。'),
('JPN', '诗篇', 19, 50, 11, 'わたしは山の鳥も残らず知っている。野に群がるものたちもわたしのもとにいる。'),
('JPN', '诗篇', 19, 50, 12, 'たとえ飢えてもわたしはあなたに言わない。世界とそれに満ちるものはわたしのものだ。'),
('JPN', '诗篇', 19, 50, 13, 'わたしが雄牛の肉を食べ雄やぎの血を飲むだろうか。'),
('JPN', '诗篇', 19, 50, 14, '感謝のいけにえを神に献げよ。あなたの誓いをいと高き神に果たせ。'),
('JPN', '诗篇', 19, 50, 15, '苦難の日にわたしを呼び求めよ。わたしはあなたを助け出しあなたはわたしをあがめる。」'),
('JPN', '诗篇', 19, 50, 16, 'しかし悪しき者に対して神は仰せられる。「何事か。おまえがわたしのおきてを語りわたしの契約を口にするとは。'),
('JPN', '诗篇', 19, 50, 17, 'おまえは戒めを憎みわたしのことばをうしろに投げ捨てた。'),
('JPN', '诗篇', 19, 50, 18, 'おまえは盗人に会うとこれと組んで姦通する者と親しくする。'),
('JPN', '诗篇', 19, 50, 19, 'おまえの口は悪を放ち舌は欺きを仕組む。'),
('JPN', '诗篇', 19, 50, 20, 'おまえは座して兄弟の悪口を言い自分の母の子をそしる。'),
('JPN', '诗篇', 19, 50, 21, 'こういうことをおまえはしてきたがわたしは黙っていた。わたしがおまえと等しい者だとおまえは思っていたのだ。わたしはおまえを責める。おまえの目の前でこれらのことを並べ立てる。'),
('JPN', '诗篇', 19, 50, 22, '神を忘れる者どもよさあこのことをよくわきまえよ。そうでないとわたしはおまえたちを引き裂き救い出す者もいなくなる。'),
('JPN', '诗篇', 19, 50, 23, '感謝のいけにえを献げる者はわたしをあがめる。自分の道を正しくする人にわたしは神の救いを見せる。」'),
('JPN', '诗篇', 19, 51, 1, '神よ私をあわれんでください。あなたの恵みにしたがって。私の背きをぬぐい去ってください。あなたの豊かなあわれみによって。'),
('JPN', '诗篇', 19, 51, 2, '私の咎を私からすっかり洗い去り私の罪から私をきよめてください。'),
('JPN', '诗篇', 19, 51, 3, 'まことに私は自分の背きを知っています。私の罪はいつも私の目の前にあります。'),
('JPN', '诗篇', 19, 51, 4, '私はあなたにただあなたの前に罪ある者です。私はあなたの目に悪であることを行いました。ですからあなたが宣告するときあなたは正しくさばくときあなたは清くあられます。'),
('JPN', '诗篇', 19, 51, 5, 'ご覧ください。私は咎ある者として生まれ罪ある者として母は私を身ごもりました。'),
('JPN', '诗篇', 19, 51, 6, '確かにあなたは心のうちの真実を喜ばれます。どうか私の心の奥に知恵を教えてください。'),
('JPN', '诗篇', 19, 51, 7, 'ヒソプで私の罪を除いてください。そうすれば私はきよくなります。私を洗ってください。そうすれば私は雪よりも白くなります。'),
('JPN', '诗篇', 19, 51, 8, '楽しみと喜びの声を聞かせてください。そうすればあなたが砕かれた骨が喜びます。'),
('JPN', '诗篇', 19, 51, 9, '御顔を私の罪から隠し私の咎をすべてぬぐい去ってください。'),
('JPN', '诗篇', 19, 51, 10, '神よ私にきよい心を造り揺るがない霊を私のうちに新しくしてください。'),
('JPN', '诗篇', 19, 51, 11, '私をあなたの御前から投げ捨てずあなたの聖なる御霊を私から取り去らないでください。'),
('JPN', '诗篇', 19, 51, 12, 'あなたの救いの喜びを私に戻し仕えることを喜ぶ霊で私を支えてください。'),
('JPN', '诗篇', 19, 51, 13, '私は背く者たちにあなたの道を教えます。罪人たちはあなたのもとに帰るでしょう。'),
('JPN', '诗篇', 19, 51, 14, '神よ私の救いの神よ血の罪から私を救い出してください。私の舌はあなたの義を高らかに歌います。'),
('JPN', '诗篇', 19, 51, 15, '主よ私の唇を開いてください。私の口はあなたの誉れを告げ知らせます。'),
('JPN', '诗篇', 19, 51, 16, 'まことに私が供えてもあなたはいけにえを喜ばれず全焼のささげ物を望まれません。'),
('JPN', '诗篇', 19, 51, 17, '神へのいけにえは砕かれた霊。打たれ砕かれた心。神よあなたはそれを蔑まれません。'),
('JPN', '诗篇', 19, 51, 18, 'どうかご恩寵によりシオンにいつくしみを施しエルサレムの城壁を築き直してください。'),
('JPN', '诗篇', 19, 51, 19, 'そのときあなたは義のいけにえを焼き尽くされる全焼のささげ物を喜ばれます。そのとき雄牛があなたの祭壇に献げられます。'),
('JPN', '诗篇', 19, 52, 1, '勇士よなぜおまえは悪を誇りとするのか。神の恵みはいつもある。'),
('JPN', '诗篇', 19, 52, 2, '欺く者よおまえの舌は破壊を企む。まるで鋭い刃物のように。'),
('JPN', '诗篇', 19, 52, 3, 'おまえは善よりも悪を義を語るよりも偽りを愛している。セラ'),
('JPN', '诗篇', 19, 52, 4, '欺きの舌よおまえはあらゆる滅びのことばを愛している。'),
('JPN', '诗篇', 19, 52, 5, 'だが神はおまえを打ち砕いて倒し幕屋からおまえを引き抜かれる。生ける者の地からおまえは根絶やしにされる。セラ'),
('JPN', '诗篇', 19, 52, 6, '正しい人たちは見て恐れ彼に向かって笑う。'),
('JPN', '诗篇', 19, 52, 7, '「見よ彼こそは神を力とせず自分の大きな富に頼り破滅のわざを勝ち誇る者。」'),
('JPN', '诗篇', 19, 52, 8, 'しかし私は神の家に生い茂るオリーブの木。私は世々限りなく神の恵みに拠り頼む。'),
('JPN', '诗篇', 19, 52, 9, '私はとこしえに感謝します。あなたのみわざのゆえに。私はあなたにある敬虔な人たちの前ですばらしいあなたの御名を待ち望みます。'),
('JPN', '诗篇', 19, 53, 1, '愚か者は心の中で「神はいない」と言う。彼らは腐っている。忌まわしい不正を行っている。善を行う者はいない。'),
('JPN', '诗篇', 19, 53, 2, '神は天から人の子らを見下ろされた。悟る者神を求める者がいるかどうかと。'),
('JPN', '诗篇', 19, 53, 3, '彼らはことごとく背き去りだれもかれも無用の者となった。善を行う者はいない。だれ一人いない。'),
('JPN', '诗篇', 19, 53, 4, '不法を行う者たちは知らないのか。彼らはわたしの民を食らいながらパンを食べ神を呼ばない。'),
('JPN', '诗篇', 19, 53, 5, '見よ彼らは恐れのないところで大いに恐れた。神があなたに陣を張る者の骨を散らされたのだ。あなたは彼らを辱めた。神が彼らを捨てられたのだ。'),
('JPN', '诗篇', 19, 53, 6, 'ああイスラエルの救いがシオンから来るように。神が御民を元どおりにされるときヤコブは楽しめ。イスラエルは喜べ。'),
('JPN', '诗篇', 19, 54, 1, '神よあなたの御名によって私をお救いください。あなたの力強いみわざによって私を弁護してください。'),
('JPN', '诗篇', 19, 54, 2, '神よ私の祈りを聞いてください。私の口のことばに耳を傾けてください。'),
('JPN', '诗篇', 19, 54, 3, '見知らぬ者たちが私に立ち向かい横暴な者たちが私のいのちを求めています。彼らは神を前にしていないのです。セラ'),
('JPN', '诗篇', 19, 54, 4, '見よ神は私を助ける方。主は私のいのちを支える方。'),
('JPN', '诗篇', 19, 54, 5, '神は私を待ち伏せる者たちにわざわいをもって報いられます。あなたの真実によって彼らを滅ぼしてください。'),
('JPN', '诗篇', 19, 54, 6, '私は心からのささげ物をもってあなたにいけにえを献げます。主よあなたの御名に感謝します。すばらしい御名に。'),
('JPN', '诗篇', 19, 54, 7, '神がすべての苦難から私を救い出し私の目が敵を平然と眺めるようになったからです。'),
('JPN', '诗篇', 19, 55, 1, '神よ私の祈りを耳に入れ私の切なる願いに耳を閉ざさないでください。'),
('JPN', '诗篇', 19, 55, 2, '私をみこころに留め私に答えてください。私は悲嘆に暮れ泣き叫んでいます。'),
('JPN', '诗篇', 19, 55, 3, 'それは敵の叫びと悪者の迫害のためです。彼らは私にわざわいを降りかからせ怒って私を攻めたてています。'),
('JPN', '诗篇', 19, 55, 4, '私の心は内にもだえ死の恐怖が私を襲っています。'),
('JPN', '诗篇', 19, 55, 5, '恐れと震えが私に起こり戦慄が私を包みました。'),
('JPN', '诗篇', 19, 55, 6, '私は言いました。「ああ私に鳩のように翼があったなら。飛び去って休むことができたなら。'),
('JPN', '诗篇', 19, 55, 7, 'ああどこか遠くへ逃れ去り荒野の中に宿りたい。セラ'),
('JPN', '诗篇', 19, 55, 8, '嵐と疾風を避けて私の逃れ場に急ぎたい。」'),
('JPN', '诗篇', 19, 55, 9, '主よ彼らの舌を混乱させ分裂させてください。私はこの都の中に暴虐と争いを見ています。'),
('JPN', '诗篇', 19, 55, 10, '昼も夜も彼らは城壁の上を歩き回り不法と害悪が都のただ中にあります。'),
('JPN', '诗篇', 19, 55, 11, '破滅が都のただ中にあり虐待と詐欺はその広場を離れません。'),
('JPN', '诗篇', 19, 55, 12, 'まことに私をそしっているのは敵ではない。それなら私は忍ぶことができる。私に向かって高ぶっているのは私を憎む者ではない。それなら私は身を隠すことができる。'),
('JPN', '诗篇', 19, 55, 13, 'それはおまえ。私の同輩私の友私の親友のおまえなのだ。'),
('JPN', '诗篇', 19, 55, 14, '私たちはともに親しく交わりにぎわいの中神の家に一緒に歩いて行ったのに。'),
('JPN', '诗篇', 19, 55, 15, '死が彼らをつかめばよい。彼らは生きたままよみに下るがよい。悪が彼らの住まいに彼らのただ中にあるからだ。'),
('JPN', '诗篇', 19, 55, 16, '私が神を呼ぶと主は私を救ってくださる。'),
('JPN', '诗篇', 19, 55, 17, '夕べに朝にまた真昼に私は嘆きうめく。すると主は私の声を聞いてくださる。'),
('JPN', '诗篇', 19, 55, 18, '主は私のたましいを敵の挑戦から平和のうちに贖い出してくださる。私と争う者が多いから。'),
('JPN', '诗篇', 19, 55, 19, '神は聞き彼らを苦しめられる。昔から御座に着いておられる方は。セラ彼らは改めず神を恐れない。'),
('JPN', '诗篇', 19, 55, 20, '彼は親しい者にまで手を伸ばし自分の誓約を犯している。'),
('JPN', '诗篇', 19, 55, 21, 'その口はよどみなく語るが心には戦いがある。そのことばは油よりも滑らかだがそれは抜き身の剣である。'),
('JPN', '诗篇', 19, 55, 22, 'あなたの重荷を主にゆだねよ。主があなたを支えてくださる。主は決して正しい者が揺るがされるようにはなさらない。'),
('JPN', '诗篇', 19, 55, 23, 'しかし神よあなたは彼らを滅びの穴に落とされます。人の血を流す者どもと欺く者どもは日数の半ばも生きられないでしょう。しかし私はあなたに拠り頼みます。'),
('JPN', '诗篇', 19, 56, 1, '神よ私をあわれんでください。人が私を踏みつけ一日中戦って私を虐げているからです。'),
('JPN', '诗篇', 19, 56, 2, '私の敵は一日中私を踏みつけています。高ぶって私に戦いを挑む者が多いのです。'),
('JPN', '诗篇', 19, 56, 3, '心に恐れを覚える日私はあなたに信頼します。'),
('JPN', '诗篇', 19, 56, 4, '神にあって私はみことばをほめたたえます。神に信頼し私は何も恐れません。肉なる者が私に何をなし得るでしょう。'),
('JPN', '诗篇', 19, 56, 5, '一日中彼らは私のことを痛めつけています。彼らの思い計ることはみな私に対する悪です。'),
('JPN', '诗篇', 19, 56, 6, '彼らは襲おうとして待ち伏せし私の跡をつけています。私のいのちを狙って。'),
('JPN', '诗篇', 19, 56, 7, '不法があるのに彼らを見逃されるのですか。神よ御怒りで国々の民を打ち倒してください。'),
('JPN', '诗篇', 19, 56, 8, 'あなたは私のさすらいを記しておられます。どうか私の涙をあなたの皮袋に蓄えてください。それともあなたの書に記されていないのですか。'),
('JPN', '诗篇', 19, 56, 9, 'そのとき私の敵は退きます。私が呼び求める日に。私は知っています。神が味方であることを。'),
('JPN', '诗篇', 19, 56, 10, '神にあって私はみことばをほめたたえます。主にあって私はみことばをほめたたえます。'),
('JPN', '诗篇', 19, 56, 11, '神に信頼し私は何も恐れません。人が私に何をなし得るでしょう。'),
('JPN', '诗篇', 19, 56, 12, '神よあなたへの誓いは私の上にあります。感謝のいけにえであなたにそれを果たします。'),
('JPN', '诗篇', 19, 56, 13, 'まことにあなたは救い出してくださいました。私のいのちを死から。私の足をつまずきから。私がいのちの光のうちに神の御前に歩むために。'),
('JPN', '诗篇', 19, 57, 1, '私をあわれんでください。神よ。私をあわれんでください。私のたましいはあなたに身を避けていますから。私は滅びが過ぎ去るまで御翼の陰に身を避けます。'),
('JPN', '诗篇', 19, 57, 2, '私はいと高き方神を呼び求めます。私のためにすべてを成し遂げてくださる神を。'),
('JPN', '诗篇', 19, 57, 3, '神は天から助けを送って私を救い私を踏みつける者どもを辱められます。セラ神は恵みとまことを送ってくださいます。'),
('JPN', '诗篇', 19, 57, 4, '私のたましいは獅子たちの間で人の子らを貪り食う者の間で横たわっています。彼らの歯は槍と矢彼らの舌は鋭い剣です。'),
('JPN', '诗篇', 19, 57, 5, '神よあなたが天であなたの栄光が全世界であがめられますように。'),
('JPN', '诗篇', 19, 57, 6, '彼らは私の足を狙って網を仕掛けました。私のたましいはうなだれています。彼らは私の前に穴を掘り自分でその中に落ちました。セラ'),
('JPN', '诗篇', 19, 57, 7, '神よ私の心は揺るぎません。私の心は揺るぎません。私は歌いほめ歌います。'),
('JPN', '诗篇', 19, 57, 8, '私のたましいよ目を覚ませ。琴よ竪琴よ目を覚ませ。私は暁を呼び覚まそう。'),
('JPN', '诗篇', 19, 57, 9, '主よ私は国々の民の間であなたに感謝しもろもろの国民の間であなたをほめ歌います。'),
('JPN', '诗篇', 19, 57, 10, 'あなたの恵みは大きく天にまで及びあなたのまことは雲にまで及ぶからです。'),
('JPN', '诗篇', 19, 57, 11, '神よあなたが天であなたの栄光が全地であがめられますように。'),
('JPN', '诗篇', 19, 58, 1, '力ある者たちよおまえたちは本当に義を語り人の子らを公正にさばくことができるのか。'),
('JPN', '诗篇', 19, 58, 2, '実におまえたちは心で不正を働き地で手の暴虐をはびこらせている。'),
('JPN', '诗篇', 19, 58, 3, '悪しき者どもは母の胎を出たときから踏み迷い偽りを言う者どもは生まれたときからさまよっている。'),
('JPN', '诗篇', 19, 58, 4, '彼らには蛇の毒のような毒がある。耳の聞こえないコブラのように耳を閉ざし'),
('JPN', '诗篇', 19, 58, 5, '蛇使いの声も聞こうとしない。巧みに呪文を唱える者の声も。'),
('JPN', '诗篇', 19, 58, 6, '神よ彼らの歯をその口の中で折ってください。主よ若獅子たちの牙を打ち砕いてください。'),
('JPN', '诗篇', 19, 58, 7, '彼らが流れ行く水のように消え去り神が矢を放たれるとき干上がりますように。'),
('JPN', '诗篇', 19, 58, 8, '彼らが溶けて消え行くなめくじのように日の目を見ない死産の子のようになりますように。'),
('JPN', '诗篇', 19, 58, 9, 'おまえたちの釜が茨の火を感じる前に神はそれが緑のままでも燃えていても等しく吹き払われる。'),
('JPN', '诗篇', 19, 58, 10, '正しい人は復讐を見て喜びその足を悪しき者の血で洗う。'),
('JPN', '诗篇', 19, 58, 11, 'こうして人は言う。「まことに正しい人には報いがある。まことにさばく神が地におられる。」'),
('JPN', '诗篇', 19, 59, 1, '私の神よ私を敵から救い出してください。向かい立つ者たちよりも高く私を引き上げてください。'),
('JPN', '诗篇', 19, 59, 2, '不法を行う者どもから私を救い出してください。人の血を流す者どもから私を救ってください。'),
('JPN', '诗篇', 19, 59, 3, '今しも彼らは私のたましいを待ち伏せし力ある者どもは私に襲いかかろうとしています。主よそれは私の背きのゆえでもなく私の罪のゆえでもありません。'),
('JPN', '诗篇', 19, 59, 4, '私には咎がないのに彼らは走り身構えています。どうか目を覚ましここに来て見てください。'),
('JPN', '诗篇', 19, 59, 5, 'あなたは万軍の神主イスラエルの神。どうか目を覚ましすべての国を罰してください。邪悪な裏切り者をだれもあわれまないでください。セラ'),
('JPN', '诗篇', 19, 59, 6, '彼らは夕べに帰って来ては犬のようにほえ町をうろつき回ります。'),
('JPN', '诗篇', 19, 59, 7, 'ご覧ください。彼らの唇には多くの剣がありその口で放言しているのです。「だれが聞くものか」と。'),
('JPN', '诗篇', 19, 59, 8, 'しかし主よあなたは彼らを笑いすべての国々を嘲られます。'),
('JPN', '诗篇', 19, 59, 9, '私の力よ私はあなたを見続けます。神が私の砦だからです。'),
('JPN', '诗篇', 19, 59, 10, '私の恵みの神は私を迎えに来てくださる。神は私に敵を平然と眺めるようにしてくださる。'),
('JPN', '诗篇', 19, 59, 11, '彼らを殺してしまわないでください。私の民が忘れることのないように。御力によって彼らをさまよわせてください。彼らを打ち倒してください。主よ私たちの盾よ。'),
('JPN', '诗篇', 19, 59, 12, '彼らの口の罪は彼らの唇のことば。彼らは高慢にとらえられるがよい。彼らが語る呪いとへつらいのゆえに。'),
('JPN', '诗篇', 19, 59, 13, '憤りをもって滅ぼし尽くしてください。滅ぼし尽くしてください。彼らがいなくなるまで。神が地の果てまでもヤコブを治められることを彼らが知るようにしてください。セラ'),
('JPN', '诗篇', 19, 59, 14, '彼らは夕べに帰って来ては犬のようにほえ町をうろつき回ります。'),
('JPN', '诗篇', 19, 59, 15, '食を求めてさまよい歩き満ち足りなければ夜を明かします。'),
('JPN', '诗篇', 19, 59, 16, 'しかしこの私はあなたの力を歌います。朝明けにはあなたの恵みを喜び歌います。私の苦しみの日にあなたが私の砦また私の逃れ場であられたからです。'),
('JPN', '诗篇', 19, 59, 17, '私の力よ私はあなたにほめ歌を歌います。神は私の砦私の恵みの神であるからです。'),
('JPN', '诗篇', 19, 60, 1, '神よあなたは私たちを拒み私たちを破られました。あなたは怒られました。どうか私たちを回復させてください。'),
('JPN', '诗篇', 19, 60, 2, 'あなたは地を揺るがし引き裂かれました。その裂け目を癒やしてください。地が揺れ動いているからです。'),
('JPN', '诗篇', 19, 60, 3, 'あなたは御民を苦しい目にあわせよろめかす酒を私たちに飲ませられました。'),
('JPN', '诗篇', 19, 60, 4, 'あなたはあなたを恐れる者に旗を授けられました。弓から逃れた者をそこに集めるために。セラ'),
('JPN', '诗篇', 19, 60, 5, 'あなたの愛する者たちが助け出されるようあなたの右の手で救い私に答えてください。'),
('JPN', '诗篇', 19, 60, 6, '神は聖所から告げられました。「わたしは喜んでシェケムを分けスコテの平原を測ろう。'),
('JPN', '诗篇', 19, 60, 7, 'ギルアデはわたしのもの。マナセもわたしのもの。エフライムはわたしの頭のかぶと。ユダはわたしの王笏。'),
('JPN', '诗篇', 19, 60, 8, 'モアブはわたしの足を洗うたらい。エドムの上にわたしの履き物を投げつけよう。ペリシテよわたしのゆえに大声で叫べ。」'),
('JPN', '诗篇', 19, 60, 9, 'だれが私を防備の町に連れて行くのでしょうか。だれが私をエドムまで導くのでしょうか。'),
('JPN', '诗篇', 19, 60, 10, '神よあなたご自身が私たちを拒まれるのですか。神よあなたはもはや私たちとともに出陣なさらないのですか。'),
('JPN', '诗篇', 19, 60, 11, 'どうか敵から私たちを助けてください。人による救いはむなしいからです。'),
('JPN', '诗篇', 19, 60, 12, '神にあって私たちは力ある働きをします。神が私たちの敵を踏みつけてくださいます。'),
('JPN', '诗篇', 19, 61, 1, '神よ私の叫びを聞き私の祈りに耳を傾けてください。'),
('JPN', '诗篇', 19, 61, 2, '私の心が衰え果てるとき私は地の果てからあなたを呼び求めます。どうか及びがたいほど高い岩の上に私を導いてください。'),
('JPN', '诗篇', 19, 61, 3, 'あなたは私の避け所敵に対して強いやぐら。'),
('JPN', '诗篇', 19, 61, 4, '私はあなたの幕屋にいつまでも住み御翼の陰に身を避けます。セラ'),
('JPN', '诗篇', 19, 61, 5, '神よまことにあなたは私の誓いを聞き入れ御名を恐れる者の受け継ぐ地を私に下さいました。'),
('JPN', '诗篇', 19, 61, 6, 'どうか王のいのちを延ばしその齢を代々に至らせてください。'),
('JPN', '诗篇', 19, 61, 7, '王が神の御前でいつまでも王座に着いているようにしてください。恵みとまことを与えて王をお守りください。'),
('JPN', '诗篇', 19, 61, 8, 'こうして私はあなたの御名をとこしえまでもほめ歌い日ごとに私の誓いを果たします。'),
('JPN', '诗篇', 19, 62, 1, '私のたましいは黙ってただ神を待ち望む。私の救いは神から来る。'),
('JPN', '诗篇', 19, 62, 2, '神こそわが岩わが救いわがやぐら。私は決して揺るがされない。'),
('JPN', '诗篇', 19, 62, 3, 'おまえたちはいつまで一人の人を襲うのか。おまえたちはこぞって打ち殺そうとしている。城壁を傾け石垣を倒すように。'),
('JPN', '诗篇', 19, 62, 4, '実に彼らは人を高い地位から突き落とそうと企んでいる。彼らは偽りを好み口では祝福し心では呪う。セラ'),
('JPN', '诗篇', 19, 62, 5, '私のたましいよ黙ってただ神を待ち望め。私の望みは神から来るからだ。'),
('JPN', '诗篇', 19, 62, 6, '神こそわが岩わが救いわがやぐら。私は揺るがされることがない。'),
('JPN', '诗篇', 19, 62, 7, '私の救いと栄光はただ神にある。私の力の岩と避け所は神のうちにある。'),
('JPN', '诗篇', 19, 62, 8, '民よどんなときにも神に信頼せよ。あなたがたの心を神の御前に注ぎ出せ。神はわれらの避け所である。セラ'),
('JPN', '诗篇', 19, 62, 9, '低い者はただ空しく高い者も偽りだ。秤にかけると彼らは上に上がる。彼らを合わせても息より軽い。'),
('JPN', '诗篇', 19, 62, 10, '圧制に頼るな。略奪に空しい望みをかけるな。富が増えてもそれに心を留めるな。'),
('JPN', '诗篇', 19, 62, 11, '神は一度告げられた。二度私はそれを聞いた。力は神のものであることを。'),
('JPN', '诗篇', 19, 62, 12, '主よ恵みもあなたのものです。あなたはその行いに応じて人に報いられます。'),
('JPN', '诗篇', 19, 63, 1, '神よあなたは私の神。私はあなたを切に求めます。水のない衰え果てた乾いた地で私のたましいはあなたに渇き私の身もあなたをあえぎ求めます。'),
('JPN', '诗篇', 19, 63, 2, '私はあなたの力と栄光を見るためにこうして聖所であなたを仰ぎ見ています。'),
('JPN', '诗篇', 19, 63, 3, 'あなたの恵みはいのちにもまさるゆえ私の唇はあなたを賛美します。'),
('JPN', '诗篇', 19, 63, 4, 'それゆえ私は生きるかぎりあなたをほめたたえあなたの御名により両手を上げて祈ります。'),
('JPN', '诗篇', 19, 63, 5, '脂肪と髄をふるまわれたかのように私のたましいは満ち足りています。喜びにあふれた唇で私の口はあなたを賛美します。'),
('JPN', '诗篇', 19, 63, 6, '床の上であなたを思い起こすとき夜もすがらあなたのことを思い巡らすときに。'),
('JPN', '诗篇', 19, 63, 7, 'まことにあなたは私の助けでした。御翼の陰で私は喜び歌います。'),
('JPN', '诗篇', 19, 63, 8, '私のたましいはあなたにすがりあなたの右の手は私を支えてくださいます。'),
('JPN', '诗篇', 19, 63, 9, '私のいのちを求める者どもは滅び地の深い所に行くでしょう。'),
('JPN', '诗篇', 19, 63, 10, '彼らは剣の力に渡され狐の餌食となるのです。'),
('JPN', '诗篇', 19, 63, 11, 'しかし王は神にあって喜び神にかけて誓う者はみな誇ります。偽りを言う者の口が封じられるからです。'),
('JPN', '诗篇', 19, 64, 1, '神よ私が嘆くとき私の声を聞いてください。敵の脅かしから私のいのちを守ってください。'),
('JPN', '诗篇', 19, 64, 2, 'どうか私をかくまってください。悪を行う者どものはかりごとから不法を行う者どもの騒ぎから。'),
('JPN', '诗篇', 19, 64, 3, '彼らはその舌を剣のように研ぎ澄まし苦いことばの矢を放っています。'),
('JPN', '诗篇', 19, 64, 4, '全き人に向けて彼らは隠れた所から射掛け不意に矢を射て何も恐れません。'),
('JPN', '诗篇', 19, 64, 5, '彼らは悪事に凝っています。示し合わせてひそかに罠をかけ「だれが見破ることができよう」と言っています。'),
('JPN', '诗篇', 19, 64, 6, '彼らは不正を企み「企んだ策略がうまくいった」と言っています。人の内なる思いと心とは底が知れません。'),
('JPN', '诗篇', 19, 64, 7, 'しかし神が彼らに矢を射掛けられるので彼らは不意に傷つきます。'),
('JPN', '诗篇', 19, 64, 8, '彼らは自らの舌につまずきました。彼らを見る者はみな頭を振って嘲ります。'),
('JPN', '诗篇', 19, 64, 9, 'こうしてすべての人は恐れ神のみわざを告げ知らせそのなさったことを悟ります。'),
('JPN', '诗篇', 19, 64, 10, '正しい人は主にあって喜び主に身を避けます。心の直ぐな人はみな誇ることができます。'),
('JPN', '诗篇', 19, 65, 1, '神よ御前には静けさがありシオンには賛美があります。あなたに誓いが果たされますように。'),
('JPN', '诗篇', 19, 65, 2, '祈りを聞かれる方よみもとにすべての肉なる者が参ります。'),
('JPN', '诗篇', 19, 65, 3, '数々の咎が私を圧倒しています。しかし私たちの背きをあなたは赦してくださいます。'),
('JPN', '诗篇', 19, 65, 4, '幸いなことよあなたが選び近寄せられた人あなたの大庭に住む人は。私たちはあなたの家の良いものあなたの宮の聖なるもので満ち足ります。'),
('JPN', '诗篇', 19, 65, 5, '私たちの救いの神よ。あなたは恐るべきみわざで義のうちに答えられます。あなたは地のすべての果て遠い大海の信頼の的です。'),
('JPN', '诗篇', 19, 65, 6, 'あなたは御力によって山々を堅く据え大能を帯びておられます。'),
('JPN', '诗篇', 19, 65, 7, 'あなたは海のとどろきを鎮められます。その大波のとどろきもろもろの国民の騒ぎを。'),
('JPN', '诗篇', 19, 65, 8, '最果てに住む者もあなたの数々のしるしを恐れます。あなたは朝と夕の始まる所が高らかに歌うようにされます。'),
('JPN', '诗篇', 19, 65, 9, 'あなたは地を訪れ水を注ぎこれを大いに豊かにされます。神の川は水で満ちています。あなたはこうして地を整え人々の穀物を備えてくださいます。'),
('JPN', '诗篇', 19, 65, 10, '地のあぜ溝を水で満たしその畝をならし夕立で地を柔らかにしその生長を祝福されます。'),
('JPN', '诗篇', 19, 65, 11, 'あなたはその年に御恵みの冠をかぶらせます。あなたの通られた跡には油が滴っています。'),
('JPN', '诗篇', 19, 65, 12, '荒野の牧場に滴りもろもろの丘も喜びをまとっています。'),
('JPN', '诗篇', 19, 65, 13, '牧草地は羊の群れをまとい広やかな平原は穀物を覆いとしています。まことに喜び叫び歌っています。'),
('JPN', '诗篇', 19, 66, 1, '全地よ神に向かって喜び叫べ。'),
('JPN', '诗篇', 19, 66, 2, '御名の栄光をほめ歌い神の誉れに栄光を帰せよ。'),
('JPN', '诗篇', 19, 66, 3, '神に申し上げよ。「あなたのみわざはなんと恐ろしいことでしょう。偉大な御力のためにあなたの敵は御前にへつらい服します。'),
('JPN', '诗篇', 19, 66, 4, '全地はあなたを伏し拝みます。あなたをほめ歌いあなたの御名をほめ歌います。」セラ'),
('JPN', '诗篇', 19, 66, 5, 'さあ神のみわざを見よ。神が人の子らになさることは恐ろしい。'),
('JPN', '诗篇', 19, 66, 6, '神は海を乾いた所とされた。人々は川の中を歩いて渡った。さあ私たちは神にあって喜ぼう。'),
('JPN', '诗篇', 19, 66, 7, '神はその御力をもってとこしえに統べ治めその目は国々を見張られる。どうか頑迷な者を高ぶらせないでください。セラ'),
('JPN', '诗篇', 19, 66, 8, '国々の民よ私たちの神をほめたたえよ。神の誉れをたたえる声を響き渡らせよ。'),
('JPN', '诗篇', 19, 66, 9, '神は私たちのたましいをいのちのうちに保ち私たちの足を揺るがされない。'),
('JPN', '诗篇', 19, 66, 10, '神よまことにあなたは私たちを試し銀を精錬するように私たちを錬られました。'),
('JPN', '诗篇', 19, 66, 11, 'あなたは私たちを網に引き入れ私たちの腰に重荷を負わされました。'),
('JPN', '诗篇', 19, 66, 12, 'あなたは人々に私たちの頭をまたがせ私たちは火の中水の中を通りました。しかしあなたは私たちを豊かな所へ導き出してくださいました。'),
('JPN', '诗篇', 19, 66, 13, '私は全焼のささげ物を携えてあなたの家に行き私の誓いをあなたに果たします。'),
('JPN', '诗篇', 19, 66, 14, 'それは私の苦しみのときに唇を大きく開きこの口で申し上げた誓いです。'),
('JPN', '诗篇', 19, 66, 15, '私は肥えたものを全焼のささげ物として雄羊のいけにえの煙とともにあなたに献げます。雄牛を雄やぎとともに献げます。セラ'),
('JPN', '诗篇', 19, 66, 16, 'さあ聞けすべて神を恐れる者たちよ。神が私のたましいになさったことを語ろう。'),
('JPN', '诗篇', 19, 66, 17, '私はこの口で神を呼び求めこの舌で神をあがめた。'),
('JPN', '诗篇', 19, 66, 18, 'もしも不義を私が心のうちに見出すなら主は聞き入れてくださらない。'),
('JPN', '诗篇', 19, 66, 19, 'しかし確かに神は聞き入れ私の祈りの声に耳を傾けてくださった。'),
('JPN', '诗篇', 19, 66, 20, 'ほむべきかな神。神は私の祈りを退けず御恵みを私から取り去られなかった。'),
('JPN', '诗篇', 19, 67, 1, 'どうか神が私たちをあわれみ祝福し御顔を私たちの上に照り輝かせてくださいますように。セラ'),
('JPN', '诗篇', 19, 67, 2, 'あなたの道が地の上で御救いがすべての国々の間で知られるために。'),
('JPN', '诗篇', 19, 67, 3, '神よ諸国の民があなたをほめたたえ諸国の民がみなあなたをほめたたえますように。'),
('JPN', '诗篇', 19, 67, 4, '国々の民が喜びまた喜び歌いますように。それはあなたが公平に諸国の民をさばき地の国民を導かれるからです。セラ'),
('JPN', '诗篇', 19, 67, 5, '神よ諸国の民があなたをほめたたえ諸国の民がみなあなたをほめたたえますように。'),
('JPN', '诗篇', 19, 67, 6, '大地はその実りを産み出しました。神が私たちの神が私たちを祝福してくださいますように。'),
('JPN', '诗篇', 19, 67, 7, '神が私たちを祝福してくださり地の果てのすべての者が神を恐れますように。'),
('JPN', '诗篇', 19, 68, 1, '神は立ち上がりその敵は散り失せる。神を憎む者たちは御前から逃げ去る。'),
('JPN', '诗篇', 19, 68, 2, '煙が追い払われるように追い払ってください。ろうが火の前で溶け去るように悪しき者が神の御前から滅び失せますように。'),
('JPN', '诗篇', 19, 68, 3, 'しかし正しい者たちは小躍りして喜ぶ。神の御前で喜び楽しむ。'),
('JPN', '诗篇', 19, 68, 4, '神に向かって歌い御名をほめ歌え。雲に乗って来られる方のために道を備えよ。その御名は主。その御前で喜び躍れ。'),
('JPN', '诗篇', 19, 68, 5, 'みなしごの父やもめのためのさばき人は聖なる住まいにおられる神。'),
('JPN', '诗篇', 19, 68, 6, '神は孤独な者を家に住まわせ捕らわれ人を歓喜の歌声とともに導き出される。しかし頑迷な者は焦げつく地に住む。'),
('JPN', '诗篇', 19, 68, 7, '神よあなたが御民に先立って出て行き荒れ野を進み行かれたときセラ'),
('JPN', '诗篇', 19, 68, 8, '地は揺れ動き天も雨を降らせました。シナイにおられる神の御前で。イスラエルの神である神の御前で。'),
('JPN', '诗篇', 19, 68, 9, '神よあなたは豊かな雨を注ぎ疲れたあなたのゆずりの地を堅く立てられました。'),
('JPN', '诗篇', 19, 68, 10, 'あなたの群れはその地に住みました。神よあなたはいつくしみをもって苦しむ者のために備えをされました。'),
('JPN', '诗篇', 19, 68, 11, '主はみことばを与えてくださる。良き知らせを告げる女たちは大きな群れ。'),
('JPN', '诗篇', 19, 68, 12, '軍勢の王たちは逃げまた逃げる。家に残った女たちは獲物を分け合う。'),
('JPN', '诗篇', 19, 68, 13, '羊の囲いの中に横たわるとしてもあなたがたは翼が銀でおおわれてきらめく黄金で羽がおおわれた鳩のようだ。'),
('JPN', '诗篇', 19, 68, 14, '全能者が王たちをその地で散らされたときツァルモンには雪が降っていた。'),
('JPN', '诗篇', 19, 68, 15, '神々しい山バシャンの山よ。峰を連ねた山バシャンの山よ。'),
('JPN', '诗篇', 19, 68, 16, '峰を連ねた山々よ。なぜおまえたちはねたみ見るのか。神がその住まいとして望まれたあの山を。まことに主はとこしえにそこに住まわれる。'),
('JPN', '诗篇', 19, 68, 17, '神の戦車は幾千万と数知れず。主はその中におられる。シナイの神は聖所の中に。'),
('JPN', '诗篇', 19, 68, 18, 'あなたは捕虜を引き連れていと高き所に上り人々に頑迷な者どもにさえ贈り物を与えられた。神であられる主がそこに住まわれるために。'),
('JPN', '诗篇', 19, 68, 19, 'ほむべきかな主。日々私たちの重荷を担われる方。この神こそ私たちの救い。セラ'),
('JPN', '诗篇', 19, 68, 20, '神は私たちの救いの神。死を免れるのは私の主神による。'),
('JPN', '诗篇', 19, 68, 21, '神は必ず敵の頭を打ち砕かれる。自分の罪過のうちを歩む者の毛深い脳天を。'),
('JPN', '诗篇', 19, 68, 22, '主は言われた。「わたしはバシャンから彼らを連れ帰る。海の深みからも連れ帰る。'),
('JPN', '诗篇', 19, 68, 23, 'あなたが彼らを打ち砕き足を血に染めあなたの犬たちの舌が敵の血をなめるために。」'),
('JPN', '诗篇', 19, 68, 24, '神よ人々はあなたの行列を見ました。聖所で私の王私の神の行列を。'),
('JPN', '诗篇', 19, 68, 25, '歌い手が前を進み楽人が後に続く。タンバリンを鳴らすおとめたちのただ中を。'),
('JPN', '诗篇', 19, 68, 26, '「相集って神をほめたたえよ。イスラエルの泉から主をほめたたえよ。」'),
('JPN', '诗篇', 19, 68, 27, 'そこには彼らを導く末子のベニヤミンがいる。その群れの中にはユダの君主たちゼブルンの君主たちナフタリの君主たちもいる。'),
('JPN', '诗篇', 19, 68, 28, 'あなたの神はあなたの力を現れさせました。神よあなたが私たちに示された力を。'),
('JPN', '诗篇', 19, 68, 29, 'エルサレムにあるあなたの宮のゆえに王たちはあなたに献上品を携えて来ます。'),
('JPN', '诗篇', 19, 68, 30, '葦の中の獣を叱ってください。国々の民の子牛を連れた雄牛の群れを。彼らは銀の品々を踏みつけています。戦いを喜ぶ国々の民を散らしてください。'),
('JPN', '诗篇', 19, 68, 31, '貢ぎ物はエジプトから到来しクシュは神に向かって急いで手を伸ばします。'),
('JPN', '诗篇', 19, 68, 32, '地の王国よ神に向かって歌え。主にほめ歌を歌え。セラ'),
('JPN', '诗篇', 19, 68, 33, 'いにしえから天の天を御される方に。聞け。神は御声を発せられる。力強い御声を。'),
('JPN', '诗篇', 19, 68, 34, '力を神に帰せよ。威光はイスラエルの上に御力は雲の中にある。'),
('JPN', '诗篇', 19, 68, 35, '神よあなたは恐るべき方。あなたはご自分の聖なる所におられます。イスラエルの神こそ力と勢いを御民にお与えになる方です。ほむべきかな神。'),
('JPN', '诗篇', 19, 69, 1, '神よ私をお救いください。水が喉にまで入って来ました。'),
('JPN', '诗篇', 19, 69, 2, '私は深い泥沼に沈み足がかりもありません。私は大水の底に陥り奔流が私を押し流しています。'),
('JPN', '诗篇', 19, 69, 3, '私は叫んで疲れ果て喉は渇き目も衰え果てました。私の神を待ちわびて。'),
('JPN', '诗篇', 19, 69, 4, 'ゆえなく私を憎む者は私の髪の毛よりも多く私を滅ぼそうとする者私の敵偽り者は強いのです。私は奪わなかった物さえ返さなければならないのですか。'),
('JPN', '诗篇', 19, 69, 5, '神よあなたは私の愚かさをご存じです。私の数々の罪過はあなたに隠されていません。'),
('JPN', '诗篇', 19, 69, 6, '万軍の神主よあなたを待ち望む者たちが私のために恥を見ないようにしてください。イスラエルの神よあなたを慕い求める者たちが私のために卑しめられないようにしてください。'),
('JPN', '诗篇', 19, 69, 7, 'あなたのことで私はそしりを受け恥辱が私の顔をおおっているのです。'),
('JPN', '诗篇', 19, 69, 8, '私は自分の兄弟からのけ者にされ母の子らにはよそ者となりました。'),
('JPN', '诗篇', 19, 69, 9, 'それはあなたの家を思う熱心が私を食い尽くしあなたを嘲る者たちの嘲りが私に降りかかったからです。'),
('JPN', '诗篇', 19, 69, 10, '私が断食しわが身を泣き悲しむとそれが私への嘲りのもととなりました。'),
('JPN', '诗篇', 19, 69, 11, '私が粗布を自分の衣とすると私は彼らの物笑いの種となりました。'),
('JPN', '诗篇', 19, 69, 12, '門に座る者たちは私のうわさ話をし私は酔いどれの歌になりました。'),
('JPN', '诗篇', 19, 69, 13, 'しかし私は主よあなたに祈ります。神よみこころの時にあなたの豊かな恵みにより御救いのまことをもって私に答えてください。'),
('JPN', '诗篇', 19, 69, 14, '私を泥沼から救い出し沈まないようにしてください。私を憎む者どもから大水の底から救い出してください。'),
('JPN', '诗篇', 19, 69, 15, '奔流が私を押し流さず深い淵が私を吞み込まず穴が私の上で口を閉じないようにしてください。'),
('JPN', '诗篇', 19, 69, 16, '主よ私に答えてください。いつくしみ深いあなたの恵みのゆえに。あなたのあわれみの豊かさにしたがって私に御顔を向けてください。'),
('JPN', '诗篇', 19, 69, 17, 'あなたのしもべに御顔を隠さないでください。私は苦しんでいます。早く私に答えてください。'),
('JPN', '诗篇', 19, 69, 18, '私のたましいに近づきこれを贖ってください。そうして私の敵から私を贖い出してください。'),
('JPN', '诗篇', 19, 69, 19, 'あなたはよくご存じです。私への嘲りと恥と恥辱とを。私に敵する者はみなあなたの御前にいます。'),
('JPN', '诗篇', 19, 69, 20, '嘲りが私の心を打ち砕き私はひどく病んでいます。私が同情を求めてもそれはなく慰める者たちを求めても見つけられません。'),
('JPN', '诗篇', 19, 69, 21, '彼らは私の食べ物の代わりに毒を与え私が渇いたときには酢を飲ませました。'),
('JPN', '诗篇', 19, 69, 22, '彼らの前の食卓は罠となり栄えるときに落とし穴となりますように。'),
('JPN', '诗篇', 19, 69, 23, '彼らの目が暗くなり見えなくなりますように。その腰がいつもよろけますように。'),
('JPN', '诗篇', 19, 69, 24, 'あなたの憤りを彼らの上に注いでください。燃える怒りを彼らに追いつかせてください。'),
('JPN', '诗篇', 19, 69, 25, '彼らの宿営が荒れ果てその天幕から住む者が絶えますように。'),
('JPN', '诗篇', 19, 69, 26, '彼らはあなたが打たれた者を迫害しあなたに刺し貫かれた者の痛みを言いふらします。'),
('JPN', '诗篇', 19, 69, 27, 'どうか彼らの咎に咎を加え彼らをあなたの義のうちに入れないでください。'),
('JPN', '诗篇', 19, 69, 28, '彼らがいのちの書から消し去られますように。正しい者と並べて彼らが書き記されることがありませんように。'),
('JPN', '诗篇', 19, 69, 29, '私は苦しんで痛みの中にいます。神よ御救いが私を高く上げますように。'),
('JPN', '诗篇', 19, 69, 30, '歌をもって私は神の御名をほめたたえ感謝をもって私は神をあがめます。'),
('JPN', '诗篇', 19, 69, 31, 'それは雄牛にまさって主に喜ばれます。角が生えひづめが割れた若い牛にまさって。'),
('JPN', '诗篇', 19, 69, 32, '心の貧しい者たちよ見て喜べ。神を求める者たちよあなたがたの心を生かせ。'),
('JPN', '诗篇', 19, 69, 33, '主は貧しい者に耳を傾け捕らわれたご自分の民を蔑まれない。'),
('JPN', '诗篇', 19, 69, 34, '天地よ主をほめたたえよ。海とそこにうごめくすべてのものも。'),
('JPN', '诗篇', 19, 69, 35, 'まことに神はシオンを救いユダの町々を建て直される。彼らはそこに住みそこを自分たちの所有とする。'),
('JPN', '诗篇', 19, 69, 36, '主のしもべたちの子孫はその地を受け継ぎ御名を愛する者たちはそこに住む。'),
('JPN', '诗篇', 19, 70, 1, '神よ私を救い出してください。主よ急いで私を助けに来てください。'),
('JPN', '诗篇', 19, 70, 2, '私のいのちを求める者たちが恥を見辱められますように。私のわざわいを喜ぶ者たちが退き卑しめられますように。'),
('JPN', '诗篇', 19, 70, 3, '「あはは」とあざ笑う者たちが恥をかいて立ち去りますように。'),
('JPN', '诗篇', 19, 70, 4, 'あなたを慕い求める人たちがみなあなたにあって楽しみ喜びますように。あなたの救いを愛する人たちが「神は大いなる方」といつも言いますように。'),
('JPN', '诗篇', 19, 70, 5, '私は苦しむ者貧しい者です。神よ私のところに急いでください。あなたは私の助け私を救い出す方。主よ遅れないでください。'),
('JPN', '诗篇', 19, 71, 1, '主よ私はあなたに身を避けています。私が決して恥を見ないようにしてください。'),
('JPN', '诗篇', 19, 71, 2, 'あなたの義によって私を救い助け出してください。あなたの耳を私に傾け私をお救いください。'),
('JPN', '诗篇', 19, 71, 3, '私の避け所の岩となってください。いつでもそこに入れるように。あなたは私の救いを定められました。あなたは私の巌私の砦なのです。'),
('JPN', '诗篇', 19, 71, 4, 'わが神よ私を悪者の手から助け出してください。不正を行う者や残虐な者の手から。'),
('JPN', '诗篇', 19, 71, 5, '神である主よあなたは私の望み若い日からの拠り所。'),
('JPN', '诗篇', 19, 71, 6, '私は生まれたときからあなたに抱かれています。あなたは私を母の胎から取り上げた方。私はいつもあなたを賛美しています。'),
('JPN', '诗篇', 19, 71, 7, '私は多くの人にとって奇跡と思われました。あなたが私の力強い避け所だからです。'),
('JPN', '诗篇', 19, 71, 8, '私の口にはあなたへの賛美があなたの栄えが絶えず満ちています。'),
('JPN', '诗篇', 19, 71, 9, '年老いたときも私を見放さないでください。私の力が衰え果てても見捨てないでください。'),
('JPN', '诗篇', 19, 71, 10, '私の敵は私のことを相談し私のいのちを狙う者がともに企みます。'),
('JPN', '诗篇', 19, 71, 11, '彼らは言っています。「神は彼を見捨てたのだ。追いかけて彼を捕らえよ。救い出す者はいないから。」'),
('JPN', '诗篇', 19, 71, 12, '神よ私から遠く離れないでください。わが神よ急いで私を助けてください。'),
('JPN', '诗篇', 19, 71, 13, '私をなじる者どもが恥を見て消え失せますように。私を痛めつけようとする者どもが恥辱と恥でおおわれますように。'),
('JPN', '诗篇', 19, 71, 14, 'しかし私は絶えずあなたを待ち望みいよいよ切にあなたを賛美します。'),
('JPN', '诗篇', 19, 71, 15, '私の口は絶えず語り告げます。あなたの義と救いとを。そのすべてを私は知っておりませんが。'),
('JPN', '诗篇', 19, 71, 16, '神である主よ私はあなたの力とともに行きます。あなたのただあなたの義だけを心に留めて。'),
('JPN', '诗篇', 19, 71, 17, '神よあなたは私の若いころから私を教えてくださいました。私は今なおあなたの奇しいみわざを告げ知らせています。'),
('JPN', '诗篇', 19, 71, 18, '年老いて白髪頭になったとしても神よ私を捨てないでください。私はなおも告げ知らせます。あなたの力を世に。あなたの大能のみわざを後に来るすべての者に。'),
('JPN', '诗篇', 19, 71, 19, '神よあなたの義は天にまで届きます。あなたは大いなることをなさいました。神よだれがあなたのようでしょう。'),
('JPN', '诗篇', 19, 71, 20, 'あなたは私を多くの苦難とわざわいとにあわせられましたが私を再び生き返らせ地の深みから再び引き上げてくださいます。'),
('JPN', '诗篇', 19, 71, 21, 'あなたが私の偉大さを増し振り向いて私を慰めてくださいますように。'),
('JPN', '诗篇', 19, 71, 22, '私もまた琴であなたをほめたたえます。わが神よあなたの真実を。私は竪琴に合わせてあなたにほめ歌を歌います。イスラエルの聖なる方よ。'),
('JPN', '诗篇', 19, 71, 23, '私があなたにほめ歌を歌うとき私の唇は高らかに歌います。あなたが贖い出された私のたましいも。'),
('JPN', '诗篇', 19, 71, 24, '私の舌も絶えずあなたの義を告げます。私のわざわいを求める者どもが恥を見て屈辱を受けるからです。'),
('JPN', '诗篇', 19, 72, 1, '神よあなたのさばきを王にあなたの義を王の子に与えてください。'),
('JPN', '诗篇', 19, 72, 2, '彼が義をもってあなたの民をさばきますように。公正をもってあなたの苦しむ民を。'),
('JPN', '诗篇', 19, 72, 3, '山も丘も義によって民に平和をもたらしますように。'),
('JPN', '诗篇', 19, 72, 4, '王が民の苦しむ者たちを弁護し貧しい者の子らを救い虐げる者どもを打ち砕きますように。'),
('JPN', '诗篇', 19, 72, 5, '彼らが日と月の続くかぎり代々にわたってあなたを恐れますように。'),
('JPN', '诗篇', 19, 72, 6, '王は牧草地に降る雨のように地を潤す夕立のように下って来ます。'),
('JPN', '诗篇', 19, 72, 7, '彼の代に正しい者が栄え月がなくなるときまでも豊かな平和がありますように。'),
('JPN', '诗篇', 19, 72, 8, '海から海に至るまで川から地の果てに至るまで王が統べ治めますように。'),
('JPN', '诗篇', 19, 72, 9, '砂漠の民は王の前に膝をつき王の敵はちりをなめますように。'),
('JPN', '诗篇', 19, 72, 10, 'タルシシュと島々の王たちは貢ぎを納めシェバとセバの王たちは贈り物を献げます。'),
('JPN', '诗篇', 19, 72, 11, 'こうしてすべての王が彼にひれ伏しすべての国々が彼に仕えるでしょう。'),
('JPN', '诗篇', 19, 72, 12, 'それは王が叫び求める貧しい者や助ける人のない苦しむ者を救い出すからです。'),
('JPN', '诗篇', 19, 72, 13, '王は弱い者や貧しい者をあわれみ貧しい者たちのいのちを救います。'),
('JPN', '诗篇', 19, 72, 14, '虐げと暴虐から王は彼らのいのちを贖います。王の目には彼らの血は尊いのです。'),
('JPN', '诗篇', 19, 72, 15, 'どうか王が生き続け彼にシェバの黄金が献げられますように。王のためにいつも彼らが祈り絶えず王をほめたたえますように。'),
('JPN', '诗篇', 19, 72, 16, '大地には穀物が豊かにあり山々の頂では実がレバノンのようにたわわに揺れ町の人々は地の草花のように咲き誇りますように。'),
('JPN', '诗篇', 19, 72, 17, '王の名がとこしえに続きその名が日の照るかぎり増え広がりますように。人々が彼によって祝福されすべての国々が彼をほめたたえますように。'),
('JPN', '诗篇', 19, 72, 18, 'ほむべきかな神である主イスラエルの神。ただひとり奇しいみわざを行われる方。'),
('JPN', '诗篇', 19, 72, 19, 'とこしえにほむべきかなその栄光の御名。その栄光が全地に満ちあふれますように。アーメン、アーメン。'),
('JPN', '诗篇', 19, 72, 20, 'エッサイの子ダビデの祈りは終わった。'),
('JPN', '诗篇', 19, 73, 1, 'まことに神はいつくしみ深い。イスラエルに心の清らかな人たちに。'),
('JPN', '诗篇', 19, 73, 2, 'けれどもこの私は足がつまずきそうで私の歩みは滑りかけた。'),
('JPN', '诗篇', 19, 73, 3, 'それは私が悪しき者が栄えるのを見て誇り高ぶる者をねたんだからだ。'),
('JPN', '诗篇', 19, 73, 4, '実に彼らの死には苦痛がなく彼らのからだは肥えている。'),
('JPN', '诗篇', 19, 73, 5, '人が苦労するときに彼らはそうではなくほかの人のように打たれることもない。'),
('JPN', '诗篇', 19, 73, 6, 'それゆえ高慢が彼らの首飾りとなり暴虐の衣が彼らをおおっている。'),
('JPN', '诗篇', 19, 73, 7, '彼らの目は脂肪でふくらみ心の思い描くものがあふれ出る。'),
('JPN', '诗篇', 19, 73, 8, '彼らは嘲り悪意をもって語り高い所から虐げを言う。'),
('JPN', '诗篇', 19, 73, 9, '彼らは口を天に据えその舌は地を行き巡る。'),
('JPN', '诗篇', 19, 73, 10, 'それゆえこの民はここに帰り豊かな水は彼らに汲み尽くされる。'),
('JPN', '诗篇', 19, 73, 11, 'そして彼らは言う。「どうして神が知るだろうか。いと高き方に知識があるだろうか。」'),
('JPN', '诗篇', 19, 73, 12, '見よこれが悪しき者。彼らはいつまでも安らかで富を増している。'),
('JPN', '诗篇', 19, 73, 13, 'ただ空しく私は自分の心を清め手を洗って自分を汚れなしとした。'),
('JPN', '诗篇', 19, 73, 14, '私は休みなく打たれ朝ごとに懲らしめを受けた。'),
('JPN', '诗篇', 19, 73, 15, 'もしも私が「このままを語ろう」と言っていたならきっと私はあなたの子らの世代を裏切っていたことだろう。'),
('JPN', '诗篇', 19, 73, 16, '私はこのことを理解しようとしたがそれは私の目には苦役であった。'),
('JPN', '诗篇', 19, 73, 17, 'ついに私は神の聖所に入って彼らの最期を悟った。'),
('JPN', '诗篇', 19, 73, 18, 'まことにあなたは彼らを滑りやすい所に置き彼らを滅びに突き落とされます。'),
('JPN', '诗篇', 19, 73, 19, 'ああ彼らは瞬く間に滅ぼされ突然の恐怖で滅ぼし尽くされます。'),
('JPN', '诗篇', 19, 73, 20, '目覚めの夢のように主よあなたが目を覚ますとき彼らの姿を蔑まれます。'),
('JPN', '诗篇', 19, 73, 21, '私の心が苦みに満ち私の内なる思いが突き刺されたとき'),
('JPN', '诗篇', 19, 73, 22, '私は愚かで考えもなくあなたの前で獣のようでした。'),
('JPN', '诗篇', 19, 73, 23, 'しかし私は絶えずあなたとともにいました。あなたは私の右の手をしっかりとつかんでくださいました。'),
('JPN', '诗篇', 19, 73, 24, 'あなたは私を諭して導き後には栄光のうちに受け入れてくださいます。'),
('JPN', '诗篇', 19, 73, 25, 'あなたのほかに天では私にだれがいるでしょう。地では私はだれをも望みません。'),
('JPN', '诗篇', 19, 73, 26, 'この身も心も尽き果てるでしょう。しかし神は私の心の岩とこしえに私が受ける割り当ての地。'),
('JPN', '诗篇', 19, 73, 27, '見よあなたから遠く離れている者は滅びます。あなたに背き不実を行う者をあなたはみな滅ぼされます。'),
('JPN', '诗篇', 19, 73, 28, 'しかし私にとって神のみそばにいることが幸せです。私は神である主を私の避け所としあなたのすべてのみわざを語り告げます。'),
('JPN', '诗篇', 19, 74, 1, '神よなぜいつまでも拒み御怒りをあなたの牧場の羊に燃やされるのですか。'),
('JPN', '诗篇', 19, 74, 2, 'どうか思い起こしてください。昔あなたが買い取られゆずりの民として贖われたあなたの会衆を。あなたの住まいであるシオンの山を。'),
('JPN', '诗篇', 19, 74, 3, 'あなたの足を永遠の廃墟に踏み入れてください。敵は聖所であらゆる害を加えています。'),
('JPN', '诗篇', 19, 74, 4, 'あなたに敵対する者どもはあなたの聖なる所でほえたけり自分たちのしるしをそこに掲げています。'),
('JPN', '诗篇', 19, 74, 5, 'あたかも木の茂みの中で斧を高く振り上げる者のようです。'),
('JPN', '诗篇', 19, 74, 6, '今や彼らは手斧と槌で聖所の彫り物をことごとく打ち砕き'),
('JPN', '诗篇', 19, 74, 7, 'あなたの聖所に火を放ちあなたの御名の住まいをその地まで汚しました。'),
('JPN', '诗篇', 19, 74, 8, '彼らは心の中で「彼らをことごとく征服しよう」と言い国中の神の聖所をみな焼き払いました。'),
('JPN', '诗篇', 19, 74, 9, 'もう私たちのしるしは見られません。もはや預言者もいません。いつまでそうなのかを知っている者も私たちの間にはいません。'),
('JPN', '诗篇', 19, 74, 10, '神よいつまではむかう者はそしるのですか。敵は永久に御名を侮るのですか。'),
('JPN', '诗篇', 19, 74, 11, 'なぜあなたは御手を右の御手を引いておられるのですか。その手を懐から出して彼らを滅ぼし尽くしてください。'),
('JPN', '诗篇', 19, 74, 12, '神は昔から私の王この地において救いのみわざを行う方。'),
('JPN', '诗篇', 19, 74, 13, 'あなたは御力をもって海を打ち破りその水の上の竜の頭を砕かれました。'),
('JPN', '诗篇', 19, 74, 14, 'あなたはレビヤタンの頭を踏みにじり砂漠に住むものたちの餌食とされました。'),
('JPN', '诗篇', 19, 74, 15, 'あなたは泉と谷を切り開き流れの絶えない川を涸らされました。'),
('JPN', '诗篇', 19, 74, 16, '昼はあなたのもの夜もあなたのもの。あなたは月と太陽を備えられました。'),
('JPN', '诗篇', 19, 74, 17, 'あなたは地のすべての境を定め夏と冬を造られました。'),
('JPN', '诗篇', 19, 74, 18, '主よどうか心に留めてください。敵がそしり愚かな民が御名を侮っていることを。'),
('JPN', '诗篇', 19, 74, 19, 'あなたの山鳩のいのちを獣に引き渡さないでください。あなたの悩む者たちのいのちを永久に忘れないでください。'),
('JPN', '诗篇', 19, 74, 20, 'どうか契約に目を留めてください。地の暗い所は暴虐の巣ですから。'),
('JPN', '诗篇', 19, 74, 21, '虐げられる者が辱めを受けて帰されることがなく苦しむ者貧しい者が御名をほめたたえますように。'),
('JPN', '诗篇', 19, 74, 22, '神よ立ち上がりご自分の言い分を立ててください。愚か者が休みなくあなたをそしっていることを心に留めてください。'),
('JPN', '诗篇', 19, 74, 23, '忘れないでください。あなたに敵対する者の声をあなたに向かい立つ者どもが絶えずあげる叫びを。'),
('JPN', '诗篇', 19, 75, 1, '私たちはあなたに感謝します。神よ私たちは感謝します。あなたの御名は近くにありあなたの奇しいみわざが語り告げられています。'),
('JPN', '诗篇', 19, 75, 2, '「わたしが定めの時を決めわたし自ら公正にさばく。'),
('JPN', '诗篇', 19, 75, 3, '地とそこに住むすべての者が揺らぐときわたしが地の柱を堅く立てる。セラ'),
('JPN', '诗篇', 19, 75, 4, 'わたしは誇る者には『誇るな』と言い悪者どもには『角を上げるな。'),
('JPN', '诗篇', 19, 75, 5, 'おまえたちの角を高く上げるな。横柄な態度で語るな』と言う。」'),
('JPN', '诗篇', 19, 75, 6, '高く上げることは東からでもなく西からでもなく荒野からでもない。'),
('JPN', '诗篇', 19, 75, 7, 'まことに神こそさばき主。ある者を低くしある者を高く上げられる。'),
('JPN', '诗篇', 19, 75, 8, '主の御手には杯があり混ぜ合わされた泡立つぶどう酒が満ちている。主がこれを注ぎ出されると実にすべて地の悪者どもはそれを飲みかすまで飲み干す。'),
('JPN', '诗篇', 19, 75, 9, 'しかし私はとこしえまでもみわざを告げます。ヤコブの神にほめ歌を歌います。'),
('JPN', '诗篇', 19, 75, 10, '私は悪者どもの角をことごとく切り捨てます。正しい者の角は高く上げられます。'),
('JPN', '诗篇', 19, 76, 1, '神はユダにご自分を示される。イスラエルにその御名の偉大さを。'),
('JPN', '诗篇', 19, 76, 2, 'その仮庵はサレムにその住まいはシオンにある。'),
('JPN', '诗篇', 19, 76, 3, '神はそこで弓の火矢を砕かれる。盾と剣も戦いも。セラ'),
('JPN', '诗篇', 19, 76, 4, 'あなたは輝かしく獲物で満ちる山々にまさって威厳があります。'),
('JPN', '诗篇', 19, 76, 5, '剛胆な者たちは略奪され深い眠りに陥りました。どの勇士たちにも手の施しようがありませんでした。'),
('JPN', '诗篇', 19, 76, 6, 'ヤコブの神よあなたが叱りつけると戦車も馬も倒れ伏しました。'),
('JPN', '诗篇', 19, 76, 7, 'あなたは実にあなたは恐ろしい方。お怒りになればだれが御前に立てるでしょう。'),
('JPN', '诗篇', 19, 76, 8, '天からあなたの宣告が聞こえると地は恐れて沈黙しました。'),
('JPN', '诗篇', 19, 76, 9, '神がさばきのために地のすべての貧しい者たちを救うために立ち上がられたそのときに。セラ'),
('JPN', '诗篇', 19, 76, 10, 'まことに人の憤りまでもがあなたをたたえあなたはあふれ出た憤りを身に帯びられます。'),
('JPN', '诗篇', 19, 76, 11, 'あなたがたの神主に誓いを立てそれを果たせ。主の周りにいる者はみな恐るべき方に贈り物を献げよ。'),
('JPN', '诗篇', 19, 76, 12, '主は君主たちの霊を刈り取られる。地の王たちにとって恐るべき方。'),
('JPN', '诗篇', 19, 77, 1, '私は神に声をあげて叫ぶ。私が神に声をあげると神は聞いてくださる。'),
('JPN', '诗篇', 19, 77, 2, '苦難の日に私は主を求め夜もすがらたゆまず手を差し伸ばした。けれども私のたましいは慰めを拒んだ。'),
('JPN', '诗篇', 19, 77, 3, '神を思い起こして私は嘆き悲しむ。思いを潜めて私の霊は衰え果てる。セラ'),
('JPN', '诗篇', 19, 77, 4, 'あなたは私のまぶたを閉じさせません。私の心は乱れてもの言うこともできません。'),
('JPN', '诗篇', 19, 77, 5, '私は昔の日々遠い昔の年月について考えました。'),
('JPN', '诗篇', 19, 77, 6, '夜には私の歌を思い起こし自分の心と語り合い私の霊は探り求めます。'),
('JPN', '诗篇', 19, 77, 7, '「主はいつまでも拒まれるのか。もう決して受け入れてくださらないのか。'),
('JPN', '诗篇', 19, 77, 8, '主の恵みはとこしえに尽き果てたのか。約束のことばは永久に絶えたのか。'),
('JPN', '诗篇', 19, 77, 9, '神はいつくしみを忘れられたのか。怒ってあわれみを閉ざされたのか。」セラ'),
('JPN', '诗篇', 19, 77, 10, '私はこう言った。「私が弱り果てたのはいと高き方の右の手が変わったからだ」と。'),
('JPN', '诗篇', 19, 77, 11, '私は主のみわざを思い起こします。昔からのあなたの奇しいみわざを思い起こします。'),
('JPN', '诗篇', 19, 77, 12, '私はあなたのなさったすべてのことを思い巡らしあなたのみわざを静かに考えます。'),
('JPN', '诗篇', 19, 77, 13, '神よあなたの道は聖です。私たちの神のように大いなる神がいるでしょうか。'),
('JPN', '诗篇', 19, 77, 14, 'あなたは奇しいみわざを行われる神。国々の民の中で御力を現される方。'),
('JPN', '诗篇', 19, 77, 15, 'あなたは御腕をもって贖われました。ご自分の民ヤコブとヨセフの子らを。セラ'),
('JPN', '诗篇', 19, 77, 16, '神よ水はあなたを見ました。水はあなたを見てわななきました。大いなる水も震え上がりました。'),
('JPN', '诗篇', 19, 77, 17, '雨雲は水を注ぎ出し雷雲は雷をとどろかしあなたの矢もひらめき飛びました。'),
('JPN', '诗篇', 19, 77, 18, 'あなたの雷の声は戦車のように鳴り稲妻は世界を照らし地は震え揺れ動きました。'),
('JPN', '诗篇', 19, 77, 19, 'あなたの道は海の中。その通り道は大水の中。あなたの足跡を見た者はいませんでした。'),
('JPN', '诗篇', 19, 77, 20, 'あなたはモーセとアロンの手によってご自分の民を羊の群れのように導かれました。'),
('JPN', '诗篇', 19, 78, 1, '私の民よ私の教えを耳に入れ私の口のことばに耳を傾けよ。'),
('JPN', '诗篇', 19, 78, 2, '私は口を開いてたとえ話を昔からの謎を語ろう。'),
('JPN', '诗篇', 19, 78, 3, 'それは私たちが聞いて知っていること。私たちの先祖が語ってくれたこと。'),
('JPN', '诗篇', 19, 78, 4, 'それを私たちは息子たちに隠さず後の時代に語り告げよう。主の誉れを主が行われた力ある奇しいみわざを。'),
('JPN', '诗篇', 19, 78, 5, '主はヤコブのうちにさとしを置きイスラエルのうちにみおしえを定め私たちの先祖に命じてその子らに教えるようにされた。'),
('JPN', '诗篇', 19, 78, 6, '後の世代の者生まれてくる子らがこれを知りさらに彼らがその子らにまた語り告げるため'),
('JPN', '诗篇', 19, 78, 7, '彼らが神に信頼し神のみわざを忘れずその命令を守るために。'),
('JPN', '诗篇', 19, 78, 8, '先祖たちのように強情で逆らう世代心定まらない世代霊が神に忠実でない世代とならないために。'),
('JPN', '诗篇', 19, 78, 9, 'エフライムの人々は弓を射る者であったが戦いの日には退却した。'),
('JPN', '诗篇', 19, 78, 10, '彼らは神の契約を守らず神のおしえに従って歩むことを拒み'),
('JPN', '诗篇', 19, 78, 11, '神の数々のみわざを忘れてしまった。神が見せてくださった多くの不思議を。'),
('JPN', '诗篇', 19, 78, 12, '神は奇しいみわざを彼らの先祖の前でエジプトの地ツォアンの野で行われた。'),
('JPN', '诗篇', 19, 78, 13, '海を分けて彼らを通らせ堰のように水を立てられた。'),
('JPN', '诗篇', 19, 78, 14, '昼は雲で彼らを導かれた。夜は夜通し炎の光で。'),
('JPN', '诗篇', 19, 78, 15, '荒野で神は岩を割り大いなる深淵の水を豊かに飲ませてくださった。'),
('JPN', '诗篇', 19, 78, 16, 'あふれる流れを岩からほとばしらせ水を豊かな川のように流れさせてくださった。'),
('JPN', '诗篇', 19, 78, 17, 'けれども彼らはなおも神に罪を犯し砂漠でいと高き方に逆らった。'),
('JPN', '诗篇', 19, 78, 18, '彼らは心のうちで神を試み欲に任せて食べ物を求めた。'),
('JPN', '诗篇', 19, 78, 19, 'そのとき彼らは神に逆らって言った。「荒野で食事を備えることが神にできるのか。'),
('JPN', '诗篇', 19, 78, 20, '確かに神が岩を打たれると水が湧き出て流れがあふれた。だが神はパンも与えることができるのか。民のために肉を用意できるのか。」'),
('JPN', '诗篇', 19, 78, 21, 'それゆえ主はこれを聞いて激しく怒られた。火はヤコブに向かって燃え怒りはイスラエルに向かって燃え上がった。'),
('JPN', '诗篇', 19, 78, 22, 'これは彼らが神を信じず御救いに信頼しなかったからである。'),
('JPN', '诗篇', 19, 78, 23, '神は上の雲に命じて天の戸を開き'),
('JPN', '诗篇', 19, 78, 24, '彼らの上に食べ物としてマナを降らせ天の穀物を彼らに与えられた。'),
('JPN', '诗篇', 19, 78, 25, 'それで人々は御使いのパンを食べた。神は満ちたりるほど食物を送られた。'),
('JPN', '诗篇', 19, 78, 26, '神は東風を天に起こし御力をもって南風を吹かせられた。'),
('JPN', '诗篇', 19, 78, 27, '彼らの上に肉をちりのように翼のある鳥を海の砂のように降らせ'),
('JPN', '诗篇', 19, 78, 28, 'それを宿営の中住まいの周りに落とされた。'),
('JPN', '诗篇', 19, 78, 29, '彼らは食べ十分に満ち足りた。こうして彼らが欲望を満たすままにされた。'),
('JPN', '诗篇', 19, 78, 30, '彼らがその欲望を手放さずまだ食べ物が口にあるうちに'),
('JPN', '诗篇', 19, 78, 31, '神の怒りが彼らに向かって燃え上がり彼らのうちの最も頑丈な者たちを殺しイスラエルの若い男たちを打ちのめした。'),
('JPN', '诗篇', 19, 78, 32, 'これらすべてにもかかわらず彼らはなおも罪を犯し神の奇しいみわざを信じなかった。'),
('JPN', '诗篇', 19, 78, 33, 'それで神は彼らの日を一息のうちに彼らの齢を突然の恐怖のうちに終わらせられた。'),
('JPN', '诗篇', 19, 78, 34, '神が彼らを殺されると彼らは神を尋ね求め立ち返り神を切に求めた。'),
('JPN', '诗篇', 19, 78, 35, '彼らは思い出した。神が自分たちの岩でありいと高き神が自分たちを贖う方であることを。'),
('JPN', '诗篇', 19, 78, 36, 'しかし彼らはその口で神に媚び舌で神に偽りを言った。'),
('JPN', '诗篇', 19, 78, 37, '彼らの心は神に堅く立たず神の契約に忠実でなかった。'),
('JPN', '诗篇', 19, 78, 38, 'しかし神はあわれみ深く彼らの咎を赦して滅ぼされなかった。怒りを何度も抑えて憤りのすべてをかき立てられることはなかった。'),
('JPN', '诗篇', 19, 78, 39, '神は心に留めておられた。彼らが肉にすぎないことを。吹けば戻らない風であることを。'),
('JPN', '诗篇', 19, 78, 40, '幾たび彼らは荒野で神に逆らい荒れ地で神を悲しませたことか。'),
('JPN', '诗篇', 19, 78, 41, '彼らは繰り返し神を試みイスラエルの聖なる方の心を痛めた。'),
('JPN', '诗篇', 19, 78, 42, '彼らは神の力も神が敵から贖い出してくださった日も思い起こさなかった。'),
('JPN', '诗篇', 19, 78, 43, '神がエジプトでしるしをツォアンの野で奇跡を行われたことを。'),
('JPN', '诗篇', 19, 78, 44, '神が大河を血に変えられたのでその流れは飲めなくなった。'),
('JPN', '诗篇', 19, 78, 45, '神は彼らにあぶの群れを送り蛙を送って彼らを食い尽くされた。'),
('JPN', '诗篇', 19, 78, 46, 'また彼らの作物を若いいなごに彼らの勤労の実をいなごに与えられた。'),
('JPN', '诗篇', 19, 78, 47, '神は雹で彼らのぶどうの木を稲妻でいちじく桑の木を滅ぼされた。'),
('JPN', '诗篇', 19, 78, 48, '彼らの家畜を雹に家畜の群れを疫病に渡された。'),
('JPN', '诗篇', 19, 78, 49, '神は彼らの上に燃える怒りを送られた。激しい怒りと憤りと苦しみを。わざわいをもたらす御使いたちを。'),
('JPN', '诗篇', 19, 78, 50, '神は御怒りに道を備え彼ら自身に死を免れさせず彼らのいのちを疫病に渡された。'),
('JPN', '诗篇', 19, 78, 51, '神はエジプトですべての長子を打ち殺された。ハムの天幕で彼らの力の初穂を。'),
('JPN', '诗篇', 19, 78, 52, '神はご自分の民を羊の群れのように連れ出し家畜の群れのように荒野の中を連れて行かれた。'),
('JPN', '诗篇', 19, 78, 53, '神が安らかに導かれたので彼らは恐れなかった。しかし彼らの敵は海がおおい隠した。'),
('JPN', '诗篇', 19, 78, 54, 'こうして神は彼らをご自分の聖なる国に右の御手で造ったこの山に連れて来られた。'),
('JPN', '诗篇', 19, 78, 55, 'また彼らの前から異邦の民を追い出しその地を相続の地として彼らに分け与えイスラエル諸族をそれぞれの天幕に住まわせた。'),
('JPN', '诗篇', 19, 78, 56, 'けれども彼らはいと高き神を試み神に逆らいそのさとしを守らなかった。'),
('JPN', '诗篇', 19, 78, 57, '彼らは元に戻り先祖たちのように裏切りたるんだ弓の矢のようにそれて行った。'),
('JPN', '诗篇', 19, 78, 58, 'また高き所を築いて神の怒りを引き起こし刻んだ像で神のねたみを起こさせた。'),
('JPN', '诗篇', 19, 78, 59, '神は聞いて激しく怒りイスラエルを激しく退けられた。'),
('JPN', '诗篇', 19, 78, 60, 'シロの御住まい人々の間に張ったその幕屋を見放して'),
('JPN', '诗篇', 19, 78, 61, '御力を捕らえられるに任せ御栄えを敵の手に渡された。'),
('JPN', '诗篇', 19, 78, 62, '神はご自分の民を剣に引き渡しゆずりの民に対して激しく怒られた。'),
('JPN', '诗篇', 19, 78, 63, '火は若い男たちを食い尽くし若い女たちは婚礼の歌を歌わなかった。'),
('JPN', '诗篇', 19, 78, 64, '祭司たちは剣に倒れやもめたちは泣くこともできなかった。'),
('JPN', '诗篇', 19, 78, 65, 'そのとき主は眠りから目を覚まされた。ぶどう酒の酔いから覚めた勇士のように。'),
('JPN', '诗篇', 19, 78, 66, '主はその敵を打って退け彼らに永遠のそしりを与えられた。'),
('JPN', '诗篇', 19, 78, 67, '主はヨセフの天幕を捨てエフライム族を選ばず'),
('JPN', '诗篇', 19, 78, 68, 'ユダの部族を選ばれた。主が愛されたシオンの山を。'),
('JPN', '诗篇', 19, 78, 69, '主はその聖所を高い天のように建てられた。ご自分が永遠に基を据えた地のように。'),
('JPN', '诗篇', 19, 78, 70, '主はしもべダビデを選び羊の囲いから召し出された。'),
('JPN', '诗篇', 19, 78, 71, '乳を飲ませる雌羊の番から彼を連れて来て御民ヤコブをご自分のゆずりの民イスラエルを牧するようにされた。'),
('JPN', '诗篇', 19, 78, 72, '彼は全き心で彼らを牧し英知の手で彼らを導いた。'),
('JPN', '诗篇', 19, 79, 1, '神よ国々はあなたのゆずりの地に侵入しあなたの聖なる宮を汚しエルサレムを瓦礫の山としました。'),
('JPN', '诗篇', 19, 79, 2, '彼らはあなたのしもべたちの屍を空の鳥の餌食としあなたにある敬虔な人たちの肉を地の獣に与え'),
('JPN', '诗篇', 19, 79, 3, '彼らの血をエルサレムの周りに水のように注ぎ出しました。彼らを葬る者もいません。'),
('JPN', '诗篇', 19, 79, 4, '私たちは隣人のそしりの的となり周りの者に嘲られ笑いぐさとなりました。'),
('JPN', '诗篇', 19, 79, 5, '主よいつまでですか。とこしえにあなたはお怒りになるのですか。いつまであなたのねたみは火のように燃えるのですか。'),
('JPN', '诗篇', 19, 79, 6, 'どうかあなたの激しい憤りを注いでください。あなたを知らない国々に。御名を呼び求めない王国の上に。'),
('JPN', '诗篇', 19, 79, 7, '彼らはヤコブを食い尽くしその住む所を荒らしたのです。'),
('JPN', '诗篇', 19, 79, 8, '先祖たちの咎を私たちのものとして思い出さないでください。あなたのあわれみが速やかに私たちを迎えるようにしてください。私たちはひどくおとしめられているのです。'),
('JPN', '诗篇', 19, 79, 9, '私たちの救いの神よ私たちを助けてください。御名の栄光のために。私たちを救い出し私たちの罪をお赦しください。御名のゆえに。'),
('JPN', '诗篇', 19, 79, 10, 'なぜ国々は「彼らの神はどこにいるのか」と言うのでしょう。あなたのしもべたちの流された血の復讐が私たちの目の前で国々に果たされますように。'),
('JPN', '诗篇', 19, 79, 11, '捕らわれ人のうめきが御前に届きますように。あなたの大いなる力のゆえに死に定められた人々を生きながらえさせてください。'),
('JPN', '诗篇', 19, 79, 12, '主よあなたをそしったそのそしりの七倍を私たちの隣人らの胸に返してください。'),
('JPN', '诗篇', 19, 79, 13, '私たちはあなたの民あなたの牧場の羊です。私たちはとこしえまでもあなたに感謝し代々限りなくあなたの誉れを語り告げます。'),
('JPN', '诗篇', 19, 80, 1, 'イスラエルの牧者よ聞いてください。ヨセフを羊の群れのように導かれる方よ光を放ってください。ケルビムの上に座しておられる方よ。'),
('JPN', '诗篇', 19, 80, 2, 'エフライムとベニヤミンとマナセの前で御力を呼び覚まし私たちを救いに来てください。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '诗篇', 19, 80, 3, '神よ私たちを元に戻し御顔を照り輝かせてください。そうすれば私たちは救われます。'),
('JPN', '诗篇', 19, 80, 4, '万軍の神主よいつまであなたの民の祈りに怒りを燃やされるのですか。'),
('JPN', '诗篇', 19, 80, 5, 'あなたは彼らに涙のパンを食べさせあふれる涙を飲ませられました。'),
('JPN', '诗篇', 19, 80, 6, 'あなたは私たちを隣人らの争いの的とし私たちの敵は私たちを嘲っています。'),
('JPN', '诗篇', 19, 80, 7, '万軍の神よ私たちを元に戻し御顔を照り輝かせてください。そうすれば私たちは救われます。'),
('JPN', '诗篇', 19, 80, 8, 'あなたはエジプトからぶどうの木を引き抜き異邦の民を追い出してそれを植えられました。'),
('JPN', '诗篇', 19, 80, 9, 'その木のためにあなたが地を整えられたのでそれは深く根を張り地の全面に広がりました。'),
('JPN', '诗篇', 19, 80, 10, '山々もその影におおわれました。神の杉の木もその大枝に。'),
('JPN', '诗篇', 19, 80, 11, 'ぶどうの木はその枝を海にまで若枝をあの川にまで伸ばしました。'),
('JPN', '诗篇', 19, 80, 12, 'なぜあなたはその石垣を破り道を行くすべての者がその実を摘み取るままにされるのですか。'),
('JPN', '诗篇', 19, 80, 13, '林の猪はこれを食い荒らし野に群がるものもこれを食らっています。'),
('JPN', '诗篇', 19, 80, 14, '万軍の神よどうか帰って来てください。天から目を注ぎご覧になってください。このぶどうの木を顧みてください。'),
('JPN', '诗篇', 19, 80, 15, 'あなたの右の手が植えた苗とご自分のために強くされた枝とを。'),
('JPN', '诗篇', 19, 80, 16, 'それは火で焼かれ切り倒されています。民は御顔のとがめによって滅びています。'),
('JPN', '诗篇', 19, 80, 17, 'あなたの右にいる人の上に御手がご自分のため強くされた人の子の上に御手がありますように。'),
('JPN', '诗篇', 19, 80, 18, '私たちはあなたから離れ去りません。私たちを生かしてください。私たちはあなたの御名を呼び求めます。'),
('JPN', '诗篇', 19, 80, 19, '万軍の神主よ私たちを元に戻し御顔を照り輝かせてください。そうすれば私たちは救われます。'),
('JPN', '诗篇', 19, 81, 1, '喜び歌え私たちの力なる神に。喜び叫べヤコブの神に。'),
('JPN', '诗篇', 19, 81, 2, 'ほめ歌を歌いタンバリンを打ち鳴らせ。麗しい音色の竪琴を琴に合わせてかき鳴らせ。'),
('JPN', '诗篇', 19, 81, 3, '新月と満月に角笛を吹き鳴らせ。私たちの祭りの日に。'),
('JPN', '诗篇', 19, 81, 4, 'これはイスラエルのためのおきてヤコブの神のための定めである。'),
('JPN', '诗篇', 19, 81, 5, '神がエジプトの地に向かって出て行かれたときヨセフのうちにそれをさとしとして授けられた。私はまだ知らなかったことばを聞いた。'),
('JPN', '诗篇', 19, 81, 6, '「わたしは彼の肩から重荷を除き彼の手を荷かごから離してやった。'),
('JPN', '诗篇', 19, 81, 7, '苦しみの中であなたは叫びわたしはあなたを助け出した。わたしは雷の隠れ場からあなたに答えメリバの水のほとりであなたを試した。セラ'),
('JPN', '诗篇', 19, 81, 8, '聞けわが民よ。わたしはあなたを戒めよう。イスラエルよわたしの言うことをよく聞け。'),
('JPN', '诗篇', 19, 81, 9, 'あなたのうちに異なる神があってはならない。異国の神を拝んではならない。'),
('JPN', '诗篇', 19, 81, 10, 'わたしはあなたの神主である。わたしがあなたをエジプトの地から連れ上った。あなたの口を大きく開けよ。わたしがそれを満たそう。'),
('JPN', '诗篇', 19, 81, 11, 'しかしわたしの民はわたしの声を聞かずイスラエルはわたしに服従しなかった。'),
('JPN', '诗篇', 19, 81, 12, 'それでわたしは彼らを頑なな心のままに任せ自分たちのはかりごとのままに歩ませた。'),
('JPN', '诗篇', 19, 81, 13, 'ああただわたしの民がわたしに聞き従いイスラエルがわたしの道を歩んでいたなら。'),
('JPN', '诗篇', 19, 81, 14, 'わたしはただちに彼らの敵を征服し彼らに逆らう者に手を下したのに。'),
('JPN', '诗篇', 19, 81, 15, '主を憎む者どもは主にへつらうが彼らの刑罰の時は永遠にまで至る。'),
('JPN', '诗篇', 19, 81, 16, 'しかし主は最良の小麦を御民に食べさせる。わたしは岩から滴る蜜であなたを満ち足らせる。」'),
('JPN', '诗篇', 19, 82, 1, '神は神の会議の中に立ち神々のただ中でさばきを下す。'),
('JPN', '诗篇', 19, 82, 2, 'いつまでおまえたちは不正をもってさばき悪しき者たちの味方をするのか。セラ'),
('JPN', '诗篇', 19, 82, 3, '弱い者とみなしごのためにさばき苦しむ者と乏しい者の正しさを認めよ。'),
('JPN', '诗篇', 19, 82, 4, '弱い者と貧しい者を助け出し悪しき者たちの手から救い出せ。'),
('JPN', '诗篇', 19, 82, 5, '彼らは知らない。また悟らない。彼らは暗闇の中を歩き回る。地の基はことごとく揺らいでいる。'),
('JPN', '诗篇', 19, 82, 6, 'わたしは言った。「おまえたちは神々だ。みないと高き者の子らだ。'),
('JPN', '诗篇', 19, 82, 7, 'にもかかわらずおまえたちは人のように死に君主たちの一人のように倒れるのだ。」'),
('JPN', '诗篇', 19, 82, 8, '神よ立ち上がって地をさばいてください。あなたがすべての国々をご自分のものとしておられるからです。'),
('JPN', '诗篇', 19, 83, 1, '神よ沈黙していないでください。黙っていないでください。神よ黙り続けないでください。'),
('JPN', '诗篇', 19, 83, 2, 'ご覧ください。あなたの敵が騒ぎ立ちあなたを憎む者どもが頭をもたげています。'),
('JPN', '诗篇', 19, 83, 3, '彼らはあなたの民に対して悪賢いはかりごとをめぐらしあなたにかくまわれている者たちに悪を企んでいます。'),
('JPN', '诗篇', 19, 83, 4, '彼らは言っています。「さあ彼らの国を消し去ってイスラエルの名がもはや覚えられないようにしよう。」'),
('JPN', '诗篇', 19, 83, 5, '彼らは心を一つにして悪を企みあなたに逆らって盟約を結んでいます。'),
('JPN', '诗篇', 19, 83, 6, 'エドムの天幕の民とイシュマエル人モアブとハガル人'),
('JPN', '诗篇', 19, 83, 7, 'ゲバルとアンモンそれにアマレクペリシテさらにはツロの住民。'),
('JPN', '诗篇', 19, 83, 8, 'アッシリアも彼らにくみし彼らはロトの子らの腕となりました。セラ'),
('JPN', '诗篇', 19, 83, 9, 'どうか彼らをミディアンやキション川でのシセラとヤビンのようにしてください。'),
('JPN', '诗篇', 19, 83, 10, 'エン・ドルで滅ぼし尽くされ土地の肥やしとなった者たちのように。'),
('JPN', '诗篇', 19, 83, 11, '彼らの貴族たちをオレブとゼエブのようにし彼らの君主たちをみなゼバフとツァルムナのようにしてください。'),
('JPN', '诗篇', 19, 83, 12, '彼らは言っています。「神の牧場を奪ってわれわれのものとしよう。」'),
('JPN', '诗篇', 19, 83, 13, '私の神よ彼らを風の前に吹き転がされる藁のようにしてください。'),
('JPN', '诗篇', 19, 83, 14, '林を燃やす火のように山々を焼き尽くす炎のように'),
('JPN', '诗篇', 19, 83, 15, 'そのようにあなたの疾風で彼らを追いあなたの嵐で恐れおののかせてください。'),
('JPN', '诗篇', 19, 83, 16, '彼らの顔を恥で満たしてください。主よ彼らが御名を捜し回りますように。'),
('JPN', '诗篇', 19, 83, 17, '彼らがいつまでも恥を見て恐れおののきますように。辱めを受けて滅びますように。'),
('JPN', '诗篇', 19, 83, 18, 'こうして彼らが知りますように。その名が主であるあなただけが全地の上におられるいと高き方であることを。'),
('JPN', '诗篇', 19, 84, 1, '万軍の主よあなたの住まいはなんと慕わしいことでしょう。'),
('JPN', '诗篇', 19, 84, 2, '私のたましいは主の大庭を恋い慕って絶え入るばかりです。私の心も身も生ける神に喜びの歌を歌います。'),
('JPN', '诗篇', 19, 84, 3, '雀さえも住みかを燕もひなを入れる巣をあなたの祭壇のところに得ます。万軍の主私の王私の神よ。'),
('JPN', '诗篇', 19, 84, 4, 'なんと幸いなことでしょう。あなたの家に住む人たちは。彼らはいつもあなたをほめたたえています。セラ'),
('JPN', '诗篇', 19, 84, 5, 'なんと幸いなことでしょう。その力があなたにあり心の中にシオンへの大路のある人は。'),
('JPN', '诗篇', 19, 84, 6, '彼らは涙の谷を過ぎるときもそこを泉の湧く所とします。初めの雨もそこを大いなる祝福でおおいます。'),
('JPN', '诗篇', 19, 84, 7, '彼らは力から力へと進みシオンで神の御前に現れます。'),
('JPN', '诗篇', 19, 84, 8, '万軍の神主よ私の祈りを聞いてください。ヤコブの神よ耳を傾けてください。セラ'),
('JPN', '诗篇', 19, 84, 9, '神よわれらの盾をご覧ください。あなたに油注がれた者の顔に目を留めてください。'),
('JPN', '诗篇', 19, 84, 10, 'まことにあなたの大庭にいる一日は千日にまさります。私は悪の天幕に住むよりは私の神の家の門口に立ちたいのです。'),
('JPN', '诗篇', 19, 84, 11, 'まことに神である主は太陽また盾。主は恵みと栄光を与え誠実に歩む者に良いものを拒まれません。'),
('JPN', '诗篇', 19, 84, 12, '万軍の主よなんと幸いなことでしょう。あなたに信頼する人は。'),
('JPN', '诗篇', 19, 85, 1, '主よあなたはご自分の地に恵みを施しヤコブを元どおりにされます。'),
('JPN', '诗篇', 19, 85, 2, 'あなたは御民の咎を担いすべての罪をおおってくださいます。セラ'),
('JPN', '诗篇', 19, 85, 3, 'あなたは激しい怒りをすべて収め燃える御怒りから身を引かれます。'),
('JPN', '诗篇', 19, 85, 4, '帰って来てください。私たちのところに。私たちの救いの神。私たちへの御怒りをやめてください。'),
('JPN', '诗篇', 19, 85, 5, 'あなたはとこしえに私たちに対して怒られるのですか。代々に至るまで御怒りを引き延ばされるのですか。'),
('JPN', '诗篇', 19, 85, 6, 'あなたは帰って来て私たちを生かしてくださらないのですか。あなたの民があなたにあって喜ぶために。'),
('JPN', '诗篇', 19, 85, 7, '主よ私たちにお示しください。あなたの恵みを。私たちにお与えください。あなたの救いを。'),
('JPN', '诗篇', 19, 85, 8, '聞かせてください。主である神の仰せを。主は御民に主にある敬虔な人たちに平和を告げられます。彼らが再び愚かさに戻らないように。'),
('JPN', '诗篇', 19, 85, 9, '確かに御救いは主を恐れる者たちに近い。それは栄光が私たちの地にとどまるためです。'),
('JPN', '诗篇', 19, 85, 10, '恵みとまことはともに会い義と平和は口づけします。'),
('JPN', '诗篇', 19, 85, 11, 'まことは地から生え出で義は天から見下ろします。'),
('JPN', '诗篇', 19, 85, 12, '主が良いものを下さるので私たちの大地は産物を産み出します。'),
('JPN', '诗篇', 19, 85, 13, '義は主の御前に先立って行き主の足跡を道とします。'),
('JPN', '诗篇', 19, 86, 1, '主よ耳を傾けて私に答えてください。私は苦しみ貧しいのです。'),
('JPN', '诗篇', 19, 86, 2, '私のたましいをお守りください。私は神を恐れる者です。あなたのしもべをお救いください。あなたは私の神。私はあなたに信頼します。'),
('JPN', '诗篇', 19, 86, 3, '主よ私をあわれんでください。絶えず私はあなたを呼んでいます。'),
('JPN', '诗篇', 19, 86, 4, 'このしもべのたましいを喜ばせてください。主よ私のたましいはあなたを仰ぎ求めています。'),
('JPN', '诗篇', 19, 86, 5, '主よまことにあなたはいつくしみ深く赦しに富みあなたを呼び求める者すべてに恵み豊かであられます。'),
('JPN', '诗篇', 19, 86, 6, '主よ私の祈りに耳を傾け私の願いの声を心に留めてください。'),
('JPN', '诗篇', 19, 86, 7, '苦難の日に私はあなたを呼び求めます。あなたが私に答えてくださるからです。'),
('JPN', '诗篇', 19, 86, 8, '主よ神々のうちであなたに並ぶ者はなくあなたのみわざに比べられるものはありません。'),
('JPN', '诗篇', 19, 86, 9, '主よあなたが造られたすべての国々はあなたの御前に来て伏し拝みあなたの御名をあがめます。'),
('JPN', '诗篇', 19, 86, 10, 'まことにあなたは大いなる方奇しいみわざを行われる方。あなただけが神です。'),
('JPN', '诗篇', 19, 86, 11, '主よあなたの道を私に教えてください。私はあなたの真理のうちを歩みます。私の心を一つにしてください。御名を恐れるように。'),
('JPN', '诗篇', 19, 86, 12, 'わが神主よ私は心を尽くしてあなたに感謝しとこしえまでもあなたの御名をあがめます。'),
('JPN', '诗篇', 19, 86, 13, 'あなたの恵みは私の上に大きくあなたが私のたましいをよみの深みから救い出してくださるからです。'),
('JPN', '诗篇', 19, 86, 14, '神よ高ぶる者どもは私に向かい立ち横暴な者の群れが私のいのちを求めます。彼らはあなたを前にしていません。'),
('JPN', '诗篇', 19, 86, 15, 'しかし主よあなたはあわれみ深く情け深い神。怒るのに遅く恵みとまことに富んでおられます。'),
('JPN', '诗篇', 19, 86, 16, '御顔を私に向け私をあわれんでください。あなたのしもべに御力を与えあなたのはしための子をお救いください。'),
('JPN', '诗篇', 19, 86, 17, '私にいつくしみのしるしを行ってください。そうすれば私を憎む者どもは見て恥を受けます。主よあなたが私を助け慰めてくださるからです。'),
('JPN', '诗篇', 19, 87, 1, '主の礎は聖なる山にある。'),
('JPN', '诗篇', 19, 87, 2, '主はシオンの門を愛される。ヤコブのどの住まいよりも。'),
('JPN', '诗篇', 19, 87, 3, '神の都よあなたについて誉れあることが語られている。セラ'),
('JPN', '诗篇', 19, 87, 4, '「わたしはラハブとバビロンをわたしを知る者として記憶しよう。見よペリシテとツロクシュもともに。『この者はこの都で生まれた』と。」'),
('JPN', '诗篇', 19, 87, 5, 'しかしシオンについてはこう言われている。「この者もあの者もこの都で生まれた。いと高き方ご自身がシオンを堅く建てられる」と。'),
('JPN', '诗篇', 19, 87, 6, '主が「この者はこの都で生まれた」と記して国々の民を登録される。セラ'),
('JPN', '诗篇', 19, 87, 7, '歌う者も踊る者も「私の泉はみなあなたにあります」と言う。'),
('JPN', '诗篇', 19, 88, 1, '主よ私の救いの神よ昼私は叫びます。夜もあなたのみそばで。'),
('JPN', '诗篇', 19, 88, 2, '私の祈りをあなたの御前にささげます。どうか私の叫びに耳を傾けてください。'),
('JPN', '诗篇', 19, 88, 3, '私のたましいは苦しみに満ち私のいのちはよみに触れていますから。'),
('JPN', '诗篇', 19, 88, 4, '私は穴に下る者たちとともに数えられ力の失せた者のようになっています。'),
('JPN', '诗篇', 19, 88, 5, '私は死人たちの間に放り出され墓に横たわる刺し殺された者たちのようです。あなたはもはや彼らを覚えてはおられません。彼らはあなたの御手から断ち切られています。'),
('JPN', '诗篇', 19, 88, 6, 'あなたは私を最も深い穴に置かれました。暗い所に深い淵に。'),
('JPN', '诗篇', 19, 88, 7, 'あなたの憤りが私の上にとどまりあなたのすべての波であなたは私を苦しめておられます。セラ'),
('JPN', '诗篇', 19, 88, 8, 'あなたは私の親友を私から遠ざけ私を彼らの忌み嫌う者とされました。私は閉じ込められて出て行くことができません。'),
('JPN', '诗篇', 19, 88, 9, '私の目は苦しみによって衰えています。主よ私は日ごとにあなたを呼び求めています。あなたに向かって両手を差し伸ばしています。'),
('JPN', '诗篇', 19, 88, 10, 'あなたは死人のために奇しいみわざを行われるでしょうか。亡霊が起き上がりあなたをほめたたえるでしょうか。セラ'),
('JPN', '诗篇', 19, 88, 11, 'あなたの恵みが墓の中で宣べられるでしょうか。あなたの真実が滅びの淵で。'),
('JPN', '诗篇', 19, 88, 12, 'あなたの奇しいみわざが闇の中で知られるでしょうか。あなたの義が忘却の地で。'),
('JPN', '诗篇', 19, 88, 13, 'しかし私は主よあなたに叫び求めます。朝明けに私の祈りは御前にあります。'),
('JPN', '诗篇', 19, 88, 14, '主よなぜあなたは私のたましいを退け私に御顔を隠されるのですか。'),
('JPN', '诗篇', 19, 88, 15, '私は苦しんでいます。若いころから死に瀕してきました。あなたの恐ろしさに耐えかねて私の心はくずおれそうです。'),
('JPN', '诗篇', 19, 88, 16, 'あなたの燃える怒りが私の上を越えて行きあなたからの恐怖が私を滅ぼし尽くしました。'),
('JPN', '诗篇', 19, 88, 17, 'それらは日夜大水のように私を囲み瞬く間に私を取り巻いてしまいました。'),
('JPN', '诗篇', 19, 88, 18, 'あなたは私から愛する者や友を遠ざけられました。私は暗闇を親しい友としています。'),
('JPN', '诗篇', 19, 89, 1, '私は主の恵みをとこしえに歌います。あなたの真実を代々限りなく私の口で知らせます。'),
('JPN', '诗篇', 19, 89, 2, '私は言います。「御恵みはとこしえに打ち立てられあなたはその真実を天に堅く立てておられます。」'),
('JPN', '诗篇', 19, 89, 3, '「わたしはわたしの選んだ者と契約を結びわたしのしもべダビデに誓う。'),
('JPN', '诗篇', 19, 89, 4, 'わたしはあなたの裔をとこしえまでも堅く立てあなたの王座を代々限りなく打ち立てる。」セラ'),
('JPN', '诗篇', 19, 89, 5, '主よ天はあなたの奇しいみわざをほめたたえます。まことにあなたの真実を聖なる者の集いで。'),
('JPN', '诗篇', 19, 89, 6, 'いったい雲の上ではだれが主と並び得るでしょう。力ある者の子らの中でだれが主に似ているでしょう。'),
('JPN', '诗篇', 19, 89, 7, '主は聖なる者の会合で大いに恐れられる神。主を囲むすべての者の上におられる恐るべき方。'),
('JPN', '诗篇', 19, 89, 8, '万軍の神主よ。だれがあなたのように力があるでしょう。主よ。あなたの真実はあなたを取り囲んでいます。'),
('JPN', '诗篇', 19, 89, 9, 'あなたは海の高まりを治めておられます。波が逆巻くときあなたはそれを鎮められます。'),
('JPN', '诗篇', 19, 89, 10, 'ラハブを打ち砕いて殺された者のようにしあなたの敵を力ある御腕で散らされました。'),
('JPN', '诗篇', 19, 89, 11, '天はあなたのもの地もあなたのもの。世界とそこに満ちているものはあなたが基を据えられました。'),
('JPN', '诗篇', 19, 89, 12, '北と南あなたがこれらを創造されました。タボルとヘルモンは御名を高らかに歌います。'),
('JPN', '诗篇', 19, 89, 13, 'あなたには力ある腕があります。御手は強く右の手は高く上げられています。'),
('JPN', '诗篇', 19, 89, 14, '義と公正はあなたの王座の基。恵みとまことが御前を進みます。'),
('JPN', '诗篇', 19, 89, 15, '幸いなことよ喜びの叫びを知る民は。主よ彼らはあなたの御顔の光の中を歩みます。'),
('JPN', '诗篇', 19, 89, 16, '彼らはあなたの御名をいつも喜びあなたの義によって高く上げられます。'),
('JPN', '诗篇', 19, 89, 17, 'あなたが彼らの力の輝きでありあなたのご恩寵によって私たちの角を高く上げられるからです。'),
('JPN', '诗篇', 19, 89, 18, '私たちの盾は主のもの私たちの王はイスラエルの聖なる方のもの。'),
('JPN', '诗篇', 19, 89, 19, 'あなたはかつて幻を通してあなたにある敬虔な者たちに告げられました。「わたしは一人の勇士に助けを与え民の中から一人の若者を高く上げた。'),
('JPN', '诗篇', 19, 89, 20, 'わたしはわたしのしもべダビデを見出しわたしの聖なる油で油を注いだ。'),
('JPN', '诗篇', 19, 89, 21, 'わたしの手は彼とともにあって揺るがずわたしの腕も彼を強くする。'),
('JPN', '诗篇', 19, 89, 22, '敵が彼に害を加えることはなく不正な者も彼を苦しめることはない。'),
('JPN', '诗篇', 19, 89, 23, 'わたしは彼の前で彼の敵を打ち砕き彼を憎む者を打ち破る。'),
('JPN', '诗篇', 19, 89, 24, 'わたしの真実とわたしの恵みは彼とともにありわたしの名によって彼の角は高く上げられる。'),
('JPN', '诗篇', 19, 89, 25, 'わたしは彼の手を海の上に彼の右の手を川の上に置く。'),
('JPN', '诗篇', 19, 89, 26, '彼はわたしを呼ぶ。『あなたはわが父わが神わが救いの岩』と。'),
('JPN', '诗篇', 19, 89, 27, 'わたしもまた彼をわたしの長子地の王たちのうちの最も高い者とする。'),
('JPN', '诗篇', 19, 89, 28, 'わたしの恵みを彼のために永遠に保つ。わたしの契約は彼にとって確かなものである。'),
('JPN', '诗篇', 19, 89, 29, 'わたしは彼の子孫をいつまでも彼の王座を天の日数のように続かせる。'),
('JPN', '诗篇', 19, 89, 30, 'もしその子孫がわたしのおしえを捨てわたしの定めのうちを歩まないなら'),
('JPN', '诗篇', 19, 89, 31, 'またもし彼らがわたしのおきてを破りわたしの命令を守らないなら'),
('JPN', '诗篇', 19, 89, 32, 'わたしは杖をもって彼らの背きをむちをもって彼らの咎を罰する。'),
('JPN', '诗篇', 19, 89, 33, 'しかしわたしは彼から恵みをもぎ取らずわたしの真実を偽らない。'),
('JPN', '诗篇', 19, 89, 34, 'わたしはわたしの契約を汚さない。唇から出たことをわたしは変えない。'),
('JPN', '诗篇', 19, 89, 35, 'わたしはかつてわが聖によって誓った。わたしは決してダビデに偽りを言わないと。'),
('JPN', '诗篇', 19, 89, 36, '彼の子孫はとこしえまでも続く。その王座は太陽のようにわたしの前にあり'),
('JPN', '诗篇', 19, 89, 37, '月のようにとこしえに堅く立つ。その子孫は雲の上の確かな証人である。」セラ'),
('JPN', '诗篇', 19, 89, 38, 'しかしあなたは拒んでお捨てになりました。あなたは激しく怒っておられます。あなたに油注がれた者に向かって。'),
('JPN', '诗篇', 19, 89, 39, 'あなたはあなたのしもべとの契約を廃棄し彼の王冠を地に捨てて汚しておられます。'),
('JPN', '诗篇', 19, 89, 40, 'あなたは彼の城壁をことごとく打ち壊しその要塞を廃墟とされました。'),
('JPN', '诗篇', 19, 89, 41, '道行く者はみな彼から奪い取り彼は隣人のそしりの的となっています。'),
('JPN', '诗篇', 19, 89, 42, 'あなたは彼の仇の右手を高く上げ彼の敵をみな喜ばせておられます。'),
('JPN', '诗篇', 19, 89, 43, 'しかもあなたは彼の剣の刃をさやに戻し彼が戦いに立てないようにしておられます。'),
('JPN', '诗篇', 19, 89, 44, 'あなたは彼の輝きを消し彼の王座を地に投げ倒されました。'),
('JPN', '诗篇', 19, 89, 45, 'あなたは彼の若い日を短くし恥で彼をおおわれました。セラ'),
('JPN', '诗篇', 19, 89, 46, 'いつまでですか。主よ。あなたがどこまでも身を隠されあなたの憤りが火のように燃えるのは。'),
('JPN', '诗篇', 19, 89, 47, '心に留めてください。私の生涯がどれほどかを。あなたがすべての人の子らをいかにむなしいものとして創造されたかを。'),
('JPN', '诗篇', 19, 89, 48, '生きていて死を見ない人はだれでしょう。だれが自分自身をよみの手から救い出せるでしょう。セラ'),
('JPN', '诗篇', 19, 89, 49, '主よあなたのかつての恵みはどこにあるのでしょうか。あなたは真実をもってダビデに誓われたのです。'),
('JPN', '诗篇', 19, 89, 50, '主よみこころに留めてください。あなたのしもべたちの受ける恥辱を。私が多くの国々の民をすべてこの胸にこらえていることを。'),
('JPN', '诗篇', 19, 89, 51, '主よあなたの敵どもはそしりました。あなたに油注がれた者の足跡をそしったのです。'),
('JPN', '诗篇', 19, 89, 52, '主はとこしえにほむべきかな。アーメン、アーメン。'),
('JPN', '诗篇', 19, 90, 1, '主よ代々にわたってあなたは私たちの住まいです。'),
('JPN', '诗篇', 19, 90, 2, '山々が生まれる前から地と世界をあなたが生み出す前からとこしえからとこしえまであなたは神です。'),
('JPN', '诗篇', 19, 90, 3, 'あなたは人をちりに帰らせます。「人の子らよ帰れ」と言われます。'),
('JPN', '诗篇', 19, 90, 4, 'まことにあなたの目には千年も昨日のように過ぎ去り夜回りのひと時ほどです。'),
('JPN', '诗篇', 19, 90, 5, 'あなたが押し流すと人は眠りに落ちます。朝には草のように消えています。'),
('JPN', '诗篇', 19, 90, 6, '朝花を咲かせても移ろい夕べにはしおれて枯れています。'),
('JPN', '诗篇', 19, 90, 7, '私たちはあなたの御怒りによって消え失せあなたの憤りにおじ惑います。'),
('JPN', '诗篇', 19, 90, 8, 'あなたは私たちの咎を御前に私たちの秘め事を御顔の光の中に置かれます。'),
('JPN', '诗篇', 19, 90, 9, '私たちのすべての日はあなたの激しい怒りの中に消え去り私たちは自分の齢を一息のように終わらせます。'),
('JPN', '诗篇', 19, 90, 10, '私たちの齢は七十年。健やかであっても八十年。そのほとんどは労苦とわざわいです。瞬く間に時は過ぎ私たちは飛び去ります。'),
('JPN', '诗篇', 19, 90, 11, 'だれが御怒りの力をあなたの激しい怒りの力を知っているでしょう。ふさわしい恐れを持つほどに。'),
('JPN', '诗篇', 19, 90, 12, 'どうか教えてください。自分の日を数えることを。そうして私たちに知恵の心を得させてください。'),
('JPN', '诗篇', 19, 90, 13, '帰って来てください。主よいつまでなのですか。あなたのしもべたちをあわれんでください。'),
('JPN', '诗篇', 19, 90, 14, '朝ごとにあなたの恵みで私たちを満ち足らせてください。私たちのすべての日に喜び歌い楽しむことができるように。'),
('JPN', '诗篇', 19, 90, 15, 'どうか喜ばせてください。私たちが苦しめられた日々とわざわいにあった年月に応じて。'),
('JPN', '诗篇', 19, 90, 16, 'みわざをあなたのしもべらにご威光を彼らの子らの上に現してください。'),
('JPN', '诗篇', 19, 90, 17, '私たちの神主の慈愛が私たちの上にありますように。私たちのために私たちの手のわざを確かなものにしてください。どうか私たちの手のわざを確かなものにしてください。'),
('JPN', '诗篇', 19, 91, 1, 'いと高き方の隠れ場に住む者その人は全能者の陰に宿る。'),
('JPN', '诗篇', 19, 91, 2, '私は主に申し上げよう。「私の避け所私の砦私が信頼する私の神」と。'),
('JPN', '诗篇', 19, 91, 3, '主こそ狩人の罠から破滅をもたらす疫病からあなたを救い出される。'),
('JPN', '诗篇', 19, 91, 4, '主はご自分の羽であなたをおおいあなたはその翼の下に身を避ける。主の真実は大盾また砦。'),
('JPN', '诗篇', 19, 91, 5, 'あなたは恐れない。夜襲の恐怖も昼に飛び来る矢も。'),
('JPN', '诗篇', 19, 91, 6, '暗闇に忍び寄る疫病も真昼に荒らす滅びをも。'),
('JPN', '诗篇', 19, 91, 7, '千人があなたの傍らに万人があなたの右に倒れてもそれはあなたには近づかない。'),
('JPN', '诗篇', 19, 91, 8, 'あなたはただそれを目にし悪者への報いを見るだけである。'),
('JPN', '诗篇', 19, 91, 9, 'それはわが避け所主をいと高き方をあなたが自分の住まいとしたからである。'),
('JPN', '诗篇', 19, 91, 10, 'わざわいはあなたに降りかからず疫病もあなたの天幕に近づかない。'),
('JPN', '诗篇', 19, 91, 11, '主があなたのために御使いたちに命じてあなたのすべての道であなたを守られるからだ。'),
('JPN', '诗篇', 19, 91, 12, '彼らはその両手にあなたをのせあなたの足が石に打ち当たらないようにする。'),
('JPN', '诗篇', 19, 91, 13, 'あなたは獅子とコブラを踏みつけ若獅子と蛇を踏みにじる。'),
('JPN', '诗篇', 19, 91, 14, '「彼がわたしを愛しているからわたしは彼を助け出す。彼がわたしの名を知っているからわたしは彼を高く上げる。'),
('JPN', '诗篇', 19, 91, 15, '彼がわたしを呼び求めればわたしは彼に答える。わたしは苦しみのときに彼とともにいて彼を救い彼に誉れを与える。'),
('JPN', '诗篇', 19, 91, 16, 'わたしは彼をとこしえのいのちで満ち足らせわたしの救いを彼に見せる。」'),
('JPN', '诗篇', 19, 92, 1, '主に感謝することは良いことです。いと高き方よあなたの御名をほめ歌うことは。'),
('JPN', '诗篇', 19, 92, 2, '朝にあなたの恵みを夜ごとにあなたの真実を告げることは。'),
('JPN', '诗篇', 19, 92, 3, '十弦の琴に合わせ竪琴の妙なる調べにのせて。'),
('JPN', '诗篇', 19, 92, 4, '主よあなたはあなたのなさったことで私を喜ばせてくださいました。あなたの御手のわざを私は喜び歌います。'),
('JPN', '诗篇', 19, 92, 5, '主よあなたのみわざはなんと大きいことでしょう。あなたの御思いはあまりにも深いのです。'),
('JPN', '诗篇', 19, 92, 6, '無思慮な者は知らず愚か者にはこれが分かりません。'),
('JPN', '诗篇', 19, 92, 7, '悪い者が青草のように萌え出で不法を行う者がみな花を咲かせてもそれは彼らが永久に滅ぼされるためです。'),
('JPN', '诗篇', 19, 92, 8, '主よあなたは永遠にいと高き所におられます。'),
('JPN', '诗篇', 19, 92, 9, '主よまことに今あなたの敵がまことに今あなたの敵が滅びます。不法を行う者はみな散らされます。'),
('JPN', '诗篇', 19, 92, 10, 'あなたは野牛の角のように私の角を高く上げ私にみずみずしい油を注がれました。'),
('JPN', '诗篇', 19, 92, 11, '私の目は私を待ち構えている者どもを眺め耳は私に向かい立つ悪人どものことを聞きます。'),
('JPN', '诗篇', 19, 92, 12, '正しい者はなつめ椰子の木のように萌え出でレバノンの杉のように育ちます。'),
('JPN', '诗篇', 19, 92, 13, '彼らは主の家に植えられ私たちの神の大庭で花を咲かせます。'),
('JPN', '诗篇', 19, 92, 14, '彼らは年老いてもなお実を実らせ青々と生い茂ります。'),
('JPN', '诗篇', 19, 92, 15, 'こうして告げます。「主は正しい方。わが岩。主には偽りがありません。」'),
('JPN', '诗篇', 19, 93, 1, '主こそ王です。威光をまとっておられます。主はまとっておられます。力を帯とされます。まことに世界は堅く据えられ揺るぎません。'),
('JPN', '诗篇', 19, 93, 2, 'あなたの御座はいにしえから堅く立ちあなたはとこしえからおられます。'),
('JPN', '诗篇', 19, 93, 3, '主よ川はとどろかせています。轟音を川はとどろかせています。激しい響きを川はとどろかせています。'),
('JPN', '诗篇', 19, 93, 4, '大水のとどろきにまさり力強い海の波にもまさって主は力に満ちておられます。いと高き所で。'),
('JPN', '诗篇', 19, 93, 5, 'あなたの証しはまことに確かです。聖なることがあなたの家にはふさわしいのです。主よいつまでも。'),
('JPN', '诗篇', 19, 94, 1, '復讐の神主よ復讐の神よ光を放ってください。'),
('JPN', '诗篇', 19, 94, 2, '地をさばく方よ立ち上がってください。高ぶる者に報復してください。'),
('JPN', '诗篇', 19, 94, 3, '主よいつまでですか悪しき者がいつまでですか悪しき者が勝ち誇るのは。'),
('JPN', '诗篇', 19, 94, 4, '彼らは放言し横柄に語り不法を行う者はみな自慢します。'),
('JPN', '诗篇', 19, 94, 5, '主よ彼らはあなたの民を打ち砕きあなたのゆずりの民を苦しめています。'),
('JPN', '诗篇', 19, 94, 6, '彼らはやもめや寄留者を殺しみなしごたちを死なせています。'),
('JPN', '诗篇', 19, 94, 7, '彼らは言っています。「主は見ることはない。ヤコブの神は気づかない。」'),
('JPN', '诗篇', 19, 94, 8, '気づけ。民のうちのまぬけな者どもよ愚かな者どもよいつになったら悟るのか。'),
('JPN', '诗篇', 19, 94, 9, '耳を植えつけた方が聞かないだろうか。目を造った方が見ないだろうか。'),
('JPN', '诗篇', 19, 94, 10, '国々を戒める方が責めないだろうか。人に知識を教えるその方が。'),
('JPN', '诗篇', 19, 94, 11, '主は人の思い計ることがいかに空しいかを知っておられる。'),
('JPN', '诗篇', 19, 94, 12, 'なんと幸いなことでしょう。主よあなたに戒められあなたのみおしえを教えられる人は。'),
('JPN', '诗篇', 19, 94, 13, 'わざわいの日にあなたはその人に平安を与えられます。しかし悪しき者のためには穴が掘られます。'),
('JPN', '诗篇', 19, 94, 14, 'まことに主はご自分の民を見放さずご自分のゆずりの民をお見捨てになりません。'),
('JPN', '诗篇', 19, 94, 15, 'こうしてさばきは再び義に戻り心の直ぐな人はみなこれに従います。'),
('JPN', '诗篇', 19, 94, 16, 'だれが私のために悪を行う者に向かって立ち上がるでしょうか。だれが私のために不法を行う者に向かって堅く立つでしょうか。'),
('JPN', '诗篇', 19, 94, 17, 'もしも主が私の助けでなかったなら私のたましいはただちに沈黙のうちにとどまったでしょう。'),
('JPN', '诗篇', 19, 94, 18, '「私の足はよろけています」と私が言ったなら主よあなたの恵みで私を支えてください。'),
('JPN', '诗篇', 19, 94, 19, '私のうちで思い煩いが増すときにあなたの慰めで私のたましいを喜ばせてください。'),
('JPN', '诗篇', 19, 94, 20, '破滅をもたらす法廷があなたを仲間に加えるでしょうか。おきてに従いながら邪悪なことを謀る者どもが。'),
('JPN', '诗篇', 19, 94, 21, '彼らは正しい者のいのちを求めてともに集まり不義に定めて咎なき者の血を流します。'),
('JPN', '诗篇', 19, 94, 22, 'しかし主は私の砦となり私の神は私の避け所の岩となられました。'),
('JPN', '诗篇', 19, 94, 23, '主は彼らの不義をその身に返し彼ら自身の悪によって彼らを滅ぼされます。私たちの神主が彼らを滅ぼされます。'),
('JPN', '诗篇', 19, 95, 1, 'さあ主に向かって喜び歌おう。私たちの救いの岩に向かって喜び叫ぼう。'),
('JPN', '诗篇', 19, 95, 2, '感謝をもって御前に進み賛美をもって主に喜び叫ぼう。'),
('JPN', '诗篇', 19, 95, 3, 'まことに主は大いなる神。すべての神々にまさって大いなる王である。'),
('JPN', '诗篇', 19, 95, 4, '地の深みは御手のうちにあり山々の頂も主のものである。'),
('JPN', '诗篇', 19, 95, 5, '海は主のもの。主がそれを造られた。陸地も御手が形造った。'),
('JPN', '诗篇', 19, 95, 6, '来たれ。ひれ伏し膝をかがめよう。私たちを造られた方主の御前にひざまずこう。'),
('JPN', '诗篇', 19, 95, 7, 'まことに主は私たちの神。私たちはその牧場の民その御手の羊。今日もし御声を聞くなら'),
('JPN', '诗篇', 19, 95, 8, 'あなたがたの心を頑なにしてはならない。メリバでのように荒野のマサでの日のように。'),
('JPN', '诗篇', 19, 95, 9, 'あなたがたの先祖はそこでわたしを試みわたしを試した。わたしのわざを見ていたのに。'),
('JPN', '诗篇', 19, 95, 10, '四十年の間わたしはその世代を退けそして言った。「彼らは心の迷った民だ。彼らはわたしの道を知らない。」'),
('JPN', '诗篇', 19, 95, 11, 'そのためわたしは怒りをもって誓った。「彼らは決してわたしの安息に入れない。」'),
('JPN', '诗篇', 19, 96, 1, '新しい歌を主に歌え。全地よ主に歌え。'),
('JPN', '诗篇', 19, 96, 2, '主に歌え。御名をほめたたえよ。日から日へと御救いの良い知らせを告げよ。'),
('JPN', '诗篇', 19, 96, 3, '主の栄光を国々の間で語り告げよ。その奇しいみわざをあらゆる民の間で。'),
('JPN', '诗篇', 19, 96, 4, 'まことに主は大いなる方大いに賛美される方。すべての神々にまさって恐れられる方だ。'),
('JPN', '诗篇', 19, 96, 5, 'まことにどの民の神々もみな偽りだ。しかし主は天をお造りになった。'),
('JPN', '诗篇', 19, 96, 6, '威厳と威光は御前にあり力と輝きは主の聖所にある。'),
('JPN', '诗篇', 19, 96, 7, 'もろもろの民の諸族よ主に帰せよ。栄光と力を主に帰せよ。'),
('JPN', '诗篇', 19, 96, 8, '御名の栄光を主に帰せよ。ささげ物を携えて主の大庭に入れ。'),
('JPN', '诗篇', 19, 96, 9, '聖なる装いをして主にひれ伏せ。全地よ主の御前におののけ。'),
('JPN', '诗篇', 19, 96, 10, '国々の間で言え。「主は王である。まことに世界は堅く据えられ揺るがない。主は公正をもって諸国の民をさばかれる。」'),
('JPN', '诗篇', 19, 96, 11, '天は喜び地は小躍りし海とそこに満ちているものは鳴りとどろけ。'),
('JPN', '诗篇', 19, 96, 12, '野とそこにあるものはみな喜び躍れ。そのとき森の木々もみな喜び歌う。主の御前で。'),
('JPN', '诗篇', 19, 96, 13, '主は必ず来られる。地をさばくために来られる。主は義をもって世界をその真実をもって諸国の民をさばかれる。'),
('JPN', '诗篇', 19, 97, 1, '主は王である。地は小躍りせよ。多くの島々は喜べ。'),
('JPN', '诗篇', 19, 97, 2, '雲と暗黒が主を囲み義とさばきが御座の基である。'),
('JPN', '诗篇', 19, 97, 3, '火は御前に先立ち主の敵を囲んで焼き尽くす。'),
('JPN', '诗篇', 19, 97, 4, '主の稲妻は世界を照らし地はそれを見ておののく。'),
('JPN', '诗篇', 19, 97, 5, '山々は主の御前にろうのように溶ける。全地の主の御前に。'),
('JPN', '诗篇', 19, 97, 6, '天は主の義を告げ諸国の民はその栄光を見る。'),
('JPN', '诗篇', 19, 97, 7, 'すべて偶像に仕える者偽りの神々を誇る者は恥を見る。すべての神々よ主にひれ伏せ。'),
('JPN', '诗篇', 19, 97, 8, 'シオンは聞いて喜びユダの娘たちも小躍りしました。主よあなたのさばきのゆえに。'),
('JPN', '诗篇', 19, 97, 9, '主よあなたこそ全地の上におられるいと高き方。すべての神々を超えて高くあがめられています。'),
('JPN', '诗篇', 19, 97, 10, '主を愛する者たちよ。悪を憎め。主は主にある敬虔な者たちのたましいを守り悪者どもの手から彼らを救い出される。'),
('JPN', '诗篇', 19, 97, 11, '光は正しい者のために蒔かれている。喜びは心の直ぐな人のために。'),
('JPN', '诗篇', 19, 97, 12, '正しい者たち。主にあって喜べ。その聖なる御名に感謝せよ。'),
('JPN', '诗篇', 19, 98, 1, '新しい歌を主に歌え。主は奇しいみわざを行われた。主の右の御手聖なる御腕が主に勝利をもたらしたのだ。'),
('JPN', '诗篇', 19, 98, 2, '主は御救いを知らしめご自分の義を国々の前に現された。'),
('JPN', '诗篇', 19, 98, 3, '主はイスラエルの家への恵みと真実を覚えておられる。地の果てのすべての者が私たちの神の救いを見ている。'),
('JPN', '诗篇', 19, 98, 4, '全地よ主に喜び叫べ。大声で叫び喜び歌いほめ歌を歌え。'),
('JPN', '诗篇', 19, 98, 5, '主にほめ歌を歌え。竪琴に合わせて。竪琴に合わせほめ歌の調べにのせて。'),
('JPN', '诗篇', 19, 98, 6, 'ラッパに合わせ角笛の調べにのせて王である主の御前で喜び叫べ。'),
('JPN', '诗篇', 19, 98, 7, '海とそこに満ちているもの世界とその中に住むものよ鳴りとどろけ。'),
('JPN', '诗篇', 19, 98, 8, 'もろもろの川よ手を打ち鳴らせ。山々もこぞって喜び歌え。'),
('JPN', '诗篇', 19, 98, 9, '主の御前で。主は地をさばくために来られる。主は義をもって世界をさばき公正をもって諸国の民をさばかれる。'),
('JPN', '诗篇', 19, 99, 1, '主は王である。国々の民は恐れおののけ。ケルビムの上に座しておられる方に。地よ震えよ。'),
('JPN', '诗篇', 19, 99, 2, '主はシオンにおられる大いなる方。主はすべての国々の民の上に高くいます。'),
('JPN', '诗篇', 19, 99, 3, '大いなる恐れ多い御名をほめたたえよ。主は聖なる方。'),
('JPN', '诗篇', 19, 99, 4, '王は力をもってさばきを愛する。あなたは公正を堅く立てさばきと正義をヤコブの中で行われた。'),
('JPN', '诗篇', 19, 99, 5, 'われらの神主をあがめよ。その足台のもとにひれ伏せ。主は聖なる方。'),
('JPN', '诗篇', 19, 99, 6, 'モーセとアロンは主の祭司たちの中にサムエルは御名を呼ぶ者たちの中にいた。彼らは主を呼び主は彼らに答えられた。'),
('JPN', '诗篇', 19, 99, 7, '主は雲の柱から彼らに語られた。彼らは主のさとしと主が賜ったおきてを守った。'),
('JPN', '诗篇', 19, 99, 8, 'われらの神主よあなたは彼らに答えられた。あなたは彼らには赦しの神彼らの悪しきわざには報復される方。'),
('JPN', '诗篇', 19, 99, 9, 'われらの神主をあがめよ。その聖なる山に向かってひれ伏せ。まことにわれらの神主は聖なる方。'),
('JPN', '诗篇', 19, 100, 1, '全地よ主に向かって喜びの声をあげよ。'),
('JPN', '诗篇', 19, 100, 2, '喜びをもって主に仕えよ。喜び歌いつつ御前に来たれ。'),
('JPN', '诗篇', 19, 100, 3, '知れ。主こそ神。主が私たちを造られた。私たちは主のもの主の民その牧場の羊。'),
('JPN', '诗篇', 19, 100, 4, '感謝しつつ主の門に賛美しつつその大庭に入れ。主に感謝し御名をほめたたえよ。'),
('JPN', '诗篇', 19, 100, 5, '主はいつくしみ深くその恵みはとこしえまでその真実は代々に至る。'),
('JPN', '诗篇', 19, 101, 1, '恵みとさばきを私は歌います。主よあなたにほめ歌を歌います。'),
('JPN', '诗篇', 19, 101, 2, '私は全き道に心を留めます。いつあなたは私のところに来てくださいますか。私は家の中を全き心で行き来します。'),
('JPN', '诗篇', 19, 101, 3, '私は目の前に卑しいことを置きません。私は曲がったわざを憎みそれが私にまといつくことはありません。'),
('JPN', '诗篇', 19, 101, 4, '曲がった心は私から遠ざかります。私は悪を知ろうともしません。'),
('JPN', '诗篇', 19, 101, 5, '陰で自分の隣人をそしる者を私は滅ぼします。高ぶる目とおごる心に耐えることはできません。'),
('JPN', '诗篇', 19, 101, 6, '私の目はこの国の忠実な人たちに注がれます。彼らが私とともに住むために。全き道を歩む者その人は私に仕えます。'),
('JPN', '诗篇', 19, 101, 7, '欺きを行う者は私の家の中に住むことはなく偽りを語る者は私の目の前に堅く立つことはありません。'),
('JPN', '诗篇', 19, 101, 8, '朝ごとに私は国の中の悪しき者をことごとく滅ぼし主の都から不法を行う者をことごとく断ち切ります。'),
('JPN', '诗篇', 19, 102, 1, '主よ私の祈りを聞いてください。私の叫びがあなたに届きますように。'),
('JPN', '诗篇', 19, 102, 2, '私の苦しみのときに御顔を私に隠さないでください。私に耳を傾けてください。私が呼ぶときにすぐに私に答えてください。'),
('JPN', '诗篇', 19, 102, 3, '私の日は煙の中に尽き果て私の骨は炉のように燃えているのです。'),
('JPN', '诗篇', 19, 102, 4, '私の心は青菜のように打たれてしおれパンを食べることさえ忘れました。'),
('JPN', '诗篇', 19, 102, 5, '私の嘆きの声で私の骨は肉に溶けてしまいました。'),
('JPN', '诗篇', 19, 102, 6, '私はまるで荒野のみみずく廃墟のふくろうのようです。'),
('JPN', '诗篇', 19, 102, 7, '私は眠ることもできず屋根の上のはぐれた鳥のようになりました。'),
('JPN', '诗篇', 19, 102, 8, '敵は絶えず私をそしり嘲る者は私を名指しにして毒づきます。'),
('JPN', '诗篇', 19, 102, 9, 'まことに私は灰をパンのように食べ飲み物に涙を混ぜ合わせました。'),
('JPN', '诗篇', 19, 102, 10, 'それはあなたが憤りと激しい怒りのゆえに私を持ち上げ私を投げ捨てられたからです。'),
('JPN', '诗篇', 19, 102, 11, '私の日は伸びていく夕影のようです。私は青菜のようにしおれています。'),
('JPN', '诗篇', 19, 102, 12, 'しかし主よあなたはとこしえに御座に着いておられます。あなたの呼び名は代々に及びます。'),
('JPN', '诗篇', 19, 102, 13, 'あなたは立ち上がりシオンをあわれんでくださいます。今やいつくしみの時です。定めの時が来ました。'),
('JPN', '诗篇', 19, 102, 14, 'まことにあなたのしもべたちはシオンの石を喜びシオンのちりをいとおしみます。'),
('JPN', '诗篇', 19, 102, 15, 'こうして国々は主の御名を地のすべての王はあなたの栄光を恐れます。'),
('JPN', '诗篇', 19, 102, 16, 'なぜなら主はシオンを建て直しその栄光のうちに現れ'),
('JPN', '诗篇', 19, 102, 17, '窮した者の祈りを顧み彼らの祈りをないがしろにされないからです。'),
('JPN', '诗篇', 19, 102, 18, 'このことが後の世代のために書き記され新しく造られる民が主を賛美しますように。'),
('JPN', '诗篇', 19, 102, 19, '主はその聖なるいと高き所から見下ろし天から地の上に目を注がれました。'),
('JPN', '诗篇', 19, 102, 20, '捕らわれ人のうめきを聞き死に定められた者たちを解き放つために。'),
('JPN', '诗篇', 19, 102, 21, '人々が主の御名をシオンで主の誉れをエルサレムで語り告げるために。'),
('JPN', '诗篇', 19, 102, 22, '諸国の民や王国が一つに集められて主に仕えるために。'),
('JPN', '诗篇', 19, 102, 23, '主は私の力を道の半ばで弱らせ私の日数を短くされました。'),
('JPN', '诗篇', 19, 102, 24, '私は申し上げます。「私の神よ私の日の半ばで私を取り去らないでください。あなたの年は代々に至ります。'),
('JPN', '诗篇', 19, 102, 25, 'あなたははるか昔に地の基を据えられました。天もあなたの御手のわざです。'),
('JPN', '诗篇', 19, 102, 26, 'これらのものは滅びます。しかしあなたはとこしえの方です。すべてのものは衣のようにすり切れます。外套のようにあなたがそれらを取り替えられるとそれらはすっかり変えられます。'),
('JPN', '诗篇', 19, 102, 27, 'しかしあなたは変わることがなくあなたの年は尽きることがありません。'),
('JPN', '诗篇', 19, 102, 28, 'あなたのしもべたちの子らは住まいを定め彼らの裔は御前に堅く立てられます。」'),
('JPN', '诗篇', 19, 103, 1, 'わがたましいよ主をほめたたえよ。私のうちにあるすべてのものよ聖なる御名をほめたたえよ。'),
('JPN', '诗篇', 19, 103, 2, 'わがたましいよ主をほめたたえよ。主が良くしてくださったことを何一つ忘れるな。'),
('JPN', '诗篇', 19, 103, 3, '主はあなたのすべての咎を赦しあなたのすべての病を癒やし'),
('JPN', '诗篇', 19, 103, 4, 'あなたのいのちを穴から贖われる。主はあなたに恵みとあわれみの冠をかぶらせ'),
('JPN', '诗篇', 19, 103, 5, 'あなたの一生を良いもので満ち足らせる。あなたの若さは鷲のように新しくなる。'),
('JPN', '诗篇', 19, 103, 6, '主は義とさばきをすべての虐げられている人々のために行われる。'),
('JPN', '诗篇', 19, 103, 7, '主はご自分の道をモーセにそのみわざをイスラエルの子らに知らされた方。'),
('JPN', '诗篇', 19, 103, 8, '主はあわれみ深く情け深い。怒るのに遅く恵み豊かである。'),
('JPN', '诗篇', 19, 103, 9, '主はいつまでも争ってはおられない。とこしえに怒ってはおられない。'),
('JPN', '诗篇', 19, 103, 10, '私たちの罪にしたがって私たちを扱うことをせず私たちの咎にしたがって私たちに報いをされることもない。'),
('JPN', '诗篇', 19, 103, 11, '天が地上はるかに高いように御恵みは主を恐れる者の上に大きい。'),
('JPN', '诗篇', 19, 103, 12, '東が西から遠く離れているように主は私たちの背きの罪を私たちから遠く離される。'),
('JPN', '诗篇', 19, 103, 13, '父がその子をあわれむように主はご自分を恐れる者をあわれまれる。'),
('JPN', '诗篇', 19, 103, 14, '主は私たちの成り立ちを知り私たちが土のちりにすぎないことを心に留めてくださる。'),
('JPN', '诗篇', 19, 103, 15, '人その一生は草のよう。人は咲く。野の花のように。'),
('JPN', '诗篇', 19, 103, 16, '風がそこを過ぎるとそれはもはやない。その場所さえもそれを知らない。'),
('JPN', '诗篇', 19, 103, 17, 'しかし主の恵みはとこしえからとこしえまで主を恐れる者の上にあり主の義はその子らの子たちに及ぶ。'),
('JPN', '诗篇', 19, 103, 18, '主の契約を守る者主の戒めに心を留めて行う者に。'),
('JPN', '诗篇', 19, 103, 19, '主は天にご自分の王座を堅く立てその王国はすべてを統べ治める。'),
('JPN', '诗篇', 19, 103, 20, '主をほめたたえよ主の御使いたちよ。みことばの声に聞き従いみことばを行う力ある勇士たちよ。'),
('JPN', '诗篇', 19, 103, 21, '主をほめたたえよ主のすべての軍勢よ。主のみこころを行い主に仕える者たちよ。'),
('JPN', '诗篇', 19, 103, 22, '主をほめたたえよすべて造られたものたちよ。主が治められるすべてのところで。わがたましいよ主をほめたたえよ。'),
('JPN', '诗篇', 19, 104, 1, 'わがたましいよ主をほめたたえよ。わが神主よあなたはまことに大いなる方。あなたは威厳と威光を身にまとっておられます。'),
('JPN', '诗篇', 19, 104, 2, 'あなたは光を衣のようにまとい天を幕のように張られます。'),
('JPN', '诗篇', 19, 104, 3, '水の中にご自分の高殿の梁を置き密雲をご自分の車とし風の翼に乗って進み行かれます。'),
('JPN', '诗篇', 19, 104, 4, '風をご自分の使いとし燃える火をご自分の召使いとされます。'),
('JPN', '诗篇', 19, 104, 5, 'あなたは地をその基の上に据えられました。地はとこしえまでも揺るぎません。'),
('JPN', '诗篇', 19, 104, 6, 'あなたは大水で衣のように地をおおわれました。水は山々の上にとどまりました。'),
('JPN', '诗篇', 19, 104, 7, '水はあなたに叱られて逃げあなたの雷の声で急ぎ去りました。'),
('JPN', '诗篇', 19, 104, 8, '山を上り谷を下りました。あなたがそれらの基とされた場所へと。'),
('JPN', '诗篇', 19, 104, 9, 'あなたは境を定められました。水がそれを越えないように再び地をおおわないように。'),
('JPN', '诗篇', 19, 104, 10, '主は泉の水を谷に送り山々の間を流れさせ'),
('JPN', '诗篇', 19, 104, 11, '野のすべての獣に飲まされます。野ろばも渇きを癒やします。'),
('JPN', '诗篇', 19, 104, 12, 'その傍らには空の鳥が住み枝の間でさえずります。'),
('JPN', '诗篇', 19, 104, 13, '主はその高殿から山々に水を注がれます。みわざの結ぶ実によって地は満ち足りています。'),
('JPN', '诗篇', 19, 104, 14, '主は家畜のために草をまた人が労して得る作物を生えさせます。地から食物を生じさせてくださいます。'),
('JPN', '诗篇', 19, 104, 15, 'ぶどう酒は人の心を喜ばせパンは人の心を支えます。油よりも顔をつややかにするために。'),
('JPN', '诗篇', 19, 104, 16, '主の木々は満ち足りています。主が植えられたレバノンの杉の木も。'),
('JPN', '诗篇', 19, 104, 17, 'そこに鳥は巣をかけこうのとりはもみの木を宿とします。'),
('JPN', '诗篇', 19, 104, 18, '高い山は野やぎのため岩は岩だぬきの隠れ場。'),
('JPN', '诗篇', 19, 104, 19, '主は季節のために月を造られました。太陽はその沈むところを知っています。'),
('JPN', '诗篇', 19, 104, 20, 'あなたが闇をもたらされると夜になりあらゆる森の獣が這い回ります。'),
('JPN', '诗篇', 19, 104, 21, '若い獅子は餌食を求めて吼えたけり神に自分の食物を求めます。'),
('JPN', '诗篇', 19, 104, 22, '日が昇ると彼らは退いて自分のねぐらで横になります。'),
('JPN', '诗篇', 19, 104, 23, '人は自分の仕事に出て行き夕暮れまでその働きにつきます。'),
('JPN', '诗篇', 19, 104, 24, '主よあなたのみわざはなんと多いことでしょう。あなたは知恵をもってそれらをみな造られました。地はあなたのもので満ちています。'),
('JPN', '诗篇', 19, 104, 25, 'そこには大きく広い海があり這うものや生き物は数えきれません。小さなものも大きなものも。'),
('JPN', '诗篇', 19, 104, 26, 'そこを船が行き交いあなたが造られたレビヤタンもそこで戯れます。'),
('JPN', '诗篇', 19, 104, 27, '彼らはみなあなたを待ち望んでいます。あなたが時にかなって食物をお与えになるのを。'),
('JPN', '诗篇', 19, 104, 28, 'あなたがお与えになると彼らは集めあなたが御手を開かれると彼らは良いもので満ち足ります。'),
('JPN', '诗篇', 19, 104, 29, 'あなたが御顔を隠されると彼らはおじ惑い彼らの息を取り去られると彼らは息絶えて自分のちりに帰ります。')
on conflict (version, book, chapter, verse) do nothing;
